CREATE OR REPLACE PACKAGE pkg_currency_reporting IS
  FUNCTION sf_latest_avg_rate(
    p_from_currency_code IN ADVENTUREWORKS.CURRENCYRATE.fromcurrencycode%TYPE,
    p_to_currency_code   IN ADVENTUREWORKS.CURRENCYRATE.tocurrencycode%TYPE
  ) RETURN ADVENTUREWORKS.CURRENCYRATE.averagerate%TYPE;

  FUNCTION sf_top_currency_pairs(
    p_as_of_date IN ADVENTUREWORKS.CURRENCYRATE.currencyratedate%TYPE
  ) RETURN VARCHAR2;
END pkg_currency_reporting;
/

CREATE OR REPLACE PACKAGE BODY pkg_currency_reporting IS

  FUNCTION sf_latest_avg_rate(
    p_from_currency_code IN ADVENTUREWORKS.CURRENCYRATE.fromcurrencycode%TYPE,
    p_to_currency_code   IN ADVENTUREWORKS.CURRENCYRATE.tocurrencycode%TYPE
  ) RETURN ADVENTUREWORKS.CURRENCYRATE.averagerate%TYPE IS
    lv_rate ADVENTUREWORKS.CURRENCYRATE.averagerate%TYPE;
  BEGIN
    SELECT cr.averagerate
      INTO lv_rate
      FROM ADVENTUREWORKS.CURRENCYRATE cr
     WHERE cr.fromcurrencycode = p_from_currency_code
       AND cr.tocurrencycode   = p_to_currency_code
       AND cr.currencyratedate = (
             SELECT MAX(cr2.currencyratedate)
               FROM ADVENTUREWORKS.CURRENCYRATE cr2
              WHERE cr2.fromcurrencycode = p_from_currency_code
                AND cr2.tocurrencycode   = p_to_currency_code
           );

    RETURN lv_rate;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found');
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
      RETURN NULL;
  END sf_latest_avg_rate;


  FUNCTION sf_top_currency_pairs(
    p_as_of_date IN ADVENTUREWORKS.CURRENCYRATE.currencyratedate%TYPE
  ) RETURN VARCHAR2 IS
    co_report_limit CONSTANT PLS_INTEGER := 15;
    lv_result VARCHAR2(4000);
  BEGIN
    SELECT LISTAGG(pair_txt, ';') WITHIN GROUP (ORDER BY averagerate DESC)
      INTO lv_result
      FROM (
            SELECT pair_txt, averagerate
              FROM (
                    SELECT cr.fromcurrencycode || '->' || cr.tocurrencycode || '=' ||
                           TO_CHAR(cr.averagerate, 'FM9999990D999999', 'NLS_NUMERIC_CHARACTERS=.,') AS pair_txt,
                           cr.averagerate
                      FROM (
                            SELECT cr.fromcurrencycode,
                                   cr.tocurrencycode,
                                   cr.averagerate,
                                   cr.currencyratedate,
                                   ROW_NUMBER() OVER (
                                     PARTITION BY cr.fromcurrencycode, cr.tocurrencycode
                                     ORDER BY cr.currencyratedate DESC
                                   ) AS rn
                              FROM ADVENTUREWORKS.CURRENCYRATE cr
                             WHERE cr.currencyratedate <= p_as_of_date
                           ) cr
                     WHERE cr.rn = 1
                     ORDER BY cr.averagerate DESC
                   )
             WHERE ROWNUM <= co_report_limit
           );

    RETURN lv_result;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found');
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned');
      RETURN NULL;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
      RETURN NULL;
  END sf_top_currency_pairs;

END pkg_currency_reporting;
/

