CREATE OR REPLACE FUNCTION sf_get_city_population (
    p_city_name IN VARCHAR2
)
RETURN VARCHAR2
IS
    v_population city_legislation.cities.population%TYPE;
BEGIN
    IF p_city_name IS NULL THEN
        RETURN 'City name cannot be NULL';
    END IF;

    SELECT population
      INTO v_population
      FROM city_legislation.cities
     WHERE LOWER(city_name) = LOWER(p_city_name);

    IF v_population IS NULL THEN
        RETURN 'Unexpected error occurred';
    END IF;

    RETURN TO_CHAR(v_population);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'City not found';
    WHEN TOO_MANY_ROWS THEN
        RETURN 'Duplicate city records found';
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_city_population;
/

CREATE OR REPLACE PACKAGE pkg_support_report IS
  PROCEDURE sp_print_customer_invoice_summary(
    p_country IN chinook.customers.country%TYPE,
    p_limit   IN NUMBER DEFAULT 15
  );
END pkg_support_report;
/
CREATE OR REPLACE PACKAGE BODY pkg_support_report IS
  PROCEDURE sp_print_customer_invoice_summary(
    p_country IN chinook.customers.country%TYPE,
    p_limit   IN NUMBER DEFAULT 15
  ) IS
    co_default_limit CONSTANT NUMBER := 15; -- Output readability default
    lv_limit         NUMBER;
    lv_dummy         NUMBER;
    lv_printed       NUMBER := 0;
  BEGIN
    lv_limit := NVL(p_limit, co_default_limit);

    DBMS_OUTPUT.PUT_LINE('Customer Invoice Summary');

    -- Single-row existence check to intentionally exercise NO_DATA_FOUND/TOO_MANY_ROWS handlers.
    SELECT 1
      INTO lv_dummy
      FROM chinook.customers c
     WHERE c.country = p_country
       AND ROWNUM = 1;

    FOR rec_ IN (
      SELECT c.customerid,
             c.lastname,
             c.firstname,
             COUNT(i.invoiceid) AS invoice_count,
             NVL(SUM(i.total), 0) AS total_sum
        FROM chinook.customers c
        LEFT JOIN chinook.invoices i
          ON i.customerid = c.customerid
       WHERE c.country = p_country
       GROUP BY c.customerid, c.lastname, c.firstname
       ORDER BY NVL(SUM(i.total), 0) DESC, c.customerid ASC
    ) LOOP
      EXIT WHEN lv_printed >= lv_limit;
      lv_printed := lv_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        rec_.lastname || ', ' || rec_.firstname ||
        ' - Invoices: ' || rec_.invoice_count ||
        ', Total: ' || rec_.total_sum
      );
    END LOOP;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
  END sp_print_customer_invoice_summary;
END pkg_support_report;
/

