CREATE OR REPLACE FUNCTION sf_get_tree_income (
    p_tree_id IN NUMBER
) RETURN NUMBER
IS
    lv_median_income NUMBER;
BEGIN
    IF p_tree_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE(
            'No data found for TREE_ID = ' || p_tree_id
        );
        RETURN -1;
    END IF;

    IF p_tree_id <= 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'Invalid TREE_ID: ' || p_tree_id);
    END IF;

    SELECT i.estimate_median_income
    INTO lv_median_income
    FROM MODERN_DATA.TREES t
    JOIN MODERN_DATA.INCOME_TREES i
      ON t.zipcode = i.zipcode
    WHERE t.tree_id = p_tree_id;

    RETURN lv_median_income;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE(
            'No data found for TREE_ID = ' || p_tree_id
        );
        RETURN -1;

    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE(
            'Multiple income records found for TREE_ID = ' || p_tree_id
        );
        RETURN -3;

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
        RETURN -2;
END;
/

