CREATE OR REPLACE PROCEDURE sp_compare_driver_points (
    p_driver_id IN NUMBER,
    p_race_id   IN NUMBER
) IS
    v_points_main NUMBER;
    v_points_ext  NUMBER;
    v_difference  NUMBER;
BEGIN
    -- Input validation
    IF p_driver_id IS NULL OR p_race_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Driver ID and Race ID must not be NULL.');
        RETURN;
    END IF;

    IF p_driver_id <= 0 OR p_race_id <= 0 THEN
        DBMS_OUTPUT.PUT_LINE('Driver ID and Race ID must be positive numbers.');
        RETURN;
    END IF;

    -- Fetch first result
    SELECT points
    INTO v_points_main
    FROM F1.DRIVER_STANDINGS
    WHERE driver_id = p_driver_id
      AND race_id   = p_race_id;

    -- Fetch second result
    SELECT points
    INTO v_points_ext
    FROM F1.DRIVER_STANDINGS_EXT
    WHERE driver_id = p_driver_id
      AND race_id   = p_race_id;

    -- Compare results
    v_difference := v_points_main - v_points_ext;

    DBMS_OUTPUT.PUT_LINE(
        'Points difference for driver ' || p_driver_id ||
        ' in race ' || p_race_id || ' is: ' || v_difference
    );

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE(
            'No matching data found for the given driver and race.'
        );

    WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE(
            'Invalid numeric input provided for driver or race.'
        );

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE(
            'Unable to compare points for driver ' || p_driver_id ||
            ' and race ' || p_race_id || '.'
        );
END;
/

