CREATE OR REPLACE PROCEDURE sp_get_playlist_track_count (
    p_playlist_id IN NUMBER
)
IS
    v_playlist_name music.playlist.name%TYPE;
    v_track_count   NUMBER;
BEGIN
    IF p_playlist_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Playlist ID cannot be NULL');
        RETURN;
    END IF;

    SELECT p.name,
           COUNT(pt.trackid)
    INTO   v_playlist_name,
           v_track_count
    FROM   music.playlist p
    LEFT JOIN music.playlisttrack pt
           ON p.playlistid = pt.playlistid
    WHERE  p.playlistid = p_playlist_id
    GROUP BY p.name;

    DBMS_OUTPUT.PUT_LINE('Playlist "' || v_playlist_name || '" contains ' || v_track_count || ' tracks');

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Playlist does not exist');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_get_playlist_track_count;
/

CREATE OR REPLACE PROCEDURE sp_get_track_details
(
    p_track_id IN NUMBER
)
IS
    lv_track_name   VARCHAR2(200);
    lv_album_title  VARCHAR2(200);
    lv_artist_name  VARCHAR2(200);
    lv_genre_name   VARCHAR2(100);
    lv_media_type   VARCHAR2(100);
    lv_unit_price   NUMBER(10,2);
BEGIN
    SELECT t.name,
           a.title,
           ar.name,
           g.name,
           m.name,
           t.unitprice
    INTO   lv_track_name,
           lv_album_title,
           lv_artist_name,
           lv_genre_name,
           lv_media_type,
           lv_unit_price
    FROM   CHINOOK.TRACKS t
           LEFT JOIN CHINOOK.ALBUMS a
               ON t.albumid = a.albumid
           LEFT JOIN CHINOOK.ARTISTS ar
               ON a.artistid = ar.artistid
           LEFT JOIN CHINOOK.GENRES g
               ON t.genreid = g.genreid
           LEFT JOIN CHINOOK.MEDIA_TYPES m
               ON t.mediatypeid = m.mediatypeid
    WHERE  t.trackid = p_track_id;

    DBMS_OUTPUT.PUT_LINE('Track Details Report:');
    DBMS_OUTPUT.PUT_LINE('---------------------');
    DBMS_OUTPUT.PUT_LINE('Track Name: ' || lv_track_name);
    DBMS_OUTPUT.PUT_LINE('Album Title: ' || lv_album_title);
    DBMS_OUTPUT.PUT_LINE('Artist Name: ' || lv_artist_name);
    DBMS_OUTPUT.PUT_LINE('Genre: ' || lv_genre_name);
    DBMS_OUTPUT.PUT_LINE('Media Type: ' || lv_media_type);
    DBMS_OUTPUT.PUT_LINE('Price: $' || TO_CHAR(lv_unit_price, 'FM9990.00'));
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Sorry, no track found with the given ID.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_get_track_details;
/

