CREATE OR REPLACE PROCEDURE sp_get_daily_hit_count (
    p_app_id IN NUMBER,
    p_day    IN DATE
)
IS
    lv_total_records NUMBER;
    e_bad_day_format EXCEPTION;
    PRAGMA EXCEPTION_INIT(e_bad_day_format, -1861);
BEGIN
    IF p_app_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Application ID must not be NULL');
        RETURN;
    END IF;

    IF p_day IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Day must not be NULL');
        RETURN;
    END IF;

    SELECT COUNT(*)
    INTO   lv_total_records
    FROM   ORACLE_SQL.WEB_COUNTER_HIST
    WHERE  app_id = p_app_id
    AND    TRUNC(TO_DATE(day, 'YYYY-MM-DD HH24:MI:SS')) = TRUNC(p_day);

    DBMS_OUTPUT.PUT_LINE(
        'Total activity records for App ID ' || p_app_id ||
        ' on ' || TO_CHAR(p_day, 'YYYY-MM-DD') ||
        ' : ' || lv_total_records
    );

EXCEPTION
    WHEN VALUE_ERROR OR e_bad_day_format THEN
        DBMS_OUTPUT.PUT_LINE('Date conversion failed. Invalid DAY format in table.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_get_daily_hit_count;
/

