CREATE OR REPLACE PROCEDURE SP_GET_LATEST_CUSTOMER_TXN (
    p_customer_id IN BANK_SALES_TRADING.CUSTOMER_TRANSACTIONS.customer_id%TYPE
) AS
    lv_txn_type    BANK_SALES_TRADING.CUSTOMER_TRANSACTIONS.txn_type%TYPE;
    lv_txn_amount  BANK_SALES_TRADING.CUSTOMER_TRANSACTIONS.txn_amount%TYPE;
BEGIN
    SELECT txn_type, 
           txn_amount
    INTO   lv_txn_type, 
           lv_txn_amount
    FROM   BANK_SALES_TRADING.CUSTOMER_TRANSACTIONS
    WHERE  customer_id = p_customer_id
    ORDER BY txn_amount DESC
    FETCH FIRST 1 ROW ONLY;

    DBMS_OUTPUT.PUT_LINE('Customer id: ' || p_customer_id);
    DBMS_OUTPUT.PUT_LINE('Type: ' || lv_txn_type);
    DBMS_OUTPUT.PUT_LINE('Amount: ' || lv_txn_amount);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No transactions found for Customer ID: ' || p_customer_id);
    WHEN OTHERS THEN 
        DBMS_OUTPUT.PUT_LINE('An unexpected error occurred.');
END;
/

create or replace NONEDITIONABLE PROCEDURE SP_PLAYER_BATTING_REVIEW (
    p_player_id IN VARCHAR2,
    p_year      IN NUMBER
)
IS
    lv_name_first  VARCHAR2(8000 BYTE);
    lv_name_last   VARCHAR2(8000 BYTE);
    lv_birth_year  NUMBER(38,0);
    lv_birth_city  VARCHAR2(8000 BYTE);

    lv_ab          NUMBER(38,0);
    lv_h           NUMBER(38,0);
    lv_hr          NUMBER(38,0);
    lv_rbi         NUMBER(38,0);

BEGIN
    BEGIN
        SELECT
            p.name_first,
            p.name_last,
            p.birth_year,
            p.birth_city
        INTO
            lv_name_first,
            lv_name_last,
            lv_birth_year,
            lv_birth_city
        FROM BASEBALL.PLAYER p
        WHERE p.player_id = p_player_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE(
                'No batting records found for PLAYER_ID ' || p_player_id || ' in year ' || p_year
            );
            RETURN;
    END;

    BEGIN
        SELECT
            ab,
            h,
            hr,
            rbi
        INTO
            lv_ab,
            lv_h,
            lv_hr,
            lv_rbi
        FROM (
            SELECT
                b.ab,
                b.h,
                b.hr,
                b.rbi
            FROM BASEBALL.BATTING b
            WHERE b.player_id = p_player_id
              AND b.year = p_year
            ORDER BY b.stint DESC
        )
        WHERE ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE(
                'No batting records found for PLAYER_ID '
                || p_player_id || ' in year ' || p_year
            );
            RETURN;
    END;

    DBMS_OUTPUT.PUT_LINE('--------------------------------------------');
    DBMS_OUTPUT.PUT_LINE('Player Batting Performance Summary');
    DBMS_OUTPUT.PUT_LINE('--------------------------------------------');
    DBMS_OUTPUT.PUT_LINE('Player ID   : ' || p_player_id);
    DBMS_OUTPUT.PUT_LINE('Name        : ' || lv_name_first || ' ' || lv_name_last);
    DBMS_OUTPUT.PUT_LINE('Birth Year  : ' || lv_birth_year);
    DBMS_OUTPUT.PUT_LINE('Birth City  : ' || lv_birth_city);
    DBMS_OUTPUT.PUT_LINE('Season Year : ' || p_year);
    DBMS_OUTPUT.PUT_LINE('--------------------------------------------');
    DBMS_OUTPUT.PUT_LINE('At Bats (AB): ' || lv_ab);
    DBMS_OUTPUT.PUT_LINE('Hits (H)    : ' || lv_h);
    DBMS_OUTPUT.PUT_LINE('Home Runs   : ' || lv_hr);
    DBMS_OUTPUT.PUT_LINE('RBIs        : ' || lv_rbi);
    DBMS_OUTPUT.PUT_LINE('--------------------------------------------');

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE(
            'Unexpected error occurred'
        );
END SP_PLAYER_BATTING_REVIEW;
/

CREATE OR REPLACE FUNCTION sf_get_match_extra_runs
(
    p_match_id IN ipl.extra_runs.match_id%TYPE
)
RETURN VARCHAR2
IS
    v_result VARCHAR2(4000);
BEGIN
    IF p_match_id IS NULL THEN
        RETURN 'Match ID cannot be null';
    END IF;

    SELECT
        'Match ID:' || p_match_id ||
        ' Wides:' || NVL(SUM(CASE WHEN extra_type = 'wides' THEN 1 ELSE 0 END), 0) ||
        ' No Balls:' || NVL(SUM(CASE WHEN extra_type = 'noballs' THEN 1 ELSE 0 END), 0) ||
        ' Leg Byes:' || NVL(SUM(CASE WHEN extra_type = 'legbyes' THEN 1 ELSE 0 END), 0) ||
        ' Byes:' || NVL(SUM(CASE WHEN extra_type = 'byes' THEN 1 ELSE 0 END), 0)
    INTO v_result
    FROM ipl.extra_runs
    WHERE match_id = p_match_id;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_match_extra_runs;
/

CREATE OR REPLACE FUNCTION SF_GET_DRIVE_COUNT_BY_YEAR (
    p_year IN F1.DRIVES.year%TYPE
)
RETURN VARCHAR2 
IS
    v_count NUMBER;
    e_null_input EXCEPTION;
BEGIN
    -- 1. Use RAISE for internal validation
    IF p_year IS NULL THEN
        RAISE e_null_input;
    END IF;

    -- 2. Retrieve data
    SELECT COUNT(*) INTO v_count
    FROM F1.DRIVES
    WHERE year = p_year;

    -- 3. Return the count as text
    RETURN TO_CHAR(v_count);

EXCEPTION
    -- 4. Return explicit error messages as the result
    WHEN e_null_input THEN
        RETURN 'ERROR: Year cannot be NULL';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END;
/

CREATE OR REPLACE FUNCTION sf_get_plyr_dtls (
    p_match_id IN wwe.matches.id%TYPE
) RETURN VARCHAR2 IS
    l_wnr_name wwe.wrestlers.name%TYPE;
    l_lsr_name wwe.wrestlers.name%TYPE;
    l_msg      VARCHAR2(900);
BEGIN
    /* Null validation */
    IF p_match_id IS NULL THEN
        RETURN 'Match ID cannot be NULL';
    END IF;

    /* Fetch winner and loser names */
    SELECT
        w.name,
        w1.name
    INTO
        l_wnr_name,
        l_lsr_name
    FROM
        wwe.matches   m
        JOIN wwe.wrestlers w  ON m.winner_id = w.id
        JOIN wwe.wrestlers w1 ON m.loser_id  = w1.id
    WHERE
        m.id = p_match_id;

    /* Build return message */
    l_msg :=
        'Winner: ' || l_wnr_name ||
        ' and Loser: ' || l_lsr_name;

    RETURN l_msg;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'No match found for match ID ' || p_match_id;

    WHEN OTHERS THEN
        RETURN ' Unexpected error occurred during runtime!';
END sf_get_plyr_dtls;
/

CREATE OR REPLACE PACKAGE pkg_btc_member_audit IS
  FUNCTION sf_member_exists(
    p_member_id IN BANK_SALES_TRADING.bitcoin_members.member_id%TYPE
  ) RETURN NUMBER;

  PROCEDURE sp_print_member_activity(
    p_member_id IN BANK_SALES_TRADING.bitcoin_members.member_id%TYPE,
    p_ticker    IN BANK_SALES_TRADING.bitcoin_transactions.ticker%TYPE,
    p_min_date  IN BANK_SALES_TRADING.bitcoin_transactions.txn_date%TYPE,
    p_max_date  IN BANK_SALES_TRADING.bitcoin_transactions.txn_date%TYPE
  );
END pkg_btc_member_audit;
/

CREATE OR REPLACE PACKAGE BODY pkg_btc_member_audit IS

  FUNCTION sf_member_exists(
    p_member_id IN BANK_SALES_TRADING.bitcoin_members.member_id%TYPE
  ) RETURN NUMBER IS
    lv_dummy BANK_SALES_TRADING.bitcoin_members.member_id%TYPE;
  BEGIN
    SELECT m.member_id
      INTO lv_dummy
      FROM BANK_SALES_TRADING.bitcoin_members m
     WHERE m.member_id = p_member_id;

    RETURN 1;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 0;
    WHEN TOO_MANY_ROWS THEN
      RETURN 1;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
      RETURN 0;
  END sf_member_exists;


  PROCEDURE sp_print_member_activity(
    p_member_id IN BANK_SALES_TRADING.bitcoin_members.member_id%TYPE,
    p_ticker    IN BANK_SALES_TRADING.bitcoin_transactions.ticker%TYPE,
    p_min_date  IN BANK_SALES_TRADING.bitcoin_transactions.txn_date%TYPE,
    p_max_date  IN BANK_SALES_TRADING.bitcoin_transactions.txn_date%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15;

    CURSOR cur_txn IS
      SELECT t.txn_id,
             t.txn_date,
             t.ticker,
             t.txn_type,
             t.quantity
        FROM BANK_SALES_TRADING.bitcoin_transactions t
       WHERE t.member_id = p_member_id
         AND t.ticker = p_ticker
         AND TO_DATE(t.txn_date, 'DD-MM-YYYY') BETWEEN TO_DATE(p_min_date, 'DD-MM-YYYY') AND TO_DATE(p_max_date, 'DD-MM-YYYY')
       ORDER BY TO_DATE(t.txn_date, 'DD-MM-YYYY'), t.txn_id;

    rec_txn cur_txn%ROWTYPE;

    lv_price         BANK_SALES_TRADING.bitcoin_prices.price%TYPE;
    lv_notional      NUMBER;
    lv_rows_printed  PLS_INTEGER := 0;
  BEGIN
    IF sf_member_exists(p_member_id) = 0 THEN
      DBMS_OUTPUT.PUT_LINE('Audit Error: Member ID [' || p_member_id || '] not found.');
      RETURN;
    END IF;

    OPEN cur_txn;

    FETCH cur_txn INTO rec_txn;
    IF cur_txn%NOTFOUND THEN
      CLOSE cur_txn;
      DBMS_OUTPUT.PUT_LINE('No transactions found for Member ID [' || p_member_id || '].');
      RETURN;
    END IF;

    WHILE cur_txn%FOUND LOOP
      lv_rows_printed := lv_rows_printed + 1;
      EXIT WHEN lv_rows_printed > co_report_limit;

      BEGIN
        SELECT p.price
          INTO lv_price
          FROM BANK_SALES_TRADING.bitcoin_prices p
         WHERE p.ticker = rec_txn.ticker
           AND TO_DATE(p.market_date, 'DD-MM-YYYY') = TO_DATE(rec_txn.txn_date, 'DD-MM-YYYY');

      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_price := 0;
          DBMS_OUTPUT.PUT_LINE('Price missing for ' || rec_txn.ticker || ' on ' || rec_txn.txn_date || '.');
        WHEN TOO_MANY_ROWS THEN
          lv_price := 0;
          DBMS_OUTPUT.PUT_LINE('Multiple rows returned');
        WHEN OTHERS THEN
          lv_price := 0;
          DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
      END;

      lv_notional := rec_txn.quantity * lv_price;

      DBMS_OUTPUT.PUT_LINE(
        'TXN_ID=[' || rec_txn.txn_id || '], ' ||
        'DATE=[' || rec_txn.txn_date || '], ' ||
        'TICKER=[' || rec_txn.ticker || '], ' ||
        'TYPE=[' || rec_txn.txn_type || '], ' ||
        'QTY=[' || rec_txn.quantity || '], ' ||
        'PRICE=[' || lv_price || '], ' ||
        'NOTIONAL=[' || lv_notional || ']'
      );

      FETCH cur_txn INTO rec_txn;
    END LOOP;

    IF cur_txn%ISOPEN THEN
      CLOSE cur_txn;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF cur_txn%ISOPEN THEN
        CLOSE cur_txn;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found');
    WHEN TOO_MANY_ROWS THEN
      IF cur_txn%ISOPEN THEN
        CLOSE cur_txn;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned');
    WHEN OTHERS THEN
      IF cur_txn%ISOPEN THEN
        CLOSE cur_txn;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
  END sp_print_member_activity;

END pkg_btc_member_audit;
/

