CREATE OR REPLACE PROCEDURE sp_customer_purchase_report
(
    p_customer_id IN NUMBER
)
IS
    exp_no_customer_exists EXCEPTION;
    lv_total_amount NUMBER := 0;
    lv_customer_name VARCHAR2(80);
    lv_had_sales BOOLEAN := FALSE;
BEGIN
    BEGIN
        SELECT cust_first_name || ' ' || cust_last_name
        INTO   lv_customer_name
        FROM   COMPLEX_ORACLE.CUSTOMERS
        WHERE  cust_id = p_customer_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE exp_no_customer_exists;
    END;

    DBMS_OUTPUT.PUT_LINE('Customer Purchase Report:');
    DBMS_OUTPUT.PUT_LINE('-------------------------');
    DBMS_OUTPUT.PUT_LINE('Customer Name: ' || lv_customer_name);
    DBMS_OUTPUT.PUT_LINE('-------------------------');

    FOR rec_sale IN
    (
        SELECT  p.prod_name,
                s.amount_sold,
                t.calendar_year
        FROM    COMPLEX_ORACLE.SALES s
        JOIN    COMPLEX_ORACLE.PRODUCTS p
        ON      s.prod_id = p.prod_id
        JOIN    COMPLEX_ORACLE.TIMES t
        ON      s.time_id = t.time_id
        WHERE   s.cust_id = p_customer_id
    )
    LOOP
        lv_had_sales := TRUE;
        lv_total_amount := lv_total_amount + rec_sale.amount_sold;

        DBMS_OUTPUT.PUT_LINE('Product       : ' || rec_sale.prod_name);
        DBMS_OUTPUT.PUT_LINE('Amount Sold   : ' || rec_sale.amount_sold);
        DBMS_OUTPUT.PUT_LINE('Year          : ' || rec_sale.calendar_year);
        DBMS_OUTPUT.PUT_LINE('-------------------------');
    END LOOP;

    IF NOT lv_had_sales THEN
        DBMS_OUTPUT.PUT_LINE('No purchases found for this customer.');
    END IF;

    DBMS_OUTPUT.PUT_LINE('-------------------------');
    DBMS_OUTPUT.PUT_LINE('TOTAL AMOUNT = ' || lv_total_amount);

    IF lv_total_amount > 50000 THEN
        DBMS_OUTPUT.PUT_LINE('CUSTOMER LOYALTY GROUP: PLATINUM');
    ELSE
        DBMS_OUTPUT.PUT_LINE('CUSTOMER LOYALTY GROUP: SILVER');
    END IF;

EXCEPTION
    WHEN exp_no_customer_exists THEN
        DBMS_OUTPUT.PUT_LINE('Audit Error: Customer ID ' || p_customer_id || ' not found.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_customer_purchase_report;
/

CREATE OR REPLACE FUNCTION sf_get_total_artist_playtime(
    p_artist_name IN VARCHAR2
) RETURN VARCHAR2 IS  

    lv_artist_id          MUSIC.ARTIST.ARTISTID%TYPE;
    lv_total_milliseconds NUMBER := 0;
    lv_total_minutes      NUMBER;
    has_track_found       BOOLEAN := FALSE;

    CURSOR cur_artist_tracks(p_artist_id NUMBER) IS
        SELECT t.MILLISECONDS
        FROM MUSIC.TRACK t 
        JOIN MUSIC.ALBUM al ON t.ALBUMID = al.ALBUMID
        WHERE al.ARTISTID = p_artist_id;

BEGIN
    IF p_artist_name IS NULL THEN
        RETURN 'Error: Artist name cannot be NULL.';
    END IF;

    SELECT ARTISTID INTO lv_artist_id
    FROM MUSIC.ARTIST
    WHERE UPPER(NAME) = UPPER(p_artist_name)
    FETCH FIRST 1 ROWS ONLY; 

    FOR i IN cur_artist_tracks(lv_artist_id) LOOP
        lv_total_milliseconds := lv_total_milliseconds + i.MILLISECONDS;
        has_track_found := TRUE;
    END LOOP;

    IF NOT has_track_found THEN
        RETURN 'No tracks found for artist: ' || p_artist_name;
    END IF;

    lv_total_minutes := ROUND(lv_total_milliseconds / 60000, 2);

    RETURN TO_CHAR(lv_total_minutes, 'FM999999990D00', 'NLS_NUMERIC_CHARACTERS=.,') || ' Minutes';

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Error: Artist not found in database.';
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END;
/

CREATE OR REPLACE PROCEDURE sp_get_flight_revenue_summary (
    p_flight_id        IN  NUMBER,
    out_total_revenue  OUT NUMBER,
    out_ticket_count   OUT NUMBER
)
IS
    lv_flight_exists  NUMBER;
BEGIN
    out_total_revenue := 0;
    out_ticket_count  := 0;

    IF p_flight_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Flight ID cannot be NULL');
        out_total_revenue := NULL;
        out_ticket_count  := NULL;
        RETURN;
    END IF;

    IF p_flight_id < 0 THEN
        DBMS_OUTPUT.PUT_LINE('Flight ID does not exist');
        out_total_revenue := NULL;
        out_ticket_count  := NULL;
        RETURN;
    END IF;

    BEGIN
        SELECT 1
        INTO   lv_flight_exists
        FROM   AIRLINES.FLIGHTS
        WHERE  flight_id = p_flight_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('Flight ID does not exist');
            out_total_revenue := NULL;
            out_ticket_count  := NULL;
            RETURN;
    END;

    FOR r IN (
        SELECT amount
        FROM   AIRLINES.TICKET_FLIGHTS
        WHERE  flight_id = p_flight_id
    ) LOOP
        out_total_revenue := out_total_revenue + NVL(r.amount, 0);
        out_ticket_count  := out_ticket_count + 1;
    END LOOP;

    IF out_ticket_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No tickets found for the given flight');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
        out_total_revenue := NULL;
        out_ticket_count  := NULL;
END;
/

