CREATE OR REPLACE PROCEDURE sp_get_employee_details (
    p_emp_id IN NUMBER,
    p_status OUT VARCHAR2
) IS
    lv_id              oracle_sql.employees.id%TYPE;
    lv_name            oracle_sql.employees.name%TYPE;
    lv_title           oracle_sql.employees.title%TYPE;
    lv_supervisor_id   oracle_sql.employees.supervisor_id%TYPE;
    lv_supervisor_name oracle_sql.employees.name%TYPE;

    CURSOR c_history IS
        SELECT start_, end_, title
        FROM oracle_sql.emp_hire_periods
        WHERE emp_id = p_emp_id
        ORDER BY start_;
BEGIN
    SELECT e.id,
           e.name,
           e.title,
           e.supervisor_id,
           s.name AS supervisor_name
    INTO lv_id, lv_name, lv_title, lv_supervisor_id, lv_supervisor_name
    FROM oracle_sql.employees e
    LEFT JOIN oracle_sql.employees s
           ON e.supervisor_id = s.id
    WHERE e.id = p_emp_id;

    DBMS_OUTPUT.PUT_LINE('Employee ID   : ' || lv_id);
    DBMS_OUTPUT.PUT_LINE('Name          : ' || lv_name);
    DBMS_OUTPUT.PUT_LINE('Title         : ' || lv_title);

    IF lv_supervisor_name IS NOT NULL THEN
        DBMS_OUTPUT.PUT_LINE('Supervisor    : ' || lv_supervisor_name);
    ELSE
        DBMS_OUTPUT.PUT_LINE('Supervisor    : NONE');
    END IF;

    DBMS_OUTPUT.PUT_LINE('--------------------------');
    DBMS_OUTPUT.PUT_LINE('Employment History');

    FOR h IN c_history LOOP
        DBMS_OUTPUT.PUT_LINE(
            'From: ' || TO_CHAR(h.start_, 'YYYY-MM-DD') ||
            ' To: ' || CASE WHEN h.end_ IS NULL THEN 'Present' ELSE TO_CHAR(h.end_, 'YYYY-MM-DD') END ||
            ' | Title: ' || h.title
        );
    END LOOP;

    p_status := 'PASS';

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        p_status := 'FAIL';
        DBMS_OUTPUT.PUT_LINE('No data available.');

    WHEN OTHERS THEN
        p_status := 'FAIL';
        DBMS_OUTPUT.PUT_LINE('Unexpected error in occurred');
END;
/

