CREATE OR REPLACE PROCEDURE sp_get_member_bitcoin_transactions (
    p_member_id IN VARCHAR2
)
IS
    c_limit      CONSTANT NUMBER := 5;

    CURSOR cur_txns IS
        SELECT t.txn_id,
               t.quantity,
               t.percentage_fee,
               t.txn_date,
               m.first_name,
               m.region
        FROM   BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
        INNER JOIN BANK_SALES_TRADING.BITCOIN_MEMBERS m ON m.member_id = t.member_id
        WHERE  t.member_id = p_member_id
        ORDER BY t.txn_date DESC;

    v_txn_id     BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.txn_id%TYPE;
    v_qty        BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.quantity%TYPE;
    v_fee        BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.percentage_fee%TYPE;
    v_date       BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.txn_date%TYPE;
    v_fname      BANK_SALES_TRADING.BITCOIN_MEMBERS.first_name%TYPE;
    v_reg        BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE;

    v_counter    NUMBER := 0;
    v_exists     BOOLEAN := FALSE;

BEGIN
    IF p_member_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: MEMBER_ID cannot be NULL');
        RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('--- MEMBER BITCOIN TRANSACTIONS (RECENT) ---');

    OPEN cur_txns;
    LOOP
        FETCH cur_txns INTO v_txn_id, v_qty, v_fee, v_date, v_fname, v_reg;
        EXIT WHEN cur_txns%NOTFOUND;

        v_exists  := TRUE;
        v_counter := v_counter + 1;

        DBMS_OUTPUT.PUT_LINE(
            '[' || v_counter || '] ID: ' || v_txn_id ||
            ' | Name: ' || v_fname ||
            ' | Region: ' || v_reg ||
            ' | Qty: ' || v_qty ||
            ' | Fee: ' || v_fee || '%' ||
            ' | Date: ' || v_date
        );

        EXIT WHEN v_counter >= c_limit;
    END LOOP;

    IF v_counter >= c_limit THEN
        FETCH cur_txns INTO v_txn_id, v_qty, v_fee, v_date, v_fname, v_reg;
        IF cur_txns%FOUND THEN
            DBMS_OUTPUT.PUT_LINE('... (Additional transactions exist in history)');
        END IF;
    END IF;

    CLOSE cur_txns;

    IF NOT v_exists THEN
        DBMS_OUTPUT.PUT_LINE('No transactions found for Member: ' || p_member_id);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        IF cur_txns%ISOPEN THEN
            CLOSE cur_txns;
        END IF;
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END sp_get_member_bitcoin_transactions;
/

