CREATE OR REPLACE PROCEDURE sp_get_channel_delivery_report (
    p_delivery_status IN DELIVERY_CENTER.DELIVERIES.DELIVERY_STATUS%TYPE
)
IS
    CURSOR c_deliveries IS
        SELECT
            delivery_id,
            delivery_order_id,
            driver_id,
            delivery_distance_meters
        FROM delivery_center.deliveries
        WHERE delivery_status = p_delivery_status
        ORDER BY delivery_id DESC
        FETCH FIRST 10 ROWS ONLY;

    rec_delivery c_deliveries%ROWTYPE;
    lv_found BOOLEAN := FALSE;

BEGIN
    IF p_delivery_status IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Delivery status must not be NULL');
        RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
        '--- Delivery Report (Status: ' || p_delivery_status || ') ---'
    );

    OPEN c_deliveries;

    LOOP
        FETCH c_deliveries INTO rec_delivery;
        EXIT WHEN c_deliveries%NOTFOUND;

        lv_found := TRUE;

        DBMS_OUTPUT.PUT_LINE(
            'Delivery ID: ' || rec_delivery.delivery_id ||
            ' | Order ID: ' || rec_delivery.delivery_order_id ||
            ' | Driver ID: ' || rec_delivery.driver_id ||
            ' | Distance (m): ' || rec_delivery.delivery_distance_meters
        );
    END LOOP;

    CLOSE c_deliveries;

    IF NOT lv_found THEN
        DBMS_OUTPUT.PUT_LINE(
            'No deliveries found for the given status'
        );
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE(
            'Unexpected error occurred'
        );
END sp_get_channel_delivery_report;
/

CREATE OR REPLACE PROCEDURE sp_print_company_funding (
    p_min_funding IN NUMBER
) 
IS
    ----------------------------------------------------------------
    -- Cursor to fetch companies with funding >= minimum amount
    ----------------------------------------------------------------
    CURSOR cur_companies IS
        SELECT company_id,
               funding,
               valuation
        FROM modern_data.companies_funding
        WHERE funding >= p_min_funding
        ORDER BY company_id;

    ----------------------------------------------------------------
    -- Local variables
    ----------------------------------------------------------------
    lv_company_id   NUMBER;
    lv_funding      NUMBER;
    lv_valuation    NUMBER;
    is_found        BOOLEAN := FALSE;

    ----------------------------------------------------------------
    -- Custom exceptions (optional if needed)
    ----------------------------------------------------------------
    exp_no_input EXCEPTION;

BEGIN
    ----------------------------------------------------------------
    -- Input validation
    ----------------------------------------------------------------
    IF p_min_funding IS NULL THEN
        RAISE exp_no_input;
    END IF;

    ----------------------------------------------------------------
    -- Open cursor and loop through company records
    ----------------------------------------------------------------
    OPEN cur_companies;

    LOOP
        FETCH cur_companies INTO lv_company_id, lv_funding, lv_valuation;
        EXIT WHEN cur_companies%NOTFOUND;

        is_found := TRUE;

        DBMS_OUTPUT.PUT_LINE(
            'Company ID: ' || lv_company_id ||
            ', Funding: ' || lv_funding ||
            ', Valuation: ' || lv_valuation
        );

    END LOOP;

    CLOSE cur_companies;

    ----------------------------------------------------------------
    -- If no records found
    ----------------------------------------------------------------
    IF NOT is_found THEN
        DBMS_OUTPUT.PUT_LINE(
            'No companies found with funding greater than or equal to the given amount.'
        );
    END IF;

EXCEPTION
    WHEN exp_no_input THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Minimum funding amount cannot be NULL.');

    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No company data found.');

    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected multiple rows returned.');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE(
            'Unexpected error occurred while processing company funding data.'
        );

END sp_print_company_funding;
/

