CREATE OR REPLACE PROCEDURE sp_top_two_artists(p_year IN NUMBER) IS
    -- Cursor to fetch artist sales in descending order
    cursor cur_artist_sales is
        select ar.artistid,
               ar.name as artist_name,
               SUM(il.quantity) as total_tracks_sold
        from music.artist ar, music.album a, music.track t, music.invoice i, music.invoiceline il
        where ar.artistid = a.artistid
        and a.albumid = t.albumid
        and t.trackid = il.trackid
        and il.invoiceid = i.invoiceid
        and extract(year from i.invoicedate) = p_year
        group by ar.artistid, ar.name
        order by total_tracks_sold desc;

    -- Variables to store cursor values
    v_artist_id music.artist.artistid%TYPE;
    v_artist_name music.artist.name%TYPE;
    v_total_tracks NUMBER;

    -- Counter to track number of artists fetched
    v_count NUMBER := 0;

    -- Custom exceptions
    no_artist_found EXCEPTION;
    only_one_artist EXCEPTION;

BEGIN
    -- Validate input parameter
    IF p_year IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Input parameter p_year cannot be NULL');
        RETURN;
    END IF;

    --Open cursor and fetch top two artists
    OPEN cur_artist_sales;
    LOOP
        FETCH cur_artist_sales INTO v_artist_id, v_artist_name, v_total_tracks;
        EXIT WHEN cur_artist_sales%NOTFOUND OR v_count = 2;

        DBMS_OUTPUT.PUT_LINE('Artist: ' || v_artist_name || ' | Total Tracks Sold: ' || v_total_tracks);

        v_count := v_count + 1;
    END LOOP;
    CLOSE cur_artist_sales;

    -- Raise exceptions based on count
    IF v_count = 0 THEN
        RAISE no_artist_found;
    ELSIF v_count = 1 THEN
        RAISE only_one_artist;
    END IF;

EXCEPTION
    WHEN no_artist_found THEN
        DBMS_OUTPUT.PUT_LINE('No sales data found for year ' || p_year);
    WHEN only_one_artist THEN
        DBMS_OUTPUT.PUT_LINE('Only one artist found for year ' || p_year || '. Displayed above.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END sp_top_two_artists;
/

CREATE OR REPLACE FUNCTION sf_get_team_keeper_runs
(
    p_match_id IN NUMBER
)
RETURN VARCHAR2
IS
    v_match_exists NUMBER;

    CURSOR c_team_keeper_runs IS
        SELECT pm.team_id,
               SUM(NVL(bs.runs_scored, 0)) keeper_runs
          FROM ipl.player_match pm
          LEFT JOIN ipl.batsman_scored bs
            ON bs.match_id = pm.match_id
         WHERE pm.match_id = p_match_id
           AND pm.role = 'Keeper'
         GROUP BY pm.team_id
         ORDER BY keeper_runs DESC;

    v_result VARCHAR2(4000) := '';
BEGIN
    IF p_match_id IS NULL THEN
        RETURN 'Match ID NULL not found';
    END IF;

    SELECT COUNT(*)
      INTO v_match_exists
      FROM ipl.player_match
     WHERE match_id = p_match_id;

    IF v_match_exists = 0 THEN
        RETURN 'Match ID : ' || p_match_id || ' not found';
    END IF;

    v_result := 'Match ID: ' || p_match_id || CHR(10) ||
                '-------------------------------------------' || CHR(10);

    FOR rec IN c_team_keeper_runs LOOP
        v_result := v_result ||
                    'Team ID: ' || rec.team_id ||
                    ' | Keeper Runs: ' || rec.keeper_runs || CHR(10);
    END LOOP;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_team_keeper_runs;
/

CREATE OR REPLACE PROCEDURE sp_event_card_health (
    p_event_date_str IN VARCHAR2,
    p_days_past      IN NUMBER DEFAULT 5,
    p_days_future    IN NUMBER DEFAULT 5
)
IS
    exp_invalid_date_format EXCEPTION;
    exp_invalid_date_range  EXCEPTION;

    co_weak_card_threshold CONSTANT NUMBER := 4;

    lv_event_date     DATE;
    lv_min_event_date DATE;
    lv_max_event_date DATE;
    lv_found          BOOLEAN := FALSE;

    CURSOR cur_cards (
        p_min_event_date DATE,
        p_max_event_date DATE
    )
    IS
        SELECT
            c.id AS card_id,
            e.name AS event_name,
            l.name AS location_name,
            TO_DATE(SUBSTR(c.event_date, 1, 10), 'YYYY-MM-DD') AS event_date,
            COUNT(m.id) AS match_count,
            SUM(CASE WHEN m.title_change = 1 THEN 1 ELSE 0 END) AS title_changes
        FROM WWE.CARDS c
        JOIN WWE.EVENTS e
            ON c.event_id = e.id
        LEFT JOIN WWE.LOCATIONS l
            ON c.location_id = l.id
        LEFT JOIN WWE.MATCHES m
            ON m.card_id = c.id
        WHERE TO_DATE(SUBSTR(c.event_date, 1, 10), 'YYYY-MM-DD')
              BETWEEN p_min_event_date AND p_max_event_date
        GROUP BY
            c.id,
            e.name,
            l.name,
            c.event_date;

BEGIN
    IF p_event_date_str IS NULL
       OR NOT REGEXP_LIKE(p_event_date_str, '^\d{4}-\d{2}-\d{2}$')
    THEN
        RAISE exp_invalid_date_format;
    END IF;

    IF p_days_past < 0 OR p_days_past > 5
       OR p_days_future < 0 OR p_days_future > 5
    THEN
        RAISE exp_invalid_date_range;
    END IF;

    BEGIN
        lv_event_date := TO_DATE(p_event_date_str, 'YYYY-MM-DD');
    EXCEPTION
        WHEN OTHERS THEN
            IF SQLCODE IN (-1830, -1839, -1843, -1847) THEN
                RAISE exp_invalid_date_format;
            ELSE
                RAISE;
            END IF;
    END;

    lv_min_event_date := lv_event_date - p_days_past;
    lv_max_event_date := lv_event_date + p_days_future;

    DBMS_OUTPUT.PUT_LINE(
        'WWE Card Health Report from '
        || TO_CHAR(lv_min_event_date, 'YYYY-MM-DD')
        || ' to '
        || TO_CHAR(lv_max_event_date, 'YYYY-MM-DD')
    );

    DBMS_OUTPUT.PUT_LINE(
           RPAD('Event', 25)
        || RPAD('Date', 12)
        || RPAD('Location', 20)
        || RPAD('Matches', 10)
        || RPAD('TitleChg', 10)
        || RPAD('Risk', 16)
        || 'Recommendation'
    );

    FOR rec_card IN cur_cards(lv_min_event_date, lv_max_event_date)
    LOOP
        lv_found := TRUE;

        DECLARE
            lv_risk           VARCHAR2(20);
            lv_recommendation VARCHAR2(200);
        BEGIN
            IF rec_card.match_count < co_weak_card_threshold THEN
                lv_risk := 'WEAK_CARD';
                lv_recommendation := 'Add more matches or combine with another event.';
            ELSIF rec_card.title_changes = 0 THEN
                lv_risk := 'NO_TITLE_CHANGES';
                lv_recommendation := 'Consider booking a title match to boost interest.';
            ELSE
                lv_risk := 'HEALTHY';
                lv_recommendation := 'Card looks balanced. No action needed.';
            END IF;

            DBMS_OUTPUT.PUT_LINE(
                   RPAD(SUBSTR(NVL(rec_card.event_name, 'N/A'), 1, 24), 25)
                || RPAD(TO_CHAR(rec_card.event_date, 'YYYY-MM-DD'), 12)
                || RPAD(SUBSTR(NVL(rec_card.location_name, 'N/A'), 1, 19), 20)
                || RPAD(TO_CHAR(rec_card.match_count), 10)
                || RPAD(TO_CHAR(rec_card.title_changes), 10)
                || RPAD(lv_risk, 16)
                || lv_recommendation
            );
        END;
    END LOOP;

    IF NOT lv_found THEN
        DBMS_OUTPUT.PUT_LINE('No WWE card records found for the given date range.');
    END IF;

EXCEPTION
    WHEN exp_invalid_date_format THEN
        DBMS_OUTPUT.PUT_LINE('Invalid date format. Expected YYYY-MM-DD.');
    WHEN exp_invalid_date_range THEN
        DBMS_OUTPUT.PUT_LINE('Date window exceeded: only past 5 days or future 5 days are allowed.');
    WHEN OTHERS THEN
        IF SQLCODE IN (-1830, -1839, -1843, -1847) THEN
            DBMS_OUTPUT.PUT_LINE('Invalid date format. Expected YYYY-MM-DD.');
        ELSE
            DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
        END IF;
END sp_event_card_health;
/

CREATE OR REPLACE PROCEDURE SP_GET_RUNNER_COMPELTED_ORDERS (
    p_runner_id IN modern_data.pizza_runners.runner_id%TYPE
) IS
    lv_reg_date     modern_data.pizza_runners.registration_date%TYPE;
    lv_total_orders modern_data.pizza_runner_orders.order_id%TYPE := 0;

    CURSOR c_orders IS
        SELECT o.order_id,
               o.distance,
               o.duration
        FROM   modern_data.pizza_runner_orders o
        WHERE  o.runner_id = p_runner_id
        AND    o.cancellation IS NULL
        ORDER BY o.order_id;
BEGIN
    SELECT registration_date
    INTO   lv_reg_date
    FROM   modern_data.pizza_runners
    WHERE  runner_id = p_runner_id;

    DBMS_OUTPUT.PUT_LINE('Runner Registered On: ' || lv_reg_date);

    FOR rec IN c_orders LOOP
        lv_total_orders := lv_total_orders + 1;

        DBMS_OUTPUT.PUT_LINE(
            'Processed Order: ' || rec.order_id ||
            ' | Distance: ' || NVL(TO_CHAR(rec.distance), 'N/A') ||
            ' | Duration: ' || NVL(TO_CHAR(rec.duration), 'N/A')
        );
    END LOOP;

    IF lv_total_orders = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Status: No successfully completed orders found.');
    ELSE
        DBMS_OUTPUT.PUT_LINE('Status: Total Completed Deliveries = ' || lv_total_orders);
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
