    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

CREATE OR REPLACE PROCEDURE sp_top_customers_by_year_month ( p_year IN NUMBER, p_month IN VARCHAR2)
IS
    v_count NUMBER := 0;
    v_month_number NUMBER;

    e_no_customer   EXCEPTION;
    e_one_customer  EXCEPTION;
    e_two_customers EXCEPTION;
    e_invalid_year  EXCEPTION;
    e_invalid_month EXCEPTION;
    e_month_null    EXCEPTION;
    e_year_null     EXCEPTION;

    CURSOR c_top_customers IS
       SELECT customer_name,
              total_amount
         FROM (
               SELECT c.firstname || ' ' || c.lastname AS customer_name,
                      SUM(ii.unitprice * ii.quantity) AS total_amount
                 FROM chinook.customers c
                 JOIN chinook.invoices i
                   ON c.customerid = i.customerid
                 JOIN chinook.invoice_items ii
                   ON i.invoiceid = ii.invoiceid
                WHERE EXTRACT(YEAR FROM i.invoicedate) = p_year
                  AND EXTRACT(MONTH FROM i.invoicedate) = v_month_number
                GROUP BY c.firstname, c.lastname
                ORDER BY SUM(ii.unitprice * ii.quantity) DESC
              )
        FETCH FIRST 3 ROWS ONLY;
BEGIN
    IF p_year IS NULL THEN
        RAISE e_year_null;
    ELSIF p_month IS NULL THEN
        RAISE e_month_null;
    ELSIF p_year < 1900 OR p_year > EXTRACT(YEAR FROM SYSDATE) THEN
        RAISE e_invalid_year;
    END IF;

    BEGIN
        v_month_number := TO_NUMBER(TO_CHAR(TO_DATE(p_month, 'MONTH', 'NLS_DATE_LANGUAGE=ENGLISH'), 'MM'));
    EXCEPTION
        WHEN OTHERS THEN
            RAISE e_invalid_month;
    END;

    FOR rec IN c_top_customers LOOP
        v_count := v_count + 1;
        DBMS_OUTPUT.PUT_LINE('Customer: ' || rec.customer_name ||' | Total Purchase Amount: ' || rec.total_amount);
    END LOOP;

    IF v_count = 0 THEN
        RAISE e_no_customer;
    ELSIF v_count = 1 THEN
        RAISE e_one_customer;
    ELSIF v_count = 2 THEN
        RAISE e_two_customers;
    END IF;

EXCEPTION
    WHEN e_no_customer THEN
        DBMS_OUTPUT.PUT_LINE('No customers found for the given year');
    WHEN e_one_customer THEN
        DBMS_OUTPUT.PUT_LINE('Only one customer found (displayed above)');
    WHEN e_two_customers THEN
        DBMS_OUTPUT.PUT_LINE('Only two customers found (displayed above)');
    WHEN e_invalid_year THEN
        DBMS_OUTPUT.PUT_LINE('Year must be between 1900 and current year');
    WHEN e_invalid_month THEN
        DBMS_OUTPUT.PUT_LINE('Month must be between 1 and 12');
    WHEN e_year_null THEN
        DBMS_OUTPUT.PUT_LINE('Input parameter p_year cannot be NULL');
    WHEN e_month_null THEN
        DBMS_OUTPUT.PUT_LINE('Input parameter p_month cannot be NULL');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_top_customers_by_year_month;
/

CREATE OR REPLACE PROCEDURE sp_get_bitcoin_transaction_summary (
    p_member_id IN BANK_SALES_TRADING.BITCOIN_MEMBERS.MEMBER_ID%TYPE
)
IS

    CURSOR c_txn IS
        SELECT 
            m.first_name,
            m.region,
            t.ticker,
            t.txn_id,
            t.txn_type,
            t.quantity,
            t.percentage_fee,
            p.high,
            p.low
        FROM bank_sales_trading.bitcoin_members m
        INNER JOIN bank_sales_trading.bitcoin_transactions t
            ON m.member_id = t.member_id
        INNER JOIN (
            SELECT
                market_date,
                ticker,
                MAX(high) AS high,
                MIN(low) AS low
            FROM bank_sales_trading.bitcoin_prices
            GROUP BY market_date, ticker
        ) p
            ON p.market_date = t.txn_date
           AND p.ticker = t.ticker
        WHERE m.member_id = p_member_id
          AND t.ticker = 'BTC'
        ORDER BY t.txn_id DESC
        FETCH FIRST 15 ROWS ONLY;

    lv_txn_rec c_txn%ROWTYPE;
    lv_found   BOOLEAN := FALSE;

BEGIN

    IF p_member_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Member ID must not be NULL');
        RETURN;
    END IF;

    OPEN c_txn;

    LOOP
        FETCH c_txn INTO lv_txn_rec;
        EXIT WHEN c_txn%NOTFOUND;

        lv_found := TRUE;

        DBMS_OUTPUT.PUT_LINE(
            'Member: ' || lv_txn_rec.first_name ||
            ', Region: ' || lv_txn_rec.region ||
            ', Ticker: ' || lv_txn_rec.ticker ||
            ', Txn ID: ' || lv_txn_rec.txn_id ||
            ', Type: ' || lv_txn_rec.txn_type ||
            ', Qty: ' || lv_txn_rec.quantity ||
            ', Fee(%): ' || lv_txn_rec.percentage_fee ||
            ', Price Range: ' || lv_txn_rec.low || ' - ' || lv_txn_rec.high
        );

    END LOOP;

    CLOSE c_txn;

    IF NOT lv_found THEN
        RAISE NO_DATA_FOUND;
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE(
            'No Bitcoin transactions found for the given member.'
        );
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred' );
END sp_get_bitcoin_transaction_summary;
/

