CREATE OR REPLACE PROCEDURE SP_GENERATE_FEATURE_DROP_REPORT (
    p_version IN NUMBER DEFAULT NULL
) AS
    lv_total_rows NUMBER := 0;
    lv_category   VARCHAR2(20);
    lv_version_to_use NUMBER;
    e_no_features_found EXCEPTION;

    CURSOR cur_features IS
        SELECT DISTINCT e.NAME,
                        e.FEATURE,
                        e.DROP_CORRELATION,
                        e.DROP_USER,
                        f.IMPORTANCE,
                        m.L1_MODEL
          FROM STACKING.EDA e
          LEFT JOIN STACKING.FEATURE_IMPORTANCE f
            ON e.FEATURE = f.FEATURE AND e.VERSION = f.VERSION
          LEFT JOIN STACKING.MODEL m
            ON e.NAME = m.NAME AND e.VERSION = m.VERSION
         WHERE e.VERSION = lv_version_to_use
           AND (e.DROP_CORRELATION > 0.8 OR e.DROP_USER = 1)
         ORDER BY e.FEATURE;

BEGIN
    -- Determine the dataset version to report.
    -- If no version is provided, use the latest available version from STACKING.EDA.
    IF p_version IS NULL THEN
        SELECT MAX(VERSION) INTO lv_version_to_use FROM STACKING.EDA;
    ELSE
        lv_version_to_use := p_version;
    END IF;

    -- Print the report header using the required output field names.
    -- The formatted layout is intended to keep report columns aligned for readability.
    DBMS_OUTPUT.PUT_LINE('NAME | FEATURE    | DROP_CORR | DROP_USER | IMPORTANCE | L1_MODEL   | CATEGORY');
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));

    -- Iterate through all features that meet DROP criteria for the selected version.
    -- DROP criteria are defined as either:
    -- 1) high correlation (DROP_CORRELATION > 0.8), or
    -- 2) explicitly flagged by the user (DROP_USER = 1).
    -- LEFT JOIN is used so that features are still reported even if IMPORTANCE
    -- or L1_MODEL details are missing in the related tables.
    FOR rec IN cur_features LOOP
        lv_total_rows := lv_total_rows + 1;

        -- Assign a business risk category based on correlation and importance.
        -- High Risk   : highly correlated and highly important.
        -- Medium Risk : either highly correlated or moderately/highly important.
        -- Low Risk    : all other matched DROP candidates.
        IF rec.DROP_CORRELATION > 0.8 AND rec.IMPORTANCE > 0.7 THEN
            lv_category := 'High Risk';
        ELSIF rec.DROP_CORRELATION > 0.8 OR rec.IMPORTANCE > 0.5 THEN
            lv_category := 'Medium Risk';
        ELSE
            lv_category := 'Low Risk';
        END IF;

        -- Print each feature row in a consistent fixed-width format.
        -- NVL is used for L1_MODEL so missing model values display as '-'.
        DBMS_OUTPUT.PUT_LINE(
            RPAD(rec.NAME, 8) || ' | ' ||
            RPAD(rec.FEATURE, 10) || ' | ' ||
            RPAD(TO_CHAR(rec.DROP_CORRELATION), 9) || ' | ' ||
            RPAD(TO_CHAR(rec.DROP_USER), 9) || ' | ' ||
            RPAD(TO_CHAR(rec.IMPORTANCE), 10) || ' | ' ||
            RPAD(NVL(rec.L1_MODEL,'-'), 10) || ' | ' ||
            RPAD(lv_category, 12)
        );
    END LOOP;

    -- If no rows were returned by the cursor, raise the required user-defined exception.
    IF lv_total_rows = 0 THEN
        RAISE e_no_features_found;
    END IF;

EXCEPTION
    WHEN e_no_features_found THEN
        DBMS_OUTPUT.PUT_LINE('No features found matching DROP criteria for version ' || '''' || lv_version_to_use);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END SP_GENERATE_FEATURE_DROP_REPORT;
/

CREATE OR REPLACE PROCEDURE SP_SUMMARISE_CITY_POPULATION (
    p_country_code IN city_legislation.cities.country_code_2%TYPE
) IS
    lv_city_name        city_legislation.cities.city_name%TYPE;
    lv_population       city_legislation.cities.population%TYPE;
    lv_country_name     city_legislation.cities_countries.country_name%TYPE;
    lv_total_population city_legislation.cities.population%TYPE := 0;
    lv_row_count        PLS_INTEGER := 0;

    CURSOR c_city_data IS
        SELECT
            c.city_name,
            c.population,
            cc.country_name
        FROM city_legislation.cities c
        JOIN city_legislation.cities_countries cc
            ON c.country_code_2 = cc.country_code_2
        WHERE c.country_code_2 = p_country_code
          AND c.population IS NOT NULL
        ORDER BY TO_NUMBER(c.population) DESC
        FETCH FIRST 10 ROWS ONLY;
BEGIN
    IF p_country_code IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Country code input cannot be NULL.');
        RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('--- TOP 10 CITIES FOR COUNTRY CODE: ' || p_country_code || ' ---');

    OPEN c_city_data;
    LOOP
        FETCH c_city_data INTO lv_city_name, lv_population, lv_country_name;
        EXIT WHEN c_city_data%NOTFOUND;

        lv_row_count := lv_row_count + 1;
        lv_total_population := lv_total_population + NVL(TO_NUMBER(lv_population), 0);

        DBMS_OUTPUT.PUT_LINE(
            'Rank ' || lv_row_count || ': ' || lv_city_name ||
            ' (' || lv_country_name || ') | Population: ' || lv_population
        );
    END LOOP;
    CLOSE c_city_data;

    IF lv_row_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No city data available for the provided country code.');
    ELSE
        DBMS_OUTPUT.PUT_LINE('-----------------------------------');
        DBMS_OUTPUT.PUT_LINE('Total Population (Top 10): ' || lv_total_population);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
        IF c_city_data%ISOPEN THEN
            CLOSE c_city_data;
        END IF;
END;
/

