CREATE OR REPLACE PROCEDURE sp_order_summary (
    p_year NUMBER,
    p_store_id NUMBER
)
IS
    co_high_value_threshold CONSTANT NUMBER := 1000;
    lv_header_printed NUMBER := 0;
    lv_total_orders NUMBER := 0;
    lv_total_amount NUMBER := 0;
    exp_no_orders_found EXCEPTION;

    CURSOR cur_order_summary IS
        SELECT
            o.order_id,
            s.store_name,
            h.hub_city,
            c.channel_name,
            p.payment_method,
            o.order_amount
        FROM DELIVERY_CENTER.ORDERS o
        INNER JOIN DELIVERY_CENTER.STORES s
            ON o.store_id = s.store_id
        INNER JOIN DELIVERY_CENTER.HUBS h
            ON s.hub_id = h.hub_id
        INNER JOIN DELIVERY_CENTER.CHANNELS c
            ON o.channel_id = c.channel_id
        INNER JOIN DELIVERY_CENTER.PAYMENTS p
            ON o.payment_order_id = p.payment_order_id
        WHERE o.order_created_year = p_year
          AND o.store_id = p_store_id
        ORDER BY o.order_id DESC;
BEGIN
    IF p_year IS NULL OR p_year < 2000 OR p_year > EXTRACT(YEAR FROM SYSDATE) THEN
        DBMS_OUTPUT.PUT_LINE('Invalid year supplied (' || NVL(TO_CHAR(p_year), 'NULL') || '). Year must be between 2000 and the current year.');
        RETURN;
    END IF;

    IF p_store_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Invalid input: Store ID cannot be NULL.');
        RETURN;
    END IF;

    FOR rec_order IN cur_order_summary LOOP
        IF lv_header_printed = 0 THEN
            DBMS_OUTPUT.PUT_LINE('Order Details Report:');
            DBMS_OUTPUT.PUT_LINE('---------------------');
            lv_header_printed := 1;
        END IF;

        lv_total_orders := lv_total_orders + 1;
        lv_total_amount := lv_total_amount + rec_order.order_amount;

        DBMS_OUTPUT.PUT_LINE('Order ID: ' || rec_order.order_id);
        DBMS_OUTPUT.PUT_LINE('Store: ' || rec_order.store_name);
        DBMS_OUTPUT.PUT_LINE('Hub: ' || rec_order.hub_city);
        DBMS_OUTPUT.PUT_LINE('Channel: ' || rec_order.channel_name);
        DBMS_OUTPUT.PUT_LINE('Payment: ' || rec_order.payment_method);
        DBMS_OUTPUT.PUT_LINE('Amount: ' || rec_order.order_amount);

        IF rec_order.order_amount >= co_high_value_threshold THEN
            DBMS_OUTPUT.PUT_LINE('Order Category: HIGH VALUE');
        ELSE
            DBMS_OUTPUT.PUT_LINE('Order Category: LOW VALUE');
        END IF;

        DBMS_OUTPUT.PUT_LINE('---------------------');
    END LOOP;

    IF lv_total_orders = 0 THEN
        RAISE exp_no_orders_found;
    END IF;

    DBMS_OUTPUT.PUT_LINE('TOTAL ORDERS  : ' || lv_total_orders);
    DBMS_OUTPUT.PUT_LINE('TOTAL AMOUNT  : ' || lv_total_amount);
EXCEPTION
    WHEN exp_no_orders_found THEN
        DBMS_OUTPUT.PUT_LINE('Audit Error: No orders found for Year ' || p_year || ' and Store ID ' || p_store_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END sp_order_summary;
/

CREATE OR REPLACE PROCEDURE proc_inventory_shortfall (
    p_warehouse_id IN ORACLE_SQL.LOCATIONS.WAREHOUSE%TYPE
) IS
    CURSOR cur_inv IS
        SELECT p.name AS product_name,
               SUM(i.qty) AS total_qty,
               NVL(pm.qty_minimum, 0) AS qty_minimum
        FROM ORACLE_SQL.INVENTORY i
        JOIN ORACLE_SQL.LOCATIONS l
          ON i.location_id = l.id
        JOIN ORACLE_SQL.PRODUCTS p
          ON i.product_id = p.id
        LEFT JOIN ORACLE_SQL.PRODUCT_MINIMUMS pm
          ON pm.product_id = p.id
        WHERE l.warehouse = p_warehouse_id
        GROUP BY p.name, NVL(pm.qty_minimum, 0);

    v_shortfall_cnt NUMBER := 0;
    v_count NUMBER := 0;
    v_dummy NUMBER;
BEGIN
    SELECT 1
    INTO v_dummy
    FROM ORACLE_SQL.LOCATIONS l
    WHERE l.warehouse = p_warehouse_id
      AND ROWNUM = 1;

    FOR rec IN cur_inv LOOP
        IF rec.total_qty < rec.qty_minimum THEN
            v_shortfall_cnt := v_shortfall_cnt + 1;
            DBMS_OUTPUT.PUT_LINE(
                'Product: ' || rec.product_name ||
                ', Available: ' || rec.total_qty ||
                ', Minimum: ' || rec.qty_minimum
            );
        END IF;
    END LOOP;

    SELECT COUNT(*)
    INTO v_count
    FROM ORACLE_SQL.INVENTORY i
    JOIN ORACLE_SQL.LOCATIONS l
      ON i.location_id = l.id
    WHERE l.warehouse = p_warehouse_id;

    IF v_shortfall_cnt = 0 THEN
        IF v_count = 0 THEN
            DBMS_OUTPUT.PUT_LINE('No inventory found with the given ID');
        ELSE
            DBMS_OUTPUT.PUT_LINE('No inventory shortfalls found.');
        END IF;
    END IF;

EXCEPTION
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Data inconsistency detected.');
    WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Numeric or conversion error occurred.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error');
END proc_inventory_shortfall;
/

