CREATE OR REPLACE PACKAGE pkg_process_sales AS
    PROCEDURE p_process_sales_with_validation (
        p_customer_id   IN complex_oracle.customers.cust_id%TYPE DEFAULT NULL,
        p_product_id    IN complex_oracle.products.prod_id%TYPE DEFAULT NULL,
        p_do_commit     IN VARCHAR2 DEFAULT 'Y'
    );
END pkg_process_sales;
/

CREATE OR REPLACE PACKAGE BODY pkg_process_sales AS

PROCEDURE p_process_sales_with_validation (
        p_customer_id   IN complex_oracle.customers.cust_id%TYPE DEFAULT NULL,
        p_product_id    IN complex_oracle.products.prod_id%TYPE DEFAULT NULL,
        p_do_commit     IN VARCHAR2 DEFAULT 'Y'
    )
IS
    CURSOR c_customers_cur IS
        SELECT cust_id
        FROM complex_oracle.customers
        WHERE cust_id = p_customer_id
        ORDER BY cust_id;

    CURSOR c_sales_cur(p_cust_id complex_oracle.customers.cust_id%TYPE) IS
        SELECT prod_id,
               SUM(amount_sold * quantity_sold) processed_amount
        FROM complex_oracle.sales
        WHERE cust_id = p_cust_id
          AND prod_id = p_product_id
        GROUP BY prod_id
        ORDER BY prod_id;

    v_product_id       complex_oracle.products.prod_id%TYPE;
    v_customer_id      complex_oracle.customers.cust_id%TYPE;
    v_total_sales      NUMBER;
    v_abort            BOOLEAN := FALSE;
    v_sales_found      BOOLEAN := FALSE;

BEGIN
    DBMS_OUTPUT.PUT_LINE('Process started');

    IF p_customer_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Customer ID NULL not found');
        v_abort := TRUE;
    ELSIF p_product_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Product ID NULL not found');
        v_abort := TRUE;
    ELSIF p_do_commit IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Commit flag NULL not found');
        v_abort := TRUE;
    ELSIF p_do_commit NOT IN ('Y','N') THEN
        DBMS_OUTPUT.PUT_LINE('Invalid commit flag');
        v_abort := TRUE;
    END IF;

    IF NOT v_abort THEN
        BEGIN
            SELECT cust_id
            INTO v_customer_id
            FROM complex_oracle.customers
            WHERE cust_id = p_customer_id;

            FOR cust_rec IN c_customers_cur LOOP
                DBMS_OUTPUT.PUT_LINE('Customer:' || cust_rec.cust_id);

                FOR sales_rec IN c_sales_cur(cust_rec.cust_id) LOOP
                    v_sales_found := TRUE;

                    BEGIN
                        SELECT prod_id
                        INTO v_product_id
                        FROM complex_oracle.products
                        WHERE prod_id = sales_rec.prod_id;

                        v_total_sales := sales_rec.processed_amount;

                        DBMS_OUTPUT.PUT_LINE(
                            'Product [' || sales_rec.prod_id || '] Processed Amount = ' || v_total_sales
                        );
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            DBMS_OUTPUT.PUT_LINE('Product [' || sales_rec.prod_id || '] not found');
                    END;
                END LOOP;
            END LOOP;

            IF NOT v_sales_found THEN
                RAISE NO_DATA_FOUND;
            END IF;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE('Customer not found');
                v_abort := TRUE;
        END;
    END IF;

    IF v_abort THEN
        ROLLBACK;
        DBMS_OUTPUT.PUT_LINE('Transaction rolled back');
    ELSIF p_do_commit = 'Y' THEN
        COMMIT;
        DBMS_OUTPUT.PUT_LINE('Transaction committed');
    ELSE
        ROLLBACK;
        DBMS_OUTPUT.PUT_LINE('Transaction rolled back');
    END IF;

    DBMS_OUTPUT.PUT_LINE('Process completed');

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        ROLLBACK;
        DBMS_OUTPUT.PUT_LINE('Error: Required data not found.');
        DBMS_OUTPUT.PUT_LINE('Process completed');
    WHEN OTHERS THEN
        ROLLBACK;
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
        DBMS_OUTPUT.PUT_LINE('Process completed');
END p_process_sales_with_validation;

END pkg_process_sales;
/

