CREATE OR REPLACE PACKAGE pkg_sales_margin_processing AS
    MAX_ROWS_TO_PROCESS CONSTANT NUMBER := 10;

    PROCEDURE sp_process_yearly_margin(p_year NUMBER);
END pkg_sales_margin_processing;
/

CREATE OR REPLACE PACKAGE BODY pkg_sales_margin_processing AS

    PROCEDURE sp_process_yearly_margin(p_year NUMBER) IS
        ex_year_missing     EXCEPTION;
        ex_no_data          EXCEPTION;

        v_row_count         NUMBER := 0;
        v_unit_cost         NUMBER;
        v_margin            NUMBER;
        v_converted_amount  NUMBER;

        CURSOR cur_sales IS
            SELECT DISTINCT
                   s.prod_id         AS product_id,
                   s.cust_id         AS customer_id,
                   t.calendar_year,
                   s.amount_sold,
                   NVL(c.to_us, 1)   AS conversion_rate
            FROM   COMPLEX_ORACLE.SALES s
            JOIN   COMPLEX_ORACLE.TIMES t
                   ON s.time_id = t.time_id
            LEFT JOIN COMPLEX_ORACLE.CURRENCY c
                   ON c.year  = t.calendar_year
                  AND c.month = t.calendar_month_number
            WHERE  t.calendar_year = p_year
            ORDER BY s.prod_id, s.cust_id
            FETCH FIRST 10 ROWS ONLY;

    BEGIN
        IF p_year IS NULL THEN
            RAISE ex_year_missing;
        END IF;

        FOR r IN cur_sales LOOP
            IF v_row_count = 0 THEN
                DBMS_OUTPUT.PUT_LINE('=== Sales Margin Analysis Report ===');
                DBMS_OUTPUT.PUT_LINE('Calendar Year: ' || p_year);
                DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
            END IF;

            v_row_count := v_row_count + 1;

            BEGIN
                SELECT MAX(unit_cost)
                  INTO v_unit_cost
                  FROM COMPLEX_ORACLE.COSTS
                 WHERE prod_id = r.product_id;

                IF v_unit_cost IS NOT NULL THEN
                    v_converted_amount := r.amount_sold * r.conversion_rate;
                    v_margin := v_converted_amount - v_unit_cost;

                    DBMS_OUTPUT.PUT_LINE('Product ID: ' || r.product_id ||
                                         ' | Customer ID: ' || r.customer_id);
                    DBMS_OUTPUT.PUT_LINE('  Amount Sold: $' || TO_CHAR(ROUND(r.amount_sold, 2), 'FM9999999999999990.00') ||
                                         ' | Conversion Rate: ' || TO_CHAR(r.conversion_rate));
                    DBMS_OUTPUT.PUT_LINE('  Converted Amount: $' || TO_CHAR(ROUND(v_converted_amount, 2), 'FM9999999999999990.00') ||
                                         ' | Unit Cost: $' || TO_CHAR(ROUND(v_unit_cost, 2), 'FM9999999999999990.00'));
                    DBMS_OUTPUT.PUT_LINE('  Margin: $' || TO_CHAR(ROUND(v_margin, 2), 'FM9999999999999990.00'));
                    DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
                END IF;
            EXCEPTION
                WHEN OTHERS THEN
                    DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
            END;
        END LOOP;

        IF v_row_count = 0 THEN
            RAISE ex_no_data;
        END IF;

        COMMIT;
        DBMS_OUTPUT.PUT_LINE('Successfully processed ' || v_row_count || ' records.');

    EXCEPTION
        WHEN ex_year_missing THEN
            DBMS_OUTPUT.PUT_LINE('ERROR: Calendar year parameter is mandatory.');
        WHEN ex_no_data THEN
            DBMS_OUTPUT.PUT_LINE('ERROR: No sales data found for year ' || p_year);
        WHEN OTHERS THEN
            ROLLBACK;
            DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
    END sp_process_yearly_margin;

END pkg_sales_margin_processing;
/

