CREATE OR REPLACE PROCEDURE SP_PROCESS_FEATURE_DROP_BATCH (
    p_batch_id   IN NUMBER DEFAULT NULL,
    p_risk_level IN VARCHAR2 DEFAULT NULL
) AS
    lv_count     NUMBER := 0;
    lv_category  VARCHAR2(10);

    e_no_data EXCEPTION;

    CURSOR c_orders IS
        SELECT c.name        AS customer_name,
               o.id          AS order_id,
               p.name        AS product_name,
               ol.qty        AS qty,
               ol.amount     AS amount
          FROM ORACLE_SQL.customers c
          JOIN ORACLE_SQL.orders o
               ON c.id = o.customer_id
          JOIN ORACLE_SQL.orderlines ol
               ON o.id = ol.order_id
          JOIN ORACLE_SQL.products p
               ON ol.product_id = p.id
         WHERE (p_batch_id IS NULL OR o.id = p_batch_id)
         ORDER BY o.id;

BEGIN
    SAVEPOINT sp_start;

    DBMS_OUTPUT.PUT_LINE('CUSTOMER | ORDER_ID | PRODUCT        | QTY | AMOUNT | CATEGORY');
    DBMS_OUTPUT.PUT_LINE('---------------------------------------------------------------');

    FOR rec IN c_orders LOOP
        IF rec.amount >= 1000 THEN
            lv_category := 'HIGH';
        ELSIF rec.amount BETWEEN 500 AND 999 THEN
            lv_category := 'MEDIUM';
        ELSE
            lv_category := 'LOW';
        END IF;

        IF NVL(UPPER(p_risk_level), 'ALL') = 'ALL'
           OR lv_category = NVL(UPPER(p_risk_level), lv_category) THEN

            lv_count := lv_count + 1;

            DBMS_OUTPUT.PUT_LINE(
                  RPAD(rec.customer_name, 12) || ' | '
                || RPAD(rec.order_id, 8)      || ' | '
                || RPAD(rec.product_name, 14) || ' | '
                || LPAD(rec.qty, 3)           || ' | '
                || LPAD(rec.amount, 6)        || ' | '
                || lv_category
            );
        END IF;
    END LOOP;

    IF lv_count = 0 THEN
        RAISE e_no_data;
    END IF;

    COMMIT;

EXCEPTION
    WHEN e_no_data THEN
        ROLLBACK TO sp_start;
        DBMS_OUTPUT.PUT_LINE('No matching records found');

    WHEN OTHERS THEN
        ROLLBACK TO sp_start;
        DBMS_OUTPUT.PUT_LINE(SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END SP_PROCESS_FEATURE_DROP_BATCH;
/

CREATE OR REPLACE PACKAGE pkg_match_audit IS
    PROCEDURE sp_validate_match_statistics(p_match_id IN IPL.MATCH.match_id%TYPE);
END pkg_match_audit;
/

CREATE OR REPLACE PACKAGE BODY pkg_match_audit IS

    c_max_display_limit       CONSTANT NUMBER := 5;
    c_max_overs               CONSTANT NUMBER := 20;
    c_balls_per_over          CONSTANT NUMBER := 6;
    c_max_runs_per_ball       CONSTANT NUMBER := 6;
    c_max_wickets_per_innings CONSTANT NUMBER := 10;

    PROCEDURE sp_validate_match_statistics (
        p_match_id IN IPL.MATCH.match_id%TYPE
    )
    IS
        CURSOR cur_match_balls IS
            SELECT b.match_id,
                   b.over_id,
                   b.ball_id,
                   b.innings_no,
                   b.team_batting,
                   b.striker,
                   b.bowler,
                   bs.runs_scored,
                   p1.player_name AS striker_name,
                   p2.player_name AS bowler_name
            FROM IPL.BALL_BY_BALL b
            LEFT JOIN IPL.BATSMAN_SCORED bs
                ON b.match_id = bs.match_id
                AND b.over_id = bs.over_id
                AND b.ball_id = bs.ball_id
                AND b.innings_no = bs.innings_no
            INNER JOIN IPL.PLAYER p1 ON b.striker = p1.player_id
            INNER JOIN IPL.PLAYER p2 ON b.bowler = p2.player_id
            WHERE b.match_id = p_match_id
            ORDER BY b.innings_no, b.over_id, b.ball_id;

        v_match_id      IPL.BALL_BY_BALL.match_id%TYPE;
        v_over_id       IPL.BALL_BY_BALL.over_id%TYPE;
        v_ball_id       IPL.BALL_BY_BALL.ball_id%TYPE;
        v_innings_no    IPL.BALL_BY_BALL.innings_no%TYPE;
        v_team_batting  IPL.BALL_BY_BALL.team_batting%TYPE;
        v_striker       IPL.BALL_BY_BALL.striker%TYPE;
        v_bowler        IPL.BALL_BY_BALL.bowler%TYPE;
        v_runs_scored   IPL.BATSMAN_SCORED.runs_scored%TYPE;
        v_striker_name  IPL.PLAYER.player_name%TYPE;
        v_bowler_name   IPL.PLAYER.player_name%TYPE;

        v_total_balls         NUMBER := 0;
        v_total_runs          NUMBER := 0;
        v_total_wickets       NUMBER := 0;
        v_invalid_over_count  NUMBER := 0;
        v_invalid_ball_count  NUMBER := 0;
        v_invalid_runs_count  NUMBER := 0;
        v_missing_score_count NUMBER := 0;
        v_processed_count     NUMBER := 0;
        v_match_exists        NUMBER := 0;
        v_validation_failed   BOOLEAN := FALSE;
        v_team1               IPL.MATCH.team_1%TYPE;
        v_team2               IPL.MATCH.team_2%TYPE;
        v_match_date          IPL.MATCH.match_date%TYPE;
        v_season_id           IPL.MATCH.season_id%TYPE;
        v_has_savepoint       BOOLEAN := FALSE;

    BEGIN
        IF p_match_id IS NULL THEN
            DBMS_OUTPUT.PUT_LINE('ERROR: MATCH_ID cannot be NULL');
            RETURN;
        END IF;

        BEGIN
            SELECT COUNT(*)
            INTO v_match_exists
            FROM IPL.MATCH
            WHERE match_id = p_match_id;

            IF v_match_exists = 0 THEN
                DBMS_OUTPUT.PUT_LINE('ERROR: Match ID ' || p_match_id || ' does not exist');
                RETURN;
            END IF;

            SELECT team_1, team_2, match_date, season_id
            INTO v_team1, v_team2, v_match_date, v_season_id
            FROM IPL.MATCH
            WHERE match_id = p_match_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE('ERROR: Match ID ' || p_match_id || ' does not exist');
                RETURN;
        END;

        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('IPL MATCH DATA QUALITY AUDIT');
        DBMS_OUTPUT.PUT_LINE('Match ID: ' || p_match_id || ' | Season: ' || v_season_id);
        DBMS_OUTPUT.PUT_LINE('Teams: Team ' || v_team1 || ' vs Team ' || v_team2);
        DBMS_OUTPUT.PUT_LINE('Date: ' || v_match_date);
        DBMS_OUTPUT.PUT_LINE('========================================');

        SAVEPOINT before_validation;
        v_has_savepoint := TRUE;

        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('PHASE 1: DATA INTEGRITY VALIDATION');
        DBMS_OUTPUT.PUT_LINE('----------------------------------');

        OPEN cur_match_balls;
        LOOP
            FETCH cur_match_balls INTO v_match_id, v_over_id, v_ball_id, v_innings_no,
                                       v_team_batting, v_striker, v_bowler, v_runs_scored,
                                       v_striker_name, v_bowler_name;
            EXIT WHEN cur_match_balls%NOTFOUND;

            v_total_balls := v_total_balls + 1;

            IF v_over_id > c_max_overs OR v_over_id < 1 THEN
                v_invalid_over_count := v_invalid_over_count + 1;
                v_validation_failed := TRUE;
                DBMS_OUTPUT.PUT_LINE('ALERT: Invalid over number ' || v_over_id ||
                                   ' in innings ' || v_innings_no);
            END IF;

            IF v_ball_id > c_balls_per_over OR v_ball_id < 1 THEN
                v_invalid_ball_count := v_invalid_ball_count + 1;
                v_validation_failed := TRUE;
                DBMS_OUTPUT.PUT_LINE('ALERT: Invalid ball number ' || v_ball_id ||
                                   ' in over ' || v_over_id);
            END IF;

            IF v_runs_scored IS NULL THEN
                v_missing_score_count := v_missing_score_count + 1;
                v_validation_failed := TRUE;
                DBMS_OUTPUT.PUT_LINE('ALERT: Missing runs data for over ' || v_over_id ||
                                   ' ball ' || v_ball_id);
            ELSE
                v_total_runs := v_total_runs + v_runs_scored;

                IF v_runs_scored > c_max_runs_per_ball THEN
                    v_invalid_runs_count := v_invalid_runs_count + 1;
                    DBMS_OUTPUT.PUT_LINE('WARNING: High runs (' || v_runs_scored ||
                                       ') on over ' || v_over_id || ' ball ' || v_ball_id);
                END IF;
            END IF;
        END LOOP;
        CLOSE cur_match_balls;

        SELECT COUNT(*)
        INTO v_total_wickets
        FROM IPL.WICKET_TAKEN
        WHERE match_id = p_match_id;

        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('Validation Statistics:');
        DBMS_OUTPUT.PUT_LINE('  Total Balls Validated: ' || v_total_balls);
        DBMS_OUTPUT.PUT_LINE('  Total Runs Recorded: ' || v_total_runs);
        DBMS_OUTPUT.PUT_LINE('  Total Wickets Recorded: ' || v_total_wickets);
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('Anomalies Detected:');
        DBMS_OUTPUT.PUT_LINE('  Invalid Over Numbers: ' || v_invalid_over_count);
        DBMS_OUTPUT.PUT_LINE('  Invalid Ball Numbers: ' || v_invalid_ball_count);
        DBMS_OUTPUT.PUT_LINE('  Missing Score Records: ' || v_missing_score_count);
        DBMS_OUTPUT.PUT_LINE('  High Runs Warnings: ' || v_invalid_runs_count);

        IF v_validation_failed THEN
            ROLLBACK TO before_validation;
            DBMS_OUTPUT.PUT_LINE('');
            DBMS_OUTPUT.PUT_LINE('========================================');
            DBMS_OUTPUT.PUT_LINE('VALIDATION FAILED - MANUAL REVIEW REQUIRED');
            DBMS_OUTPUT.PUT_LINE('========================================');
            DBMS_OUTPUT.PUT_LINE('STATUS: Match flagged for data quality review');
            DBMS_OUTPUT.PUT_LINE('ACTION: Correct data inconsistencies before certification');
            DBMS_OUTPUT.PUT_LINE('');
            DBMS_OUTPUT.PUT_LINE('Critical Issues Found: ' ||
                               (v_invalid_over_count + v_invalid_ball_count + v_missing_score_count));
            RETURN;
        END IF;

        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('VALIDATION PASSED - DATA QUALITY CERTIFIED');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('STATUS: Match data meets IPL quality standards');
        DBMS_OUTPUT.PUT_LINE('All validation checks completed successfully');

        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('PHASE 2: AUDIT REPORT GENERATION');
        DBMS_OUTPUT.PUT_LINE('--------------------------------');

        v_processed_count := 0;
        OPEN cur_match_balls;
        LOOP
            FETCH cur_match_balls INTO v_match_id, v_over_id, v_ball_id, v_innings_no,
                                       v_team_batting, v_striker, v_bowler, v_runs_scored,
                                       v_striker_name, v_bowler_name;
            EXIT WHEN cur_match_balls%NOTFOUND;

            v_processed_count := v_processed_count + 1;

            IF v_processed_count <= c_max_display_limit THEN
                DBMS_OUTPUT.PUT_LINE('Ball ' || v_processed_count || ': Innings ' || v_innings_no ||
                                   ' | Over ' || v_over_id || '.' || v_ball_id ||
                                   ' | ' || v_striker_name || ' vs ' || v_bowler_name ||
                                   ' | Runs: ' || NVL(v_runs_scored, 0));
            END IF;
        END LOOP;
        CLOSE cur_match_balls;

        COMMIT;

        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('AUDIT COMPLETED SUCCESSFULLY');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('Total Balls Audited: ' || v_processed_count);
        DBMS_OUTPUT.PUT_LINE('Match data certified for official IPL records');

    EXCEPTION
        WHEN OTHERS THEN
            IF v_has_savepoint THEN
                ROLLBACK TO before_validation;
            ELSE
                ROLLBACK;
            END IF;
            IF cur_match_balls%ISOPEN THEN
                CLOSE cur_match_balls;
            END IF;
            DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
    END sp_validate_match_statistics;

END pkg_match_audit;
/

