  v_status    AIRLINES.FLIGHTS.STATUS%TYPE;
  v_sched_dep AIRLINES.FLIGHTS.SCHEDULED_DEPARTURE%TYPE;
  v_err_msg   VARCHAR2(4000);
BEGIN
  SELECT STATUS, SCHEDULED_DEPARTURE INTO v_status, v_sched_dep FROM AIRLINES.FLIGHTS WHERE FLIGHT_ID = v_flight_id;
  IF v_status = 'Arrived' THEN DBMS_OUTPUT.PUT_LINE('Flight ' || v_flight_id || ' has Arrived');
  ELSIF v_status = 'Scheduled' THEN DBMS_OUTPUT.PUT_LINE('Flight ' || v_flight_id || ' is Scheduled for ' || TO_CHAR(v_sched_dep, 'YYYY-MM-DD HH24:MI:SS'));
  ELSE DBMS_OUTPUT.PUT_LINE('Flight ' || v_flight_id || ' status: ' || v_status); END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('No record for ID: ' || v_flight_id);
  WHEN OTHERS THEN v_err_msg := SQLERRM; DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || v_err_msg);
END;
/

