CREATE OR REPLACE PROCEDURE sp_store_orders(
    p_store_id IN NUMBER
) IS

    lv_store_name    DELIVERY_CENTER.STORES.store_name%TYPE;
    lv_store_segment DELIVERY_CENTER.STORES.store_segment%TYPE;
    lv_store_count   NUMBER := 0;
    lv_order_count   NUMBER := 0;
    lv_total_orders  NUMBER := 0;

    CURSOR cur_orders(p_sid NUMBER) IS
        SELECT order_id,
               order_status,
               order_amount,
               order_delivery_fee
          FROM DELIVERY_CENTER.ORDERS
         WHERE store_id = p_sid;

    rec_order cur_orders%ROWTYPE;

BEGIN
    DBMS_OUTPUT.PUT_LINE('AUDIT_START');
    DBMS_OUTPUT.PUT_LINE('STORE_ID=' || NVL(TO_CHAR(p_store_id), 'NULL'));

    -- RCA: Anticipate NULL p_store_id before any SELECT
    IF p_store_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('RCA_START');
        DBMS_OUTPUT.PUT_LINE('RCA_CAUSE=NULL_STORE_ID');
        DBMS_OUTPUT.PUT_LINE('RCA_END');
        DBMS_OUTPUT.PUT_LINE('AUDIT_END');
        RETURN;
    END IF;


    -- RCA: Anticipate store absent from STORES table
    SELECT COUNT(*)
      INTO lv_store_count
      FROM DELIVERY_CENTER.STORES
     WHERE store_id = p_store_id;

    IF lv_store_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('RCA_START');
        DBMS_OUTPUT.PUT_LINE('RCA_CAUSE=STORE_NOT_FOUND');
        DBMS_OUTPUT.PUT_LINE('RCA_END');
        DBMS_OUTPUT.PUT_LINE('AUDIT_END');
        RETURN;
    END IF;


    SELECT store_name,
           store_segment
      INTO lv_store_name,
           lv_store_segment
      FROM DELIVERY_CENTER.STORES
     WHERE store_id = p_store_id;

    DBMS_OUTPUT.PUT_LINE('STORE_NAME='    || NVL(lv_store_name,    'NULL'));
    DBMS_OUTPUT.PUT_LINE('STORE_SEGMENT=' || NVL(lv_store_segment, 'NULL'));


    -- RCA: Anticipate zero orders for the store
    SELECT COUNT(*)
      INTO lv_order_count
      FROM DELIVERY_CENTER.ORDERS
     WHERE store_id = p_store_id;

    IF lv_order_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('RCA_START');
        DBMS_OUTPUT.PUT_LINE('RCA_CAUSE=NO_ORDERS_FOUND');
        DBMS_OUTPUT.PUT_LINE('RCA_END');
        DBMS_OUTPUT.PUT_LINE('TOTAL_ORDERS=0');
        DBMS_OUTPUT.PUT_LINE('AUDIT_END');
        RETURN;
    END IF;


    DBMS_OUTPUT.PUT_LINE('RCA_START');
    DBMS_OUTPUT.PUT_LINE('RCA_CAUSE=NONE');
    DBMS_OUTPUT.PUT_LINE('RCA_END');


    OPEN cur_orders(p_store_id);
    LOOP
        FETCH cur_orders INTO rec_order;
        EXIT WHEN cur_orders%NOTFOUND;

        lv_total_orders := lv_total_orders + 1;


        IF rec_order.order_status = 'FINISHED' THEN
            DBMS_OUTPUT.PUT_LINE('ORDER_ID='          || rec_order.order_id);
            DBMS_OUTPUT.PUT_LINE('ORDER_STATUS='      || rec_order.order_status);
            DBMS_OUTPUT.PUT_LINE('ORDER_AMOUNT='      || NVL(rec_order.order_amount, 0));
            DBMS_OUTPUT.PUT_LINE('ORDER_DELIVERY_FEE='|| NVL(rec_order.order_delivery_fee, 0));
        ELSIF rec_order.order_status = 'CANCELLED' THEN
            DBMS_OUTPUT.PUT_LINE('ORDER_ID='          || rec_order.order_id);
            DBMS_OUTPUT.PUT_LINE('ORDER_STATUS='      || rec_order.order_status);
            DBMS_OUTPUT.PUT_LINE('ORDER_AMOUNT='      || NVL(rec_order.order_amount, 0));
            DBMS_OUTPUT.PUT_LINE('ORDER_DELIVERY_FEE='|| NVL(rec_order.order_delivery_fee, 0));
        ELSE
            DBMS_OUTPUT.PUT_LINE('ORDER_ID='          || rec_order.order_id);
            DBMS_OUTPUT.PUT_LINE('ORDER_STATUS='      || rec_order.order_status);
            DBMS_OUTPUT.PUT_LINE('ORDER_AMOUNT='      || NVL(rec_order.order_amount, 0));
            DBMS_OUTPUT.PUT_LINE('ORDER_DELIVERY_FEE='|| NVL(rec_order.order_delivery_fee, 0));
        END IF;

    END LOOP;
    CLOSE cur_orders;


    DBMS_OUTPUT.PUT_LINE('TOTAL_ORDERS=' || lv_total_orders);
    DBMS_OUTPUT.PUT_LINE('AUDIT_END');

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No data found');
        DBMS_OUTPUT.PUT_LINE('AUDIT_END');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('RCA_START');
        DBMS_OUTPUT.PUT_LINE('RCA_CAUSE=UNEXPECTED_ERROR');
        DBMS_OUTPUT.PUT_LINE('RCA_END');
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
        DBMS_OUTPUT.PUT_LINE('AUDIT_END');
END sp_store_orders;
/

