DECLARE
    -- [Memory & Type] [Data Synchronization]
    lv_target_industry MODERN_DATA.COMPANIES_INDUSTRIES.industry%TYPE := NULL;
    lv_founding_year   MODERN_DATA.COMPANIES_DATES.year_founded%TYPE;
    lv_other_avg_val   NUMBER;
    lv_row_counter     NUMBER := 0;
    lv_row_limit       CONSTANT NUMBER := 15;

    -- [Cursors] [Data Retrieval]
    CURSOR cur_industry_peers IS
        SELECT i.company_id, 
               i.industry, 
               f.valuation
        FROM   MODERN_DATA.COMPANIES_INDUSTRIES i
        JOIN   MODERN_DATA.COMPANIES_FUNDING f ON i.company_id = f.company_id
        WHERE  i.industry = lv_target_industry
        ORDER BY f.valuation DESC;
BEGIN
    -- [Validation] [Control Flow]
    -- Prevents silent failure when input is missing
    IF lv_target_industry IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Target industry cannot be NULL or empty.');
        RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('--- Analysis: Top ' || lv_row_limit || ' ' || lv_target_industry || ' Peer Comparisons ---');

    -- [Iterative] [Control Flow]
    FOR rec_comp IN cur_industry_peers LOOP
        lv_row_counter := lv_row_counter + 1;

        EXIT WHEN lv_row_counter > lv_row_limit;

        -- [Data Retrieval]
        SELECT year_founded 
        INTO   lv_founding_year
        FROM   MODERN_DATA.COMPANIES_DATES
        WHERE  company_id = rec_comp.company_id;

        -- [Aggregation]
        SELECT peer_val 
        INTO   lv_other_avg_val
        FROM   (SELECT AVG(f.valuation) AS peer_val
                FROM   MODERN_DATA.COMPANIES_FUNDING f
                JOIN   MODERN_DATA.COMPANIES_INDUSTRIES i ON f.company_id = i.company_id
                WHERE  i.industry = rec_comp.industry
                  AND  f.company_id <> rec_comp.company_id);

        -- [Decision Logic]
        IF rec_comp.valuation > NVL(lv_other_avg_val, 0) THEN
            DBMS_OUTPUT.PUT_LINE(lv_row_counter || '. Success: ID ' || rec_comp.company_id || ' is strictly higher than peers.');
            DBMS_OUTPUT.PUT_LINE('    Valuation: ' || rec_comp.valuation || ' | Peer Avg: ' || ROUND(lv_other_avg_val, 2));
        ELSE
            DBMS_OUTPUT.PUT_LINE(lv_row_counter || '. Status: Below Peer Average');
            DBMS_OUTPUT.PUT_LINE('    Root Cause: Deficit of ' || (NVL(lv_other_avg_val, 0) - rec_comp.valuation) || ' from Peer Avg.');
        END IF;
    END LOOP;

    -- [Root Cause Analysis]
    IF lv_row_counter = 0 THEN
        DBMS_OUTPUT.PUT_LINE('No records found for the specified industry.');
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Root Cause: Incomplete data profile for company.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

