    lv_target_industry MODERN_DATA.COMPANIES_INDUSTRIES.industry%TYPE := 'Health';
    lv_founding_year   MODERN_DATA.COMPANIES_DATES.year_founded%TYPE;
    lv_other_avg_val   NUMBER;
