CREATE OR REPLACE FUNCTION sf_get_product_price (
    p_prod_id IN NUMBER
) RETURN VARCHAR2
IS
    v_prodname VARCHAR2(100);
    v_price NUMBER;
BEGIN
    IF p_prod_id IS NULL THEN
        RETURN 'Product id NULL not found';
    END IF;

    SELECT prod_name, prod_list_price
      INTO v_prodname, v_price
      FROM complex_oracle.products
     WHERE prod_id = p_prod_id;

    RETURN 'Product ID: ' || p_prod_id || CHR(10) ||
           'Product Name: ' || v_prodname || CHR(10) ||
           'Product List price: ' || v_price;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Product ID: ' || p_prod_id || ' Data not found';
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_product_price;
/

CREATE OR REPLACE FUNCTION sf_get_delivery_info (
    p_delivery_id IN NUMBER
) RETURN VARCHAR2 IS
    v_distance delivery_center.deliveries.delivery_distance_meters%TYPE;
    v_status   delivery_center.deliveries.delivery_status%TYPE;
BEGIN
    -- Control Flow (input validation)
    IF p_delivery_id IS NULL THEN
        RETURN 'Delivery id NULL not found';
    END IF;

    -- Data Retrieval
    SELECT delivery_distance_meters, delivery_status
    INTO v_distance, v_status
    FROM delivery_center.deliveries
    WHERE delivery_id = p_delivery_id;

    -- Control Flow
    IF v_distance > 5000 THEN
        RETURN 'Delivery ID: ' || p_delivery_id || CHR(10) ||
            'Delivery Remark: Delivery is far and current status is ' || v_status;
    ELSE
        RETURN 'Delivery ID: ' ||p_delivery_id||chr(10)||
            'Delivery Remark: Delivery is nearby and current status is ' || v_status;
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Delivery ID: ' ||p_delivery_id||  '  '||'Delivery Data not found';
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_delivery_info;
/

DECLARE
    -- Parameters
    v_artist_name CONSTANT VARCHAR2(100) := 'Iron Maiden';
    v_artist_id MUSIC.ARTIST.ARTISTID%TYPE;
    v_total_albums NUMBER := 0;
    v_total_tracks NUMBER := 0;
    v_max_tracks_count NUMBER := 0;
    v_max_tracks_album MUSIC.ALBUM.TITLE%TYPE;
    v_track_count NUMBER := 0;
    v_rca_message VARCHAR2(4000);

    -- Custom exception for null artist name
    ex_no_name_found EXCEPTION;

    CURSOR cur_artist_albums IS
        SELECT a.albumid,
               a.title
        FROM   music.album a
        WHERE  a.artistid = v_artist_id
        ORDER BY a.title;
BEGIN
    -- Raise custom exception if artist name is null
    IF v_artist_name IS NULL THEN
        RAISE ex_no_name_found;
    END IF;

    DBMS_OUTPUT.PUT_LINE('=== Artist Album Performance Analysis ===');
    DBMS_OUTPUT.PUT_LINE('Artist: ' || v_artist_name);
    DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');

    -- Get artist ID
    BEGIN
        SELECT artistid
        INTO   v_artist_id
        FROM   music.artist
        WHERE  name = v_artist_name;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_rca_message := 'RCA: The artist "' || v_artist_name || '" does not exist in MUSIC.ARTIST table.';
            DBMS_OUTPUT.PUT_LINE('ERROR: Artist not found');
            DBMS_OUTPUT.PUT_LINE(v_rca_message);
            RETURN;
        WHEN TOO_MANY_ROWS THEN
            v_rca_message := 'RCA: Multiple entries exist for "' || v_artist_name || '" in MUSIC.ARTIST table. Data quality issue.';
            DBMS_OUTPUT.PUT_LINE('ERROR: Multiple artists found with same name');
            DBMS_OUTPUT.PUT_LINE(v_rca_message);
            RETURN;
    END;

    -- Process each album
    FOR rec IN cur_artist_albums LOOP
        v_total_albums := v_total_albums + 1;

        -- Inline execution: count tracks using subquery directly
        SELECT (SELECT COUNT(*) FROM music.track t WHERE t.albumid = rec.albumid)
        INTO   v_track_count
        FROM   dual;

        v_total_tracks := v_total_tracks + v_track_count;

        -- Track album with most tracks
        IF v_track_count > v_max_tracks_count THEN
            v_max_tracks_count := v_track_count;
            v_max_tracks_album := rec.title;
        END IF;
    END LOOP;

    -- Display results
    IF v_total_albums = 0 THEN
        v_rca_message := 'RCA: Artist exists but has no albums in MUSIC.ALBUM table.';
        DBMS_OUTPUT.PUT_LINE('No albums found for this artist');
        DBMS_OUTPUT.PUT_LINE(v_rca_message);
    ELSE
        DBMS_OUTPUT.PUT_LINE('Total Albums: ' || v_total_albums);
        DBMS_OUTPUT.PUT_LINE('Total Tracks: ' || v_total_tracks);
        DBMS_OUTPUT.PUT_LINE('Average Tracks per Album: ' || ROUND(v_total_tracks / v_total_albums, 2));
        DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
        DBMS_OUTPUT.PUT_LINE('Album with Most Tracks: ' || v_max_tracks_album);
        DBMS_OUTPUT.PUT_LINE('Track Count: ' || v_max_tracks_count);
        v_rca_message := 'RCA: Analysis completed successfully. Data retrieved from MUSIC.ALBUM and MUSIC.TRACK tables.';
        DBMS_OUTPUT.PUT_LINE(v_rca_message);
    END IF;

EXCEPTION
    WHEN ex_no_name_found THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: No artist name provided.');
        DBMS_OUTPUT.PUT_LINE('RCA: Parameter v_artist_name is NULL. Please provide a valid artist name.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END;

