CREATE OR REPLACE PROCEDURE sp_evaluate_sales_performance (
    p_salesperson_id IN NUMBER
) IS
    lv_region_name ADVENTUREWORKS.salesterritory.name%TYPE;
    lv_sales_ytd   ADVENTUREWORKS.salesperson.salesytd%TYPE;
    lv_sales_quota ADVENTUREWORKS.salesperson.salesquota%TYPE;
BEGIN
    -- Joining Salesperson with Territory to get Region Name. 
    -- Using Left join instead of Inner join to handle unassigned territories.
    SELECT t.name, s.salesytd, s.salesquota
    INTO lv_region_name, lv_sales_ytd, lv_sales_quota
    FROM ADVENTUREWORKS.salesperson s
    LEFT JOIN ADVENTUREWORKS.salesterritory t ON s.territoryid = t.territoryid
    WHERE s.businessentityid = p_salesperson_id;

    IF lv_region_name IS NULL THEN
        RAISE NO_DATA_FOUND;
    END IF;

    -- Evaluate Performance with Regional Context
    IF lv_sales_quota IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Info: No quota assigned for Salesperson ' || p_salesperson_id || ' (Region: ' || lv_region_name || ').');
    ELSIF lv_sales_ytd >= lv_sales_quota THEN
        DBMS_OUTPUT.PUT_LINE('Success: Salesperson ' || p_salesperson_id || ' (Region: ' || lv_region_name || ') met target. Eligible for Bonus.');
    ELSE
        DBMS_OUTPUT.PUT_LINE('Alert: Salesperson ' || p_salesperson_id || ' (Region: ' || lv_region_name || ') missed target. Review required.');
    END IF;

EXCEPTION
    -- Handle Cases when there is not data found and other exceptions
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Error: Salesperson ID ' || p_salesperson_id || ' not found or not assigned to a valid territory.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

