DECLARE
    lv_flight_id   AIRLINES.FLIGHTS.flight_id%TYPE := 563;  
    -- Local variable to store input flight id

    lv_flight_no   AIRLINES.FLIGHTS.flight_no%TYPE;         
    -- Local variable to store retrieved flight number

    lv_status      AIRLINES.FLIGHTS.status%TYPE;            
    -- Local variable to store retrieved flight status
BEGIN
    /* Validate input flight id */
    IF lv_flight_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Invalid input: Flight id cannot be NULL');
        RETURN;
    END IF;

    /* 
       Inline execution using correlated subqueries.
       Flight number and status are retrieved during execution
       without separate validation queries or cursors.
    */
    SELECT
           (SELECT f.flight_no
              FROM AIRLINES.FLIGHTS f
             WHERE f.flight_id = a.flight_id),
           (SELECT f.status
              FROM AIRLINES.FLIGHTS f
             WHERE f.flight_id = a.flight_id)
      INTO lv_flight_no,
           lv_status
      FROM AIRLINES.FLIGHTS a
     WHERE a.flight_id = lv_flight_id;

    /* Display successful retrieval message */
    DBMS_OUTPUT.PUT_LINE('Flight details retrieved successfully');
    DBMS_OUTPUT.PUT_LINE('Flight ID   : ' || lv_flight_id);
    DBMS_OUTPUT.PUT_LINE('Flight No   : ' || lv_flight_no);
    DBMS_OUTPUT.PUT_LINE('Status      : ' || lv_status);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No flight found for the given flight id');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;

