CREATE OR REPLACE FUNCTION sf_get_alien_risk (
    p_id IN NUMBER
) RETURN VARCHAR2
IS
    v_aggressive NUMBER;
    v_age        NUMBER;

BEGIN
    -- input validation
    IF p_id IS NULL THEN
        RETURN 'Alien ID NULL not found';
    END IF;

    -- Retrieve aggression level and age for the given alien ID
    SELECT aggressive, age
    INTO v_aggressive, v_age
    FROM city_legislation.alien_data
    WHERE id = p_id;

    -- Condition 1: aggressive and very old
    IF v_aggressive = 1 AND v_age > 100 THEN
        RETURN 'Alien ID: ' || p_id ||chr(10)||
               'aggression level: '||'HIGH RISK';

    -- Condition 2: aggressive but not extremely old
    ELSIF v_aggressive = 1 THEN
        RETURN 'Alien ID: ' || p_id ||chr(10)||
               'aggression level: '||'MEDIUM RISK';

    -- Condition 3: not aggressive
    ELSE
        RETURN 'Alien ID: ' || p_id ||chr(10)||
               'aggression level: '||'LOW RISK';
    END IF;

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'Alien ID ' || p_id || ' not found.';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_get_alien_risk;
/

CREATE OR REPLACE PROCEDURE sp_validate_customer_credit
(
    p_cust_id IN complex_oracle.customers.cust_id%TYPE
)
IS

    ------------------------------------------------
    -- VARIABLES
    ------------------------------------------------
    lv_customer_exists   NUMBER;
    lv_credit_limit      NUMBER;
    lv_country_name      complex_oracle.countries.country_name%TYPE;

    lv_credit_threshold  NUMBER := 2000;
    lv_credit_status     VARCHAR2(20) := 'CREDIT_OK';

BEGIN

    ------------------------------------------------
    -- INPUT VALIDATION (Control Flow)
    ------------------------------------------------
    IF p_cust_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('RCA: Customer ID is NULL not found');
        RETURN;
    END IF;

    ------------------------------------------------
    -- DATA RETRIEVAL USING INLINE SCALAR SUBQUERIES
    ------------------------------------------------
    SELECT
        /* Customer existence */
        (SELECT COUNT(*)
           FROM complex_oracle.customers c
          WHERE c.cust_id = p_cust_id),

        /* Customer credit limit */
        (SELECT NVL(c.cust_credit_limit,0)
           FROM complex_oracle.customers c
          WHERE c.cust_id = p_cust_id),

        /* Customer country */
        (SELECT co.country_name
           FROM complex_oracle.customers c
           JOIN complex_oracle.countries co
             ON c.country_id = co.country_id
          WHERE c.cust_id = p_cust_id)

    INTO
        lv_customer_exists,
        lv_credit_limit,
        lv_country_name
    FROM dual;

    DBMS_OUTPUT.PUT_LINE('RCA: Data retrieval completed successfully.');

    ------------------------------------------------
    -- ROOT CAUSE ANALYSIS DECISION LOGIC
    ------------------------------------------------
    IF lv_customer_exists = 0 THEN

        DBMS_OUTPUT.PUT_LINE('RCA: Customer ID:'||p_cust_id||' No data found');
        lv_credit_status := 'CREDIT_ISSUE';

    ELSE

        DBMS_OUTPUT.PUT_LINE('RCA: Customer exists.');
        DBMS_OUTPUT.PUT_LINE('Customer Country: ' || lv_country_name);

        IF lv_credit_limit > lv_credit_threshold THEN

            DBMS_OUTPUT.PUT_LINE('RCA: Credit limit exceeds threshold. Limit = ' || lv_credit_limit);
            lv_credit_status := 'CREDIT_OK';

        ELSE

            DBMS_OUTPUT.PUT_LINE('RCA: Credit limit is below acceptable threshold. Limit = ' || lv_credit_limit);
            lv_credit_status := 'CREDIT_ISSUE';

        END IF;

    END IF;

    ------------------------------------------------
    -- FINAL SUMMARY
    ------------------------------------------------
    DBMS_OUTPUT.PUT_LINE('Final Credit Status: ' || lv_credit_status);

------------------------------------------------
-- EXCEPTION HANDLING
------------------------------------------------
EXCEPTION

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END sp_validate_customer_credit;
/

