DECLARE
    v_order_id NUMBER := 68422076;  
    v_status   VARCHAR2(50);
    v_amount   NUMBER;

BEGIN

    /* Data Retrieval using Inline View */

    SELECT order_status, order_amount
    INTO v_status, v_amount
    FROM (
        SELECT order_id,
               order_status,
               order_amount
        FROM delivery_center.orders
    ) iv
    WHERE iv.order_id = v_order_id;

    /* Control Flow */

    IF v_status = 'FINISHED' THEN
        DBMS_OUTPUT.PUT_LINE('Order ID : ' || v_order_id);
        DBMS_OUTPUT.PUT_LINE('Order delivered successfully.');
        DBMS_OUTPUT.PUT_LINE('Order Amount: ' || v_amount);

    ELSIF v_status = 'CANCELED' THEN
        DBMS_OUTPUT.PUT_LINE('Order ID : ' || v_order_id);
        DBMS_OUTPUT.PUT_LINE('Order was cancelled.');

    ELSE
        DBMS_OUTPUT.PUT_LINE('Order ID : ' || v_order_id);
        DBMS_OUTPUT.PUT_LINE('Order is still in process.');
    END IF;

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Order ID [' || v_order_id || '] not found.');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;
/

