    lv_flight_id  AIRLINES.FLIGHTS.flight_id%TYPE := 100;
    lv_status     AIRLINES.FLIGHTS.status%TYPE;
BEGIN
    -- [Validation] [Control Flow]
    IF lv_flight_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Flight ID cannot be NULL.');
        RETURN;
    END IF;

    -- [Data Retrieval]
    -- [Inline Execution] using a subquery to isolate the flight record
    SELECT status 
    INTO   lv_status 
    FROM   (
        SELECT status 
        FROM   AIRLINES.FLIGHTS 
