        DBMS_OUTPUT.PUT_LINE('Flight ' || lv_flight_id || ' has completed its journey.');
    ELSIF lv_status = 'On Time' THEN
        DBMS_OUTPUT.PUT_LINE('Flight ' || lv_flight_id || ' is scheduled to depart as planned.');
