CREATE OR REPLACE PROCEDURE proc_get_price_snapshot (
    p_ticker      IN BANK_SALES_TRADING.BITCOIN_PRICES.TICKER%TYPE,
    p_market_date IN VARCHAR2
) IS
    /* Business exceptions */
    e_invalid_input EXCEPTION;
    e_no_data       EXCEPTION;

    /* Variables to hold prices */
    v_open_price BANK_SALES_TRADING.BITCOIN_PRICES.OPEN%TYPE;
    v_high_price BANK_SALES_TRADING.BITCOIN_PRICES.HIGH%TYPE;
    v_low_price  BANK_SALES_TRADING.BITCOIN_PRICES.LOW%TYPE;
BEGIN
    /* Input validation */
    IF p_ticker IS NULL OR p_market_date IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Invalid input parameters passed!');
        RETURN;
    END IF;

    /* Fetch price snapshot */
    SELECT
        bp.open,
        bp.high,
        bp.low
    INTO
        v_open_price,
        v_high_price,
        v_low_price
    FROM BANK_SALES_TRADING.BITCOIN_PRICES bp
    WHERE UPPER(bp.ticker) = UPPER(p_ticker)
      AND bp.market_date = to_date(p_market_date,'dd/mm/yyyy');

    /* Output */
    DBMS_OUTPUT.PUT_LINE('Ticker       : ' || p_ticker);
    DBMS_OUTPUT.PUT_LINE('Market Date  : ' || p_market_date);
    DBMS_OUTPUT.PUT_LINE('Open Price   : ' || v_open_price);
    DBMS_OUTPUT.PUT_LINE('High Price   : ' || v_high_price);
    DBMS_OUTPUT.PUT_LINE('Low Price    : ' || v_low_price);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE(
            'ERROR: No price data found for ticker '
            || p_ticker || ' on ' || p_market_date
        );

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error: ' );
END;
/

