DECLARE
    p_max_rows   NUMBER := 20;           -- Controls review scope
    p_risk_focus VARCHAR2(10) := 'ALL';  -- ALL / HIGH / MEDIUM / LOW

    /*=========================================================
      Cursor definition
    =========================================================*/
    CURSOR cur_alien_behavior IS
       SELECT
           x.first_name,
           x.last_name,
           x.feeding_frequency,
           x.aggressive
    FROM (  SELECT
               a.first_name,
               a.last_name,
               d.feeding_frequency,
               d.aggressive
          FROM CITY_LEGISLATION.ALIENS a
          JOIN CITY_LEGISLATION.ALIENS_DETAILS d
            ON a.id = d.detail_id
         ORDER BY a.first_name, a.last_name)x
         FETCH FIRST p_max_rows ROWS ONLY;

    /*=========================================================
      Risk counters
    =========================================================*/
    lv_total_count  NUMBER := 0;
    lv_high_risk    NUMBER := 0;
    lv_medium_risk  NUMBER := 0;
    lv_low_risk     NUMBER := 0;
    lv_restriction  BOOLEAN := FALSE;

BEGIN
    /*=========================================================
      RCA -- Input Parameter Validation
    =========================================================*/
    IF p_max_rows IS NULL OR p_max_rows <= 0 THEN
    DBMS_OUTPUT.PUT_LINE('ERROR: Invalid maximum row limit provided.');
    DBMS_OUTPUT.PUT_LINE('RCA Note: Input parameter p_max_rows must be a positive number to '
        || 'define a valid compliance review scope.');
    RETURN;
END IF;

    IF p_risk_focus NOT IN ('ALL', 'HIGH', 'MEDIUM', 'LOW') THEN
    DBMS_OUTPUT.PUT_LINE('ERROR: Invalid risk focus value provided.');
    DBMS_OUTPUT.PUT_LINE('RCA Note: Input parameter p_risk_focus received an unsupported value.');
    DBMS_OUTPUT.PUT_LINE('Allowed values are ALL, HIGH, MEDIUM, or LOW to align with compliance risk classifications.');
        RETURN;
    END IF;

    /*=========================================================
      Core compliance assessment
    =========================================================*/
    FOR rec IN cur_alien_behavior LOOP
        lv_total_count := lv_total_count + 1;

        IF rec.aggressive = 1
           AND rec.feeding_frequency IN ('Daily','Often','Weekly','Monthly') THEN

            lv_high_risk := lv_high_risk + 1;

            IF p_risk_focus IN ('ALL','HIGH') THEN
                DBMS_OUTPUT.PUT_LINE(
                    'HIGH RISK | ' || rec.first_name || ' ' || rec.last_name
                );
            END IF;

        ELSIF rec.aggressive = 1 THEN
            lv_medium_risk := lv_medium_risk + 1;

            IF p_risk_focus IN ('ALL','MEDIUM') THEN
                DBMS_OUTPUT.PUT_LINE(
                    'MEDIUM RISK | ' || rec.first_name || ' ' || rec.last_name
                );
            END IF;

        ELSE
            lv_low_risk := lv_low_risk + 1;

            IF p_risk_focus IN ('ALL','LOW') THEN
                DBMS_OUTPUT.PUT_LINE(
                    'LOW RISK | ' || rec.first_name || ' ' || rec.last_name
                );
            END IF;
        END IF;
    END LOOP;

    /*=========================================================
      RCA -- Outcome Analysis (Input-driven, not error-driven)
    =========================================================*/
    IF lv_total_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE(
            'RCA Note: No alien records matched the review scope defined by input parameters.'
        );
    END IF;

    IF lv_high_risk = 0 AND p_risk_focus IN ('ALL','HIGH') THEN
        DBMS_OUTPUT.PUT_LINE(
            'RCA Note: No high-risk behavioral patterns detected within the evaluated population.'
        );
    END IF;

    IF p_risk_focus <> 'ALL' AND lv_total_count > 0 THEN
        IF (p_risk_focus = 'HIGH' AND (lv_medium_risk + lv_low_risk) > 0)
           OR (p_risk_focus = 'MEDIUM' AND (lv_high_risk + lv_low_risk) > 0)
           OR (p_risk_focus = 'LOW' AND (lv_high_risk + lv_medium_risk) > 0) THEN
            lv_restriction := TRUE;
        END IF;

        IF lv_restriction THEN
            DBMS_OUTPUT.PUT_LINE(
                'RCA Note: Output restricted by risk focus parameter ('
                || p_risk_focus || '), not by data absence.'
            );
        END IF;
    END IF;

    /*=========================================================
      Summary
    =========================================================*/
    DBMS_OUTPUT.PUT_LINE('------------------------------------------');
    DBMS_OUTPUT.PUT_LINE('Total Reviewed : ' || lv_total_count);
    DBMS_OUTPUT.PUT_LINE('High Risk      : ' || lv_high_risk);
    DBMS_OUTPUT.PUT_LINE('Medium Risk    : ' || lv_medium_risk);
    DBMS_OUTPUT.PUT_LINE('Low Risk       : ' || lv_low_risk);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE(
            'Unexpected error occurred'
        );
END;
/

