CREATE OR REPLACE PROCEDURE sp_validate_track_sales
(
    p_track_id IN music.track.trackid%TYPE
)
IS

------------------------------------------------
-- VARIABLES
------------------------------------------------
lv_track_exists   NUMBER := 0;
lv_track_name     music.track.name%TYPE;
lv_total_quantity NUMBER := 0;
lv_unit_price     music.track.unitprice%TYPE;

lv_sales_status   VARCHAR2(30) := 'SALES_OK';

BEGIN

------------------------------------------------
-- CONTROL FLOW : INPUT VALIDATION
------------------------------------------------
IF p_track_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('RCA: Track ID is NULL not found');
    RETURN;
END IF;

------------------------------------------------
-- DATA RETRIEVAL : CHECK TRACK EXISTENCE
------------------------------------------------
SELECT COUNT(*)
INTO lv_track_exists
FROM music.track
WHERE trackid = p_track_id;

------------------------------------------------
-- ROOT CAUSE ANALYSIS : TRACK EXISTENCE
------------------------------------------------
IF lv_track_exists = 0 THEN

    DBMS_OUTPUT.PUT_LINE('RCA: Track ID '||p_track_id||' no data found');
    lv_sales_status := 'SALES_ISSUE';

ELSE

------------------------------------------------
-- DATA RETRIEVAL : TRACK DETAILS
------------------------------------------------
    SELECT name, unitprice
    INTO lv_track_name, lv_unit_price
    FROM music.track
    WHERE trackid = p_track_id;

    DBMS_OUTPUT.PUT_LINE('RCA: Track exists.');
    DBMS_OUTPUT.PUT_LINE('Track Name: ' || lv_track_name);

------------------------------------------------
-- DATA RETRIEVAL : SALES QUANTITY
------------------------------------------------
    SELECT NVL(SUM(quantity),0)
    INTO lv_total_quantity
    FROM music.invoiceline
    WHERE trackid = p_track_id;

------------------------------------------------
-- ROOT CAUSE ANALYSIS : SALES CHECK
------------------------------------------------
    IF lv_total_quantity = 0 THEN

        DBMS_OUTPUT.PUT_LINE('RCA: Track exists but no sales found.');
        lv_sales_status := 'SALES_ISSUE';

    ELSE

        DBMS_OUTPUT.PUT_LINE('RCA: Track has sales.');
        DBMS_OUTPUT.PUT_LINE('Total Quantity Sold: ' || lv_total_quantity);
        DBMS_OUTPUT.PUT_LINE('Unit Price: ' || lv_unit_price);

        lv_sales_status := 'SALES_OK';

    END IF;

END IF;

------------------------------------------------
-- FINAL RESULT
------------------------------------------------
DBMS_OUTPUT.PUT_LINE('Final Sales Status: ' || lv_sales_status);

------------------------------------------------
-- EXCEPTION HANDLING
------------------------------------------------
EXCEPTION

WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('RCA: Track data not found.');

WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END sp_validate_track_sales;
/

