DECLARE
    -- Parameter for optional flight number filter (NULL = analyze all flights)
    p_flight_no VARCHAR2(100) := 'PG0402';  -- Change this to test: NULL, valid flight number, or invalid flight number

    -- Variables for flight analysis
    lv_flight_id AIRLINES.FLIGHTS.FLIGHT_ID%TYPE;
    lv_flight_no AIRLINES.FLIGHTS.FLIGHT_NO%TYPE;
    lv_departure_airport AIRLINES.FLIGHTS.DEPARTURE_AIRPORT%TYPE;
    lv_arrival_airport AIRLINES.FLIGHTS.ARRIVAL_AIRPORT%TYPE;
    lv_aircraft_code AIRLINES.FLIGHTS.AIRCRAFT_CODE%TYPE;
    lv_status AIRLINES.FLIGHTS.STATUS%TYPE;
    lv_departure_city AIRLINES.AIRPORTS_DATA.CITY%TYPE;
    lv_arrival_city AIRLINES.AIRPORTS_DATA.CITY%TYPE;
    lv_aircraft_model AIRLINES.AIRCRAFTS_DATA.MODEL%TYPE;

    -- Variables for delay calculations
    lv_departure_delay NUMBER := 0;
    lv_arrival_delay NUMBER := 0;
    lv_total_delay NUMBER := 0;
    lv_performance_rating VARCHAR2(20);

    -- Variables for statistics
    lv_total_flights NUMBER := 0;
    lv_delayed_flights NUMBER := 0;
    lv_on_time_flights NUMBER := 0;
    lv_cancelled_flights NUMBER := 0;
    lv_avg_delay NUMBER := 0;
    lv_processed_count NUMBER := 0;

    -- Variables for flight number validation
    lv_flight_exists NUMBER := 0;

    -- Thresholds for performance categorization
    lv_threshold_minor NUMBER := 15;  -- minutes
    lv_threshold_major NUMBER := 60;  -- minutes

    -- Exception handling variables
    lv_error_context VARCHAR2(500);

    -- Custom exceptions
    e_no_flights_found EXCEPTION;
    e_invalid_delay_calc EXCEPTION;
    e_data_quality_issue EXCEPTION;
    e_null_flight_number EXCEPTION;
    e_invalid_flight_number EXCEPTION;

BEGIN
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('FLIGHT PERFORMANCE ANALYSIS');
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('Analysis Start: ' );
    DBMS_OUTPUT.PUT_LINE('');

    -- Validate flight number parameter
    IF p_flight_no IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('ERROR: Flight number should not be NULL');
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('INSTRUCTIONS:');
        DBMS_OUTPUT.PUT_LINE('  - Please provide a valid flight number');
        DBMS_OUTPUT.PUT_LINE('  - Example: p_flight_no := ''PG0001'';');
        DBMS_OUTPUT.PUT_LINE('========================================');
        RAISE e_null_flight_number;
    END IF;

    -- Check if flight number exists in database
    BEGIN
        SELECT COUNT(*)
        INTO lv_flight_exists
        FROM AIRLINES.FLIGHTS
        WHERE FLIGHT_NO = p_flight_no
        AND ROWNUM = 1;

        IF lv_flight_exists = 0 THEN
            DBMS_OUTPUT.PUT_LINE('ERROR: Invalid flight number');
            DBMS_OUTPUT.PUT_LINE('Flight Number Provided: ' || p_flight_no);
            DBMS_OUTPUT.PUT_LINE('');
            DBMS_OUTPUT.PUT_LINE('ROOT CAUSE ANALYSIS:');
            DBMS_OUTPUT.PUT_LINE('  - The flight number "' || p_flight_no || '" does not exist in the database');
            DBMS_OUTPUT.PUT_LINE('  - Please verify the flight number and try again');
            DBMS_OUTPUT.PUT_LINE('========================================');
            RAISE e_invalid_flight_number;
        END IF;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('ERROR: Invalid flight number');
            DBMS_OUTPUT.PUT_LINE('Flight Number Provided: ' || p_flight_no);
            DBMS_OUTPUT.PUT_LINE('========================================');
            RAISE e_invalid_flight_number;
    END;

    -- Display filter information
    DBMS_OUTPUT.PUT_LINE('Filter: Flight Number = ' || p_flight_no);
    DBMS_OUTPUT.PUT_LINE('');

    -- Phase 1: Retrieve Overall Statistics
    DBMS_OUTPUT.PUT_LINE('PHASE 1: RETRIEVING FLIGHT STATISTICS');
    DBMS_OUTPUT.PUT_LINE('--------------------------------------');

    BEGIN
        SELECT COUNT(*) 
        INTO lv_total_flights
        FROM AIRLINES.FLIGHTS
        WHERE FLIGHT_NO = p_flight_no;

        IF lv_total_flights = 0 THEN
            RAISE e_no_flights_found;
        END IF;

        DBMS_OUTPUT.PUT_LINE('Total Flights to Analyze: ' || lv_total_flights);

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            lv_error_context := 'No flight data available for flight number: ' || p_flight_no;
            DBMS_OUTPUT.PUT_LINE('ERROR: ' || lv_error_context);
            DBMS_OUTPUT.PUT_LINE('ROOT CAUSE: No matching flights found');
            RAISE e_no_flights_found;
    END;

    DBMS_OUTPUT.PUT_LINE('');
    DBMS_OUTPUT.PUT_LINE('PHASE 2: ANALYZING INDIVIDUAL FLIGHTS');
    DBMS_OUTPUT.PUT_LINE('--------------------------------------');

    -- Phase 2: Analyze Individual Flights
    FOR flight_rec IN (
        SELECT 
            f.flight_id,
            f.flight_no,
            f.departure_airport,
            f.arrival_airport,
            f.aircraft_code,
            f.status,
            f.scheduled_departure,
            f.actual_departure,
            f.scheduled_arrival,
            f.actual_arrival,
            dep_apt.city AS departure_city,
            arr_apt.city AS arrival_city,
            ac.model AS aircraft_model
        FROM AIRLINES.FLIGHTS f
        LEFT JOIN AIRLINES.AIRPORTS_DATA dep_apt ON f.departure_airport = dep_apt.airport_code
        LEFT JOIN AIRLINES.AIRPORTS_DATA arr_apt ON f.arrival_airport = arr_apt.airport_code
        LEFT JOIN AIRLINES.AIRCRAFTS_DATA ac ON f.aircraft_code = ac.aircraft_code
        WHERE f.FLIGHT_NO = p_flight_no
        AND f.status 
        IN (
                    SELECT 'Arrived'   FROM dual
                    UNION
                    SELECT 'Scheduled' FROM dual
                    UNION
                    SELECT 'On Time'   FROM dual
                    UNION
                    SELECT 'Delayed'   FROM dual
                    UNION
                    SELECT 'Cancelled' FROM dual
                    UNION
                    SELECT 'Departed'  FROM dual
                ) -- Subquery to only use the status which is specified here
        ORDER BY f.flight_id
    ) LOOP
        BEGIN
            -- Reset variables for each flight
            lv_flight_id := flight_rec.flight_id;
            lv_flight_no := flight_rec.flight_no;
            lv_departure_airport := flight_rec.departure_airport;
            lv_arrival_airport := flight_rec.arrival_airport;
            lv_aircraft_code := flight_rec.aircraft_code;
            lv_status := flight_rec.status;
            lv_departure_city := flight_rec.departure_city;
            lv_arrival_city := flight_rec.arrival_city;
            lv_aircraft_model := flight_rec.aircraft_model;
            lv_departure_delay := 0;
            lv_arrival_delay := 0;
            lv_total_delay := 0;
            lv_performance_rating := 'UNKNOWN';

            -- Calculate departure delay (in minutes)
            IF flight_rec.actual_departure IS NOT NULL AND flight_rec.scheduled_departure IS NOT NULL THEN
                BEGIN
                    -- Using EXTRACT to handle INTERVAL DAY TO SECOND
                    lv_departure_delay := 
                        EXTRACT(DAY FROM (flight_rec.actual_departure - flight_rec.scheduled_departure)) * 24 * 60
                        + EXTRACT(HOUR FROM (flight_rec.actual_departure - flight_rec.scheduled_departure)) * 60
                        + EXTRACT(MINUTE FROM (flight_rec.actual_departure - flight_rec.scheduled_departure));
                EXCEPTION
                    WHEN OTHERS THEN
                        -- Fallback: Convert to DATE first, then calculate
                        lv_departure_delay := 
                            ROUND((CAST(flight_rec.actual_departure AS DATE) - 
                                   CAST(flight_rec.scheduled_departure AS DATE)) * 24 * 60, 0);
                END;
            END IF;

            -- Calculate arrival delay (in minutes)
            IF flight_rec.actual_arrival IS NOT NULL AND flight_rec.scheduled_arrival IS NOT NULL THEN
                BEGIN
                    -- Using EXTRACT to handle INTERVAL DAY TO SECOND
                    lv_arrival_delay := 
                        EXTRACT(DAY FROM (flight_rec.actual_arrival - flight_rec.scheduled_arrival)) * 24 * 60
                        + EXTRACT(HOUR FROM (flight_rec.actual_arrival - flight_rec.scheduled_arrival)) * 60
                        + EXTRACT(MINUTE FROM (flight_rec.actual_arrival - flight_rec.scheduled_arrival));
                EXCEPTION
                    WHEN OTHERS THEN
                        -- Fallback: Convert to DATE first, then calculate
                        lv_arrival_delay := 
                            ROUND((CAST(flight_rec.actual_arrival AS DATE) - 
                                   CAST(flight_rec.scheduled_arrival AS DATE)) * 24 * 60, 0);
                END;
            END IF;

            -- Calculate total delay
            lv_total_delay := lv_departure_delay + lv_arrival_delay;

            -- Validate delay calculations
            IF lv_total_delay < -1440 OR lv_total_delay > 1440 THEN
                RAISE e_invalid_delay_calc;
            END IF;

            -- Categorize flight performance
            IF lv_status = 'Cancelled' THEN
                lv_performance_rating := 'CANCELLED';
                lv_cancelled_flights := lv_cancelled_flights + 1;
            ELSIF lv_status = 'Scheduled' THEN
                lv_performance_rating := 'SCHEDULED';
            ELSIF lv_total_delay <= 0 THEN
                lv_performance_rating := 'ON TIME';
                lv_on_time_flights := lv_on_time_flights + 1;
            ELSIF lv_total_delay > 0 AND lv_total_delay <= lv_threshold_minor THEN
                lv_performance_rating := 'MINOR DELAY';
                lv_delayed_flights := lv_delayed_flights + 1;
            ELSIF lv_total_delay > lv_threshold_minor AND lv_total_delay <= lv_threshold_major THEN
                lv_performance_rating := 'MODERATE DELAY';
                lv_delayed_flights := lv_delayed_flights + 1;
            ELSIF lv_total_delay > lv_threshold_major THEN
                lv_performance_rating := 'MAJOR DELAY';
                lv_delayed_flights := lv_delayed_flights + 1;
            ELSE
                lv_performance_rating := 'UNDETERMINED';
            END IF;

            -- Output flight analysis
            DBMS_OUTPUT.PUT_LINE('');
            DBMS_OUTPUT.PUT_LINE('Flight: ' || NVL(lv_flight_no, 'Unknown'));
            DBMS_OUTPUT.PUT_LINE('  Flight ID: ' || lv_flight_id);
            DBMS_OUTPUT.PUT_LINE('  Route: ' || NVL(lv_departure_city, lv_departure_airport) || 
                                ' -> ' || NVL(lv_arrival_city, lv_arrival_airport));
            DBMS_OUTPUT.PUT_LINE('  Aircraft: ' || NVL(lv_aircraft_model, lv_aircraft_code));
            DBMS_OUTPUT.PUT_LINE('  Status: ' || NVL(lv_status, 'Unknown'));
            DBMS_OUTPUT.PUT_LINE('  Departure Delay: ' || lv_departure_delay || ' min');
            DBMS_OUTPUT.PUT_LINE('  Arrival Delay: ' || lv_arrival_delay || ' min');
            DBMS_OUTPUT.PUT_LINE('  Total Delay: ' || lv_total_delay || ' min');
            DBMS_OUTPUT.PUT_LINE('  Performance Rating: ' || lv_performance_rating);

            -- Provide recommendations
            CASE lv_performance_rating
                WHEN 'MAJOR DELAY' THEN
                    DBMS_OUTPUT.PUT_LINE('  ** RECOMMENDATION: Investigate operational issues');
                    DBMS_OUTPUT.PUT_LINE('  ** ROOT CAUSE: Potential scheduling or operational problems');
                WHEN 'MODERATE DELAY' THEN
                    DBMS_OUTPUT.PUT_LINE('  * NOTE: Monitor for recurring patterns');
                WHEN 'ON TIME' THEN
                    DBMS_OUTPUT.PUT_LINE('  + EXCELLENT: Flight operated on schedule');
                WHEN 'CANCELLED' THEN
                    DBMS_OUTPUT.PUT_LINE('  !! ALERT: Flight cancelled - review reason');
                WHEN 'SCHEDULED' THEN
                    DBMS_OUTPUT.PUT_LINE('  - INFO: Flight not yet departed');
                ELSE
                    NULL;
            END CASE;

            lv_processed_count := lv_processed_count + 1;

        EXCEPTION
            WHEN e_invalid_delay_calc THEN
                lv_error_context := 'Invalid delay calculation for Flight ID: ' || lv_flight_id;
                DBMS_OUTPUT.PUT_LINE('  ERROR: ' || lv_error_context);
                DBMS_OUTPUT.PUT_LINE('  ROOT CAUSE: Timestamp data may be corrupted or illogical');
                DBMS_OUTPUT.PUT_LINE('  DEPARTURE DELAY: ' || lv_departure_delay || ' min');
                DBMS_OUTPUT.PUT_LINE('  ARRIVAL DELAY: ' || lv_arrival_delay || ' min');
                lv_processed_count := lv_processed_count + 1;
            WHEN VALUE_ERROR THEN
                lv_error_context := 'Data type conversion error for Flight ID: ' || lv_flight_id;
                DBMS_OUTPUT.PUT_LINE('  ERROR: ' || lv_error_context);
                DBMS_OUTPUT.PUT_LINE('  ROOT CAUSE: Invalid timestamp or numeric data in flight record');
                DBMS_OUTPUT.PUT_LINE('  SQLCODE: ' || SQLCODE);
                lv_processed_count := lv_processed_count + 1;
            WHEN OTHERS THEN
                DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
                lv_processed_count := lv_processed_count + 1;
        END;
    END LOOP;

    -- Phase 3: Summary Statistics
    DBMS_OUTPUT.PUT_LINE('');
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('SUMMARY STATISTICS');
    DBMS_OUTPUT.PUT_LINE('========================================');

    BEGIN
        -- Calculate average delay with proper INTERVAL handling
        BEGIN
            SELECT NVL(AVG(
                       CASE 
                           WHEN actual_arrival IS NOT NULL AND scheduled_arrival IS NOT NULL THEN
                               EXTRACT(DAY FROM (actual_arrival - scheduled_arrival)) * 24 * 60
                               + EXTRACT(HOUR FROM (actual_arrival - scheduled_arrival)) * 60
                               + EXTRACT(MINUTE FROM (actual_arrival - scheduled_arrival))
                           ELSE 0
                       END
                   ), 0)
            INTO lv_avg_delay
            FROM AIRLINES.FLIGHTS
            WHERE status IN ('Arrived', 'Departed')
            AND FLIGHT_NO = p_flight_no;
        EXCEPTION
            WHEN OTHERS THEN
                -- Fallback: Use DATE casting
                SELECT NVL(AVG(
                           CASE 
                               WHEN actual_arrival IS NOT NULL AND scheduled_arrival IS NOT NULL THEN
                                   (CAST(actual_arrival AS DATE) - CAST(scheduled_arrival AS DATE)) * 24 * 60
                               ELSE 0
                           END
                       ), 0)
                INTO lv_avg_delay
                FROM AIRLINES.FLIGHTS
                WHERE status IN ('Arrived', 'Departed')
                AND FLIGHT_NO = p_flight_no;
        END;

        DBMS_OUTPUT.PUT_LINE('Total Flights Analyzed: ' || lv_processed_count);
        DBMS_OUTPUT.PUT_LINE('On-Time Flights: ' || lv_on_time_flights || 
                            ' (' || ROUND(CASE WHEN lv_processed_count > 0 THEN (lv_on_time_flights / lv_processed_count) * 100 ELSE 0 END, 1) || '%)');
        DBMS_OUTPUT.PUT_LINE('Delayed Flights: ' || lv_delayed_flights || 
                            ' (' || ROUND(CASE WHEN lv_processed_count > 0 THEN (lv_delayed_flights / lv_processed_count) * 100 ELSE 0 END, 1) || '%)');
        DBMS_OUTPUT.PUT_LINE('Cancelled Flights: ' || lv_cancelled_flights);
        DBMS_OUTPUT.PUT_LINE('Average Delay: ' || ROUND(lv_avg_delay, 2) || ' minutes');

    EXCEPTION
        WHEN ZERO_DIVIDE THEN
            lv_error_context := 'Division by zero in percentage calculations';
            DBMS_OUTPUT.PUT_LINE('ERROR: ' || lv_error_context);
            DBMS_OUTPUT.PUT_LINE('ROOT CAUSE: No flights were successfully processed');
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
    END;

    -- Final Assessment
    DBMS_OUTPUT.PUT_LINE('');
    DBMS_OUTPUT.PUT_LINE('OVERALL ASSESSMENT:');
    DBMS_OUTPUT.PUT_LINE('-------------------');

    IF lv_processed_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('WARNING: No flights were successfully analyzed');
        DBMS_OUTPUT.PUT_LINE('ROOT CAUSE: Check data availability and quality');
        RAISE e_no_flights_found;
    ELSIF lv_delayed_flights > (lv_processed_count * 0.5) THEN
        DBMS_OUTPUT.PUT_LINE('ALERT: More than 50% of flights experienced delays');
        DBMS_OUTPUT.PUT_LINE('RECOMMENDATION: Investigate systemic operational issues');
    ELSIF lv_on_time_flights > (lv_processed_count * 0.8) THEN
        DBMS_OUTPUT.PUT_LINE('EXCELLENT: Over 80% on-time performance');
    ELSE
        DBMS_OUTPUT.PUT_LINE('ACCEPTABLE: Performance within normal parameters');
    END IF;

    DBMS_OUTPUT.PUT_LINE('');
    DBMS_OUTPUT.PUT_LINE('Analysis End: ');
    DBMS_OUTPUT.PUT_LINE('========================================');

EXCEPTION
    WHEN e_null_flight_number THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('EXECUTION TERMINATED: NULL FLIGHT NUMBER');
        DBMS_OUTPUT.PUT_LINE('========================================');

    WHEN e_invalid_flight_number THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('EXECUTION TERMINATED: INVALID FLIGHT NUMBER');
        DBMS_OUTPUT.PUT_LINE('========================================');

    WHEN e_no_flights_found THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('CRITICAL ERROR: NO FLIGHTS FOUND');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('ROOT CAUSE ANALYSIS:');
        DBMS_OUTPUT.PUT_LINE('  1. No flights match the filter criteria');
        DBMS_OUTPUT.PUT_LINE('  2. Flight number "' || p_flight_no || '" exists but has no records');
        DBMS_OUTPUT.PUT_LINE('  3. Database connection may be restricted');
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('RECOMMENDATIONS:');
        DBMS_OUTPUT.PUT_LINE('  - Verify flight number has associated records');
        DBMS_OUTPUT.PUT_LINE('  - Check database connectivity');
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('SQLCODE: ' || SQLCODE);

    WHEN e_data_quality_issue THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('CRITICAL ERROR: DATA QUALITY ISSUE');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('ROOT CAUSE ANALYSIS:');
        DBMS_OUTPUT.PUT_LINE('  1. Invalid or corrupted data in source tables');
        DBMS_OUTPUT.PUT_LINE('  2. Data integrity constraints violated');
        DBMS_OUTPUT.PUT_LINE('  3. Timestamp fields contain invalid values');
        DBMS_OUTPUT.PUT_LINE('  4. Foreign key relationships broken');

    WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('ERROR: VALUE ERROR');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('ROOT CAUSE ANALYSIS:');
        DBMS_OUTPUT.PUT_LINE('  1. Variable size mismatch');
        DBMS_OUTPUT.PUT_LINE('  2. Invalid data type conversion');
        DBMS_OUTPUT.PUT_LINE('  3. NULL value handling issue');
        DBMS_OUTPUT.PUT_LINE('  4. Timestamp arithmetic overflow');
        DBMS_OUTPUT.PUT_LINE('Context: ' || NVL(lv_error_context, 'General execution'));
        DBMS_OUTPUT.PUT_LINE('SQLCODE: ' || SQLCODE);

    WHEN ZERO_DIVIDE THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('ERROR: DIVISION BY ZERO');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('ROOT CAUSE ANALYSIS:');
        DBMS_OUTPUT.PUT_LINE('  1. No flights available for percentage calculation');
        DBMS_OUTPUT.PUT_LINE('  2. Counter variables not incremented properly');
        DBMS_OUTPUT.PUT_LINE('  3. NULLIF protection failed unexpectedly');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');

END;
