        WHEN NO_DATA_FOUND THEN
            lv_error_context := 'No flight data available for flight number: ' || p_flight_no;
            DBMS_OUTPUT.PUT_LINE('ERROR: ' || lv_error_context);
            DBMS_OUTPUT.PUT_LINE('ROOT CAUSE: No matching flights found');
            RAISE e_no_flights_found;
    END;
    DBMS_OUTPUT.PUT_LINE('');
    DBMS_OUTPUT.PUT_LINE('PHASE 2: ANALYZING INDIVIDUAL FLIGHTS');
