                DBMS_OUTPUT.PUT_LINE('  ERROR: ' || lv_error_context);
                DBMS_OUTPUT.PUT_LINE('  ROOT CAUSE: Invalid timestamp or numeric data in flight record');
                DBMS_OUTPUT.PUT_LINE('  SQLCODE: ' || SQLCODE);
