    BEGIN
        BEGIN
            SELECT NVL(AVG(
                       CASE 
                           WHEN actual_arrival IS NOT NULL AND scheduled_arrival IS NOT NULL THEN
                               EXTRACT(DAY FROM (actual_arrival - scheduled_arrival)) * 24 * 60
                               + EXTRACT(HOUR FROM (actual_arrival - scheduled_arrival)) * 60
                               + EXTRACT(MINUTE FROM (actual_arrival - scheduled_arrival))
                           ELSE 0
                       END
                   ), 0)
            INTO lv_avg_delay
            FROM AIRLINES.FLIGHTS
            WHERE status IN ('Arrived', 'Departed')
            AND FLIGHT_NO = p_flight_no
            AND ROWNUM <= 100;
        EXCEPTION
            WHEN OTHERS THEN
                -- Fallback: Use DATE casting
                SELECT NVL(AVG(
                           CASE 
                               WHEN actual_arrival IS NOT NULL AND scheduled_arrival IS NOT NULL THEN
                                   (CAST(actual_arrival AS DATE) - CAST(scheduled_arrival AS DATE)) * 24 * 60
                               ELSE 0
                           END
                       ), 0)
                INTO lv_avg_delay
                FROM AIRLINES.FLIGHTS
                WHERE status IN ('Arrived', 'Departed')
                AND FLIGHT_NO = p_flight_no
                AND ROWNUM <= 100;
        END;
        DBMS_OUTPUT.PUT_LINE('Total Flights Analyzed: ' || lv_processed_count);
        IF lv_processed_count > 0 THEN
            DBMS_OUTPUT.PUT_LINE('On-Time Flights: ' || lv_on_time_flights || 
                                ' (' || ROUND((lv_on_time_flights / lv_processed_count) * 100, 1) || '%)');
            DBMS_OUTPUT.PUT_LINE('Delayed Flights: ' || lv_delayed_flights || 
                                ' (' || ROUND((lv_delayed_flights / lv_processed_count) * 100, 1) || '%)');
            DBMS_OUTPUT.PUT_LINE('Cancelled Flights: ' || lv_cancelled_flights);
            DBMS_OUTPUT.PUT_LINE('Average Delay: ' || ROUND(lv_avg_delay, 2) || ' minutes');
        ELSE
            DBMS_OUTPUT.PUT_LINE('No flights were processed for statistical analysis');
        END IF;
    EXCEPTION
        WHEN ZERO_DIVIDE THEN
            lv_error_context := 'Division by zero in percentage calculations';
            DBMS_OUTPUT.PUT_LINE('ERROR: ' || lv_error_context);
            DBMS_OUTPUT.PUT_LINE('ROOT CAUSE: No flights were successfully processed');
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
    END;
