            lv_arrival_city := flight_rec.arrival_city;
            lv_aircraft_model := flight_rec.aircraft_model;
            lv_departure_delay := 0;
            lv_arrival_delay := 0;
            lv_total_delay := 0;
            lv_performance_rating := 'UNKNOWN';
