CREATE OR REPLACE FUNCTION sf_get_customer_email (
    p_customer_id IN NUMBER
) RETURN VARCHAR2
IS

    v_name  VARCHAR2(70);
    v_email VARCHAR2(60);

BEGIN

    IF p_customer_id IS NULL THEN
        RETURN 'Customer ID NULL not found';
    END IF;

    -- Data Retrieval
    SELECT firstname || ' ' || lastname, email
    INTO v_name, v_email
    FROM chinook.customers
    WHERE customerid = p_customer_id;

    -- Control Flow
    IF v_email IS NULL THEN
        RETURN 'Customer ID: ' || p_customer_id || CHR(10) ||
               'Customer: ' || v_name || CHR(10) ||
               'EMAIL Status: EMAIL NOT AVAILABLE';
    ELSE
        RETURN 'Customer ID: ' || p_customer_id || CHR(10) ||
               'Customer: ' || v_name ||chr(10)||
               'EMAIL Status:'||' is having email as : ' || v_email;
    END IF;

-- Exception Handling
EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'Customer ID: ' || p_customer_id || ' Data not found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_get_customer_email;
/

CREATE OR REPLACE PROCEDURE sp_station_trip_summary (
    p_station_id IN AUSTIN_BIKESHARE.BIKESHARE_STATIONS.STATION_ID%TYPE
)
IS
    ------------------------------------------------------------------
    -- Local variables
    ------------------------------------------------------------------
    lv_station_name    AUSTIN_BIKESHARE.BIKESHARE_STATIONS.NAME%TYPE;
    lv_status          AUSTIN_BIKESHARE.BIKESHARE_STATIONS.STATUS%TYPE;
    lv_total_trips     NUMBER := 0;
    lv_total_duration  NUMBER := 0;

BEGIN
    ------------------------------------------------------------------
    -- Step 1: Validate input
    ------------------------------------------------------------------
    IF p_station_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Station ID cannot be NULL.');
        RETURN;
    END IF;

    ------------------------------------------------------------------
    -- Step 2: Confirm station exists and retrieve details
    ------------------------------------------------------------------
    BEGIN
        SELECT NAME, STATUS
        INTO lv_station_name, lv_status
        FROM AUSTIN_BIKESHARE.BIKESHARE_STATIONS
        WHERE STATION_ID = p_station_id;

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('Station does not exist.');
            RETURN;
    END;

    ------------------------------------------------------------------
    -- Step 3: Check station status
    ------------------------------------------------------------------
    IF lv_status <> 'active' THEN
        DBMS_OUTPUT.PUT_LINE('Station exists but is not active.');
        RETURN;
    END IF;

    ------------------------------------------------------------------
    -- Step 4: Retrieve trip summary
    ------------------------------------------------------------------
    SELECT COUNT(*),
           NVL(SUM(TO_NUMBER(DURATION_MINUTES)), 0)
    INTO lv_total_trips,
         lv_total_duration
    FROM AUSTIN_BIKESHARE.BIKESHARE_TRIPS
    WHERE START_STATION_ID = p_station_id;

    ------------------------------------------------------------------
    -- Step 5: Display results
    ------------------------------------------------------------------
    DBMS_OUTPUT.PUT_LINE('--------------------------------');
    DBMS_OUTPUT.PUT_LINE('Station Name   : ' || lv_station_name);
    DBMS_OUTPUT.PUT_LINE('Total Trips    : ' || lv_total_trips);
    DBMS_OUTPUT.PUT_LINE('Total Duration : ' || lv_total_duration || ' minutes');
    DBMS_OUTPUT.PUT_LINE('--------------------------------');

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END sp_station_trip_summary;
/

