DECLARE
    -- [Memory & Type] [Data Synchronization]
    lv_input_year            NUMBER := 2020;
    lv_current_year          NUMBER := EXTRACT(YEAR FROM SYSDATE);
    lv_record_check          NUMBER;
    lv_efficiency_multiplier NUMBER;

    -- [Cursors] [Inline Execution]
    -- Joins encapsulated in a subquery for isolated data retrieval
    CURSOR c_startup_stats IS
        SELECT company_id, 
               year_founded, 
               valuation, 
               funding, 
               select_investors,
               industry
        FROM   (
            SELECT d.company_id, 
                   d.year_founded, 
                   f.valuation, 
                   f.funding, 
                   f.select_investors,
                   i.industry
            FROM   MODERN_DATA.COMPANIES_DATES d
            JOIN   MODERN_DATA.COMPANIES_FUNDING f ON d.company_id = f.company_id
            JOIN   MODERN_DATA.COMPANIES_INDUSTRIES i ON d.company_id = i.company_id
            WHERE  d.year_founded >= lv_input_year
        )
        ORDER BY company_id ASC;

    r_firm c_startup_stats%ROWTYPE;
BEGIN
    -- [RCA Logging] Initial Start
    DBMS_OUTPUT.PUT_LINE('RCA LOG -> START: Initializing startup financial audit for year ' || lv_input_year);

    -- [Validation] [Control Flow]
    IF lv_input_year < 1900 OR lv_input_year > lv_current_year THEN
        DBMS_OUTPUT.PUT_LINE('Input Error the input year between 1900 to current year ');
        DBMS_OUTPUT.PUT_LINE(lv_input_year || ' is invalid.');
        RETURN;
    END IF;

    -- [Pre-check for Data Existence]
    SELECT COUNT(*)
    INTO   lv_record_check
    FROM   MODERN_DATA.COMPANIES_DATES
    WHERE  year_founded >= lv_input_year;

    IF lv_record_check = 0 THEN
        RAISE NO_DATA_FOUND;
    END IF;

    DBMS_OUTPUT.PUT_LINE('--- Analyzing Companies Founded From ' || lv_input_year || ' Onwards ---');

    -- [Iterative Processing] [Data Retrieval]
    OPEN c_startup_stats;
    LOOP
        FETCH c_startup_stats INTO r_firm;
        EXIT WHEN c_startup_stats%NOTFOUND;

        -- [Decision Logic] [Root Cause Analysis]
        IF NVL(r_firm.funding, 0) > 0 THEN
            lv_efficiency_multiplier := r_firm.valuation / r_firm.funding;

            DBMS_OUTPUT.PUT_LINE('ID: ' || r_firm.company_id || 
                                 ' | Industry: ' || r_firm.industry || 
                                 ' | Investors: ' || r_firm.select_investors ||
                                 ' | Efficiency: ' || ROUND(lv_efficiency_multiplier, 2) || 'x');
        ELSE
            -- Identifying companies that do not provide funding data for multiplier calculation
            DBMS_OUTPUT.PUT_LINE('ID: ' || r_firm.company_id || ' | Skip | Cause: Funding is 0/NULL');
        END IF;
    END LOOP;
    CLOSE c_startup_stats;

    -- [RCA Logging] Process Completion
    DBMS_OUTPUT.PUT_LINE('RCA LOG -> END: Analysis successfully finalized for year ' || lv_input_year);

EXCEPTION
    -- [Exception Handling] [Resource Management]
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No Data Found: No records found for the year ' || lv_input_year);
    WHEN OTHERS THEN 
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred'); 
END;

