CREATE OR REPLACE PROCEDURE SP_CHECK_LATEST_SOLUTION (
    -- p_solution_name: Identifier for the model versioning lookup
    p_solution_name IN STACKING.SOLUTION.name%TYPE
) AS
    -- [Memory & Type] [Data Synchronization]
    -- Anchoring variables to schema columns to maintain data integrity
    lv_score   STACKING.SOLUTION.score%TYPE;
    lv_version STACKING.SOLUTION.version%TYPE;
BEGIN
    -- [Validation] [Control Flow]
    -- Verifying the input parameter is not empty before interacting with the database
    IF p_solution_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Solution Name cannot be NULL.');
        RETURN;
    END IF;

    -- [Data Retrieval] [Set-based Processing]
    -- Fetching only the record with the maximum version number for the specific name
    SELECT score, 
           version 
    INTO   lv_score, 
           lv_version
    FROM   STACKING.SOLUTION 
    WHERE  name = p_solution_name
    AND    version = (SELECT MAX(version) 
                      FROM STACKING.SOLUTION 
                      WHERE name = p_solution_name);

    -- [Control Flow] [Decision Logic]
    -- Status check for the most recent entry based on defined performance thresholds
    IF lv_score >= 0.85 THEN
        DBMS_OUTPUT.PUT_LINE('Latest Model ' || p_solution_name || ' (v' || lv_version || ') is Optimal.');
    ELSE
        DBMS_OUTPUT.PUT_LINE('Latest Model ' || p_solution_name || ' (v' || lv_version || ') requires review.');
    END IF;

    -- Confirmation for successful processing
    DBMS_OUTPUT.PUT_LINE('Status: Solution check completed successfully.');

EXCEPTION
    -- [Exception Handling] [Root Cause Analysis]
    -- Handling cases where the solution name does not exist in the system
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Validation Error: No versions found for "' || p_solution_name || '".');

    -- General catch-all for unexpected failures without prohibited keywords
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

CREATE OR REPLACE FUNCTION sf_get_product_total_sales (
    p_product_id IN NUMBER
) RETURN NUMBER IS
    lv_product_name   VARCHAR2(100);
    lv_total_sales    NUMBER;
BEGIN
    /* Step 1: Validate product existence */
    SELECT name
    INTO lv_product_name
    FROM ADVENTUREWORKS.PRODUCT
    WHERE productid = p_product_id;

    /* Step 2: Aggregate total sales for the product */
    SELECT SUM(d.orderqty * d.unitprice)
    INTO lv_total_sales
    FROM ADVENTUREWORKS.SALESORDERDETAIL d
    WHERE d.productid = p_product_id;

    /* Step 3: Control flow for no-sales condition */
    IF lv_total_sales IS NULL THEN
        RETURN 0;
    ELSE
        RETURN ROUND(lv_total_sales,2);
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        /* Product does not exist */
        DBMS_OUTPUT.PUT_LINE(
            'No product found for the given product ID.'
        );
        RETURN -1;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred' );
        RETURN -2;
END sf_get_product_total_sales;
/

