CREATE OR REPLACE PROCEDURE sp_get_flight_departure_info (
    p_flight_no IN VARCHAR2
) IS
    lv_status       VARCHAR2(100);
    lv_airport_name VARCHAR2(100);
BEGIN
    /* Data retrieval with single-row guarantee */
    SELECT
        f.status,
        a.airport_name
    INTO
        lv_status,
        lv_airport_name
    FROM
             airlines.flights f
        JOIN airlines.airports_data a ON f.departure_airport = a.airport_code
    WHERE
            f.flight_no = p_flight_no
        AND f.scheduled_departure = (
            SELECT
                MAX(f2.scheduled_departure)
            FROM
                airlines.flights f2
            WHERE
                f2.flight_no = p_flight_no
        );

    /* Control Flow */
    IF lv_status = 'Scheduled' THEN
        dbms_output.put_line('Flight Number: ' || p_flight_no);
        dbms_output.put_line('Flight Status: ' || lv_status);
        dbms_output.put_line('Departure Airport: ' || lv_airport_name);
    ELSE
        dbms_output.put_line('Flight found, but not in scheduled status.');
        dbms_output.put_line('Current Status: ' || lv_status);
    END IF;

EXCEPTION
    WHEN no_data_found THEN
        dbms_output.put_line('No flight found for the given flight number.');
        dbms_output.put_line('Please verify the flight number.');
    WHEN OTHERS THEN
        dbms_output.put_line('Unexpected error occurred');
END sp_get_flight_departure_info;
/

