DECLARE
    lv_input_id      COMPLEX_ORACLE.PRODUCTS.prod_id%TYPE := 40;
    lv_prod_name     COMPLEX_ORACLE.PRODUCTS.prod_name%TYPE;
    lv_category      COMPLEX_ORACLE.PRODUCTS.prod_category%TYPE;

    lv_prod_revenue  NUMBER;
    lv_peer_avg      NUMBER;
BEGIN
    SELECT prod_name, 
           prod_category
    INTO   lv_prod_name, 
           lv_category
    FROM   COMPLEX_ORACLE.PRODUCTS
    WHERE  prod_id = lv_input_id;

    SELECT NVL(SUM(amount_sold),0)
    INTO   lv_prod_revenue
    FROM   COMPLEX_ORACLE.SALES
    WHERE  prod_id = lv_input_id;

    SELECT AVG(cat_sales)
    INTO   lv_peer_avg
    FROM   (SELECT SUM(s.amount_sold) AS cat_sales
            FROM   COMPLEX_ORACLE.SALES s
            JOIN   COMPLEX_ORACLE.PRODUCTS p ON s.prod_id = p.prod_id
            WHERE  p.prod_category = lv_category
              AND  p.prod_id <> lv_input_id
            GROUP BY p.prod_id);

    DBMS_OUTPUT.PUT_LINE('Analysis for: ' || lv_prod_name || ' [' || lv_category || ']');

    IF NVL(lv_prod_revenue,0) > NVL(lv_peer_avg, 0) THEN
        DBMS_OUTPUT.PUT_LINE('Success: Revenue is strictly higher than category peers.');
        DBMS_OUTPUT.PUT_LINE('Revenue: ' || NVL(lv_prod_revenue,0) || ' | Peer Avg: ' || ROUND(NVL(lv_peer_avg,0), 2));
    ELSE
        DBMS_OUTPUT.PUT_LINE('Status: Below Peer Average');
        DBMS_OUTPUT.PUT_LINE('Revenue deficit of ' || (NVL(lv_peer_avg,0) - NVL(lv_prod_revenue,0)) || ' from peers.');
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Root Cause: Product ID ' || lv_input_id || ' not found.');
    WHEN OTHERS THEN 
    DBMS_OUTPUT.PUT_LINE('Unexpected error occurred'); 
END;
/

