    -- [Data Retrieval] [Set-based Processing]
    -- Fetching primary product details directly into local variables
    SELECT prod_name, 
           prod_category
    INTO   lv_prod_name, 
           lv_category
    FROM   COMPLEX_ORACLE.PRODUCTS
    WHERE  prod_id = lv_input_id;

    -- [Inline Execution] [Aggregation]
    -- Calculating total earnings for the specific product
    SELECT SUM(amount_sold)
    INTO   lv_prod_revenue
    FROM   COMPLEX_ORACLE.SALES
    WHERE  prod_id = lv_input_id;

