DECLARE
    v_customer    modern_data.pizza_customer_orders.customer_id%TYPE:=101;
    order_details CLOB;
    order_count NUMBER;
BEGIN
    -- DATA RETRIEVAL USING INLINE VIEW
    SELECT
        COUNT(*),
        LISTAGG(
            'Order ID: ' || order_id ||
            ' | Customer: ' || customer_id ||
            ' | Pizza: ' || pizza_name,
            CHR(10)
        ) WITHIN GROUP (ORDER BY order_id)
    INTO order_count, order_details
    FROM (
        SELECT o.order_id,
               o.customer_id,
               p.pizza_name
        FROM modern_data.pizza_customer_orders o
        JOIN modern_data.pizza_names p
          ON o.pizza_id = p.pizza_id
    )
    WHERE customer_id=v_customer;

    -- CONTROL FLOW
    IF order_count > 0 THEN
        DBMS_OUTPUT.PUT_LINE('Customer ID: ' || v_customer);
        DBMS_OUTPUT.PUT_LINE(order_details);
        DBMS_OUTPUT.PUT_LINE('Total Orders: ' || order_count);
    ELSE
        DBMS_OUTPUT.PUT_LINE('Customer ID: ' || v_customer||' '||'no data found.');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
END;
/

