DECLARE
    lv_test_target_id VARCHAR2(50) := 'rodrial01';
    lv_test_year      NUMBER := 2004;
    lv_target_id    VARCHAR2(50) := lv_test_target_id;
    lv_target_year  NUMBER := lv_test_year;
    lv_first_name   BASEBALL.player.name_first%TYPE;
    lv_last_name    BASEBALL.player.name_last%TYPE;
    lv_salary       BASEBALL.salary.salary%TYPE;
BEGIN
    -- Retrieve player details and salary for the audit year
    -- Note: Joining on PLAYER_ID and filtering by YEAR 
    SELECT p.name_first, p.name_last, s.salary
    INTO lv_first_name, lv_last_name, lv_salary
    FROM BASEBALL.player p
    JOIN BASEBALL.salary s ON p.player_id = s.player_id
    WHERE p.player_id = lv_target_id
      AND s.year = lv_target_year
      AND s.salary > (SELECT AVG(salary) FROM BASEBALL.salary WHERE year = lv_target_year - 1);

    -- Analyze Contract Tier
    IF lv_salary > 10000000 THEN
        DBMS_OUTPUT.PUT_LINE('Contract Audit: ' || lv_first_name || ' ' || lv_last_name || ' - $' || lv_salary || ' (Status: Superstar Contract)');
    ELSE
        DBMS_OUTPUT.PUT_LINE('Contract Audit: ' || lv_first_name || ' ' || lv_last_name || ' - $' || lv_salary || ' (Status: Standard Contract)');
    END IF;

EXCEPTION
    -- Handle missing data (e.g., player didn't play that year or data missing)
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Alert: No contract record found for ' || lv_target_id || ' in ' || lv_target_year || '.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected Error Occured.');
END;
/

