DECLARE
    lv_test_target_id VARCHAR2(100);
    lv_test_year      NUMBER;
    lv_target_id    VARCHAR2(100);
    lv_target_year  NUMBER;
    lv_first_name   BASEBALL.player.name_first%TYPE;
    lv_last_name    BASEBALL.player.name_last%TYPE;
    lv_salary       BASEBALL.salary.salary%TYPE;
BEGIN
    -- Find a player/year with multiple qualifying salary rows
    SELECT player_id, year
    INTO lv_test_target_id, lv_test_year
    FROM (
        SELECT s.player_id, s.year
        FROM BASEBALL.salary s
        WHERE s.salary > (SELECT AVG(s2.salary) FROM BASEBALL.salary s2 WHERE s2.year = s.year - 1)
        GROUP BY s.player_id, s.year
        HAVING COUNT(*) > 1
        FETCH FIRST 1 ROWS ONLY
    );

    lv_target_id := lv_test_target_id;
    lv_target_year := lv_test_year;

    -- Retrieve player details and salary for the audit year (expected to raise TOO_MANY_ROWS)
    SELECT p.name_first, p.name_last, s.salary
    INTO lv_first_name, lv_last_name, lv_salary
    FROM BASEBALL.player p
    JOIN BASEBALL.salary s ON p.player_id = s.player_id
    WHERE p.player_id = lv_target_id
      AND s.year = lv_target_year
      AND s.salary > (SELECT AVG(salary) FROM BASEBALL.salary WHERE year = lv_target_year - 1)
      AND ROWNUM <= 50;

    -- Analyze Contract Tier
    IF lv_salary > 10000000 THEN
        DBMS_OUTPUT.PUT_LINE('Contract Audit: ' || lv_first_name || ' ' || lv_last_name || ' - $' || lv_salary || ' (Status: Superstar Contract)');
