CREATE OR REPLACE FUNCTION sf_get_supervisor_name (
    p_emp_id IN ORACLE_SQL.employees.id%TYPE   -- input employee id
) RETURN VARCHAR2 IS

    lv_supervisor_name ORACLE_SQL.employees.name%TYPE;  -- supervisor name

BEGIN
    -- Validate input parameter
    IF p_emp_id IS NULL THEN
        RETURN 'EMPLOYEE ID CANNOT BE NULL';
    END IF;

    -- Fetch supervisor name using self join
    SELECT sup.name
    INTO   lv_supervisor_name
    FROM   ORACLE_SQL.employees emp
           LEFT JOIN ORACLE_SQL.employees sup
               ON emp.supervisor_id = sup.id
    WHERE  emp.id = p_emp_id;

    -- If employee exists but no supervisor assigned
    IF lv_supervisor_name IS NULL THEN
        RETURN 'NO MANAGER ASSIGNED';
    END IF;

    -- Successful scenario
    RETURN lv_supervisor_name;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        -- Employee id does not exist
        RETURN 'EMPLOYEE NOT FOUND';

    WHEN OTHERS THEN
        -- Generic fallback for unexpected errors
        RETURN 'Unexpected error occurred';
END sf_get_supervisor_name;
/

CREATE OR REPLACE PROCEDURE SP_GET_PROBLEM_DETAILS (
    -- p_problem_name: Input identifier for the specific configuration lookup
    p_problem_name IN STACKING.PROBLEM.name%TYPE
) AS
    -- [Memory & Type] [Data Synchronization]
    -- Anchoring variables to schema columns for data integrity
    lv_path   STACKING.PROBLEM.path%TYPE;
    lv_type   STACKING.PROBLEM.type%TYPE;
    lv_target STACKING.PROBLEM.target%TYPE;
BEGIN
    -- [Validation] [Control Flow]
    -- Ensuring the input is not empty before database interaction
    IF p_problem_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Problem Name cannot be NULL.');
        RETURN;
    END IF;

    -- [Data Retrieval] [Set-based Processing]
    -- Selecting configuration details into local variables
    SELECT path, 
           type, 
           target
    INTO   lv_path, 
           lv_type, 
           lv_target
    FROM   STACKING.PROBLEM
    WHERE  name = p_problem_name;

    -- [Control Flow] [Decision Logic]
    -- Outputting basic details followed by categorized logic
    DBMS_OUTPUT.PUT_LINE('Problem: ' || p_problem_name);
    DBMS_OUTPUT.PUT_LINE('Storage Path: ' || lv_path);

    -- Categorizing output based on the problem type
    IF lv_type = 'classification' THEN
        DBMS_OUTPUT.PUT_LINE('Category: Categorical Target (' || lv_target || ')');
    ELSIF lv_type = 'regression' THEN
         DBMS_OUTPUT.PUT_LINE('Category: Numerical Target (' || lv_target || ')');
    ELSE
        DBMS_OUTPUT.PUT_LINE('Category: ' || lv_type || ' | Target: ' || lv_target);
    END IF;

    -- Success confirmation
    DBMS_OUTPUT.PUT_LINE('Status: Problem details retrieved successfully.');

EXCEPTION
    -- [Exception Handling] [Root Cause Analysis]
    -- Handling cases where the problem name does not exist in the table
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No Data Found for Problem "' || p_problem_name || '"');

    -- General catch-all for unexpected system errors without prohibited keywords
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

