DECLARE
    -- Input
    lv_flight_id AIRLINES.FLIGHTS.FLIGHT_ID%TYPE := 7657857;

    -- Inline execution results
    lv_flight_exists     NUMBER;
    lv_total_seats       NUMBER;
    lv_booked_tickets    NUMBER;
    lv_allocation_status VARCHAR2(20) := 'ALLOCATION_OK';

    -- Cursor for RCA details
    CURSOR cur_tickets IS
        SELECT TICKET_NO
        FROM AIRLINES.TICKET_FLIGHTS
        WHERE FLIGHT_ID = lv_flight_id
        ORDER BY TICKET_NO;

    rec_ticket cur_tickets%ROWTYPE;

BEGIN

    IF lv_flight_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('RCA: FLIGHT_ID is NULL.');
        RETURN;
    END IF;

    -- ===============================
    -- INLINE EXECUTION WITH SUBQUERIES
    -- ===============================
    SELECT
        /* Inline subquery: flight existence */
        (SELECT COUNT(*)
           FROM AIRLINES.FLIGHTS f
          WHERE f.FLIGHT_ID = lv_flight_id),

        /* Inline subquery: total seats */
        (SELECT COUNT(*)
           FROM AIRLINES.SEATS s
           JOIN AIRLINES.FLIGHTS f
             ON f.AIRCRAFT_CODE = s.AIRCRAFT_CODE
          WHERE f.FLIGHT_ID = lv_flight_id),

        /* Inline subquery: booked tickets */
        (SELECT COUNT(*)
           FROM AIRLINES.TICKET_FLIGHTS tf
          WHERE tf.FLIGHT_ID = lv_flight_id)

    INTO
        lv_flight_exists,
        lv_total_seats,
        lv_booked_tickets
    FROM dual;

    -- ===============================
    -- RCA DECISION LOGIC
    -- ===============================
    IF lv_flight_exists = 0 THEN
        DBMS_OUTPUT.PUT_LINE('RCA: Flight does not exist.');
        lv_allocation_status := 'ALLOCATION_ISSUE';

    ELSIF lv_total_seats = 0 THEN
        DBMS_OUTPUT.PUT_LINE('RCA: Aircraft assigned but no seats configured.');
        lv_allocation_status := 'ALLOCATION_ISSUE';

    ELSIF lv_booked_tickets > lv_total_seats THEN
        DBMS_OUTPUT.PUT_LINE(
            'RCA: Overbooking detected. Tickets = '
            || lv_booked_tickets || ', Seats = ' || lv_total_seats
        );
        lv_allocation_status := 'ALLOCATION_ISSUE';

    ELSE
        DBMS_OUTPUT.PUT_LINE('RCA: Seat allocation is valid.');
        lv_allocation_status := 'ALLOCATION_OK';
    END IF;

    -- RCA DETAIL USING CURSOR
    IF lv_flight_exists > 0 THEN
        OPEN cur_tickets;
        LOOP
            FETCH cur_tickets INTO rec_ticket;
            EXIT WHEN cur_tickets%NOTFOUND;
            DBMS_OUTPUT.PUT_LINE('RCA Detail: Ticket booked -> ' || rec_ticket.TICKET_NO);
        END LOOP;
        CLOSE cur_tickets;
    END IF;

    -- FINAL SUMMARY
    DBMS_OUTPUT.PUT_LINE('--- Inline Execution Summary ---');
    DBMS_OUTPUT.PUT_LINE(
        'Flight ' || lv_flight_id || ' Allocation Status = ' || lv_allocation_status
    );

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;

