CREATE OR REPLACE FUNCTION sf_get_invoice_total (
    p_invoiceid IN NUMBER
) RETURN VARCHAR2
IS
    v_total NUMBER;
BEGIN
--input validation
    IF p_invoiceid IS NULL THEN
        RETURN'Invoice ID NULL not found';
    END IF;
    --calculates invoice totals using aggregation
    SELECT SUM(quantity * unitprice)
    INTO v_total
    FROM chinook.invoice_items
    WHERE invoiceid = p_invoiceid;
-- Control flow
    IF v_total =0 THEN
        RETURN 'Invoice ID: ' || p_invoiceid || CHR(10) ||
               'Total Invoive value: '||0;
    ELSIF v_total IS NULL THEN
        RETURN 'Invoice ID: ' || p_invoiceid || ' no data found';              
    ELSE
        RETURN 'Invoice ID: ' || p_invoiceid || CHR(10) ||
               'Total Invoive value: '||v_total;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_invoice_total;
/

