CREATE OR REPLACE PROCEDURE sp_analyze_member_activity(
    p_region           IN BANK_SALES_TRADING.BITCOIN_MEMBERS.REGION%TYPE DEFAULT NULL,
    p_min_transactions IN NUMBER DEFAULT 5
) IS

    -- Variables to hold details for the current member being processed
    v_member_id     BANK_SALES_TRADING.BITCOIN_MEMBERS.MEMBER_ID%TYPE;
    v_member_name   BANK_SALES_TRADING.BITCOIN_MEMBERS.FIRST_NAME%TYPE;
    v_member_region BANK_SALES_TRADING.BITCOIN_MEMBERS.REGION%TYPE;

    -- Variables to hold transaction statistics for the current member
    v_total_transactions NUMBER := 0;
    v_buy_transactions   NUMBER := 0;
    v_sell_transactions  NUMBER := 0;
    v_total_quantity     NUMBER := 0;

    -- Activity classification label for the current member
    v_activity_status   VARCHAR2(20);
    -- Tracks how many members have been processed in the loop
    v_members_processed NUMBER := 0;
    -- Tracks how many members met the minimum transaction threshold
    v_members_qualified NUMBER := 0;

    -- Maximum number of members to process before stopping the loop
    c_max_display_members CONSTANT NUMBER := 5;

    -- Raised when p_min_transactions is NULL or negative
    e_invalid_min_transactions EXCEPTION;
    -- Raised when no members were found or processed
    e_no_members_found         EXCEPTION;

BEGIN

    -- Print the report header
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('BITCOIN MEMBER ACTIVITY ANALYSIS');
    DBMS_OUTPUT.PUT_LINE('========================================');

    -- Validate the minimum transactions parameter before proceeding
    IF p_min_transactions IS NULL OR p_min_transactions < 0 THEN
        RAISE e_invalid_min_transactions;
    END IF;

    -- Print the active filter values
    IF p_region IS NOT NULL THEN
        DBMS_OUTPUT.PUT_LINE('Region Filter: ' || p_region);
    ELSE
        DBMS_OUTPUT.PUT_LINE('Region Filter: ALL REGIONS');
    END IF;

    DBMS_OUTPUT.PUT_LINE('Minimum Transactions: ' || p_min_transactions);
    DBMS_OUTPUT.PUT_LINE('Display Limit: ' || c_max_display_members || ' members');
    DBMS_OUTPUT.PUT_LINE('----------------------------------------');
    DBMS_OUTPUT.PUT_LINE('');

    -- Loop through members matching the region filter ordered by region then name
    FOR member_rec IN (
        SELECT m.member_id, m.first_name, m.region
        FROM   BANK_SALES_TRADING.BITCOIN_MEMBERS m
        WHERE  (p_region IS NULL OR m.region = p_region)
        ORDER  BY m.region, m.first_name
    ) LOOP

        -- Stop once the maximum display limit has been reached
        EXIT WHEN v_members_processed >= c_max_display_members;

        BEGIN
            -- Reset all transaction counters before querying for this member
            v_total_transactions := 0;
            v_buy_transactions   := 0;
            v_sell_transactions  := 0;
            v_total_quantity     := 0;
            v_activity_status    := 'INACTIVE';

            -- Retrieve aggregated transaction statistics for the current member
            SELECT COUNT(*),
                   SUM(CASE WHEN txn_type = 'BUY'  THEN 1 ELSE 0 END),
                   SUM(CASE WHEN txn_type = 'SELL' THEN 1 ELSE 0 END),
                   NVL(SUM(quantity), 0)
            INTO   v_total_transactions,
                   v_buy_transactions,
                   v_sell_transactions,
                   v_total_quantity
            FROM   BANK_SALES_TRADING.BITCOIN_TRANSACTIONS
            WHERE  member_id = member_rec.member_id;

            -- Classify the member based on how many transactions they have
            IF    v_total_transactions >= p_min_transactions * 2 THEN
                v_activity_status := 'HIGHLY ACTIVE';
            ELSIF v_total_transactions >= p_min_transactions THEN
                v_activity_status := 'ACTIVE';
            ELSIF v_total_transactions > 0 THEN
                v_activity_status := 'LOW ACTIVITY';
            ELSE
                v_activity_status := 'INACTIVE';
            END IF;

            -- Print details only for members who meet the minimum threshold
            IF v_total_transactions >= p_min_transactions THEN
                DBMS_OUTPUT.PUT_LINE(
                    'Member: ' || member_rec.first_name
                    || ' [ID: ' || member_rec.member_id || ']');
                DBMS_OUTPUT.PUT_LINE('  Region: '             || member_rec.region);
                DBMS_OUTPUT.PUT_LINE('  Total Transactions: ' || v_total_transactions);
                DBMS_OUTPUT.PUT_LINE(
                    '  Buy: ' || v_buy_transactions
                    || ' | Sell: ' || v_sell_transactions);
                DBMS_OUTPUT.PUT_LINE(
                    '  Total Quantity: '
                    || TO_CHAR(v_total_quantity, '999,999.99'));
                DBMS_OUTPUT.PUT_LINE('  Activity Status: ' || v_activity_status);
                DBMS_OUTPUT.PUT_LINE('');

                v_members_qualified := v_members_qualified + 1;
            END IF;

            v_members_processed := v_members_processed + 1;

        EXCEPTION
            -- Warn when no transaction rows exist for this member
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE(
                    '  [WARNING] No transaction data for member: '
                    || member_rec.member_id);
            -- Catch any other unexpected error during member processing
            WHEN OTHERS THEN
                DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
        END;

    END LOOP;

    -- Raise an error if the loop processed no members at all
    IF v_members_processed = 0 THEN
        RAISE e_no_members_found;
    END IF;

    -- Print the final summary section
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('SUMMARY');
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('Total Members Processed: ' || v_members_processed);
    DBMS_OUTPUT.PUT_LINE('Members Meeting Criteria: ' || v_members_qualified);
    DBMS_OUTPUT.PUT_LINE('========================================');

EXCEPTION
    -- Handle invalid minimum transactions value
    WHEN e_invalid_min_transactions THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('ERROR: Invalid minimum transactions parameter');
        DBMS_OUTPUT.PUT_LINE('DETAILS: Minimum transactions must be a positive number');
        DBMS_OUTPUT.PUT_LINE(
            'PROVIDED VALUE: ' || NVL(TO_CHAR(p_min_transactions), 'NULL'));

    -- Handle the case where no members were found or processed
    WHEN e_no_members_found THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('ERROR: No members found matching criteria');
        DBMS_OUTPUT.PUT_LINE('DETAILS: Check region filter or database content');

    -- Catch any other unexpected error at the top level
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');

END sp_analyze_member_activity;
/

