DECLARE
    p_from_date    DATE := DATE '2019-01-01';
    p_to_date      DATE := DATE '2019-12-31';
    p_channel_desc COMPLEX_ORACLE.CHANNELS.CHANNEL_DESC%TYPE := 'Internet';

    e_invalid_input EXCEPTION;
    e_no_data       EXCEPTION;

    v_profit NUMBER;
BEGIN
    /* Validation */
    IF p_from_date IS NULL
       OR p_to_date IS NULL
       OR p_channel_desc IS NULL
       OR p_from_date > p_to_date THEN
        RAISE e_invalid_input;
    END IF;

    /* Profit / Loss calculation */
    SELECT SUM(c.unit_price - c.unit_cost)
    INTO v_profit
    FROM complex_oracle.costs c
    INNER JOIN complex_oracle.channels ch
      ON ch.channel_id = c.channel_id
    WHERE UPPER(ch.channel_desc) = UPPER(p_channel_desc)
      AND c.time_id BETWEEN p_from_date AND p_to_date;
   IF v_profit IS NULL THEN
        RAISE e_no_data;
    ELSIF v_profit > 0 THEN
        dbms_output.put_line('Profit for channel "'
                             || upper(p_channel_desc)
                             || '" between '
                             || p_from_date
                             || ' and '
                             || p_to_date
                             || ' is: '
                             || v_profit);
    ELSE
        dbms_output.put_line('Loss for channel "'
                             || upper(p_channel_desc)
                             || '" between '
                             || p_from_date
                             || ' and '
                             || p_to_date
                             || ' is: '
                             || v_profit);
    END IF;

EXCEPTION
    WHEN e_invalid_input THEN
        DBMS_OUTPUT.PUT_LINE('Invalid input parameters.');
    WHEN e_no_data THEN
        DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN OTHERS THEN
        dbms_output.put_line('Unexpected error');
END;
/

