CREATE OR REPLACE PROCEDURE sp_get_customer_product_promo_sales
(
    p_cust_id   IN NUMBER,       -- input customer id
    p_year      IN NUMBER        -- input calendar year
)
IS

    -- local variable to check customer existence
    lv_customer_count NUMBER;

    -- local variable to store total sales
    lv_total_sales NUMBER;

BEGIN

    -----------------------------------------------------------
    -- Validate customer id input parameter
    -----------------------------------------------------------
    IF p_cust_id IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Customer id cannot be NULL or blank.');
        RETURN;
    END IF;

    -----------------------------------------------------------
    -- Check whether the given customer exists
    -----------------------------------------------------------
    SELECT COUNT(*)
    INTO lv_customer_count
    FROM COMPLEX_ORACLE.CUSTOMERS
    WHERE cust_id = p_cust_id;

    IF lv_customer_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Error: Customer does not exist for the given id.');
        RETURN;
    END IF;

    -----------------------------------------------------------
    -- Retrieve total sales amount for given customer and year
    -----------------------------------------------------------
    SELECT SUM(amount_sold)
    INTO lv_total_sales
    FROM COMPLEX_ORACLE.SALES s
    JOIN COMPLEX_ORACLE.TIMES t
      ON s.time_id = t.time_id
    WHERE s.cust_id = p_cust_id
    AND   t.calendar_year = p_year;

    -----------------------------------------------------------
    -- Handle scenario when no sales data is found
    -----------------------------------------------------------
    IF lv_total_sales IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('No sales found for the given customer and year.');
        RETURN;
    ELSE
        DBMS_OUTPUT.PUT_LINE('Sales retrieved successfully.');
        DBMS_OUTPUT.PUT_LINE('Total Sales Amount : ' || lv_total_sales);
    END IF;

EXCEPTION

    -----------------------------------------------------------
    -- Generic exception handler
    -----------------------------------------------------------
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');

END sp_get_customer_product_promo_sales;
/

