CREATE OR REPLACE PROCEDURE pr_bikeshare_station_summary (
    p_landmark IN VARCHAR2
)
IS
    lv_total_stations   NUMBER := 0;
    lv_total_docks      NUMBER := 0;
BEGIN
    IF p_landmark IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Landmark cannot be NULL');
        RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('===== BIKESHARE STATION SUMMARY =====');

    SELECT 
        COUNT(*),
        SUM(TO_NUMBER(dockcount))
    INTO 
        lv_total_stations,
        lv_total_docks
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS
    WHERE UPPER(landmark) = UPPER(p_landmark);

    DBMS_OUTPUT.PUT_LINE('Landmark: ' || p_landmark);
    DBMS_OUTPUT.PUT_LINE('Total Stations: ' || lv_total_stations);
    DBMS_OUTPUT.PUT_LINE('Total Docks: ' || NVL(lv_total_docks, 0));

    IF lv_total_stations = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Status: No stations found');
    ELSE
        DBMS_OUTPUT.PUT_LINE('Status: Data retrieved successfully');
    END IF;

    DBMS_OUTPUT.PUT_LINE('====================================');

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Error: No data found');
    WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Error: Invalid number conversion');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

