CREATE OR REPLACE PROCEDURE report_patient_recent_encounters(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_cost_flag  VARCHAR2(10);
  lv_row_count  PLS_INTEGER := 0;
  lv_dummy      NUMBER;
BEGIN
  IF p_patient_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Patient ID is required.');
    RETURN;
  END IF;

  SELECT 1
    INTO lv_dummy
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  DBMS_OUTPUT.PUT_LINE('Recent encounters for patient: ' || p_patient_id);

  -- Inline query loop (implicit cursor) to keep the routine simple
  FOR rec IN (
    SELECT e.id               AS encounter_id,
           e.start_timestamp  AS start_ts,
           e.stop_timestamp   AS stop_ts,
           e.encounterclass   AS encounter_class,
           e.description      AS encounter_desc,
           e.total_claim_cost AS total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id
     ORDER BY e.start_timestamp DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_row_count := lv_row_count + 1;

    IF rec.total_claim_cost >= 1000 THEN
      lv_cost_flag := 'HIGH';
    ELSE
      lv_cost_flag := 'NORMAL';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Encounter: ' || rec.encounter_id ||
      ' | Start: ' || TO_CHAR(rec.start_ts, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | Stop: ' || TO_CHAR(rec.stop_ts, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | Class: ' || rec.encounter_class ||
      ' | Desc: ' || rec.encounter_desc ||
      ' | Total Claim: ' || TO_CHAR(rec.total_claim_cost) ||
      ' | Cost Flag: ' || lv_cost_flag
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_patient_recent_encounters;
/

