CREATE OR REPLACE PACKAGE pkg_patient_care AS
    -- Procedure to assess the care category for a single patient
    PROCEDURE sp_assess_patient(
        p_patient_id IN VARCHAR2 -- Input patient identifier
    );
END pkg_patient_care;
/

CREATE OR REPLACE PACKAGE BODY pkg_patient_care AS
    PROCEDURE sp_assess_patient(
        p_patient_id IN VARCHAR2 -- Input patient identifier
    ) IS
        lv_first_name   SYNTHEA.PATIENTS.first%TYPE;      -- Stores patient first name
        lv_last_name    SYNTHEA.PATIENTS.last%TYPE;       -- Stores patient last name
        lv_birthdate    SYNTHEA.PATIENTS.birthdate%TYPE;  -- Stores patient birthdate
        lv_patient_age  NUMBER;                           -- Stores derived patient age
        lv_care_type    VARCHAR2(30);                     -- Stores derived care category
    BEGIN
        -- Retrieve patient demographic details for the given patient id
        SELECT first,
               last,
               birthdate
        INTO   lv_first_name,
               lv_last_name,
               lv_birthdate
        FROM   SYNTHEA.PATIENTS
        WHERE  id = p_patient_id;

        -- Derive patient age from birthdate
        lv_patient_age := FLOOR(MONTHS_BETWEEN(TRUNC(DATE '2025-01-01'), TRUNC(lv_birthdate)) / 12);

        -- Assign care category based on derived age
        IF lv_patient_age >= 65 THEN
            lv_care_type := 'Senior Wellness';
        ELSIF lv_patient_age >= 18 THEN
            lv_care_type := 'Adult Primary Care';
        ELSE
            lv_care_type := 'Pediatric Care';
        END IF;

        -- Print successful assessment output
        DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_first_name || ' ' || lv_last_name);
        DBMS_OUTPUT.PUT_LINE('Senior Wellness | Adult Primary Care | Pediatric Care');
        DBMS_OUTPUT.PUT_LINE('Category: ' || lv_care_type);

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            DBMS_OUTPUT.PUT_LINE('No patient data found');
        WHEN TOO_MANY_ROWS THEN
            DBMS_OUTPUT.PUT_LINE('Multiple rows returned unexpectedly');
        WHEN OTHERS THEN
            DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
    END sp_assess_patient;
END pkg_patient_care;
/

