CREATE OR REPLACE FUNCTION sf_get_county_births (
    p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE%TYPE,
    p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.YEAR%TYPE
)
RETURN VARCHAR2
IS
    lv_births SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.BIRTHS%TYPE;
BEGIN

    -- Input validation
    IF p_county_name IS NULL OR p_year IS NULL THEN
        RETURN 'Validation failed: County name or Year is NULL';
    END IF;

    -- Retrieve births
    SELECT BIRTHS
    INTO lv_births
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
    WHERE COUNTY_OF_RESIDENCE = p_county_name
    AND YEAR = p_year;

    -- Success message
    RETURN 'County: ' || p_county_name ||
           ' | Year: ' || TO_CHAR(p_year,'YYYY') ||
           ' | Births: ' || lv_births;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Business error: No natality records found for the given county and year';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_county_births;
/

CREATE OR REPLACE FUNCTION sf_get_driver_nationality (
    p_driver_id IN NUMBER
) RETURN VARCHAR2
IS
    -- Variable to hold the retrieved nationality
    v_nationality F1.DRIVERS.nationality%TYPE;

BEGIN
    -- Validate input parameter
    IF p_driver_id IS NULL THEN
        RETURN 'Error: p_driver_id cannot be NULL';
    END IF;

    -- Retrieve driver nationality from the DRIVERS table
    SELECT nationality
    INTO   v_nationality
    FROM   F1.DRIVERS
    WHERE  driver_id = p_driver_id;

    -- Return the nationality on success
    RETURN v_nationality;

EXCEPTION
    -- Handle case where driver ID does not exist
    WHEN NO_DATA_FOUND THEN
        RETURN 'Error: Driver not found for ID ' || p_driver_id;
    -- Handle any unexpected runtime errors
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred.';

END sf_get_driver_nationality;
/

CREATE OR REPLACE FUNCTION sf_get_unemployment_value (
    p_series_id IN BLS.UNEMPLOYMENT_CPS.SERIES_ID%TYPE,
    p_year      IN BLS.UNEMPLOYMENT_CPS.YEAR%TYPE
) RETURN VARCHAR2
IS
    lv_avg_value NUMBER;
    lv_count     NUMBER;
BEGIN

    -- Input validation
    IF p_series_id IS NULL OR p_year IS NULL THEN
        RETURN 'Validation failed: SERIES_ID or YEAR is NULL';
    END IF;

    -- Retrieve count and average in single query
    SELECT COUNT(value), AVG(TO_NUMBER(value))
    INTO lv_count, lv_avg_value
    FROM BLS.UNEMPLOYMENT_CPS
    WHERE series_id = p_series_id
      AND year = p_year
      AND value IS NOT NULL;

    IF lv_count = 0 THEN
        RETURN 'No unemployment records found for Series ID '
               || p_series_id || ' in Year ' || p_year;
    END IF;

    RETURN 'Series ID: ' || p_series_id ||
           ' | Year: ' || p_year ||
           ' | Average Unemployment Value: ' || ROUND(lv_avg_value,2);

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_unemployment_value;
/

