CREATE OR REPLACE FUNCTION sf_get_trip_duration (
    p_trip_id IN SAN_FRANCISCO.BIKESHARE_TRIPS.TRIP_ID%TYPE
)
RETURN VARCHAR2
IS
    lv_duration SAN_FRANCISCO.BIKESHARE_TRIPS.DURATION_SEC%TYPE;
BEGIN

    IF p_trip_id IS NULL OR TRIM(p_trip_id) = '' THEN
        RETURN 'Trip ID is NULL or Empty';
    END IF;

    SELECT DURATION_SEC
    INTO lv_duration
    FROM SAN_FRANCISCO.BIKESHARE_TRIPS
    WHERE TRIP_ID = p_trip_id;

    RETURN 'Trip ID: ' || p_trip_id || ' | Duration (seconds): ' || lv_duration;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Trip ID not found';
    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_trip_duration;
/

