    lv_year        BLS.CPSAAT18.YEAR%TYPE;
    lv_women       BLS.CPSAAT18.PERCENT_WOMEN%TYPE;
    lv_white       BLS.CPSAAT18.PERCENT_WHITE%TYPE;
    lv_black       BLS.CPSAAT18.PERCENT_BLACK_OR_AFRICAN_AMERICAN%TYPE;
    lv_asian       BLS.CPSAAT18.PERCENT_ASIAN%TYPE;

BEGIN

    -- Validate input
    IF p_sector IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Sector cannot be NULL');
        RETURN;
    END IF;

    -- Retrieve demographic statistics
    SELECT YEAR,
           PERCENT_WOMEN,
           PERCENT_WHITE,
           PERCENT_BLACK_OR_AFRICAN_AMERICAN,
           PERCENT_ASIAN
    INTO   lv_year,
           lv_women,
           lv_white,
           lv_black,
           lv_asian
    FROM (
            SELECT YEAR,
                   PERCENT_WOMEN,
                   PERCENT_WHITE,
                   PERCENT_BLACK_OR_AFRICAN_AMERICAN,
                   PERCENT_ASIAN
            FROM BLS.CPSAAT18
            WHERE UPPER(SECTOR) = UPPER(p_sector)
            ORDER BY YEAR DESC
         )
    WHERE ROWNUM = 1;

    DBMS_OUTPUT.PUT_LINE(
        'Sector: ' || p_sector ||
        ' | Percent Women: ' || lv_women ||
        ' | Percent White: ' || lv_white ||
        ' | Percent Black: ' || lv_black ||
        ' | Percent Asian: ' || lv_asian
    );

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No demographic data found for the provided sector');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;

