CREATE OR REPLACE FUNCTION sf_get_promo_sales (
    p_promo_id IN COMPLEX_ORACLE.SALES.PROMO_ID%TYPE
) RETURN VARCHAR2
IS
    lv_total_sales NUMBER := 0;
BEGIN

    -- Input Validation
    IF p_promo_id IS NULL THEN
        RETURN 'Validation failed: PROMO_ID cannot be NULL';
    END IF;

    -- Retrieve total sales amount
    SELECT NVL(SUM(AMOUNT_SOLD),0)
    INTO lv_total_sales
    FROM COMPLEX_ORACLE.SALES
    WHERE PROMO_ID = p_promo_id;

    -- Check if sales exist
    IF lv_total_sales = 0 THEN
        RETURN 'No sales found for Promotion ID: ' || p_promo_id;
    END IF;

    -- Return formatted result
    RETURN 'Promotion ID: ' || p_promo_id || ' | Total Sales: ' || lv_total_sales;

EXCEPTION

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_get_promo_sales;
/

CREATE OR REPLACE FUNCTION sf_get_country_info (
    p_country_code IN WORLD_BANK_WDI.COUNTRY_SUMMARY.COUNTRY_CODE%TYPE
)
RETURN VARCHAR2
IS
    v_country_name WORLD_BANK_WDI.COUNTRY_SUMMARY.LONG_NAME%TYPE;
    v_region       WORLD_BANK_WDI.COUNTRY_SUMMARY.REGION%TYPE;
    v_income_group WORLD_BANK_WDI.COUNTRY_SUMMARY.INCOME_GROUP%TYPE;
BEGIN
    IF p_country_code IS NULL THEN
        RETURN 'Country code cannot be NULL';
    END IF;

    SELECT LONG_NAME, REGION, INCOME_GROUP
      INTO v_country_name, v_region, v_income_group
      FROM WORLD_BANK_WDI.COUNTRY_SUMMARY
     WHERE COUNTRY_CODE = p_country_code;

    RETURN 'Country: ' || v_country_name ||
