    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';
END sf_get_country_info;
/

DECLARE
    -- Thresholds to classify how much stock a product has
    c_high_stock CONSTANT NUMBER := 100;
    c_low_stock  CONSTANT NUMBER := 10;

    -- Cursor to retrieve the first 3 products sorted by product ID
    CURSOR cur_products IS
        SELECT id,
               name,
               group_id
        FROM   ORACLE_SQL.PRODUCTS
        ORDER  BY id ASC
        FETCH  FIRST 3 ROWS ONLY;

    -- Counter for total products found in the table
    v_product_count NUMBER := 0;
    -- Counter for how many products were processed in the loop
    v_loop_count    NUMBER := 0;
    -- Running total of inventory quantities across all displayed products
    v_total_qty     NUMBER := 0;
    -- Average inventory quantity across displayed products
    v_avg_qty       NUMBER := 0;
    -- Inventory quantity available for the current product
    v_inv_qty       NUMBER := 0;
    -- Total quantity ordered for the current product
    v_order_qty     NUMBER := 0;
    -- Stock label assigned based on inventory level
    v_stock_status  VARCHAR2(20);

    -- Raised when no products exist or match the query
    e_no_products_found      EXCEPTION;
    -- Raised when a product has a negative inventory quantity
    e_invalid_inventory_data EXCEPTION;

BEGIN

    -- Print the report header
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('PRODUCT INVENTORY ANALYSIS');
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('');

    -- Count all products in the table to confirm data exists
    SELECT COUNT(*)
    INTO   v_product_count
    FROM   ORACLE_SQL.PRODUCTS;

    -- Stop processing if the table has no products
    IF v_product_count = 0 THEN
        RAISE e_no_products_found;
    END IF;

    -- Print validation summary before entering the main loop
    DBMS_OUTPUT.PUT_LINE('PHASE 1: DATA VALIDATION');
    DBMS_OUTPUT.PUT_LINE('------------------------');
    DBMS_OUTPUT.PUT_LINE('Total Products Available: ' || v_product_count);
    DBMS_OUTPUT.PUT_LINE('');

    -- Print the header for the per-product analysis section
    DBMS_OUTPUT.PUT_LINE('PHASE 2: PRODUCT ANALYSIS');
    DBMS_OUTPUT.PUT_LINE('-------------------------');
    DBMS_OUTPUT.PUT_LINE('');

    -- Loop through each product returned by the cursor
    FOR prod_rec IN cur_products LOOP
        BEGIN
            -- Look up how much of this product is currently in inventory
            BEGIN
                SELECT NVL(SUM(qty), 0)
                INTO   v_inv_qty
                FROM   ORACLE_SQL.INVENTORY
                WHERE  product_id = prod_rec.id;
            EXCEPTION
                -- If no inventory rows exist for this product default to zero
                WHEN NO_DATA_FOUND THEN
                    v_inv_qty := 0;
            END;

            -- Look up how much of this product has been ordered
            BEGIN
                SELECT NVL(SUM(qty), 0)
                INTO   v_order_qty
                FROM   ORACLE_SQL.ORDERLINES
                WHERE  product_id = prod_rec.id;
            EXCEPTION
                -- If no order rows exist for this product default to zero
                WHEN NO_DATA_FOUND THEN
                    v_order_qty := 0;
            END;

            -- A negative inventory quantity indicates bad data
            IF v_inv_qty < 0 THEN
                RAISE e_invalid_inventory_data;
            END IF;

            -- Assign a stock label based on how much inventory is available
            IF    v_inv_qty >= c_high_stock THEN
                v_stock_status := 'OVERSTOCKED';
            ELSIF v_inv_qty >= c_low_stock THEN
                v_stock_status := 'ADEQUATE';
            ELSE
                v_stock_status := 'LOW STOCK';
            END IF;

            -- Print the details for the current product
            DBMS_OUTPUT.PUT_LINE('Product: '        || prod_rec.name);
            DBMS_OUTPUT.PUT_LINE('  Product ID: '   || prod_rec.id);
            DBMS_OUTPUT.PUT_LINE('  Group ID: '     || NVL(TO_CHAR(prod_rec.group_id), 'N/A'));
            DBMS_OUTPUT.PUT_LINE('  Inventory Qty: '|| v_inv_qty);
            DBMS_OUTPUT.PUT_LINE('  Order Qty: '    || v_order_qty);
            DBMS_OUTPUT.PUT_LINE('  Stock Status: ' || v_stock_status);

            -- Print an action recommendation based on the stock label
            IF v_stock_status = 'OVERSTOCKED' THEN
                DBMS_OUTPUT.PUT_LINE('  >> ACTION: Review purchasing to reduce overstock');
            ELSIF v_stock_status = 'ADEQUATE' THEN
                DBMS_OUTPUT.PUT_LINE('  >> ACTION: Maintain current stock levels');
            ELSE
                DBMS_OUTPUT.PUT_LINE('  >> ACTION: Reorder required - stock below threshold');
            END IF;

            DBMS_OUTPUT.PUT_LINE('');

            -- Accumulate totals for the summary section
            v_total_qty  := v_total_qty  + v_inv_qty;
            v_loop_count := v_loop_count + 1;

        EXCEPTION
            -- Handle bad inventory data for this product and continue the loop
            WHEN e_invalid_inventory_data THEN
                DBMS_OUTPUT.PUT_LINE(
                    '  ERROR: Invalid inventory data for Product ID: ' || prod_rec.id);
                DBMS_OUTPUT.PUT_LINE(
                    '  ROOT CAUSE: Negative inventory quantity detected');
                DBMS_OUTPUT.PUT_LINE(
                    '  RECOMMENDATION: Verify inventory records in INVENTORY table');
                DBMS_OUTPUT.PUT_LINE('');

            -- Catch any unexpected error for this product and continue the loop
            WHEN OTHERS THEN
                DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');
        END;
    END LOOP;

    -- Print the summary section after all products have been processed
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('SUMMARY STATISTICS');
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('Total Products Available: '        || v_product_count);
    DBMS_OUTPUT.PUT_LINE('Products Displayed: '              || v_loop_count);
    DBMS_OUTPUT.PUT_LINE('Total Inventory Qty (Displayed): ' || v_total_qty);

    -- Only calculate and print the average if at least one product was processed
    IF v_loop_count > 0 THEN
        v_avg_qty := v_total_qty / v_loop_count;
        DBMS_OUTPUT.PUT_LINE('Average Inventory per Product: '
            || TO_CHAR(v_avg_qty, '999,999.99'));
    END IF;

    DBMS_OUTPUT.PUT_LINE('========================================');

EXCEPTION
    -- Handle the case where no products were found in the table
    WHEN e_no_products_found THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('CRITICAL ERROR: NO PRODUCTS FOUND');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('ROOT CAUSE ANALYSIS:');
        DBMS_OUTPUT.PUT_LINE('  1. PRODUCTS table may be empty');
        DBMS_OUTPUT.PUT_LINE('  2. User may lack SELECT privileges');
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('RECOMMENDATIONS:');
        DBMS_OUTPUT.PUT_LINE('  - Verify PRODUCTS table contains data');
        DBMS_OUTPUT.PUT_LINE('  - Verify database permissions');

    -- Catch any unexpected error at the top level
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');

END;

