CREATE OR REPLACE FUNCTION sf_get_aircraft_range (
    p_aircraft_code IN AIRLINES.AIRCRAFTS_DATA.AIRCRAFT_CODE%TYPE
)
RETURN VARCHAR2
IS
    lv_model AIRLINES.AIRCRAFTS_DATA.MODEL%TYPE;
    lv_range AIRLINES.AIRCRAFTS_DATA.RANGE%TYPE;
BEGIN

    -- Validate input
    IF p_aircraft_code IS NULL THEN
        RETURN 'Aircraft code cannot be NULL';
    END IF;

    -- Retrieve aircraft details
    SELECT MODEL,
           RANGE
    INTO   lv_model,
           lv_range
    FROM AIRLINES.AIRCRAFTS_DATA
    WHERE UPPER(AIRCRAFT_CODE) = UPPER(p_aircraft_code);

    -- Return formatted output
    RETURN 'Aircraft Code: ' || p_aircraft_code ||
           ' | Model: ' || lv_model ||
           ' | Range: ' || lv_range;

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'Aircraft not found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_get_aircraft_range;
/

CREATE OR REPLACE FUNCTION sf_get_veg_category (
    p_item_code IN BANK_SALES_TRADING.VEG_CAT.ITEM_CODE%TYPE
)
RETURN VARCHAR2
IS
    lv_item_name      BANK_SALES_TRADING.VEG_CAT.ITEM_NAME%TYPE;
    lv_category_name  BANK_SALES_TRADING.VEG_CAT.CATEGORY_NAME%TYPE;
BEGIN

    -- Input validation
    IF p_item_code IS NULL THEN
        RETURN 'Validation failed: ITEM_CODE cannot be NULL';
    END IF;

    -- Retrieve vegetable details
    SELECT ITEM_NAME, CATEGORY_NAME
    INTO lv_item_name, lv_category_name
    FROM BANK_SALES_TRADING.VEG_CAT
    WHERE ITEM_CODE = p_item_code;

    -- Return formatted result
    RETURN 'Item Code: ' || p_item_code ||
           ' | Item Name: ' || lv_item_name ||
           ' | Category: ' || lv_category_name;

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'No vegetable item found for ITEM_CODE: ' || p_item_code;

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_get_veg_category;
/

