    END IF;

    -- Retrieve latest model score
    SELECT MODEL, TRAIN_SCORE, TEST_SCORE
    INTO lv_model, lv_train_score, lv_test_score
    FROM (
        SELECT MODEL, TRAIN_SCORE, TEST_SCORE
        FROM STACKING.MODEL_SCORE
        WHERE NAME = p_dataset_name
        ORDER BY VERSION DESC, STEP DESC
    )
    WHERE ROWNUM = 1;

    RETURN 'Dataset: ' || p_dataset_name ||
           ' | Model: ' || lv_model ||
           ' | Train Score: ' || lv_train_score ||
           ' | Test Score: ' || lv_test_score;

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'No model score found for dataset: ' || p_dataset_name;

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_get_model_scores;
/

