CREATE OR REPLACE FUNCTION sf_get_physician_details (
    p_npi IN VARCHAR2
) RETURN VARCHAR2
IS
    lv_provider_last_name   VARCHAR2(100);
    lv_provider_first_name  VARCHAR2(50);
    lv_provider_type        VARCHAR2(100);
BEGIN

    -- Input Validation
    IF p_npi IS NULL THEN
        RETURN 'NPI ID NULL not found';
    END IF;

    -- Retrieve physician information
    SELECT nppes_provider_last_org_name,
           nppes_provider_first_name,
           provider_type
    INTO   lv_provider_last_name,
           lv_provider_first_name,
           lv_provider_type
    FROM   cms_medicare.physicians_and_other_supplier
    WHERE  npi = p_npi
    AND    ROWNUM = 1;

    -- Return formatted result
    RETURN 'NPI ID: ' || p_npi || CHR(10) ||
           'Provider Last Name: ' || lv_provider_last_name || CHR(10) ||
           'Provider First Name: ' || lv_provider_first_name || CHR(10) ||
           'Provider Type: ' || lv_provider_type;

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'NPI ID:' || p_npi || ' No data found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_get_physician_details;
/

SET SERVEROUTPUT ON;
DECLARE
    ------------------------------------------------------------------
    -- Input Parameter
    ------------------------------------------------------------------
    p_country_code   VARCHAR2(50) := 'Finland';

    ------------------------------------------------------------------
    -- Cursor (4 tables)
    ------------------------------------------------------------------
    CURSOR cur_job_data IS
        SELECT
            j.job_id,
            j.job_title,
            j.salary_year_avg,
            c.name AS company_name,
            cc.country_name
        FROM CITY_LEGISLATION.JOB_POSTINGS_FACT j
        INNER JOIN CITY_LEGISLATION.JOB_COMPANY c
            ON j.company_id = c.company_id
        INNER JOIN CITY_LEGISLATION.CITIES_COUNTRIES cc
            ON UPPER(j.job_country) = UPPER(cc.country_name)  
        INNER JOIN CITY_LEGISLATION.CITIES ci
            ON cc.country_code_2 = ci.country_code_2
        WHERE UPPER(j.job_country) = UPPER(p_country_code)
        FETCH FIRST 15 ROWS ONLY;

    ------------------------------------------------------------------
    -- Variables
    ------------------------------------------------------------------
    lv_job_id     NUMBER;
    lv_title      VARCHAR2(500);
    lv_salary     NUMBER;
    lv_company    VARCHAR2(500);
    lv_country    VARCHAR2(500);

    lv_total      NUMBER := 0;

BEGIN
    ------------------------------------------------------------------
    -- Input Validation
    ------------------------------------------------------------------
    IF p_country_code IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Error: Country code cannot be NULL');
        RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('===== JOB AUDIT REPORT =====');

    ------------------------------------------------------------------
    -- Cursor Processing
    ------------------------------------------------------------------
    OPEN cur_job_data;

    LOOP
        FETCH cur_job_data INTO
            lv_job_id,
            lv_title,
            lv_salary,
            lv_company,
            lv_country;

        EXIT WHEN cur_job_data%NOTFOUND;

        lv_total := lv_total + 1;

        ------------------------------------------------------------------
        -- Output
        ------------------------------------------------------------------
        DBMS_OUTPUT.PUT_LINE(
            'Job ID: ' || lv_job_id ||
            ' | Job: ' || lv_title ||
            ' | Company: ' || lv_company ||
            ' | Country: ' || lv_country ||
            ' | Salary: ' || NVL(lv_salary, 0)
        );

        ------------------------------------------------------------------
        -- Control Flow
        ------------------------------------------------------------------
        IF lv_salary IS NULL THEN
            DBMS_OUTPUT.PUT_LINE('Status: Salary Not Available');
        ELSIF lv_salary < 50000 THEN
            DBMS_OUTPUT.PUT_LINE('Status: Low Salary');
        ELSE
            DBMS_OUTPUT.PUT_LINE('Status: Good Salary');
        END IF;

        DBMS_OUTPUT.PUT_LINE('----------------------------------');

    END LOOP;

    CLOSE cur_job_data;

    ------------------------------------------------------------------
    -- No Data Case
    ------------------------------------------------------------------
    IF lv_total = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Error: No jobs found');
        RETURN;
    END IF;

    ------------------------------------------------------------------
    -- Summary
    ------------------------------------------------------------------
    DBMS_OUTPUT.PUT_LINE('Total Jobs Processed: ' || lv_total);
    DBMS_OUTPUT.PUT_LINE('Audit Completed Successfully');

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Error: Data not found');

    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Error: Duplicate data found');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

