CREATE OR REPLACE FUNCTION sf_get_series_details (
    p_series_code IN VARCHAR2
) RETURN VARCHAR2
IS
    lv_indicator_name VARCHAR2(300);
    lv_topic          VARCHAR2(200);
BEGIN

    -- Input Validation
    IF p_series_code IS NULL THEN
        RETURN 'SERIES CODE NULL not found';
    END IF;

    -- Retrieve series information
    SELECT indicator_name,
           topic
    INTO   lv_indicator_name,
           lv_topic
    FROM   world_bank_intl_debt.series_summary
    WHERE  series_code = p_series_code;

    -- Return formatted result
    RETURN 'Series Code: ' || p_series_code || chr(10) ||
           'Indicator: ' || lv_indicator_name || chr(10) ||
           'Topic: ' || lv_topic;

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'SERIES CODE:'|| p_series_code||'  '||'No data found' ;

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_get_series_details;
/

DECLARE
    lv_input_region VARCHAR2(50) := 'Sub-Saharan Africa';
    -- Variable anchoring
    lv_region       world_bank_intl_debt.country_summary.region%TYPE := lv_input_region;
    lv_record_count NUMBER := 0;
    lv_category     VARCHAR2(20);
    lv_val_billions NUMBER;

    -- Parameterized Cursor with multi-table join and aggregation
    CURSOR cur_regional_debt(p_region VARCHAR2) IS
        SELECT cs.short_name, id.indicator_name, AVG(id.value) AS avg_value
        FROM world_bank_intl_debt.international_debt id
        JOIN world_bank_intl_debt.country_summary cs
          ON id.country_code = cs.country_code
        WHERE cs.region = p_region AND id.VALUE IS NOT NULL
        GROUP BY cs.short_name, id.indicator_name
        ORDER BY avg_value DESC
        FETCH FIRST 5 ROWS ONLY;

BEGIN
    DBMS_OUTPUT.PUT_LINE('Debt Analysis for Region: ' || lv_region);

    -- Passing the variable into the parameterized cursor
    FOR i IN cur_regional_debt(lv_region) LOOP
        lv_record_count := lv_record_count + 1;

        -- Data Transformation
        lv_val_billions := ROUND(i.avg_value / 1000000000, 2);

        -- Multi-tiered Control Flow
        IF i.avg_value > 10000000000 THEN
            lv_category := 'Severe';
        ELSIF i.avg_value >= 1000000000 THEN
            lv_category := 'High';
        ELSE
            lv_category := 'Moderate';
        END IF;

        DBMS_OUTPUT.PUT_LINE('Country: ' || i.short_name || ' | ' || i.indicator_name || ': ' || lv_val_billions || 'B USD (' || lv_category || ')');
    END LOOP;

    IF lv_record_count = 0 THEN
        RAISE NO_DATA_FOUND;
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No data found');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;
/

