    lv_birth_rate  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.CRUDE_BIRTH_RATE%TYPE;
    lv_death_rate  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.CRUDE_DEATH_RATE%TYPE;
    lv_year        CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.YEAR%TYPE;
    lv_area        CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.COUNTRY_AREA%TYPE;

    CURSOR cur_growth IS
        SELECT g.year,
               g.crude_birth_rate,
               g.crude_death_rate,
               a.country_area
        FROM   CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES g
        JOIN   CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA a
        ON     g.country_code = a.country_code
        WHERE  g.country_name = p_country_name
        ORDER BY g.year;

    lv_count NUMBER := 0;

BEGIN

    -- Control Flow Validation
    IF p_country_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Country name cannot be NULL');
        RETURN;
    END IF;

    -- Cursor Iteration
    FOR rec_growth IN cur_growth LOOP

        lv_count := lv_count + 1;

        lv_year := rec_growth.year;
        lv_birth_rate := rec_growth.crude_birth_rate;
        lv_death_rate := rec_growth.crude_death_rate;
        lv_area := rec_growth.country_area;

        DBMS_OUTPUT.PUT_LINE(
            'Country: ' || p_country_name ||
            ' | Area: ' || lv_area ||
            ' | Year: ' || lv_year ||
            ' | Birth Rate: ' || lv_birth_rate ||
            ' | Death Rate: ' || lv_death_rate
        );

        -- Control Flow Processing
        IF TO_NUMBER(lv_birth_rate) > TO_NUMBER(lv_death_rate) THEN
            DBMS_OUTPUT.PUT_LINE('Population is increasing');

        ELSIF TO_NUMBER(lv_birth_rate) < TO_NUMBER(lv_death_rate) THEN
            DBMS_OUTPUT.PUT_LINE('Population is decreasing');

        ELSE
            DBMS_OUTPUT.PUT_LINE('Population is stable');
        END IF;

    END LOOP;

    IF lv_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Growth rate data not found');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');
END;

