CREATE OR REPLACE FUNCTION sf_country_currency
(
    p_country_name IN WORLD_BANK_WDI.COUNTRY_SUMMARY.SHORT_NAME%TYPE
)
RETURN VARCHAR2
IS

    lv_currency WORLD_BANK_WDI.COUNTRY_SUMMARY.CURRENCY_UNIT%TYPE;
    lv_result   VARCHAR2(500);

BEGIN

    -- Validate input
    IF p_country_name IS NULL THEN
        RETURN 'Country name cannot be NULL';
    END IF;

    -- Retrieve currency information
    SELECT currency_unit
    INTO   lv_currency
    FROM   WORLD_BANK_WDI.COUNTRY_SUMMARY
    WHERE  SHORT_NAME = p_country_name;

    lv_result :=
        'Country: ' || p_country_name ||
        ' | Currency: ' || lv_currency;

    RETURN lv_result;

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'Country currency information not found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_country_currency;
/

CREATE OR REPLACE PROCEDURE sp_analyze_country_indicators(
    p_country_code   IN WORLD_BANK_WDI.INDICATORS_DATA.COUNTRY_CODE%TYPE   DEFAULT NULL,
    p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.INDICATOR_CODE%TYPE DEFAULT NULL
)
IS
    -- Total number of indicator records matching the given filters
    v_record_count    NUMBER := 0;
    -- Number of distinct indicator codes in the filtered dataset
    v_indicator_count NUMBER := 0;
    -- Number of distinct years covered in the filtered dataset
    v_year_count      NUMBER := 0;
    -- Income group classification for the given country
    v_income_group    VARCHAR2(50);
    -- Coverage label assigned based on how many years of data exist
    v_data_coverage   VARCHAR2(20);

    -- Raised when no indicator records match the filter criteria
    e_no_data_found EXCEPTION;

BEGIN

    -- Print the report header
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('COUNTRY INDICATOR ANALYSIS');
    DBMS_OUTPUT.PUT_LINE('========================================');

    -- Print active filters if they were provided
    IF p_country_code IS NOT NULL THEN
        DBMS_OUTPUT.PUT_LINE('Country Filter: ' || p_country_code);
    END IF;

    IF p_indicator_code IS NOT NULL THEN
        DBMS_OUTPUT.PUT_LINE('Indicator Filter: ' || p_indicator_code);
    END IF;

    DBMS_OUTPUT.PUT_LINE('----------------------------------------');
    DBMS_OUTPUT.PUT_LINE('');

    -- Count how many records match the filters to confirm data exists
    SELECT COUNT(*)
    INTO   v_record_count
    FROM   WORLD_BANK_WDI.INDICATORS_DATA
    WHERE  (p_country_code   IS NULL OR country_code   = p_country_code)
    AND    (p_indicator_code IS NULL OR indicator_code = p_indicator_code);

    -- Stop processing if no matching records were found
    IF v_record_count = 0 THEN
        RAISE e_no_data_found;
    END IF;

    -- Print validation summary before moving to the analysis section
    DBMS_OUTPUT.PUT_LINE('PHASE 1: DATA VALIDATION');
    DBMS_OUTPUT.PUT_LINE('------------------------');
    DBMS_OUTPUT.PUT_LINE('Total Records Found: ' || v_record_count);
    DBMS_OUTPUT.PUT_LINE('');

    -- Print the header for the detailed analysis section
    DBMS_OUTPUT.PUT_LINE('PHASE 2: INDICATOR ANALYSIS');
    DBMS_OUTPUT.PUT_LINE('---------------------------');
    DBMS_OUTPUT.PUT_LINE('');

    -- Retrieve the number of distinct indicators and years from the filtered dataset
    SELECT COUNT(DISTINCT indicator_code),
           COUNT(DISTINCT year)
    INTO   v_indicator_count,
           v_year_count
    FROM   WORLD_BANK_WDI.INDICATORS_DATA
    WHERE  (p_country_code   IS NULL OR country_code   = p_country_code)
    AND    (p_indicator_code IS NULL OR indicator_code = p_indicator_code);

    -- Look up the income group for the given country if a country code was provided
    BEGIN
        IF p_country_code IS NOT NULL THEN
            SELECT NVL(income_group, 'N/A')
            INTO   v_income_group
            FROM   WORLD_BANK_WDI.COUNTRY_SUMMARY
            WHERE  country_code = p_country_code;
        ELSE
            v_income_group := 'N/A';
        END IF;
    EXCEPTION
        -- If the country code does not exist in COUNTRY_SUMMARY default to N/A
        WHEN NO_DATA_FOUND THEN
            v_income_group := 'N/A';
    END;

    -- Assign a coverage label based on how many years of data are available
    IF    v_year_count > 50 THEN
        v_data_coverage := 'EXTENSIVE';
    ELSIF v_year_count > 20 THEN
        v_data_coverage := 'MODERATE';
    ELSE
        v_data_coverage := 'LIMITED';
    END IF;

    -- Print the indicator metrics for the filtered dataset
    DBMS_OUTPUT.PUT_LINE('Total Records: '       || v_record_count);
    DBMS_OUTPUT.PUT_LINE('Distinct Indicators: ' || v_indicator_count);
    DBMS_OUTPUT.PUT_LINE('Years Covered: '       || v_year_count);
    DBMS_OUTPUT.PUT_LINE('Income Group: '        || v_income_group);
    DBMS_OUTPUT.PUT_LINE('Data Coverage: '       || v_data_coverage);

    -- Print an action recommendation based on the assigned coverage label
    IF v_data_coverage = 'EXTENSIVE' THEN
        DBMS_OUTPUT.PUT_LINE(
            '>> ACTION: Rich dataset available - suitable for long-term trend analysis');
    ELSIF v_data_coverage = 'MODERATE' THEN
        DBMS_OUTPUT.PUT_LINE(
            '>> ACTION: Moderate dataset - suitable for medium-term analysis');
    ELSE
        DBMS_OUTPUT.PUT_LINE(
            '>> ACTION: Limited data available - interpret results with caution');
    END IF;

    -- Print the summary section with overall totals
    DBMS_OUTPUT.PUT_LINE('');
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('SUMMARY STATISTICS');
    DBMS_OUTPUT.PUT_LINE('========================================');
    DBMS_OUTPUT.PUT_LINE('Records Analysed: '     || v_record_count);
    DBMS_OUTPUT.PUT_LINE('Data Coverage Level: '  || v_data_coverage);
    DBMS_OUTPUT.PUT_LINE('========================================');

EXCEPTION
    -- Handle the case where no records matched the filter criteria
    WHEN e_no_data_found THEN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('CRITICAL ERROR: NO DATA FOUND');
        DBMS_OUTPUT.PUT_LINE('========================================');
        DBMS_OUTPUT.PUT_LINE('ROOT CAUSE ANALYSIS:');
        DBMS_OUTPUT.PUT_LINE('  1. INDICATORS_DATA table may be empty');
        DBMS_OUTPUT.PUT_LINE('  2. No records match filter criteria');
        IF p_country_code IS NOT NULL THEN
            DBMS_OUTPUT.PUT_LINE(
                '  3. Country code ' || p_country_code || ' does not exist');
        END IF;
        DBMS_OUTPUT.PUT_LINE('  4. User may lack SELECT privileges');
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('RECOMMENDATIONS:');
        DBMS_OUTPUT.PUT_LINE('  - Verify INDICATORS_DATA table contains data');
        DBMS_OUTPUT.PUT_LINE('  - Check filter parameters');
        DBMS_OUTPUT.PUT_LINE('  - Verify database permissions');

    -- Catch any unexpected error at the top level
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred.');

END sp_analyze_country_indicators;
/

