CREATE OR REPLACE FUNCTION sf_get_patient_allergy (
    p_patient_id IN SYNTHEA.ALLERGIES.PATIENT%TYPE
) 
RETURN VARCHAR2
IS
    lv_code        SYNTHEA.ALLERGIES.CODE%TYPE;
    lv_desc        SYNTHEA.ALLERGIES.DESCRIPTION%TYPE;
    lv_start_date  SYNTHEA.ALLERGIES.START_DATE%TYPE;
BEGIN

    -- Validate input
    IF p_patient_id IS NULL THEN
        RETURN 'Patient ID cannot be NULL';
    END IF;

    -- Retrieve allergy details
    SELECT CODE, DESCRIPTION, START_DATE
    INTO lv_code, lv_desc, lv_start_date
    FROM SYNTHEA.ALLERGIES
    WHERE PATIENT = p_patient_id;

    -- Return formatted output
    RETURN 'Patient: ' || p_patient_id ||
           ' | Allergy Code: ' || lv_code ||
           ' | Description: ' || lv_desc ||
           ' | Start Date: ' || TO_CHAR(lv_start_date,'YYYY-MM-DD');

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        RETURN 'No allergy data found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_get_patient_allergy;
/

DECLARE
