    lv_county        SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT.COUNTY_OF_RESIDENCE%TYPE;
    lv_payment_src   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT.SOURCE_OF_PAYMENT%TYPE;
    lv_births        SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT.BIRTHS%TYPE;

BEGIN

    -- Validate input
    IF p_county_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('County name cannot be NULL');
        RETURN;
    END IF;

    -- Retrieve latest birth statistics by year
    SELECT COUNTY_OF_RESIDENCE,
           SOURCE_OF_PAYMENT,
           BIRTHS
    INTO   lv_county,
           lv_payment_src,
           lv_births
    FROM (
        SELECT COUNTY_OF_RESIDENCE,
               SOURCE_OF_PAYMENT,
               BIRTHS
        FROM   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT
        WHERE  UPPER(COUNTY_OF_RESIDENCE) = UPPER(p_county_name)
        ORDER BY YEAR DESC
    )
    WHERE ROWNUM = 1;

    -- Display output
    DBMS_OUTPUT.PUT_LINE(
        'County: ' || lv_county ||
        ' | Payment Source: ' || lv_payment_src ||
        ' | Births: ' || lv_births
    );

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No payment source data found');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;

