CREATE OR REPLACE FUNCTION sf_check_sales_performance
(
    p_businessentityid    NUMBER
)
RETURN VARCHAR2
IS

------------------------------------------------
-- VARIABLES
------------------------------------------------
    v_salesytd        NUMBER;
    v_saleslastyear   NUMBER;
    v_growth          NUMBER;

BEGIN

------------------------------------------------
-- INPUT VALIDATION
------------------------------------------------
    IF p_businessentityid IS NULL THEN
        RETURN 'BUSINESSENTITY ID NULL not found';
    END IF;

------------------------------------------------
-- DATA RETRIEVAL
------------------------------------------------
    SELECT salesytd,
           saleslastyear
    INTO   v_salesytd,
           v_saleslastyear
    FROM   adventureworks.salesperson
    WHERE  businessentityid = p_businessentityid;

------------------------------------------------
-- CONTROL FLOW (BUSINESS LOGIC)
------------------------------------------------
    v_growth := ((v_salesytd - v_saleslastyear) / v_saleslastyear) * 100;

    IF v_growth >= 20 THEN
        RETURN 'BUSINESSENTITY ID:' || p_businessentityid || CHR(10) || 'Performance: EXCELLENT';

    ELSIF v_growth BETWEEN 1 AND 19 THEN
        RETURN 'BUSINESSENTITY ID:' || p_businessentityid || CHR(10) || 'Performance: IMPROVING';

    ELSE
        RETURN 'BUSINESSENTITY ID:' || p_businessentityid || CHR(10) || 'Performance: DECLINING';
    END IF;

------------------------------------------------
-- EXCEPTION HANDLING
------------------------------------------------
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'BUSINESSENTITY ID: ' || p_businessentityid || ' No data found';

    WHEN OTHERS THEN
        RETURN 'Unexpected error occurred';

END sf_check_sales_performance;
/

DECLARE

    p_series_code WORLD_BANK_WDI.FOOTNOTES.SERIES_CODE%TYPE := 'SL.UEM.TOTL.NE.ZS';

    lv_count NUMBER := 0;

    CURSOR cur_footnotes IS
     SELECT *
        FROM (
        SELECT f.series_code,
               s.indicator_name,
               f.year,
               f.description
        FROM WORLD_BANK_WDI.FOOTNOTES f
        JOIN WORLD_BANK_WDI.SERIES_SUMMARY s
        ON f.series_code = s.series_code
        WHERE f.series_code = p_series_code
        ORDER BY f.year, s.indicator_name
        )
        WHERE ROWNUM <= 5;

BEGIN

    -- Input Validation
    IF p_series_code IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Series code cannot be NULL');
        RETURN;
    END IF;

    -- Cursor Iteration
    FOR rec_note IN cur_footnotes LOOP

        lv_count := lv_count + 1;

        DBMS_OUTPUT.PUT_LINE(
            'Series Code: ' || rec_note.series_code ||
            ' | Indicator: ' || rec_note.indicator_name ||
            ' | Year: ' || rec_note.year ||
            ' | Footnote: ' || rec_note.description
        );

        -- Control Flow Logic
        IF rec_note.description IS NOT NULL 
           AND LENGTH(rec_note.description) > 100 THEN
            DBMS_OUTPUT.PUT_LINE('Detailed historical note available');
        ELSE
            DBMS_OUTPUT.PUT_LINE('Brief note available');
        END IF;

    END LOOP;

    -- No Data Handling
    IF lv_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Footnote data not found');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;

