    lv_track_name   MUSIC.TRACK.NAME%TYPE;
    lv_media_type   MUSIC.MEDIATYPE.NAME%TYPE;

BEGIN

    -- Validate input
    IF p_track_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Track name cannot be NULL');
        RETURN;
    END IF;

    -- Retrieve media type name
    SELECT t.NAME,
           m.NAME
    INTO   lv_track_name,
           lv_media_type
    FROM   MUSIC.TRACK t
           JOIN MUSIC.MEDIATYPE m
           ON t.MEDIATYPEID = m.MEDIATYPEID
    WHERE  UPPER(t.NAME) = UPPER(p_track_name);

    -- Display formatted output
    DBMS_OUTPUT.PUT_LINE(
        'Track: ' || lv_track_name ||
        ' | Media Type: ' || lv_media_type
    );

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Track media type information not found');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;

