DECLARE
    p_occupation_code   BLS.WM_SERIES.OCCUPATION_CODE%TYPE := 372011;

    lv_series_title      BLS.WM_SERIES.SERIES_TITLE%TYPE;
    lv_year              BLS.WM.YEAR%TYPE;
    lv_value             BLS.WM.VALUE%TYPE;

BEGIN

    -- Validate input
    IF p_occupation_code IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Occupation code cannot be NULL');
        RETURN;
    END IF;

    -- Retrieve wage measurement statistics
    SELECT s.SERIES_TITLE,
           w.YEAR,
           w.VALUE
    INTO   lv_series_title,
           lv_year,
           lv_value
    FROM   BLS.WM w
           JOIN BLS.WM_SERIES s
           ON w.SERIES_ID = s.SERIES_ID
    WHERE  s.OCCUPATION_CODE = p_occupation_code
    ORDER BY w.YEAR DESC
