        'Occupation Code: ' || p_occupation_code ||
        ' | Series Title: ' || lv_series_title ||
        ' | Year: ' || lv_year ||
        ' | Wage Value: ' || lv_value
    );

EXCEPTION

    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Wage data not found');

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

