question:
A compliance analyst wants a quick "data quality + operational" review of Medicare Home Health Agencies for a given state.

Build a reusable PL/SQL package that produces a row-limited ranked report (top agencies by Medicare payment amount) for the state. It should iterate through the ranked agencies with an explicit cursor and flag suspicious records where numeric fields are not numeric or are negative by setting them to NULL (only for rows in that state). It should print a summary showing how many agencies were reviewed and how many fields were nullified.

The source table stores many numeric fields as VARCHAR2, so you must defensively validate and handle conversion errors without crashing.

Requirements:
Procedure Name: CMS_HHA_QA_PKG.RUN_STATE_QA
Parameters:
P_STATE IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('QA start. State=' || NVL(p_state, 'NULL'));
DBMS_OUTPUT.PUT_LINE('Top agencies by Medicare payment (non-LUPA):');
DBMS_OUTPUT.PUT_LINE(LPAD('RNK', 4) || ' | ' || RPAD('PROVIDER_ID', 10) || ' | ' || RPAD('AGENCY_NAME', 40) || ' | ' || LPAD('PAYMENT_AMT', 14));
DBMS_OUTPUT.PUT_LINE(LPAD(TO_CHAR(rec.rnk), 4) || ' | ' || RPAD(rec.provider_id, 10) || ' | ' || RPAD(SUBSTR(rec.agency_name, 1, 40), 40) || ' | ' || LPAD(NVL(rec.payment_amt, 'NULL'), 14));
DBMS_OUTPUT.PUT_LINE('Reviewed agencies: ' || TO_CHAR(lv_reviewed));
DBMS_OUTPUT.PUT_LINE('Fields nullified: ' || TO_CHAR(lv_nullified));
DBMS_OUTPUT.PUT_LINE('QA complete.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN VALUE_ERROR THEN: 'Invalid numeric conversion.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE cms_hha_qa_pkg IS
  PROCEDURE run_state_qa(
    p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
  );
END cms_hha_qa_pkg;
/

CREATE OR REPLACE PACKAGE BODY cms_hha_qa_pkg IS

  PROCEDURE run_state_qa(
    p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_reviewed   PLS_INTEGER := 0;
    lv_nullified  PLS_INTEGER := 0;

    CURSOR c_ranked_agencies IS
      WITH ranked AS (
        SELECT
          hha.provider_id,
          hha.agency_name,
          hha.state,
          hha.total_hha_medicare_payment_amount_non_lupa AS payment_amt,
          ROW_NUMBER() OVER (
            ORDER BY
              -- Defensive CASE to safely convert VARCHAR2 payment amount to NUMBER for sorting, preventing VALUE_ERROR exceptions
              CASE
                WHEN REGEXP_LIKE(TRIM(hha.total_hha_medicare_payment_amount_non_lupa), '^-?\d+(\.\d+)?$')
                  THEN TO_NUMBER(TRIM(hha.total_hha_medicare_payment_amount_non_lupa))
                ELSE NULL
              END DESC,
              hha.provider_id
          ) AS rnk
        FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
        WHERE hha.state = p_state
      )
      SELECT
        ranked.provider_id,
        ranked.agency_name,
        ranked.state,
        ranked.payment_amt,
        ranked.rnk
      FROM ranked
      WHERE ranked.rnk <= co_report_limit
      ORDER BY ranked.rnk;

    -- Procedure uses dynamic SQL to update a column whose name is passed as a parameter, enabling flexible nullification of invalid fields
    PROCEDURE nullify_if_bad_number(
      p_provider_id IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.provider_id%TYPE,
      p_state_in    IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE,
      p_col_name    IN VARCHAR2,
      p_col_value   IN VARCHAR2,
      io_nullified  IN OUT PLS_INTEGER
    ) IS
      lv_is_numeric BOOLEAN;
      lv_num        NUMBER;
      lv_sql        VARCHAR2(1000);
    BEGIN
      lv_is_numeric := REGEXP_LIKE(TRIM(p_col_value), '^-?\d+(\.\d+)?$');

      IF p_col_value IS NULL THEN
        RETURN;
      END IF;

      IF lv_is_numeric THEN
        lv_num := TO_NUMBER(TRIM(p_col_value));
        IF lv_num < 0 THEN
          lv_sql := 'UPDATE CMS_MEDICARE.HOME_HEALTH_AGENCIES ' ||
                    'SET ' || p_col_name || ' = NULL ' ||
                    'WHERE provider_id = :1 AND state = :2';
          EXECUTE IMMEDIATE lv_sql USING p_provider_id, p_state_in;
          io_nullified := io_nullified + 1;
        END IF;
      ELSE
        lv_sql := 'UPDATE CMS_MEDICARE.HOME_HEALTH_AGENCIES ' ||
                  'SET ' || p_col_name || ' = NULL ' ||
                  'WHERE provider_id = :1 AND state = :2';
        EXECUTE IMMEDIATE lv_sql USING p_provider_id, p_state_in;
        io_nullified := io_nullified + 1;
      END IF;

    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Invalid numeric conversion.');
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    END nullify_if_bad_number;

  BEGIN
    DBMS_OUTPUT.PUT_LINE('QA start. State=' || NVL(p_state, 'NULL'));

    IF p_state IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Top agencies by Medicare payment (non-LUPA):');
    DBMS_OUTPUT.PUT_LINE(LPAD('RNK', 4) || ' | ' || RPAD('PROVIDER_ID', 10) || ' | ' || RPAD('AGENCY_NAME', 40) || ' | ' || LPAD('PAYMENT_AMT', 14));

    FOR rec IN c_ranked_agencies LOOP
      lv_reviewed := lv_reviewed + 1;

      DBMS_OUTPUT.PUT_LINE(
        LPAD(TO_CHAR(rec.rnk), 4) || ' | ' ||
        RPAD(rec.provider_id, 10) || ' | ' ||
        RPAD(SUBSTR(rec.agency_name, 1, 40), 40) || ' | ' ||
        LPAD(NVL(rec.payment_amt, 'NULL'), 14)
      );

      nullify_if_bad_number(
        p_provider_id => rec.provider_id,
        p_state_in    => rec.state,
        p_col_name    => 'TOTAL_HHA_MEDICARE_PAYMENT_AMOUNT_NON_LUPA',
        p_col_value   => rec.payment_amt,
        io_nullified  => lv_nullified
      );

      -- Re-check a couple additional numeric-as-text fields for the same provider/state.
      DECLARE
        lv_charge_amt CMS_MEDICARE.HOME_HEALTH_AGENCIES.total_hha_charge_amount_non_lupa%TYPE;
        lv_episodes   CMS_MEDICARE.HOME_HEALTH_AGENCIES.total_episodes_non_lupa%TYPE;
      BEGIN
        SELECT
          hha.total_hha_charge_amount_non_lupa,
          hha.total_episodes_non_lupa
        INTO
          lv_charge_amt,
          lv_episodes
        FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
        WHERE hha.provider_id = rec.provider_id
          AND hha.state = rec.state;

        nullify_if_bad_number(
          p_provider_id => rec.provider_id,
          p_state_in    => rec.state,
          p_col_name    => 'TOTAL_HHA_CHARGE_AMOUNT_NON_LUPA',
          p_col_value   => lv_charge_amt,
          io_nullified  => lv_nullified
        );

        nullify_if_bad_number(
          p_provider_id => rec.provider_id,
          p_state_in    => rec.state,
          p_col_name    => 'TOTAL_EPISODES_NON_LUPA',
          p_col_value   => lv_episodes,
          io_nullified  => lv_nullified
        );

      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          DBMS_OUTPUT.PUT_LINE('No data found.');
        WHEN TOO_MANY_ROWS THEN
          DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
        WHEN OTHERS THEN
          DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      END;

    END LOOP;

    COMMIT;

    IF lv_reviewed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Reviewed agencies: ' || TO_CHAR(lv_reviewed));
    DBMS_OUTPUT.PUT_LINE('Fields nullified: ' || TO_CHAR(lv_nullified));
    DBMS_OUTPUT.PUT_LINE('QA complete.');

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      ROLLBACK;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN VALUE_ERROR THEN
      ROLLBACK;
      DBMS_OUTPUT.PUT_LINE('Invalid numeric conversion.');
    WHEN OTHERS THEN
      ROLLBACK;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_state_qa;

END cms_hha_qa_pkg;
/

