DECLARE

    p_country_name WORLD_BANK_WDI.COUNTRY_SUMMARY.SHORT_NAME%TYPE := 'India';

    lv_count NUMBER := 0;

    CURSOR cur_indicator_data IS
        SELECT *
        FROM (
            SELECT cs.short_name,
                   cs.region,
                   id.indicator_name,
                   id.year,
                   id.value
            FROM WORLD_BANK_WDI.COUNTRY_SUMMARY cs
            JOIN WORLD_BANK_WDI.INDICATORS_DATA id
            ON cs.country_code = id.country_code
            WHERE cs.short_name = p_country_name
            ORDER BY id.year, id.indicator_name
        )
        WHERE ROWNUM <= 10;

BEGIN

    -- Input Validation
    IF p_country_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Country name cannot be NULL');
        RETURN;
    END IF;

    -- Cursor Iteration
    FOR rec_indicator IN cur_indicator_data LOOP

        lv_count := lv_count + 1;

        DBMS_OUTPUT.PUT_LINE(
            'Country: ' || rec_indicator.short_name ||
            ' | Region: ' || rec_indicator.region ||
            ' | Indicator: ' || rec_indicator.indicator_name ||
            ' | Year: ' || rec_indicator.year ||
            ' | Value: ' || rec_indicator.value
        );

        -- Control Flow
        IF rec_indicator.value IS NOT NULL 
           AND TO_NUMBER(rec_indicator.value) > 0 THEN
            DBMS_OUTPUT.PUT_LINE('Valid indicator value recorded');
        ELSE
            DBMS_OUTPUT.PUT_LINE('Indicator value unavailable or invalid');
        END IF;

    END LOOP;

    -- No Data Handling
    IF lv_count = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Indicator data not found');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;

