DECLARE

    -- Input Parameters
    p_name    STACKING.EDA.NAME%TYPE := 'PCOS';
    p_version STACKING.EDA.VERSION%TYPE := 2;

    -- Constants
    co_corr_threshold CONSTANT NUMBER := 0.5;
    co_imp_threshold  CONSTANT NUMBER := 0.5;

    -- Local Variables
    lv_dropped_features VARCHAR2(4000) := '';
    lv_count NUMBER := 0;

    -- Custom Exception
    exp_no_data EXCEPTION;

    -- Cursor (Duplicate handled using ROW_NUMBER)
    CURSOR cur_eda IS
        SELECT name,
               version,
               feature,
               drop_correlation,
               range,
               importance
        FROM (
            SELECT e.name,
                   e.version,
                   e.feature,
                   e.drop_correlation,
                   e.range,
                   f.importance,
                   ROW_NUMBER() OVER (
                       PARTITION BY e.name, e.version, e.feature
                       ORDER BY e.feature
                   ) rn
            FROM STACKING.EDA e
            JOIN STACKING.FEATURE_IMPORTANCE f
              ON e.name = f.name
             AND e.feature = f.feature
             AND e.version = f.version
            WHERE e.name = p_name
              AND e.version = p_version
        )
        WHERE rn = 1
        ORDER BY feature;

BEGIN

    -- Input Validation
    IF p_name IS NULL OR p_version IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Name and Version cannot be NULL');
        RETURN;
    END IF;

    -- Cursor Loop
    FOR rec_eda IN cur_eda LOOP

        lv_count := lv_count + 1;

        -- Handle NULL RANGE safely
        IF rec_eda.range IS NULL THEN
            DBMS_OUTPUT.PUT_LINE(
                'Skipping NULL RANGE for feature: ' || rec_eda.feature
            );
        END IF;

        -- Filtering Logic
        IF rec_eda.drop_correlation IS NOT NULL
           AND rec_eda.importance IS NOT NULL
           AND rec_eda.drop_correlation > co_corr_threshold
           AND rec_eda.importance < co_imp_threshold THEN

            lv_dropped_features :=
                lv_dropped_features || rec_eda.feature || ', ';

        END IF;

    END LOOP;

    -- No Data Handling
    IF lv_count = 0 THEN
        RAISE exp_no_data;
    END IF;

    -- Output Result
    IF lv_dropped_features IS NOT NULL AND LENGTH(lv_dropped_features) > 0 THEN
        DBMS_OUTPUT.PUT_LINE(
            'Dropped Features for ' || p_name ||
            ' (Version: ' || p_version || '): ' ||
            RTRIM(lv_dropped_features, ', ')
        );
    ELSE
        DBMS_OUTPUT.PUT_LINE(
            'No features to drop for ' || p_name ||
            ' (Version: ' || p_version || ')'
        );
    END IF;

EXCEPTION

    WHEN exp_no_data THEN
        DBMS_OUTPUT.PUT_LINE(
            'No data found for given NAME and VERSION'
        );

    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error occurred');

END;
/

