CREATE OR REPLACE PROCEDURE wh_picklist_report(
  p_order_id IN ORACLE_SQL.ORDERS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_lines IS
    SELECT ol.id AS line_id,
           p.name AS product_name,
           ol.qty AS ordered_qty,
           NVL(inv.onhand_qty, 0) AS onhand_qty
      FROM ORACLE_SQL.ORDERLINES ol
      INNER JOIN ORACLE_SQL.PRODUCTS p
        ON p.id = ol.product_id
      LEFT OUTER JOIN (
        SELECT i.product_id,
               SUM(i.qty) AS onhand_qty
          FROM ORACLE_SQL.INVENTORY i
         GROUP BY i.product_id
      ) inv
        ON inv.product_id = ol.product_id
     WHERE ol.order_id = p_order_id
       AND ROWNUM <= co_report_limit
     ORDER BY ol.id;

  lv_lines NUMBER := 0;
  lv_ready NUMBER := 0;
  lv_short NUMBER := 0;
  lv_dummy ORACLE_SQL.ORDERS.id%TYPE;

  rec c_lines%ROWTYPE;
BEGIN
  -- Validate order exists (also ensures NO_DATA_FOUND is possible and handled)
  SELECT o.id
    INTO lv_dummy
    FROM ORACLE_SQL.ORDERS o
   WHERE o.id = p_order_id;

  DBMS_OUTPUT.PUT_LINE('Order ' || p_order_id || ' pick readiness report:');

  OPEN c_lines;
  LOOP
    FETCH c_lines INTO rec;
    EXIT WHEN c_lines%NOTFOUND;

    lv_lines := lv_lines + 1;

    IF rec.onhand_qty >= rec.ordered_qty THEN
      lv_ready := lv_ready + 1;
      DBMS_OUTPUT.PUT_LINE(
        'Line ' || rec.line_id || ': product ' || rec.product_name ||
        ' ordered=' || rec.ordered_qty || ' on_hand=' || rec.onhand_qty ||
        ' => ' || 'READY'
      );
    ELSE
      lv_short := lv_short + 1;
      DBMS_OUTPUT.PUT_LINE(
        'Line ' || rec.line_id || ': product ' || rec.product_name ||
        ' ordered=' || rec.ordered_qty || ' on_hand=' || rec.onhand_qty ||
        ' => ' || 'SHORT'
      );
    END IF;
  END LOOP;
  CLOSE c_lines;

  IF lv_lines = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Summary: lines=' || lv_lines || ', ready=' || lv_ready || ', short=' || lv_short);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_lines%ISOPEN THEN
      CLOSE c_lines;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF c_lines%ISOPEN THEN
      CLOSE c_lines;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF c_lines%ISOPEN THEN
      CLOSE c_lines;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END wh_picklist_report;
/

CREATE OR REPLACE PROCEDURE report_channel_latest_sales(
  p_channel_id IN COMPLEX_ORACLE.SALES.channel_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_channel_desc    COMPLEX_ORACLE.CHANNELS.channel_desc%TYPE;
  lv_latest_time_id  COMPLEX_ORACLE.SALES.time_id%TYPE;
  ln_sales_day_count PLS_INTEGER;
BEGIN
  -- Basic input validation
  IF p_channel_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Channel ID: ' || p_channel_id);
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
    RETURN;
  END IF;

  -- 1) Look up channel description
  SELECT c.channel_desc
    INTO lv_channel_desc
    FROM COMPLEX_ORACLE.CHANNELS c
   WHERE c.channel_id = p_channel_id;

  DBMS_OUTPUT.PUT_LINE('Channel ID: ' || p_channel_id);
  DBMS_OUTPUT.PUT_LINE('Channel: ' || lv_channel_desc);

  -- 2) Latest sales date for that channel
  SELECT MAX(s.time_id)
    INTO lv_latest_time_id
    FROM COMPLEX_ORACLE.SALES s
   WHERE s.channel_id = p_channel_id;

  -- 4) Control flow: if no sales, print message and stop
  IF lv_latest_time_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No sales found for channel ' || p_channel_id || '.');
    RETURN;
  END IF;

  -- Ensure the day actually has rows (defensive check)
  SELECT COUNT(*)
    INTO ln_sales_day_count
    FROM COMPLEX_ORACLE.SALES s
   WHERE s.channel_id = p_channel_id
     AND s.time_id = lv_latest_time_id;

  IF ln_sales_day_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No sales found for channel ' || p_channel_id || '.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Latest sales date: ' || TO_CHAR(lv_latest_time_id, 'YYYY-MM-DD'));
  DBMS_OUTPUT.PUT_LINE('Top products on latest date (by amount_sold):');

  -- 3) Print up to 15 products sold on that date, highest amount first
  FOR rec IN (
    SELECT s.prod_id,
           s.quantity_sold,
           s.amount_sold
      FROM COMPLEX_ORACLE.SALES s
     WHERE s.channel_id = p_channel_id
       AND s.time_id = lv_latest_time_id
     ORDER BY s.amount_sold DESC, s.prod_id
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('  PROD_ID=' || rec.prod_id || '  QTY=' || rec.quantity_sold || '  AMT=' || rec.amount_sold);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_channel_latest_sales;
/

CREATE OR REPLACE PROCEDURE report_landmark_station_status(
  p_landmark IN SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_station_count PLS_INTEGER := 0;
  lv_status_count  PLS_INTEGER := 0;
  lv_printed       PLS_INTEGER := 0;

  lv_status        VARCHAR2(10);
BEGIN
  IF p_landmark IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Landmark is required.');
    RETURN;
  END IF;

  -- Verify landmark has stations
  SELECT COUNT(*)
    INTO lv_station_count
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
   WHERE s.landmark = p_landmark;

  IF lv_station_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark: ' || p_landmark);
    RETURN;
  END IF;

  -- Verify those stations have at least one status snapshot
  SELECT COUNT(*)
    INTO lv_status_count
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
    JOIN SAN_FRANCISCO.BIKESHARE_STATUS st
      ON st.station_id = s.station_id
   WHERE s.landmark = p_landmark;

  IF lv_status_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No status snapshots found for landmark: ' || p_landmark);
    RETURN;
  END IF;

  -- Print up to N stations using the most recent status time per station
  FOR rec IN (
    WITH latest_status AS (
      SELECT st.station_id,
             st.bikes_available,
             st.docks_available,
             st.time,
             ROW_NUMBER() OVER (PARTITION BY st.station_id ORDER BY st.time DESC) AS rn
        FROM SAN_FRANCISCO.BIKESHARE_STATUS st
    )
    SELECT s.name,
           s.dockcount,
           ls.bikes_available,
           ls.docks_available
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
      JOIN latest_status ls
        ON ls.station_id = s.station_id
       AND ls.rn = 1
     WHERE s.landmark = p_landmark
       AND ROWNUM <= co_report_limit
     ORDER BY s.name
  ) LOOP
    IF TO_NUMBER(rec.bikes_available) = 0 THEN
      lv_status := 'EMPTY';
    ELSIF TO_NUMBER(rec.docks_available) = 0 THEN
      lv_status := 'FULL';
    ELSE
      lv_status := 'OK';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Station: ' || rec.name ||
      ' | Dockcount: ' || rec.dockcount ||
      ' | Bikes: ' || rec.bikes_available ||
      ' | Docks: ' || rec.docks_available ||
      ' | Status: ' || lv_status
    );

    lv_printed := lv_printed + 1;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Stations printed: ' || lv_printed);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_landmark_station_status;
/

