Operations wants a quick on-screen report for a given departure airport code. Build an anonymous PL/SQL block that:
Validates the airport code is not NULL.
Looks up the airport name and city.
Prints a small summary of up to 15 upcoming scheduled flights departing from that airport (flight number, scheduled departure, status, arrival airport).
Adds a simple label for each flight based on its status (for example, treat 'Cancelled' specially; otherwise treat it as 'Operating').
Handles error scenarios safely so no runtime error is shown.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output:
DBMS_OUTPUT.PUT_LINE('Airport: ' || lv_departure_airport || ' - ' || lv_airport_name || ' (' || lv_city || ')');
DBMS_OUTPUT.PUT_LINE('No flights found for this departure airport.');
DBMS_OUTPUT.PUT_LINE('Flight ' || rec.flight_no || ' | Dep ' || TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI') || ' | Arr ' || rec.arrival_airport || ' | Status ' || rec.status || ' | Label ' || lv_label);
DBMS_OUTPUT.PUT_LINE('Departure airport code is required.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_departure_airport AIRLINES.FLIGHTS.departure_airport%TYPE := 'SVO';

  lv_airport_name      AIRLINES.AIRPORTS_DATA.airport_name%TYPE;
  lv_city              AIRLINES.AIRPORTS_DATA.city%TYPE;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_flight_count PLS_INTEGER := 0;
  lv_label        VARCHAR2(30);
BEGIN
  IF lv_departure_airport IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Departure airport code is required.');
    RETURN;
  END IF;

  SELECT ad.airport_name,
         ad.city
    INTO lv_airport_name,
         lv_city
    FROM AIRLINES.AIRPORTS_DATA ad
   WHERE ad.airport_code = lv_departure_airport;

  DBMS_OUTPUT.PUT_LINE(
    'Airport: ' || lv_departure_airport || ' - ' || lv_airport_name || ' (' || lv_city || ')'
  );

  FOR rec IN (
    SELECT f.flight_no,
           f.scheduled_departure,
           f.status,
           f.arrival_airport
      FROM AIRLINES.FLIGHTS f
     WHERE f.departure_airport = lv_departure_airport
       AND f.scheduled_departure >= SYSTIMESTAMP
     ORDER BY f.scheduled_departure
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_flight_count := lv_flight_count + 1;

    IF rec.status = 'Cancelled' THEN
      lv_label := 'Cancelled';
    ELSE
      lv_label := 'Operating';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Flight ' || rec.flight_no ||
      ' | Dep ' || TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
      ' | Arr ' || rec.arrival_airport ||
      ' | Status ' || rec.status ||
      ' | Label ' || lv_label
    );
  END LOOP;

  IF lv_flight_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No flights found for this departure airport.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

