CREATE OR REPLACE PROCEDURE report_driver_results(
  p_year    IN F1.RACES.YEAR%TYPE,
  p_surname IN F1.DRIVERS.SURNAME%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_driver_id   F1.DRIVERS.DRIVER_ID%TYPE;
  lv_driver_name F1.DRIVERS.FORENAME%TYPE;
  lv_rows        PLS_INTEGER := 0;
BEGIN
  IF p_year IS NULL OR p_surname IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year and surname are required.');
    RETURN;
  END IF;

  -- Resolve a single driver by surname.
  SELECT d.driver_id,
         d.forename || ' ' || d.surname
    INTO lv_driver_id,
         lv_driver_name
    FROM F1.DRIVERS d
   WHERE d.surname = p_surname;

  DBMS_OUTPUT.PUT_LINE('Driver: ' || lv_driver_name || ' (driver_id=' || lv_driver_id || '), Year: ' || p_year);

  -- Print up to 15 race results (earliest first).
  FOR rec IN (
    SELECT r.c_date,
           r.name AS race_name,
           res.grid,
           res.position_text,
           res.points
      FROM F1.RACES r
      INNER JOIN F1.RESULTS res
        ON res.race_id = r.race_id
     WHERE r.year = p_year
       AND res.driver_id = lv_driver_id
     ORDER BY r.c_date ASC, r.race_id ASC
  ) LOOP
    EXIT WHEN lv_rows >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Date=' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') ||
      ', Race=' || rec.race_name ||
      ', Grid=' || rec.grid ||
      ', Finish=' || rec.position_text ||
      ', Points=' || rec.points
    );

    lv_rows := lv_rows + 1;
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple drivers match that surname.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_driver_results;
/

CREATE OR REPLACE PROCEDURE pr_runner_delivery_report(
  p_runner_id IN MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS.runner_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_report_rows  PLS_INTEGER := 0;
  lv_speed_rows   PLS_INTEGER := 0;
  lv_speed_sum    NUMBER := 0;

  lv_avg_speed    NUMBER;
BEGIN
  -- Basic input validation
  IF p_runner_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Runner Delivery Report - Runner ID: ' || p_runner_id);
  DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');

  FOR rec IN (
    WITH successful_orders AS (
      SELECT r.order_id,
             r.pickup_time,
             r.distance,
             r.duration
        FROM MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS r
       WHERE r.runner_id = p_runner_id
         AND r.cancellation IS NULL
       ORDER BY r.pickup_time DESC
    ),
    limited_orders AS (
      SELECT so.order_id,
             so.pickup_time,
             so.distance,
             so.duration
        FROM successful_orders so
       WHERE ROWNUM <= co_report_limit
    ),
    pizzas_per_order AS (
      SELECT co.order_id,
             LISTAGG(pn.pizza_name, ', ') WITHIN GROUP (ORDER BY pn.pizza_name) AS pizza_names
        FROM MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS co
        INNER JOIN MODERN_DATA.PIZZA_NAMES pn
          ON pn.pizza_id = co.pizza_id
       GROUP BY co.order_id
    )
    SELECT lo.order_id,
           lo.pickup_time,
           lo.distance,
           lo.duration,
           NVL(p.pizza_names, 'UNKNOWN') AS pizza_names
      FROM limited_orders lo
      LEFT OUTER JOIN pizzas_per_order p
        ON p.order_id = lo.order_id
     ORDER BY lo.pickup_time DESC
  ) LOOP
    lv_report_rows := lv_report_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      'Order ID: ' || rec.order_id ||
      ' | Pickup: ' || rec.pickup_time ||
      ' | Distance: ' || rec.distance ||
      ' | Duration: ' || rec.duration ||
      ' | Speed: ' || CASE
                        WHEN rec.duration > 0 THEN TO_CHAR(ROUND(rec.distance / rec.duration, 4))
                        ELSE 'N/A'
                      END
    );
    DBMS_OUTPUT.PUT_LINE('  Pizzas: ' || rec.pizza_names);

    IF rec.duration > 0 THEN
      lv_speed_rows := lv_speed_rows + 1;
      lv_speed_sum  := lv_speed_sum + (rec.distance / rec.duration);
    END IF;
  END LOOP;

  IF lv_report_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No successful deliveries found for this runner.');
  END IF;

  DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
  DBMS_OUTPUT.PUT_LINE('Successful deliveries in report: ' || lv_report_rows);

  DBMS_OUTPUT.PUT_LINE(
    'Average speed (distance/duration) over non-zero durations: ' ||
    CASE
      WHEN lv_speed_rows > 0 THEN TO_CHAR(ROUND(lv_speed_sum / lv_speed_rows, 4))
      ELSE 'N/A'
    END
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END pr_runner_delivery_report;
/

CREATE OR REPLACE PROCEDURE report_payer_encounter_costs(
  p_payer_id IN SYNTHEA.ENCOUNTERS.payer%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_encounter_count NUMBER := 0;
BEGIN
  -- Guard against a NULL payer identifier before any further processing.
  IF p_payer_id IS NULL THEN
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Payer encounter cost snapshot for payer_id=' || p_payer_id);

  -- Implicit cursor FOR loop: iterate over the most recent encounters for the payer.
  FOR rec IN (
    SELECT e.start_timestamp,
           e.encounterclass,
           e.total_claim_cost,
           e.payer_coverage,
           (e.total_claim_cost - e.payer_coverage) AS patient_responsibility
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.payer = p_payer_id
     ORDER BY e.start_timestamp DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_encounter_count := lv_encounter_count + 1;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rec.start_timestamp, 'YYYY-MM-DD HH24:MI') || ' | ' ||
      rec.encounterclass || ' | total=' ||
      TO_CHAR(rec.total_claim_cost,      'FM9999999990D00') || ' | coverage=' ||
      TO_CHAR(rec.payer_coverage,        'FM9999999990D00') || ' | patient_resp=' ||
      TO_CHAR(rec.patient_responsibility,'FM9999999990D00')
    );
  END LOOP;

  -- A valid payer ID that simply has no encounters produces a friendly message
  -- rather than an exception, distinguishing it from a missing or NULL payer.
  IF lv_encounter_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for payer_id=' || p_payer_id);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_payer_encounter_costs;
/

