CREATE OR REPLACE PROCEDURE rpt_patient_allergy_snapshot(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_patient_name  VARCHAR2(250);
  lv_allergy_cnt   NUMBER;
BEGIN
  IF p_patient_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
    RETURN;
  END IF;

  -- Fetch patient display name (single-row expected)
  SELECT p.first || ' ' || p.last
    INTO lv_patient_name
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  -- Count allergy records for header
  SELECT COUNT(*)
    INTO lv_allergy_cnt
    FROM SYNTHEA.ALLERGIES a
   WHERE a.patient = p_patient_id;

  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient_name);
  DBMS_OUTPUT.PUT_LINE('Allergy records: ' || lv_allergy_cnt);

  IF lv_allergy_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No allergies found for patient.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('---- Recent Allergies (max ' || co_report_limit || ') ----');

  -- Detail lines (implicit cursor FOR loop; limited to most recent records)
  FOR rec IN (
    SELECT a.start_date,
           a.stop_date,
           a.description
      FROM SYNTHEA.ALLERGIES a
     WHERE a.patient = p_patient_id
     ORDER BY a.start_date DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rec.start_date, 'YYYY-MM-DD') || ' to ' ||
      TO_CHAR(NVL(rec.stop_date, rec.start_date), 'YYYY-MM-DD') ||
      ' | ' || rec.description
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No patient found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple patients returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_patient_allergy_snapshot;
/

