      FROM SYNTHEA.ALLERGIES a
     WHERE a.patient = p_patient_id
     ORDER BY a.start_date DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rec.start_date, 'YYYY-MM-DD') || ' to ' ||
      TO_CHAR(NVL(rec.stop_date, rec.start_date), 'YYYY-MM-DD') ||
      ' | ' || rec.description
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No patient found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple patients returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_patient_allergy_snapshot;
/

CREATE OR REPLACE PROCEDURE print_country_debt_snapshot(
  p_country_code       IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.country_code%TYPE,
  p_year               IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE,
  p_indicator_keyword  IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_short_name    WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.short_name%TYPE;
  lv_region        WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE;
  lv_income_group  WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE;

  lv_value_num     NUMBER;
  lv_category      VARCHAR2(10);
  lv_printed_count PLS_INTEGER := 0;

  -- Simple categorization thresholds. (Units differ by indicator; this is for exercise purposes.)
  co_high_threshold   CONSTANT NUMBER := 1000000000; -- 1B
  co_medium_threshold CONSTANT NUMBER := 1000000;    -- 1M
BEGIN
  DBMS_OUTPUT.PUT_LINE('Snapshot for country_code=' || p_country_code || ', year=' || p_year || ', keyword=' || p_indicator_keyword);

  -- Input validation
  IF p_country_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: country code is required.');
    RETURN;
  ELSIF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year is required.');
    RETURN;
  ELSIF p_indicator_keyword IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: indicator keyword is required.');
    RETURN;
  END IF;

  -- Country enrichment (single-row expectation)
  SELECT cs.short_name,
         cs.region,
         cs.income_group
    INTO lv_short_name,
         lv_region,
         lv_income_group
    FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
   WHERE cs.country_code = p_country_code;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_short_name || ' (' || p_country_code || '), Region=' || lv_region || ', Income Group=' || lv_income_group);

  DBMS_OUTPUT.PUT_LINE(RPAD('Indicator', 70, ' ') || ' | ' || LPAD('Value', 16, ' ') || ' | ' || 'Category');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-') || '-+-' || LPAD('-', 16, '-') || '-+-' || RPAD('-', 8, '-'));

  -- Pull a small snapshot of matching indicators; handle VALUE conversion safely per row.
  FOR rec IN (
    SELECT id.indicator_name,
           id.value
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
     WHERE id.country_code = p_country_code
       AND id.year = p_year
       AND UPPER(id.indicator_name) LIKE '%' || UPPER(p_indicator_keyword) || '%'
     ORDER BY id.indicator_name
  ) LOOP
    EXIT WHEN lv_printed_count >= co_report_limit;

    -- VALUE is stored as text; attempt conversion and categorize.
    BEGIN
      lv_value_num := TO_NUMBER(rec.value);

      IF lv_value_num >= co_high_threshold THEN
        lv_category := 'HIGH';
      ELSIF lv_value_num >= co_medium_threshold THEN
        lv_category := 'MEDIUM';
      ELSE
        lv_category := 'LOW';
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.indicator_name, 70, ' ') || ' | ' ||
        LPAD(TO_CHAR(lv_value_num, 'FM9999999999990D00'), 16, ' ') || ' | ' ||
        lv_category
      );

      lv_printed_count := lv_printed_count + 1;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        -- Skip non-numeric values without failing the report.
        NULL;
      WHEN INVALID_NUMBER THEN
        -- Skip non-numeric values without failing the report.
        NULL;
    END;
  END LOOP;

  IF lv_printed_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matching indicators found for the given filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END print_country_debt_snapshot;
/

