question:
Build a reusable package that generates a small “indicator health check” report for a given World Bank indicator code.

The report should:
- Validate the requested indicator code exists in the metadata.
- Iterate through up to 15 countries that have data for that indicator and compute how complete the time series is per country (min year, max year, count of non-null numeric values).
- Only treat VALUE rows as numeric if they can be converted to NUMBER; ignore other rows (e.g., blank strings).
- Print one report line per country in descending order of numeric value count.
- Print a final summary line showing totals across the reported countries.
- Handle cases where the indicator code doesn’t exist, or no qualifying numeric values exist for the indicator.

Requirements:
Procedure Name: wdi_health_pkg.report_indicator_health
Parameters:
p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Indicator: ' || lv_indicator_code || ' - ' || lv_indicator_name);
DBMS_OUTPUT.PUT_LINE('Top ' || co_report_limit || ' countries by numeric value count (min/max year shown):');
DBMS_OUTPUT.PUT_LINE('  ' || RPAD(rec.short_name, 35, ' ') || ' | ' || RPAD(rec.country_code, 10, ' ') || ' | ' || 'min=' || rec.min_year || ', max=' || rec.max_year || ', cnt=' || rec.numeric_cnt);
DBMS_OUTPUT.PUT_LINE('Summary: countries=' || lv_country_rows || ', total_numeric_values=' || lv_total_numeric_values);
DBMS_OUTPUT.PUT_LINE('No numeric indicator values found for indicator code ' || lv_indicator_code || '.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE wdi_health_pkg IS
  PROCEDURE report_indicator_health(
    p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE
  );
END wdi_health_pkg;
/

CREATE OR REPLACE PACKAGE BODY wdi_health_pkg IS

  PROCEDURE report_indicator_health(
    p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE := TRIM(p_indicator_code);
    lv_indicator_name WORLD_BANK_WDI.SERIES_SUMMARY.indicator_name%TYPE;

    lv_country_rows         PLS_INTEGER := 0;
    lv_total_numeric_values PLS_INTEGER := 0;

    CURSOR c_country_health(p_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE) IS
      WITH numeric_vals AS (
        SELECT d.country_code,
               d.year,
               TO_NUMBER(TRIM(d.value)) AS num_val
          FROM WORLD_BANK_WDI.INDICATORS_DATA d
         WHERE d.indicator_code = p_code
           AND REGEXP_LIKE(TRIM(d.value), '^[+-]?\d+(\.\d+)?$')
      ), agg AS (
        SELECT nv.country_code,
               MIN(TO_NUMBER(nv.year)) AS min_year,
               MAX(TO_NUMBER(nv.year)) AS max_year,
               COUNT(*)                AS numeric_cnt
          FROM numeric_vals nv
         GROUP BY nv.country_code
      ), ranked AS (
        SELECT a.country_code,
               a.min_year,
               a.max_year,
               a.numeric_cnt,
               ROW_NUMBER() OVER (ORDER BY a.numeric_cnt DESC, a.country_code ASC) AS rn
          FROM agg a
      )
      SELECT cs.short_name,
             r.country_code,
             r.min_year,
             r.max_year,
             r.numeric_cnt
        FROM ranked r
        INNER JOIN WORLD_BANK_WDI.COUNTRY_SUMMARY cs
          ON cs.country_code = r.country_code
       WHERE r.rn <= co_report_limit
       ORDER BY r.numeric_cnt DESC, r.country_code ASC;

  BEGIN
    IF lv_indicator_code IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    -- Validate that the indicator exists (metadata lookup)
    SELECT s.indicator_name
      INTO lv_indicator_name
      FROM WORLD_BANK_WDI.SERIES_SUMMARY s
     WHERE s.series_code = lv_indicator_code;

    DBMS_OUTPUT.PUT_LINE('Indicator: ' || lv_indicator_code || ' - ' || lv_indicator_name);
    DBMS_OUTPUT.PUT_LINE('Top ' || co_report_limit || ' countries by numeric value count (min/max year shown):');

    FOR rec IN c_country_health(lv_indicator_code) LOOP
      lv_country_rows := lv_country_rows + 1;
      lv_total_numeric_values := lv_total_numeric_values + rec.numeric_cnt;

      DBMS_OUTPUT.PUT_LINE('  ' || RPAD(rec.short_name, 35, ' ') || ' | ' || RPAD(rec.country_code, 10, ' ') || ' | ' || 'min=' || rec.min_year || ', max=' || rec.max_year || ', cnt=' || rec.numeric_cnt);
    END LOOP;

    IF lv_country_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No numeric indicator values found for indicator code ' || lv_indicator_code || '.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Summary: countries=' || lv_country_rows || ', total_numeric_values=' || lv_total_numeric_values);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_indicator_health;

END wdi_health_pkg;
/

