CREATE OR REPLACE PROCEDURE report_top_intersectional_rep(
  p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE,
  p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_report_year  GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE;
  lv_workforce    GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Default to latest year if not provided.
  IF p_report_year IS NULL THEN
    SELECT MAX(t.report_year)
      INTO lv_report_year
      FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION t;
  ELSE
    lv_report_year := p_report_year;
  END IF;

  -- Default to most common workforce if not provided.
  IF p_workforce IS NULL THEN
    SELECT x.workforce
      INTO lv_workforce
      FROM (
        SELECT t.workforce
          FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION t
         GROUP BY t.workforce
         ORDER BY COUNT(*) DESC, t.workforce ASC
      ) x
     WHERE ROWNUM = 1;
  ELSE
    lv_workforce := p_workforce;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Effective filters -> REPORT_YEAR=' || lv_report_year || ', WORKFORCE=' || lv_workforce);

  -- Print up to 15 rows with the highest combined race indicator score.
  FOR r IN (
    SELECT y.gender_us,
           y.race_asian,
           y.race_black,
           y.race_hispanic_latinx,
           y.race_native_american,
           y.race_white,
           (CASE WHEN y.race_asian = 'Yes' THEN 1 ELSE 0 END +
            CASE WHEN y.race_black = 'Yes' THEN 1 ELSE 0 END +
            CASE WHEN y.race_hispanic_latinx = 'Yes' THEN 1 ELSE 0 END +
            CASE WHEN y.race_native_american = 'Yes' THEN 1 ELSE 0 END +
            CASE WHEN y.race_white = 'Yes' THEN 1 ELSE 0 END) AS race_score
      FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION y
     WHERE y.report_year = lv_report_year
       AND y.workforce = lv_workforce
     ORDER BY race_score DESC, y.gender_us ASC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      'GENDER_US=' || r.gender_us ||
      ', ASIAN=' || r.race_asian ||
      ', BLACK=' || r.race_black ||
      ', HISPANIC_LATINX=' || r.race_hispanic_latinx ||
      ', NATIVE_AMERICAN=' || r.race_native_american ||
      ', WHITE=' || r.race_white ||
      ' | SCORE=' || r.race_score
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched for the selected filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_intersectional_rep;
/

CREATE OR REPLACE PROCEDURE cpiu_print_area_item_year(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_item_name IN BLS.CPI_U.item_name%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
  lv_value_num    NUMBER;
  lv_value_to_print VARCHAR2(30);
BEGIN
  -- Basic input validation
  IF p_area_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: area_name is required.');
    RETURN;
  ELSIF p_item_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: item_name is required.');
    RETURN;
  ELSIF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI-U for ' || p_area_name || ' / ' || p_item_name || ' / ' || p_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('PERIOD', 12) || 'VALUE');

  FOR rec IN (
    SELECT c.period,
           c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND c.year = p_year
     ORDER BY c.period
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    -- Convert VALUE to a number when possible; otherwise show N/A
    BEGIN
      lv_value_num := TO_NUMBER(rec.value);
      lv_value_to_print := TO_CHAR(lv_value_num);
    EXCEPTION
      WHEN OTHERS THEN
        lv_value_to_print := 'N/A';
    END;

    DBMS_OUTPUT.PUT_LINE(RPAD(rec.period, 12) || lv_value_to_print);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Rows printed: ' || lv_rows_printed);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpiu_print_area_item_year;
/

CREATE OR REPLACE PROCEDURE report_top_birth_counties(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input year is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top counties by births for year=' || TO_CHAR(p_year, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE(RPAD('COUNTY', 30) || ' ' || RPAD('FIPS', 10) || ' ' || 'BIRTHS');

  FOR r IN (
    WITH cleaned AS (
      SELECT
        cn.county_of_residence,
        cn.county_of_residence_fips,
        TO_NUMBER(cn.births DEFAULT NULL ON CONVERSION ERROR) AS births_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
      WHERE cn.year = p_year
    )
    SELECT
      c.county_of_residence,
      c.county_of_residence_fips,
      c.births_num
    FROM cleaned c
    WHERE c.births_num IS NOT NULL
    ORDER BY c.births_num DESC, c.county_of_residence
    FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(r.county_of_residence, 30) || ' ' ||
      RPAD(r.county_of_residence_fips, 10) || ' ' ||
      TO_CHAR(r.births_num)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_birth_counties;
/

