question:
Create a reusable procedure that produces a small, patient-specific utilization snapshot for a care management dashboard.

Given a patient id, the procedure should:
Validate the input (NULL or blank should be handled gracefully).
Retrieve and print the patient name.
Retrieve and print counts of encounters, allergies, conditions, medications, and immunizations for that patient.
Based on total encounters, classify the patient as LOW/MEDIUM/HIGH utilization.
Keep the output readable (limit any detail queries to a maximum of 15 rows, even if the patient has more data).
Make sure runtime errors never reach the client; print friendly messages instead.

Requirements:
Procedure Name: report_patient_utilization
Parameters:
p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Patient utilization snapshot');
DBMS_OUTPUT.PUT_LINE('Patient ID: ' || p_patient_id);
DBMS_OUTPUT.PUT_LINE('Patient Name: ' || lv_patient_name);
DBMS_OUTPUT.PUT_LINE('Encounters: ' || lv_encounters_cnt);
DBMS_OUTPUT.PUT_LINE('Allergies: ' || lv_allergies_cnt);
DBMS_OUTPUT.PUT_LINE('Conditions: ' || lv_conditions_cnt);
DBMS_OUTPUT.PUT_LINE('Medications: ' || lv_meds_cnt);
DBMS_OUTPUT.PUT_LINE('Immunizations: ' || lv_imms_cnt);
DBMS_OUTPUT.PUT_LINE('Utilization Level: ' || lv_util_level);
DBMS_OUTPUT.PUT_LINE('Recent encounter examples (up to ' || co_report_limit || '):');
DBMS_OUTPUT.PUT_LINE('  ' || TO_CHAR(r.start_timestamp, 'YYYY-MM-DD') || ' | ' || r.encounterclass || ' | ' || r.description);
DBMS_OUTPUT.PUT_LINE('Patient utilization snapshot');
DBMS_OUTPUT.PUT_LINE('Patient ID: ' || p_patient_id);
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid input value.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_patient_utilization(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for readability

  lv_patient_name  VARCHAR2(250);

  lv_encounters_cnt NUMBER;
  lv_allergies_cnt  NUMBER;
  lv_conditions_cnt NUMBER;
  lv_meds_cnt       NUMBER;
  lv_imms_cnt       NUMBER;

  lv_util_level     VARCHAR2(10);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Patient utilization snapshot');
  DBMS_OUTPUT.PUT_LINE('Patient ID: ' || p_patient_id);

  -- Basic input validation
  IF p_patient_id IS NULL OR TRIM(p_patient_id) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
    RETURN;
  END IF;

  -- Patient name (single-row expected)
  SELECT p.first || ' ' || p.last
    INTO lv_patient_name
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  DBMS_OUTPUT.PUT_LINE('Patient Name: ' || lv_patient_name);

  -- Counts by domain
  SELECT COUNT(*)
    INTO lv_encounters_cnt
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.patient = p_patient_id;

  SELECT COUNT(*)
    INTO lv_allergies_cnt
    FROM SYNTHEA.ALLERGIES a
   WHERE a.patient = p_patient_id;

  SELECT COUNT(*)
    INTO lv_conditions_cnt
    FROM SYNTHEA.CONDITIONS c
   WHERE c.patient = p_patient_id;

  SELECT COUNT(*)
    INTO lv_meds_cnt
    FROM SYNTHEA.MEDICATIONS m
   WHERE m.patient = p_patient_id;

  SELECT COUNT(*)
    INTO lv_imms_cnt
    FROM SYNTHEA.IMMUNIZATIONS i
   WHERE i.patient = p_patient_id;

  DBMS_OUTPUT.PUT_LINE('Encounters: ' || lv_encounters_cnt);
  DBMS_OUTPUT.PUT_LINE('Allergies: ' || lv_allergies_cnt);
  DBMS_OUTPUT.PUT_LINE('Conditions: ' || lv_conditions_cnt);
  DBMS_OUTPUT.PUT_LINE('Medications: ' || lv_meds_cnt);
  DBMS_OUTPUT.PUT_LINE('Immunizations: ' || lv_imms_cnt);

  -- Simple utilization classification
  IF lv_encounters_cnt >= 20 THEN
    lv_util_level := 'HIGH';
  ELSIF lv_encounters_cnt >= 5 THEN
    lv_util_level := 'MEDIUM';
  ELSE
    lv_util_level := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Utilization Level: ' || lv_util_level);

  -- Example detail output (row-limited)
  DBMS_OUTPUT.PUT_LINE('Recent encounter examples (up to ' || co_report_limit || '):');

  FOR r IN (
    SELECT e.start_timestamp, e.encounterclass, e.description
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id
     ORDER BY e.start_timestamp DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('  ' || TO_CHAR(r.start_timestamp, 'YYYY-MM-DD') || ' | ' || r.encounterclass || ' | ' || r.description);
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Patient utilization snapshot');
  DBMS_OUTPUT.PUT_LINE('Patient ID: ' || p_patient_id);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_patient_utilization;
