CREATE OR REPLACE PROCEDURE census_country_dashboard(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_start_year   IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE,
  p_end_year     IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country_code  CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_code%TYPE;
  lv_start_year_n  NUMBER;
  lv_end_year_n    NUMBER;

  CURSOR cur_years IS
    SELECT (lv_start_year_n + LEVEL - 1) AS year
      FROM dual
    CONNECT BY LEVEL <= (lv_end_year_n - lv_start_year_n + 1)
     ORDER BY year;

  lv_pop           NUMBER;
  lv_tfr           NUMBER;
  lv_le            NUMBER;
  lv_status        VARCHAR2(20);
  lv_rows_printed  PLS_INTEGER := 0;

  lv_has_pop        BOOLEAN;
  lv_has_tfr        BOOLEAN;
  lv_has_le         BOOLEAN;
BEGIN
  -- Input validation
  IF p_country_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country name is required.');
    RETURN;
  END IF;

  IF p_start_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: start year is required.');
    RETURN;
  END IF;

  IF p_end_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: end year is required.');
    RETURN;
  END IF;

  IF NOT REGEXP_LIKE(TRIM(p_start_year), '^[0-9]{4}$') OR NOT REGEXP_LIKE(TRIM(p_end_year), '^[0-9]{4}$') THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: years must be 4 digits.');
    RETURN;
  END IF;

  lv_start_year_n := TO_NUMBER(TRIM(p_start_year));
  lv_end_year_n   := TO_NUMBER(TRIM(p_end_year));

  IF lv_start_year_n > lv_end_year_n THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: start year must be <= end year.');
    RETURN;
  END IF;

  -- Resolve the country code (exact match on name)
  SELECT cna.country_code
    INTO lv_country_code
    FROM CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cna
   WHERE cna.country_name = p_country_name;

  DBMS_OUTPUT.PUT_LINE('Country dashboard for: ' || p_country_name || ' (' || lv_country_code || ')');
  DBMS_OUTPUT.PUT_LINE('Year range: ' || p_start_year || ' to ' || p_end_year || ' (max rows ' || co_report_limit || ')');

  -- Iterate years using an explicit named cursor
  FOR r_year IN cur_years LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    lv_pop := NULL;
    lv_tfr := NULL;
    lv_le  := NULL;

    lv_has_pop := FALSE;
    lv_has_tfr := FALSE;
    lv_has_le  := FALSE;

    -- Midyear population (may be missing for a year)
    BEGIN
      SELECT TO_NUMBER(mp.midyear_population)
        INTO lv_pop
        FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION mp
       WHERE mp.country_code = lv_country_code
         AND mp.year = r_year.year;
      lv_has_pop := TRUE;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        lv_has_pop := FALSE;
      WHEN TOO_MANY_ROWS THEN
        lv_has_pop := FALSE;
      WHEN OTHERS THEN
        lv_has_pop := FALSE;
    END;

    -- Total fertility rate (may be missing for a year)
    BEGIN
      SELECT TO_NUMBER(af.total_fertility_rate)
        INTO lv_tfr
        FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES af
       WHERE af.country_code = lv_country_code
         AND af.year = r_year.year;
      lv_has_tfr := TRUE;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        lv_has_tfr := FALSE;
      WHEN TOO_MANY_ROWS THEN
        lv_has_tfr := FALSE;
      WHEN OTHERS THEN
        lv_has_tfr := FALSE;
    END;

    -- Life expectancy (may be missing for a year)
    BEGIN
      SELECT TO_NUMBER(mle.life_expectancy)
        INTO lv_le
        FROM CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY mle
       WHERE mle.country_code = lv_country_code
         AND mle.year = r_year.year;
      lv_has_le := TRUE;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        lv_has_le := FALSE;
      WHEN TOO_MANY_ROWS THEN
        lv_has_le := FALSE;
      WHEN OTHERS THEN
        lv_has_le := FALSE;
    END;

    IF lv_has_pop AND lv_has_tfr AND lv_has_le THEN
      lv_status := 'DATA_OK';
    ELSE
      lv_status := 'MISSING_METRIC';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'YEAR=' || r_year.year ||
      ' | POP=' || NVL(TO_CHAR(lv_pop), 'NA') ||
      ' | TFR=' || NVL(TO_CHAR(lv_tfr), 'NA') ||
      ' | LIFE_EXP=' || NVL(TO_CHAR(lv_le), 'NA') ||
      ' | ' || lv_status
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Rows printed: ' || lv_rows_printed);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END census_country_dashboard;
/

