question:
As part of an F1 race-ops quick report, build a reusable stored procedure that accepts a season year and prints a small leaderboard of the top 10 drivers by total race points for that season. For each driver, print the drivers full name and the summed points. If the caller passes NULL, default the season to the most recent year in the races table. Also print a header that includes the effective season year used. Ensure the procedure gracefully handles cases where the year has no races or no results.

Requirements:
Procedure Name: report_top_drivers_by_year
Parameters:
p_year IN F1.RACES.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Season Year Used: ' || lv_year_used);
DBMS_OUTPUT.PUT_LINE('Top Drivers (max ' || co_report_limit || '):');
DBMS_OUTPUT.PUT_LINE(LPAD(lv_rank, 2, ' ') || '. ' || rec.driver_name || ' - Points: ' || rec.total_points);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_top_drivers_by_year(
  p_year IN F1.RACES.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 10; -- Limit output for report readability

  lv_year_used F1.RACES.year%TYPE;
  lv_rank      PLS_INTEGER := 0;
BEGIN
  -- Default NULL input to the most recent season year present in races.
  IF p_year IS NULL THEN
    SELECT MAX(r.year)
      INTO lv_year_used
      FROM F1.RACES r;
  ELSE
    lv_year_used := p_year;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Season Year Used: ' || lv_year_used);
  DBMS_OUTPUT.PUT_LINE('Top Drivers (max ' || co_report_limit || '):');

  -- Print up to the report limit.
  FOR rec IN (
    SELECT d.forename || ' ' || d.surname AS driver_name,
           SUM(res.points)               AS total_points
      FROM F1.RACES r
      JOIN F1.RESULTS res
        ON res.race_id = r.race_id
      JOIN F1.DRIVERS d
        ON d.driver_id = res.driver_id
     WHERE r.year = lv_year_used
     GROUP BY d.forename, d.surname
     ORDER BY SUM(res.points) DESC, d.surname, d.forename
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rank := lv_rank + 1;
    DBMS_OUTPUT.PUT_LINE(LPAD(lv_rank, 2, ' ') || '. ' || rec.driver_name || ' - Points: ' || rec.total_points);
  END LOOP;

  -- If the loop printed nothing, treat it as a no-data scenario for consistent messaging.
  IF lv_rank = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_drivers_by_year;
/

CREATE OR REPLACE PROCEDURE report_debt_snapshot(
  p_country_code   IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.country_code%TYPE,
  p_indicator_code IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_code%TYPE,
  p_year           IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_lookup_limit CONSTANT PLS_INTEGER := 15; -- Limit exploratory lookups for predictable runtime

  lv_country_code   WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.country_code%TYPE;
  lv_indicator_code WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_code%TYPE;
  lv_year           WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE;

  lv_short_name WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.short_name%TYPE;
  lv_region     WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE;

  lv_indicator_name WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_name%TYPE;
  lv_value_raw      WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.value%TYPE;
  lv_value_num      NUMBER;

  lv_year_num NUMBER;
BEGIN
  -- Required input validation
  IF p_country_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: country code is required.');
    RETURN;
  END IF;

  lv_country_code := p_country_code;

  -- Default the indicator code when not provided: pick the most common for the country
  IF p_indicator_code IS NULL THEN
    SELECT sub.indicator_code
      INTO lv_indicator_code
      FROM (
            SELECT id.indicator_code
              FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
             WHERE id.country_code = lv_country_code
             GROUP BY id.indicator_code
             ORDER BY COUNT(*) DESC, id.indicator_code
           ) sub
     WHERE ROWNUM = 1;
  ELSE
    lv_indicator_code := p_indicator_code;
  END IF;

  -- Default the year when not provided: pick maximum year available for country + indicator
  IF p_year IS NULL THEN
    SELECT MAX(id.year)
      INTO lv_year
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
     WHERE id.country_code = lv_country_code
       AND id.indicator_code = lv_indicator_code;
  ELSE
    lv_year := p_year;
  END IF;

  -- Validate year is numeric-like (stored as VARCHAR2 in source)
  lv_year_num := TO_NUMBER(lv_year);

  -- Lookup country context
  SELECT cs.short_name,
         cs.region
    INTO lv_short_name,
         lv_region
    FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
   WHERE cs.country_code = lv_country_code;

  -- Retrieve the single row of interest (may throw NO_DATA_FOUND / TOO_MANY_ROWS)
  SELECT id.indicator_name,
         id.value
    INTO lv_indicator_name,
         lv_value_raw
    FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
   WHERE id.country_code = lv_country_code
     AND id.indicator_code = lv_indicator_code
     AND id.year = lv_year;

  -- Convert stored VALUE (VARCHAR2) to numeric; trap conversion issues via VALUE_ERROR
  lv_value_num := TO_NUMBER(lv_value_raw);

  DBMS_OUTPUT.PUT_LINE('Debt Snapshot - Country: ' || lv_short_name || ' (' || lv_country_code || '), Region: ' || lv_region);
  DBMS_OUTPUT.PUT_LINE('Indicator: ' || lv_indicator_name || ' (' || lv_indicator_code || '), Year: ' || lv_year);
  DBMS_OUTPUT.PUT_LINE('Value: ' || TO_CHAR(lv_value_num));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Value conversion failed: stored VALUE is not numeric.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_debt_snapshot;
/

question:
Your economics team wants a quick “sanity-check” report for a single CPI item in a single area, focused on one calendar year.

Build an anonymous PL/SQL block that:
Finds the most recent CPI value in that year for the given area/item (based on C_DATE).
Finds the earliest CPI value in that year for the same area/item.
 Calculates the percent change between earliest and latest. Classifies the year as:
    'UP' if percent change > 0
    'DOWN' if percent change < 0
    'FLAT' if percent change = 0
 Prints a small, readable report via DBMS_OUTPUT, including area, item, year, earliest date/value, latest date/value, percent change (rounded to 2 decimals), and the trend classification.

Make sure the block is robust:
 Treat VALUE as numeric even though it is stored as VARCHAR2 (convert safely).
 If no rows exist for that area/item/year, print a clear message.
 If the selection logic accidentally returns multiple rows, handle it cleanly.
 Do not let any runtime error escape to the client.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('CPI Trend Report');
DBMS_OUTPUT.PUT_LINE('Area: ' || lv_area_name);
DBMS_OUTPUT.PUT_LINE('Item: ' || lv_item_name);
DBMS_OUTPUT.PUT_LINE('Year: ' || p_year);
DBMS_OUTPUT.PUT_LINE('Earliest: ' || TO_CHAR(lv_earliest_date, 'YYYY-MM-DD') || ' value=' || TO_CHAR(lv_earliest_value));
DBMS_OUTPUT.PUT_LINE('Latest:   ' || TO_CHAR(lv_latest_date, 'YYYY-MM-DD') || ' value=' || TO_CHAR(lv_latest_value));
DBMS_OUTPUT.PUT_LINE('Percent change: ' || TO_CHAR(ROUND(lv_pct_change, 2)) || '%');
DBMS_OUTPUT.PUT_LINE('Trend: ' || lv_trend);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid numeric value encountered.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  -- Inputs (set as needed)
  p_area_name BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  p_item_name BLS.CPI_U.item_name%TYPE := 'All items';
  p_year      BLS.CPI_U.year%TYPE      := '2020';

  -- Row-limiting constant for deterministic single-row picks
  co_pick_one CONSTANT PLS_INTEGER := 1; -- Ensure only one earliest/latest row is chosen

  lv_area_name      BLS.CPI_U.area_name%TYPE;
  lv_item_name      BLS.CPI_U.item_name%TYPE;

  lv_earliest_date  BLS.CPI_U.c_date%TYPE;
  lv_latest_date    BLS.CPI_U.c_date%TYPE;

  lv_earliest_value NUMBER;
  lv_latest_value   NUMBER;

  lv_pct_change     NUMBER;
  lv_trend          VARCHAR2(10);
BEGIN
  -- Latest row in the year
  SELECT q.area_name,
         q.item_name,
         q.c_date,
         TO_NUMBER(q.value)
    INTO lv_area_name,
         lv_item_name,
         lv_latest_date,
         lv_latest_value
    FROM (
          SELECT c.area_name,
                 c.item_name,
                 c.c_date,
                 c.value
            FROM BLS.CPI_U c
           WHERE c.area_name = p_area_name
             AND c.item_name = p_item_name
             AND c.year = p_year
           ORDER BY c.c_date DESC
         ) q
   WHERE ROWNUM = co_pick_one;

  -- Earliest row in the year
  SELECT q.c_date,
         TO_NUMBER(q.value)
    INTO lv_earliest_date,
         lv_earliest_value
    FROM (
          SELECT c.c_date,
                 c.value
            FROM BLS.CPI_U c
           WHERE c.area_name = p_area_name
             AND c.item_name = p_item_name
             AND c.year = p_year
           ORDER BY c.c_date ASC
         ) q
   WHERE ROWNUM = co_pick_one;

  IF lv_earliest_value = 0 THEN
    lv_pct_change := 0;
  ELSE
    lv_pct_change := ((lv_latest_value - lv_earliest_value) / lv_earliest_value) * 100;
  END IF;

  IF lv_pct_change > 0 THEN
    lv_trend := 'UP';
  ELSIF lv_pct_change < 0 THEN
    lv_trend := 'DOWN';
  ELSE
    lv_trend := 'FLAT';
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI Trend Report');
  DBMS_OUTPUT.PUT_LINE('Area: ' || lv_area_name);
  DBMS_OUTPUT.PUT_LINE('Item: ' || lv_item_name);
  DBMS_OUTPUT.PUT_LINE('Year: ' || p_year);
  DBMS_OUTPUT.PUT_LINE('Earliest: ' || TO_CHAR(lv_earliest_date, 'YYYY-MM-DD') || ' value=' || TO_CHAR(lv_earliest_value));
  DBMS_OUTPUT.PUT_LINE('Latest:   ' || TO_CHAR(lv_latest_date, 'YYYY-MM-DD') || ' value=' || TO_CHAR(lv_latest_value));
  DBMS_OUTPUT.PUT_LINE('Percent change: ' || TO_CHAR(ROUND(lv_pct_change, 2)) || '%');
  DBMS_OUTPUT.PUT_LINE('Trend: ' || lv_trend);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

