CREATE OR REPLACE PROCEDURE cpi_movement_check(
  p_item_name  IN BLS.CPI_U.item_name%TYPE,
  p_area_name  IN BLS.CPI_U.area_name%TYPE,
  p_start_year IN BLS.CPI_U.year%TYPE,
  p_end_year   IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR cur_cpi IS
    SELECT c.c_date,
           c.period,
           c.value
      FROM BLS.CPI_U c
     WHERE c.item_name = p_item_name
       AND c.area_name = p_area_name
       AND c.period LIKE 'M%'
       AND c.year BETWEEN p_start_year AND p_end_year
     ORDER BY c.c_date;

  lv_cdate           BLS.CPI_U.c_date%TYPE;
  lv_period          BLS.CPI_U.period%TYPE;
  lv_value_text      BLS.CPI_U.value%TYPE;
  lv_value_num       NUMBER;
  lv_prev_value_num  NUMBER;

  lv_rows_printed    PLS_INTEGER := 0;
  lv_has_prev        BOOLEAN := FALSE;

  lv_found_any       BOOLEAN := FALSE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI movement check for item="' || p_item_name || '", area="' || p_area_name || '", years ' || p_start_year || '-' || p_end_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));

  OPEN cur_cpi;
  LOOP
    FETCH cur_cpi INTO lv_cdate, lv_period, lv_value_text;
    EXIT WHEN cur_cpi%NOTFOUND;

    lv_found_any := TRUE;

    -- Validate and convert CPI value.
    lv_value_num := TO_NUMBER(lv_value_text);

    IF lv_rows_printed >= co_report_limit THEN
      EXIT;
    END IF;

    IF NOT lv_has_prev THEN
      DBMS_OUTPUT.PUT_LINE(
        'PeriodDate=' || TO_CHAR(lv_cdate, 'YYYY-MM-DD') ||
        ', Period=' || lv_period ||
        ', CPI=' || TO_CHAR(lv_value_num) ||
        ', Change=N/A'
      );
      lv_has_prev := TRUE;
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'PeriodDate=' || TO_CHAR(lv_cdate, 'YYYY-MM-DD') ||
        ', Period=' || lv_period ||
        ', CPI=' || TO_CHAR(lv_value_num) ||
        ', Change=' || TO_CHAR(ROUND(lv_value_num - lv_prev_value_num, 3))
      );
    END IF;

    lv_prev_value_num := lv_value_num;
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;
  CLOSE cur_cpi;

  IF NOT lv_found_any THEN
    -- Standardized no-data message for exercises.
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Total rows reported=' || lv_rows_printed);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF cur_cpi%ISOPEN THEN
      CLOSE cur_cpi;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF cur_cpi%ISOPEN THEN
      CLOSE cur_cpi;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN INVALID_NUMBER THEN
    IF cur_cpi%ISOPEN THEN
      CLOSE cur_cpi;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Invalid numeric CPI value encountered.');
  WHEN OTHERS THEN
    IF cur_cpi%ISOPEN THEN
      CLOSE cur_cpi;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_movement_check;
/

