question:
Your HR analytics team wants a small reusable reporting routine that summarizes the share of women employed by industry for a given year. Build a stored procedure that accepts a year (as a 4-character string) and prints up to 15 industries with the highest reported percent women, including the sector/subsector/group labels.

The procedure must validate the input year (must be exactly 4 digits). If the year is invalid, print a clear message and stop. If the year is valid but there are no rows, print a no-data message. Use simple control flow to enforce these rules and include exception handling so the routine never throws an unhandled error.

Requirements:
Procedure Name: report_top_women_employment
Parameters:
p_year IN BLS.CPSAAT18.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Top industries by percent women for year ' || p_year || ':');
DBMS_OUTPUT.PUT_LINE(RPAD('Industry', 40) || ' | ' || RPAD('Sector', 25) || ' | ' || RPAD('Subsector', 25) || ' | ' || RPAD('Industry Group', 25) || ' | ' || 'Percent Women');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 40, '-') || '-+-' || RPAD('-', 25, '-') || '-+-' || RPAD('-', 25, '-') || '-+-' || RPAD('-', 25, '-') || '-+-' || RPAD('-', 13, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(SUBSTR(rec.industry, 1, 40), 40) || ' | ' || RPAD(SUBSTR(rec.sector, 1, 25), 25) || ' | ' || RPAD(SUBSTR(rec.subsector, 1, 25), 25) || ' | ' || RPAD(SUBSTR(rec.industry_group, 1, 25), 25) || ' | ' || TO_CHAR(rec.pct_women));
DBMS_OUTPUT.PUT_LINE('No rows found for year ' || p_year || '.');
DBMS_OUTPUT.PUT_LINE('Invalid year. Provide exactly 4 digits (e.g., 2020).');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No rows found for year ' || p_year || '.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_top_women_employment(
  p_year IN BLS.CPSAAT18.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_row_count PLS_INTEGER := 0;
  lv_dummy     PLS_INTEGER;
BEGIN
  -- Validate input year: must be exactly 4 digits
  IF p_year IS NULL OR NOT REGEXP_LIKE(p_year, '^[0-9]{4}$') THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year. Provide exactly 4 digits (e.g., 2020).');
    RETURN;
  END IF;

  -- Force a NO_DATA_FOUND if no rows exist for the year (keeps behavior deterministic)
  SELECT 1
    INTO lv_dummy
    FROM BLS.CPSAAT18 c
   WHERE c.year = p_year
     AND ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Top industries by percent women for year ' || p_year || ':');
  DBMS_OUTPUT.PUT_LINE(RPAD('Industry', 40) || ' | ' || RPAD('Sector', 25) || ' | ' || RPAD('Subsector', 25) || ' | ' || RPAD('Industry Group', 25) || ' | ' || 'Percent Women');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 40, '-') || '-+-' || RPAD('-', 25, '-') || '-+-' || RPAD('-', 25, '-') || '-+-' || RPAD('-', 25, '-') || '-+-' || RPAD('-', 13, '-'));

  -- Inline FOR loop (implicit cursor) to list top industries by percent women
  FOR rec IN (
    SELECT c.industry,
           c.sector,
           c.subsector,
           c.industry_group,
           TO_NUMBER(c.percent_women) AS pct_women
      FROM BLS.CPSAAT18 c
     WHERE c.year = p_year
       AND c.percent_women IS NOT NULL
     ORDER BY TO_NUMBER(c.percent_women) DESC, c.industry ASC
  ) LOOP
    EXIT WHEN lv_row_count >= co_report_limit;

    lv_row_count := lv_row_count + 1;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(SUBSTR(rec.industry, 1, 40), 40) || ' | ' ||
      RPAD(SUBSTR(rec.sector, 1, 25), 25) || ' | ' ||
      RPAD(SUBSTR(rec.subsector, 1, 25), 25) || ' | ' ||
      RPAD(SUBSTR(rec.industry_group, 1, 25), 25) || ' | ' ||
      TO_CHAR(rec.pct_women)
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for year ' || p_year || '.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_women_employment;
/

DECLARE
  lv_match_id      IPL.MATCH.match_id%TYPE := 1;

  lv_match_date    IPL.MATCH.match_date%TYPE;
  lv_team1_id      IPL.MATCH.team_1%TYPE;
  lv_team2_id      IPL.MATCH.team_2%TYPE;
  lv_winner_id     IPL.MATCH.match_winner%TYPE;

  lv_team1_name    IPL.TEAM.name%TYPE;
  lv_team2_name    IPL.TEAM.name%TYPE;
  lv_winner_name   IPL.TEAM.name%TYPE;

  lv_rank          PLS_INTEGER := 0;
  lv_has_scores    PLS_INTEGER := 0;

  co_report_limit  CONSTANT PLS_INTEGER := 3; -- Limit output for quick ops summary
BEGIN
  -- Match header data
  SELECT m.match_date, m.team_1, m.team_2, m.match_winner
    INTO lv_match_date, lv_team1_id, lv_team2_id, lv_winner_id
    FROM IPL.MATCH m
   WHERE m.match_id = lv_match_id;

  SELECT t.name INTO lv_team1_name
    FROM IPL.TEAM t
   WHERE t.team_id = lv_team1_id;

  SELECT t.name INTO lv_team2_name
    FROM IPL.TEAM t
   WHERE t.team_id = lv_team2_id;

  IF lv_winner_id IS NULL THEN
    lv_winner_name := NULL;
  ELSE
    SELECT t.name INTO lv_winner_name
      FROM IPL.TEAM t
     WHERE t.team_id = lv_winner_id;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Match ID: ' || lv_match_id);
  DBMS_OUTPUT.PUT_LINE('Match Date: ' || TO_CHAR(lv_match_date, 'YYYY-MM-DD'));
  DBMS_OUTPUT.PUT_LINE('Team 1: ' || lv_team1_name);
  DBMS_OUTPUT.PUT_LINE('Team 2: ' || lv_team2_name);

  IF lv_winner_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Winner: No result');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Winner: ' || lv_winner_name);
  END IF;

  -- Check for any scoring rows to avoid printing an empty section
  SELECT COUNT(*)
    INTO lv_has_scores
    FROM IPL.BATSMAN_SCORED bs
   WHERE bs.match_id = lv_match_id;

  IF lv_has_scores = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No batting score data found for this match.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top Run Scorers (up to ' || co_report_limit || '):');

  FOR rec IN (
    SELECT *
      FROM (
        SELECT p.player_name AS player_name,
               SUM(bs.runs_scored) AS total_runs
          FROM IPL.BATSMAN_SCORED bs
          JOIN IPL.BALL_BY_BALL bbb
            ON bbb.match_id = bs.match_id
           AND bbb.over_id = bs.over_id
           AND bbb.ball_id = bs.ball_id
           AND bbb.innings_no = bs.innings_no
          JOIN IPL.PLAYER p
            ON p.player_id = bbb.striker
         WHERE bs.match_id = lv_match_id
         GROUP BY p.player_name
         ORDER BY SUM(bs.runs_scored) DESC, p.player_name ASC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rank := lv_rank + 1;
    DBMS_OUTPUT.PUT_LINE(LPAD(lv_rank, 2, ' ') || '. ' || rec.player_name || ' - ' || rec.total_runs || ' runs');
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

