  lv_docks_available SAN_FRANCISCO.BIKESHARE_STATUS.docks_available%TYPE;
BEGIN
  -- Guard clause for required input
  IF p_station_name IS NULL OR TRIM(p_station_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Station name is required.');
    RETURN;
  END IF;

  -- Look up the station ID by case-insensitive station name.
  SELECT s.station_id,
         s.name
    INTO lv_station_id,
         lv_station_name
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
   WHERE UPPER(s.name) = UPPER(TRIM(p_station_name));

  -- Get the latest status for the station.
  SELECT st.time,
         st.bikes_available,
         st.docks_available
    INTO lv_status_time,
         lv_bikes_available,
         lv_docks_available
    FROM (
          SELECT st1.time,
                 st1.bikes_available,
                 st1.docks_available
            FROM SAN_FRANCISCO.BIKESHARE_STATUS st1
           WHERE st1.station_id = lv_station_id
           ORDER BY st1.time DESC
         ) st
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Station Name: ' || lv_station_name);
  DBMS_OUTPUT.PUT_LINE('Station ID: ' || lv_station_id);
  DBMS_OUTPUT.PUT_LINE('Latest Time: ' || TO_CHAR(lv_status_time, 'YYYY-MM-DD HH24:MI:SS'));
  DBMS_OUTPUT.PUT_LINE('Bikes Available: ' || lv_bikes_available);
  DBMS_OUTPUT.PUT_LINE('Docks Available: ' || lv_docks_available);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching station/status found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple stations matched that name.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_station_availability;
/

question:
Build a reusable reporting routine for analysts that summarizes CPI-U inflation for a given area and item. The routine must:
Validate the inputs and default the year range when not provided.
Pull up to 15 of the most recent monthly CPI-U observations in the requested year range.
Compute month-over-month percent change (MoM %) using the prior month value.
Print a compact report to the console, including a warning when values are missing or non-numeric.
Handle all common runtime issues gracefully.

Requirements:
Procedure Name: report_cpi_u_mom
Parameters:
p_area_name IN BLS.CPI_U.area_name%TYPE
p_item_name IN BLS.CPI_U.item_name%TYPE
p_start_year IN BLS.CPI_U.year%TYPE
p_end_year IN BLS.CPI_U.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('CPI-U MoM report | Area=' || p_area_name || ' | Item=' || p_item_name || ' | Years=' || lv_start_year || '-' || lv_end_year);
DBMS_OUTPUT.PUT_LINE(RPAD('DATE', 12) || ' ' || RPAD('VALUE', 10) || ' ' || RPAD('PRIOR', 10) || ' ' || 'MOM%');
DBMS_OUTPUT.PUT_LINE('------------------------------------------------------------');
DBMS_OUTPUT.PUT_LINE(lv_date_label || ' ' || RPAD(lv_value_txt, 10) || ' ' || RPAD(lv_prior_txt, 10) || ' ' || lv_mom_txt);
DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
DBMS_OUTPUT.PUT_LINE('Invalid input: area name is required.');
DBMS_OUTPUT.PUT_LINE('Invalid input: item name is required.');
DBMS_OUTPUT.PUT_LINE('Invalid input: start year is after end year.');
DBMS_OUTPUT.PUT_LINE('Warning: non-numeric CPI value encountered; skipping MoM calculation for that row.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_cpi_u_mom(
  p_area_name  IN BLS.CPI_U.area_name%TYPE,
  p_item_name  IN BLS.CPI_U.item_name%TYPE,
  p_start_year IN BLS.CPI_U.year%TYPE,
  p_end_year   IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_start_year  BLS.CPI_U.year%TYPE;
  lv_end_year    BLS.CPI_U.year%TYPE;

  lv_rows_printed PLS_INTEGER := 0;

  lv_value_num   NUMBER;
  lv_prior_num   NUMBER;
  lv_mom_num     NUMBER;

  lv_value_txt   VARCHAR2(30);
  lv_prior_txt   VARCHAR2(30);
  lv_mom_txt     VARCHAR2(30);
  lv_date_label  VARCHAR2(12);
BEGIN
  -- Input validation
  IF p_area_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: area name is required.');
    RETURN;
  END IF;

  IF p_item_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: item name is required.');
    RETURN;
  END IF;

  -- Default year range when not provided (last 5 years up to latest year in data)
  IF p_end_year IS NULL THEN
    SELECT MAX(c.year)
      INTO lv_end_year
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name;
  ELSE
    lv_end_year := p_end_year;
  END IF;

  IF p_start_year IS NULL THEN
    lv_start_year := TO_CHAR(TO_NUMBER(lv_end_year) - 4);
  ELSE
    lv_start_year := p_start_year;
  END IF;

  IF TO_NUMBER(lv_start_year) > TO_NUMBER(lv_end_year) THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: start year is after end year.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI-U MoM report | Area=' || p_area_name || ' | Item=' || p_item_name || ' | Years=' || lv_start_year || '-' || lv_end_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('DATE', 12) || ' ' || RPAD('VALUE', 10) || ' ' || RPAD('PRIOR', 10) || ' ' || 'MOM%');
  DBMS_OUTPUT.PUT_LINE('------------------------------------------------------------');

  -- Use an inline query FOR loop (implicit cursor) and compute prior value with analytic LAG.
  FOR r IN (
    WITH base AS (
      SELECT
        c.c_date,
        c.year,
        c.period,
        c.value,
        LAG(c.value) OVER (ORDER BY c.c_date) AS prior_value
      FROM BLS.CPI_U c
      WHERE c.area_name = p_area_name
        AND c.item_name = p_item_name
        AND c.period LIKE 'M%'
        AND TO_NUMBER(c.year) BETWEEN TO_NUMBER(lv_start_year) AND TO_NUMBER(lv_end_year)
    )
    SELECT
      b.c_date,
      b.value,
      b.prior_value
    FROM base b
    ORDER BY b.c_date DESC
    FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    lv_date_label := TO_CHAR(r.c_date, 'YYYY-MM-DD');

    -- Convert VALUE and PRIOR_VALUE to numbers safely; if non-numeric, warn and skip MoM.
    lv_value_txt := NVL(r.value, '');
    lv_prior_txt := NVL(r.prior_value, '');

    BEGIN
      lv_value_num := TO_NUMBER(r.value);
      lv_prior_num := TO_NUMBER(r.prior_value);

      IF lv_prior_num = 0 THEN
        lv_mom_txt := 'NA';
      ELSE
        lv_mom_num := ((lv_value_num - lv_prior_num) / lv_prior_num) * 100;
        lv_mom_txt := TO_CHAR(ROUND(lv_mom_num, 2));
      END IF;

    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Warning: non-numeric CPI value encountered; skipping MoM calculation for that row.');
        lv_mom_txt := 'NA';
      WHEN INVALID_NUMBER THEN
        DBMS_OUTPUT.PUT_LINE('Warning: non-numeric CPI value encountered; skipping MoM calculation for that row.');
        lv_mom_txt := 'NA';
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
        lv_mom_txt := 'NA';
    END;

    IF lv_value_txt IS NULL THEN
      lv_value_txt := 'NULL';
    END IF;

    IF lv_prior_txt IS NULL THEN
      lv_prior_txt := 'NULL';
    END IF;

    DBMS_OUTPUT.PUT_LINE(lv_date_label || ' ' || RPAD(lv_value_txt, 10) || ' ' || RPAD(lv_prior_txt, 10) || ' ' || lv_mom_txt);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_cpi_u_mom;
/

