question:
As part of model governance for our stacking experiments, build a reusable procedure that audits a single solution version for a given experiment name. It should:
 Validate inputs.
 Find the exact SOLUTION row for (name, version). If it doesn’t exist, report it.
 Using that solution’s CORRELATION, print a compact report of up to 15 models ranked by TEST_SCORE (highest first) for that same (name, version). If there are ties, use TRAIN_SCORE descending.
Iterate explicitly with a cursor (so we can later extend it with cursor attributes) and show each ranked row.
If any model has a NULL TEST_SCORE, count it and report the count at the end.
Handle errors safely (no unhandled exceptions).

Requirements:
Procedure Name: audit_solution_models
Parameters:
p_name IN STACKING.SOLUTION.name%TYPE
p_version IN STACKING.SOLUTION.version%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Input validation failed: p_name is required.');
DBMS_OUTPUT.PUT_LINE('Input validation failed: p_version is required.');
DBMS_OUTPUT.PUT_LINE('Solution not found for name=' || p_name || ', version=' || TO_CHAR(p_version) || '.');
DBMS_OUTPUT.PUT_LINE('Models for name=' || p_name || ', version=' || TO_CHAR(p_version) || ', correlation=' || TO_CHAR(lv_correlation) || ' (top ' || TO_CHAR(co_report_limit) || ' by test_score)');
DBMS_OUTPUT.PUT_LINE('Rank ' || TO_CHAR(lv_rank) || ': model=' || rec.model || ', test_score=' || TO_CHAR(rec.test_score) || ', train_score=' || TO_CHAR(rec.train_score));
DBMS_OUTPUT.PUT_LINE('Models with NULL test_score in this solution: ' || TO_CHAR(lv_null_test_cnt));
DBMS_OUTPUT.PUT_LINE('No models found for this solution.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No models found for this solution.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE audit_solution_models(
  p_name    IN STACKING.SOLUTION.name%TYPE,
  p_version IN STACKING.SOLUTION.version%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_correlation    STACKING.SOLUTION.correlation%TYPE;
  lv_rank           PLS_INTEGER := 0;
  lv_null_test_cnt  PLS_INTEGER := 0;

  CURSOR c_models IS
    WITH ranked AS (
      SELECT
        ms.model,
        ms.test_score,
        ms.train_score,
        ROW_NUMBER() OVER (
          ORDER BY ms.test_score DESC NULLS LAST, ms.train_score DESC NULLS LAST, ms.model
        ) AS rn
      FROM STACKING.MODEL_SCORE ms
      WHERE ms.name = p_name
        AND ms.version = p_version
        AND ms.step = lv_correlation
    )
    SELECT r.model, r.test_score, r.train_score
    FROM ranked r
    WHERE r.rn <= co_report_limit
    ORDER BY r.rn;

BEGIN
  -- Input validation
  IF p_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: p_name is required.');
    RETURN;
  END IF;

  IF p_version IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: p_version is required.');
    RETURN;
  END IF;

  -- Find the solution correlation for the given (name, version)
  BEGIN
    SELECT s.correlation
      INTO lv_correlation
      FROM STACKING.SOLUTION s
     WHERE s.name = p_name
       AND s.version = p_version;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Solution not found for name=' || p_name || ', version=' || TO_CHAR(p_version) || '.');
      RETURN;
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      RETURN;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      RETURN;
  END;

  DBMS_OUTPUT.PUT_LINE(
    'Models for name=' || p_name || ', version=' || TO_CHAR(p_version) || ', correlation=' || TO_CHAR(lv_correlation) ||
    ' (top ' || TO_CHAR(co_report_limit) || ' by test_score)'
  );

  -- Explicit cursor processing over ranked model scores
  FOR rec IN c_models LOOP
    lv_rank := lv_rank + 1;

    IF rec.test_score IS NULL THEN
      lv_null_test_cnt := lv_null_test_cnt + 1;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Rank ' || TO_CHAR(lv_rank) || ': model=' || rec.model ||
      ', test_score=' || TO_CHAR(rec.test_score) ||
      ', train_score=' || TO_CHAR(rec.train_score)
    );
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Models with NULL test_score in this solution: ' || TO_CHAR(lv_null_test_cnt));

  IF lv_rank = 0 THEN
    -- Normalize empty report into NO_DATA_FOUND for consistent handling
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No models found for this solution.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END audit_solution_models;
/

CREATE OR REPLACE PROCEDURE report_hospice_providers_by_state(
  p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_row_count PLS_INTEGER := 0;
  lv_category  VARCHAR2(10);
  lv_pay_num   NUMBER;

  -- Used only to deliberately demonstrate TOO_MANY_ROWS handling in a controlled way.
  lv_any_state CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Hospice providers report for state=' || NVL(p_state, 'NULL'));

  -- If caller passes NULL, treat it as an empty result set.
  IF p_state IS NULL THEN
    RAISE NO_DATA_FOUND;
  END IF;

  FOR r IN (
    SELECT hp.provider_id,
           hp.name,
           hp.city,
           hp.total_medicare_payment_amount
      FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
     WHERE hp.state = p_state
     ORDER BY hp.provider_id
  ) LOOP
    lv_row_count := lv_row_count + 1;
    EXIT WHEN lv_row_count > co_report_limit;

    -- Derive category from a VARCHAR2 amount; keep conversion safe.
    BEGIN
      IF r.total_medicare_payment_amount IS NULL THEN
        lv_category := 'UNKNOWN';
      ELSE
        lv_pay_num := TO_NUMBER(r.total_medicare_payment_amount);

        IF lv_pay_num >= 1000000 THEN
          lv_category := 'HIGH';
        ELSIF lv_pay_num >= 250000 THEN
          lv_category := 'MEDIUM';
        ELSE
          lv_category := 'LOW';
        END IF;
      END IF;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        lv_category := 'UNKNOWN';
    END;

    DBMS_OUTPUT.PUT_LINE('Provider ID=' || r.provider_id || ', Name=' || r.name || ', City=' || r.city || ', Category=' || lv_category);
  END LOOP;

  IF lv_row_count = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

  -- Controlled demonstration of TOO_MANY_ROWS handling.
  -- This query is intentionally broad; in real code you would avoid it.
  SELECT hp.state
    INTO lv_any_state
    FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No providers found for the requested state.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_hospice_providers_by_state;
/

CREATE OR REPLACE PROCEDURE report_bikeshare_landmark_status(
  p_landmark IN SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_printed_count PLS_INTEGER := 0;
  lv_bucket        VARCHAR2(10);
BEGIN
  IF p_landmark IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input landmark is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Report for landmark: ' || p_landmark);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));
  DBMS_OUTPUT.PUT_LINE(RPAD('Station', 35) || ' | ' || RPAD('Docks', 5) || ' | ' || RPAD('Bikes', 5) || ' | ' || RPAD('Open', 5) || ' | ' || RPAD('Bucket', 7) || ' | ' || 'AsOf');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));

  -- Inline cursor loop (implicit) to keep logic simple and avoid explicit cursor usage.
  FOR rec IN (
    SELECT
      s.name AS station_name,
      s.dockcount AS dock_count,
      NVL(st.bikes_available, '0') AS bikes_available,
      NVL(st.docks_available, '0') AS docks_available,
      NVL(TO_CHAR(st.time, 'YYYY-MM-DD HH24:MI:SS'), 'NO STATUS') AS asof
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
    LEFT OUTER JOIN (
      SELECT
        bs.station_id,
        bs.bikes_available,
        bs.docks_available,
        bs.time
      FROM SAN_FRANCISCO.BIKESHARE_STATUS bs
      INNER JOIN (
        SELECT station_id, MAX(time) AS max_time
        FROM SAN_FRANCISCO.BIKESHARE_STATUS
        GROUP BY station_id
      ) mx
        ON mx.station_id = bs.station_id
       AND mx.max_time = bs.time
    ) st
      ON st.station_id = s.station_id
    WHERE s.landmark = p_landmark
    ORDER BY s.name
  ) LOOP
    EXIT WHEN lv_printed_count >= co_report_limit;

    -- Bucket logic based on latest availability.
    IF TO_NUMBER(rec.bikes_available) = 0 THEN
      lv_bucket := 'EMPTY';
    ELSIF TO_NUMBER(rec.docks_available) = 0 THEN
      lv_bucket := 'FULL';
    ELSE
      lv_bucket := 'OK';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.station_name, 35) || ' | ' ||
      RPAD(rec.dock_count, 5) || ' | ' ||
      RPAD(rec.bikes_available, 5) || ' | ' ||
      RPAD(rec.docks_available, 5) || ' | ' ||
      RPAD(lv_bucket, 7) || ' | ' ||
      rec.asof
    );

    lv_printed_count := lv_printed_count + 1;
  END LOOP;

  IF lv_printed_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark: ' || p_landmark);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_bikeshare_landmark_status;
/

