question:
Your analytics team needs a quick CPI snapshot for a single geography/item. Build an anonymous PL/SQL report that:
Accepts an area name, item name, and year.
Prints up to 15 monthly CPI-U observations for that combination, ordered by date.
Uses simple control flow: if no rows match, print a clear message; otherwise print each row.
Catches and reports common exceptions so the script never fails at runtime.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('CPI report for Area=' || lv_area_name || ', Item=' || lv_item_name || ', Year=' || lv_year);
DBMS_OUTPUT.PUT_LINE(RPAD('DATE', 12) || ' ' || RPAD('PERIOD', 8) || ' ' || 'VALUE');
DBMS_OUTPUT.PUT_LINE('------------ -------- --------------------');
DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.c_date, 'YYYY-MM-DD') || ' ' || RPAD(rec.period, 8) || ' ' || rec.value);
DBMS_OUTPUT.PUT_LINE('No data found for the requested filters.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found for the requested filters.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_area_name BLS.CPI_U.area_name%TYPE;
  lv_item_name BLS.CPI_U.item_name%TYPE;
  lv_year      BLS.CPI_U.year%TYPE;

  lv_row_count PLS_INTEGER := 0;
BEGIN
  -- Pick a commonly occurring filter set to make the block runnable without user input.
  SELECT area_name, item_name, year
    INTO lv_area_name, lv_item_name, lv_year
    FROM (
          SELECT c.area_name, c.item_name, c.year, COUNT(*) AS cnt
            FROM BLS.CPI_U c
           WHERE c.area_name IS NOT NULL
             AND c.item_name IS NOT NULL
             AND c.year IS NOT NULL
           GROUP BY c.area_name, c.item_name, c.year
           ORDER BY COUNT(*) DESC
         )
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('CPI report for Area=' || lv_area_name || ', Item=' || lv_item_name || ', Year=' || lv_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('DATE', 12) || ' ' || RPAD('PERIOD', 8) || ' ' || 'VALUE');
  DBMS_OUTPUT.PUT_LINE('------------ -------- --------------------');

  FOR rec IN (
    SELECT c.c_date, c.period, c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = lv_area_name
       AND c.item_name = lv_item_name
       AND c.year = lv_year
     ORDER BY c.c_date
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_row_count := lv_row_count + 1;
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.c_date, 'YYYY-MM-DD') || ' ' || RPAD(rec.period, 8) || ' ' || rec.value);
  END LOOP;

  IF lv_row_count = 0 THEN
    -- Use NO_DATA_FOUND to reuse the standard exception message pattern.
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the requested filters.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

