CREATE OR REPLACE PROCEDURE report_alien_risk(
  p_country IN CITY_LEGISLATION.ALIEN_DATA.country%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country    CITY_LEGISLATION.ALIEN_DATA.country%TYPE;
  lv_risk_label VARCHAR2(20);
  ln_rows       PLS_INTEGER := 0;
BEGIN
  lv_country := NVL(p_country, 'UNKNOWN');

  DBMS_OUTPUT.PUT_LINE('Alien Risk Report for Country=' || lv_country);

  FOR rec IN (
    SELECT ad.first_name,
           ad.last_name,
           ad.type,
           ad.current_location,
           ad.favorite_food,
           ad.feeding_frequency,
           ad.aggressive
      FROM CITY_LEGISLATION.ALIEN_DATA ad
     WHERE ad.country = lv_country
     ORDER BY ad.last_name, ad.first_name
  ) LOOP
    ln_rows := ln_rows + 1;
    EXIT WHEN ln_rows > co_report_limit;

    -- Risk derivation rules
    IF rec.aggressive = 1
       OR UPPER(NVL(rec.feeding_frequency, '')) LIKE '%DAY%'
       OR UPPER(NVL(rec.feeding_frequency, '')) LIKE '%DAILY%'
       OR UPPER(NVL(rec.feeding_frequency, '')) LIKE '%HOUR%'
    THEN
      lv_risk_label := 'HIGH_RISK';
    ELSE
      lv_risk_label := 'LOW_RISK';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Name=' || rec.first_name || ' ' || rec.last_name ||
      ' | Type=' || rec.type ||
      ' | Location=' || rec.current_location ||
      ' | Food=' || rec.favorite_food ||
      ' | Risk=' || lv_risk_label
    );
  END LOOP;

  IF ln_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_alien_risk;
/

question:
Build a reusable reporting routine for an IPL analytics dashboard.

Create a stored procedure that, for a given season and a minimum match count threshold, lists up to 15 players who received the Man of the Match award most frequently in that season. For each player, show the number of awards and the first and last match date (within that season) when they received the award.

Add simple categorization logic: if a player’s award count is greater than or equal to the minimum match count threshold, label them as 'STAR'; otherwise label them as 'REGULAR'. Print a clear header and then one line per player.

The procedure must handle bad inputs and edge cases gracefully:
If the season id parameter is NULL, print an error message and stop.
If the minimum threshold is NULL or <= 0, default it to 1.
If the season id does not exist in the MATCH table, print a 'No data found.' message.

Requirements:
Procedure Name: report_season_mom_leaders
Parameters:
p_season_id IN IPL.MATCH.season_id%TYPE
p_min_awards IN NUMBER
Output:
DBMS_OUTPUT.PUT_LINE('Season MoM leaders report');
DBMS_OUTPUT.PUT_LINE('Season Id: ' || p_season_id);
DBMS_OUTPUT.PUT_LINE('Min awards threshold: ' || lv_min_awards);
DBMS_OUTPUT.PUT_LINE('PLAYER | AWARDS | FIRST_AWARD_DATE | LAST_AWARD_DATE | CATEGORY');
DBMS_OUTPUT.PUT_LINE(rp.player_name || ' | ' || rp.award_count || ' | ' || TO_CHAR(rp.first_award_date, 'YYYY-MM-DD') || ' | ' || TO_CHAR(rp.last_award_date, 'YYYY-MM-DD') || ' | ' || lv_category);
DBMS_OUTPUT.PUT_LINE('Season id is required.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_season_mom_leaders(
  p_season_id   IN IPL.MATCH.season_id%TYPE,
  p_min_awards  IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_min_awards NUMBER;
  lv_season_match_count NUMBER;
  lv_category VARCHAR2(20);
BEGIN
  IF p_season_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Season id is required.');
    RETURN;
  END IF;

  -- Default invalid threshold to 1
  lv_min_awards := CASE WHEN p_min_awards IS NULL OR p_min_awards <= 0 THEN 1 ELSE p_min_awards END;

  -- Validate season existence (must have at least one match)
  SELECT COUNT(*)
    INTO lv_season_match_count
    FROM IPL.MATCH m
   WHERE m.season_id = p_season_id;

  IF lv_season_match_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Season MoM leaders report');
  DBMS_OUTPUT.PUT_LINE('Season Id: ' || p_season_id);
  DBMS_OUTPUT.PUT_LINE('Min awards threshold: ' || lv_min_awards);
  DBMS_OUTPUT.PUT_LINE('PLAYER | AWARDS | FIRST_AWARD_DATE | LAST_AWARD_DATE | CATEGORY');

  FOR rp IN (
    WITH mom_agg AS (
      SELECT m.man_of_the_match AS player_id,
             COUNT(*) AS award_count,
             MIN(m.match_date) AS first_award_date,
             MAX(m.match_date) AS last_award_date
        FROM IPL.MATCH m
       WHERE m.season_id = p_season_id
         AND m.man_of_the_match IS NOT NULL
       GROUP BY m.man_of_the_match
    ),
    ranked AS (
      SELECT ma.player_id,
             ma.award_count,
             ma.first_award_date,
             ma.last_award_date,
             ROW_NUMBER() OVER (ORDER BY ma.award_count DESC, ma.last_award_date DESC, ma.player_id) AS rn
        FROM mom_agg ma
    )
    SELECT p.player_name,
           r.award_count,
           r.first_award_date,
           r.last_award_date
      FROM ranked r
      INNER JOIN IPL.PLAYER p
        ON p.player_id = r.player_id
     WHERE r.rn <= co_report_limit
     ORDER BY r.award_count DESC, r.last_award_date DESC, p.player_name
  ) LOOP
    IF rp.award_count >= lv_min_awards THEN
      lv_category := 'STAR';
    ELSE
      lv_category := 'REGULAR';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      rp.player_name || ' | ' || rp.award_count || ' | ' ||
      TO_CHAR(rp.first_award_date, 'YYYY-MM-DD') || ' | ' ||
      TO_CHAR(rp.last_award_date, 'YYYY-MM-DD') || ' | ' ||
      lv_category
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_season_mom_leaders;
/

