question:
Build a reusable stored procedure for Sales Ops to print a short sales performance report for a given sales channel and date range. The report should list up to 15 products (by name) with total quantity and total amount sold in that period.

The procedure must validate the inputs (channel and dates), handle the case where no rows match, and never allow an exception to reach the client. Use simple branching so that if the date range is invalid, the procedure exits early with a clear message.

Requirements:
Procedure Name: report_channel_sales
Parameters:
p_channel_id IN COMPLEX_ORACLE.SALES.channel_id%TYPE
p_from_date IN COMPLEX_ORACLE.SALES.time_id%TYPE
p_to_date IN COMPLEX_ORACLE.SALES.time_id%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Channel sales report');
DBMS_OUTPUT.PUT_LINE('Channel ID: ' || p_channel_id);
DBMS_OUTPUT.PUT_LINE('From: ' || TO_CHAR(p_from_date, 'YYYY-MM-DD') || ' To: ' || TO_CHAR(p_to_date, 'YYYY-MM-DD'));
DBMS_OUTPUT.PUT_LINE('Invalid input: channel_id is required.');
DBMS_OUTPUT.PUT_LINE('Invalid input: from_date and to_date are required.');
DBMS_OUTPUT.PUT_LINE('Invalid input: from_date must be <= to_date.');
DBMS_OUTPUT.PUT_LINE('No matching sales found for the given inputs.');
DBMS_OUTPUT.PUT_LINE(RPAD('Product', 30) || ' ' || LPAD('Qty', 10) || ' ' || LPAD('Amount', 14));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 30, '-') || ' ' || LPAD('-', 10, '-') || ' ' || LPAD('-', 14, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.prod_name, 30) || ' ' || LPAD(rec.total_qty, 10) || ' ' || LPAD(TO_CHAR(rec.total_amt, '9999999990D00'), 14));
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No matching sales found for the given inputs.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_channel_sales(
  p_channel_id IN COMPLEX_ORACLE.SALES.channel_id%TYPE,
  p_from_date  IN COMPLEX_ORACLE.SALES.time_id%TYPE,
  p_to_date    IN COMPLEX_ORACLE.SALES.time_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Channel sales report');
  DBMS_OUTPUT.PUT_LINE('Channel ID: ' || p_channel_id);
  DBMS_OUTPUT.PUT_LINE(
    'From: ' || TO_CHAR(p_from_date, 'YYYY-MM-DD') || ' To: ' || TO_CHAR(p_to_date, 'YYYY-MM-DD')
  );

  -- Input validation with early exit
  IF p_channel_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: channel_id is required.');
    RETURN;
  ELSIF p_from_date IS NULL OR p_to_date IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: from_date and to_date are required.');
    RETURN;
  ELSIF p_from_date > p_to_date THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: from_date must be <= to_date.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE(RPAD('Product', 30) || ' ' || LPAD('Qty', 10) || ' ' || LPAD('Amount', 14));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 30, '-') || ' ' || LPAD('-', 10, '-') || ' ' || LPAD('-', 14, '-'));

  FOR rec IN (
    SELECT *
    FROM (
      SELECT p.prod_name AS prod_name,
             SUM(s.quantity_sold) AS total_qty,
             SUM(s.amount_sold) AS total_amt
        FROM COMPLEX_ORACLE.SALES s
        INNER JOIN COMPLEX_ORACLE.PRODUCTS p
          ON p.prod_id = s.prod_id
       WHERE s.channel_id = p_channel_id
         AND s.time_id BETWEEN p_from_date AND p_to_date
       GROUP BY p.prod_name
       ORDER BY SUM(s.amount_sold) DESC, p.prod_name ASC
    )
    WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.prod_name, 30) || ' ' ||
      LPAD(rec.total_qty, 10) || ' ' ||
      LPAD(TO_CHAR(rec.total_amt, '9999999990D00'), 14)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matching sales found for the given inputs.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching sales found for the given inputs.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_channel_sales;
/

