CREATE OR REPLACE PROCEDURE report_region_member_trading(
  p_region     IN BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE,
  p_start_date IN VARCHAR2,
  p_end_date   IN VARCHAR2
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_start_date DATE;
  lv_end_date   DATE;
  lv_printed    PLS_INTEGER := 0;

  CURSOR c_members IS
    WITH member_activity AS (
      SELECT
        m.member_id,
        m.first_name,
        COUNT(*) AS txn_count,
        SUM(t.quantity) AS total_qty,
        AVG(t.percentage_fee) AS avg_fee
      FROM BANK_SALES_TRADING.BITCOIN_MEMBERS m
      INNER JOIN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
        ON t.member_id = m.member_id
      WHERE m.region = p_region
        AND TO_DATE(t.txn_date, 'YYYY-MM-DD') BETWEEN lv_start_date AND lv_end_date
      GROUP BY m.member_id, m.first_name
    )
    SELECT
      ma.member_id,
      ma.first_name,
      ma.txn_count,
      ma.total_qty,
      ma.avg_fee
    FROM member_activity ma
    ORDER BY ma.txn_count DESC, ma.total_qty DESC, ma.member_id;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Region trading member summary');
  DBMS_OUTPUT.PUT_LINE('Region=' || p_region || ' Start=' || p_start_date || ' End=' || p_end_date);

  -- Input validation
  IF p_region IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input region is required.');
    RETURN;
  END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input dates are required.');
    RETURN;
  END IF;

  lv_start_date := TO_DATE(p_start_date, 'YYYY-MM-DD');
  lv_end_date   := TO_DATE(p_end_date, 'YYYY-MM-DD');

  IF lv_start_date > lv_end_date THEN
    DBMS_OUTPUT.PUT_LINE('Start date must be <= end date.');
    RETURN;
  END IF;

  -- Cursor-based iteration so per-member rules can be added later.
  FOR r_mem IN c_members LOOP
    lv_printed := lv_printed + 1;
    EXIT WHEN lv_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'MEMBER_ID=' || r_mem.member_id ||
      ' FIRST_NAME=' || r_mem.first_name ||
      ' TXN_COUNT=' || r_mem.txn_count ||
      ' TOTAL_QTY=' || r_mem.total_qty ||
      ' AVG_FEE=' || TO_CHAR(r_mem.avg_fee)
    );
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No members found for the requested region/date range.');
  END IF;

  -- Make the empty-result scenario testable via NO_DATA_FOUND too (single-row check).
  IF lv_printed = 0 THEN
    DECLARE
      lv_dummy BANK_SALES_TRADING.BITCOIN_MEMBERS.member_id%TYPE;
    BEGIN
      SELECT m.member_id
        INTO lv_dummy
        FROM BANK_SALES_TRADING.BITCOIN_MEMBERS m
        INNER JOIN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
          ON t.member_id = m.member_id
       WHERE m.region = p_region
         AND TO_DATE(t.txn_date, 'YYYY-MM-DD') BETWEEN lv_start_date AND lv_end_date
         AND ROWNUM = 1;
    END;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No members found for the requested region/date range.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid date format. Use YYYY-MM-DD.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_member_trading;
