CREATE OR REPLACE PROCEDURE wdi_latest_indicator_snapshot(
  p_country_code   IN WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE,
  p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE
) IS
  co_detail_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_latest_year     WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;
  lv_country_name    WORLD_BANK_WDI.INDICATORS_DATA.country_name%TYPE;
  lv_indicator_name  WORLD_BANK_WDI.INDICATORS_DATA.indicator_name%TYPE;
  lv_raw_value       WORLD_BANK_WDI.INDICATORS_DATA.value%TYPE;
  lv_numeric_value   NUMBER;

  lv_details_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_country_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country code is required.');
    RETURN;
  END IF;

  IF p_indicator_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: indicator code is required.');
    RETURN;
  END IF;

  -- Find the latest year available for this country/indicator
  SELECT MAX(d.year)
    INTO lv_latest_year
    FROM WORLD_BANK_WDI.INDICATORS_DATA d
   WHERE d.country_code = p_country_code
     AND d.indicator_code = p_indicator_code;

  IF lv_latest_year IS NULL THEN
    -- MAX(...) returning NULL means there were no rows.
    RAISE NO_DATA_FOUND;
  END IF;

  -- Pull a single snapshot row for that latest year.
  -- The MAX(year) can still have multiple rows in that year, so we protect with ROWNUM=1.
  SELECT d.country_name,
         d.indicator_name,
         d.value
    INTO lv_country_name,
         lv_indicator_name,
         lv_raw_value
    FROM WORLD_BANK_WDI.INDICATORS_DATA d
   WHERE d.country_code = p_country_code
     AND d.indicator_code = p_indicator_code
     AND d.year = lv_latest_year
     AND ROWNUM = 1;

  -- Detail output (kept under a capped number of lines)
  IF lv_details_printed < co_detail_limit THEN
    DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name);
    lv_details_printed := lv_details_printed + 1;
  END IF;

  IF lv_details_printed < co_detail_limit THEN
    DBMS_OUTPUT.PUT_LINE('Indicator: ' || lv_indicator_name);
    lv_details_printed := lv_details_printed + 1;
  END IF;

  IF lv_details_printed < co_detail_limit THEN
    DBMS_OUTPUT.PUT_LINE('Latest Year: ' || lv_latest_year);
    lv_details_printed := lv_details_printed + 1;
  END IF;

  IF lv_details_printed < co_detail_limit THEN
    DBMS_OUTPUT.PUT_LINE('Raw Value: ' || NVL(lv_raw_value, 'NULL'));
    lv_details_printed := lv_details_printed + 1;
  END IF;

  -- Numeric interpretation
  BEGIN
    IF lv_raw_value IS NULL THEN
      IF lv_details_printed < co_detail_limit THEN
        DBMS_OUTPUT.PUT_LINE('Numeric Value: not numeric or missing.');
        lv_details_printed := lv_details_printed + 1;
      END IF;
    ELSE
      lv_numeric_value := TO_NUMBER(lv_raw_value);
      IF lv_details_printed < co_detail_limit THEN
        DBMS_OUTPUT.PUT_LINE('Numeric Value: ' || TO_CHAR(lv_numeric_value));
        lv_details_printed := lv_details_printed + 1;
      END IF;
    END IF;
  EXCEPTION
    WHEN VALUE_ERROR THEN
      IF lv_details_printed < co_detail_limit THEN
        DBMS_OUTPUT.PUT_LINE('Invalid numeric value.');
        lv_details_printed := lv_details_printed + 1;
      END IF;
  END;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END wdi_latest_indicator_snapshot;
/

CREATE OR REPLACE PROCEDURE report_region_station_activity(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
  p_hours_back  IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
  lv_region_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;

  CURSOR c_ranked_stations(p_region_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE) IS
    WITH recent_starts AS (
      SELECT t.start_station_id AS station_id,
             COUNT(*) AS trip_starts
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
       WHERE t.start_date >= SYSTIMESTAMP - NUMTODSINTERVAL(p_hours_back, 'HOUR')
       GROUP BY t.start_station_id
    ), ranked AS (
      SELECT ROW_NUMBER() OVER (ORDER BY rs.trip_starts DESC, si.name ASC, si.station_id ASC) AS rn,
             si.name AS station_name,
             ss.num_bikes_available AS bikes_avail,
             ss.num_docks_available AS docks_avail,
             rs.trip_starts AS trip_starts
        FROM recent_starts rs
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
          ON si.station_id = rs.station_id
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
          ON ss.station_id = si.station_id
       WHERE si.region_id = p_region_id
         AND ss.is_installed = '1'
         AND ss.is_renting = '1'
    )
    SELECT r.rn,
           r.station_name,
           r.bikes_avail,
           r.docks_avail,
           r.trip_starts
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn;

  lv_rank         NUMBER;
  lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  lv_bikes_avail  SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE;
  lv_docks_avail  SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_docks_available%TYPE;
  lv_trip_starts  NUMBER;
  lv_printed_rows PLS_INTEGER := 0;
BEGIN
  -- Basic parameter validation
  IF p_region_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: region name is required.');
    RETURN;
  END IF;

  IF p_hours_back IS NULL OR p_hours_back <= 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: hours_back must be positive.');
    RETURN;
  END IF;

  -- Resolve region
  SELECT r.region_id, r.name
    INTO lv_region_id, lv_region_name
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
   WHERE r.name = p_region_name;

  DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region_name || ' | Hours back: ' || p_hours_back);

  -- Iterate with an explicit cursor (manual open/fetch/close)
  OPEN c_ranked_stations(lv_region_id);
  LOOP
    FETCH c_ranked_stations INTO lv_rank, lv_station_name, lv_bikes_avail, lv_docks_avail, lv_trip_starts;
    EXIT WHEN c_ranked_stations%NOTFOUND;

    lv_printed_rows := lv_printed_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      LPAD(TO_CHAR(lv_rank), 2, ' ') || '. ' || lv_station_name ||
      ' | bikes=' || lv_bikes_avail ||
      ' | docks=' || lv_docks_avail ||
      ' | starts=' || lv_trip_starts
    );
  END LOOP;
  CLOSE c_ranked_stations;

  IF lv_printed_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations matched the criteria.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Region not found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF c_ranked_stations%ISOPEN THEN
      CLOSE c_ranked_stations;
    END IF;
END report_region_station_activity;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_products IS
    SELECT x.product_id,
           x.product_name
      FROM (
            SELECT ol.product_id AS product_id,
                   p.name        AS product_name,
                   COUNT(*)      AS orderline_cnt
              FROM ORACLE_SQL.orderlines ol
              INNER JOIN ORACLE_SQL.products p
                ON p.id = ol.product_id
             GROUP BY ol.product_id, p.name
             ORDER BY COUNT(*) DESC, ol.product_id
           ) x
     WHERE ROWNUM <= co_report_limit;

  lv_sold_qty      ORACLE_SQL.orderlines.qty%TYPE;
  lv_inv_qty       ORACLE_SQL.inventory.qty%TYPE;
  lv_min_qty       ORACLE_SQL.product_minimums.qty_minimum%TYPE;
  lv_purchase_qty  ORACLE_SQL.product_minimums.qty_purchase%TYPE;
  lv_risk          VARCHAR2(20);
BEGIN
  FOR r_prod IN c_products LOOP
    -- Aggregate sold quantity for this product
    SELECT SUM(ol.qty)
      INTO lv_sold_qty
      FROM ORACLE_SQL.orderlines ol
     WHERE ol.product_id = r_prod.product_id;

    -- Aggregate current inventory quantity for this product (treat no rows as 0)
    SELECT NVL(SUM(i.qty), 0)
      INTO lv_inv_qty
      FROM ORACLE_SQL.inventory i
     WHERE i.product_id = r_prod.product_id;

    -- Fetch minimum settings; if missing, treat as 0 to avoid false alarms
    BEGIN
      SELECT pm.qty_minimum,
             pm.qty_purchase
        INTO lv_min_qty,
             lv_purchase_qty
        FROM ORACLE_SQL.product_minimums pm
       WHERE pm.product_id = r_prod.product_id;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        lv_min_qty := 0;
        lv_purchase_qty := 0;
    END;

    -- Risk classification
    IF lv_inv_qty < lv_min_qty THEN
      lv_risk := 'CRITICAL';
    ELSIF lv_inv_qty < lv_purchase_qty THEN
      lv_risk := 'LOW';
    ELSE
      lv_risk := 'OK';
    END IF;

    DBMS_OUTPUT.PUT_LINE('PRODUCT_ID=' || r_prod.product_id || ' | PRODUCT_NAME=' || r_prod.product_name || ' | SOLD_QTY=' || lv_sold_qty || ' | INV_QTY=' || lv_inv_qty || ' | MIN_QTY=' || lv_min_qty || ' | PURCHASE_QTY=' || lv_purchase_qty || ' | RISK=' || lv_risk);
  END LOOP;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

