question:
Build a reusable procedure that prints a small on-screen report for a given passenger ID: list up to 15 of their most recent flights (scheduled departure), including flight number, departure/arrival airport codes, status, fare conditions, and amount. If the passenger has no tickets, print a clear message. Also handle unexpected errors cleanly without letting any exception propagate.

Requirements:
Procedure Name: report_passenger_recent_flights
Parameters:
p_passenger_id IN AIRLINES.TICKETS.passenger_id%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Passenger ID: ' || p_passenger_id);
DBMS_OUTPUT.PUT_LINE('No flights found for passenger.');
DBMS_OUTPUT.PUT_LINE('Flight ' || rec.flight_no || ' | Dep: ' || rec.departure_airport || ' | Arr: ' || rec.arrival_airport || ' | SchedDep: ' || TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI') || ' | Status: ' || rec.status || ' | Fare: ' || rec.fare_conditions || ' | Amount: ' || rec.amount);
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No flights found for passenger.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_passenger_recent_flights(
  p_passenger_id IN AIRLINES.TICKETS.passenger_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Passenger ID: ' || p_passenger_id);

  IF p_passenger_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No flights found for passenger.');
    RETURN;
  END IF;

  FOR rec IN (
    SELECT f.flight_no,
           f.departure_airport,
           f.arrival_airport,
           f.scheduled_departure,
           f.status,
           tf.fare_conditions,
           tf.amount
      FROM AIRLINES.TICKETS t
      INNER JOIN AIRLINES.TICKET_FLIGHTS tf
        ON tf.ticket_no = t.ticket_no
      INNER JOIN AIRLINES.FLIGHTS f
        ON f.flight_id = tf.flight_id
     WHERE t.passenger_id = p_passenger_id
     ORDER BY f.scheduled_departure DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Flight ' || rec.flight_no ||
      ' | Dep: ' || rec.departure_airport ||
      ' | Arr: ' || rec.arrival_airport ||
      ' | SchedDep: ' || TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
      ' | Status: ' || rec.status ||
      ' | Fare: ' || rec.fare_conditions ||
      ' | Amount: ' || rec.amount
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No flights found for passenger.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_passenger_recent_flights;
/

CREATE OR REPLACE PROCEDURE report_member_daily_txns(
  p_member_id IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.member_id%TYPE,
  p_txn_date  IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.txn_date%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region        BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE;
  lv_printed_count PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_member_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: member id is required.');
    RETURN;
  END IF;

  IF p_txn_date IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: transaction date is required.');
    RETURN;
  END IF;

  -- Look up member region (expect exactly one row)
  SELECT bm.region
    INTO lv_region
    FROM BANK_SALES_TRADING.BITCOIN_MEMBERS bm
   WHERE bm.member_id = p_member_id;

  DBMS_OUTPUT.PUT_LINE('Member ID: ' || p_member_id);
  DBMS_OUTPUT.PUT_LINE('Transaction Date: ' || p_txn_date);
  DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region);

  -- Print up to 15 transactions for that member/date
  FOR rec IN (
    SELECT bt.txn_id,
           bt.txn_type,
           bt.quantity,
           bt.percentage_fee,
           bt.txn_time
      FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt
     WHERE bt.member_id = p_member_id
       AND bt.txn_date = p_txn_date
       AND ROWNUM <= co_report_limit
     ORDER BY bt.txn_id
  ) LOOP
    lv_printed_count := lv_printed_count + 1;
    DBMS_OUTPUT.PUT_LINE(
      'TXN_ID=' || rec.txn_id ||
      ', TYPE=' || rec.txn_type ||
      ', QTY=' || rec.quantity ||
