  PROCEDURE print_region_station_health(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
  );
END bikeshare_ops_pkg;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_ops_pkg IS
  PROCEDURE print_region_station_health(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_region_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
    lv_region_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;

    CURSOR c_health(p_rid SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE) IS
      WITH latest_status AS (
        SELECT s.station_id,
               s.num_bikes_available,
               s.num_docks_available,
               s.is_installed,
               s.is_renting,
               s.is_returning,
               ROW_NUMBER() OVER (
                 PARTITION BY s.station_id
                 ORDER BY TO_NUMBER(s.last_reported) DESC
               ) AS rn
          FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
      )
      SELECT si.name AS station_name,
             TO_NUMBER(si.capacity) AS capacity,
             TO_NUMBER(ls.num_bikes_available) AS bikes_avail,
             TO_NUMBER(ls.num_docks_available) AS docks_avail,
             CASE
               WHEN TO_NUMBER(si.capacity) = 0 THEN 'CRITICAL_LOW'
               WHEN TO_NUMBER(ls.num_bikes_available) <= TO_NUMBER(si.capacity) * 0.10 THEN 'CRITICAL_LOW'
               WHEN TO_NUMBER(ls.num_bikes_available) <= TO_NUMBER(si.capacity) * 0.25 THEN 'LOW'
               ELSE 'OK'
             END AS util_status
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        INNER JOIN latest_status ls
          ON ls.station_id = si.station_id
         AND ls.rn = 1
       WHERE si.region_id = p_rid
         AND ls.is_installed = '1'
         AND ls.is_renting = '1'
         AND ls.is_returning = '1'
         AND ROWNUM <= co_report_limit
       ORDER BY TO_NUMBER(ls.num_bikes_available) ASC, si.name ASC;

    lv_any_rows NUMBER := 0;
  BEGIN
    -- Resolve region (single-row lookup). This intentionally raises NO_DATA_FOUND / TOO_MANY_ROWS.
    SELECT r.region_id, r.name
      INTO lv_region_id, lv_region_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE r.name = p_region_name;

    DBMS_OUTPUT.PUT_LINE('Station Health Report - Region: ' || lv_region_name);
    DBMS_OUTPUT.PUT_LINE('------------------------------------------------------------------');

    FOR rec IN c_health(lv_region_id) LOOP
      lv_any_rows := 1;
      DBMS_OUTPUT.PUT_LINE(
        'Station: ' || rec.station_name ||
        ' | Capacity: ' || rec.capacity ||
        ' | Bikes: ' || rec.bikes_avail ||
        ' | Docks: ' || rec.docks_avail ||
        ' | Status: ' || rec.util_status
      );
    END LOOP;

    IF lv_any_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No stations matched the operational filters for this region.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_region_station_health;
END bikeshare_ops_pkg;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country   CITY_LEGISLATION.ALIEN_DATA.country%TYPE := NULL;
  lv_avg_age   CITY_LEGISLATION.ALIEN_DATA.age%TYPE;
  lv_rownum    PLS_INTEGER := 0;
  lv_label     VARCHAR2(20);
BEGIN
  -- Input (simulated parameter for an anonymous block)
  lv_country := NULL;

  -- Defaulting rule for NULL/blank country
  IF lv_country IS NULL OR TRIM(lv_country) IS NULL THEN
    lv_country := 'USA';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Country used: ' || lv_country);

  -- Compute average age for aggressive aliens in the selected country
  SELECT AVG(ad.age)
    INTO lv_avg_age
    FROM CITY_LEGISLATION.ALIEN_DATA ad
   WHERE ad.aggressive = 1
     AND ad.country = lv_country;

  IF lv_avg_age IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No aggressive aliens found for country: ' || lv_country);
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Avg aggressive age: ' || TO_CHAR(lv_avg_age));

  -- Print up to 15 aggressive aliens, oldest to youngest
  FOR r IN (
    SELECT ad.id,
           ad.first_name || ' ' || ad.last_name AS full_name,
           ad.age,
           ad.current_location,
           ad.occupation
      FROM CITY_LEGISLATION.ALIEN_DATA ad
     WHERE ad.aggressive = 1
       AND ad.country = lv_country
       AND ad.age IS NOT NULL
     ORDER BY ad.age DESC, ad.id
  ) LOOP
    lv_rownum := lv_rownum + 1;
    EXIT WHEN lv_rownum > co_report_limit;

    IF r.age >= lv_avg_age THEN
      lv_label := 'SENIOR';
    ELSE
      lv_label := 'JUNIOR';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Alien ' || TO_CHAR(lv_rownum) || ': ' || TO_CHAR(r.id) || ' - ' || r.full_name ||
      ' | age=' || TO_CHAR(r.age) || ' | ' || r.current_location || ' | ' || r.occupation ||
      ' | ' || lv_label
    );
  END LOOP;

  IF lv_rownum = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No aggressive aliens found for country: ' || lv_country);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No aggressive aliens found for country: ' || lv_country);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

