CREATE OR REPLACE PROCEDURE report_region_ticker_activity(
  p_region IN BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE,
  p_ticker IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.ticker%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region          BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE := p_region;
  lv_ticker          BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.ticker%TYPE := p_ticker;
  lv_latest_mkt_date BANK_SALES_TRADING.BITCOIN_PRICES.market_date%TYPE;
  lv_latest_price    BANK_SALES_TRADING.BITCOIN_PRICES.price%TYPE;
  lv_rows_printed    PLS_INTEGER := 0;
BEGIN
  -- Input defaults
  IF lv_region IS NULL THEN
    lv_region := 'UNKNOWN';
    DBMS_OUTPUT.PUT_LINE('Input region is NULL; defaulting to ''UNKNOWN''.');
  END IF;

  IF lv_ticker IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input ticker is NULL; defaulting to the most recent ticker from price history.');

    SELECT p.ticker
      INTO lv_ticker
      FROM (
            SELECT p1.ticker,
                   ROW_NUMBER() OVER (ORDER BY p1.market_date DESC) AS rn
              FROM BANK_SALES_TRADING.BITCOIN_PRICES p1
           ) p
     WHERE p.rn = 1;
  END IF;

  -- Latest price snapshot for the chosen ticker
  SELECT p.price, p.market_date
    INTO lv_latest_price, lv_latest_mkt_date
    FROM (
          SELECT p1.price,
                 p1.market_date,
                 ROW_NUMBER() OVER (ORDER BY p1.market_date DESC) AS rn
            FROM BANK_SALES_TRADING.BITCOIN_PRICES p1
           WHERE p1.ticker = lv_ticker
         ) p
   WHERE p.rn = 1;

  DBMS_OUTPUT.PUT_LINE(
    'Snapshot: ticker=' || lv_ticker ||
    ', latest_market_date=' || lv_latest_mkt_date ||
    ', latest_price=' || TO_CHAR(lv_latest_price)
  );

  DBMS_OUTPUT.PUT_LINE('Top members by total quantity for region=' || lv_region || ', ticker=' || lv_ticker || ':');

  -- Use an implicit cursor FOR loop (no explicit cursors per requirements)
  FOR rec IN (
    WITH member_totals AS (
      SELECT t.member_id,
             SUM(t.quantity) AS total_qty
        FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
        INNER JOIN BANK_SALES_TRADING.BITCOIN_MEMBERS m
          ON m.member_id = t.member_id
       WHERE m.region = lv_region
         AND t.ticker = lv_ticker
       GROUP BY t.member_id
    )
    SELECT member_id, first_name, total_qty
      FROM (
        SELECT mt.member_id,
               m.first_name,
               mt.total_qty,
               ROW_NUMBER() OVER (ORDER BY mt.total_qty DESC, mt.member_id) AS rn
          FROM member_totals mt
          INNER JOIN BANK_SALES_TRADING.BITCOIN_MEMBERS m
            ON m.member_id = mt.member_id
      )
     WHERE rn <= co_report_limit
     ORDER BY total_qty DESC, member_id
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      '  member_id=' || rec.member_id ||
      ', first_name=' || rec.first_name ||
      ', total_qty=' || TO_CHAR(rec.total_qty)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No qualifying transactions found for region=' || lv_region || ', ticker=' || lv_ticker || '.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_ticker_activity;
/

CREATE OR REPLACE PROCEDURE report_solution_model_scores(
  p_solution_name    IN STACKING.SOLUTION.name%TYPE,
  p_solution_version IN STACKING.SOLUTION.version%TYPE,
  p_min_test_score   IN STACKING.MODEL_SCORE.test_score%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_solution_score STACKING.SOLUTION.score%TYPE;
  lv_status         VARCHAR2(20);
BEGIN
  -- Validate that the solution exists and get its overall score (single-row expectation).
  SELECT s.score
    INTO lv_solution_score
    FROM STACKING.SOLUTION s
   WHERE s.name = p_solution_name
     AND s.version = p_solution_version;

  DBMS_OUTPUT.PUT_LINE('Solution: ' || p_solution_name || ' v' || p_solution_version);
  DBMS_OUTPUT.PUT_LINE('Score: ' || TO_CHAR(lv_solution_score));

  -- Print up to 15 model score rows for this run.
  FOR rec IN (
    SELECT ms.model,
           ms.train_score,
           ms.test_score
      FROM STACKING.MODEL_SCORE ms
     WHERE ms.name = p_solution_name
       AND ms.version = p_solution_version
     ORDER BY ms.step, ms.model
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    IF rec.test_score IS NOT NULL AND p_min_test_score IS NOT NULL AND rec.test_score >= p_min_test_score THEN
      lv_status := 'OK';
    ELSE
      lv_status := 'REVIEW';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'MODEL=' || rec.model ||
      ' TRAIN=' || TO_CHAR(rec.train_score) ||
      ' TEST=' || TO_CHAR(rec.test_score) ||
      ' STATUS=' || lv_status
    );
  END LOOP;

  -- If no rows were printed, report it.
  IF SQL%ROWCOUNT = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No models found for this solution/version.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching solution found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple solutions matched.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_solution_model_scores;
/

