DECLARE
  -- Inputs (set these values before running in your environment)
  lv_county_name  SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE := 'Los Angeles County, CA';
  lv_start_year   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE := DATE '2016-01-01';
  lv_end_year     SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE := DATE '2020-01-01';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for readability

  lv_year         SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE;
  lv_births_num   NUMBER;
  lv_avg_age_num  NUMBER;

  lv_any_rows     BOOLEAN := FALSE;
BEGIN
  -- Basic input validation
  IF lv_start_year > lv_end_year THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: start year is after end year.');
    RETURN;
  END IF;

  -- Report up to 15 year rows for the county
  FOR r IN (
    SELECT cn.year,
           TO_NUMBER(cn.births) AS births_num,
           TO_NUMBER(cn.ave_age_of_mother) AS avg_age_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.county_of_residence = lv_county_name
       AND cn.year BETWEEN lv_start_year AND lv_end_year
     ORDER BY cn.year
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_any_rows := TRUE;

    lv_year := r.year;
    lv_births_num := r.births_num;
    lv_avg_age_num := r.avg_age_num;

    DBMS_OUTPUT.PUT_LINE(
      'Year=' || TO_CHAR(lv_year, 'YYYY') ||
      ', Births=' || TO_CHAR(lv_births_num) ||
      ', AvgMotherAge=' || TO_CHAR(lv_avg_age_num)
    );
  END LOOP;

  IF NOT lv_any_rows THEN
    -- Raise NO_DATA_FOUND in a controlled way to reuse the required handler
    SELECT cn.year
      INTO lv_year
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE 1 = 2;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

