question:
Your operations team wants a reusable routine to quickly audit delivery performance for a specific channel name. Build a stored procedure that:

Validates the channel name input.
Pulls a small ranked report (max 15 rows) of the longest deliveries (by distance) for that channel, showing the delivery id, order id, driver id, distance, and delivery status.
Also prints a short summary: total deliveries for the channel, and the average distance.

Use control flow so that if the channel has no deliveries you print a clear message and stop the report section. Make sure all errors are caught and reported via DBMS_OUTPUT without propagating exceptions.

Requirements:
Procedure Name: dc_channel_delivery_audit
Parameters:
p_channel_name IN DELIVERY_CENTER.CHANNELS.channel_name%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Audit for channel: ' || p_channel_name);
DBMS_OUTPUT.PUT_LINE('Invalid channel name (NULL or blank).');
DBMS_OUTPUT.PUT_LINE('Channel not found.');
DBMS_OUTPUT.PUT_LINE('No deliveries found for this channel.');
DBMS_OUTPUT.PUT_LINE('Total deliveries: ' || lv_total_deliveries);
DBMS_OUTPUT.PUT_LINE('Average distance (m): ' || lv_avg_distance);
DBMS_OUTPUT.PUT_LINE('Top longest deliveries (up to ' || co_report_limit || '):');
DBMS_OUTPUT.PUT_LINE('Rank=' || rec.rn || ', delivery_id=' || rec.delivery_id || ', order_id=' || rec.order_id || ', driver_id=' || rec.driver_id || ', distance_m=' || rec.delivery_distance_meters || ', status=' || rec.delivery_status);
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE dc_channel_delivery_audit(
  p_channel_name IN DELIVERY_CENTER.CHANNELS.channel_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_channel_id       DELIVERY_CENTER.CHANNELS.channel_id%TYPE;
  lv_total_deliveries NUMBER;
  lv_avg_distance     NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Audit for channel: ' || p_channel_name);

  -- Basic input validation (avoid querying with NULL/blank)
  IF p_channel_name IS NULL OR TRIM(p_channel_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid channel name (NULL or blank).');
    RETURN;
  END IF;

  -- Resolve channel id (single row expected)
  SELECT c.channel_id
    INTO lv_channel_id
    FROM DELIVERY_CENTER.CHANNELS c
   WHERE c.channel_name = p_channel_name;

  -- Summary metrics for the channel
  SELECT COUNT(*), AVG(d.delivery_distance_meters)
    INTO lv_total_deliveries, lv_avg_distance
    FROM DELIVERY_CENTER.ORDERS o
    INNER JOIN DELIVERY_CENTER.DELIVERIES d
      ON d.delivery_order_id = o.delivery_order_id
   WHERE o.channel_id = lv_channel_id;

  IF lv_total_deliveries = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No deliveries found for this channel.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Total deliveries: ' || lv_total_deliveries);
  DBMS_OUTPUT.PUT_LINE('Average distance (m): ' || lv_avg_distance);
  DBMS_OUTPUT.PUT_LINE('Top longest deliveries (up to ' || co_report_limit || '):');

  -- Ranked detail report (longest deliveries first)
  FOR rec IN (
    WITH ranked AS (
      SELECT d.delivery_id,
             o.order_id,
             d.driver_id,
             d.delivery_distance_meters,
             d.delivery_status,
             ROW_NUMBER() OVER (ORDER BY d.delivery_distance_meters DESC, d.delivery_id DESC) AS rn
        FROM DELIVERY_CENTER.ORDERS o
        INNER JOIN DELIVERY_CENTER.DELIVERIES d
          ON d.delivery_order_id = o.delivery_order_id
       WHERE o.channel_id = lv_channel_id
    )
    SELECT r.delivery_id,
           r.order_id,
           r.driver_id,
           r.delivery_distance_meters,
           r.delivery_status,
           r.rn
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'Rank=' || rec.rn ||
      ', delivery_id=' || rec.delivery_id ||
      ', order_id=' || rec.order_id ||
      ', driver_id=' || rec.driver_id ||
      ', distance_m=' || rec.delivery_distance_meters ||
      ', status=' || rec.delivery_status
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    -- Either channel name not found OR unexpected single-row lookup failure
    IF lv_channel_id IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Channel not found.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END dc_channel_delivery_audit;
/

CREATE OR REPLACE PROCEDURE report_hha_payments_by_state(
  p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_payment CMS_MEDICARE.HOME_HEALTH_AGENCIES.total_hha_medicare_payment_amount_non_lupa%TYPE;
  ln_payment NUMBER;
  lv_level   VARCHAR2(10);

  ln_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_state IS NULL OR TRIM(p_state) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('State is required.');
    RETURN;
  END IF;

  FOR rec IN (
    SELECT hha.provider_id,
           hha.agency_name,
           hha.city,
           hha.total_hha_medicare_payment_amount_non_lupa
      FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
     WHERE hha.state = TRIM(p_state)
     ORDER BY hha.agency_name
  ) LOOP
    ln_rows_printed := ln_rows_printed + 1;
    IF ln_rows_printed > co_report_limit THEN
      EXIT;
    END IF;

    lv_payment := rec.total_hha_medicare_payment_amount_non_lupa;

    -- Convert stored text amount to a number; blank/NULL treated as 0.
    ln_payment := CASE
                    WHEN lv_payment IS NULL OR TRIM(lv_payment) IS NULL THEN 0
                    ELSE TO_NUMBER(TRIM(lv_payment))
                  END;

    IF ln_payment >= 100000 THEN
      lv_level := 'HIGH_PAY';
    ELSE
      lv_level := 'NORMAL';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Provider: ' || rec.provider_id ||
      ' | Agency: ' || rec.agency_name ||
      ' | City: ' || rec.city ||
      ' | Payment: ' || TO_CHAR(ln_payment) ||
      ' | Level: ' || lv_level
    );
  END LOOP;

  IF ln_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No agencies found for the given state.');
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Invalid payment value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_hha_payments_by_state;
/

DECLARE
  -- Inputs (set these before running)
  p_country CITY_LEGISLATION.ALIEN_DATA.country%TYPE := 'United States';
  p_state   CITY_LEGISLATION.ALIEN_DATA.state%TYPE   := NULL;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_aliens(
    cp_country CITY_LEGISLATION.ALIEN_DATA.country%TYPE,
    cp_state   CITY_LEGISLATION.ALIEN_DATA.state%TYPE
  ) IS
    SELECT ad.first_name,
           ad.last_name,
           ad.email,
           ad.current_location,
           ad.state,
           ad.country,
           ad.aggressive
      FROM CITY_LEGISLATION.ALIEN_DATA ad
     WHERE ad.country = cp_country
       AND (cp_state IS NULL OR ad.state = cp_state)
       AND ROWNUM <= co_report_limit
     ORDER BY ad.current_location, ad.last_name;

  lv_rows_printed     PLS_INTEGER := 0;
  lv_aggressive_count PLS_INTEGER := 0;
BEGIN
  FOR r_alien IN c_aliens(p_country, p_state) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    IF r_alien.aggressive = 1 THEN
      lv_aggressive_count := lv_aggressive_count + 1;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Alien: ' || r_alien.first_name || ' ' || r_alien.last_name ||
      ' | Email: ' || r_alien.email ||
      ' | Location: ' || r_alien.current_location || ', ' || r_alien.state || ', ' || r_alien.country ||
      ' | Aggressive: ' || CASE WHEN r_alien.aggressive = 1 THEN 'Y' ELSE 'N' END
    );
  END LOOP;

  IF lv_rows_printed > 0 THEN
    DBMS_OUTPUT.PUT_LINE('Summary: rows_printed=' || lv_rows_printed || ', aggressive_count=' || lv_aggressive_count);
  ELSE
    DBMS_OUTPUT.PUT_LINE('Summary: no matching aliens found for filters.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

