question:
Operations wants a quick "sales pulse" for a single country: list up to 15 of the most recent invoices for that country (invoice id, invoice date, customer name, and total). If the user doesn't provide a country, default to the most common customer country in the system. Also print a short summary line that says whether the country is a "High value" market based on the average invoice total for that country (>= 5.00), otherwise "Standard". Make sure the script never crashes: handle missing data and any unexpected errors cleanly.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('Using country: ' || lv_country);
DBMS_OUTPUT.PUT_LINE('Market segment: High value');
DBMS_OUTPUT.PUT_LINE('Market segment: Standard');
DBMS_OUTPUT.PUT_LINE('InvoiceId=' || inv.invoiceid || ', InvoiceDate=' || TO_CHAR(inv.invoicedate, 'YYYY-MM-DD') || ', Customer=' || inv.customer_name || ', Total=' || TO_CHAR(inv.total, 'FM9999990.00'));
DBMS_OUTPUT.PUT_LINE('No invoices found for the selected country.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No invoices found for the selected country.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  -- Input (can be set to NULL to use default country)
  lv_input_country CHINOOK.CUSTOMERS.country%TYPE := NULL;

  lv_country       CHINOOK.CUSTOMERS.country%TYPE;
  lv_avg_total     CHINOOK.INVOICES.total%TYPE;

  co_report_limit  CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  -- Default the country to the most common customer country if not provided
  IF lv_input_country IS NULL THEN
    SELECT country
      INTO lv_country
      FROM (
        SELECT c.country
          FROM CHINOOK.CUSTOMERS c
         GROUP BY c.country
         ORDER BY COUNT(*) DESC, c.country
      )
     WHERE ROWNUM = 1;
  ELSE
    lv_country := lv_input_country;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Using country: ' || lv_country);

  -- Compute average invoice total for the selected country
  SELECT AVG(i.total)
    INTO lv_avg_total
    FROM CHINOOK.INVOICES i
    INNER JOIN CHINOOK.CUSTOMERS c
      ON c.customerid = i.customerid
   WHERE c.country = lv_country;

  IF lv_avg_total >= 5 THEN
    DBMS_OUTPUT.PUT_LINE('Market segment: High value');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Market segment: Standard');
  END IF;

  -- Print up to 15 most recent invoices for the selected country
  FOR inv IN (
    SELECT i.invoiceid,
           i.invoicedate,
           (c.firstname || ' ' || c.lastname) AS customer_name,
           i.total
      FROM CHINOOK.INVOICES i
      INNER JOIN CHINOOK.CUSTOMERS c
        ON c.customerid = i.customerid
     WHERE c.country = lv_country
     ORDER BY i.invoicedate DESC, i.invoiceid DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'InvoiceId=' || inv.invoiceid ||
      ', InvoiceDate=' || TO_CHAR(inv.invoicedate, 'YYYY-MM-DD') ||
      ', Customer=' || inv.customer_name ||
      ', Total=' || TO_CHAR(inv.total, 'FM9999990.00')
    );
  END LOOP;

  -- If average was NULL, there are no invoices for the country
  IF lv_avg_total IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No invoices found for the selected country.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No invoices found for the selected country.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

