CREATE OR REPLACE PROCEDURE report_country_debt_snapshot(
  p_country_code IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.country_code%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country_name WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.short_name%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Validate that the country exists (single-row fetch expected for a code)
  SELECT cs.short_name
    INTO lv_country_name
    FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
   WHERE cs.country_code = p_country_code;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name || ' (' || p_country_code || ')');

  -- Print a snapshot of up to N debt indicator rows with numeric conversions and categorization
  FOR rec IN (
    SELECT d.year AS year_txt,
           d.indicator_name,
           TO_NUMBER(d.value) AS value_num,
           CASE
             WHEN TO_NUMBER(d.value) >= 1000000000 THEN 'HIGH'
             ELSE 'LOW'
           END AS value_level
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
     WHERE d.country_code = p_country_code
     ORDER BY TO_NUMBER(d.year) DESC, d.indicator_name
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      'Year=' || rec.year_txt ||
      ' | Indicator=' || rec.indicator_name ||
      ' | Value=' || TO_CHAR(rec.value_num) ||
      ' | Level=' || rec.value_level
    );
  END LOOP;

  -- Control flow: if the loop produced no rows, treat it as a reportable no-data condition
  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No debt rows found for country code ' || p_country_code || '.');
  END IF;

EXCEPTION
  -- If country code does not exist
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No debt rows found for country code ' || p_country_code || '.');
  -- If the country summary unexpectedly has duplicate country codes
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('No debt rows found for country code ' || p_country_code || '.');
  -- Bad numeric text in YEAR or VALUE conversion
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric data encountered for country code ' || p_country_code || '.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_debt_snapshot;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year            WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE := '2019';
  lv_keyword         VARCHAR2(100) := 'debt';
  lv_rows_printed    PLS_INTEGER := 0;

  CURSOR c_top_country_debt(
    p_year    IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE,
    p_keyword IN VARCHAR2
  ) IS
    WITH base AS (
      SELECT
        d.indicator_name,
        d.country_name,
        d.year,
        TO_NUMBER(d.value) AS value_num
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
      WHERE d.year = p_year
        AND (p_keyword IS NULL OR LOWER(d.indicator_name) LIKE '%' || LOWER(p_keyword) || '%')
        AND REGEXP_LIKE(d.value, '^\s*[-+]?[0-9]*\.?[0-9]+\s*$')
    ), ranked AS (
      SELECT
        b.indicator_name,
        b.country_name,
        b.year,
        b.value_num,
        ROW_NUMBER() OVER (
          PARTITION BY b.indicator_name
          ORDER BY b.value_num DESC
        ) AS rn
      FROM base b
    )
    SELECT
      r.indicator_name,
      r.country_name,
      r.year,
      r.value_num
    FROM ranked r
    WHERE r.rn <= 3
      AND ROWNUM <= co_report_limit
    ORDER BY r.indicator_name, r.value_num DESC;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Debt risk scan for year=' || lv_year || ', keyword=' || lv_keyword);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));

  FOR rec IN c_top_country_debt(lv_year, lv_keyword) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      'INDICATOR=' || rec.indicator_name ||
      ' | COUNTRY=' || rec.country_name ||
      ' | YEAR=' || rec.year ||
      ' | VALUE=' || TO_CHAR(rec.value_num)
    );
  END LOOP;

  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));

  IF lv_rows_printed < 3 THEN
    DBMS_OUTPUT.PUT_LINE('WARNING: Fewer than 3 rows printed; broaden your keyword or verify data availability.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Done. Rows printed=' || TO_CHAR(lv_rows_printed));
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Value error encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

