question:
Your analytics team wants a reusable routine that prints a small county-level natality quality report for a given year and state FIPS prefix. The report should:

Summarize total births by county for the requested year for all counties whose COUNTY_OF_RESIDENCE_FIPS starts with the provided state prefix.
For each county, also show how many births are associated with congenital abnormality records marked as "Y" for that same year (join by year, county name, and county FIPS).
Print only the top counties by births (for readability) and include a simple "data quality" note when numeric conversions fail (because BIRTHS is stored as VARCHAR2).

Implement this as a stored procedure that uses an explicit cursor to iterate through the ranked county list, handles missing inputs, and never allows runtime errors to escape to the client.

Requirements:
Procedure Name: report_top_county_births
Parameters:
p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
p_state_fips_prefix IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Report parameters - Year: ' || TO_CHAR(p_year, 'YYYY') || ', State FIPS prefix: ' || p_state_fips_prefix);
DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD('County', 35) || ' | ' || LPAD('Births', 12) || ' | ' || LPAD('CongAbn(Y) Births', 18) || ' | Note');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(lv_county, 35) || ' | ' || LPAD(TO_CHAR(lv_births), 12) || ' | ' || LPAD(TO_CHAR(lv_cong_abn_births), 18) || ' | ' || lv_note);
DBMS_OUTPUT.PUT_LINE('No rows matched the requested year/prefix.');
DBMS_OUTPUT.PUT_LINE('Input validation failed: both parameters are required.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_top_county_births(
  p_year             IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_state_fips_prefix IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_county           SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE;
  lv_births           NUMBER;
  lv_cong_abn_births  NUMBER;
  lv_note             VARCHAR2(200);

  lv_rows_printed     PLS_INTEGER := 0;

  CURSOR c_top IS
    WITH county_totals AS (
      SELECT
        cn.county_of_residence       AS county_of_residence,
        cn.county_of_residence_fips  AS county_of_residence_fips,
        SUM(TO_NUMBER(cn.births DEFAULT NULL ON CONVERSION ERROR)) AS births_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
      WHERE cn.year = p_year
        AND cn.county_of_residence_fips LIKE p_state_fips_prefix || '%'
      GROUP BY cn.county_of_residence, cn.county_of_residence_fips
    ),
    cong_abn_totals AS (
      SELECT
        ca.county_of_residence      AS county_of_residence,
        ca.county_of_residence_fips AS county_of_residence_fips,
        SUM(TO_NUMBER(ca.births DEFAULT NULL ON CONVERSION ERROR)) AS cong_births_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_CONGENITAL_ABNORMALITIES ca
      WHERE ca.year = p_year
        AND ca.county_of_residence_fips LIKE p_state_fips_prefix || '%'
        AND ca.congenital_abnormality_checked_yn = 'Y'
      GROUP BY ca.county_of_residence, ca.county_of_residence_fips
    ),
    ranked AS (
      SELECT
        ct.county_of_residence,
        ct.county_of_residence_fips,
        NVL(ct.births_num, 0) AS births_num,
        NVL(cat.cong_births_num, 0) AS cong_births_num,
        ROW_NUMBER() OVER (
          ORDER BY NVL(ct.births_num, 0) DESC, ct.county_of_residence
        ) AS rn,
        CASE
          WHEN ct.births_num IS NULL THEN 'Non-numeric births in COUNTY_NATALITY'
          ELSE NULL
        END AS note
      FROM county_totals ct
      LEFT JOIN cong_abn_totals cat
        ON cat.county_of_residence = ct.county_of_residence
       AND cat.county_of_residence_fips = ct.county_of_residence_fips
    )
    SELECT
      r.county_of_residence,
      r.births_num,
      r.cong_births_num,
      r.note
    FROM ranked r
    WHERE r.rn <= co_report_limit
    ORDER BY r.rn;

BEGIN
  IF p_year IS NULL OR p_state_fips_prefix IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: both parameters are required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Report parameters - Year: ' || TO_CHAR(p_year, 'YYYY') || ', State FIPS prefix: ' || p_state_fips_prefix);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
  DBMS_OUTPUT.PUT_LINE(RPAD('County', 35) || ' | ' || LPAD('Births', 12) || ' | ' || LPAD('CongAbn(Y) Births', 18) || ' | Note');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));

  OPEN c_top;
  LOOP
    FETCH c_top INTO lv_county, lv_births, lv_cong_abn_births, lv_note;
    EXIT WHEN c_top%NOTFOUND;

    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(lv_county, 35) || ' | ' ||
      LPAD(TO_CHAR(lv_births), 12) || ' | ' ||
      LPAD(TO_CHAR(lv_cong_abn_births), 18) || ' | ' ||
      NVL(lv_note, '')
    );
  END LOOP;
  CLOSE c_top;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested year/prefix.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_top%ISOPEN THEN
      CLOSE c_top;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF c_top%ISOPEN THEN
      CLOSE c_top;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF c_top%ISOPEN THEN
      CLOSE c_top;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_county_births;
/

DECLARE
  -- Inputs (simulate parameters for an anonymous run)
  lv_country_name  CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE := 'Canada';
  lv_start_year    CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE := '2000';
  lv_end_year      CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE := '2010';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year      CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE;
  lv_tfr_raw   CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;
  lv_tfr_num   NUMBER;
  lv_class     VARCHAR2(20);

  lv_valid_rows   PLS_INTEGER := 0;
  lv_sum_tfr      NUMBER := 0;
  lv_min_tfr      NUMBER;
  lv_max_tfr      NUMBER;
  lv_avg_tfr      NUMBER;
  lv_rows_seen    PLS_INTEGER := 0;

  CURSOR cur_tfr(p_country CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
                 p_start   CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
                 p_end     CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE) IS
    SELECT a.year,
           a.total_fertility_rate
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
     WHERE a.country_name = p_country
       AND a.year BETWEEN p_start AND p_end
     ORDER BY a.year;

  lv_start_num NUMBER;
  lv_end_num   NUMBER;
BEGIN
  -- Basic input validation
  IF lv_country_name IS NULL OR TRIM(lv_country_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No valid rows found for country=' || lv_country_name || ' years=' || lv_start_year || '-' || lv_end_year);
    RETURN;
  END IF;

  IF lv_start_year IS NULL OR lv_end_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No valid rows found for country=' || lv_country_name || ' years=' || lv_start_year || '-' || lv_end_year);
    RETURN;
  END IF;

  IF NOT REGEXP_LIKE(lv_start_year, '^\d{4}$') OR NOT REGEXP_LIKE(lv_end_year, '^\d{4}$') THEN
    DBMS_OUTPUT.PUT_LINE('No valid rows found for country=' || lv_country_name || ' years=' || lv_start_year || '-' || lv_end_year);
    RETURN;
  END IF;

  lv_start_num := TO_NUMBER(lv_start_year);
  lv_end_num := TO_NUMBER(lv_end_year);

  IF lv_start_num > lv_end_num THEN
    DBMS_OUTPUT.PUT_LINE('No valid rows found for country=' || lv_country_name || ' years=' || lv_start_year || '-' || lv_end_year);
    RETURN;
  END IF;

  -- Iterate with an explicit, named cursor
  FOR r IN cur_tfr(lv_country_name, lv_start_year, lv_end_year) LOOP
    lv_rows_seen := lv_rows_seen + 1;

    lv_year := r.year;
    lv_tfr_raw := r.total_fertility_rate;

    -- Data quality check: only keep numeric TFRs
    IF lv_tfr_raw IS NOT NULL AND REGEXP_LIKE(TRIM(lv_tfr_raw), '^-?\d+(\.\d+)?$') THEN
      lv_tfr_num := TO_NUMBER(TRIM(lv_tfr_raw));

      IF lv_tfr_num < 2.1 THEN
        lv_class := 'LOW';
      ELSIF lv_tfr_num <= 3.5 THEN
        lv_class := 'REPLACEMENT';
      ELSE
        lv_class := 'HIGH';
      END IF;

      -- Enforce output row limit based on valid rows only
      IF lv_valid_rows < co_report_limit THEN
        DBMS_OUTPUT.PUT_LINE('YEAR=' || lv_year || ' TFR=' || TO_CHAR(lv_tfr_num) || ' CLASS=' || lv_class);
      END IF;

      lv_valid_rows := lv_valid_rows + 1;
      lv_sum_tfr := lv_sum_tfr + lv_tfr_num;

      IF lv_min_tfr IS NULL OR lv_tfr_num < lv_min_tfr THEN
        lv_min_tfr := lv_tfr_num;
      END IF;

      IF lv_max_tfr IS NULL OR lv_tfr_num > lv_max_tfr THEN
        lv_max_tfr := lv_tfr_num;
      END IF;

      IF lv_valid_rows >= co_report_limit THEN
        EXIT;
      END IF;
    END IF;
  END LOOP;

  IF lv_valid_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No valid rows found for country=' || lv_country_name || ' years=' || lv_start_year || '-' || lv_end_year);
  ELSE
    lv_avg_tfr := lv_sum_tfr / lv_valid_rows;
    DBMS_OUTPUT.PUT_LINE('SUMMARY country=' || lv_country_name || ' years=' || lv_start_year || '-' || lv_end_year || ' valid_rows=' || TO_CHAR(lv_valid_rows) || ' avg_tfr=' || TO_CHAR(lv_avg_tfr) || ' min_tfr=' || TO_CHAR(lv_min_tfr) || ' max_tfr=' || TO_CHAR(lv_max_tfr));
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

