  lv_end_num := TO_NUMBER(lv_end_year);
  FOR r IN cur_tfr(lv_country_name, lv_start_year, lv_end_year) LOOP NULL; END LOOP;
  IF lv_valid_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No valid rows found for country=' || lv_country_name || ' years=' || lv_start_year || '-' || lv_end_year);
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

