CREATE OR REPLACE PROCEDURE report_solution_models(
  p_solution_name    IN STACKING.SOLUTION.name%TYPE,
  p_solution_version IN STACKING.SOLUTION.version%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_correlation STACKING.SOLUTION.correlation%TYPE;
  lv_nb_model    STACKING.SOLUTION.nb_model%TYPE;
  lv_nb_feature  STACKING.SOLUTION.nb_feature%TYPE;
  lv_score       STACKING.SOLUTION.score%TYPE;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation (do not crash on NULLs)
  IF p_solution_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Missing input: solution name is required.');
    RETURN;
  END IF;

  IF p_solution_version IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Missing input: solution version is required.');
    RETURN;
  END IF;

  -- Verify the solution exists and fetch its summary values
  SELECT s.correlation,
         s.nb_model,
         s.nb_feature,
         s.score
    INTO lv_correlation,
         lv_nb_model,
         lv_nb_feature,
         lv_score
    FROM STACKING.SOLUTION s
   WHERE s.name = p_solution_name
     AND s.version = p_solution_version;

  DBMS_OUTPUT.PUT_LINE('Solution: ' || p_solution_name || ' v' || TO_CHAR(p_solution_version));
  DBMS_OUTPUT.PUT_LINE(
    'Correlation: ' || TO_CHAR(lv_correlation) ||
    ' | Nb Models: ' || TO_CHAR(lv_nb_model) ||
    ' | Nb Features: ' || TO_CHAR(lv_nb_feature) ||
    ' | Score: ' || TO_CHAR(lv_score)
  );

  DBMS_OUTPUT.PUT_LINE('Model list (up to ' || TO_CHAR(co_report_limit) || ' rows):');

  -- Print up to 15 models for the solution, with any available train/test scores.
  FOR rec IN (
    SELECT m.step,
           m.l1_model AS model,
           ms.train_score,
           ms.test_score
      FROM STACKING.MODEL m
      LEFT JOIN STACKING.MODEL_SCORE ms
        ON ms.name = m.name
       AND ms.version = m.version
       AND ms.step = m.step
       AND ms.model = m.l1_model
     WHERE m.name = p_solution_name
       AND m.version = p_solution_version
     ORDER BY m.step, m.l1_model
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      '  Step=' || TO_CHAR(rec.step) ||
      ' | Model=' || rec.model ||
      ' | Train=' || TO_CHAR(rec.train_score) ||
      ' | Test=' || TO_CHAR(rec.test_score)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No models found for this solution.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_solution_models;
/

CREATE OR REPLACE PROCEDURE report_indicator_country_values(
  p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE,
  p_year           IN WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed  PLS_INTEGER := 0;
  lv_numeric_flag  VARCHAR2(3);
  lv_year_num      NUMBER;
BEGIN
  -- Basic input validation
  IF p_indicator_code IS NULL OR TRIM(p_indicator_code) IS NULL OR p_year IS NULL OR TRIM(p_year) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
    RETURN;
  END IF;

  -- Validate year format (must be numeric)
  lv_year_num := TO_NUMBER(TRIM(p_year));

  DBMS_OUTPUT.PUT_LINE('Report for indicator_code=' || p_indicator_code || ', year=' || p_year);

  -- Retrieve and print up to 15 country rows for the indicator/year
  FOR rec IN (
    SELECT d.country_name,
           d.country_code,
           d.value
      FROM WORLD_BANK_WDI.INDICATORS_DATA d
     WHERE d.indicator_code = p_indicator_code
       AND d.year = p_year
     ORDER BY d.country_name
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    -- Classify whether VALUE looks numeric (VALUE is stored as VARCHAR2)
    BEGIN
      IF rec.value IS NULL THEN
        lv_numeric_flag := 'NO';
      ELSE
        DECLARE
          lv_dummy NUMBER;
        BEGIN
          lv_dummy := TO_NUMBER(TRIM(rec.value));
          lv_numeric_flag := 'YES';
        EXCEPTION
          WHEN VALUE_ERROR THEN
            lv_numeric_flag := 'NO';
        END;
      END IF;
    END;

    DBMS_OUTPUT.PUT_LINE(
      'Country=' || rec.country_name || ' (' || rec.country_code || '), value=' || NVL(rec.value, 'NULL') || ', numeric_flag=' || lv_numeric_flag
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    -- Standardized way to surface the empty result case
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Rows printed=' || lv_rows_printed);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_indicator_country_values;
/

CREATE OR REPLACE PROCEDURE report_intersectional_rep(
  p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE,
  p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_top_white   NUMBER := 0;
  lv_label       VARCHAR2(10);
  lv_row_count   PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Intersectional representation report');
  DBMS_OUTPUT.PUT_LINE('Year=' || p_report_year || ', Workforce=' || p_workforce);

  -- Guard against missing parameters.
  IF p_report_year IS NULL OR p_workforce IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No rows for the provided filters.');
    RETURN;
  END IF;

  -- Find the top numeric RACE_WHITE value (treat non-numeric/missing as zero).
  SELECT MAX(
           CASE
             WHEN REGEXP_LIKE(race_white, '^\s*-?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(race_white))
             ELSE 0
           END
         )
    INTO lv_top_white
    FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION
   WHERE report_year = p_report_year
     AND workforce = p_workforce;

  IF lv_top_white >= 50 THEN
    lv_label := 'HIGH';
  ELSIF lv_top_white >= 20 THEN
    lv_label := 'MEDIUM';
  ELSE
    lv_label := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top RACE_WHITE value=' || TO_CHAR(lv_top_white) || ', Label=' || lv_label);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));

  -- Print up to 15 rows ordered by numeric RACE_WHITE descending.
  FOR rec IN (
    SELECT r.gender_us,
           r.race_asian,
           r.race_black,
           r.race_hispanic_latinx,
           r.race_native_american,
           r.race_white
      FROM (
        SELECT gender_us,
               race_asian,
               race_black,
               race_hispanic_latinx,
               race_native_american,
               race_white,
               CASE
                 WHEN REGEXP_LIKE(race_white, '^\s*-?\d+(\.\d+)?\s*$') THEN TO_NUMBER(TRIM(race_white))
                 ELSE 0
               END AS white_num
          FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION
         WHERE report_year = p_report_year
           AND workforce = p_workforce
         ORDER BY white_num DESC, gender_us
      ) r
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_row_count := lv_row_count + 1;
    DBMS_OUTPUT.PUT_LINE(
      'GENDER_US=' || rec.gender_us ||
      ', ASIAN=' || rec.race_asian ||
      ', BLACK=' || rec.race_black ||
      ', HISPANIC_LATINX=' || rec.race_hispanic_latinx ||
      ', NATIVE_AMERICAN=' || rec.race_native_american ||
      ', WHITE=' || rec.race_white
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows for the provided filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_intersectional_rep;
/

CREATE OR REPLACE PROCEDURE wdi_print_indicator_trend(
  p_country_code   IN WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE,
  p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country_name   WORLD_BANK_WDI.INDICATORS_DATA.country_name%TYPE;
  lv_indicator_name WORLD_BANK_WDI.INDICATORS_DATA.indicator_name%TYPE;
  lv_rows_printed   PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_country_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country code is required.');
    RETURN;
  ELSIF p_indicator_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: indicator code is required.');
    RETURN;
  ELSIF LENGTH(p_country_code) > 10 THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country code is too long.');
    RETURN;
  ELSIF LENGTH(p_indicator_code) > 50 THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: indicator code is too long.');
    RETURN;
  END IF;

  -- Derive display labels from the data (single-row fetch expected)
  SELECT MAX(d.country_name), MAX(d.indicator_name)
    INTO lv_country_name, lv_indicator_name
    FROM WORLD_BANK_WDI.INDICATORS_DATA d
   WHERE d.country_code = p_country_code
     AND d.indicator_code = p_indicator_code;

  IF lv_country_name IS NULL OR lv_indicator_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No indicator data found for the given country and indicator.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name);
  DBMS_OUTPUT.PUT_LINE('Indicator: ' || lv_indicator_name);
  DBMS_OUTPUT.PUT_LINE(RPAD('YEAR', 6) || 'VALUE');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 6, '-') || RPAD('-', 20, '-'));

  -- Print up to N most recent rows
  FOR rec IN (
    SELECT d.year, d.value
      FROM WORLD_BANK_WDI.INDICATORS_DATA d
     WHERE d.country_code = p_country_code
       AND d.indicator_code = p_indicator_code
     ORDER BY d.year DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(RPAD(rec.year, 6) || rec.value);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No indicator data found for the given country and indicator.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No indicator data found for the given country and indicator.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END wdi_print_indicator_trend;
/

CREATE OR REPLACE PROCEDURE rpt_patient_encounter_summary(
  p_patient_id IN SYNTHEA.ENCOUNTERS.patient%TYPE
) IS
  co_limit CONSTANT PLS_INTEGER := 15; -- Limit for any supporting query output

  lv_top_class      SYNTHEA.ENCOUNTERS.encounterclass%TYPE;
  lv_top_class_cnt  NUMBER;
  lv_total_cnt      NUMBER;
BEGIN
  IF p_patient_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No patient id provided.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Patient: ' || p_patient_id);

  -- Total encounter count for the patient
  SELECT COUNT(*)
    INTO lv_total_cnt
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.patient = p_patient_id;

  IF lv_total_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for patient: ' || p_patient_id);
    RETURN;
  END IF;

  -- Find the most common encounter class (ties broken deterministically by encounterclass)
  SELECT encounterclass, class_cnt
    INTO lv_top_class, lv_top_class_cnt
    FROM (
      SELECT e.encounterclass AS encounterclass,
             COUNT(*) AS class_cnt
        FROM SYNTHEA.ENCOUNTERS e
       WHERE e.patient = p_patient_id
       GROUP BY e.encounterclass
       ORDER BY COUNT(*) DESC, e.encounterclass ASC
    )
   WHERE ROWNUM = 1
     AND ROWNUM <= co_limit;

  DBMS_OUTPUT.PUT_LINE('Top encounter class: ' || lv_top_class);
  DBMS_OUTPUT.PUT_LINE('Encounters in top class: ' || lv_top_class_cnt);
  DBMS_OUTPUT.PUT_LINE('Total encounters: ' || lv_total_cnt);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for patient: ' || p_patient_id);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_patient_encounter_summary;
/

CREATE OR REPLACE PROCEDURE report_recent_race_top_drivers(
  p_year IN F1.RACES.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit races printed for report readability

  CURSOR cur_recent_races IS
    SELECT r.race_id,
           r.round AS round_no,
           r.name  AS race_name,
           TO_CHAR(r.c_date, 'YYYY-MM-DD') AS c_date_fmt
      FROM F1.RACES r
     WHERE r.year = p_year
     ORDER BY r.c_date DESC, r.round DESC
     FETCH FIRST co_report_limit ROWS ONLY;

  lv_result_count PLS_INTEGER;
  lv_rank         PLS_INTEGER;
BEGIN
  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Year is required.');
    RETURN;
  END IF;

  FOR rec_race IN cur_recent_races LOOP
    DBMS_OUTPUT.PUT_LINE(
      'Race: ' || rec_race.c_date_fmt || ' - ' || rec_race.race_name || ' (Round ' || rec_race.round_no || ')'
    );

    -- Check if there are any results for this race.
    SELECT COUNT(*)
      INTO lv_result_count
      FROM F1.RESULTS res
     WHERE res.race_id = rec_race.race_id;

    IF lv_result_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('  No results found for this race.');
    ELSE
      lv_rank := 0;

      -- Print up to 3 top scorers by points for the race.
      FOR rec_top IN (
        SELECT d.forename || ' ' || d.surname AS driver_name,
               c.name AS constructor_name,
               res.points
          FROM F1.RESULTS res
          INNER JOIN F1.DRIVERS d
            ON d.driver_id = res.driver_id
          INNER JOIN F1.CONSTRUCTORS c
            ON c.constructor_id = res.constructor_id
         WHERE res.race_id = rec_race.race_id
         ORDER BY res.points DESC, d.surname ASC, d.forename ASC
      ) LOOP
        lv_rank := lv_rank + 1;

        IF lv_rank <= 3 THEN
          DBMS_OUTPUT.PUT_LINE(
            '  #' || lv_rank || ' Driver: ' || rec_top.driver_name ||
            ' | Constructor: ' || rec_top.constructor_name ||
            ' | Points: ' || rec_top.points
