DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  -- Inputs (set these as needed)
  lv_year       SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE := DATE '2019-01-01';
  lv_min_births NUMBER := 1000;

  lv_births_num NUMBER;
  lv_category   VARCHAR2(10);

  lv_rows_printed PLS_INTEGER := 0;
  lv_rows_kept    PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Report Year = ' || TO_CHAR(lv_year, 'YYYY') || ', Min Births = ' || lv_min_births);

  FOR rec IN (
    SELECT cn.county_of_residence,
           cn.births
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = lv_year
     ORDER BY cn.county_of_residence
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    BEGIN
      lv_births_num := TO_NUMBER(rec.births);
    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Skipped county=' || rec.county_of_residence || ' due to non-numeric births.');
        CONTINUE;
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Skipped county=' || rec.county_of_residence || ' due to non-numeric births.');
        CONTINUE;
    END;

    IF lv_births_num < NVL(lv_min_births, 0) THEN
      CONTINUE;
    END IF;

    IF lv_births_num >= 5000 THEN
      lv_category := 'HIGH';
    ELSIF lv_births_num >= 1000 THEN
      lv_category := 'MEDIUM';
    ELSE
      lv_category := 'LOW';
    END IF;

    DBMS_OUTPUT.PUT_LINE('County=' || rec.county_of_residence || ', Births=' || TO_CHAR(lv_births_num) || ', Category=' || lv_category);

    lv_rows_printed := lv_rows_printed + 1;
    lv_rows_kept := lv_rows_kept + 1;
  END LOOP;

  IF lv_rows_kept = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No qualifying counties were found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

