question:
Your operations team wants a quick “station activity health check” report for a chosen landmark (e.g., San Francisco / San Jose / Redwood City). Build a PL/SQL anonymous block that:
Accepts a landmark value.
For that landmark, prints up to 15 stations ranked by total number of trips that started there.
For each printed station, also show the latest known snapshot time in the status table and the bikes/docks available at that time.
Add control flow so that stations with no matching status snapshots print "No status snapshot" instead of bikes/docks.
Make sure bad inputs (NULL landmark) and unexpected runtime issues are handled via exception handling and the script never crashes.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('Landmark = ' || lv_landmark);
DBMS_OUTPUT.PUT_LINE('Top stations by trip starts (limited to ' || co_report_limit || ' rows):');
DBMS_OUTPUT.PUT_LINE('Rank ' || rec.rn || ': ' || rec.station_name || ' (station_id=' || rec.station_id || '), trips_started=' || rec.trips_started || ', latest_status_time=' || rec.latest_time || ', bikes=' || rec.bikes_available || ', docks=' || rec.docks_available);
DBMS_OUTPUT.PUT_LINE('Rank ' || rec.rn || ': ' || rec.station_name || ' (station_id=' || rec.station_id || '), trips_started=' || rec.trips_started || ', No status snapshot');
DBMS_OUTPUT.PUT_LINE('No stations found for the provided landmark.');
DBMS_OUTPUT.PUT_LINE('Landmark must not be NULL.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No stations found for the provided landmark.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

tests:
SET SERVEROUTPUT ON;
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15;
  lv_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE := 'San Francisco';
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF lv_landmark IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Landmark must not be NULL.');
    RETURN;
  END IF;
  DBMS_OUTPUT.PUT_LINE('Landmark = ' || lv_landmark);
  DBMS_OUTPUT.PUT_LINE('Top stations by trip starts (limited to ' || co_report_limit || ' rows):');
  FOR rec IN (
    WITH trip_counts AS (
      SELECT s.station_id, s.name AS station_name, COUNT(t.trip_id) AS trips_started
        FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
        LEFT JOIN SAN_FRANCISCO.BIKESHARE_TRIPS t ON t.start_station_id = s.station_id
       WHERE s.landmark = lv_landmark
       GROUP BY s.station_id, s.name
    ), ranked AS (
      SELECT tc.station_id, tc.station_name, tc.trips_started,
             ROW_NUMBER() OVER (ORDER BY tc.trips_started DESC, tc.station_name) AS rn
        FROM trip_counts tc
    ), latest_status AS (
      SELECT bs.station_id, bs.time AS latest_time, bs.bikes_available, bs.docks_available
        FROM SAN_FRANCISCO.BIKESHARE_STATUS bs
        INNER JOIN (SELECT station_id, MAX(time) AS max_time FROM SAN_FRANCISCO.BIKESHARE_STATUS GROUP BY station_id) mx
          ON mx.station_id = bs.station_id AND mx.max_time = bs.time
    )
    SELECT r.rn, r.station_id, r.station_name, r.trips_started, ls.latest_time, ls.bikes_available, ls.docks_available
      FROM ranked r LEFT JOIN latest_status ls ON ls.station_id = r.station_id
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    IF rec.latest_time IS NOT NULL THEN
      DBMS_OUTPUT.PUT_LINE('Rank ' || rec.rn || ': ' || rec.station_name || ' (station_id=' || rec.station_id || '), trips_started=' || rec.trips_started || ', latest_status_time=' || rec.latest_time || ', bikes=' || rec.bikes_available || ', docks=' || rec.docks_available);
    ELSE
      DBMS_OUTPUT.PUT_LINE('Rank ' || rec.rn || ': ' || rec.station_name || ' (station_id=' || rec.station_id || '), trips_started=' || rec.trips_started || ', No status snapshot');
    END IF;
  END LOOP;
  IF lv_rows_printed = 0 THEN RAISE NO_DATA_FOUND; END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('No stations found for the provided landmark.');
  WHEN TOO_MANY_ROWS THEN DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

