reference_answer:
CREATE OR REPLACE PROCEDURE report_product_sales_snapshot(
  p_product_id IN ADVENTUREWORKS.PRODUCT.productid%TYPE
) IS
  lv_product_name ADVENTUREWORKS.PRODUCT.name%TYPE;
  lv_sales_cnt    NUMBER;
  lv_demand_level VARCHAR2(20);
BEGIN
  -- 1) Product lookup
  SELECT p.name
    INTO lv_product_name
    FROM ADVENTUREWORKS.PRODUCT p
   WHERE p.productid = p_product_id;

  -- 2) Sales detail count for that product
  SELECT COUNT(*)
    INTO lv_sales_cnt
    FROM ADVENTUREWORKS.SALESORDERDETAIL sod
   WHERE sod.productid = p_product_id;

  -- 3) Demand classification
  IF lv_sales_cnt = 0 THEN
    lv_demand_level := 'NO SALES';
  ELSIF lv_sales_cnt BETWEEN 1 AND 10 THEN
    lv_demand_level := 'LOW';
  ELSE
    lv_demand_level := 'HIGH';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Product ID: ' || p_product_id);
  DBMS_OUTPUT.PUT_LINE('Product Name: ' || lv_product_name);
  DBMS_OUTPUT.PUT_LINE('Sales Detail Rows: ' || lv_sales_cnt);
  DBMS_OUTPUT.PUT_LINE('Demand Level: ' || lv_demand_level);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_product_sales_snapshot;
/

question:
Build a reusable stored procedure that produces a short “salary snapshot” for a given team and year. The snapshot should show up to 15 players for that team/year with their salary, ordered from highest to lowest salary. Print a clear header, each player line, and a final total row count.

If the caller passes a NULL team or year, print a single message indicating missing input and exit without querying.

Make sure the procedure safely handles the case where there are no salaries for that team/year (print a user-friendly message). Also handle unexpected errors without letting an exception propagate to the client.

Requirements:
Procedure Name: team_salary_snapshot
Parameters:
p_team_id IN BASEBALL.SALARY.team_id%TYPE
p_year IN BASEBALL.SALARY.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Missing input: team_id and year are required.');
DBMS_OUTPUT.PUT_LINE('Salary snapshot for team ' || p_team_id || ' in ' || p_year);
DBMS_OUTPUT.PUT_LINE('player_id=' || rec.player_id || ', salary=' || rec.salary);
DBMS_OUTPUT.PUT_LINE('Rows returned: ' || lv_rows);
DBMS_OUTPUT.PUT_LINE('No salary data found for the given team/year.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No salary data found for the given team/year.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE team_salary_snapshot(
  p_team_id IN BASEBALL.SALARY.team_id%TYPE,
  p_year    IN BASEBALL.SALARY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows         PLS_INTEGER := 0;
BEGIN
  IF p_team_id IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Missing input: team_id and year are required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Salary snapshot for team ' || p_team_id || ' in ' || p_year);

  FOR rec IN (
    SELECT s.player_id,
           s.salary
      FROM BASEBALL.SALARY s
     WHERE s.team_id = p_team_id
       AND s.year = p_year
     ORDER BY s.salary DESC, s.player_id
  ) LOOP
    EXIT WHEN lv_rows >= co_report_limit;
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE('player_id=' || rec.player_id || ', salary=' || rec.salary);
  END LOOP;

  IF lv_rows = 0 THEN
    RAISE NO_DATA_FOUND;
