CREATE OR REPLACE PROCEDURE report_org_top_patient_costs(
  p_organization_id IN  synthea.encounters.organization%TYPE,
  p_start_ts        IN  synthea.encounters.start_timestamp%TYPE,
  p_end_ts          IN  synthea.encounters.stop_timestamp%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_patients IS
    WITH patient_costs AS (
      SELECT e.patient AS patient_id,
             COUNT(*) AS encounter_cnt,
             SUM(e.total_claim_cost) AS total_claim_cost
        FROM synthea.encounters e
       WHERE e.organization = p_organization_id
         AND e.start_timestamp >= p_start_ts
         AND e.stop_timestamp  <= p_end_ts
       GROUP BY e.patient
    ), ranked AS (
      SELECT pc.patient_id,
             pc.encounter_cnt,
             pc.total_claim_cost,
             ROW_NUMBER() OVER (ORDER BY pc.total_claim_cost DESC NULLS LAST, pc.encounter_cnt DESC, pc.patient_id) AS rn
        FROM patient_costs pc
    )
    SELECT r.patient_id,
           (p.first || ' ' || p.last) AS patient_name,
           r.encounter_cnt,
           r.total_claim_cost
      FROM ranked r
      INNER JOIN synthea.patients p
        ON p.id = r.patient_id
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn;

  lv_avg_claim NUMBER;
BEGIN
  IF p_organization_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Organization id is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top patients by total claim cost (limited to ' || co_report_limit || ' rows).');

  FOR r IN c_patients LOOP
    IF r.encounter_cnt = 0 THEN
      DBMS_OUTPUT.PUT_LINE('Warning: Patient=' || r.patient_id || ' average cannot be computed because encounter count is 0.');
    ELSIF r.total_claim_cost IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Warning: Patient=' || r.patient_id || ' has encounters but total claim cost is NULL.');
    ELSE
      lv_avg_claim := ROUND(r.total_claim_cost / r.encounter_cnt, 2);
      DBMS_OUTPUT.PUT_LINE(
        'Patient=' || r.patient_id ||
        ', Name=' || r.patient_name ||
        ', Encounters=' || r.encounter_cnt ||
        ', TotalClaim=' || TO_CHAR(r.total_claim_cost, 'FM9999999990D00') ||
        ', AvgClaim=' || TO_CHAR(lv_avg_claim, 'FM9999999990D00')
      );
    END IF;
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_org_top_patient_costs;
/

question:
Your analytics team needs a quick PL/SQL reporting script to review a World Bank indicator across countries.

Build an anonymous PL/SQL block that:
Accepts three inputs (as variables inside the block): a country region, an indicator code, and a year (as a string).
Validates that all inputs are provided.
Iterates through matching indicator rows for countries in that region and year, converting the indicator VALUE to a number where possible.
Prints up to 15 countries with their value, plus a final summary line showing how many rows were printed, how many were skipped due to non-numeric values, and the average numeric value.
Handles "no matching data" cleanly and includes robust exception handling.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Inputs -> Region=' || lv_region || ', Indicator=' || lv_indicator_code || ', Year=' || lv_year);
DBMS_OUTPUT.PUT_LINE('Input validation failed: region, indicator code, and year are all required.');
DBMS_OUTPUT.PUT_LINE('Country=' || rec.short_name || ' (' || rec.country_code || '), Value=' || rec.value);
DBMS_OUTPUT.PUT_LINE('Report summary -> printed=' || lv_printed_cnt || ', skipped_non_numeric=' || lv_skipped_non_numeric_cnt || ', avg_numeric_value=' || CASE WHEN lv_numeric_cnt > 0 THEN TO_CHAR(lv_sum_numeric / lv_numeric_cnt) ELSE 'N/A' END);
DBMS_OUTPUT.PUT_LINE('No matching data found for the given filters.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No matching data found for the given filters.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  -- Inputs (adjust values here to run different scenarios)
  lv_region         WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE := 'South Asia';
  lv_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE := 'SP.POP.TOTL';
  lv_year           WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE := '2019';

  -- Working variables
  lv_printed_cnt             PLS_INTEGER := 0;
  lv_skipped_non_numeric_cnt PLS_INTEGER := 0;
  lv_numeric_cnt             PLS_INTEGER := 0;
  lv_sum_numeric             NUMBER := 0;
  lv_any_row_found           PLS_INTEGER := 0;

  lv_value_num NUMBER;

  CURSOR cur_indicator_rows(
    p_region         WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE,
    p_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE,
    p_year           WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE
  ) IS
    SELECT cs.country_code,
           cs.short_name,
           id.value
      FROM WORLD_BANK_WDI.COUNTRY_SUMMARY cs
      INNER JOIN WORLD_BANK_WDI.INDICATORS_DATA id
        ON id.country_code = cs.country_code
     WHERE cs.region = p_region
       AND id.indicator_code = p_indicator_code
       AND id.year = p_year
     ORDER BY cs.short_name;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Inputs -> Region=' || lv_region || ', Indicator=' || lv_indicator_code || ', Year=' || lv_year);

  -- Input validation
  IF lv_region IS NULL OR lv_indicator_code IS NULL OR lv_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: region, indicator code, and year are all required.');
    RETURN;
  END IF;

  FOR rec IN cur_indicator_rows(lv_region, lv_indicator_code, lv_year) LOOP
    lv_any_row_found := 1;

    EXIT WHEN lv_printed_cnt >= co_report_limit;

    -- Convert VARCHAR2 value to NUMBER when possible; treat non-numeric as "skipped"
    BEGIN
      lv_value_num := TO_NUMBER(rec.value);
      lv_numeric_cnt := lv_numeric_cnt + 1;
      lv_sum_numeric := lv_sum_numeric + lv_value_num;

      DBMS_OUTPUT.PUT_LINE('Country=' || rec.short_name || ' (' || rec.country_code || '), Value=' || rec.value);
      lv_printed_cnt := lv_printed_cnt + 1;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        lv_skipped_non_numeric_cnt := lv_skipped_non_numeric_cnt + 1;
    END;
  END LOOP;

  IF lv_any_row_found = 0 THEN
    -- Standardize on NO_DATA_FOUND for "no matching data" scenario
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Report summary -> printed=' || lv_printed_cnt ||
    ', skipped_non_numeric=' || lv_skipped_non_numeric_cnt ||
    ', avg_numeric_value=' ||
    CASE
      WHEN lv_numeric_cnt > 0 THEN TO_CHAR(lv_sum_numeric / lv_numeric_cnt)
      ELSE 'N/A'
    END
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching data found for the given filters.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

