question:
Create a small operations report for the sales team: given an invoice id, print the customer name and invoice total, then list up to 15 track lines on that invoice (track name, quantity, unit price, and extended line amount). As you print each line, also categorize it as 'HIGH VALUE' when the extended amount is >= 2, otherwise 'STANDARD'. If the invoice has no lines, print a clear message and stop.

Make sure the script is safe: handle missing invoice ids, data issues, and any other unexpected errors without raising exceptions to the caller.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output:
DBMS_OUTPUT.PUT_LINE('Invoice not found.');
DBMS_OUTPUT.PUT_LINE('Multiple invoices returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
DBMS_OUTPUT.PUT_LINE('Invoice: ' || lv_invoice_id || ' | Customer: ' || lv_customer_name || ' | Total: ' || TO_CHAR(lv_total, 'FM9999990D00'));
DBMS_OUTPUT.PUT_LINE('No invoice lines found.');
DBMS_OUTPUT.PUT_LINE('Track: ' || rec.track_name || ' | Qty: ' || rec.quantity || ' | Unit: ' || TO_CHAR(rec.unit_price, 'FM9999990D00') || ' | Ext: ' || TO_CHAR(rec.ext_amount, 'FM9999990D00') || ' | Category: ' || lv_category);
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'Invoice not found.'.
WHEN TOO_MANY_ROWS THEN: 'Multiple invoices returned.'.
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_invoice_id     MUSIC.INVOICE.invoiceid%TYPE := 1;
  lv_customer_name  VARCHAR2(200);
  lv_total          MUSIC.INVOICE.total%TYPE;
  lv_line_count     PLS_INTEGER := 0;
  lv_category       VARCHAR2(20);
BEGIN
  -- Header: invoice + customer
  SELECT i.invoiceid,
         (c.firstname || ' ' || c.lastname) AS customer_name,
         i.total
    INTO lv_invoice_id,
         lv_customer_name,
         lv_total
    FROM MUSIC.INVOICE i
    INNER JOIN MUSIC.CUSTOMER c
      ON c.customerid = i.customerid
   WHERE i.invoiceid = lv_invoice_id;

  DBMS_OUTPUT.PUT_LINE(
    'Invoice: ' || lv_invoice_id ||
    ' | Customer: ' || lv_customer_name ||
    ' | Total: ' || TO_CHAR(lv_total, 'FM9999990D00')
  );

  -- Detail lines (implicit cursor FOR loop)
  FOR rec IN (
    SELECT t.name AS track_name,
           il.quantity,
           il.unitprice AS unit_price,
           (il.quantity * il.unitprice) AS ext_amount
      FROM MUSIC.INVOICELINE il
      INNER JOIN MUSIC.TRACK t
        ON t.trackid = il.trackid
     WHERE il.invoiceid = lv_invoice_id
     ORDER BY t.name
  ) LOOP
    lv_line_count := lv_line_count + 1;

    IF rec.ext_amount >= 2 THEN
      lv_category := 'HIGH VALUE';
    ELSE
      lv_category := 'STANDARD';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Track: ' || rec.track_name ||
      ' | Qty: ' || rec.quantity ||
      ' | Unit: ' || TO_CHAR(rec.unit_price, 'FM9999990D00') ||
      ' | Ext: ' || TO_CHAR(rec.ext_amount, 'FM9999990D00') ||
      ' | Category: ' || lv_category
    );

    EXIT WHEN lv_line_count >= co_report_limit;
  END LOOP;

  IF lv_line_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No invoice lines found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Invoice not found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple invoices returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

