CREATE OR REPLACE PROCEDURE report_runner_performance(
  p_pizza_name IN MODERN_DATA.PIZZA_NAMES.pizza_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_pizza_id    MODERN_DATA.PIZZA_NAMES.pizza_id%TYPE;
  lv_perf_label  VARCHAR2(10);
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_pizza_name IS NULL OR TRIM(p_pizza_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Pizza name is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Runner performance for pizza: ' || p_pizza_name);

  -- Resolve the pizza_id. This also validates that the name is unambiguous.
  SELECT pn.pizza_id
    INTO lv_pizza_id
    FROM MODERN_DATA.PIZZA_NAMES pn
   WHERE pn.pizza_name = p_pizza_name;

  -- Ranked report: delivered orders only (cancellation is NULL), aggregated per runner.
  FOR rec IN (
    WITH runner_stats AS (
      SELECT ro.runner_id AS runner_id,
             COUNT(*) AS delivered_orders,
             AVG(ro.duration) AS avg_duration_min
        FROM MODERN_DATA.PIZZA_CLEAN_CUSTOMER_ORDERS co
        INNER JOIN MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS ro
          ON ro.order_id = co.order_id
       WHERE co.pizza_id = lv_pizza_id
         AND ro.cancellation IS NULL
       GROUP BY ro.runner_id
    ),
    ranked AS (
      SELECT rs.runner_id,
             rs.delivered_orders,
             rs.avg_duration_min,
             ROW_NUMBER() OVER (
               ORDER BY rs.delivered_orders DESC, rs.avg_duration_min ASC, rs.runner_id ASC
             ) AS rn
        FROM runner_stats rs
    )
    SELECT r.runner_id,
           r.delivered_orders,
           r.avg_duration_min
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    IF rec.avg_duration_min < 20 THEN
      lv_perf_label := 'FAST';
    ELSIF rec.avg_duration_min <= 30 THEN
      lv_perf_label := 'MEDIUM';
    ELSE
      lv_perf_label := 'SLOW';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Runner ' || rec.runner_id ||
      ' | Delivered Orders=' || rec.delivered_orders ||
      ' | Avg Duration(min)=' || TO_CHAR(ROUND(rec.avg_duration_min, 1)) ||
      ' | Performance=' || lv_perf_label
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    -- Empty result set (no delivered orders) for a valid pizza name.
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No delivered orders found for pizza: ' || p_pizza_name);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple pizzas matched the name: ' || p_pizza_name);
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_runner_performance;
/

DECLARE
  -- Inputs (edit these values when running the block)
  p_year      BLS.CPI_U.year%TYPE      := '2020';
  p_item_like BLS.CPI_U.item_name%TYPE := '%Food%';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
  lv_value_num    NUMBER;
  lv_class        VARCHAR2(10);
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI-U sanity report for year=' || p_year || ', item like=' || p_item_like);

  -- Basic input validation
  IF p_year IS NULL OR LENGTH(TRIM(p_year)) <> 4 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
    RETURN;
  END IF;

  FOR rec IN (
    SELECT c.area_name,
           c.item_name,
           c.period,
           c.value
      FROM BLS.CPI_U c
     WHERE c.year = p_year
       AND c.item_name LIKE p_item_like
       AND ROWNUM <= co_report_limit
     ORDER BY c.area_name, c.item_name, c.period
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    -- VALUE is stored as VARCHAR2; attempt numeric conversion for classification
    lv_value_num := TO_NUMBER(rec.value);

    IF lv_value_num < 50 THEN
      lv_class := 'LOW';
    ELSIF lv_value_num <= 200 THEN
      lv_class := 'NORMAL';
    ELSE
      lv_class := 'HIGH';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'AREA=' || rec.area_name || ' | ITEM=' || rec.item_name || ' | PERIOD=' || rec.period ||
      ' | VALUE=' || rec.value || ' | CLASS=' || lv_class
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
