question:
Create a small demographic reporting script for analysts. The script should accept a country name and a year, validate the inputs, then pull the midyear population for that country/year and print it. If the population is above a threshold, print an additional note. Also print a short fertility summary (total fertility rate) for the same country/year when available. Make sure all errors are handled gracefully (including missing data).

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Population report for ' || lv_country_name || ' (' || lv_year || ')');
DBMS_OUTPUT.PUT_LINE('Midyear population: ' || lv_mypop);
DBMS_OUTPUT.PUT_LINE('Note: population exceeds ' || lv_threshold);
DBMS_OUTPUT.PUT_LINE('Total fertility rate: ' || lv_tfr);
DBMS_OUTPUT.PUT_LINE('Total fertility rate: not available for ' || lv_country_name || ' (' || lv_year || ')');
DBMS_OUTPUT.PUT_LINE('Input validation failed: country name is required.');
DBMS_OUTPUT.PUT_LINE('Input validation failed: year must be 4 digits (e.g., 2010).');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit any supporting lookups for deterministic output

  lv_country_name CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.country_name%TYPE := 'India';
  lv_year         CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE := '2010';

  lv_mypop        CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.midyear_population%TYPE;
  lv_tfr          CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;

  lv_threshold    NUMBER := 100000000; -- 100M
BEGIN
  -- Basic input validation
  IF lv_country_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country name is required.');
    RETURN;
  ELSIF lv_year IS NULL OR LENGTH(lv_year) <> 4 OR NOT REGEXP_LIKE(lv_year, '^[0-9]{4}$') THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year must be 4 digits (e.g., 2010).');
    RETURN;
  END IF;

  -- Population: expect a single row for country/year
  SELECT m.midyear_population
    INTO lv_mypop
    FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION m
   WHERE m.country_name = lv_country_name
     AND m.year = lv_year
     AND ROWNUM <= co_report_limit;

  DBMS_OUTPUT.PUT_LINE('Population report for ' || lv_country_name || ' (' || lv_year || ')');
  DBMS_OUTPUT.PUT_LINE('Midyear population: ' || lv_mypop);

  IF TO_NUMBER(lv_mypop) > lv_threshold THEN
    DBMS_OUTPUT.PUT_LINE('Note: population exceeds ' || lv_threshold);
  END IF;

  -- Fertility: optional; handle missing data locally so the population report still prints
  BEGIN
    SELECT f.total_fertility_rate
      INTO lv_tfr
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
     WHERE f.country_name = lv_country_name
       AND f.year = lv_year
       AND ROWNUM <= co_report_limit;

    DBMS_OUTPUT.PUT_LINE('Total fertility rate: ' || lv_tfr);
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('Total fertility rate: not available for ' || lv_country_name || ' (' || lv_year || ')');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

