DECLARE
  -- Inputs (simulate bind variables for training/demo)
  lv_state        CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE := 'CA';
  lv_min_episodes NUMBER := 100;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Default handling for missing/blank input
  IF lv_state IS NULL OR TRIM(lv_state) IS NULL THEN
    lv_state := 'CA';
  END IF;

  IF lv_min_episodes IS NULL OR lv_min_episodes < 0 THEN
    lv_min_episodes := 0;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Report parameters -> state=' || lv_state || ', min_episodes=' || lv_min_episodes);

  -- Report: only rows with numeric TOTAL_EPISODES_NON_LUPA
  FOR rec IN (
    SELECT hha.provider_id,
           hha.agency_name,
           hha.city,
           TO_NUMBER(hha.total_episodes_non_lupa) AS episodes
      FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
     WHERE hha.state = lv_state
       AND REGEXP_LIKE(hha.total_episodes_non_lupa, '^\s*\d+\s*$')
       AND TO_NUMBER(hha.total_episodes_non_lupa) >= lv_min_episodes
     ORDER BY TO_NUMBER(hha.total_episodes_non_lupa) DESC, hha.provider_id
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Provider=' || rec.provider_id ||
      ' | Agency=' || rec.agency_name ||
      ' | City=' || rec.city ||
      ' | Episodes=' || rec.episodes
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  -- If no rows matched, raise NO_DATA_FOUND to use the standard handler
  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

