question:
Your Medicare analytics team needs a reusable routine to produce a quick “market scan” of hospice providers for a given state and (optionally) a city. The scan should show up to 15 providers, ranked by the highest total Medicare payment amount, and for each provider include: provider id, name, city, hospice beneficiaries, total Medicare payment amount, and payment-per-beneficiary. 

Because the source columns are stored as strings, the routine must safely convert numeric fields and skip rows with non-numeric amounts while still reporting how many rows were skipped. It must also support a minimum-beneficiaries threshold and handle empty/NULL inputs gracefully.

Implement this as a package with a single procedure that uses an explicit cursor to iterate through the ranked results and prints them in DBMS_OUTPUT, including a final summary line with how many rows were printed and how many were skipped.

Requirements:
Procedure Name: pkg_hospice_scan.run_scan
Parameters:
p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
p_city IN CMS_MEDICARE.HOSPICE_PROVIDERS.city%TYPE
p_min_beneficiaries IN NUMBER
Output:
DBMS_OUTPUT.PUT_LINE('Hospice scan for STATE=' || NVL(p_state, 'NULL') || ', CITY=' || NVL(p_city, 'NULL') || ', MIN_BENEF=' || TO_CHAR(NVL(p_min_beneficiaries, 0)));
DBMS_OUTPUT.PUT_LINE('PROVIDER_ID=' || r.provider_id || ', NAME=' || r.name || ', CITY=' || r.city || ', BENE=' || TO_CHAR(r.bene_num) || ', PAY=' || TO_CHAR(r.pay_num, 'FM999G999G999G990D00') || ', PAY_PER_BENE=' || TO_CHAR(lv_pay_per_bene, 'FM999G999G999G990D00'));
DBMS_OUTPUT.PUT_LINE('Printed rows=' || TO_CHAR(lv_printed) || '; Skipped (bad numeric)=' || TO_CHAR(lv_skipped) || '.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE pkg_hospice_scan IS
  PROCEDURE run_scan(
    p_state             IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE,
    p_city              IN CMS_MEDICARE.HOSPICE_PROVIDERS.city%TYPE,
    p_min_beneficiaries IN NUMBER
  );
END pkg_hospice_scan;
/

CREATE OR REPLACE PACKAGE BODY pkg_hospice_scan IS
  PROCEDURE run_scan(
    p_state             IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE,
    p_city              IN CMS_MEDICARE.HOSPICE_PROVIDERS.city%TYPE,
    p_min_beneficiaries IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_ranked(
      cp_state   CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE,
      cp_city    CMS_MEDICARE.HOSPICE_PROVIDERS.city%TYPE,
      cp_min_ben NUMBER
    ) IS
      WITH ranked AS (
        SELECT
          hp.provider_id,
          hp.name,
          hp.city,
          hp.state,
          hp.hospice_beneficiaries,
          hp.total_medicare_payment_amount,
          ROW_NUMBER() OVER (
            ORDER BY TO_NUMBER(REPLACE(hp.total_medicare_payment_amount, ',', '')) DESC
          ) AS rn
        FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
        WHERE hp.state = cp_state
          AND (cp_city IS NULL OR hp.city = cp_city)
          AND TO_NUMBER(REPLACE(hp.hospice_beneficiaries, ',', '')) >= NVL(cp_min_ben, 0)
          AND REGEXP_LIKE(hp.total_medicare_payment_amount, '^[0-9]+(\.[0-9]+)?$')
          AND REGEXP_LIKE(hp.hospice_beneficiaries, '^[0-9]+$')
      )
      SELECT
        r.provider_id,
        r.name,
        r.city,
        TO_NUMBER(REPLACE(r.hospice_beneficiaries, ',', '')) AS bene_num,
        TO_NUMBER(REPLACE(r.total_medicare_payment_amount, ',', '')) AS pay_num
      FROM ranked r
      WHERE r.rn <= co_report_limit
      ORDER BY r.rn;

    lr_row c_ranked%ROWTYPE;

    lv_printed PLS_INTEGER := 0;
    lv_skipped PLS_INTEGER := 0;

    lv_pay_per_bene NUMBER;

    lv_total_in_scope PLS_INTEGER;
    lv_total_valid    PLS_INTEGER;
  BEGIN
    DBMS_OUTPUT.PUT_LINE(
      'Hospice scan for STATE=' || NVL(p_state, 'NULL') ||
      ', CITY=' || NVL(p_city, 'NULL') ||
      ', MIN_BENEF=' || TO_CHAR(NVL(p_min_beneficiaries, 0))
    );

    -- Basic input guard; still deterministic and exception-safe
    IF p_state IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    -- Count totals to report skipped rows due to bad numeric formats
    SELECT COUNT(*)
      INTO lv_total_in_scope
      FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
     WHERE hp.state = p_state
       AND (p_city IS NULL OR hp.city = p_city);

    SELECT COUNT(*)
      INTO lv_total_valid
      FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
     WHERE hp.state = p_state
       AND (p_city IS NULL OR hp.city = p_city)
       AND REGEXP_LIKE(hp.total_medicare_payment_amount, '^[0-9]+(\.[0-9]+)?$')
       AND REGEXP_LIKE(hp.hospice_beneficiaries, '^[0-9]+$')
       AND TO_NUMBER(REPLACE(hp.hospice_beneficiaries, ',', '')) >= NVL(p_min_beneficiaries, 0);

    lv_skipped := GREATEST(lv_total_in_scope - lv_total_valid, 0);

    OPEN c_ranked(p_state, p_city, p_min_beneficiaries);
    LOOP
      FETCH c_ranked INTO lr_row;
      EXIT WHEN c_ranked%NOTFOUND;

      -- Control flow for edge cases
      IF lr_row.bene_num = 0 THEN
        lv_pay_per_bene := NULL;
      ELSE
        lv_pay_per_bene := lr_row.pay_num / lr_row.bene_num;
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        'PROVIDER_ID=' || lr_row.provider_id ||
        ', NAME=' || lr_row.name ||
        ', CITY=' || lr_row.city ||
        ', BENE=' || TO_CHAR(lr_row.bene_num) ||
        ', PAY=' || TO_CHAR(lr_row.pay_num, 'FM999G999G999G990D00') ||
        ', PAY_PER_BENE=' || TO_CHAR(lv_pay_per_bene, 'FM999G999G999G990D00')
      );

      lv_printed := lv_printed + 1;
    END LOOP;
    CLOSE c_ranked;

    IF lv_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Printed rows=' || TO_CHAR(lv_printed) ||
      '; Skipped (bad numeric)=' || TO_CHAR(lv_skipped) ||
      '.'
    );

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      -- Covers unexpected empty single-row fetches (e.g., count queries if table is inaccessible)
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      -- Ensure cursor is closed if an error occurs mid-stream
      IF c_ranked%ISOPEN THEN
        CLOSE c_ranked;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END run_scan;
END pkg_hospice_scan;
/

