question:
As part of an internal data quality and reporting tool for the World Bank international debt dataset, build a reusable routine that prints a small "debt profile" report for a given income group and year.

The report should:
Validate the inputs (income group and year) and print a clear message if they are missing.
Look up how many countries exist in that income group.
For the specified year, compute the TOP 5 debt indicators (by total numeric value summed across all countries in the income group), and print them in descending order.
Also print the TOP 5 countries (by total numeric value summed across all indicators for that year) in descending order.

Important constraints:
The data in INTERNATIONAL_DEBT.VALUE is stored as text; convert it to a number safely for aggregation.
Keep output readable and deterministic; limit lists to a maximum of 5 rows each.
Use exception handling so the routine never crashes.

Requirements:
Procedure Name: rpt_income_group_debt_profile
Parameters:
p_income_group IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE
p_year IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Debt Profile | Income Group: ' || p_income_group || ' | Year: ' || p_year);
DBMS_OUTPUT.PUT_LINE('Countries in group: ' || lv_country_cnt);
DBMS_OUTPUT.PUT_LINE('Top indicators by total debt value:');
DBMS_OUTPUT.PUT_LINE('  ' || LPAD(lv_seq, 2, ' ') || '. ' || rec_ind.indicator_code || ' | ' || rec_ind.indicator_name || ' | total=' || TO_CHAR(rec_ind.total_value));
DBMS_OUTPUT.PUT_LINE('Top countries by total debt value:');
DBMS_OUTPUT.PUT_LINE('  ' || LPAD(lv_seq, 2, ' ') || '. ' || rec_cty.country_code || ' | ' || rec_cty.country_name || ' | total=' || TO_CHAR(rec_cty.total_value));
DBMS_OUTPUT.PUT_LINE('Income group is required.');
DBMS_OUTPUT.PUT_LINE('Year is required.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE rpt_income_group_debt_profile(
  p_income_group IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE,
  p_year         IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_top_limit CONSTANT PLS_INTEGER := 5; -- Keep report short and readable

  lv_country_cnt PLS_INTEGER;
  lv_seq         PLS_INTEGER;
BEGIN
  -- Basic input validation (reporting routine should not crash)
  IF p_income_group IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Income group is required.');
    RETURN;
  END IF;

  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Year is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Debt Profile | Income Group: ' || p_income_group || ' | Year: ' || p_year);

  -- Count countries in the group (data quality context)
  SELECT COUNT(*)
    INTO lv_country_cnt
    FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
   WHERE cs.income_group = p_income_group;

  DBMS_OUTPUT.PUT_LINE('Countries in group: ' || lv_country_cnt);

  -- Top indicators by summed numeric debt value for the income group and year
  DBMS_OUTPUT.PUT_LINE('Top indicators by total debt value:');
  lv_seq := 0;
  FOR rec_ind IN (
    WITH ind_totals AS (
      SELECT d.indicator_code,
             d.indicator_name,
             SUM(TO_NUMBER(d.value)) AS total_value
        FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
        JOIN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
          ON cs.country_code = d.country_code
       WHERE cs.income_group = p_income_group
         AND d.year = p_year
         AND REGEXP_LIKE(d.value, '^[-+]?(\\d+)(\\.\\d+)?$')
       GROUP BY d.indicator_code, d.indicator_name
    )
    SELECT indicator_code,
           indicator_name,
           total_value
      FROM ind_totals
     ORDER BY total_value DESC, indicator_code ASC
     FETCH FIRST co_top_limit ROWS ONLY
  ) LOOP
    lv_seq := lv_seq + 1;
    DBMS_OUTPUT.PUT_LINE('  ' || LPAD(lv_seq, 2, ' ') || '. ' || rec_ind.indicator_code || ' | ' || rec_ind.indicator_name || ' | total=' || TO_CHAR(rec_ind.total_value));
  END LOOP;

  -- Top countries by summed numeric debt value for the income group and year
  DBMS_OUTPUT.PUT_LINE('Top countries by total debt value:');
  lv_seq := 0;
  FOR rec_cty IN (
    WITH cty_totals AS (
      SELECT d.country_code,
             d.country_name,
             SUM(TO_NUMBER(d.value)) AS total_value
        FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
        JOIN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
          ON cs.country_code = d.country_code
       WHERE cs.income_group = p_income_group
         AND d.year = p_year
         AND REGEXP_LIKE(d.value, '^[-+]?(\\d+)(\\.\\d+)?$')
       GROUP BY d.country_code, d.country_name
    )
    SELECT country_code,
           country_name,
           total_value
      FROM cty_totals
     ORDER BY total_value DESC, country_code ASC
     FETCH FIRST co_top_limit ROWS ONLY
  ) LOOP
    lv_seq := lv_seq + 1;
    DBMS_OUTPUT.PUT_LINE('  ' || LPAD(lv_seq, 2, ' ') || '. ' || rec_cty.country_code || ' | ' || rec_cty.country_name || ' | total=' || TO_CHAR(rec_cty.total_value));
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_income_group_debt_profile;
/

