  PROCEDURE print_top_counties(
    p_start_year     IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_end_year       IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_abnormal_desc  IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_ABNORMAL_CONDITIONS.abnormal_conditions_checked_desc%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_note        VARCHAR2(200);
    lv_row_count   PLS_INTEGER := 0;

    CURSOR c_top IS
      WITH county_totals AS (
        SELECT
          cn.county_of_residence,
          cn.county_of_residence_fips,
          SUM(
            CASE
              WHEN REGEXP_LIKE(TRIM(cn.births), '^\d+(\.\d+)?$') THEN TO_NUMBER(TRIM(cn.births))
              ELSE 0
            END
          ) AS total_births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
        WHERE cn.year BETWEEN p_start_year AND p_end_year
        GROUP BY cn.county_of_residence, cn.county_of_residence_fips
      ),
      abnormal_totals AS (
        SELECT
          ac.county_of_residence_fips,
          SUM(
            CASE
              WHEN ac.abnormal_conditions_checked_yn = 'Yes'
                   AND REGEXP_LIKE(TRIM(ac.births), '^\d+(\.\d+)?$') THEN TO_NUMBER(TRIM(ac.births))
              ELSE 0
            END
          ) AS abnormal_births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_ABNORMAL_CONDITIONS ac
        WHERE ac.year BETWEEN p_start_year AND p_end_year
          AND ac.abnormal_conditions_checked_desc = p_abnormal_desc
        GROUP BY ac.county_of_residence_fips
      ),
      ranked AS (
        SELECT
          ct.county_of_residence,
          ct.county_of_residence_fips,
          ct.total_births,
          COALESCE(at.abnormal_births, 0) AS abnormal_births,
          ROW_NUMBER() OVER (ORDER BY ct.total_births DESC, ct.county_of_residence_fips) AS rnk
        FROM county_totals ct
        LEFT OUTER JOIN abnormal_totals at
          ON at.county_of_residence_fips = ct.county_of_residence_fips
      )
      SELECT
        r.county_of_residence,
        r.county_of_residence_fips,
        r.total_births,
        r.abnormal_births,
        r.rnk
      FROM ranked r
      WHERE r.rnk <= co_report_limit
      ORDER BY r.rnk;

  BEGIN
    -- Basic input validation
    IF p_start_year IS NULL OR p_end_year IS NULL OR p_abnormal_desc IS NULL THEN
      RAISE VALUE_ERROR;
    END IF;

    IF p_start_year > p_end_year THEN
      RAISE VALUE_ERROR;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Top counties by births (' || TO_CHAR(p_start_year, 'YYYY') || '-' || TO_CHAR(p_end_year, 'YYYY') || '), Abnormal condition: ' || p_abnormal_desc);
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));

    FOR r_county IN c_top LOOP
      lv_row_count := lv_row_count + 1;

      -- Simple consistency/quality note
      IF r_county.total_births = 0 THEN
        lv_note := 'Total births is zero (or non-numeric values dominated).';
      ELSIF r_county.abnormal_births > r_county.total_births THEN
        lv_note := 'Abnormal births exceed total births (data inconsistency).';
      ELSIF r_county.abnormal_births = 0 THEN
        lv_note := 'No abnormal births flagged as Yes for this condition.';
      ELSE
        lv_note := 'OK';
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        'Rank=' || r_county.rnk ||
        ' | County=' || r_county.county_of_residence ||
        ' | FIPS=' || r_county.county_of_residence_fips ||
        ' | TotalBirths=' || r_county.total_births ||
        ' | AbnormalBirths=' || r_county.abnormal_births ||
        ' | Note=' || lv_note
      );
    END LOOP;

    IF lv_row_count = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No counties found for the given criteria.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input: start year is after end year.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_counties;

END pkg_natality_reports;
/

