CREATE OR REPLACE PROCEDURE report_county_births_rank(
  p_county_fips IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE,
  p_year_from   IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_year_to     IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
  lv_any_eligible_rows NUMBER(1) := 0;
BEGIN
  -- Basic input validation (control flow)
  IF p_county_fips IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: county FIPS is required.');
    RETURN;
  END IF;

  IF p_year_from IS NULL OR p_year_to IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year_from and year_to are required.');
    RETURN;
  END IF;

  IF p_year_from > p_year_to THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year range is reversed (year_from > year_to).');
    RETURN;
  END IF;

  -- Keep bounds explicit for deterministic training behavior
  IF p_year_from < DATE '2000-01-01' OR p_year_to > DATE '2025-12-31' THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year range is outside supported bounds (2000-2025).');
    RETURN;
  END IF;

  -- Determine whether any rows qualify after cleaning non-numeric births
  SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
    INTO lv_any_eligible_rows
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.county_of_residence_fips = p_county_fips
     AND cn.year BETWEEN p_year_from AND p_year_to
     AND REGEXP_LIKE(TRIM(cn.births), '^\d+$');

  IF lv_any_eligible_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('County FIPS: ' || p_county_fips || ' | Years: ' || TO_CHAR(p_year_from, 'YYYY') || '-' || TO_CHAR(p_year_to, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('Year', 8) || LPAD('Births', 12));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 6, '-') || RPAD('-', 8, '-') || LPAD('-', 12, '-'));

  -- Rank years by births (numeric conversion is safe due to regex filter)
  FOR rec IN (
    WITH cleaned AS (
      SELECT cn.year AS year,
             TO_NUMBER(TRIM(cn.births)) AS births_num
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.county_of_residence_fips = p_county_fips
         AND cn.year BETWEEN p_year_from AND p_year_to
         AND REGEXP_LIKE(TRIM(cn.births), '^\d+$')
    )
    SELECT c.year,
           c.births_num,
           RANK() OVER (ORDER BY c.births_num DESC, c.year DESC) AS rnk
      FROM cleaned c
     ORDER BY rnk, c.year DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(rec.rnk), 6) ||
      RPAD(TO_CHAR(rec.year, 'YYYY'), 8) ||
      LPAD(TO_CHAR(rec.births_num), 12)
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_county_births_rank;
/

DECLARE
  co_row_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE;
  lv_start_year     WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;

  CURSOR c_obs IS
    SELECT d.country_code,
           c.short_name,
           d.year,
           d.indicator_code,
           s.topic,
           d.value AS value_txt
      FROM WORLD_BANK_WDI.INDICATORS_DATA d
      INNER JOIN WORLD_BANK_WDI.COUNTRY_SUMMARY c
        ON c.country_code = d.country_code
      LEFT OUTER JOIN WORLD_BANK_WDI.SERIES_SUMMARY s
        ON s.series_code = d.indicator_code
     WHERE d.indicator_code = lv_indicator_code
       AND TO_NUMBER(d.year) >= TO_NUMBER(lv_start_year)
       AND ROWNUM <= co_row_limit
     ORDER BY d.country_code, TO_NUMBER(d.year);

  TYPE t_sum_by_country IS TABLE OF NUMBER INDEX BY VARCHAR2(10);
  TYPE t_cnt_by_country IS TABLE OF PLS_INTEGER INDEX BY VARCHAR2(10);
  TYPE t_name_by_country IS TABLE OF VARCHAR2(100) INDEX BY VARCHAR2(10);

  l_sum   t_sum_by_country;
  l_cnt   t_cnt_by_country;
  l_name  t_name_by_country;

  rec c_obs%ROWTYPE;

  lv_num NUMBER;

  lv_printed_rows       PLS_INTEGER := 0;
  lv_skipped_non_numeric PLS_INTEGER := 0;

  TYPE t_top_country IS RECORD (
    country_code VARCHAR2(10),
    country_name VARCHAR2(100),
    avg_val      NUMBER
  );

  TYPE t_top_list IS TABLE OF t_top_country INDEX BY PLS_INTEGER;
  l_top t_top_list;

  lv_i            PLS_INTEGER;
  lv_j            PLS_INTEGER;
  lv_k            PLS_INTEGER;
  lv_country_code VARCHAR2(10);
  lv_country_name VARCHAR2(100);
  lv_avg          NUMBER;

  FUNCTION is_numeric(p_txt IN VARCHAR2) RETURN BOOLEAN IS
  BEGIN
    RETURN REGEXP_LIKE(TRIM(p_txt), '^[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?$');
  END;

  PROCEDURE consider_top5(
    p_code IN VARCHAR2,
    p_name IN VARCHAR2,
    p_avg  IN NUMBER
  ) IS
    lv_pos PLS_INTEGER;
    lv_tmp t_top_country;
  BEGIN
    IF l_top.COUNT < 5 THEN
      l_top(l_top.COUNT + 1).country_code := p_code;
      l_top(l_top.COUNT).country_name := p_name;
      l_top(l_top.COUNT).avg_val := p_avg;
    ELSIF p_avg > l_top(5).avg_val THEN
      l_top(5).country_code := p_code;
      l_top(5).country_name := p_name;
      l_top(5).avg_val := p_avg;
    ELSE
      RETURN;
    END IF;

    -- Keep l_top sorted descending by avg_val (simple insertion sort for 5 rows)
    IF l_top.COUNT > 1 THEN
      FOR lv_pos IN REVERSE 2 .. l_top.COUNT LOOP
        IF l_top(lv_pos).avg_val > l_top(lv_pos - 1).avg_val THEN
          lv_tmp := l_top(lv_pos - 1);
          l_top(lv_pos - 1) := l_top(lv_pos);
          l_top(lv_pos) := lv_tmp;
        END IF;
      END LOOP;
    END IF;
  END;

BEGIN
  -- Pick a common indicator code for a realistic run
  SELECT sub.indicator_code
    INTO lv_indicator_code
    FROM (
          SELECT d.indicator_code
            FROM WORLD_BANK_WDI.INDICATORS_DATA d
           WHERE d.indicator_code IS NOT NULL
           GROUP BY d.indicator_code
           ORDER BY COUNT(*) DESC, d.indicator_code
         ) sub
   WHERE ROWNUM = 1;

  -- Starting year based on available data for the chosen indicator
  SELECT MIN(d.year)
    INTO lv_start_year
    FROM WORLD_BANK_WDI.INDICATORS_DATA d
   WHERE d.indicator_code = lv_indicator_code;

  DBMS_OUTPUT.PUT_LINE('Input indicator_code=' || lv_indicator_code || ', start_year=' || lv_start_year);

  OPEN c_obs;
  LOOP
    FETCH c_obs INTO rec;
    EXIT WHEN c_obs%NOTFOUND;

    IF is_numeric(rec.value_txt) THEN
      lv_num := TO_NUMBER(TRIM(rec.value_txt));
      lv_printed_rows := lv_printed_rows + 1;

      IF l_sum.EXISTS(rec.country_code) THEN
        l_sum(rec.country_code) := l_sum(rec.country_code) + lv_num;
        l_cnt(rec.country_code) := l_cnt(rec.country_code) + 1;
      ELSE
        l_sum(rec.country_code) := lv_num;
        l_cnt(rec.country_code) := 1;
        l_name(rec.country_code) := rec.short_name;
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        'ROW: ' || rec.country_code || ' | ' || rec.short_name || ' | ' || rec.year ||
        ' | ' || rec.indicator_code || ' | ' || rec.topic || ' | value=' || rec.value_txt ||
        ' | num=' || TO_CHAR(lv_num)
      );
    ELSE
      lv_skipped_non_numeric := lv_skipped_non_numeric + 1;
    END IF;
  END LOOP;
  CLOSE c_obs;

  IF lv_printed_rows = 0 THEN
    -- Treat "no printable numeric data" as NO_DATA_FOUND for this report
    RAISE NO_DATA_FOUND;
  END IF;

  -- Compute top-5 averages from the in-memory aggregates
  lv_country_code := l_sum.FIRST;
  WHILE lv_country_code IS NOT NULL LOOP
    IF l_cnt(lv_country_code) > 0 THEN
      lv_avg := l_sum(lv_country_code) / l_cnt(lv_country_code);
      consider_top5(lv_country_code, l_name(lv_country_code), lv_avg);
    END IF;
    lv_country_code := l_sum.NEXT(lv_country_code);
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('SUMMARY: printed_rows=' || lv_printed_rows || ', skipped_non_numeric=' || lv_skipped_non_numeric);

  IF l_top.COUNT > 0 THEN
    FOR lv_k IN 1 .. l_top.COUNT LOOP
      lv_country_code := l_top(lv_k).country_code;
      lv_country_name := l_top(lv_k).country_name;
      lv_avg := l_top(lv_k).avg_val;
      DBMS_OUTPUT.PUT_LINE('TOP5: ' || lv_country_code || ' | ' || lv_country_name || ' | avg=' || TO_CHAR(lv_avg));
    END LOOP;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Value error.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

