    IF l_top.COUNT > 1 THEN
      FOR lv_pos IN REVERSE 2 .. l_top.COUNT LOOP
        IF l_top(lv_pos).avg_val > l_top(lv_pos-1).avg_val THEN lv_tmp := l_top(lv_pos-1); l_top(lv_pos-1) := l_top(lv_pos); l_top(lv_pos) := lv_tmp; END IF;
      END LOOP;
    END IF;
  END;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Input indicator_code=' || lv_indicator_code || ', start_year=' || lv_start_year);
  OPEN c_obs;
  LOOP FETCH c_obs INTO rec; EXIT WHEN c_obs%NOTFOUND;
    IF is_numeric(rec.value_txt) THEN
      lv_num := TO_NUMBER(TRIM(rec.value_txt)); lv_printed_rows := lv_printed_rows + 1;
      IF l_sum.EXISTS(rec.country_code) THEN l_sum(rec.country_code) := l_sum(rec.country_code) + lv_num; l_cnt(rec.country_code) := l_cnt(rec.country_code) + 1;
      ELSE l_sum(rec.country_code) := lv_num; l_cnt(rec.country_code) := 1; l_name(rec.country_code) := rec.short_name; END IF;
      DBMS_OUTPUT.PUT_LINE('ROW: ' || rec.country_code || ' | ' || rec.short_name || ' | ' || rec.year || ' | ' || rec.indicator_code || ' | ' || rec.topic || ' | value=' || rec.value_txt || ' | num=' || TO_CHAR(lv_num));
    ELSE lv_skipped_non_numeric := lv_skipped_non_numeric + 1; END IF;
  END LOOP; CLOSE c_obs;
  IF lv_printed_rows = 0 THEN RAISE NO_DATA_FOUND; END IF;
  lv_country_code := l_sum.FIRST; WHILE lv_country_code IS NOT NULL LOOP
    IF l_cnt(lv_country_code) > 0 THEN lv_avg := l_sum(lv_country_code) / l_cnt(lv_country_code); consider_top5(lv_country_code, l_name(lv_country_code), lv_avg); END IF;
    lv_country_code := l_sum.NEXT(lv_country_code);
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('SUMMARY: printed_rows=' || lv_printed_rows || ', skipped_non_numeric=' || lv_skipped_non_numeric);
  IF l_top.COUNT > 0 THEN FOR lv_k IN 1 .. l_top.COUNT LOOP
    DBMS_OUTPUT.PUT_LINE('TOP5: ' || l_top(lv_k).country_code || ' | ' || l_top(lv_k).country_name || ' | avg=' || TO_CHAR(l_top(lv_k).avg_val));
  END LOOP; END IF;
EXCEPTION WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('No data found.'); WHEN TOO_MANY_ROWS THEN DBMS_OUTPUT.PUT_LINE('Multiple rows returned.'); WHEN VALUE_ERROR THEN DBMS_OUTPUT.PUT_LINE('Value error.'); WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('Unexpected error.'); END;
/

