question:
Build a reusable PL/SQL routine for a finance analyst that produces a small “debt indicator snapshot” report for a given year. The routine must:
Validate the year input.
Pull the top countries by total debt value for that year (treat VALUE as numeric), limited to a small, readable number of rows.
For each country in the result, classify it as a "HIGH" or "LOW" total-debt country using a threshold derived from the overall average total debt across all countries for the same year.
Print a neatly formatted report and handle all expected error situations gracefully.

Requirements:
Procedure Name: debt_snapshot_report
Parameters:
  p_year IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
Output:
  DBMS_OUTPUT.PUT_LINE('Debt snapshot for year: ' || p_year);
  DBMS_OUTPUT.PUT_LINE('Overall average total debt (all countries): ' || TO_CHAR(lv_avg_total_debt, 'FM999G999G999G999G990D00'));
  DBMS_OUTPUT.PUT_LINE('Threshold multiplier: ' || TO_CHAR(co_threshold_multiplier, 'FM999G990D00'));
  DBMS_OUTPUT.PUT_LINE('Top countries (limited to ' || co_report_limit || '):');
  DBMS_OUTPUT.PUT_LINE(RPAD('Country', 32) || RPAD('Total Debt', 22) || 'Class');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 32, '-') || RPAD('-', 22, '-') || RPAD('-', 10, '-'));
  DBMS_OUTPUT.PUT_LINE(RPAD(rec.country_name, 32) || RPAD(TO_CHAR(rec.total_debt, 'FM999G999G999G999G990D00'), 22) || rec.debt_class);
  DBMS_OUTPUT.PUT_LINE('No countries matched the criteria for year: ' || p_year);
Exception Handling:
  WHEN NO_DATA_FOUND THEN: 'No data found.'
  WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
  WHEN VALUE_ERROR THEN: 'Invalid numeric conversion encountered.'
  WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE debt_snapshot_report(
  p_year IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 10; -- Limit output for report readability
  co_threshold_multiplier CONSTANT NUMBER := 1.25; -- "High" if total debt >= avg * multiplier

  lv_avg_total_debt NUMBER;
  lv_row_count      PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_year IS NULL OR LENGTH(TRIM(p_year)) = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No countries matched the criteria for year: ' || p_year);
    RETURN;
  END IF;

  -- Derive average total debt across all countries for the year
  SELECT AVG(country_total)
    INTO lv_avg_total_debt
    FROM (
      SELECT id.country_name,
             SUM(TO_NUMBER(id.value)) AS country_total
        FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
       WHERE id.year = p_year
       GROUP BY id.country_name
    );

  DBMS_OUTPUT.PUT_LINE('Debt snapshot for year: ' || p_year);
  DBMS_OUTPUT.PUT_LINE('Overall average total debt (all countries): ' || TO_CHAR(lv_avg_total_debt, 'FM999G999G999G999G990D00'));
  DBMS_OUTPUT.PUT_LINE('Threshold multiplier: ' || TO_CHAR(co_threshold_multiplier, 'FM999G990D00'));
  DBMS_OUTPUT.PUT_LINE('Top countries (limited to ' || co_report_limit || '):');
  DBMS_OUTPUT.PUT_LINE(RPAD('Country', 32) || RPAD('Total Debt', 22) || 'Class');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 32, '-') || RPAD('-', 22, '-') || RPAD('-', 10, '-'));

  -- Report: compute totals and classify relative to derived threshold
  FOR rec IN (
    WITH country_totals AS (
      SELECT id.country_name,
             SUM(TO_NUMBER(id.value)) AS total_debt
        FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
       WHERE id.year = p_year
       GROUP BY id.country_name
    ), ranked AS (
      SELECT ct.country_name,
             ct.total_debt,
             CASE
               WHEN ct.total_debt >= (lv_avg_total_debt * co_threshold_multiplier) THEN 'HIGH'
               ELSE 'LOW'
             END AS debt_class,
             ROW_NUMBER() OVER (ORDER BY ct.total_debt DESC) AS rn
        FROM country_totals ct
    )
    SELECT r.country_name,
           r.total_debt,
           r.debt_class
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.total_debt DESC
  ) LOOP
    lv_row_count := lv_row_count + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.country_name, 32) ||
      RPAD(TO_CHAR(rec.total_debt, 'FM999G999G999G999G990D00'), 22) ||
      rec.debt_class
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No countries matched the criteria for year: ' || p_year);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric conversion encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END debt_snapshot_report;
/

CREATE OR REPLACE PROCEDURE report_hha_payment_per_episode(
  p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_state IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('State is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('State: ' || p_state);

  FOR r IN (
    SELECT q.provider_id,
           q.agency_name,
           q.city,
           q.payment_per_episode
      FROM (
            SELECT hha.provider_id,
                   hha.agency_name,
                   hha.city,
                   CASE
                     WHEN TO_NUMBER(hha.total_episodes_non_lupa) = 0 THEN NULL
                     ELSE TO_NUMBER(hha.total_hha_medicare_payment_amount_non_lupa) /
                          TO_NUMBER(hha.total_episodes_non_lupa)
                   END AS payment_per_episode
              FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
             WHERE hha.state = p_state
           ) q
     ORDER BY q.payment_per_episode DESC NULLS LAST, q.provider_id
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    IF lv_rows_printed > co_report_limit THEN
      EXIT;
    END IF;

    IF r.payment_per_episode IS NULL THEN
      DBMS_OUTPUT.PUT_LINE(
        'Provider: ' || r.provider_id || ' | Agency: ' || r.agency_name || ' | City: ' || r.city ||
        ' | Payment per episode: N/A'
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'Provider: ' || r.provider_id || ' | Agency: ' || r.agency_name || ' | City: ' || r.city ||
        ' | Payment per episode: ' || TO_CHAR(r.payment_per_episode, 'FM999G999G999G990D00')
      );
    END IF;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No agencies found for state.');
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered while calculating payment per episode.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_hha_payment_per_episode;
/

DECLARE
  lv_departure_airport AIRLINES.FLIGHTS.departure_airport%TYPE := 'SVO';
  lv_max_flight_id     AIRLINES.FLIGHTS.flight_id%TYPE := 999999999;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF lv_departure_airport IS NULL OR TRIM(lv_departure_airport) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input error: departure airport code is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Upcoming flights from ' || lv_departure_airport || ' (flight_id <= ' || lv_max_flight_id || '):');

  FOR rec IN (
    SELECT f.flight_id,
           f.flight_no,
           f.status,
           f.scheduled_departure
      FROM AIRLINES.FLIGHTS f
     WHERE f.departure_airport = lv_departure_airport
       AND f.flight_id <= lv_max_flight_id
     ORDER BY f.scheduled_departure
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Flight ' || rec.flight_id || ' / ' || rec.flight_no || ' / ' || rec.status || ' / ' ||
      TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI')
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No flights found for the given criteria.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

