CREATE OR REPLACE PROCEDURE report_orders_by_date(
  p_order_date            IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE,
  p_high_value_threshold  IN ADVENTUREWORKS.SALESORDERHEADER.totaldue%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_printed_count PLS_INTEGER := 0;
  lv_label         VARCHAR2(20);
BEGIN
  IF p_order_date IS NULL OR p_high_value_threshold IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  FOR r IN (
    SELECT soh.salesorderid,
           soh.customerid,
           soh.status,
           soh.totaldue
      FROM ADVENTUREWORKS.SALESORDERHEADER soh
     WHERE soh.orderdate = p_order_date
       AND ROWNUM <= co_report_limit
     ORDER BY soh.salesorderid
  ) LOOP
    IF r.totaldue > p_high_value_threshold THEN
      lv_label := 'HIGH_VALUE';
    ELSE
      lv_label := 'NORMAL';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Order ' || r.salesorderid || ' | Customer ' || r.customerid ||
      ' | Status ' || r.status || ' | TotalDue ' || r.totaldue || ' | ' || lv_label
    );

    lv_printed_count := lv_printed_count + 1;
  END LOOP;

  IF lv_printed_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Summary: printed ' || lv_printed_count || ' orders for ' || TO_CHAR(p_order_date, 'YYYY-MM-DD')
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_orders_by_date;
/

