CREATE OR REPLACE PROCEDURE report_cpi_u_monthly(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_item_name IN BLS.CPI_U.item_name%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_area_name IS NULL OR p_item_name IS NULL OR p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: area_name, item_name, and year are required.');
    RETURN;
  END IF;

  -- Ensure year is a 4-digit numeric string
  IF NOT REGEXP_LIKE(p_year, '^\d{4}$') THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year must be a 4-digit number.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI-U Monthly Report');
  DBMS_OUTPUT.PUT_LINE('Area=' || p_area_name || ' | Item=' || p_item_name || ' | Year=' || p_year);

  -- Retrieve and print up to co_report_limit rows (most recent first)
  FOR r IN (
    SELECT c.period,
           c.c_date,
           c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND c.year = p_year
     ORDER BY c.c_date DESC, c.period DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Period=' || r.period ||
      ' | Date=' || TO_CHAR(r.c_date, 'YYYY-MM-DD') ||
      ' | Value=' || r.value
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  -- Force a NO_DATA_FOUND path for empty result sets (implicit cursor loop doesn't raise it)
  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows match the provided filters.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_cpi_u_monthly;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_solution_name    STACKING.MODEL_IMPORTANCE.name%TYPE := 'DEMO_SOLUTION';
  lv_version_text     VARCHAR2(50) := '1'; -- Set to 'ABC' to trigger VALUE_ERROR
  lv_solution_version STACKING.MODEL_IMPORTANCE.version%TYPE;

  CURSOR c_model_importance(p_name STACKING.MODEL_IMPORTANCE.name%TYPE,
                            p_version STACKING.MODEL_IMPORTANCE.version%TYPE) IS
    SELECT mi.model AS model_name,
           mi.importance AS model_importance
      FROM STACKING.MODEL_IMPORTANCE mi
     WHERE mi.name = p_name
       AND mi.version = p_version
     ORDER BY mi.importance DESC
     FETCH FIRST co_report_limit ROWS ONLY;

  lv_best_test_score   STACKING.MODEL_SCORE.test_score%TYPE;
  lv_models_processed  PLS_INTEGER := 0;
  lv_total_importance  NUMBER := 0;
  lv_scored_models     PLS_INTEGER := 0;
  lv_total_test_score  NUMBER := 0;
BEGIN
  -- Defensive conversion that can raise VALUE_ERROR
  lv_solution_version := TO_NUMBER(lv_version_text);

  DBMS_OUTPUT.PUT_LINE('Solution: ' || lv_solution_name || ', version=' || lv_solution_version);

  FOR r_mi IN c_model_importance(lv_solution_name, lv_solution_version) LOOP
    lv_models_processed := lv_models_processed + 1;
    lv_total_importance := lv_total_importance + NVL(r_mi.model_importance, 0);

    -- Find best available test score for this model (if any)
    lv_best_test_score := NULL;
    SELECT MAX(ms.test_score)
      INTO lv_best_test_score
      FROM STACKING.MODEL_SCORE ms
     WHERE ms.name = lv_solution_name
       AND ms.version = lv_solution_version
       AND ms.model = r_mi.model_name;

    IF lv_best_test_score IS NOT NULL THEN
      lv_scored_models := lv_scored_models + 1;
      lv_total_test_score := lv_total_test_score + lv_best_test_score;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Model=' || r_mi.model_name || ' | model_importance=' || TO_CHAR(r_mi.model_importance) || ' | best_test_score=' || NVL(TO_CHAR(lv_best_test_score), 'N/A'));
  END LOOP;

  IF lv_models_processed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  ELSE
    DBMS_OUTPUT.PUT_LINE(
      'Summary: models=' || TO_CHAR(lv_models_processed) ||
      ', total_importance=' || TO_CHAR(lv_total_importance) ||
      ', avg_test_score=' || CASE WHEN lv_scored_models = 0 THEN 'N/A' ELSE TO_CHAR(lv_total_test_score / lv_scored_models) END
    );
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric value provided.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

