CREATE OR REPLACE PROCEDURE report_route_punctuality(
  p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE,
  p_arrival_airport   IN AIRLINES.FLIGHTS.arrival_airport%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR cur_flights IS
    SELECT f.flight_no,
           f.scheduled_departure,
           f.actual_departure,
           f.status
      FROM AIRLINES.FLIGHTS f
     WHERE f.departure_airport = p_departure_airport
       AND f.arrival_airport   = p_arrival_airport
     ORDER BY f.scheduled_departure DESC
     FETCH FIRST co_report_limit ROWS ONLY;

  lv_flight_no   AIRLINES.FLIGHTS.flight_no%TYPE;
  lv_sched_dep   AIRLINES.FLIGHTS.scheduled_departure%TYPE;
  lv_actual_dep  AIRLINES.FLIGHTS.actual_departure%TYPE;
  lv_status      AIRLINES.FLIGHTS.status%TYPE;

  lv_delay_min   NUMBER;
  lv_category    VARCHAR2(20);

  lv_rows        PLS_INTEGER := 0;
BEGIN
  IF p_departure_airport = p_arrival_airport THEN
    DBMS_OUTPUT.PUT_LINE('Invalid route: departure and arrival airports are the same.');
    RETURN;
  END IF;

  OPEN cur_flights;
  LOOP
    FETCH cur_flights INTO lv_flight_no, lv_sched_dep, lv_actual_dep, lv_status;
    EXIT WHEN cur_flights%NOTFOUND;

    lv_rows := lv_rows + 1;

    IF lv_actual_dep IS NULL THEN
      lv_delay_min := NULL;
      lv_category  := 'UNKNOWN';
    ELSE
      lv_delay_min := ROUND((CAST(lv_actual_dep AS DATE) - CAST(lv_sched_dep AS DATE)) * 24 * 60);

      IF lv_delay_min > 15 THEN
        lv_category := 'DELAYED';
      ELSE
        lv_category := 'ON_TIME';
      END IF;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'FLIGHT_NO=' || lv_flight_no ||
      ', SCHED_DEP=' || TO_CHAR(lv_sched_dep, 'YYYY-MM-DD HH24:MI') ||
      ', STATUS=' || lv_status ||
      ', delay_min=' || CASE WHEN lv_delay_min IS NULL THEN 'NULL' ELSE TO_CHAR(lv_delay_min) END ||
      ', CATEGORY=' || lv_category
    );
  END LOOP;
  CLOSE cur_flights;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No flights found for the given route.');
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No flights found for the given route.');
  WHEN OTHERS THEN
    IF cur_flights%ISOPEN THEN
      CLOSE cur_flights;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_route_punctuality;
/

CREATE OR REPLACE PROCEDURE report_top_customers_by_country(
  p_billing_country IN CHINOOK.INVOICES.billingcountry%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_billing_country IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Country must not be NULL.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top customers for country: ' || p_billing_country);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 60, '-'));

  FOR rec IN (
    SELECT
      c.customerid AS customerid,
      c.firstname || ' ' || c.lastname AS full_name,
      SUM(i.total) AS total_spend,
      COUNT(*) AS invoice_count
    FROM CHINOOK.CUSTOMERS c
    INNER JOIN CHINOOK.INVOICES i
      ON i.customerid = c.customerid
    WHERE i.billingcountry = p_billing_country
    GROUP BY c.customerid, c.firstname, c.lastname
    ORDER BY SUM(i.total) DESC, COUNT(*) DESC, c.customerid
    FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      'CustomerId=' || rec.customerid ||
      ' | Name=' || rec.full_name ||
      ' | Total=' || TO_CHAR(rec.total_spend, 'FM9999990D00') ||
      ' | Invoices=' || rec.invoice_count
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows to report.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_customers_by_country;
/

CREATE OR REPLACE PROCEDURE report_country_demographics(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE,
  p_year_from    IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE,
  p_year_to      IN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_lines_printed PLS_INTEGER := 0;

  lv_cbr VARCHAR2(30);
  lv_cdr VARCHAR2(30);
  lv_gr  VARCHAR2(30);
  lv_tfr VARCHAR2(30);

  -- Safe numeric formatting helper (kept as local function for reuse).
  FUNCTION safe_num(p_txt IN VARCHAR2) RETURN VARCHAR2 IS
    lv_num NUMBER;
  BEGIN
    IF p_txt IS NULL OR TRIM(p_txt) IS NULL THEN
      RETURN 'N/A';
    END IF;

    lv_num := TO_NUMBER(TRIM(p_txt));
    RETURN TO_CHAR(lv_num);
  EXCEPTION
    WHEN VALUE_ERROR THEN
      RETURN 'N/A';
    WHEN INVALID_NUMBER THEN
      RETURN 'N/A';
    WHEN OTHERS THEN
      RETURN 'N/A';
  END safe_num;
BEGIN
  -- Parameter validation
  IF p_country_name IS NULL OR TRIM(p_country_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: country name is required.');
    RETURN;
  END IF;

  IF p_year_from IS NULL OR p_year_to IS NULL OR TRIM(p_year_from) IS NULL OR TRIM(p_year_to) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year range is required.');
    RETURN;
  END IF;

  IF TO_NUMBER(TRIM(p_year_from)) > TO_NUMBER(TRIM(p_year_to)) THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year_from must be <= year_to.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('COUNTRY=' || p_country_name || ' YEARS=' || p_year_from || '-' || p_year_to);

  FOR rec IN (
    WITH b AS (
      SELECT
        bdg.country_name,
        bdg.year,
        bdg.crude_birth_rate,
        bdg.crude_death_rate,
        bdg.growth_rate
      FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bdg
      WHERE bdg.country_name = p_country_name
        AND TO_NUMBER(TRIM(bdg.year)) BETWEEN TO_NUMBER(TRIM(p_year_from)) AND TO_NUMBER(TRIM(p_year_to))
    ),
    f AS (
      SELECT
        asfr.country_name,
        asfr.year,
        asfr.total_fertility_rate
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES asfr
      WHERE asfr.country_name = p_country_name
        AND TO_NUMBER(TRIM(asfr.year)) BETWEEN TO_NUMBER(TRIM(p_year_from)) AND TO_NUMBER(TRIM(p_year_to))
    )
    SELECT
      b.year,
      b.crude_birth_rate,
      b.crude_death_rate,
      b.growth_rate,
      f.total_fertility_rate
    FROM b
    LEFT OUTER JOIN f
      ON f.country_name = b.country_name
     AND f.year = b.year
    ORDER BY TO_NUMBER(TRIM(b.year))
  ) LOOP
    lv_cbr := safe_num(rec.crude_birth_rate);
    lv_cdr := safe_num(rec.crude_death_rate);
    lv_gr  := safe_num(rec.growth_rate);
    lv_tfr := safe_num(rec.total_fertility_rate);

    DBMS_OUTPUT.PUT_LINE(
      'YEAR=' || rec.year ||
      ' CBR=' || lv_cbr ||
      ' CDR=' || lv_cdr ||
      ' GR='  || lv_gr  ||
      ' TFR=' || lv_tfr
    );

    lv_lines_printed := lv_lines_printed + 1;
    IF lv_lines_printed >= co_report_limit THEN
      EXIT;
    END IF;
  END LOOP;

  IF lv_lines_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found for inputs.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found for inputs.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_demographics;
/

