DECLARE
  co_row_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_report_year GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING.report_year%TYPE := '2023';
  lv_row_count   PLS_INTEGER := 0;
BEGIN
  IF lv_report_year IS NULL OR LENGTH(lv_report_year) <> 4 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid report year. Provide a 4-character year like 2023.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Hiring representation for year ' || lv_report_year || ' (showing up to ' || co_row_limit || ' rows)');

  FOR rec IN (
    SELECT h.workforce,
           h.gender_us,
           h.race_asian,
           h.race_black,
           h.race_hispanic_latinx,
           h.race_native_american,
           h.race_white
      FROM GOOGLE_DEI.DAR_INTERSECTIONAL_HIRING h
     WHERE h.report_year = lv_report_year
     ORDER BY h.workforce, h.gender_us
  ) LOOP
    lv_row_count := lv_row_count + 1;
    EXIT WHEN lv_row_count > co_row_limit;

    DBMS_OUTPUT.PUT_LINE(
      'WORKFORCE=' || rec.workforce ||
      ', GENDER_US=' || rec.gender_us ||
      ', ASIAN=' || rec.race_asian ||
      ', BLACK=' || rec.race_black ||
      ', HISPANIC_LATINX=' || rec.race_hispanic_latinx ||
      ', NATIVE_AMERICAN=' || rec.race_native_american ||
      ', WHITE=' || rec.race_white
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for year ' || lv_report_year || '.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

