CREATE OR REPLACE PROCEDURE report_group_pick_readiness(
  p_group_name IN ORACLE_SQL.PRODUCT_GROUPS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_group_id      ORACLE_SQL.PRODUCT_GROUPS.id%TYPE;
  lv_product_name  ORACLE_SQL.PRODUCTS.name%TYPE;
  lv_minimum       ORACLE_SQL.PRODUCT_MINIMUMS.qty_minimum%TYPE;
  lv_on_hand       ORACLE_SQL.INVENTORY.qty%TYPE;
  lv_status        VARCHAR2(10);

  lv_ready_cnt     PLS_INTEGER := 0;
  lv_short_cnt     PLS_INTEGER := 0;
  lv_rows_printed  PLS_INTEGER := 0;

  CURSOR cur_products(p_gid ORACLE_SQL.PRODUCT_GROUPS.id%TYPE) IS
    SELECT p.name AS product_name,
           pm.qty_minimum AS qty_minimum,
           (SELECT NVL(SUM(i.qty), 0)
              FROM ORACLE_SQL.INVENTORY i
             WHERE i.product_id = p.id) AS on_hand
      FROM ORACLE_SQL.PRODUCTS p
      INNER JOIN ORACLE_SQL.PRODUCT_MINIMUMS pm
        ON pm.product_id = p.id
     WHERE p.group_id = p_gid
     ORDER BY p.name;
BEGIN
  IF p_group_name IS NULL OR TRIM(p_group_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input group name is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Pick readiness report for group: ' || p_group_name);

  SELECT pg.id
    INTO lv_group_id
    FROM ORACLE_SQL.PRODUCT_GROUPS pg
   WHERE pg.name = p_group_name;

  DBMS_OUTPUT.PUT_LINE(RPAD('Product', 35) || ' ' || LPAD('OnHand', 10) || ' ' || LPAD('Minimum', 10) || ' Status');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || ' ' || LPAD('-', 10, '-') || ' ' || LPAD('-', 10, '-') || ' ' || RPAD('-', 6, '-'));

  FOR r IN cur_products(lv_group_id) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    lv_product_name := r.product_name;
    lv_minimum := r.qty_minimum;
    lv_on_hand := r.on_hand;

    IF lv_on_hand >= lv_minimum THEN
      lv_status := 'READY';
      lv_ready_cnt := lv_ready_cnt + 1;
    ELSE
      lv_status := 'SHORT';
      lv_short_cnt := lv_short_cnt + 1;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(lv_product_name, 35) || ' ' ||
      LPAD(TO_CHAR(lv_on_hand), 10) || ' ' ||
      LPAD(TO_CHAR(lv_minimum), 10) || ' ' ||
      lv_status
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No products found for group: ' || p_group_name);
  ELSE
    DBMS_OUTPUT.PUT_LINE('Summary - READY: ' || lv_ready_cnt || ', SHORT: ' || lv_short_cnt);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No such product group: ' || p_group_name);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_group_pick_readiness;
/

