CREATE OR REPLACE PROCEDURE report_category_price_health(
  p_category IN COMPLEX_ORACLE.PRODUCTS.prod_category%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_status  VARCHAR2(20);
  lv_printed PLS_INTEGER := 0;
BEGIN
  IF p_category IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Category is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Price health report for category: ' || p_category);

  FOR rec IN (
    SELECT p.prod_name,
           p.prod_list_price,
           p.prod_min_price
      FROM COMPLEX_ORACLE.PRODUCTS p
     WHERE p.prod_category = p_category
       AND ROWNUM <= co_report_limit
     ORDER BY p.prod_name
  ) LOOP
    lv_printed := lv_printed + 1;

    IF rec.prod_list_price < rec.prod_min_price THEN
      lv_status := 'PRICE_ERROR';
    ELSE
      lv_status := 'OK';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Product: ' || rec.prod_name ||
      ' | List: ' || TO_CHAR(rec.prod_list_price) ||
      ' | Min: ' || TO_CHAR(rec.prod_min_price) ||
      ' | Status: ' || lv_status
    );
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No products found for category: ' || p_category);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_category_price_health;
/

CREATE OR REPLACE PROCEDURE report_bikeshare_landmark_health(
  p_landmark IN SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_station_count PLS_INTEGER := 0;
  lv_dock_sum      NUMBER := 0;
  lv_avg_docks     NUMBER := 0;
BEGIN
  IF p_landmark IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Landmark is required.');
    RETURN;
  END IF;

  -- Latest status per station (if present). Convert string metrics safely via TO_NUMBER.
  FOR rec IN (
    WITH latest_status AS (
      SELECT s.station_id,
             TO_NUMBER(s.bikes_available) AS bikes_avail_num,
             TO_NUMBER(s.docks_available) AS docks_avail_num,
             ROW_NUMBER() OVER (PARTITION BY s.station_id ORDER BY s.time DESC) AS rn
        FROM SAN_FRANCISCO.BIKESHARE_STATUS s
    )
    SELECT st.name AS station_name,
           TO_NUMBER(st.dockcount) AS dock_count_num,
           NVL(ls.bikes_avail_num, 0) AS bikes_avail_num,
           NVL(ls.docks_avail_num, 0) AS docks_avail_num
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS st
      LEFT JOIN latest_status ls
        ON ls.station_id = st.station_id
       AND ls.rn = 1
     WHERE st.landmark = p_landmark
     ORDER BY TO_NUMBER(st.dockcount) DESC, st.name
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_station_count := lv_station_count + 1;
    lv_dock_sum := lv_dock_sum + rec.dock_count_num;

    DBMS_OUTPUT.PUT_LINE(
      'Station: ' || rec.station_name ||
      ' | Docks: ' || rec.dock_count_num ||
      ' | Bikes avail: ' || rec.bikes_avail_num ||
      ' | Docks avail: ' || rec.docks_avail_num
    );
  END LOOP;

  IF lv_station_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark.');
    RETURN;
  END IF;

  lv_avg_docks := lv_dock_sum / lv_station_count;
  DBMS_OUTPUT.PUT_LINE(
    'Summary | Stations shown: ' || lv_station_count ||
    ' | Avg docks: ' || TO_CHAR(lv_avg_docks, 'FM9990D00')
  );

EXCEPTION
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered.');
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_bikeshare_landmark_health;
/

