           f.scheduled_departure,
           CASE
             WHEN EXISTS (
               SELECT 1
                 FROM AIRLINES.BOARDING_PASSES bp
                WHERE bp.flight_id = f.flight_id
             ) THEN 'READY'
             ELSE 'NOT READY'
           END AS boarding_status
      FROM AIRLINES.FLIGHTS f
     WHERE f.departure_airport = lv_departure_airport
       AND f.status = 'Scheduled'
     ORDER BY f.scheduled_departure
  ) LOOP
    EXIT WHEN lv_printed_rows >= co_report_limit;
    lv_printed_rows := lv_printed_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      'Flight ' || r.flight_no ||
      ' | SchedDep=' || TO_CHAR(r.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
      ' | Boarding=' || r.boarding_status
    );
  END LOOP;

  IF lv_printed_rows = 0 THEN
    -- Treat an empty result set as "no data" for the report consumer
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

