CREATE OR REPLACE PROCEDURE report_races_by_year(
  p_year IN F1.RACES.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year F1.RACES.year%TYPE;
  lv_cnt  NUMBER;
BEGIN
  -- Default to most recent season year when input is NULL
  IF p_year IS NULL THEN
    SELECT MAX(r.year)
      INTO lv_year
      FROM F1.RACES r;
  ELSE
    lv_year := p_year;
  END IF;

  -- Validate that the year has races before attempting the report
  SELECT COUNT(*)
    INTO lv_cnt
    FROM F1.RACES r
   WHERE r.year = lv_year;

  IF lv_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No races found for year ' || lv_year);
    RETURN;
  END IF;

  FOR r IN (
    SELECT *
      FROM (
        SELECT ra.name  AS race_name,
               ra.c_date AS race_date,
               c.name   AS circuit_name,
               c.country AS country
          FROM F1.RACES ra
          INNER JOIN F1.CIRCUITS c
            ON c.circuit_id = ra.circuit_id
         WHERE ra.year = lv_year
         ORDER BY ra.c_date, ra.race_id
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'Race: ' || r.race_name ||
      ' | Date: ' || TO_CHAR(r.race_date, 'YYYY-MM-DD') ||
      ' | Circuit: ' || r.circuit_name ||
      ' | Country: ' || r.country
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No races found for year ' || p_year);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_races_by_year;
/

CREATE OR REPLACE PROCEDURE rpt_active_careplans(
  p_patient_id IN SYNTHEA.CAREPLANS.patient%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_patient_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Patient ID is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Active care plans for patient ' || p_patient_id || ':');

  FOR rec IN (
    SELECT cp.start_date,
           cp.code,
           cp.description
      FROM SYNTHEA.CAREPLANS cp
     WHERE cp.patient = p_patient_id
       AND cp.stop_date IS NULL
     ORDER BY cp.start_date DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Start=' || TO_CHAR(rec.start_date, 'YYYY-MM-DD') ||
      ' Code=' || rec.code ||
      ' Desc=' || SUBSTR(rec.description, 1, 80)
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No active care plans found.');
    -- Emphasize exception handling for "no data" as a training objective
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No active care plans found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_active_careplans;
/

