question:
Build a reusable stored procedure that, for a given patient ID, prints a small “clinical snapshot” to the console:

 Print the patient’s full name.
 Print up to 15 of the most recent encounters (newest first) with encounter start date/time, class, and description.
 For each listed encounter, also print a medication count for that encounter.
 If the patient has no encounters, print a clear message and do not error.

Make sure the procedure is safe for production use: handle null inputs, handle missing patients, and catch unexpected errors without letting them propagate.

Requirements:
Procedure Name: print_patient_snapshot
Parameters:
p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient_name);
DBMS_OUTPUT.PUT_LINE('Most recent encounters (max ' || co_report_limit || '):');
DBMS_OUTPUT.PUT_LINE('No encounters found for patient.');
DBMS_OUTPUT.PUT_LINE(' - ' || TO_CHAR(rec.start_ts, 'YYYY-MM-DD HH24:MI') || ' | ' || NVL(rec.enc_class, 'UNKNOWN') || ' | ' || NVL(rec.enc_desc, 'UNKNOWN') || ' | meds=' || rec.med_count);
DBMS_OUTPUT.PUT_LINE('Input patient_id is NULL.');
DBMS_OUTPUT.PUT_LINE('Patient not found.');
DBMS_OUTPUT.PUT_LINE('Multiple patients returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'Patient not found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple patients returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE print_patient_snapshot(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_patient_name VARCHAR2(250);
  lv_encounter_rows PLS_INTEGER := 0;
BEGIN
  IF p_patient_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input patient_id is NULL.');
    RETURN;
  END IF;

  -- Fetch patient display name
  SELECT p.first || ' ' || p.last
    INTO lv_patient_name
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient_name);
  DBMS_OUTPUT.PUT_LINE('Most recent encounters (max ' || co_report_limit || '):');

  -- Print up to N most recent encounters with a per-encounter medication count
  FOR rec IN (
    SELECT *
      FROM (
        SELECT e.start_timestamp AS start_ts,
               e.encounterclass AS enc_class,
               e.description AS enc_desc,
               e.id AS encounter_id,
               (SELECT COUNT(*)
                  FROM SYNTHEA.MEDICATIONS m
                 WHERE m.encounter = e.id) AS med_count
          FROM SYNTHEA.ENCOUNTERS e
         WHERE e.patient = p_patient_id
         ORDER BY e.start_timestamp DESC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_encounter_rows := lv_encounter_rows + 1;

    DBMS_OUTPUT.PUT_LINE(
      ' - ' || TO_CHAR(rec.start_ts, 'YYYY-MM-DD HH24:MI') ||
      ' | ' || NVL(rec.enc_class, 'UNKNOWN') ||
      ' | ' || NVL(rec.enc_desc, 'UNKNOWN') ||
      ' | meds=' || rec.med_count
    );
  END LOOP;

  IF lv_encounter_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for patient.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Patient not found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple patients returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END print_patient_snapshot;
/

CREATE OR REPLACE PACKAGE debt_reporting_pkg IS
  PROCEDURE report_indicator_top_countries(
    p_indicator_code IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_code%TYPE,
    p_year           IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
  );
END debt_reporting_pkg;
/

CREATE OR REPLACE PACKAGE BODY debt_reporting_pkg IS
  PROCEDURE report_indicator_top_countries(
    p_indicator_code IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_code%TYPE,
    p_year           IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_indicator_name WORLD_BANK_INTL_DEBT.SERIES_SUMMARY.indicator_name%TYPE;
    lv_total_value    NUMBER;
    lv_rows_reported  PLS_INTEGER := 0;
    lv_risk_band      VARCHAR2(10);
  BEGIN
    -- Basic parameter validation
    IF p_indicator_code IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input validation failed: indicator code is required.');
      RETURN;
    END IF;

    IF p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input validation failed: year is required.');
      RETURN;
    END IF;

    -- Confirm indicator exists in the catalog (and retrieve its name)
    SELECT ss.indicator_name
      INTO lv_indicator_name
      FROM WORLD_BANK_INTL_DEBT.SERIES_SUMMARY ss
     WHERE ss.series_code = p_indicator_code;

    DBMS_OUTPUT.PUT_LINE('Indicator verified: ' || lv_indicator_name);

    -- Compute total among the same top-N rows we will output
    WITH ranked AS (
      SELECT id.country_name,
             TO_NUMBER(id.value) AS val_num,
             ROW_NUMBER() OVER (ORDER BY TO_NUMBER(id.value) DESC, id.country_name ASC) AS rn
        FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
       WHERE id.indicator_code = p_indicator_code
         AND id.year = p_year
         AND id.value IS NOT NULL
    )
    SELECT SUM(r.val_num)
      INTO lv_total_value
      FROM ranked r
     WHERE r.rn <= co_report_limit;

    -- Output top countries with share-based risk banding
    FOR rec IN (
      WITH ranked AS (
        SELECT id.country_name,
               TO_NUMBER(id.value) AS val_num,
               ROW_NUMBER() OVER (ORDER BY TO_NUMBER(id.value) DESC, id.country_name ASC) AS rn
          FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
         WHERE id.indicator_code = p_indicator_code
           AND id.year = p_year
           AND id.value IS NOT NULL
      )
      SELECT r.country_name,
             r.val_num,
             CASE
               WHEN lv_total_value = 0 THEN 0
               ELSE (r.val_num / lv_total_value) * 100
             END AS share_pct
        FROM ranked r
       WHERE r.rn <= co_report_limit
       ORDER BY r.rn
    ) LOOP
      lv_rows_reported := lv_rows_reported + 1;

      IF rec.share_pct >= 10 THEN
        lv_risk_band := 'HIGH';
      ELSIF rec.share_pct >= 3 THEN
        lv_risk_band := 'MEDIUM';
      ELSE
        lv_risk_band := 'LOW';
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        'Country: ' || rec.country_name ||
        ' | Value: ' || TO_CHAR(rec.val_num) ||
        ' | Share: ' || TO_CHAR(rec.share_pct, 'FM990D00') || '% | Risk: ' || lv_risk_band
      );
    END LOOP;

    IF lv_rows_reported = 0 THEN
      -- Standardize to NO_DATA_FOUND handler message for the whole procedure
      RAISE NO_DATA_FOUND;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Summary: rows_reported=' || lv_rows_reported ||
      ' total_value=' || TO_CHAR(lv_total_value)
    );

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found for indicator/year.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Indicator code is ambiguous in the catalog.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_indicator_top_countries;
END debt_reporting_pkg;
/

