CREATE OR REPLACE PACKAGE wdi_reporting_pkg IS
  PROCEDURE report_indicator_top_countries(
    p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE,
    p_year           IN WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE,
    p_region         IN WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE
  );
END wdi_reporting_pkg;
/

CREATE OR REPLACE PACKAGE BODY wdi_reporting_pkg IS
  PROCEDURE report_indicator_top_countries(
    p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE,
    p_year           IN WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE,
    p_region         IN WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_year_num PLS_INTEGER;
    lv_rows     PLS_INTEGER := 0;

    CURSOR c_top IS
      WITH ranked AS (
        SELECT
          cs.short_name   AS country_name,
          cs.income_group AS income_group,
          TO_NUMBER(id.value) AS ind_value,
          ROW_NUMBER() OVER (ORDER BY TO_NUMBER(id.value) DESC, cs.short_name ASC) AS rn
        FROM WORLD_BANK_WDI.INDICATORS_DATA id
        INNER JOIN WORLD_BANK_WDI.COUNTRY_SUMMARY cs
          ON cs.country_code = id.country_code
        WHERE id.indicator_code = p_indicator_code
          AND id.year = p_year
          AND (p_region IS NULL OR cs.region = p_region)
          AND id.value IS NOT NULL
      )
      SELECT
        ranked.country_name,
        ranked.income_group,
        ranked.ind_value
      FROM ranked
      WHERE ranked.rn <= co_report_limit
      ORDER BY ranked.rn;

    r c_top%ROWTYPE;
  BEGIN
    -- Basic input validation
    IF p_indicator_code IS NULL OR p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input validation failed: indicator_code and year are required.');
      RETURN;
    END IF;

    -- Ensure year is numeric (conversion used only for validation)
    lv_year_num := TO_NUMBER(p_year);

    DBMS_OUTPUT.PUT_LINE('Report: Top countries for indicator ' || p_indicator_code || ', year ' || p_year || ', region ' || p_region);

    OPEN c_top;
    LOOP
      FETCH c_top INTO r;
      EXIT WHEN c_top%NOTFOUND;

      lv_rows := lv_rows + 1;
      DBMS_OUTPUT.PUT_LINE('Country: ' || r.country_name || ' | Income group: ' || r.income_group || ' | Value: ' || r.ind_value);
    END LOOP;
    CLOSE c_top;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the given filters.');
    END IF;

    DBMS_OUTPUT.PUT_LINE('Rows output: ' || lv_rows);

  EXCEPTION
    WHEN VALUE_ERROR THEN
      -- Covers non-numeric year and non-numeric indicator values
      IF c_top%ISOPEN THEN
        CLOSE c_top;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Invalid year: must be a numeric string.');
    WHEN NO_DATA_FOUND THEN
      IF c_top%ISOPEN THEN
        CLOSE c_top;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      IF c_top%ISOPEN THEN
        CLOSE c_top;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      IF c_top%ISOPEN THEN
        CLOSE c_top;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_indicator_top_countries;
END wdi_reporting_pkg;
/

