CREATE OR REPLACE PROCEDURE dei_snapshot(
  p_workforce   IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE,
  p_report_year IN GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_race_asian           GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.race_asian%TYPE;
  lv_race_black           GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.race_black%TYPE;
  lv_race_hispanic_latinx GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.race_hispanic_latinx%TYPE;
  lv_race_native_american GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.race_native_american%TYPE;
  lv_race_white           GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.race_white%TYPE;

  lv_non_null_race_fields NUMBER := 0;
BEGIN
  -- Basic input guardrails
  IF p_workforce IS NULL OR p_report_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: workforce and report year are required.');
    RETURN;
  END IF;

  -- Single-row fetch for the intersectional representation record
  SELECT r.race_asian,
         r.race_black,
         r.race_hispanic_latinx,
         r.race_native_american,
         r.race_white
    INTO lv_race_asian,
         lv_race_black,
         lv_race_hispanic_latinx,
         lv_race_native_american,
         lv_race_white
    FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
   WHERE r.workforce = p_workforce
     AND r.report_year = p_report_year;

  -- Simple completeness check: count non-null race columns
  IF lv_race_asian IS NOT NULL THEN
    lv_non_null_race_fields := lv_non_null_race_fields + 1;
  END IF;
  IF lv_race_black IS NOT NULL THEN
    lv_non_null_race_fields := lv_non_null_race_fields + 1;
  END IF;
  IF lv_race_hispanic_latinx IS NOT NULL THEN
    lv_non_null_race_fields := lv_non_null_race_fields + 1;
  END IF;
  IF lv_race_native_american IS NOT NULL THEN
    lv_non_null_race_fields := lv_non_null_race_fields + 1;
  END IF;
  IF lv_race_white IS NOT NULL THEN
    lv_non_null_race_fields := lv_non_null_race_fields + 1;
  END IF;

  DBMS_OUTPUT.PUT_LINE('DEI Snapshot - Workforce: ' || p_workforce || ', Year: ' || p_report_year);
  DBMS_OUTPUT.PUT_LINE('Completeness - Non-null race fields: ' || lv_non_null_race_fields);

  -- Print only populated race fields; cap to a small report limit
  DECLARE
    lv_printed PLS_INTEGER := 0;
  BEGIN
    IF lv_race_asian IS NOT NULL AND lv_printed < co_report_limit THEN
      DBMS_OUTPUT.PUT_LINE('Race Asian: ' || lv_race_asian);
      lv_printed := lv_printed + 1;
    END IF;

    IF lv_race_black IS NOT NULL AND lv_printed < co_report_limit THEN
      DBMS_OUTPUT.PUT_LINE('Race Black: ' || lv_race_black);
      lv_printed := lv_printed + 1;
    END IF;

    IF lv_race_hispanic_latinx IS NOT NULL AND lv_printed < co_report_limit THEN
      DBMS_OUTPUT.PUT_LINE('Race Hispanic/Latinx: ' || lv_race_hispanic_latinx);
      lv_printed := lv_printed + 1;
    END IF;

    IF lv_race_native_american IS NOT NULL AND lv_printed < co_report_limit THEN
      DBMS_OUTPUT.PUT_LINE('Race Native American: ' || lv_race_native_american);
      lv_printed := lv_printed + 1;
    END IF;

    IF lv_race_white IS NOT NULL AND lv_printed < co_report_limit THEN
      DBMS_OUTPUT.PUT_LINE('Race White: ' || lv_race_white);
      lv_printed := lv_printed + 1;
    END IF;

    IF lv_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No race fields are populated for this row.');
    END IF;
  END;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END dei_snapshot;
/

CREATE OR REPLACE PROCEDURE cpi_u_year_summary(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_item_name IN BLS.CPI_U.item_name%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) IS
  lv_period_count NUMBER;
  lv_min_value    NUMBER;
  lv_max_value    NUMBER;
BEGIN
  -- Basic input validation
  IF p_area_name IS NULL OR TRIM(p_area_name) IS NULL
     OR p_item_name IS NULL OR TRIM(p_item_name) IS NULL
     OR p_year IS NULL OR TRIM(p_year) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: area_name, item_name, and year are required.');
    RETURN;
  END IF;

  -- Summarize CPI-U values for the given slice.
  SELECT COUNT(*),
         MIN(TO_NUMBER(c.value)),
         MAX(TO_NUMBER(c.value))
    INTO lv_period_count, lv_min_value, lv_max_value
    FROM BLS.CPI_U c
   WHERE c.area_name = p_area_name
     AND c.item_name = p_item_name
     AND c.year = p_year;

  -- COUNT(*) always returns a row; use this guard to raise NO_DATA_FOUND explicitly.
  IF lv_period_count = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI-U Summary | Area=' || p_area_name || ' | Item=' || p_item_name || ' | Year=' || p_year);
  DBMS_OUTPUT.PUT_LINE('Periods found=' || TO_CHAR(lv_period_count));
  DBMS_OUTPUT.PUT_LINE('Min value=' || TO_CHAR(lv_min_value));
  DBMS_OUTPUT.PUT_LINE('Max value=' || TO_CHAR(lv_max_value));

  -- Simple coverage label based on the number of periods captured.
  IF lv_period_count >= 12 THEN
    DBMS_OUTPUT.PUT_LINE('Coverage=Full year');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Coverage=Partial year');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_u_year_summary;
/

CREATE OR REPLACE PROCEDURE report_county_natality(
  p_county_name IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
  p_start_year  IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_end_year    IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_row_count    PLS_INTEGER := 0;
BEGIN
  -- Basic parameter validation
  IF p_county_name IS NULL
     OR p_start_year IS NULL
     OR p_end_year IS NULL
     OR p_start_year > p_end_year
  THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: county name and year range are required, and start year must be <= end year.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('County=' || p_county_name || ', Years=' || TO_CHAR(p_start_year, 'YYYY') || '-' || TO_CHAR(p_end_year, 'YYYY'));
  DBMS_OUTPUT.PUT_LINE('YEAR | BIRTHS | AVE_BIRTH_WEIGHT_GMS');

  FOR rec IN (
    SELECT t.year,
           TO_NUMBER(TRIM(t.births)) AS births_num,
           CASE
             WHEN REGEXP_LIKE(TRIM(t.ave_birth_weight_gms), '^[-+]?[0-9]*\.?[0-9]+$')
             THEN TO_NUMBER(TRIM(t.ave_birth_weight_gms))
             ELSE NULL
           END AS ave_bw_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY t
     WHERE t.county_of_residence = p_county_name
       AND t.year BETWEEN p_start_year AND p_end_year
       -- Only keep rows with numeric births that are > 0
       AND REGEXP_LIKE(TRIM(t.births), '^[0-9]+(\.[0-9]+)?$')
       AND TO_NUMBER(TRIM(t.births)) > 0
     ORDER BY t.year
  ) LOOP
    lv_row_count := lv_row_count + 1;
    EXIT WHEN lv_row_count > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rec.year, 'YYYY') || ' | ' || TO_CHAR(rec.births_num) || ' | ' ||
      CASE WHEN rec.ave_bw_num IS NULL THEN 'NULL' ELSE TO_CHAR(rec.ave_bw_num) END
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_county_natality;
/

