CREATE OR REPLACE PROCEDURE report_region_top_start_stations(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE,
  p_start_ts    IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_date%TYPE,
  p_end_ts      IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.end_date%TYPE,
  p_top_n       IN NUMBER
) IS
  co_max_top_n CONSTANT PLS_INTEGER := 15; -- Safety cap to keep report output readable

  lv_region_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Region: ' || p_region_name);
  DBMS_OUTPUT.PUT_LINE('Window: ' || TO_CHAR(p_start_ts, 'YYYY-MM-DD HH24:MI:SS') || ' to ' || TO_CHAR(p_end_ts, 'YYYY-MM-DD HH24:MI:SS'));
  DBMS_OUTPUT.PUT_LINE('Top N: ' || p_top_n);

  -- Input validation
  IF p_region_name IS NULL OR TRIM(p_region_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: region name is required.');
    RETURN;
  END IF;

  IF p_start_ts IS NULL OR p_end_ts IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: start and end timestamps are required.');
    RETURN;
  END IF;

  IF p_end_ts <= p_start_ts THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: end timestamp must be after start timestamp.');
    RETURN;
  END IF;

  IF p_top_n IS NULL OR p_top_n < 1 OR p_top_n > co_max_top_n THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: top_n must be between 1 and 15.');
    RETURN;
  END IF;

  -- Resolve region; if not found, treat as NO_DATA_FOUND
  SELECT r.region_id
    INTO lv_region_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
   WHERE UPPER(r.name) = UPPER(p_region_name);

  -- Rank stations by trip volume in the window (deterministic tie-break using station_name/station_id)
  FOR rec IN (
    WITH station_trip_counts AS (
      SELECT si.station_id,
             si.name AS station_name,
             COUNT(*) AS trip_cnt
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        LEFT OUTER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
          ON t.start_station_id = si.station_id
         AND t.start_date >= p_start_ts
         AND t.start_date <  p_end_ts
       WHERE si.region_id = lv_region_id
       GROUP BY si.station_id, si.name
    ), ranked AS (
      SELECT stc.station_id,
             stc.station_name,
             stc.trip_cnt,
             ROW_NUMBER() OVER (ORDER BY stc.trip_cnt DESC, stc.station_name ASC, stc.station_id ASC) AS rn
        FROM station_trip_counts stc
       WHERE stc.trip_cnt > 0
    )
    SELECT rnk.station_id,
           rnk.station_name,
           rnk.trip_cnt,
           rnk.rn
      FROM ranked rnk
     WHERE rnk.rn <= p_top_n
     ORDER BY rnk.rn
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(LPAD(TO_CHAR(rec.rn), 2, ' ') || '. ' || rec.station_name || ' (station_id=' || rec.station_id || ') trips=' || rec.trip_cnt);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No trips found for the given region and time window.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_top_start_stations;
/

