question:
Build a reusable stored procedure that prints a small report of the most recent encounters for a given patient. The report should show encounter start/stop timestamps, encounter class, and total claim cost, sorted with the newest encounter first.

If the caller passes NULL for the patient id, default to the patient id that appears most frequently in the encounters table. Also, if no encounters exist for the resolved patient id, print a friendly message and exit cleanly.

Make sure the procedure never throws an unhandled runtime error; it must catch and report common exceptions.

Requirements:
Procedure Name: rpt_recent_encounters
Parameters:
p_patient_id IN SYNTHEA.ENCOUNTERS.patient%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient);
DBMS_OUTPUT.PUT_LINE('Showing up to ' || co_report_limit || ' most recent encounters');
DBMS_OUTPUT.PUT_LINE(RPAD('START', 19) || ' ' || RPAD('STOP', 19) || ' ' || RPAD('CLASS', 12) || ' ' || LPAD('TOTAL_CLAIM_COST', 16));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 19, '-') || ' ' || RPAD('-', 19, '-') || ' ' || RPAD('-', 12, '-') || ' ' || LPAD('-', 16, '-'));
DBMS_OUTPUT.PUT_LINE(TO_CHAR(r.start_timestamp, 'YYYY-MM-DD HH24:MI') || ' ' || TO_CHAR(r.stop_timestamp,  'YYYY-MM-DD HH24:MI') || ' ' || RPAD(NVL(r.encounterclass, 'UNKNOWN'), 12) || ' ' || LPAD(TO_CHAR(NVL(r.total_claim_cost, 0), 'FM9999999990D00'), 16));
DBMS_OUTPUT.PUT_LINE('No encounters found for patient.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE rpt_recent_encounters(
  p_patient_id IN SYNTHEA.ENCOUNTERS.patient%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_patient    SYNTHEA.ENCOUNTERS.patient%TYPE;
  lv_row_count  PLS_INTEGER := 0;
BEGIN
  -- Resolve patient id: use input when present; otherwise default to most frequent patient in encounters.
  IF p_patient_id IS NOT NULL THEN
    lv_patient := p_patient_id;
  ELSE
    SELECT patient
      INTO lv_patient
      FROM (
            SELECT e.patient, COUNT(*) AS cnt
              FROM SYNTHEA.ENCOUNTERS e
             GROUP BY e.patient
             ORDER BY cnt DESC, e.patient
           )
     WHERE ROWNUM = 1;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient);
  DBMS_OUTPUT.PUT_LINE('Showing up to ' || co_report_limit || ' most recent encounters');
  DBMS_OUTPUT.PUT_LINE(RPAD('START', 19) || ' ' || RPAD('STOP', 19) || ' ' || RPAD('CLASS', 12) || ' ' || LPAD('TOTAL_CLAIM_COST', 16));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 19, '-') || ' ' || RPAD('-', 19, '-') || ' ' || RPAD('-', 12, '-') || ' ' || LPAD('-', 16, '-'));

  -- Print up to co_report_limit newest encounters.
  FOR r IN (
    SELECT e.start_timestamp,
           e.stop_timestamp,
           e.encounterclass,
           e.total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = lv_patient
     ORDER BY e.start_timestamp DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_row_count := lv_row_count + 1;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(r.start_timestamp, 'YYYY-MM-DD HH24:MI') || ' ' ||
      TO_CHAR(r.stop_timestamp,  'YYYY-MM-DD HH24:MI') || ' ' ||
      RPAD(NVL(r.encounterclass, 'UNKNOWN'), 12) || ' ' ||
      LPAD(TO_CHAR(NVL(r.total_claim_cost, 0), 'FM9999999990D00'), 16)
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for patient.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_recent_encounters;
/

CREATE OR REPLACE PACKAGE demo_pulse_pkg IS
  PROCEDURE print_country_pulse(
    p_country_code IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.country_code%TYPE,
    p_start_year   IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE,
    p_end_year     IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
  );
END demo_pulse_pkg;
/

CREATE OR REPLACE PACKAGE BODY demo_pulse_pkg IS

  PROCEDURE print_country_pulse(
    p_country_code IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.country_code%TYPE,
    p_start_year   IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE,
    p_end_year     IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_start_year_num NUMBER;
    lv_end_year_num   NUMBER;

    CURSOR cur_years(p_cc CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.country_code%TYPE,
                     p_sy CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE,
                     p_ey CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE) IS
      WITH years_in_range AS (
        SELECT DISTINCT mp.country_code,
                        mp.year
          FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION mp
         WHERE mp.country_code = p_cc
           AND TO_NUMBER(mp.year) BETWEEN TO_NUMBER(p_sy) AND TO_NUMBER(p_ey)
        UNION
        SELECT DISTINCT bdg.country_code,
                        bdg.year
          FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bdg
         WHERE bdg.country_code = p_cc
           AND TO_NUMBER(bdg.year) BETWEEN TO_NUMBER(p_sy) AND TO_NUMBER(p_ey)
        UNION
        SELECT DISTINCT asfr.country_code,
                        asfr.year
          FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES asfr
         WHERE asfr.country_code = p_cc
           AND TO_NUMBER(asfr.year) BETWEEN TO_NUMBER(p_sy) AND TO_NUMBER(p_ey)
      )
      SELECT y.country_code,
             y.year
        FROM years_in_range y
       ORDER BY TO_NUMBER(y.year);

    TYPE t_year_rec IS RECORD(
      country_code CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.country_code%TYPE,
      year         CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
    );

    r_yr t_year_rec;

    lv_population  CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.midyear_population%TYPE;
    lv_cbr         CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_birth_rate%TYPE;
    lv_cdr         CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.crude_death_rate%TYPE;
    lv_growth_rate CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.growth_rate%TYPE;
    lv_tfr         CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;

    lv_growth_num NUMBER;
    lv_status     VARCHAR2(20);

    lv_rows_printed PLS_INTEGER := 0;

    lv_cnt_growing   PLS_INTEGER := 0;
    lv_cnt_shrinking PLS_INTEGER := 0;
    lv_cnt_stable    PLS_INTEGER := 0;
    lv_cnt_unknown   PLS_INTEGER := 0;

    lv_any_data PLS_INTEGER := 0;

    PROCEDURE safe_to_number(
      p_str    IN  VARCHAR2,
      p_number OUT NUMBER,
      p_ok     OUT BOOLEAN
    ) IS
    BEGIN
      p_number := TO_NUMBER(p_str);
      p_ok := TRUE;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        p_number := NULL;
        p_ok := FALSE;
      WHEN OTHERS THEN
        p_number := NULL;
        p_ok := FALSE;
    END safe_to_number;

  BEGIN
    -- Input validation
    IF p_country_code IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input validation failed: country code is required.');
      RETURN;
    END IF;

    IF p_start_year IS NULL OR p_end_year IS NULL OR
       NOT REGEXP_LIKE(p_start_year, '^[0-9]{4}$') OR
       NOT REGEXP_LIKE(p_end_year, '^[0-9]{4}$') THEN
      DBMS_OUTPUT.PUT_LINE('Input validation failed: years must be 4-digit strings.');
      RETURN;
    END IF;

    lv_start_year_num := TO_NUMBER(p_start_year);
    lv_end_year_num := TO_NUMBER(p_end_year);

    IF lv_start_year_num > lv_end_year_num THEN
      DBMS_OUTPUT.PUT_LINE('Input validation failed: start year must be <= end year.');
      RETURN;
    END IF;

    OPEN cur_years(p_country_code, p_start_year, p_end_year);

    LOOP
      FETCH cur_years INTO r_yr;
      EXIT WHEN cur_years%NOTFOUND;

      lv_any_data := 1;

      -- Reset per-year values
      lv_population := NULL;
      lv_cbr := NULL;
      lv_cdr := NULL;
      lv_growth_rate := NULL;
      lv_tfr := NULL;

      -- Pull metrics (single-row expects) - protected via local blocks
      BEGIN
        SELECT mp.midyear_population
          INTO lv_population
          FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION mp
         WHERE mp.country_code = r_yr.country_code
           AND mp.year = r_yr.year
           AND ROWNUM = 1;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_population := NULL;
        WHEN TOO_MANY_ROWS THEN
          lv_population := NULL;
        WHEN OTHERS THEN
          lv_population := NULL;
      END;

      BEGIN
        SELECT bdg.crude_birth_rate,
               bdg.crude_death_rate,
               bdg.growth_rate
          INTO lv_cbr,
               lv_cdr,
               lv_growth_rate
          FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bdg
         WHERE bdg.country_code = r_yr.country_code
           AND bdg.year = r_yr.year
           AND ROWNUM = 1;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_cbr := NULL;
          lv_cdr := NULL;
          lv_growth_rate := NULL;
        WHEN TOO_MANY_ROWS THEN
          lv_cbr := NULL;
          lv_cdr := NULL;
          lv_growth_rate := NULL;
        WHEN OTHERS THEN
          lv_cbr := NULL;
          lv_cdr := NULL;
          lv_growth_rate := NULL;
      END;

      BEGIN
        SELECT asfr.total_fertility_rate
          INTO lv_tfr
          FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES asfr
         WHERE asfr.country_code = r_yr.country_code
           AND asfr.year = r_yr.year
           AND ROWNUM = 1;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_tfr := NULL;
        WHEN TOO_MANY_ROWS THEN
          lv_tfr := NULL;
        WHEN OTHERS THEN
          lv_tfr := NULL;
      END;

      -- Derive status based on (possibly non-numeric) growth_rate
      DECLARE
        lv_ok BOOLEAN;
      BEGIN
        safe_to_number(lv_growth_rate, lv_growth_num, lv_ok);

        IF lv_ok = FALSE OR lv_growth_num IS NULL THEN
          lv_status := 'UNKNOWN';
          lv_cnt_unknown := lv_cnt_unknown + 1;
        ELSIF lv_growth_num > 0 THEN
          lv_status := 'GROWING';
          lv_cnt_growing := lv_cnt_growing + 1;
        ELSIF lv_growth_num < 0 THEN
          lv_status := 'SHRINKING';
          lv_cnt_shrinking := lv_cnt_shrinking + 1;
        ELSE
          lv_status := 'STABLE';
          lv_cnt_stable := lv_cnt_stable + 1;
        END IF;
      EXCEPTION
        WHEN OTHERS THEN
          lv_status := 'UNKNOWN';
          lv_cnt_unknown := lv_cnt_unknown + 1;
      END;

      IF lv_rows_printed < co_report_limit THEN
        DBMS_OUTPUT.PUT_LINE('YEAR=' || r_yr.year ||
                           ' COUNTRY=' || r_yr.country_code ||
                           ' POP=' || NVL(lv_population, 'NA') ||
                           ' CBR=' || NVL(lv_cbr, 'NA') ||
                           ' CDR=' || NVL(lv_cdr, 'NA') ||
                           ' TFR=' || NVL(lv_tfr, 'NA') ||
                           ' GROWTH=' || NVL(lv_growth_rate, 'NA') ||
                           ' STATUS=' || lv_status);
        lv_rows_printed := lv_rows_printed + 1;
      END IF;

      EXIT WHEN lv_rows_printed >= co_report_limit;
    END LOOP;

    CLOSE cur_years;

    IF lv_any_data = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Summary for ' || p_country_code || ' years ' || p_start_year || '-' || p_end_year || ': ' ||
                         'GROWING=' || lv_cnt_growing || ', ' ||
                         'SHRINKING=' || lv_cnt_shrinking || ', ' ||
                         'STABLE=' || lv_cnt_stable || ', ' ||
                         'UNKNOWN=' || lv_cnt_unknown);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      IF cur_years%ISOPEN THEN
        CLOSE cur_years;
      END IF;
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      IF cur_years%ISOPEN THEN
        CLOSE cur_years;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      IF cur_years%ISOPEN THEN
        CLOSE cur_years;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_country_pulse;

END demo_pulse_pkg;
/

CREATE OR REPLACE PROCEDURE report_circuits_last_race(
  p_country IN F1.CIRCUITS.country%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_last_race_year F1.RACES.year%TYPE;
  lv_rows_printed   PLS_INTEGER := 0;
BEGIN
  IF p_country IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Country is required.');
    RETURN;
  END IF;

  -- Process circuits one-by-one; for each, derive last race year (or NO RACE)
  FOR rec IN (
    SELECT c.circuit_id, c.name
      FROM F1.CIRCUITS c
     WHERE c.country = p_country
     ORDER BY c.name
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    lv_last_race_year := NULL;

    -- Determine latest race year for this circuit; if none, keep NULL
    SELECT MAX(r.year)
      INTO lv_last_race_year
      FROM F1.RACES r
     WHERE r.circuit_id = rec.circuit_id;

    IF lv_last_race_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('CIRCUIT: ' || rec.name || ' | LAST_RACE_YEAR: NO RACE');
    ELSE
      DBMS_OUTPUT.PUT_LINE('CIRCUIT: ' || rec.name || ' | LAST_RACE_YEAR: ' || lv_last_race_year);
    END IF;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    -- Use NO_DATA_FOUND as a controlled, business-friendly outcome
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No circuits found for country: ' || p_country);
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_circuits_last_race;
/

CREATE OR REPLACE PROCEDURE report_indicator_coverage(
  p_indicator_code IN WORLD_BANK_INTL_DEBT.SERIES_SUMMARY.series_code%TYPE,
  p_year           IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_indicator_name WORLD_BANK_INTL_DEBT.SERIES_SUMMARY.indicator_name%TYPE;
  lv_topic          WORLD_BANK_INTL_DEBT.SERIES_SUMMARY.topic%TYPE;
  lv_country_count  PLS_INTEGER;

  lv_year_num NUMBER;
  lv_rank     PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_indicator_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: indicator code is required.');
    RETURN;
  END IF;

  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year is required.');
    RETURN;
  END IF;

  -- Enforce a 4-digit year (stored as VARCHAR2 in the dataset)
  lv_year_num := TO_NUMBER(p_year);
  IF lv_year_num < 1000 OR lv_year_num > 9999 THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year must be a 4-digit number.');
    RETURN;
  END IF;

  -- Validate indicator exists and fetch metadata
  SELECT ss.indicator_name,
         ss.topic
    INTO lv_indicator_name,
         lv_topic
    FROM WORLD_BANK_INTL_DEBT.SERIES_SUMMARY ss
   WHERE ss.series_code = p_indicator_code;

  DBMS_OUTPUT.PUT_LINE('Indicator: ' || lv_indicator_name);
  DBMS_OUTPUT.PUT_LINE('Topic: ' || lv_topic);

  -- Coverage count for the requested year and indicator (numeric-only VALUE rows)
  SELECT COUNT(DISTINCT id.country_code)
    INTO lv_country_count
    FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
   WHERE id.indicator_code = p_indicator_code
     AND id.year = p_year
     AND REGEXP_LIKE(id.value, '^\s*[+-]?(\d+(\.\d+)?|\.\d+)\s*$');

  DBMS_OUTPUT.PUT_LINE('Countries with numeric values: ' || lv_country_count);
  DBMS_OUTPUT.PUT_LINE('Top ' || co_report_limit || ' countries by value:');

  -- Rank and print up to 15 countries with the largest numeric values
  FOR rec IN (
    WITH numeric_rows AS (
      SELECT id.country_name AS country_name,
             id.country_code AS country_code,
             TO_NUMBER(TRIM(id.value)) AS val_num
        FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
       WHERE id.indicator_code = p_indicator_code
         AND id.year = p_year
         AND REGEXP_LIKE(id.value, '^\s*[+-]?(\d+(\.\d+)?|\.\d+)\s*$')
    ),
    ranked AS (
      SELECT nr.country_name,
             nr.country_code,
             nr.val_num,
             ROW_NUMBER() OVER (ORDER BY nr.val_num DESC, nr.country_name ASC) AS rn
        FROM numeric_rows nr
    )
    SELECT r.country_name,
           r.country_code,
           r.val_num,
           r.rn
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn
  ) LOOP
    lv_rank := rec.rn;
    DBMS_OUTPUT.PUT_LINE(
      '  ' || LPAD(TO_CHAR(lv_rank), 2, ' ') || '. ' || rec.country_name ||
      ' (' || rec.country_code || '): ' || TO_CHAR(rec.val_num)
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year must be a 4-digit number.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_indicator_coverage;
/

DECLARE
  -- Limit output for report readability
  co_report_limit CONSTANT PLS_INTEGER := 15;

  lv_area_name  BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name  BLS.CPI_U.item_name%TYPE := 'All items';
  lv_start_year BLS.CPI_U.year%TYPE := '2020';
  lv_end_year   BLS.CPI_U.year%TYPE := '2021';

  lv_cpi_value NUMBER;
  lv_class     VARCHAR2(10);

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI spot-check report');
  DBMS_OUTPUT.PUT_LINE('Area=' || lv_area_name || ', Item=' || lv_item_name || ', Years=' || lv_start_year || '-' || lv_end_year);

  -- Validate year range (stored as VARCHAR2, compare numerically)
  IF TO_NUMBER(lv_start_year) > TO_NUMBER(lv_end_year) THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year range.');
    RETURN;
  END IF;

  -- Fetch and print up to co_report_limit monthly observations (M01..M12)
  FOR rec IN (
    SELECT c.year,
           c.period,
           c.value,
           c.c_date
      FROM BLS.CPI_U c
     WHERE c.area_name = lv_area_name
       AND c.item_name = lv_item_name
       AND TO_NUMBER(c.year) BETWEEN TO_NUMBER(lv_start_year) AND TO_NUMBER(lv_end_year)
       AND c.period LIKE 'M%'
       AND c.period <> 'M13'
     ORDER BY c.c_date
  ) LOOP
    lv_cpi_value := TO_NUMBER(rec.value);

    IF lv_cpi_value >= 300 THEN
      lv_class := 'HIGH';
    ELSIF lv_cpi_value >= 200 THEN
      lv_class := 'MEDIUM';
    ELSE
      lv_class := 'LOW';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Year=' || rec.year || ', Period=' || rec.period || ', CPI=' || TO_CHAR(lv_cpi_value) || ', Class=' || lv_class
    );

    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed >= co_report_limit;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

  -- Intentional single-row check to demonstrate TOO_MANY_ROWS handling for ambiguous filters.
  DECLARE
    lv_dummy BLS.CPI_U.series_id%TYPE;
  BEGIN
    SELECT c.series_id
      INTO lv_dummy
      FROM BLS.CPI_U c
     WHERE c.area_name = lv_area_name
       AND c.item_name = lv_item_name
       AND TO_NUMBER(c.year) BETWEEN TO_NUMBER(lv_start_year) AND TO_NUMBER(lv_end_year)
       AND c.period LIKE 'M%'
       AND c.period <> 'M13';
  END;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for the provided filters.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric data found in VALUE; cannot convert to number.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

