CREATE OR REPLACE PROCEDURE cpi_trend_report(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_item_name IN BLS.CPI_U.item_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  CURSOR c_cpi IS
    SELECT cu.c_date,
           cu.value
      FROM BLS.CPI_U cu
     WHERE (p_area_name IS NULL OR cu.area_name = p_area_name)
       AND (p_item_name IS NULL OR cu.item_name = p_item_name)
     ORDER BY cu.c_date DESC
     FETCH FIRST co_report_limit ROWS ONLY;

  lv_prev_value    NUMBER := NULL;
  lv_curr_value    NUMBER := NULL;
  lv_mom_change    NUMBER := NULL;
  lv_printed_rows  PLS_INTEGER := 0;
  lv_seen_rows     PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI Trend Report');
  DBMS_OUTPUT.PUT_LINE('Area=' || NVL(p_area_name, 'NULL') || ', Item=' || NVL(p_item_name, 'NULL'));

  FOR rec IN c_cpi LOOP
    lv_seen_rows := lv_seen_rows + 1;

    BEGIN
      -- VALUE is stored as text; convert defensively per row.
      lv_curr_value := TO_NUMBER(rec.value);
    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Skipping row due to non-numeric CPI value.');
        CONTINUE;
    END;

    IF lv_prev_value IS NULL THEN
      lv_mom_change := NULL;
    ELSE
      lv_mom_change := lv_curr_value - lv_prev_value;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Period=' || TO_CHAR(rec.c_date, 'YYYY-MM') ||
      ', Value=' || TO_CHAR(lv_curr_value) ||
      ', MoM_Change=' || TO_CHAR(lv_mom_change)
    );

    lv_printed_rows := lv_printed_rows + 1;
    lv_prev_value := lv_curr_value;
  END LOOP;

  IF lv_seen_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the given area/item filters.');
  END IF;

  DBMS_OUTPUT.PUT_LINE('Printed rows=' || TO_CHAR(lv_printed_rows));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_trend_report;
/

