CREATE OR REPLACE PROCEDURE report_cpi_u_value_alerts(
  p_area_name  IN BLS.CPI_U.area_name%TYPE,
  p_item_name  IN BLS.CPI_U.item_name%TYPE,
  p_year       IN BLS.CPI_U.year%TYPE,
  p_threshold  IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
  lv_val_num      NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI-U value alert report');
  DBMS_OUTPUT.PUT_LINE(
    'Area=' || NVL(p_area_name, 'NULL') ||
    ', Item=' || NVL(p_item_name, 'NULL') ||
    ', Year=' || NVL(p_year, 'NULL') ||
    ', Threshold=' || TO_CHAR(p_threshold)
  );

  -- Implicit cursor loop over matching CPI-U rows, limited to monthly periods.
  FOR rec IN (
    SELECT c.c_date,
           c.period,
           c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND c.year = p_year
       AND c.period LIKE 'M%'
     ORDER BY c.c_date
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    -- Convert VALUE to NUMBER; if conversion fails, skip the row.
    BEGIN
      lv_val_num := TO_NUMBER(rec.value);

      IF lv_val_num > p_threshold THEN
        DBMS_OUTPUT.PUT_LINE(
          'ALERT: ' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') ||
          ' Period=' || rec.period ||
          ' Value=' || rec.value
        );
      ELSE
        DBMS_OUTPUT.PUT_LINE(
          'OK: ' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') ||
          ' Period=' || rec.period ||
          ' Value=' || rec.value
        );
      END IF;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE(
          'SKIP (non-numeric VALUE): ' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') ||
          ' Period=' || rec.period ||
          ' Value=' || rec.value
        );
    END;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No CPI-U rows matched the inputs.');
    -- Ensure outer exception coverage includes NO_DATA_FOUND in a deterministic way.
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No CPI-U rows matched the inputs.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_cpi_u_value_alerts;
/

