BEGIN
  FOR rec IN (
    SELECT over_id,
           batsman_runs,
           extra_runs,
           (batsman_runs + extra_runs) AS total_runs,
           CASE
             WHEN (batsman_runs + extra_runs) >= 10 THEN 'HIGH'
             ELSE 'LOW'
           END AS over_band
      FROM (
        SELECT bs.over_id,
