CREATE OR REPLACE PROCEDURE report_cpi_mom(
  p_area_name  IN BLS.CPI_U.area_name%TYPE,
  p_item_name  IN BLS.CPI_U.item_name%TYPE,
  p_start_year IN BLS.CPI_U.year%TYPE,
  p_end_year   IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_area_name  BLS.CPI_U.area_name%TYPE;
  lv_item_name  BLS.CPI_U.item_name%TYPE;
  lv_start_year BLS.CPI_U.year%TYPE;
  lv_end_year   BLS.CPI_U.year%TYPE;

  lv_prev_val   NUMBER;
  lv_mom        NUMBER;
  lv_printed    PLS_INTEGER := 0;
BEGIN
  lv_start_year := p_start_year;
  lv_end_year   := p_end_year;

  -- If the range is reversed, swap it.
  IF lv_start_year IS NOT NULL
     AND lv_end_year IS NOT NULL
     AND lv_start_year > lv_end_year THEN
    DECLARE
      lv_tmp BLS.CPI_U.year%TYPE;
    BEGIN
      lv_tmp := lv_start_year;
      lv_start_year := lv_end_year;
      lv_end_year := lv_tmp;
    END;
  END IF;

  -- Default area/item to most common values if not provided.
  IF p_area_name IS NULL THEN
    SELECT area_name
      INTO lv_area_name
      FROM (
        SELECT c.area_name
          FROM BLS.CPI_U c
         GROUP BY c.area_name
         ORDER BY COUNT(*) DESC, c.area_name
      )
     WHERE ROWNUM = 1;
  ELSE
    lv_area_name := p_area_name;
  END IF;

  IF p_item_name IS NULL THEN
    SELECT item_name
      INTO lv_item_name
      FROM (
        SELECT c.item_name
          FROM BLS.CPI_U c
         GROUP BY c.item_name
         ORDER BY COUNT(*) DESC, c.item_name
      )
     WHERE ROWNUM = 1;
  ELSE
    lv_item_name := p_item_name;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI MoM report for Area="' || lv_area_name || '", Item="' || lv_item_name || '", Years ' || lv_start_year || '-' || lv_end_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('Year', 6) || RPAD('Period', 8) || LPAD('Value', 12) || LPAD('MoM', 12));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 6, '-') || RPAD('-', 8, '-') || LPAD('-', 12, '-') || LPAD('-', 12, '-'));

  lv_prev_val := NULL;

  FOR rec IN (
    WITH base AS (
      SELECT c.year,
             c.period,
             c.c_date,
             c.value
        FROM BLS.CPI_U c
       WHERE c.area_name = lv_area_name
         AND c.item_name = lv_item_name
         AND lv_start_year IS NOT NULL
         AND lv_end_year IS NOT NULL
         AND c.year BETWEEN lv_start_year AND lv_end_year
         AND c.period LIKE 'M%'
    ), ranked AS (
      SELECT b.year,
             b.period,
             b.c_date,
             b.value,
             ROW_NUMBER() OVER (ORDER BY b.c_date) AS rn
        FROM base b
    )
    SELECT r.year,
           r.period,
           r.c_date,
           r.value,
           LAG(r.value) OVER (ORDER BY r.c_date) AS prev_value
      FROM ranked r
     ORDER BY r.c_date
  ) LOOP
    EXIT WHEN lv_printed >= co_report_limit;

    -- Skip rows where VALUE cannot be converted to a number.
    BEGIN
      DECLARE
        lv_curr NUMBER;
        lv_prev NUMBER;
      BEGIN
        lv_curr := TO_NUMBER(rec.value);

        IF rec.prev_value IS NULL THEN
          lv_mom := NULL;
        ELSE
          lv_prev := TO_NUMBER(rec.prev_value);
          lv_mom := lv_curr - lv_prev;
        END IF;

        DBMS_OUTPUT.PUT_LINE(
          RPAD(rec.year, 6) ||
          RPAD(rec.period, 8) ||
          LPAD(TO_CHAR(lv_curr, 'FM9999990D00'), 12) ||
          LPAD(TO_CHAR(lv_mom, 'FM9999990D00'), 12)
        );

        lv_printed := lv_printed + 1;
      END;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        NULL;
    END;
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matching CPI data found for the requested filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching CPI data found for the requested filters.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric conversion encountered while processing CPI values.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_cpi_mom;
/

CREATE OR REPLACE PACKAGE pkg_stacking_health IS
  PROCEDURE report_model_health(
    p_name           IN STACKING.MODEL.name%TYPE,
    p_version        IN STACKING.MODEL.version%TYPE,
    p_min_test_score IN STACKING.MODEL_SCORE.test_score%TYPE
  );
END pkg_stacking_health;
/

CREATE OR REPLACE PACKAGE BODY pkg_stacking_health IS

  PROCEDURE report_model_health(
    p_name           IN STACKING.MODEL.name%TYPE,
    p_version        IN STACKING.MODEL.version%TYPE,
    p_min_test_score IN STACKING.MODEL_SCORE.test_score%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_models IS
      SELECT m.step,
             m.l1_model
        FROM STACKING.MODEL m
       WHERE m.name = p_name
         AND m.version = p_version
       ORDER BY m.step, m.l1_model
       FETCH FIRST co_report_limit ROWS ONLY;

    lv_step     STACKING.MODEL.step%TYPE;
    lv_l1_model STACKING.MODEL.l1_model%TYPE;

    lv_train_score STACKING.MODEL_SCORE.train_score%TYPE;
    lv_test_score  STACKING.MODEL_SCORE.test_score%TYPE;

    lv_status      VARCHAR2(20);
    lv_ok_cnt      PLS_INTEGER := 0;
    lv_low_cnt     PLS_INTEGER := 0;
    lv_missing_cnt PLS_INTEGER := 0;
  BEGIN
    IF p_name IS NULL OR p_version IS NULL OR p_min_test_score IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input validation failed: NAME, VERSION, and MIN_TEST_SCORE are required.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('MODEL HEALTH REPORT - NAME=' || p_name || ', VERSION=' || p_version || ', MIN_TEST_SCORE=' || p_min_test_score);

    OPEN c_models;
    LOOP
      FETCH c_models INTO lv_step, lv_l1_model;
      EXIT WHEN c_models%NOTFOUND;

      BEGIN
        SELECT ms.train_score,
               ms.test_score
          INTO lv_train_score,
               lv_test_score
          FROM STACKING.MODEL_SCORE ms
         WHERE ms.name = p_name
           AND ms.version = p_version
           AND ms.step = lv_step
           AND ms.model = lv_l1_model;

        IF lv_test_score >= p_min_test_score THEN
          lv_status := 'OK';
          lv_ok_cnt := lv_ok_cnt + 1;
        ELSE
          lv_status := 'LOW';
          lv_low_cnt := lv_low_cnt + 1;
        END IF;

        DBMS_OUTPUT.PUT_LINE('STEP=' || lv_step || ', L1_MODEL=' || lv_l1_model || ', TRAIN_SCORE=' || TO_CHAR(lv_train_score) || ', TEST_SCORE=' || TO_CHAR(lv_test_score) || ', STATUS=' || lv_status);

      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_missing_cnt := lv_missing_cnt + 1;
          DBMS_OUTPUT.PUT_LINE('STEP=' || lv_step || ', L1_MODEL=' || lv_l1_model || ', TRAIN_SCORE=NULL, TEST_SCORE=NULL, STATUS=MISSING');
      END;
    END LOOP;
    CLOSE c_models;

    DBMS_OUTPUT.PUT_LINE('TOTALS: OK=' || lv_ok_cnt || ', LOW=' || lv_low_cnt || ', MISSING=' || lv_missing_cnt);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      IF c_models%ISOPEN THEN
        CLOSE c_models;
      END IF;
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_model_health;

END pkg_stacking_health;
/

CREATE OR REPLACE PROCEDURE report_hospice_high_spend(
  p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
  lv_payment_num  NUMBER;
  lv_class        VARCHAR2(10);
BEGIN
  IF p_state IS NULL OR LENGTH(TRIM(p_state)) <> 2 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid state code.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Hospice high spend report for state=' || p_state);

  FOR rec IN (
    SELECT hp.provider_id,
           hp.name,
           hp.city,
           hp.total_medicare_payment_amount
      FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
     WHERE hp.state = TRIM(p_state)
       AND hp.total_medicare_payment_amount IS NOT NULL
     ORDER BY TO_NUMBER(REPLACE(hp.total_medicare_payment_amount, ',', '')) DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    lv_payment_num := TO_NUMBER(REPLACE(rec.total_medicare_payment_amount, ',', ''));

    IF lv_payment_num >= 10000000 THEN
      lv_class := 'HIGH';
    ELSE
      lv_class := 'NORMAL';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Provider=' || rec.provider_id ||
      ' Name=' || rec.name ||
      ' City=' || rec.city ||
      ' Payment=' || rec.total_medicare_payment_amount ||
      ' Class=' || lv_class
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No providers found for state=' || p_state);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_hospice_high_spend;
/

CREATE OR REPLACE PROCEDURE report_station_status(
  p_landmark IN SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_time  SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;
  lv_bikes SAN_FRANCISCO.BIKESHARE_STATUS.bikes_available%TYPE;
  lv_docks SAN_FRANCISCO.BIKESHARE_STATUS.docks_available%TYPE;

  lv_station_count PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_landmark IS NULL OR TRIM(p_landmark) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: landmark is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Landmark: ' || p_landmark);

  -- List up to 15 stations for the requested landmark
  FOR r_station IN (
    SELECT s.station_id, s.name
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
     WHERE s.landmark = p_landmark
     ORDER BY s.name
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_station_count := lv_station_count + 1;

    -- Latest status per station (single-row fetch using ORDER BY and FETCH FIRST 1)
    BEGIN
      SELECT st.time, st.bikes_available, st.docks_available
        INTO lv_time, lv_bikes, lv_docks
        FROM SAN_FRANCISCO.BIKESHARE_STATUS st
       WHERE st.station_id = r_station.station_id
       ORDER BY st.time DESC
       FETCH FIRST 1 ROWS ONLY;

      DBMS_OUTPUT.PUT_LINE(
        'Station: ' || r_station.name || ' (ID=' || r_station.station_id ||
        ') | Latest status time: ' || TO_CHAR(lv_time, 'YYYY-MM-DD HH24:MI:SS') ||
        ' | Bikes: ' || lv_bikes || ' | Docks: ' || lv_docks
      );
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Station: ' || r_station.name || ' (ID=' || r_station.station_id || ') | No status found.');
      WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    END;
  END LOOP;

  IF lv_station_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark: ' || p_landmark);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark: ' || p_landmark);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_station_status;
/

