question:
Your finance team wants a quick CPI spot-check report for a given metro area and CPI item. Build an anonymous PL/SQL block that:

 Validates the input year is numeric (YYYY) and the input month is between 1 and 12.
 Reads CPI-U data from BLS.CPI_U for the given area, item, year, and month.
 Prints up to 15 matching rows in descending date order, including the date, area name, item name, and CPI value.
 If no rows match, print a clear message; if multiple rows match unexpectedly, print a clear message; and always handle any other unexpected issue without crashing.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('CPI-U report for ' || lv_area_name || ' / ' || lv_item_name || ' (' || lv_year || '-' || lv_period || ')');
DBMS_OUTPUT.PUT_LINE('Report rows (max ' || co_report_limit || '):');
DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.c_date, 'YYYY-MM-DD') || ' | ' || rec.area_name || ' | ' || rec.item_name || ' | ' || rec.value);
DBMS_OUTPUT.PUT_LINE('No CPI-U rows matched the requested filters.');
DBMS_OUTPUT.PUT_LINE('Invalid input: year must be 4 digits and month must be between 1 and 12.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No CPI-U rows matched the requested filters.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  -- Inputs (set these as needed for the exercise)
  lv_area_name_filter BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name_filter BLS.CPI_U.item_name%TYPE := 'All items';
  lv_year            BLS.CPI_U.year%TYPE := '2020';
  lv_month           PLS_INTEGER := 1;

  lv_period          BLS.CPI_U.period%TYPE;

  -- Display values (picked from data after validation)
  lv_area_name BLS.CPI_U.area_name%TYPE;
  lv_item_name BLS.CPI_U.item_name%TYPE;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF LENGTH(lv_year) <> 4 OR TRANSLATE(lv_year, '0123456789', ' ') IS NOT NULL OR lv_month NOT BETWEEN 1 AND 12 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year must be 4 digits and month must be between 1 and 12.');
    RETURN;
  END IF;

  lv_period := 'M' || LPAD(lv_month, 2, '0');

  -- Confirm there is data and capture canonical labels (forces NO_DATA_FOUND when missing)
  SELECT MIN(c.area_name), MIN(c.item_name)
    INTO lv_area_name, lv_item_name
    FROM BLS.CPI_U c
   WHERE c.area_name = lv_area_name_filter
     AND c.item_name = lv_item_name_filter
     AND c.year = lv_year
     AND c.period = lv_period;

  DBMS_OUTPUT.PUT_LINE('CPI-U report for ' || lv_area_name || ' / ' || lv_item_name || ' (' || lv_year || '-' || lv_period || ')');
  DBMS_OUTPUT.PUT_LINE('Report rows (max ' || co_report_limit || '):');

  FOR rec IN (
    SELECT c.c_date,
           c.area_name,
           c.item_name,
           c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = lv_area_name_filter
       AND c.item_name = lv_item_name_filter
       AND c.year = lv_year
       AND c.period = lv_period
     ORDER BY c.c_date DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.c_date, 'YYYY-MM-DD') || ' | ' || rec.area_name || ' | ' || rec.item_name || ' | ' || rec.value);
  END LOOP;

  -- Defensive: should not happen if the MIN(...) SELECT succeeded, but keeps behavior explicit.
  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No CPI-U rows matched the requested filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No CPI-U rows matched the requested filters.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

