CREATE OR REPLACE PROCEDURE alien_compliance_report(
  p_country IN CITY_LEGISLATION.ALIEN_DATA.country%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_total_aliens      NUMBER;
  lv_aggressive_aliens NUMBER;
BEGIN
  -- Guard clause for missing input
  IF p_country IS NULL OR TRIM(p_country) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input country is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Alien Compliance Report - Country: ' || p_country);

  -- Summary counts first (also ensures NO_DATA_FOUND can be raised intentionally)
  SELECT COUNT(*),
         SUM(CASE WHEN a.aggressive = 1 THEN 1 ELSE 0 END)
    INTO lv_total_aliens,
         lv_aggressive_aliens
    FROM CITY_LEGISLATION.ALIEN_DATA a
   WHERE a.country = p_country;

  IF lv_total_aliens = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

  -- Detail lines: aggressive first, then older within group
  FOR rec IN (
    SELECT *
      FROM (
        SELECT a.first_name,
               a.last_name,
               a.type,
               a.age,
               a.aggressive,
               a.current_location,
               a.state
          FROM CITY_LEGISLATION.ALIEN_DATA a
         WHERE a.country = p_country
         ORDER BY a.aggressive DESC, a.age DESC, a.last_name, a.first_name
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'Name: ' || rec.first_name || ' ' || rec.last_name ||
      ' | Type: ' || rec.type ||
      ' | Age: ' || rec.age ||
      ' | Aggressive: ' || rec.aggressive ||
      ' | Location: ' || rec.current_location || ', ' || rec.state
    );
  END LOOP;

  DBMS_OUTPUT.PUT_LINE(
    'Summary - Total aliens: ' || lv_total_aliens ||
    ' | Aggressive aliens: ' || lv_aggressive_aliens
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No aliens found for the specified country.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END alien_compliance_report;
/

