CREATE OR REPLACE PROCEDURE report_match_batting_impact(
  p_match_id    IN IPL.MATCH.match_id%TYPE,
  p_innings_no  IN IPL.BALL_BY_BALL.innings_no%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_delivery_cnt NUMBER;
  lv_player_name  IPL.PLAYER.player_name%TYPE;
  lv_strike_rate  NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Batting impact report for match_id=' || p_match_id || ', innings_no=' || p_innings_no);
  DBMS_OUTPUT.PUT_LINE(RPAD('Player', 35) || ' ' || LPAD('Runs', 6) || ' ' || LPAD('Balls', 6) || ' ' || LPAD('SR', 8));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || ' ' || LPAD('-', 6, '-') || ' ' || LPAD('-', 6, '-') || ' ' || LPAD('-', 8, '-'));

  -- Check if the match/innings has any deliveries before printing detail lines.
  SELECT COUNT(*)
    INTO lv_delivery_cnt
    FROM IPL.BALL_BY_BALL b
   WHERE b.match_id = p_match_id
     AND b.innings_no = p_innings_no;

  IF lv_delivery_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No deliveries found for the given match/innings.');
    DBMS_OUTPUT.PUT_LINE('End of report.');
    RETURN;
  END IF;

  -- Summarize by striker. Use a ranking query to reliably cap output at co_report_limit.
  FOR rec IN (
    WITH batter_base AS (
      SELECT b.striker AS player_id,
             SUM(s.runs_scored) AS total_runs,
             COUNT(*) AS balls_faced
        FROM IPL.BALL_BY_BALL b
        INNER JOIN IPL.BATSMAN_SCORED s
          ON s.match_id = b.match_id
         AND s.innings_no = b.innings_no
         AND s.over_id = b.over_id
         AND s.ball_id = b.ball_id
       WHERE b.match_id = p_match_id
         AND b.innings_no = p_innings_no
       GROUP BY b.striker
    ),
    batter_ranked AS (
      SELECT bb.player_id,
             bb.total_runs,
             bb.balls_faced,
             ROW_NUMBER() OVER (ORDER BY bb.total_runs DESC, bb.balls_faced ASC, bb.player_id ASC) AS rn
        FROM batter_base bb
    )
    SELECT br.player_id,
           br.total_runs,
           br.balls_faced
      FROM batter_ranked br
     WHERE br.rn <= co_report_limit
     ORDER BY br.total_runs DESC, br.balls_faced ASC, br.player_id ASC
  ) LOOP
    -- Lookup player name; default to a placeholder if the player dimension is incomplete.
    BEGIN
      SELECT p.player_name
        INTO lv_player_name
        FROM IPL.PLAYER p
       WHERE p.player_id = rec.player_id;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        lv_player_name := 'UNKNOWN';
      WHEN TOO_MANY_ROWS THEN
        lv_player_name := 'UNKNOWN';
      WHEN OTHERS THEN
        lv_player_name := 'UNKNOWN';
    END;

    -- Strike rate: handle safety even though balls_faced should be > 0.
    lv_strike_rate := (rec.total_runs / NULLIF(rec.balls_faced, 0)) * 100;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(lv_player_name, 35) || ' ' ||
      LPAD(rec.total_runs, 6) || ' ' ||
      LPAD(rec.balls_faced, 6) || ' ' ||
      LPAD(TO_CHAR(lv_strike_rate, 'FM9990D00'), 8)
    );
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('End of report.');

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN ZERO_DIVIDE THEN
    DBMS_OUTPUT.PUT_LINE('Divide by zero encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_match_batting_impact;
/

CREATE OR REPLACE PROCEDURE report_channel_sales(
  p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
  p_channel_id    IN COMPLEX_ORACLE.CHANNELS.channel_id%TYPE DEFAULT NULL
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Channel performance snapshot');
  DBMS_OUTPUT.PUT_LINE(
    'Year=' || p_calendar_year || ', Channel_ID=' || NVL(TO_CHAR(p_channel_id), 'ALL')
  );

  IF p_calendar_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Year must be provided.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('Channel', 25) || 'Total_Amount');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 6, '-') || RPAD('-', 25, '-') || RPAD('-', 12, '-'));

  FOR rec IN (
    WITH chan_totals AS (
      SELECT ch.channel_desc AS channel_desc,
             SUM(s.amount_sold) AS total_amount
        FROM COMPLEX_ORACLE.SALES s
        INNER JOIN COMPLEX_ORACLE.TIMES t
          ON t.time_id = s.time_id
        INNER JOIN COMPLEX_ORACLE.CHANNELS ch
          ON ch.channel_id = s.channel_id
       WHERE t.calendar_year = p_calendar_year
         AND (p_channel_id IS NULL OR s.channel_id = p_channel_id)
       GROUP BY ch.channel_desc
    )
    SELECT channel_desc,
           total_amount,
           ROW_NUMBER() OVER (ORDER BY total_amount DESC) AS rn
      FROM chan_totals
     WHERE ROWNUM <= co_report_limit
     ORDER BY rn
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(rec.rn), 6) ||
      RPAD(SUBSTR(rec.channel_desc, 1, 24), 25) ||
      TO_CHAR(rec.total_amount)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the given filters.');
    RETURN;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the given filters.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_channel_sales;
/

CREATE OR REPLACE PROCEDURE btc_daily_member_report(
  p_member_id IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.member_id%TYPE,
  p_txn_date  IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.txn_date%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_first_name BANK_SALES_TRADING.BITCOIN_MEMBERS.first_name%TYPE;
  lv_region     BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE;

  lv_txn_count   PLS_INTEGER := 0;
  lv_buy_qty     BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.quantity%TYPE := 0;
  lv_sell_qty    BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.quantity%TYPE := 0;
  lv_total_fees  NUMBER := 0;
  lv_fee_amt     NUMBER;
  lv_rows_printed PLS_INTEGER := 0;

  CURSOR c_txns IS
    SELECT t.txn_id,
           t.txn_time,
           t.txn_type,
           t.quantity,
           t.percentage_fee
      FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
     WHERE t.member_id = p_member_id
       AND t.txn_date  = p_txn_date
     ORDER BY t.txn_time, t.txn_id;

  rec c_txns%ROWTYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Report for MEMBER_ID=' || p_member_id || ' on TXN_DATE=' || p_txn_date);

  -- Validate member exists (and fetch display attributes)
  SELECT m.first_name, m.region
    INTO lv_first_name, lv_region
    FROM BANK_SALES_TRADING.BITCOIN_MEMBERS m
   WHERE m.member_id = p_member_id;

  DBMS_OUTPUT.PUT_LINE('Member: ' || lv_first_name || ' (Region=' || lv_region || ')');

  OPEN c_txns;
  LOOP
    FETCH c_txns INTO rec;
    EXIT WHEN c_txns%NOTFOUND;

    lv_txn_count := lv_txn_count + 1;

    -- Fee amount: quantity * percentage_fee / 100
    lv_fee_amt := NVL(rec.quantity, 0) * NVL(rec.percentage_fee, 0) / 100;
    lv_total_fees := lv_total_fees + lv_fee_amt;

    IF rec.txn_type = 'BUY' THEN
      lv_buy_qty := lv_buy_qty + NVL(rec.quantity, 0);
    ELSIF rec.txn_type = 'SELL' THEN
      lv_sell_qty := lv_sell_qty + NVL(rec.quantity, 0);
    END IF;

    IF lv_rows_printed < co_report_limit THEN
      DBMS_OUTPUT.PUT_LINE(
        'TXN_ID=' || rec.txn_id ||
        ' TIME=' || rec.txn_time ||
        ' TYPE=' || rec.txn_type ||
        ' QTY=' || TO_CHAR(rec.quantity) ||
        ' FEE%=' || TO_CHAR(rec.percentage_fee) ||
        ' FEE_AMT=' || TO_CHAR(lv_fee_amt)
      );
      lv_rows_printed := lv_rows_printed + 1;
    END IF;
  END LOOP;
  CLOSE c_txns;

  IF lv_txn_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No transactions found for the requested member/date.');
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Summary: TXN_COUNT=' || TO_CHAR(lv_txn_count) ||
    ' BUY_QTY=' || TO_CHAR(lv_buy_qty) ||
    ' SELL_QTY=' || TO_CHAR(lv_sell_qty) ||
    ' TOTAL_FEES=' || TO_CHAR(lv_total_fees)
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    -- Raised by member validation SELECT when member_id does not exist.
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input format.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END btc_daily_member_report;
/

