CREATE OR REPLACE PROCEDURE wdi_print_recent_indicator(
  p_country_code   IN WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE,
  p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF TRIM(p_country_code) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input rejected: country code is required.');
    RETURN;
  END IF;

  IF TRIM(p_indicator_code) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input rejected: indicator code is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Country=' || p_country_code || ', Indicator=' || p_indicator_code);

  -- Print up to the most recent N observations
  FOR rec IN (
    SELECT d.year, d.value
      FROM WORLD_BANK_WDI.INDICATORS_DATA d
     WHERE d.country_code = p_country_code
       AND d.indicator_code = p_indicator_code
     ORDER BY TO_NUMBER(d.year) DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE('Year=' || rec.year || ', Value=' || rec.value);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found for Country=' || p_country_code || ', Indicator=' || p_indicator_code);
  END IF;

EXCEPTION
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END wdi_print_recent_indicator;
/

question:
The operations team wants a quick “region health” report they can run in SQL*Plus. Build a reusable PL/SQL package that prints a small, row-limited report for a given region name: list up to 15 stations in that region with their current available bikes and docks, plus a simple utilization classification (LOW / MEDIUM / HIGH) based on (bikes_available / capacity). The package should also print a region-level summary (station count, total capacity, total bikes available, and average utilization). 

Use an explicit cursor (not an inline SELECT loop) to iterate the station rows, and make sure you safely handle data quality problems such as non-numeric CAPACITY or status fields stored as text. Also handle a bad region name (no matches) gracefully.

Requirements:
Procedure Name: bikeshare_ops_pkg.print_region_health
Parameters:
p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Region: ' || p_region_name);
DBMS_OUTPUT.PUT_LINE('Stations found: ' || lv_station_count);
DBMS_OUTPUT.PUT_LINE('Total capacity: ' || lv_total_capacity);
DBMS_OUTPUT.PUT_LINE('Total bikes available: ' || lv_total_bikes);
DBMS_OUTPUT.PUT_LINE('Average utilization: ' || TO_CHAR(lv_avg_utilization * 100, 'FM999990D00') || '%');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 78, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD('Station', 40) || ' ' || LPAD('Bikes', 5) || ' ' || LPAD('Docks', 5) || ' ' || LPAD('Cap', 5) || ' ' || RPAD('Util', 8) || ' ' || 'Class');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 78, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(lv_station_name, 40) || ' ' || LPAD(lv_bikes_txt, 5) || ' ' || LPAD(lv_docks_txt, 5) || ' ' || LPAD(lv_cap_txt, 5) || ' ' || LPAD(lv_util_txt, 8) || ' ' || lv_class);
DBMS_OUTPUT.PUT_LINE('No station status rows found for region.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN INVALID_NUMBER THEN: 'Invalid numeric data encountered.'
WHEN OTHERS THEN: 'Unexpected error.'

