CREATE OR REPLACE PACKAGE bikeshare_ops_pkg IS
  PROCEDURE print_region_health(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
  );
END bikeshare_ops_pkg;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_ops_pkg IS
  PROCEDURE print_region_health(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_region_id       SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;

    lv_station_count   PLS_INTEGER := 0;
    lv_total_capacity  NUMBER := 0;
    lv_total_bikes     NUMBER := 0;
    lv_avg_utilization NUMBER := 0;

    lv_station_name    SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
    lv_cap_txt         SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.capacity%TYPE;
    lv_bikes_txt       SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE;
    lv_docks_txt       SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_docks_available%TYPE;
    lv_cap_num         NUMBER;
    lv_bikes_num       NUMBER;
    lv_util            NUMBER;
    lv_util_txt        VARCHAR2(30);
    lv_class           VARCHAR2(10);

    lv_status_rows     PLS_INTEGER := 0;

    CURSOR c_station_status(p_region_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE) IS
      WITH ranked AS (
        SELECT
          si.name AS station_name,
          si.capacity AS cap_txt,
          ss.num_bikes_available AS bikes_txt,
          ss.num_docks_available AS docks_txt,
          ROW_NUMBER() OVER (ORDER BY si.name) AS rn
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
          ON ss.station_id = si.station_id
        WHERE si.region_id = p_region_id
      )
      SELECT
        ranked.station_name,
        ranked.cap_txt,
        ranked.bikes_txt,
        ranked.docks_txt
      FROM ranked
      WHERE ranked.rn <= co_report_limit
      ORDER BY ranked.station_name;

  BEGIN
    -- Resolve region name to region_id; treat a bad region name as no data.
    SELECT r.region_id
      INTO lv_region_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE r.name = p_region_name;

    -- Region-level summary across all stations in the region (not row-limited).
    SELECT
      COUNT(*),
      SUM(TO_NUMBER(si.capacity)),
      SUM(TO_NUMBER(ss.num_bikes_available)),
      AVG(TO_NUMBER(ss.num_bikes_available) / NULLIF(TO_NUMBER(si.capacity), 0))
      INTO
      lv_station_count,
      lv_total_capacity,
      lv_total_bikes,
      lv_avg_utilization
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
        ON ss.station_id = si.station_id
     WHERE si.region_id = lv_region_id;

    DBMS_OUTPUT.PUT_LINE('Region: ' || p_region_name);
    DBMS_OUTPUT.PUT_LINE('Stations found: ' || lv_station_count);
    DBMS_OUTPUT.PUT_LINE('Total capacity: ' || lv_total_capacity);
    DBMS_OUTPUT.PUT_LINE('Total bikes available: ' || lv_total_bikes);
    DBMS_OUTPUT.PUT_LINE('Average utilization: ' || TO_CHAR(lv_avg_utilization * 100, 'FM999990D00') || '%');

    DBMS_OUTPUT.PUT_LINE(RPAD('-', 78, '-'));
    DBMS_OUTPUT.PUT_LINE(RPAD('Station', 40) || ' ' || LPAD('Bikes', 5) || ' ' || LPAD('Docks', 5) || ' ' || LPAD('Cap', 5) || ' ' || RPAD('Util', 8) || ' ' || 'Class');
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 78, '-'));

    FOR rec IN c_station_status(lv_region_id) LOOP
      lv_status_rows := lv_status_rows + 1;

      lv_station_name := rec.station_name;
      lv_cap_txt      := rec.cap_txt;
      lv_bikes_txt    := rec.bikes_txt;
      lv_docks_txt    := rec.docks_txt;

      -- Convert text fields safely; surface issues via INVALID_NUMBER handler.
      lv_cap_num   := TO_NUMBER(lv_cap_txt);
      lv_bikes_num := TO_NUMBER(lv_bikes_txt);

      IF lv_cap_num <= 0 THEN
        lv_util := 0;
      ELSE
        lv_util := lv_bikes_num / lv_cap_num;
      END IF;

      IF lv_util < 0.25 THEN
        lv_class := 'LOW';
      ELSIF lv_util < 0.75 THEN
        lv_class := 'MEDIUM';
      ELSE
        lv_class := 'HIGH';
      END IF;

      lv_util_txt := TO_CHAR(lv_util * 100, 'FM999990D00') || '%';

      DBMS_OUTPUT.PUT_LINE(
        RPAD(lv_station_name, 40) || ' ' ||
        LPAD(lv_bikes_txt, 5) || ' ' ||
        LPAD(lv_docks_txt, 5) || ' ' ||
        LPAD(lv_cap_txt, 5) || ' ' ||
        LPAD(lv_util_txt, 8) || ' ' ||
        lv_class
      );
    END LOOP;

    IF lv_status_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No station status rows found for region.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN INVALID_NUMBER THEN
      DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_region_health;
END bikeshare_ops_pkg;
/

