DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_product_id   ORACLE_SQL.PRODUCTS.id%TYPE := 1;
  lv_product_name ORACLE_SQL.PRODUCTS.name%TYPE;

  lv_status       VARCHAR2(20);
  lv_total_budget NUMBER := 0;
  lv_total_sales  NUMBER := 0;

  CURSOR cur_mth(p_product_id IN ORACLE_SQL.PRODUCTS.id%TYPE) IS
    WITH mths AS (
      SELECT mb.mth
        FROM ORACLE_SQL.MONTHLY_BUDGET mb
       WHERE mb.product_id = p_product_id
      UNION
      SELECT ms.mth
        FROM ORACLE_SQL.MONTHLY_SALES ms
       WHERE ms.product_id = p_product_id
    )
    SELECT x.mth,
           mb.qty AS budget_qty,
           ms.qty AS sales_qty
      FROM (
            SELECT mths.mth,
                   ROW_NUMBER() OVER (ORDER BY mths.mth) AS rn
              FROM mths
           ) x
      LEFT OUTER JOIN ORACLE_SQL.MONTHLY_BUDGET mb
        ON mb.product_id = p_product_id
       AND mb.mth = x.mth
      LEFT OUTER JOIN ORACLE_SQL.MONTHLY_SALES ms
        ON ms.product_id = p_product_id
       AND ms.mth = x.mth
     WHERE x.rn <= co_report_limit
     ORDER BY x.mth;
BEGIN
  SELECT p.name
    INTO lv_product_name
    FROM ORACLE_SQL.PRODUCTS p
   WHERE p.id = lv_product_id;

  DBMS_OUTPUT.PUT_LINE('Product: ' || lv_product_id || ' - ' || lv_product_name);

  FOR rec IN cur_mth(lv_product_id) LOOP
    IF rec.budget_qty IS NULL AND rec.sales_qty IS NOT NULL THEN
      lv_status := 'NO_BUDGET';
    ELSIF rec.budget_qty IS NOT NULL AND rec.sales_qty IS NULL THEN
      lv_status := 'NO_SALES';
    ELSIF rec.budget_qty IS NOT NULL AND rec.sales_qty IS NOT NULL AND rec.sales_qty > rec.budget_qty THEN
      lv_status := 'OVER_BUDGET';
    ELSE
      lv_status := 'OK';
    END IF;

    lv_total_budget := lv_total_budget + NVL(rec.budget_qty, 0);
    lv_total_sales  := lv_total_sales + NVL(rec.sales_qty, 0);

    DBMS_OUTPUT.PUT_LINE('Month: ' || rec.mth || ' | Budget: ' || rec.budget_qty || ' | Sales: ' || rec.sales_qty || ' | Status: ' || lv_status);
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('TOTAL | Budget: ' || lv_total_budget || ' | Sales: ' || lv_total_sales);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

