CREATE OR REPLACE PROCEDURE route_flight_report(
  p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE,
  p_arrival_airport   IN AIRLINES.FLIGHTS.arrival_airport%TYPE,
  p_from_ts           IN AIRLINES.FLIGHTS.scheduled_departure%TYPE,
  p_to_ts             IN AIRLINES.FLIGHTS.scheduled_departure%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_departure_airport IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: departure airport is required.');
    RETURN;
  ELSIF p_arrival_airport IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: arrival airport is required.');
    RETURN;
  ELSIF p_from_ts IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: from timestamp is required.');
    RETURN;
  ELSIF p_to_ts IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: to timestamp is required.');
    RETURN;
  ELSIF p_from_ts > p_to_ts THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: from timestamp must be <= to timestamp.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Route report: ' || p_departure_airport || ' -> ' || p_arrival_airport);
  DBMS_OUTPUT.PUT_LINE(
    'Window: ' || TO_CHAR(p_from_ts, 'YYYY-MM-DD HH24:MI') ||
    ' to ' || TO_CHAR(p_to_ts, 'YYYY-MM-DD HH24:MI')
  );

  FOR r IN (
    SELECT
      f.flight_no,
      f.scheduled_departure,
      f.actual_departure,
      f.status,
      CASE
        WHEN f.actual_departure IS NULL THEN 'No actual departure yet'
        WHEN f.actual_departure <= f.scheduled_departure THEN 'On time'
        ELSE 'Delayed'
      END AS punctuality
    FROM AIRLINES.FLIGHTS f
    WHERE f.departure_airport = p_departure_airport
      AND f.arrival_airport = p_arrival_airport
      AND f.scheduled_departure >= p_from_ts
      AND f.scheduled_departure <= p_to_ts
    ORDER BY f.scheduled_departure
    FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      'Flight ' || r.flight_no ||
      ' | Sched: ' || TO_CHAR(r.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
      ' | Actual: ' || CASE
                        WHEN r.actual_departure IS NULL THEN 'N/A'
                        ELSE TO_CHAR(r.actual_departure, 'YYYY-MM-DD HH24:MI')
                      END ||
      ' | Status: ' || r.status ||
      ' | Punctuality: ' || r.punctuality
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No flights found for this route/window.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END route_flight_report;
/

