CREATE OR REPLACE PROCEDURE report_member_activity(
  p_member_id IN BANK_SALES_TRADING.BITCOIN_MEMBERS.member_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_first_name BANK_SALES_TRADING.BITCOIN_MEMBERS.first_name%TYPE;
  lv_region     BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE;

  lv_txn_count  PLS_INTEGER := 0;
BEGIN
  -- Treat NULL as "not found" for this routine.
  IF p_member_id IS NULL THEN
    RAISE NO_DATA_FOUND;
  END IF;

  -- Fetch member profile (expect exactly one row).
  SELECT m.first_name,
         m.region
    INTO lv_first_name,
         lv_region
    FROM BANK_SALES_TRADING.BITCOIN_MEMBERS m
   WHERE m.member_id = p_member_id;

  DBMS_OUTPUT.PUT_LINE('Member: ' || lv_first_name || ' (' || lv_region || ')');

  -- Print up to 15 most recent transactions.
  FOR rec IN (
    SELECT t.txn_id,
           t.txn_date,
           t.txn_type,
           t.ticker,
           t.quantity,
           t.percentage_fee
      FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
     WHERE t.member_id = p_member_id
     ORDER BY t.txn_date DESC, t.txn_id DESC
  ) LOOP
    EXIT WHEN lv_txn_count >= co_report_limit;
    lv_txn_count := lv_txn_count + 1;

    DBMS_OUTPUT.PUT_LINE(
      'Txn ' || rec.txn_id || ' | ' || rec.txn_date || ' | ' || rec.txn_type ||
      ' | ' || rec.ticker || ' | qty=' || rec.quantity || ' | fee%=' || rec.percentage_fee
    );
  END LOOP;

  IF lv_txn_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No transactions found for this member.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_member_activity;
/

CREATE OR REPLACE PACKAGE pkg_bikeshare_ops IS
  PROCEDURE print_station_trip_snapshot(
    p_start_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_station_id%TYPE
  );
END pkg_bikeshare_ops;
/

CREATE OR REPLACE PACKAGE BODY pkg_bikeshare_ops IS

  PROCEDURE print_station_trip_snapshot(
    p_start_station_id IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS.start_station_id%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 10; -- Limit printed rows for report readability
    co_window_days  CONSTANT PLS_INTEGER := 30; -- Lookback window for "recent" trips

    lv_start_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
    lv_region_name        SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
    lv_rows_printed       PLS_INTEGER := 0;

    CURSOR cur_top_end_stations IS
      WITH end_stats AS (
        SELECT
          t.end_station_id,
          t.end_station_name,
          COUNT(*) AS trip_cnt,
          AVG(TO_NUMBER(t.duration_sec) / 60) AS avg_minutes
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_TRIPS t
        WHERE t.start_station_id = p_start_station_id
          AND t.start_date >= SYSTIMESTAMP - co_window_days
          AND t.end_station_id IS NOT NULL
          AND t.end_station_name IS NOT NULL
        GROUP BY t.end_station_id, t.end_station_name
      ), ranked AS (
        SELECT
          es.end_station_id,
          es.end_station_name,
          es.trip_cnt,
          es.avg_minutes,
          ROW_NUMBER() OVER (ORDER BY es.trip_cnt DESC, es.end_station_name ASC) AS rnk
        FROM end_stats es
      )
      SELECT
        r.end_station_id,
        r.end_station_name,
        r.trip_cnt,
        r.avg_minutes,
        r.rnk
      FROM ranked r
      WHERE r.rnk <= co_report_limit
      ORDER BY r.rnk;

  BEGIN
    DBMS_OUTPUT.PUT_LINE('Trip snapshot for start_station_id=' || p_start_station_id);

    IF p_start_station_id IS NULL OR TRIM(p_start_station_id) IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input: start station id is required.');
      RETURN;
    END IF;

    BEGIN
      SELECT
        si.name,
        r.name
      INTO
        lv_start_station_name,
        lv_region_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      LEFT OUTER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
        ON r.region_id = si.region_id
      WHERE si.station_id = p_start_station_id;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No station info found for start station id.');
        RETURN;
      WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
        RETURN;
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
        RETURN;
    END;

    DBMS_OUTPUT.PUT_LINE('Start station: ' || lv_start_station_name || ' | Region: ' || lv_region_name);
    DBMS_OUTPUT.PUT_LINE('Window days: ' || co_window_days || ' | Max rows: ' || co_report_limit);

    FOR rec IN cur_top_end_stations LOOP
      lv_rows_printed := lv_rows_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        'Rank ' || rec.rnk || ': end_station=' || rec.end_station_name || ' (id=' || rec.end_station_id || '), trips=' || rec.trip_cnt || ', avg_min=' || TO_CHAR(rec.avg_minutes, 'FM9990D00')
      );

      IF lv_rows_printed >= co_report_limit THEN
        EXIT;
      END IF;
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No trips found in the selected window for this start station.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_station_trip_snapshot;

END pkg_bikeshare_ops;
/

question:
Create an anonymous PL/SQL report used by the city compliance team to review alien records for a given country. The script should accept a country code (2-letter code stored in ALIEN_DATA.country), print a header, then list up to 15 matching alien profiles ordered by most recent birth year first (treat higher birth_year as more recent). For each returned alien, output their full name, email, type, age, occupation, current location, state, favorite food, and whether they are flagged aggressive.

Add control-flow logic so that if the input country is NULL or blank, the script prints a clear message and stops cleanly. Also compute and print a small summary at the end: total aliens found for that country, number aggressive, and percent aggressive (rounded to 1 decimal). If no rows match, print a "no records" message instead of an empty list.

Make sure the block is resilient: handle NO_DATA_FOUND, TOO_MANY_ROWS, and any unexpected errors without allowing an exception to propagate to the client.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('ALIEN COMPLIANCE REPORT');
DBMS_OUTPUT.PUT_LINE('Country filter: ' || lv_country);
DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
DBMS_OUTPUT.PUT_LINE('Invalid input: country must be provided.');
DBMS_OUTPUT.PUT_LINE(RPAD('Name', 25) || ' | ' || RPAD('Email', 25) || ' | ' || RPAD('Type', 10) || ' | ' || RPAD('Age', 3) || ' | ' || RPAD('Agg', 3));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 25, '-') || '-+-' || RPAD('-', 25, '-') || '-+-' || RPAD('-', 10, '-') || '-+-' || RPAD('-', 3, '-') || '-+-' || RPAD('-', 3, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(lv_name, 25) || ' | ' || RPAD(NVL(rec.email, 'UNKNOWN'), 25) || ' | ' || RPAD(NVL(rec.type, 'UNKNOWN'), 10) || ' | ' || RPAD(TO_CHAR(rec.age), 3) || ' | ' || RPAD(lv_agg_txt, 3));
DBMS_OUTPUT.PUT_LINE('    Occupation: ' || NVL(rec.occupation, 'UNKNOWN'));
DBMS_OUTPUT.PUT_LINE('    Location:   ' || NVL(rec.current_location, 'UNKNOWN') || ', ' || NVL(rec.state, 'UNKNOWN'));
DBMS_OUTPUT.PUT_LINE('    Food/Freq:  ' || NVL(rec.favorite_food, 'UNKNOWN') || ' / ' || NVL(rec.feeding_frequency, 'UNKNOWN'));
DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
DBMS_OUTPUT.PUT_LINE('No alien records found for the given country.');
DBMS_OUTPUT.PUT_LINE('Summary - Total: ' || TO_CHAR(lv_total) || ', Aggressive: ' || TO_CHAR(lv_aggressive) || ', Agg%: ' || TO_CHAR(lv_aggressive_pct, 'FM9990.0'));
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country         CITY_LEGISLATION.ALIEN_DATA.country%TYPE := 'US';
  lv_total           NUMBER := 0;
  lv_aggressive      NUMBER := 0;
  lv_aggressive_pct  NUMBER := 0;

  lv_name     VARCHAR2(4000);
  lv_agg_txt  VARCHAR2(3);
BEGIN
  DBMS_OUTPUT.PUT_LINE('ALIEN COMPLIANCE REPORT');
  DBMS_OUTPUT.PUT_LINE('Country filter: ' || lv_country);
  DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');

  IF lv_country IS NULL OR TRIM(lv_country) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: country must be provided.');
    RETURN;
  END IF;

  SELECT COUNT(*),
         SUM(CASE WHEN ad.aggressive = 1 THEN 1 ELSE 0 END)
    INTO lv_total, lv_aggressive
    FROM CITY_LEGISLATION.ALIEN_DATA ad
   WHERE ad.country = lv_country;

  IF lv_total = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No alien records found for the given country.');
    RETURN;
  END IF;

  lv_aggressive_pct := ROUND((lv_aggressive / lv_total) * 100, 1);

  DBMS_OUTPUT.PUT_LINE(RPAD('Name', 25) || ' | ' || RPAD('Email', 25) || ' | ' || RPAD('Type', 10) || ' | ' || RPAD('Age', 3) || ' | ' || RPAD('Agg', 3));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 25, '-') || '-+-' || RPAD('-', 25, '-') || '-+-' || RPAD('-', 10, '-') || '-+-' || RPAD('-', 3, '-') || '-+-' || RPAD('-', 3, '-'));

  FOR rec IN (
    SELECT ad.first_name,
           ad.last_name,
           ad.email,
           ad.type,
           ad.age,
           ad.occupation,
           ad.current_location,
           ad.state,
           ad.favorite_food,
           ad.feeding_frequency,
           ad.aggressive
      FROM CITY_LEGISLATION.ALIEN_DATA ad
     WHERE ad.country = lv_country
     ORDER BY ad.birth_year DESC NULLS LAST
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_name := TRIM(NVL(rec.first_name, '') || ' ' || NVL(rec.last_name, ''));

    IF rec.aggressive = 1 THEN
      lv_agg_txt := 'YES';
    ELSE
      lv_agg_txt := 'NO';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(lv_name, 25) || ' | ' ||
      RPAD(NVL(rec.email, 'UNKNOWN'), 25) || ' | ' ||
      RPAD(NVL(rec.type, 'UNKNOWN'), 10) || ' | ' ||
      RPAD(TO_CHAR(rec.age), 3) || ' | ' ||
      RPAD(lv_agg_txt, 3)
    );
    DBMS_OUTPUT.PUT_LINE('    Occupation: ' || NVL(rec.occupation, 'UNKNOWN'));
    DBMS_OUTPUT.PUT_LINE('    Location:   ' || NVL(rec.current_location, 'UNKNOWN') || ', ' || NVL(rec.state, 'UNKNOWN'));
    DBMS_OUTPUT.PUT_LINE('    Food/Freq:  ' || NVL(rec.favorite_food, 'UNKNOWN') || ' / ' || NVL(rec.feeding_frequency, 'UNKNOWN'));
    DBMS_OUTPUT.PUT_LINE('--------------------------------------------------');
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Summary - Total: ' || TO_CHAR(lv_total) || ', Aggressive: ' || TO_CHAR(lv_aggressive) || ', Agg%: ' || TO_CHAR(lv_aggressive_pct, 'FM9990.0'));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

