question:
Your trading desk wants a reusable routine to produce a short, operator-friendly report of recent member activity.

Build a stored procedure that, for a given member region and a date range, prints up to 15 members from that region with their total number of trades, total quantity traded, and a simple activity band (HIGH/MEDIUM/LOW) based on trade count. Use control flow to derive the activity band. Make sure the procedure is resilient: handle missing inputs, empty result sets, and unexpected issues without throwing runtime errors.

Requirements:
Procedure Name: report_region_member_activity
Parameters:
p_region IN BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE
p_start_date IN VARCHAR2
p_end_date IN VARCHAR2
Output:
DBMS_OUTPUT.PUT_LINE('Region activity report');
DBMS_OUTPUT.PUT_LINE('Region=' || NVL(p_region, 'NULL') || ', Start=' || NVL(p_start_date, 'NULL') || ', End=' || NVL(p_end_date, 'NULL'));
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE(rpad('MEMBER_ID', 20) || rpad('NAME', 18) || lpad('TRADES', 8) || lpad('QTY', 12) || '  BAND');
DBMS_OUTPUT.PUT_LINE(rpad('-', 20, '-') || rpad('-', 18, '-') || lpad('-', 8, '-') || lpad('-', 12, '-') || '  ' || rpad('-', 8, '-'));
DBMS_OUTPUT.PUT_LINE(rpad(rec.member_id, 20) || rpad(substr(rec.first_name, 1, 17), 18) || lpad(to_char(rec.trade_cnt), 8) || lpad(to_char(rec.total_qty), 12) || '  ' || rec.activity_band);
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_region_member_activity(
  p_region     IN BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE,
  p_start_date IN VARCHAR2,
  p_end_date   IN VARCHAR2
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_start_date DATE;
  lv_end_date   DATE;

  lv_region_cnt NUMBER;
  lv_rows_printed PLS_INTEGER := 0;

  lv_debug_member_id BANK_SALES_TRADING.BITCOIN_MEMBERS.member_id%TYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Region activity report');
  DBMS_OUTPUT.PUT_LINE('Region=' || NVL(p_region, 'NULL') || ', Start=' || NVL(p_start_date, 'NULL') || ', End=' || NVL(p_end_date, 'NULL'));

  -- Basic parameter validation
  IF p_region IS NULL OR p_start_date IS NULL OR p_end_date IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  -- Date parsing from inbound strings
  lv_start_date := TO_DATE(p_start_date, 'YYYY-MM-DD');
  lv_end_date   := TO_DATE(p_end_date, 'YYYY-MM-DD');

  IF lv_end_date < lv_start_date THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  -- Confirm region exists (single-row expected)
  SELECT COUNT(*)
    INTO lv_region_cnt
    FROM BANK_SALES_TRADING.BITCOIN_MEMBERS bm
   WHERE bm.region = p_region;

  IF lv_region_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE(rpad('MEMBER_ID', 20) || rpad('NAME', 18) || lpad('TRADES', 8) || lpad('QTY', 12) || '  BAND');
  DBMS_OUTPUT.PUT_LINE(rpad('-', 20, '-') || rpad('-', 18, '-') || lpad('-', 8, '-') || lpad('-', 12, '-') || '  ' || rpad('-', 8, '-'));

  -- Row-limited summary by member (implicit cursor FOR loop; no explicit cursor usage)
  FOR rec IN (
    WITH member_trade_summary AS (
      SELECT bm.member_id,
             bm.first_name,
             COUNT(*) AS trade_cnt,
             SUM(bt.quantity) AS total_qty
        FROM BANK_SALES_TRADING.BITCOIN_MEMBERS bm
        JOIN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS bt
          ON bt.member_id = bm.member_id
       WHERE bm.region = p_region
         AND TO_DATE(bt.txn_date, 'YYYY-MM-DD') BETWEEN lv_start_date AND lv_end_date
       GROUP BY bm.member_id, bm.first_name
    )
    SELECT mts.member_id,
           mts.first_name,
           mts.trade_cnt,
           mts.total_qty,
           CASE
             WHEN mts.trade_cnt >= 10 THEN 'HIGH'
             WHEN mts.trade_cnt >= 5 THEN 'MEDIUM'
             ELSE 'LOW'
           END AS activity_band
      FROM member_trade_summary mts
     ORDER BY mts.trade_cnt DESC, mts.total_qty DESC, mts.member_id
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    lv_debug_member_id := rec.member_id;

    DBMS_OUTPUT.PUT_LINE(
      rpad(rec.member_id, 20) ||
      rpad(substr(rec.first_name, 1, 17), 18) ||
      lpad(to_char(rec.trade_cnt), 8) ||
      lpad(to_char(rec.total_qty), 12) ||
      '  ' || rec.activity_band
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_member_activity;
/

