CREATE OR REPLACE PROCEDURE report_model_gap(
  p_name          IN STACKING.MODEL_SCORE.name%TYPE,
  p_version       IN STACKING.MODEL_SCORE.version%TYPE,
  p_gap_threshold IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_row_count PLS_INTEGER := 0;
  lv_status    VARCHAR2(20);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Model Gap Report for ' || p_name || ' v' || p_version);

  -- Validate inputs early to avoid confusing results.
  IF p_name IS NULL OR p_version IS NULL OR p_gap_threshold IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  -- Data retrieval + control flow classification.
  FOR rec IN (
    SELECT ms.model,
           ms.train_score,
           ms.test_score,
           (ms.train_score - ms.test_score) AS gap
      FROM STACKING.MODEL_SCORE ms
     WHERE ms.name = p_name
       AND ms.version = p_version
     ORDER BY ms.test_score DESC, ms.model
  ) LOOP
    EXIT WHEN lv_row_count >= co_report_limit;

    lv_row_count := lv_row_count + 1;

    IF rec.gap > p_gap_threshold THEN
      lv_status := 'OVERFIT';
    ELSE
      lv_status := 'OK';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Model=' || rec.model ||
      ', Train=' || TO_CHAR(rec.train_score) ||
      ', Test=' || TO_CHAR(rec.test_score) ||
      ', Gap=' || TO_CHAR(rec.gap) ||
      ', Status=' || lv_status
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    -- Standardize the “no rows” behavior via NO_DATA_FOUND.
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_model_gap;
/

