CREATE OR REPLACE PROCEDURE report_long_deliveries(
  p_hub_city               IN DELIVERY_CENTER.HUBS.hub_city%TYPE,
  p_distance_threshold_m   IN DELIVERY_CENTER.DELIVERIES.delivery_distance_meters%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed   PLS_INTEGER := 0;
  lv_exceed_count   PLS_INTEGER := 0;
  lv_city_present   PLS_INTEGER := 0;
BEGIN
  -- Validate that the city exists in HUBS (keeps "no data" behavior deterministic)
  SELECT COUNT(*)
    INTO lv_city_present
    FROM DELIVERY_CENTER.HUBS h
   WHERE h.hub_city = p_hub_city;

  IF lv_city_present = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top deliveries for city=' || p_hub_city || ' (limit=' || co_report_limit || '):');

  -- Inline FOR loop (implicit cursor) to report deliveries for the city.
  FOR r IN (
    SELECT *
      FROM (
        SELECT h.hub_name,
               s.store_name,
               o.order_id,
               d.driver_id,
               d.delivery_status,
               d.delivery_distance_meters
          FROM DELIVERY_CENTER.HUBS h
          INNER JOIN DELIVERY_CENTER.STORES s
            ON s.hub_id = h.hub_id
          INNER JOIN DELIVERY_CENTER.ORDERS o
            ON o.store_id = s.store_id
          INNER JOIN DELIVERY_CENTER.DELIVERIES d
            ON d.delivery_order_id = o.delivery_order_id
         WHERE h.hub_city = p_hub_city
           AND d.delivery_distance_meters IS NOT NULL
         ORDER BY d.delivery_distance_meters DESC, o.order_id
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      'HUB=' || r.hub_name ||
      ' | STORE=' || r.store_name ||
      ' | ORDER_ID=' || r.order_id ||
      ' | DRIVER_ID=' || r.driver_id ||
      ' | STATUS=' || r.delivery_status ||
      ' | DIST_M=' || r.delivery_distance_meters
    );

    IF r.delivery_distance_meters > p_distance_threshold_m THEN
      lv_exceed_count := lv_exceed_count + 1;
    END IF;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    -- City exists, but no matching deliveries/orders.
    RAISE NO_DATA_FOUND;
  END IF;

  IF lv_exceed_count > 0 THEN
    DBMS_OUTPUT.PUT_LINE('ALERT: ' || lv_exceed_count || ' of ' || lv_rows_printed ||
                         ' deliveries exceed threshold ' || p_distance_threshold_m || ' meters.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('OK: No deliveries exceed threshold ' || p_distance_threshold_m ||
                         ' meters (rows=' || lv_rows_printed || ').');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No deliveries found for the provided city.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_long_deliveries;
/

