question:
Build a reusable procedure that prints a small report of Home Health Agencies for a given US state. The report should show up to 15 agencies in that state, sorted by agency name. For each agency, print the provider id, agency name, city, and the average age (if present). While printing, also keep a running count of how many agencies were printed and a count of how many had a missing average age value.

Make the procedure robust:
If the caller passes NULL or a non-2-character state code, print a clear message and stop.
If there are no agencies for the state, print a clear message.
Ensure unexpected errors are caught and reported.

Requirements:
Procedure Name: report_hha_by_state
Parameters:
p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Invalid state input. Provide a 2-character state code.');
DBMS_OUTPUT.PUT_LINE('HHA report for state=' || p_state);
DBMS_OUTPUT.PUT_LINE('Provider=' || rec.provider_id || ' | Agency=' || rec.agency_name || ' | City=' || rec.city || ' | AvgAge=' || NVL(rec.average_age, 'N/A'));
DBMS_OUTPUT.PUT_LINE('Total agencies printed=' || lv_printed_cnt);
DBMS_OUTPUT.PUT_LINE('Agencies with missing average age=' || lv_missing_age_cnt);
DBMS_OUTPUT.PUT_LINE('No agencies found for state=' || p_state);
Exception Handling:
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_hha_by_state(
  p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_printed_cnt     PLS_INTEGER := 0;
  lv_missing_age_cnt PLS_INTEGER := 0;
BEGIN
  IF p_state IS NULL OR LENGTH(p_state) <> 2 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid state input. Provide a 2-character state code.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('HHA report for state=' || p_state);

  FOR rec IN (
    SELECT hha.provider_id,
           hha.agency_name,
           hha.city,
           hha.average_age
      FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
     WHERE hha.state = p_state
     ORDER BY hha.agency_name
  ) LOOP
    EXIT WHEN lv_printed_cnt >= co_report_limit;

    lv_printed_cnt := lv_printed_cnt + 1;

    IF rec.average_age IS NULL THEN
      lv_missing_age_cnt := lv_missing_age_cnt + 1;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Provider=' || rec.provider_id ||
      ' | Agency=' || rec.agency_name ||
      ' | City=' || rec.city ||
      ' | AvgAge=' || NVL(rec.average_age, 'N/A')
    );
  END LOOP;

  IF lv_printed_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No agencies found for state=' || p_state);
  ELSE
    DBMS_OUTPUT.PUT_LINE('Total agencies printed=' || lv_printed_cnt);
    DBMS_OUTPUT.PUT_LINE('Agencies with missing average age=' || lv_missing_age_cnt);
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_hha_by_state;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country  CITY_LEGISLATION.ALIEN_DATA.country%TYPE;
  lv_age_text VARCHAR2(30);
  lv_status   VARCHAR2(10);

  CURSOR cur_aliens_by_country(p_country CITY_LEGISLATION.ALIEN_DATA.country%TYPE) IS
    SELECT ad.id,
           ad.first_name,
           ad.last_name,
           ad.occupation,
           ad.age,
           ad.aggressive
      FROM CITY_LEGISLATION.ALIEN_DATA ad
     WHERE ad.country = p_country
     ORDER BY ad.last_name, ad.first_name, ad.id;

  lv_rec          cur_aliens_by_country%ROWTYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Choose the most common country as the report focus.
  SELECT country
    INTO lv_country
    FROM (
          SELECT ad.country
            FROM CITY_LEGISLATION.ALIEN_DATA ad
           WHERE ad.country IS NOT NULL
           GROUP BY ad.country
           ORDER BY COUNT(*) DESC, ad.country
         )
   WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Country chosen: ' || lv_country);

  OPEN cur_aliens_by_country(lv_country);
  LOOP
    FETCH cur_aliens_by_country INTO lv_rec;
    EXIT WHEN cur_aliens_by_country%NOTFOUND;

    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    IF lv_rec.aggressive = 1 THEN
      lv_status := 'RISK';
    ELSE
      lv_status := 'OK';
    END IF;

    IF lv_rec.age IS NULL THEN
      lv_age_text := 'UNKNOWN';
    ELSE
      lv_age_text := TO_CHAR(lv_rec.age);
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(lv_rows_printed) || ') ' ||
      lv_rec.last_name || ', ' || lv_rec.first_name || ' (ID=' || lv_rec.id || ') - ' ||
      'OCCUPATION=' || lv_rec.occupation || ', ' ||
      'AGE=' || lv_age_text || ', ' ||
      'STATUS=' || lv_status
    );
  END LOOP;

  IF cur_aliens_by_country%ISOPEN THEN
    CLOSE cur_aliens_by_country;
  END IF;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF cur_aliens_by_country%ISOPEN THEN
      CLOSE cur_aliens_by_country;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF cur_aliens_by_country%ISOPEN THEN
      CLOSE cur_aliens_by_country;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF cur_aliens_by_country%ISOPEN THEN
      CLOSE cur_aliens_by_country;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

