CREATE OR REPLACE PROCEDURE report_station_top_destinations(
  p_start_station_name IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_station_name%TYPE,
  p_from_ts            IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE,
  p_to_ts              IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_station_name  SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE;
  lv_rank          PLS_INTEGER := 0;
  lv_rows_printed  PLS_INTEGER := 0;

  CURSOR c_top_destinations(
    p_station_name IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_station_name%TYPE,
    p_from         IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE,
    p_to           IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_date%TYPE
  ) IS
    WITH ranked_dest AS (
      SELECT
        t.end_station_name AS end_station_name,
        COUNT(*) AS trip_cnt,
        AVG(TO_NUMBER(t.duration_sec)) / 60 AS avg_minutes,
        ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC, t.end_station_name) AS rn
      FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
      WHERE t.start_station_name = p_station_name
        AND t.start_date >= p_from
        AND t.start_date <= p_to
      GROUP BY t.end_station_name
    )
    SELECT
      rd.end_station_name,
      rd.trip_cnt,
      rd.avg_minutes
    FROM ranked_dest rd
    WHERE rd.rn <= co_report_limit
    ORDER BY rd.rn;

BEGIN
  -- Input validation
  IF p_start_station_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: start station name is required.');
    RETURN;
  END IF;

  IF p_from_ts IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: from timestamp is required.');
    RETURN;
  END IF;

  IF p_to_ts IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: to timestamp is required.');
    RETURN;
  END IF;

  IF p_from_ts > p_to_ts THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: from timestamp must be less than or equal to to timestamp.');
    RETURN;
  END IF;

  -- Validate station exists in master data
  SELECT s.name
    INTO lv_station_name
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
   WHERE s.name = p_start_station_name;

  DBMS_OUTPUT.PUT_LINE('Start station: ' || p_start_station_name);
  DBMS_OUTPUT.PUT_LINE('Date range: ' || TO_CHAR(p_from_ts, 'YYYY-MM-DD HH24:MI:SS') || ' to ' || TO_CHAR(p_to_ts, 'YYYY-MM-DD HH24:MI:SS'));
  DBMS_OUTPUT.PUT_LINE('Top destinations (max ' || co_report_limit || '):');

  FOR r_dest IN c_top_destinations(p_start_station_name, p_from_ts, p_to_ts) LOOP
    lv_rank := lv_rank + 1;
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      '  ' || LPAD(lv_rank, 2, ' ') || '. ' || r_dest.end_station_name ||
      ' | trips=' || r_dest.trip_cnt ||
      ' | avg_minutes=' || TO_CHAR(r_dest.avg_minutes, 'FM9990D00')
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No destinations found for the given filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_station_top_destinations;
/

