DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_email       CHINOOK.CUSTOMERS.email%TYPE := 'test@chinook.com';
  lv_customer_id CHINOOK.CUSTOMERS.customerid%TYPE;

  lv_first_name  CHINOOK.CUSTOMERS.firstname%TYPE;
  lv_last_name   CHINOOK.CUSTOMERS.lastname%TYPE;
  lv_country     CHINOOK.CUSTOMERS.country%TYPE;

  lv_invoice_count NUMBER;
  lv_grand_total  NUMBER;
BEGIN
  -- Basic input guard (NULL or blank)
  IF lv_email IS NULL OR TRIM(lv_email) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Email is required.');
    RETURN;
  END IF;

  -- Resolve customer by email (expects exactly one match)
  SELECT c.customerid, c.firstname, c.lastname, c.country
    INTO lv_customer_id, lv_first_name, lv_last_name, lv_country
    FROM CHINOOK.CUSTOMERS c
   WHERE c.email = lv_email;

  -- Aggregate invoice summary
  SELECT COUNT(*), NVL(SUM(i.total), 0)
    INTO lv_invoice_count, lv_grand_total
    FROM CHINOOK.INVOICES i
   WHERE i.customerid = lv_customer_id;

  DBMS_OUTPUT.PUT_LINE('Customer: ' || lv_first_name || ' ' || lv_last_name || ' | Country: ' || lv_country);
  DBMS_OUTPUT.PUT_LINE('Invoice count: ' || lv_invoice_count || ' | Grand total: ' || lv_grand_total);
  DBMS_OUTPUT.PUT_LINE('Recent invoices (most recent first):');

  -- List up to N most recent invoices
  FOR rec IN (
    SELECT *
      FROM (
        SELECT i.invoiceid, i.invoicedate, i.total
          FROM CHINOOK.INVOICES i
         WHERE i.customerid = lv_customer_id
         ORDER BY i.invoicedate DESC, i.invoiceid DESC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'InvoiceId=' || rec.invoiceid ||
      ' | InvoiceDate=' || TO_CHAR(rec.invoicedate, 'YYYY-MM-DD') ||
      ' | Total=' || rec.total
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

