reference_answer:
CREATE OR REPLACE PROCEDURE report_country_debt_snapshot(
  p_country_code IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.country_code%TYPE,
  p_year         IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_country_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country code is required.');
    RETURN;
  END IF;

  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Debt snapshot for country_code=' || p_country_code || ', year=' || p_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 60, '-'));

  -- Report up to N indicators for the country/year
  FOR rec IN (
    SELECT d.indicator_name,
           d.value
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
     WHERE d.country_code = p_country_code
       AND d.year = p_year
     ORDER BY d.indicator_name
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(RPAD(rec.indicator_name, 45) || ' ' || rec.value);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

  DBMS_OUTPUT.PUT_LINE('Rows printed: ' || lv_rows_printed);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_debt_snapshot;
/

question:
As a debt reporting analyst, you need a small PL/SQL script that produces a quick “debt indicator snapshot” for a single country and year.

Use the country’s short name to find its country code, then list up to 15 debt indicators for the requested year ordered by numeric debt value (highest first). Since the debt VALUE column is stored as text, safely convert it to a number and skip rows that can’t be converted.

While printing the report, also compute:
total numeric value across the printed indicators
 how many indicators were skipped due to non-numeric VALUE

If the country short name is ambiguous (multiple country codes), treat it as an error and print a clear message. If the country doesn’t exist or there are no debt rows for that year, print a clear message.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output:
DBMS_OUTPUT.PUT_LINE('Debt indicator snapshot');
DBMS_OUTPUT.PUT_LINE('Country: ' || lv_short_name || ' (code=' || lv_country_code || '), Year=' || lv_year);
DBMS_OUTPUT.PUT_LINE(RPAD('Indicator', 60) || ' | ' || LPAD('Value', 20));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 60, '-') || '-+-' || RPAD('-', 20, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.indicator_name, 60) || ' | ' || LPAD(TO_CHAR(rec.value_num), 20));
DBMS_OUTPUT.PUT_LINE('---');
DBMS_OUTPUT.PUT_LINE('Printed indicators: ' || lv_printed_cnt);
DBMS_OUTPUT.PUT_LINE('Skipped (non-numeric VALUE): ' || lv_skipped_cnt);
DBMS_OUTPUT.PUT_LINE('Total of printed numeric values: ' || TO_CHAR(lv_total_value));
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_short_name   WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.short_name%TYPE := 'India';
  lv_year         WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE := '2019';
  lv_country_code WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.country_code%TYPE;

  lv_total_value  NUMBER := 0;
  lv_printed_cnt  PLS_INTEGER := 0;
  lv_skipped_cnt  PLS_INTEGER := 0;

  CURSOR cur_debt_indicators(
    p_country_code WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.country_code%TYPE,
    p_year         WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
  ) IS
    WITH debt_rows AS (
      SELECT
        idt.indicator_name,
        CASE
          WHEN REGEXP_LIKE(TRIM(idt.value), '^[+-]?([0-9]+(\.[0-9]+)?|\.[0-9]+)$')
            THEN TO_NUMBER(TRIM(idt.value))
          ELSE NULL
        END AS value_num,
        CASE
          WHEN REGEXP_LIKE(TRIM(idt.value), '^[+-]?([0-9]+(\.[0-9]+)?|\.[0-9]+)$')
            THEN 0
          ELSE 1
        END AS is_bad
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT idt
      WHERE idt.country_code = p_country_code
        AND idt.year = p_year
    ),
    ranked AS (
      SELECT
        dr.indicator_name,
        dr.value_num,
        dr.is_bad,
        ROW_NUMBER() OVER (ORDER BY dr.value_num DESC NULLS LAST, dr.indicator_name) AS rn
      FROM debt_rows dr
    )
    SELECT
      r.indicator_name,
      r.value_num,
      r.is_bad
    FROM ranked r
    WHERE r.rn <= co_report_limit
    ORDER BY r.rn;

  TYPE t_ind_rec IS RECORD (
    indicator_name WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_name%TYPE,
    value_num      NUMBER,
    is_bad         NUMBER
  );

  lr_ind t_ind_rec;

  lv_has_any_rows BOOLEAN := FALSE;
BEGIN
  -- Lookup country code from short name; treat multiple matches as ambiguity.
  SELECT cs.country_code
    INTO lv_country_code
    FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
   WHERE cs.short_name = lv_short_name;

  DBMS_OUTPUT.PUT_LINE('Debt indicator snapshot');
  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_short_name || ' (code=' || lv_country_code || '), Year=' || lv_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('Indicator', 60) || ' | ' || LPAD('Value', 20));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 60, '-') || '-+-' || RPAD('-', 20, '-'));

  OPEN cur_debt_indicators(lv_country_code, lv_year);
  LOOP
    FETCH cur_debt_indicators INTO lr_ind;
    EXIT WHEN cur_debt_indicators%NOTFOUND;

    lv_has_any_rows := TRUE;

    IF lr_ind.is_bad = 1 OR lr_ind.value_num IS NULL THEN
      lv_skipped_cnt := lv_skipped_cnt + 1;
      CONTINUE;
    END IF;

    lv_printed_cnt := lv_printed_cnt + 1;
    lv_total_value := lv_total_value + lr_ind.value_num;

    DBMS_OUTPUT.PUT_LINE(RPAD(lr_ind.indicator_name, 60) || ' | ' || LPAD(TO_CHAR(lr_ind.value_num), 20));
  END LOOP;
  CLOSE cur_debt_indicators;

  IF NOT lv_has_any_rows THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('---');
  DBMS_OUTPUT.PUT_LINE('Printed indicators: ' || lv_printed_cnt);
  DBMS_OUTPUT.PUT_LINE('Skipped (non-numeric VALUE): ' || lv_skipped_cnt);
  DBMS_OUTPUT.PUT_LINE('Total of printed numeric values: ' || TO_CHAR(lv_total_value));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    -- Ensure all unexpected exceptions are captured and reported.
    BEGIN
      IF cur_debt_indicators%ISOPEN THEN
        CLOSE cur_debt_indicators;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;

    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

