CREATE OR REPLACE PACKAGE natality_reporting_pkg IS
  PROCEDURE print_county_maternal_profile(
    p_year       IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_min_births IN NUMBER
  );
END natality_reporting_pkg;
/

CREATE OR REPLACE PACKAGE BODY natality_reporting_pkg IS

  PROCEDURE print_county_maternal_profile(
    p_year       IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    p_min_births IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_counties IS
      SELECT cn.county_of_residence,
             cn.county_of_residence_fips,
             cn.births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
       ORDER BY TO_NUMBER(cn.births DEFAULT NULL ON CONVERSION ERROR) DESC NULLS LAST;

    lv_births               NUMBER;
    lv_abnormal_yes_births  NUMBER;
    lv_morbidity_yes_births NUMBER;
    lv_abnormal_rate        NUMBER;
    lv_morbidity_rate       NUMBER;

    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE(
      'County maternal profile for year=' || TO_CHAR(p_year, 'YYYY') || ', min_births=' || TO_CHAR(p_min_births)
    );

    FOR rec IN c_counties LOOP
      EXIT WHEN lv_rows_printed >= co_report_limit;

      -- Convert births safely from VARCHAR2.
      lv_births := TO_NUMBER(rec.births DEFAULT NULL ON CONVERSION ERROR);

      IF lv_births IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Skipping county=' || rec.county_of_residence || ' because births is non-numeric.');
        CONTINUE;
      ELSIF lv_births = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Skipping county=' || rec.county_of_residence || ' because births=0.');
        CONTINUE;
      ELSIF p_min_births IS NOT NULL AND lv_births < p_min_births THEN
        CONTINUE;
      END IF;

      -- Pull "Yes" births from abnormal conditions for the same year+county.
      SELECT SUM(TO_NUMBER(ac.births DEFAULT 0 ON CONVERSION ERROR))
        INTO lv_abnormal_yes_births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_ABNORMAL_CONDITIONS ac
       WHERE ac.year = p_year
         AND ac.county_of_residence_fips = rec.county_of_residence_fips
         AND ac.abnormal_conditions_checked_yn = 'Yes';

      -- Pull "Yes" births from maternal morbidity for the same year+county.
      SELECT SUM(TO_NUMBER(mm.births DEFAULT 0 ON CONVERSION ERROR))
        INTO lv_morbidity_yes_births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_MATERNAL_MORBIDITY mm
       WHERE mm.year = p_year
         AND mm.county_of_residence_fips = rec.county_of_residence_fips
         AND mm.maternal_morbidity_yn = 'Yes';

      lv_abnormal_rate  := lv_abnormal_yes_births / lv_births;
      lv_morbidity_rate := lv_morbidity_yes_births / lv_births;

      DBMS_OUTPUT.PUT_LINE(
        'County=' || rec.county_of_residence ||
        ' | births=' || TO_CHAR(lv_births) ||
        ' | abnormal_yes_births=' || TO_CHAR(lv_abnormal_yes_births) ||
        ' | abnormal_rate=' || TO_CHAR(lv_abnormal_rate, 'FM0.0000') ||
        ' | morbidity_yes_births=' || TO_CHAR(lv_morbidity_yes_births) ||
        ' | morbidity_rate=' || TO_CHAR(lv_morbidity_rate, 'FM0.0000')
      );

      lv_rows_printed := lv_rows_printed + 1;
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_county_maternal_profile;

END natality_reporting_pkg;
/

