DECLARE
  -- Parameters for the report
  lv_country_name  CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.country_name%TYPE := 'United States';
  lv_start_year    CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE := '2010';
  lv_end_year      CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES.year%TYPE := '2015';

  co_report_limit  CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  -- Counters
  lv_printed       PLS_INTEGER := 0;
  lv_skipped       PLS_INTEGER := 0;

  -- Working variables (numeric conversions)
  lv_cbr           NUMBER;
  lv_cdr           NUMBER;
  lv_rni           NUMBER;
  lv_gr            NUMBER;
  lv_rni_minus_gr  NUMBER;
  lv_life_exp      NUMBER;

  -- Explicit cursor: pull rate rows in range; oldest to newest
  CURSOR cur_rates IS
    SELECT b.year,
           b.crude_birth_rate,
           b.crude_death_rate,
           b.rate_natural_increase,
           b.growth_rate
      FROM CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES b
     WHERE b.country_name = lv_country_name
       AND b.year BETWEEN lv_start_year AND lv_end_year
     ORDER BY b.year;

  -- Used to raise NO_DATA_FOUND if nothing was printed
  lv_any_row_seen  BOOLEAN := FALSE;
BEGIN
  -- Validate year range (VARCHAR2 years; lexical compare is safe for 4-digit years)
  IF lv_start_year > lv_end_year THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year range.');
    RETURN;
  END IF;

  FOR r_rates IN cur_rates LOOP
    lv_any_row_seen := TRUE;

    EXIT WHEN lv_printed >= co_report_limit;

    BEGIN
      -- Convert “stringly typed” numeric values; conversion errors skip this year
      lv_cbr := TO_NUMBER(r_rates.crude_birth_rate);
      lv_cdr := TO_NUMBER(r_rates.crude_death_rate);
      lv_rni := TO_NUMBER(r_rates.rate_natural_increase);
      lv_gr  := TO_NUMBER(r_rates.growth_rate);

      lv_rni_minus_gr := lv_rni - lv_gr;

      -- Join-in life expectancy for the same country/year (also stringly typed)
      SELECT TO_NUMBER(m.life_expectancy)
        INTO lv_life_exp
        FROM CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m
       WHERE m.country_name = lv_country_name
         AND m.year = r_rates.year;

      DBMS_OUTPUT.PUT_LINE('YEAR=' || r_rates.year ||
                           ' CBR=' || TO_CHAR(lv_cbr) ||
                           ' CDR=' || TO_CHAR(lv_cdr) ||
                           ' RNI=' || TO_CHAR(lv_rni) ||
                           ' GR=' || TO_CHAR(lv_gr) ||
                           ' RNI_MINUS_GR=' || TO_CHAR(lv_rni_minus_gr) ||
                           ' LIFE_EXP=' || TO_CHAR(lv_life_exp));

      lv_printed := lv_printed + 1;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        lv_skipped := lv_skipped + 1;
        DBMS_OUTPUT.PUT_LINE('Skipped year due to bad numeric data: ' || r_rates.year);
      WHEN INVALID_NUMBER THEN
        lv_skipped := lv_skipped + 1;
        DBMS_OUTPUT.PUT_LINE('Skipped year due to bad numeric data: ' || r_rates.year);
      WHEN NO_DATA_FOUND THEN
        -- Missing life expectancy for this year; treat as bad row
        lv_skipped := lv_skipped + 1;
        DBMS_OUTPUT.PUT_LINE('Skipped year due to bad numeric data: ' || r_rates.year);
    END;
  END LOOP;

  IF NOT lv_any_row_seen THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Summary: printed_years=' || TO_CHAR(lv_printed) || ' skipped_bad_rows=' || TO_CHAR(lv_skipped));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

