question:
Operations wants a reusable routine to quickly assess bike availability by region. Build a package that returns the “health snapshot” for a given region name: it should  find the region_id, count how many stations belong to that region, compute totals of bikes and docks currently available by joining station info to the latest station status data available and classify the region as GREEN / AMBER / RED based on the average bikes available per station (>= 8 is GREEN, >= 3 is AMBER, else RED). 

If the region name is NULL or blank, the routine must not query the tables and should print a clear message.

Make sure the routine never throws an unhandled error: handle NO_DATA_FOUND when the region name is not found, TOO_MANY_ROWS if the name matches multiple region rows, and a catch-all OTHERS handler.

Requirements:
Procedure Name: bikeshare_ops_pkg.report_region_health
Parameters:
p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Region name is required.');
DBMS_OUTPUT.PUT_LINE('Region: ' || p_region_name);
DBMS_OUTPUT.PUT_LINE('Stations: ' || lv_station_cnt);
DBMS_OUTPUT.PUT_LINE('Bikes available: ' || lv_bikes_available);
DBMS_OUTPUT.PUT_LINE('Docks available: ' || lv_docks_available);
DBMS_OUTPUT.PUT_LINE('Avg bikes per station: ' || TO_CHAR(lv_avg_bikes_per_station, 'FM999990D00'));
DBMS_OUTPUT.PUT_LINE('Health: ' || lv_health);
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE bikeshare_ops_pkg IS
  PROCEDURE report_region_health(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
  );
END bikeshare_ops_pkg;
/

CREATE OR REPLACE PACKAGE BODY bikeshare_ops_pkg IS

  PROCEDURE report_region_health(
    p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
  ) IS

    lv_region_id              SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
    lv_station_cnt            PLS_INTEGER := 0;
    lv_bikes_available        NUMBER := 0;
    lv_docks_available        NUMBER := 0;
    lv_avg_bikes_per_station  NUMBER := 0;
    lv_health                 VARCHAR2(10);
  BEGIN
    -- Guard clause: do not query when the input is not usable.
    IF p_region_name IS NULL OR TRIM(p_region_name) IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Region name is required.');
      RETURN;
    END IF;

    -- 1) Identify the region.
    SELECT r.region_id
      INTO lv_region_id
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
     WHERE r.name = p_region_name;

    -- 2) Count stations in the region.
    SELECT COUNT(*)
      INTO lv_station_cnt
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
     WHERE si.region_id = lv_region_id;

    -- 3) Sum availability (status may be missing for some stations).
    SELECT NVL(SUM(TO_NUMBER(ss.num_bikes_available)), 0),
           NVL(SUM(TO_NUMBER(ss.num_docks_available)), 0)
      INTO lv_bikes_available,
           lv_docks_available
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      LEFT OUTER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
        ON ss.station_id = si.station_id
     WHERE si.region_id = lv_region_id;

    -- Avoid divide-by-zero; also supports regions with no stations.
    IF lv_station_cnt = 0 THEN
      lv_avg_bikes_per_station := 0;
    ELSE
      lv_avg_bikes_per_station := lv_bikes_available / lv_station_cnt;
    END IF;

    -- 4) Classify region health.
    IF lv_avg_bikes_per_station >= 8 THEN
      lv_health := 'GREEN';
    ELSIF lv_avg_bikes_per_station >= 3 THEN
      lv_health := 'AMBER';
    ELSE
      lv_health := 'RED';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Region: ' || p_region_name);
    DBMS_OUTPUT.PUT_LINE('Stations: ' || lv_station_cnt);
    DBMS_OUTPUT.PUT_LINE('Bikes available: ' || lv_bikes_available);
    DBMS_OUTPUT.PUT_LINE('Docks available: ' || lv_docks_available);
    DBMS_OUTPUT.PUT_LINE('Avg bikes per station: ' || TO_CHAR(lv_avg_bikes_per_station, 'FM999990D00'));
    DBMS_OUTPUT.PUT_LINE('Health: ' || lv_health);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_region_health;

END bikeshare_ops_pkg;
/

CREATE OR REPLACE PROCEDURE report_solution_models(
  p_name    IN STACKING.SOLUTION.name%TYPE,
  p_version IN STACKING.SOLUTION.version%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_score      STACKING.SOLUTION.score%TYPE;
  lv_nb_model   STACKING.SOLUTION.nb_model%TYPE;
  lv_nb_feature STACKING.SOLUTION.nb_feature%TYPE;

  lv_found_model_rows BOOLEAN := FALSE;
  lv_class            VARCHAR2(10);
BEGIN
  -- Basic input validation
  IF p_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: NAME is required.');
    RETURN;
  ELSIF p_version IS NULL OR p_version <= 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: VERSION must be a positive number.');
    RETURN;
  END IF;

  -- Fetch the solution header (single-row expectation)
  SELECT s.score, s.nb_model, s.nb_feature
    INTO lv_score, lv_nb_model, lv_nb_feature
    FROM STACKING.SOLUTION s
   WHERE s.name = p_name
     AND s.version = p_version;

  DBMS_OUTPUT.PUT_LINE(
    'Solution ' || p_name || ' v' || p_version ||
    ' - Score: ' || TO_CHAR(lv_score) ||
    ', NB_MODEL: ' || TO_CHAR(lv_nb_model) ||
    ', NB_FEATURE: ' || TO_CHAR(lv_nb_feature)
  );

  -- Print top important models (implicit cursor FOR loop; no explicit cursors)
  FOR rec IN (
    SELECT mi.model,
           mi.importance
      FROM STACKING.MODEL_IMPORTANCE mi
     WHERE mi.name = p_name
       AND mi.version = p_version
     ORDER BY mi.importance DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_found_model_rows := TRUE;

    -- Simple classification logic
    IF rec.importance >= 0.7 THEN
      lv_class := 'HIGH';
    ELSIF rec.importance >= 0.3 THEN
      lv_class := 'MEDIUM';
    ELSE
      lv_class := 'LOW';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Model: ' || rec.model ||
      ' | Importance: ' || TO_CHAR(rec.importance) ||
      ' | Class: ' || lv_class
    );
  END LOOP;

  IF NOT lv_found_model_rows THEN
    DBMS_OUTPUT.PUT_LINE('No model importance rows found for this solution.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_solution_models;
/

