CREATE OR REPLACE PROCEDURE report_latest_indicator(
  p_country_code   IN WORLD_BANK_WDI.INDICATORS_DATA.country_code%TYPE,
  p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_latest_year WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;
  ln_row_count   PLS_INTEGER := 0;
BEGIN
  -- Simple input validation
  IF p_country_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country code is required.');
    RETURN;
  END IF;

  IF p_indicator_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: indicator code is required.');
    RETURN;
  END IF;

  -- Find the most recent year for this country+indicator
  SELECT MAX(d.year)
    INTO lv_latest_year
    FROM WORLD_BANK_WDI.INDICATORS_DATA d
   WHERE d.country_code = p_country_code
     AND d.indicator_code = p_indicator_code;

  DBMS_OUTPUT.PUT_LINE('Latest year: ' || lv_latest_year);

  -- Print up to 15 rows for that year
  FOR rec IN (
    SELECT d.country_name,
           d.indicator_code,
           d.year,
           d.value
      FROM WORLD_BANK_WDI.INDICATORS_DATA d
     WHERE d.country_code = p_country_code
       AND d.indicator_code = p_indicator_code
       AND d.year = lv_latest_year
     ORDER BY d.country_name
  ) LOOP
    ln_row_count := ln_row_count + 1;
    EXIT WHEN ln_row_count > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Country: ' || rec.country_name ||
      ' | Indicator: ' || rec.indicator_code ||
      ' | Year: ' || rec.year ||
      ' | Value: ' || rec.value
    );
  END LOOP;

  IF ln_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for the latest year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_latest_indicator;
/

