CREATE OR REPLACE PROCEDURE report_patient_payer_snapshot(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_first     SYNTHEA.PATIENTS.first%TYPE;
  lv_last      SYNTHEA.PATIENTS.last%TYPE;
  lv_birthdate SYNTHEA.PATIENTS.birthdate%TYPE;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Patient header (must exist)
  SELECT p.first,
         p.last,
         p.birthdate
    INTO lv_first,
         lv_last,
         lv_birthdate
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_first || ' ' || lv_last || ' (DOB=' || TO_CHAR(lv_birthdate, 'YYYY-MM-DD') || ')');
  DBMS_OUTPUT.PUT_LINE('Payer transitions (up to ' || co_report_limit || '):');

  -- Print up to N transitions (implicit cursor FOR loop; no explicit cursors)
  FOR rec IN (
    SELECT pt.start_year,
           pt.end_year,
           py.name AS payer_name,
           pt.ownership
      FROM SYNTHEA.PAYER_TRANSITIONS pt
      JOIN SYNTHEA.PAYERS py
        ON py.id = pt.payer
     WHERE pt.patient = p_patient_id
     ORDER BY pt.start_year, pt.end_year, py.name
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE('  ' || TO_CHAR(rec.start_year) || '-' || TO_CHAR(rec.end_year) || ' | ' || rec.payer_name || ' | ' || rec.ownership);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No payer transitions found for this patient.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_patient_payer_snapshot;
/

CREATE OR REPLACE PROCEDURE pr_f1_season_constructor_points(
  p_year            IN F1.RACES.year%TYPE,
  p_constructor_ref IN F1.CONSTRUCTORS.constructor_ref%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year_exists      PLS_INTEGER;
  lv_constructor_id   F1.CONSTRUCTORS.constructor_id%TYPE;
  lv_race_seq         PLS_INTEGER := 0;
  lv_points           F1.RESULTS.points%TYPE;

  CURSOR c_races(p_y F1.RACES.year%TYPE) IS
    SELECT r.race_id,
           r.round,
           r.name AS race_name
      FROM F1.RACES r
     WHERE r.year = p_y
     ORDER BY r.round;

  r_races c_races%ROWTYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Season points report - year=' || p_year || ', constructor_ref=' || NVL(p_constructor_ref, 'ALL'));

  -- Validate that the season exists.
  SELECT COUNT(*)
    INTO lv_year_exists
    FROM F1.SEASONS s
   WHERE s.year = p_year;

  IF lv_year_exists = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No races found for year=' || p_year || '.');
    RETURN;
  END IF;

  -- Resolve constructor_ref to constructor_id if a filter is provided.
  IF p_constructor_ref IS NOT NULL THEN
    SELECT c.constructor_id
      INTO lv_constructor_id
      FROM F1.CONSTRUCTORS c
     WHERE c.constructor_ref = p_constructor_ref;
  ELSE
    lv_constructor_id := NULL;
  END IF;

  OPEN c_races(p_year);
  LOOP
    FETCH c_races INTO r_races;
    EXIT WHEN c_races%NOTFOUND OR lv_race_seq >= co_report_limit;

    lv_race_seq := lv_race_seq + 1;

    BEGIN
      -- Points for this race under the optional constructor filter.
      SELECT SUM(res.points)
        INTO lv_points
        FROM F1.RESULTS res
       WHERE res.race_id = r_races.race_id
         AND (lv_constructor_id IS NULL OR res.constructor_id = lv_constructor_id);

      IF lv_points IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('No points rows for this filter in this race.');
        lv_points := 0;
      END IF;

      DBMS_OUTPUT.PUT_LINE('Race ' || TO_CHAR(lv_race_seq) || ': round=' || r_races.round || ', race=' || r_races.race_name || ', points=' || TO_CHAR(lv_points));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No points rows for this filter in this race.');
      WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    END;
  END LOOP;

  IF c_races%ISOPEN THEN
    CLOSE c_races;
  END IF;

  IF lv_race_seq = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No races found for year=' || p_year || '.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END pr_f1_season_constructor_points;
/

