question:
Create a small county natality report for a given year and source-of-payment. The report should show up to 15 counties (highest births first) along with births and average birth weight (grams). If the year or payment code is missing, print a clear message and stop. Also handle cases where the payment code doesn’t exist for that year.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Validation failed: year is required.');
DBMS_OUTPUT.PUT_LINE('Validation failed: payment code is required.');
DBMS_OUTPUT.PUT_LINE('Report for year=' || TO_CHAR(lv_year, 'YYYY') || ', payment_code=' || lv_payment_code);
DBMS_OUTPUT.PUT_LINE('No matching payment records found for the given year/code.');
DBMS_OUTPUT.PUT_LINE(RPAD('County', 30) || ' | ' || LPAD('Births', 10) || ' | ' || LPAD('Avg Birth Wt (g)', 16));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 30, '-') || '-+-' || RPAD('-', 10, '-') || '-+-' || RPAD('-', 16, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.county_of_residence, 30) || ' | ' || LPAD(TO_CHAR(rec.births_num), 10) || ' | ' || LPAD(TO_CHAR(rec.avg_bw_num, '9999990D0'), 16));
DBMS_OUTPUT.PUT_LINE('No county rows found for the given year/code.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid numeric data encountered in births or average birth weight.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year         SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT.YEAR%TYPE := DATE '2018-01-01';
  lv_payment_code SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT.SOURCE_OF_PAYMENT_CODE%TYPE := '1';

  lv_payment_exists NUMBER;
  lv_rows_printed   PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF lv_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Validation failed: year is required.');
    RETURN;
  END IF;

  IF lv_payment_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Validation failed: payment code is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Report for year=' || TO_CHAR(lv_year, 'YYYY') || ', payment_code=' || lv_payment_code);

  -- Verify there is data for the given year/payment code
  SELECT 1
    INTO lv_payment_exists
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT p
   WHERE p.YEAR = lv_year
     AND p.SOURCE_OF_PAYMENT_CODE = lv_payment_code
     AND ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE(RPAD('County', 30) || ' | ' || LPAD('Births', 10) || ' | ' || LPAD('Avg Birth Wt (g)', 16));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 30, '-') || '-+-' || RPAD('-', 10, '-') || '-+-' || RPAD('-', 16, '-'));

  FOR rec IN (
    SELECT p.COUNTY_OF_RESIDENCE AS county_of_residence,
           TO_NUMBER(p.BIRTHS) AS births_num,
           TO_NUMBER(p.AVE_BIRTH_WEIGHT_GMS) AS avg_bw_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT p
     WHERE p.YEAR = lv_year
       AND p.SOURCE_OF_PAYMENT_CODE = lv_payment_code
       AND p.BIRTHS IS NOT NULL
       AND p.AVE_BIRTH_WEIGHT_GMS IS NOT NULL
     ORDER BY TO_NUMBER(p.BIRTHS) DESC, p.COUNTY_OF_RESIDENCE ASC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.county_of_residence, 30) || ' | ' ||
      LPAD(TO_CHAR(rec.births_num), 10) || ' | ' ||
      LPAD(TO_CHAR(rec.avg_bw_num, '9999990D0'), 16)
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No county rows found for the given year/code.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching payment records found for the given year/code.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered in births or average birth weight.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

