  lv_row_count  PLS_INTEGER := 0;
BEGIN
  -- Resolve territory (case-insensitive).
  SELECT st.territoryid,
         st.name
    INTO lv_territory_id,
         lv_territory_name
    FROM ADVENTUREWORKS.SALESTERRITORY st
   WHERE UPPER(st.name) = UPPER(p_territory_name);

  DBMS_OUTPUT.PUT_LINE('Territory: ' || lv_territory_name);
  DBMS_OUTPUT.PUT_LINE('Min revenue filter: ' || TO_CHAR(p_min_total_revenue));
  DBMS_OUTPUT.PUT_LINE(RPAD('Product', 35) || ' | ' || LPAD('Revenue', 15) || ' | ' || 'Label');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || LPAD('-', 15, '-') || '-+-' || RPAD('-', 5, '-'));

  FOR rec IN (
    SELECT p.name AS product_name,
           SUM(sod.orderqty * sod.unitprice * (1 - sod.unitpricediscount)) AS revenue
      FROM ADVENTUREWORKS.SALESORDERHEADER soh
      JOIN ADVENTUREWORKS.SALESORDERDETAIL sod
        ON sod.salesorderid = soh.salesorderid
      JOIN ADVENTUREWORKS.PRODUCT p
        ON p.productid = sod.productid
     WHERE soh.territoryid = lv_territory_id
     GROUP BY p.name
    HAVING SUM(sod.orderqty * sod.unitprice * (1 - sod.unitpricediscount)) >= p_min_total_revenue
     ORDER BY revenue DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_row_count := lv_row_count + 1;

    -- Simple performance label based on revenue tiers.
    IF rec.revenue >= 100000 THEN
      lv_label := 'HIGH';
    ELSIF rec.revenue >= 50000 THEN
      lv_label := 'MEDIUM';
    ELSE
      lv_label := 'LOW';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.product_name, 35) || ' | ' || LPAD(TO_CHAR(ROUND(rec.revenue, 2)), 15) || ' | ' || lv_label
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No products found for the given criteria.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Territory not found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple territories matched the given name.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_products_by_territory;
/

CREATE OR REPLACE PROCEDURE report_team_season_summary(
  p_year    IN BASEBALL.TEAM.year%TYPE,
  p_team_id IN BASEBALL.TEAM.team_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_wins   BASEBALL.TEAM.w%TYPE;
  lv_losses BASEBALL.TEAM.l%TYPE;
  lv_found_players PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Team season: ' || p_year || ' / ' || p_team_id);

  -- Single-row fetch for the team season record
  SELECT t.w,
         t.l
    INTO lv_wins,
         lv_losses
    FROM BASEBALL.TEAM t
   WHERE t.year = p_year
     AND t.team_id = p_team_id;

  -- Simple win/loss status
  IF lv_wins > lv_losses THEN
    DBMS_OUTPUT.PUT_LINE('Win/Loss status: ABOVE .500');
  ELSIF lv_wins = lv_losses THEN
    DBMS_OUTPUT.PUT_LINE('Win/Loss status: EXACTLY .500');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Win/Loss status: BELOW .500');
  END IF;

  DBMS_OUTPUT.PUT_LINE('Players (up to ' || co_report_limit || '):');

  -- Implicit cursor loop (no explicit cursor declarations)
  FOR rec IN (
    SELECT a.player_id,
           a.g_all
      FROM BASEBALL.APPEARANCES a
     WHERE a.year = p_year
       AND a.team_id = p_team_id
       AND a.g_all IS NOT NULL
     ORDER BY a.g_all DESC, a.player_id
  ) LOOP
    EXIT WHEN lv_found_players >= co_report_limit;

    lv_found_players := lv_found_players + 1;
    DBMS_OUTPUT.PUT_LINE('- Player: ' || rec.player_id || ', Games: ' || rec.g_all);
  END LOOP;

  IF lv_found_players = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No players found for that team/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_team_season_summary;
/

