question:
Build a reusable reporting routine for a care management dashboard.

Given an organization name, list up to 15 providers in that organization ordered by highest utilization first. For each provider, show the provider name, speciality, gender, and the count of encounters they handled, plus the total claim cost for those encounters.

Requirements:
Use a named explicit cursor to iterate providers in the organization.
For each provider, compute encounter count and total claim cost.
If a provider has no encounters, print a line indicating that.
Handle bad or missing input and ensure the routine never throws an unhandled exception.

Requirements:
Procedure Name: report_org_provider_utilization
Parameters:
p_org_name IN SYNTHEA.ORGANIZATIONS.name%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Organization: ' || p_org_name);
DBMS_OUTPUT.PUT_LINE('Provider: ' || r_prov.provider_name || ' | Speciality: ' || r_prov.speciality || ' | Gender: ' || r_prov.gender || ' | Utilization: ' || r_prov.utilization);
DBMS_OUTPUT.PUT_LINE('  Encounters: ' || lv_encounter_cnt || ' | Total Claim Cost: ' || TO_CHAR(lv_total_claim_cost, 'FM999G999G999G990D00'));
DBMS_OUTPUT.PUT_LINE('  Encounters: 0 | Total Claim Cost: 0.00');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_org_provider_utilization(
  p_org_name IN SYNTHEA.ORGANIZATIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_org_id SYNTHEA.ORGANIZATIONS.id%TYPE;

  CURSOR c_providers(p_org_id IN SYNTHEA.ORGANIZATIONS.id%TYPE) IS
    SELECT p.id AS provider_id,
           p.name AS provider_name,
           p.speciality,
           p.gender,
           p.utilization
      FROM SYNTHEA.PROVIDERS p
     WHERE p.organization = p_org_id
     ORDER BY p.utilization DESC, p.name
     FETCH FIRST co_report_limit ROWS ONLY;

  lv_encounter_cnt NUMBER;
  lv_total_claim_cost NUMBER;
BEGIN
  IF p_org_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Organization: ' || p_org_name);

  SELECT o.id
    INTO lv_org_id
    FROM SYNTHEA.ORGANIZATIONS o
   WHERE o.name = p_org_name;

  FOR r_prov IN c_providers(lv_org_id) LOOP
    DBMS_OUTPUT.PUT_LINE('Provider: ' || r_prov.provider_name || ' | Speciality: ' || r_prov.speciality || ' | Gender: ' || r_prov.gender || ' | Utilization: ' || r_prov.utilization);

    SELECT COUNT(*), NVL(SUM(e.total_claim_cost), 0)
      INTO lv_encounter_cnt, lv_total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.provider = r_prov.provider_id;

    IF lv_encounter_cnt > 0 THEN
      DBMS_OUTPUT.PUT_LINE('  Encounters: ' || lv_encounter_cnt || ' | Total Claim Cost: ' || TO_CHAR(lv_total_claim_cost, 'FM999G999G999G990D00'));
    ELSE
      DBMS_OUTPUT.PUT_LINE('  Encounters: 0 | Total Claim Cost: 0.00');
    END IF;
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_org_provider_utilization;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE := 'SP.POP.TOTL';
  lv_year           WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE := '2010';

  lv_rows_printed PLS_INTEGER := 0;

  CURSOR cur_top_values IS
    WITH numeric_rows AS (
      SELECT d.country_code,
             CASE
               WHEN REGEXP_LIKE(TRIM(d.value), '^[+-]?(\\d+)(\\.\\d+)?$') THEN TO_NUMBER(TRIM(d.value))
               ELSE NULL
             END AS num_value
        FROM WORLD_BANK_WDI.INDICATORS_DATA d
       WHERE d.indicator_code = lv_indicator_code
         AND d.year = lv_year
    ), ranked_rows AS (
      SELECT nr.country_code,
             nr.num_value,
             ROW_NUMBER() OVER (ORDER BY nr.num_value DESC NULLS LAST, nr.country_code) AS rn
        FROM numeric_rows nr
       WHERE nr.num_value IS NOT NULL
    )
    SELECT rr.country_code,
           cs.short_name,
           rr.num_value
      FROM ranked_rows rr
      LEFT OUTER JOIN WORLD_BANK_WDI.COUNTRY_SUMMARY cs
        ON cs.country_code = rr.country_code
     WHERE rr.rn <= co_report_limit
     ORDER BY rr.num_value DESC, rr.country_code;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Indicator: ' || lv_indicator_code || ' Year: ' || lv_year);

  OPEN cur_top_values;
  LOOP
    DECLARE
      rec cur_top_values%ROWTYPE;
    BEGIN
      FETCH cur_top_values INTO rec;
      EXIT WHEN cur_top_values%NOTFOUND;

      lv_rows_printed := lv_rows_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        'Country Code: ' || rec.country_code || ' | Country: ' || NVL(rec.short_name, 'UNKNOWN') || ' | Value: ' || TO_CHAR(rec.num_value)
      );

      IF rec.short_name IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('Warning: No country summary found for country_code=' || rec.country_code);
      END IF;
    END;
  END LOOP;
  CLOSE cur_top_values;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No qualifying numeric data found for the given indicator/year.');
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Rows printed: ' || TO_CHAR(lv_rows_printed));
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No qualifying numeric data found for the given indicator/year.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF cur_top_values%ISOPEN THEN
      CLOSE cur_top_values;
    END IF;
END;
/

