DECLARE
  lv_email        MUSIC.CUSTOMER.email%TYPE := 'laura@ferrari.com';

  lv_customer_id  MUSIC.CUSTOMER.customerid%TYPE;
  lv_first_name   MUSIC.CUSTOMER.firstname%TYPE;
  lv_last_name    MUSIC.CUSTOMER.lastname%TYPE;

  lv_printed_count PLS_INTEGER := 0;
  lv_total_sum     MUSIC.INVOICE.total%TYPE := 0;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  IF lv_email IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: email is required.');
    RETURN;
  END IF;

  -- Expect exactly one customer per email; handle data quality issues via exceptions.
  SELECT c.customerid, c.firstname, c.lastname
    INTO lv_customer_id, lv_first_name, lv_last_name
    FROM MUSIC.CUSTOMER c
   WHERE c.email = lv_email;

  DBMS_OUTPUT.PUT_LINE('Customer: ' || lv_first_name || ' ' || lv_last_name || ' (ID=' || lv_customer_id || ')');

  -- Print up to co_report_limit most recent invoices for this customer.
  FOR inv IN (
    SELECT i.invoiceid AS invoice_id,
           i.invoicedate AS invoice_date,
           i.total AS total
      FROM MUSIC.INVOICE i
     WHERE i.customerid = lv_customer_id
     ORDER BY i.invoicedate DESC, i.invoiceid DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_printed_count := lv_printed_count + 1;
    lv_total_sum := lv_total_sum + inv.total;

    DBMS_OUTPUT.PUT_LINE(
      'InvoiceId=' || inv.invoice_id ||
      ', InvoiceDate=' || TO_CHAR(inv.invoice_date, 'YYYY-MM-DD') ||
      ', Total=' || TO_CHAR(inv.total, 'FM999999990.00')
    );
  END LOOP;

  IF lv_printed_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No invoices found for this customer.');
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Invoices printed=' || lv_printed_count ||
    ', Total printed=' || TO_CHAR(lv_total_sum, 'FM999999990.00')
  );
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

