DECLARE
  lv_support_rep_id   MUSIC.CUSTOMER.supportrepid%TYPE := 3; -- Input: support rep to report on
  lv_rep_name         VARCHAR2(200);

  ln_customer_count   PLS_INTEGER := 0;
  ln_invoice_rowcount PLS_INTEGER := 0;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  -- Guard clause for required input
  IF lv_support_rep_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Support Rep Id is required.');
    RETURN;
  END IF;

  -- Validate the support rep exists and capture display name
  SELECT e.firstname || ' ' || e.lastname
    INTO lv_rep_name
    FROM MUSIC.EMPLOYEE e
   WHERE e.employeeid = lv_support_rep_id;

  -- Check whether the rep has any customers
  SELECT COUNT(*)
    INTO ln_customer_count
    FROM MUSIC.CUSTOMER c
   WHERE c.supportrepid = lv_support_rep_id;

  IF ln_customer_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No customers found for Support Rep Id: ' || lv_support_rep_id);
    RETURN;
  END IF;

  -- Check whether any invoices exist for those customers
  SELECT COUNT(*)
    INTO ln_invoice_rowcount
    FROM MUSIC.INVOICE i
    JOIN MUSIC.CUSTOMER c
      ON c.customerid = i.customerid
   WHERE c.supportrepid = lv_support_rep_id;

  IF ln_invoice_rowcount = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No invoice data found for customers of Support Rep Id: ' || lv_support_rep_id);
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Support Rep: ' || lv_rep_name);

  -- Revenue spotlight: rank customers within the rep by total invoice amount
  FOR r IN (
    WITH cust_totals AS (
      SELECT c.customerid,
             c.firstname || ' ' || c.lastname AS customer_name,
             SUM(i.total) AS total_spent
        FROM MUSIC.CUSTOMER c
        JOIN MUSIC.INVOICE i
          ON i.customerid = c.customerid
       WHERE c.supportrepid = lv_support_rep_id
       GROUP BY c.customerid, c.firstname, c.lastname
    )
    SELECT ct.customerid,
           ct.customer_name,
           ct.total_spent,
           RANK() OVER (ORDER BY ct.total_spent DESC) AS revenue_rank
      FROM cust_totals ct
     ORDER BY revenue_rank, ct.customerid
  ) LOOP
    EXIT WHEN r.revenue_rank > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'CustomerId=' || r.customerid ||
      ', Customer=' || r.customer_name ||
      ', TotalSpent=' || TO_CHAR(r.total_spent) ||
      ', Rank=' || r.revenue_rank
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Support Rep not found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

