CREATE OR REPLACE PROCEDURE report_runner_performance(
  p_runner_id IN MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS.runner_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_delivered_cnt NUMBER;
  lv_avg_speed     NUMBER;
  lv_tier          VARCHAR2(30);
BEGIN
  IF p_runner_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input runner id is NULL; nothing to report.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Runner performance snapshot for runner_id=' || p_runner_id);

  -- Aggregate metrics for delivered (non-cancelled) orders
  SELECT COUNT(*),
         AVG(CASE
               WHEN cro.duration > 0 THEN cro.distance / cro.duration
               ELSE NULL
             END)
    INTO lv_delivered_cnt, lv_avg_speed
    FROM MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS cro
   WHERE cro.runner_id = p_runner_id
     AND cro.cancellation IS NULL;

  IF lv_delivered_cnt = 0 OR lv_avg_speed IS NULL THEN
    lv_tier := 'NO_DELIVERIES';
  ELSIF lv_avg_speed >= 0.50 THEN
    lv_tier := 'FAST';
  ELSIF lv_avg_speed >= 0.30 THEN
    lv_tier := 'STANDARD';
  ELSE
    lv_tier := 'SLOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Delivered orders=' || lv_delivered_cnt || ', avg_speed_km_per_min=' || TO_CHAR(lv_avg_speed, 'FM9990D000'));
  DBMS_OUTPUT.PUT_LINE('Performance tier=' || lv_tier);
  DBMS_OUTPUT.PUT_LINE('Recent delivered orders (max ' || co_report_limit || '):');

  -- Ranked report of most recent delivered orders (max 15)
  FOR rec IN (
    WITH delivered AS (
      SELECT cro.order_id,
             NVL(cro.pickup_time, 'UNKNOWN') AS pickup_time_disp,
             cro.distance AS distance_km,
             cro.duration AS duration_min,
             CASE
               WHEN cro.duration > 0 THEN cro.distance / cro.duration
               ELSE NULL
             END AS speed_km_per_min,
             ROW_NUMBER() OVER (
               ORDER BY NVL(cro.pickup_time, 'UNKNOWN') DESC, cro.order_id DESC
             ) AS rn
        FROM MODERN_DATA.PIZZA_CLEAN_RUNNER_ORDERS cro
       WHERE cro.runner_id = p_runner_id
         AND cro.cancellation IS NULL
    )
    SELECT d.order_id,
           d.pickup_time_disp,
           d.distance_km,
           d.duration_min,
           d.speed_km_per_min
      FROM delivered d
     WHERE d.rn <= co_report_limit
     ORDER BY d.rn
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'order_id=' || rec.order_id ||
      ', pickup_time=' || rec.pickup_time_disp ||
      ', distance=' || TO_CHAR(rec.distance_km, 'FM9990D00') ||
      ', duration=' || TO_CHAR(rec.duration_min, 'FM9990D00') ||
      ', speed=' || TO_CHAR(rec.speed_km_per_min, 'FM9990D000')
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_runner_performance;
/

DECLARE
  -- Inputs (in a real form/report these would come from bind variables)
  lv_area_name  BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name  BLS.CPI_U.item_name%TYPE := 'All items';
  lv_year       BLS.CPI_U.year%TYPE := '2020';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_printed_rows PLS_INTEGER := 0;
  lv_min_val      NUMBER;
  lv_max_val      NUMBER;
  lv_sum_val      NUMBER := 0;
  lv_cnt_val      PLS_INTEGER := 0;
  lv_avg_val      NUMBER;

  lv_num_val      NUMBER;
BEGIN
  -- Basic input validation
  IF lv_area_name IS NULL OR lv_item_name IS NULL OR lv_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Missing input: area, item, and year are all required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI-U monthly observations (limited to ' || co_report_limit || ' rows):');

  -- Print up to N rows in chronological order
  FOR rec IN (
    SELECT c.period,
           c.value,
           c.c_date
      FROM BLS.CPI_U c
     WHERE c.area_name = lv_area_name
       AND c.item_name = lv_item_name
       AND c.year = lv_year
     ORDER BY c.c_date
  ) LOOP
    EXIT WHEN lv_printed_rows >= co_report_limit;

    lv_printed_rows := lv_printed_rows + 1;
    DBMS_OUTPUT.PUT_LINE('PERIOD=' || rec.period || ', VALUE=' || rec.value);

    -- Safe numeric conversion for summary stats (skip invalid numeric values)
    BEGIN
      lv_num_val := TO_NUMBER(rec.value);

      IF lv_cnt_val = 0 THEN
        lv_min_val := lv_num_val;
        lv_max_val := lv_num_val;
      ELSE
        IF lv_num_val < lv_min_val THEN
          lv_min_val := lv_num_val;
        END IF;
        IF lv_num_val > lv_max_val THEN
          lv_max_val := lv_num_val;
        END IF;
      END IF;

      lv_sum_val := lv_sum_val + lv_num_val;
      lv_cnt_val := lv_cnt_val + 1;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        NULL; -- Ignore non-numeric VALUE rows for the summary
    END;
  END LOOP;

  IF lv_printed_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No monthly observations found for the given filters.');
    RETURN;
  END IF;

  IF lv_cnt_val = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No numeric CPI values found to summarize (all values invalid or missing).');
    RETURN;
  END IF;

  lv_avg_val := ROUND(lv_sum_val / lv_cnt_val, 4);

  DBMS_OUTPUT.PUT_LINE(
    'Summary for YEAR=' || lv_year || ': MIN=' || lv_min_val || ', MAX=' || lv_max_val || ', AVG=' || lv_avg_val
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

