  DBMS_OUTPUT.PUT_LINE('CPI-U monthly observations (limited to ' || co_report_limit || ' rows):');
  FOR rec IN (
    SELECT c.period, c.value, c.c_date
      FROM BLS.CPI_U c
     WHERE c.area_name = lv_area_name
       AND c.item_name = lv_item_name
       AND c.year = lv_year
     ORDER BY c.c_date
  ) LOOP
    EXIT WHEN lv_printed_rows >= co_report_limit;
    lv_printed_rows := lv_printed_rows + 1;
    DBMS_OUTPUT.PUT_LINE('PERIOD=' || rec.period || ', VALUE=' || rec.value);
    BEGIN
      lv_num_val := TO_NUMBER(rec.value);
      IF lv_cnt_val = 0 THEN lv_min_val := lv_num_val; lv_max_val := lv_num_val; ELSE
