DECLARE
  lv_state       CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE := 'CA';
  lv_state_avg   NUMBER;
  lv_row_count   PLS_INTEGER := 0;
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  lv_state := UPPER(TRIM(lv_state));

  DBMS_OUTPUT.PUT_LINE('State: ' || lv_state);

  SELECT AVG(
           CASE
             WHEN REGEXP_LIKE(hha.total_hha_medicare_payment_amount_non_lupa, '^\s*-?\d+(\.\d+)?\s*$')
               THEN TO_NUMBER(TRIM(hha.total_hha_medicare_payment_amount_non_lupa))
             ELSE 0
           END
         )
    INTO lv_state_avg
    FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
   WHERE hha.state = lv_state;

  DBMS_OUTPUT.PUT_LINE('State average payment (non-LUPA): ' || TO_CHAR(lv_state_avg, 'FM999G999G999G990D00'));

  FOR rec IN (
    SELECT provider_id,
           agency_name,
           pay_amt
      FROM (
        SELECT hha.provider_id AS provider_id,
               hha.agency_name AS agency_name,
               CASE
                 WHEN REGEXP_LIKE(hha.total_hha_medicare_payment_amount_non_lupa, '^\s*-?\d+(\.\d+)?\s*$')
                   THEN TO_NUMBER(TRIM(hha.total_hha_medicare_payment_amount_non_lupa))
                 ELSE 0
               END AS pay_amt
          FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
         WHERE hha.state = lv_state
         ORDER BY pay_amt DESC, hha.provider_id
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_row_count := lv_row_count + 1;

    DBMS_OUTPUT.PUT_LINE(
      'Provider: ' || rec.provider_id ||
      ' | Agency: ' || rec.agency_name ||
      ' | Payment: ' || TO_CHAR(rec.pay_amt, 'FM999G999G999G990D00') ||
      ' | Class: ' || CASE WHEN rec.pay_amt >= lv_state_avg THEN 'HIGH' ELSE 'LOW' END
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No agencies found for state: ' || lv_state);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No agencies found for state: ' || lv_state);
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

