CREATE OR REPLACE PACKAGE cms_provider_rpt IS
  PROCEDURE print_hospice_payment_spotlight(
    p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
  );
END cms_provider_rpt;
/

CREATE OR REPLACE PACKAGE BODY cms_provider_rpt IS

  PROCEDURE print_hospice_payment_spotlight(
    p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_ranked_providers IS
      WITH ranked AS (
        SELECT
          hp.provider_id,
          hp.name,
          hp.total_medicare_payment_amount,
          hp.total_days,
          ROW_NUMBER() OVER (
            ORDER BY TO_NUMBER(TRIM(hp.total_medicare_payment_amount)) DESC
          ) AS rn
        FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
        WHERE hp.state = p_state
          AND TRIM(hp.total_medicare_payment_amount) IS NOT NULL
          AND TRIM(hp.total_days) IS NOT NULL
          AND REGEXP_LIKE(TRIM(hp.total_medicare_payment_amount), '^[-+]?[0-9]*\.?[0-9]+$')
          AND REGEXP_LIKE(TRIM(hp.total_days), '^[-+]?[0-9]*\.?[0-9]+$')
      )
      SELECT
        r.provider_id,
        r.name,
        r.total_medicare_payment_amount,
        r.total_days,
        r.rn
      FROM ranked r
      WHERE r.rn <= co_report_limit
      ORDER BY r.rn;

    v_printed PLS_INTEGER := 0;
    v_skipped PLS_INTEGER := 0;

    v_pay  NUMBER;
    v_days NUMBER;
    v_ppd  NUMBER;

    v_cat  VARCHAR2(10);
    v_rank PLS_INTEGER;

  BEGIN
    DBMS_OUTPUT.PUT_LINE('Hospice payment spotlight for state=' || p_state);
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 72, '-'));

    IF p_state IS NULL OR TRIM(p_state) IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    FOR r IN c_ranked_providers LOOP
      BEGIN
        v_pay  := TO_NUMBER(TRIM(r.total_medicare_payment_amount));
        v_days := TO_NUMBER(TRIM(r.total_days));

        IF v_days = 0 THEN
          v_skipped := v_skipped + 1;
          CONTINUE;
        END IF;

        v_ppd := v_pay / v_days;

        IF v_ppd >= 500 THEN
          v_cat := 'HIGH';
        ELSIF v_ppd >= 250 THEN
          v_cat := 'MEDIUM';
        ELSE
          v_cat := 'LOW';
        END IF;

        v_rank := r.rn;

        DBMS_OUTPUT.PUT_LINE(
          'Rank ' || v_rank || ': ' || r.name || ' (Provider ' || r.provider_id || '), Payment=' ||
          TO_CHAR(v_pay, 'FM999G999G999G990D00') || ', Days=' ||
          TO_CHAR(v_days, 'FM999G999G999G990') || ', Pay/Day=' ||
          TO_CHAR(v_ppd, 'FM999G999G999G990D00') || ', Category=' || v_cat
        );

        v_printed := v_printed + 1;

      EXCEPTION
        WHEN VALUE_ERROR THEN
          v_skipped := v_skipped + 1;
        WHEN INVALID_NUMBER THEN
          v_skipped := v_skipped + 1;
        WHEN ZERO_DIVIDE THEN
          v_skipped := v_skipped + 1;
        WHEN OTHERS THEN
          v_skipped := v_skipped + 1;
      END;
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Summary: printed=' || v_printed || ', skipped_bad_data=' || v_skipped);

    IF v_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_hospice_payment_spotlight;

END cms_provider_rpt;
/

CREATE OR REPLACE PROCEDURE report_country_debt(
  p_country_code IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.country_code%TYPE,
  p_year         IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country_name WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.short_name%TYPE;
  lv_region       WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE;

  lv_total_debt   NUMBER;
  lv_classification VARCHAR2(10);

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Input validation
  IF p_country_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country code is required.');
    RETURN;
  END IF;

  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year is required.');
    RETURN;
  END IF;

  -- Retrieve basic country context (single-row lookup)
  SELECT cs.short_name,
         cs.region
    INTO lv_country_name,
         lv_region
    FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
   WHERE cs.country_code = p_country_code;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name || ' (' || p_country_code || ')');
  DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region);

  -- Compute total numeric debt for classification, skipping non-numeric values.
  SELECT NVL(
           SUM(
             CASE
               WHEN REGEXP_LIKE(d.value, '^[+-]?(\d+)(\.\d+)?$') THEN TO_NUMBER(d.value)
               ELSE NULL
             END
           ),
           0
         )
    INTO lv_total_debt
    FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
   WHERE d.country_code = p_country_code
     AND d.year = p_year;

  IF lv_total_debt >= 1000000000 THEN
    lv_classification := 'HIGH';
  ELSE
    lv_classification := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Debt classification for ' || p_year || ': ' || lv_classification);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 80, '-'));
  DBMS_OUTPUT.PUT_LINE(RPAD('Indicator', 55) || 'Value');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 80, '-'));

  -- Print up to 15 top indicators by numeric value (skip non-numeric values)
  FOR r IN (
    SELECT indicator_name,
           value_num
      FROM (
        SELECT d.indicator_name AS indicator_name,
               TO_NUMBER(d.value) AS value_num
          FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
         WHERE d.country_code = p_country_code
           AND d.year = p_year
           AND REGEXP_LIKE(d.value, '^[+-]?(\d+)(\.\d+)?$')
         ORDER BY TO_NUMBER(d.value) DESC, d.indicator_name
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(RPAD(SUBSTR(r.indicator_name, 1, 54), 55) || TO_CHAR(r.value_num));
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No numeric indicator rows found for the provided country/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric conversion encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_debt;
/

