question:
Build a reusable procedure that produces a small “top products by revenue” report for a given order date range, and categorizes each product’s performance based on total revenue. For each product, calculate revenue as SUM(orderqty * unitprice * (1 - unitpricediscount)). Show the product name, number of order lines, total quantity, total revenue, and a performance tier:
PLATINUM when total revenue >= a configurable threshold
GOLD when total revenue is between 50% of that threshold and the threshold
 SILVER otherwise

Only include rows for products that belong to a specified product category name. The procedure should print up to 15 products, ordered by total revenue descending.

Make sure the routine validates inputs (including the date range and threshold) and handles empty result sets cleanly without raising an unhandled exception.

Requirements:
Procedure Name: report_top_products_by_revenue
Parameters:
p_category_name IN ADVENTUREWORKS.PRODUCTCATEGORY.name%TYPE
p_start_date IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE
p_end_date IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE
p_platinum_threshold IN ADVENTUREWORKS.SALESORDERHEADER.totaldue%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Report filter - Category: ' || p_category_name || ', Date range: ' || TO_CHAR(p_start_date, 'YYYY-MM-DD') || ' to ' || TO_CHAR(p_end_date, 'YYYY-MM-DD'));
DBMS_OUTPUT.PUT_LINE('Threshold (PLATINUM): ' || TO_CHAR(p_platinum_threshold));
DBMS_OUTPUT.PUT_LINE('PRODUCT_NAME | LINES | QTY | REVENUE | TIER');
DBMS_OUTPUT.PUT_LINE(RPAD(rec.product_name, 30) || ' | ' || LPAD(rec.line_count, 5) || ' | ' || LPAD(rec.total_qty, 5) || ' | ' || LPAD(TO_CHAR(rec.total_revenue, 'FM999999990D00'), 12) || ' | ' || rec.tier);
DBMS_OUTPUT.PUT_LINE('No data found for the provided filters.');
DBMS_OUTPUT.PUT_LINE('Invalid inputs: category name, dates, and threshold must be provided.');
DBMS_OUTPUT.PUT_LINE('Invalid date range: start date must be <= end date.');
DBMS_OUTPUT.PUT_LINE('Invalid threshold: must be greater than 0.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found for the provided filters.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_top_products_by_revenue(
  p_category_name       IN ADVENTUREWORKS.PRODUCTCATEGORY.name%TYPE,
  p_start_date          IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE,
  p_end_date            IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE,
  p_platinum_threshold  IN ADVENTUREWORKS.SALESORDERHEADER.totaldue%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic parameter validation
  IF p_category_name IS NULL
     OR p_start_date IS NULL
     OR p_end_date IS NULL
     OR p_platinum_threshold IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid inputs: category name, dates, and threshold must be provided.');
    RETURN;
  END IF;

  IF p_start_date > p_end_date THEN
    DBMS_OUTPUT.PUT_LINE('Invalid date range: start date must be <= end date.');
    RETURN;
  END IF;

  IF p_platinum_threshold <= 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid threshold: must be greater than 0.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Report filter - Category: ' || p_category_name || ', Date range: ' || TO_CHAR(p_start_date, 'YYYY-MM-DD') || ' to ' || TO_CHAR(p_end_date, 'YYYY-MM-DD'));
  DBMS_OUTPUT.PUT_LINE('Threshold (PLATINUM): ' || TO_CHAR(p_platinum_threshold));
  DBMS_OUTPUT.PUT_LINE('PRODUCT_NAME | LINES | QTY | REVENUE | TIER');

  -- Implicit cursor loop (required_cursors = False)
  FOR rec IN (
    WITH product_rev AS (
      SELECT
        p.name AS product_name,
        COUNT(*) AS line_count,
        SUM(d.orderqty) AS total_qty,
        SUM(d.orderqty * d.unitprice * (1 - d.unitpricediscount)) AS total_revenue
      FROM ADVENTUREWORKS.SALESORDERHEADER h
      INNER JOIN ADVENTUREWORKS.SALESORDERDETAIL d
        ON d.salesorderid = h.salesorderid
      INNER JOIN ADVENTUREWORKS.PRODUCT p
        ON p.productid = d.productid
      INNER JOIN ADVENTUREWORKS.PRODUCTSUBCATEGORY sc
        ON sc.productsubcategoryid = p.productsubcategoryid
      INNER JOIN ADVENTUREWORKS.PRODUCTCATEGORY c
        ON c.productcategoryid = sc.productcategoryid
      WHERE c.name = p_category_name
        AND h.orderdate >= p_start_date
        AND h.orderdate < (p_end_date + 1) -- inclusive end date
      GROUP BY p.name
    )
    SELECT
      pr.product_name,
      pr.line_count,
      pr.total_qty,
      pr.total_revenue,
      CASE
        WHEN pr.total_revenue >= p_platinum_threshold THEN 'PLATINUM'
        WHEN pr.total_revenue >= (p_platinum_threshold * 0.5) THEN 'GOLD'
        ELSE 'SILVER'
      END AS tier
    FROM product_rev pr
    ORDER BY pr.total_revenue DESC
    FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.product_name, 30) || ' | ' ||
      LPAD(rec.line_count, 5) || ' | ' ||
      LPAD(rec.total_qty, 5) || ' | ' ||
      LPAD(TO_CHAR(rec.total_revenue, 'FM999999990D00'), 12) || ' | ' ||
      rec.tier
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the provided filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the provided filters.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_products_by_revenue;
/

