CREATE OR REPLACE PROCEDURE report_county_maternal_profile(
  p_year        IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_county_fips IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_county_fips SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE;

  CURSOR c_nat(
    cp_year SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
    cp_fips SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE
  ) IS
    SELECT county_of_residence,
           county_of_residence_fips,
           births,
           ave_age_of_mother
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
     WHERE year = cp_year
       AND county_of_residence_fips = cp_fips
     ORDER BY TO_NUMBER(REGEXP_REPLACE(births, '[^0-9]', '')) DESC NULLS LAST;

  lv_county_name     SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE;
  lv_county_fips_row SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence_fips%TYPE;
  lv_births_txt      SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.births%TYPE;
  lv_age_txt         SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.ave_age_of_mother%TYPE;

  lv_births_num    NUMBER := 0;
  lv_total_births  NUMBER := 0;
  lv_max_births    NUMBER := 0;
  lv_rows_printed  PLS_INTEGER := 0;
  lv_age_disp      VARCHAR2(20);

  lv_births_clean  VARCHAR2(4000);
BEGIN
  DBMS_OUTPUT.PUT_LINE('County Maternal Profile Report');
  DBMS_OUTPUT.PUT_LINE('Year=' || TO_CHAR(p_year, 'YYYY') || ', CountyFIPS=' || NVL(p_county_fips, ''));

  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  IF p_county_fips IS NOT NULL THEN
    lv_county_fips := p_county_fips;
  ELSE
    -- Most common county FIPS for that year
    SELECT county_of_residence_fips
      INTO lv_county_fips
      FROM (
            SELECT county_of_residence_fips
              FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY
             WHERE year = p_year
               AND county_of_residence_fips IS NOT NULL
             GROUP BY county_of_residence_fips
             ORDER BY COUNT(*) DESC, county_of_residence_fips
           )
     WHERE ROWNUM = 1;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Resolved CountyFIPS=' || lv_county_fips);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));
  DBMS_OUTPUT.PUT_LINE(RPAD('County', 30) || RPAD('FIPS', 12) || LPAD('Births', 10) || LPAD('AvgAge', 10));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));

  OPEN c_nat(p_year, lv_county_fips);
  LOOP
    FETCH c_nat INTO lv_county_name, lv_county_fips_row, lv_births_txt, lv_age_txt;
    EXIT WHEN c_nat%NOTFOUND;

    lv_rows_printed := lv_rows_printed + 1;

    -- Convert births safely; treat conversion issues as 0
    lv_births_clean := REGEXP_REPLACE(lv_births_txt, '[^0-9]', '');
    BEGIN
      lv_births_num := TO_NUMBER(lv_births_clean);
    EXCEPTION
      WHEN OTHERS THEN
        lv_births_num := 0;
    END;

    lv_total_births := lv_total_births + lv_births_num;
    IF lv_births_num > lv_max_births THEN
      lv_max_births := lv_births_num;
    END IF;

    lv_age_disp := SUBSTR(NVL(lv_age_txt, 'n/a'), 1, 10);

    DBMS_OUTPUT.PUT_LINE(
      RPAD(lv_county_name, 30) ||
      RPAD(lv_county_fips_row, 12) ||
      LPAD(TO_CHAR(lv_births_num), 10) ||
      LPAD(lv_age_disp, 10)
    );

    EXIT WHEN lv_rows_printed >= co_report_limit;
  END LOOP;
  CLOSE c_nat;

  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));
  DBMS_OUTPUT.PUT_LINE('Rows printed=' || TO_CHAR(lv_rows_printed));
  DBMS_OUTPUT.PUT_LINE('Total births=' || TO_CHAR(lv_total_births));
  DBMS_OUTPUT.PUT_LINE('Max births=' || TO_CHAR(lv_max_births));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_county_maternal_profile;
/

