DECLARE
  -- Inputs (set these before running)
  lv_rate_date      ADVENTUREWORKS.CURRENCYRATE.currencyratedate%TYPE := DATE '2005-07-01';
  lv_from_currency  ADVENTUREWORKS.CURRENCYRATE.fromcurrencycode%TYPE := 'USD';
  lv_to_currency    ADVENTUREWORKS.CURRENCYRATE.tocurrencycode%TYPE   := 'CAD';

  -- Business threshold for a simple classification
  ln_threshold      NUMBER := 1; -- Example threshold for HIGH/LOW classification

  -- Outputs
  lv_avg_rate       ADVENTUREWORKS.CURRENCYRATE.averagerate%TYPE;
  lv_eod_rate       ADVENTUREWORKS.CURRENCYRATE.endofdayrate%TYPE;
  lv_classification VARCHAR2(10);
BEGIN
  -- Basic input validation
  IF lv_rate_date IS NULL OR lv_from_currency IS NULL OR lv_to_currency IS NULL THEN
    RAISE VALUE_ERROR;
  END IF;

  -- Retrieve exact rate for the day and currency pair
  SELECT cr.averagerate,
         cr.endofdayrate
    INTO lv_avg_rate,
         lv_eod_rate
    FROM ADVENTUREWORKS.CURRENCYRATE cr
   WHERE cr.currencyratedate   = lv_rate_date
     AND cr.fromcurrencycode   = lv_from_currency
     AND cr.tocurrencycode     = lv_to_currency;

  -- Simple control-flow classification
  IF lv_avg_rate >= ln_threshold THEN
    lv_classification := 'HIGH';
  ELSE
    lv_classification := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Rate summary: ' || lv_from_currency || '->' || lv_to_currency ||
    ' on ' || TO_CHAR(lv_rate_date, 'YYYY-MM-DD') ||
    ' avg=' || TO_CHAR(lv_avg_rate) ||
    ' eod=' || TO_CHAR(lv_eod_rate) ||
    ' classification=' || lv_classification
  );
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

