CREATE OR REPLACE PROCEDURE report_top_counties_by_births(
  p_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year  SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE;
  lv_class VARCHAR2(20);
BEGIN
  -- Default NULL input to the latest available year.
  IF p_year IS NULL THEN
    SELECT MAX(cn.year)
      INTO lv_year
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn;
  ELSE
    lv_year := p_year;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top counties by births for year=' || TO_CHAR(lv_year, 'YYYY') || ' (showing up to ' || co_report_limit || ')');
  DBMS_OUTPUT.PUT_LINE(RPAD('County', 35) || ' | ' || LPAD('Births', 10) || ' | ' || 'Class');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || LPAD('-', 10, '-') || '-+-' || RPAD('-', 10, '-'));

  -- If no rows exist for the requested year, raise NO_DATA_FOUND in a controlled way.
  DECLARE
    lv_cnt PLS_INTEGER;
  BEGIN
    SELECT COUNT(*)
      INTO lv_cnt
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE cn.year = lv_year;

    IF lv_cnt = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;
  END;

  FOR rec IN (
    WITH base AS (
      SELECT cn.county_of_residence,
             CASE
               WHEN TRIM(cn.births) IS NULL THEN 0
               WHEN REGEXP_LIKE(TRIM(cn.births), '^[-]?[0-9]+(\\.[0-9]+)?$') THEN TO_NUMBER(TRIM(cn.births))
               ELSE 0
             END AS births_num
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = lv_year
    ), ranked AS (
      SELECT b.county_of_residence,
             b.births_num,
             ROW_NUMBER() OVER (ORDER BY b.births_num DESC, b.county_of_residence ASC) AS rn
        FROM base b
    )
    SELECT r.county_of_residence,
           r.births_num
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.births_num DESC, r.county_of_residence ASC
  ) LOOP
    -- Classification for briefing
    IF rec.births_num >= 10000 THEN
      lv_class := 'HIGH';
    ELSIF rec.births_num BETWEEN 3000 AND 9999 THEN
      lv_class := 'MEDIUM';
    ELSIF rec.births_num BETWEEN 1 AND 2999 THEN
      lv_class := 'LOW';
    ELSE
      lv_class := 'ZERO_OR_MISSING';
    END IF;

    DBMS_OUTPUT.PUT_LINE(RPAD(rec.county_of_residence, 35) || ' | ' || LPAD(TO_CHAR(rec.births_num), 10) || ' | ' || lv_class);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_counties_by_births;
/

