DECLARE
  -- Report inputs (set these for execution)
  lv_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE := 'SP.POP.TOTL';
  lv_year          WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE := '2010';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_row_count PLS_INTEGER := 0;
  lv_min_val   NUMBER;
  lv_max_val   NUMBER;

  -- Explicit cursor: top countries by numeric value for a given indicator/year
  CURSOR c_top_countries (
    p_indicator_code IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE,
    p_year           IN WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE
  ) IS
    WITH ranked AS (
      SELECT
        d.country_name,
        d.country_code,
        TO_NUMBER(d.value) AS value_num,
        cs.region,
        cs.income_group,
        ROW_NUMBER() OVER (ORDER BY TO_NUMBER(d.value) DESC) AS rn
      FROM WORLD_BANK_WDI.INDICATORS_DATA d
      INNER JOIN WORLD_BANK_WDI.COUNTRY_SUMMARY cs
        ON cs.country_code = d.country_code
      WHERE d.indicator_code = p_indicator_code
        AND d.year = p_year
        AND d.value IS NOT NULL
    )
    SELECT
      ranked.country_name,
      ranked.country_code,
      ranked.value_num,
      ranked.region,
      ranked.income_group
    FROM ranked
    WHERE ranked.rn <= co_report_limit
    ORDER BY ranked.value_num DESC;

  r_country c_top_countries%ROWTYPE;
BEGIN
  -- Basic input validation
  IF lv_indicator_code IS NULL OR lv_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for indicator/year.');
    DBMS_OUTPUT.PUT_LINE(
      'Summary: rows=' || TO_CHAR(0) ||
      ', min=' || 'N/A' ||
      ', max=' || 'N/A'
    );
    RETURN;
  END IF;

  -- Validate that year is numeric (this will raise VALUE_ERROR if not)
  DECLARE
    lv_year_num NUMBER;
  BEGIN
    lv_year_num := TO_NUMBER(lv_year);
  END;

  DBMS_OUTPUT.PUT_LINE('Input indicator_code=' || lv_indicator_code || ', year=' || lv_year);

  OPEN c_top_countries(lv_indicator_code, lv_year);
  LOOP
    FETCH c_top_countries INTO r_country;
    EXIT WHEN c_top_countries%NOTFOUND;

    lv_row_count := lv_row_count + 1;

    IF lv_row_count = 1 THEN
      lv_min_val := r_country.value_num;
      lv_max_val := r_country.value_num;
    ELSE
      IF r_country.value_num < lv_min_val THEN
        lv_min_val := r_country.value_num;
      END IF;
      IF r_country.value_num > lv_max_val THEN
        lv_max_val := r_country.value_num;
      END IF;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Country=' || r_country.country_name ||
      ' (' || r_country.country_code ||
      '), value=' || TO_CHAR(r_country.value_num) ||
      ', region=' || r_country.region ||
      ', income_group=' || r_country.income_group
    );
  END LOOP;
  CLOSE c_top_countries;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for indicator/year.');
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Summary: rows=' || TO_CHAR(lv_row_count) ||
    ', min=' || CASE WHEN lv_row_count = 0 THEN 'N/A' ELSE TO_CHAR(lv_min_val) END ||
    ', max=' || CASE WHEN lv_row_count = 0 THEN 'N/A' ELSE TO_CHAR(lv_max_val) END
  );
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
