CREATE OR REPLACE PACKAGE debt_snapshot_pkg IS
  PROCEDURE print_top_countries(
    p_income_group IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE,
    p_year         IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
  );
END debt_snapshot_pkg;
/

CREATE OR REPLACE PACKAGE BODY debt_snapshot_pkg IS
  PROCEDURE print_top_countries(
    p_income_group IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE,
    p_year         IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_income_group WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE;
    lv_req_year_num NUMBER;
    lv_effective_year WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE;

    lv_rank PLS_INTEGER := 0;
    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    -- Normalize/validate inputs
    lv_income_group := NULLIF(TRIM(p_income_group), '');

    IF lv_income_group IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    IF p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Invalid year value.');
      RETURN;
    END IF;

    lv_req_year_num := TO_NUMBER(TRIM(p_year));

    -- Find effective year (most recent year <= requested year for the given income group)
    SELECT MAX(d.year)
      INTO lv_effective_year
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
      INNER JOIN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
        ON cs.country_code = d.country_code
     WHERE cs.income_group = lv_income_group
       AND TO_NUMBER(TRIM(d.year)) <= lv_req_year_num;

    IF lv_effective_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Effective year: ' || lv_effective_year);
    DBMS_OUTPUT.PUT_LINE('Top countries by total debt for income group "' || lv_income_group || '"');

    -- Print ranked results; use an inline query with ROWNUM to cap output deterministically.
    FOR rec IN (
      WITH totals AS (
        SELECT d.country_name,
               SUM(TO_NUMBER(TRIM(d.value))) AS total_debt
          FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
          INNER JOIN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
            ON cs.country_code = d.country_code
         WHERE cs.income_group = lv_income_group
           AND d.year = lv_effective_year
         GROUP BY d.country_name
      )
      SELECT t.country_name,
             t.total_debt
        FROM (
          SELECT t2.country_name,
                 t2.total_debt
            FROM totals t2
           ORDER BY t2.total_debt DESC, t2.country_name ASC
        ) t
       WHERE ROWNUM <= co_report_limit
    ) LOOP
      lv_rank := lv_rank + 1;
      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE(LPAD(lv_rank, 2, '0') || '. ' || rec.country_name || ' | total_debt=' || TO_CHAR(rec.total_debt));
    END LOOP;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No rows matched the criteria.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid year value.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_countries;
END debt_snapshot_pkg;
/

CREATE OR REPLACE PROCEDURE report_hospitals_by_state(
  p_state IN CMS_MEDICARE.HOSPITAL_GENERAL_INFO.state%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
  lv_category     VARCHAR2(20);
BEGIN
  IF p_state IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('State parameter is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Hospital snapshot for state: ' || p_state);

  FOR rec IN (
    SELECT h.provider_id,
           h.hospital_name,
           h.city,
           h.emergency_services,
           h.hospital_overall_rating
      FROM CMS_MEDICARE.HOSPITAL_GENERAL_INFO h
     WHERE h.state = p_state
       AND ROWNUM <= co_report_limit
     ORDER BY h.hospital_name
  ) LOOP
    -- Categorize the rating for quick interpretation.
    IF rec.hospital_overall_rating IN ('5', '4') THEN
      lv_category := 'High';
    ELSIF rec.hospital_overall_rating IN ('3') THEN
      lv_category := 'Medium';
    ELSIF rec.hospital_overall_rating IN ('2', '1') THEN
      lv_category := 'Low';
    ELSE
      lv_category := 'Unknown';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Provider ' || rec.provider_id || ' | ' || rec.hospital_name || ' | ' || rec.city ||
      ' | ER=' || rec.emergency_services || ' | Rating=' || rec.hospital_overall_rating ||
      ' | Category=' || lv_category
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    -- Normalize empty result set to NO_DATA_FOUND for consistent exception messaging.
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No hospitals found for the requested state.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_hospitals_by_state;
/

