DECLARE
  -- Input parameters for the report (set these before running)
  p_departure_airport AIRLINES.FLIGHTS.departure_airport%TYPE := 'DME';
  p_sched_date        VARCHAR2(10) := '2017-08-15';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_departure_airport AIRLINES.FLIGHTS.departure_airport%TYPE;
  ld_sched_date        DATE;
  ln_rows_printed      PLS_INTEGER := 0;
BEGIN
  -- Validate required airport code
  IF p_departure_airport IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: departure airport code is required.');
    RETURN;
  END IF;

  lv_departure_airport := p_departure_airport;

  -- Validate date format (must be YYYY-MM-DD)
  BEGIN
    ld_sched_date := TO_DATE(p_sched_date, 'YYYY-MM-DD');
  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Invalid input: scheduled date must be YYYY-MM-DD.');
      RETURN;
  END;

  DBMS_OUTPUT.PUT_LINE('Flights for airport ' || lv_departure_airport || ' on ' || p_sched_date || ':');

  FOR r IN (
    SELECT f.flight_no,
           f.flight_id,
           f.status,
           f.scheduled_departure,
           (SELECT COUNT(*)
              FROM AIRLINES.BOARDING_PASSES bp
             WHERE bp.flight_id = f.flight_id) AS bp_count
      FROM AIRLINES.FLIGHTS f
     WHERE f.departure_airport = lv_departure_airport
       AND f.scheduled_departure >= CAST(ld_sched_date AS TIMESTAMP)
       AND f.scheduled_departure <  CAST(ld_sched_date + 1 AS TIMESTAMP)
     ORDER BY f.scheduled_departure
  ) LOOP
    EXIT WHEN ln_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      '  Flight ' || r.flight_no || ' (ID=' || r.flight_id || ') status=' || r.status ||
      ', sched=' || TO_CHAR(r.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
      ', boarding_passes=' || r.bp_count
    );

    ln_rows_printed := ln_rows_printed + 1;
  END LOOP;

  IF ln_rows_printed = 0 THEN
    -- Force the required NO_DATA_FOUND handler in a controlled way
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching flights found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

