  IF p_territory_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('TerritoryID is required.');
    RETURN;
  END IF;

  -- Look up territory name (expects exactly one row)
  SELECT st.name
    INTO lv_territory_name
    FROM ADVENTUREWORKS.SALESTERRITORY st
   WHERE st.territoryid = p_territory_id;

  DBMS_OUTPUT.PUT_LINE('Territory: ' || lv_territory_name || ' (ID=' || p_territory_id || ')');

  -- Check whether there are any orders for this territory
  SELECT COUNT(*)
    INTO lv_order_count
    FROM ADVENTUREWORKS.SALESORDERHEADER soh
   WHERE soh.territoryid = p_territory_id;

  IF lv_order_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No orders found for territory ID ' || p_territory_id || '.');
    RETURN;
  END IF;

  -- Print up to 15 most recent orders
  FOR r IN (
    SELECT soh.salesorderid,
           soh.orderdate,
           soh.status,
           soh.totaldue
      FROM ADVENTUREWORKS.SALESORDERHEADER soh
     WHERE soh.territoryid = p_territory_id
     ORDER BY soh.orderdate DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'Order ' || r.salesorderid || ' | ' || TO_CHAR(r.orderdate, 'YYYY-MM-DD') ||
      ' | Status=' || r.status ||
      ' | TotalDue=' || TO_CHAR(r.totaldue)
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_territory_recent_orders;
/

