CREATE OR REPLACE PROCEDURE report_cpi_u_area_item(
  p_area_name       IN BLS.CPI_U.area_name%TYPE,
  p_item_name       IN BLS.CPI_U.item_name%TYPE,
  p_year            IN BLS.CPI_U.year%TYPE,
  p_high_threshold  IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year_num NUMBER;
  lv_rows     PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI-U Report');
  DBMS_OUTPUT.PUT_LINE('Area: ' || NVL(p_area_name, 'NULL'));
  DBMS_OUTPUT.PUT_LINE('Item: ' || NVL(p_item_name, 'NULL'));
  DBMS_OUTPUT.PUT_LINE('Year: ' || NVL(p_year, 'NULL'));
  DBMS_OUTPUT.PUT_LINE('High threshold: ' || TO_CHAR(p_high_threshold));

  -- Validate year is numeric (YEAR is stored as VARCHAR2 in the source table)
  lv_year_num := TO_NUMBER(p_year);

  -- Implicit cursor loop (required_cursors = False)
  FOR rec IN (
    WITH ranked AS (
      SELECT
        c.period,
        c.c_date,
        c.value,
        ROW_NUMBER() OVER (ORDER BY c.c_date) AS rn,
        CASE
          WHEN TO_NUMBER(c.value) >= p_high_threshold THEN 'HIGH'
          ELSE 'NORMAL'
        END AS status
      FROM BLS.CPI_U c
      WHERE c.area_name = p_area_name
        AND c.item_name = p_item_name
        AND TO_NUMBER(c.year) = lv_year_num
        AND c.c_date IS NOT NULL
        AND c.value IS NOT NULL
    )
    SELECT
      ranked.rn,
      ranked.period,
      ranked.c_date,
      ranked.value,
      ranked.status
    FROM ranked
    WHERE ranked.rn <= co_report_limit
    ORDER BY ranked.rn
  ) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(
      'rn=' || rec.rn ||
      ' period=' || rec.period ||
      ' date=' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') ||
      ' value=' || rec.value ||
      ' status=' || rec.status
    );
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the input filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric input or value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_cpi_u_area_item;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_name       STACKING.SOLUTION.name%TYPE := 'UNKNOWN';
  lv_version    STACKING.SOLUTION.version%TYPE := 1;

  lv_score      STACKING.SOLUTION.score%TYPE;
  lv_nb_model   STACKING.SOLUTION.nb_model%TYPE;
  lv_nb_feature STACKING.SOLUTION.nb_feature%TYPE;

  lv_eda_type   STACKING.EDA.type%TYPE;
  lv_drop_user  STACKING.EDA.drop_user%TYPE;
  lv_drop_corr  STACKING.EDA.drop_correlation%TYPE;

  lv_missing_eda PLS_INTEGER := 0;
  lv_scanned     PLS_INTEGER := 0;

  CURSOR c_fi(p_name STACKING.FEATURE_IMPORTANCE.name%TYPE,
              p_version STACKING.FEATURE_IMPORTANCE.version%TYPE) IS
    SELECT fi.feature,
           fi.importance
      FROM STACKING.FEATURE_IMPORTANCE fi
     WHERE fi.name = p_name
       AND fi.version = p_version
     ORDER BY fi.importance DESC
     FETCH FIRST co_report_limit ROWS ONLY;
BEGIN
  -- Pick the most common (name, version) pair to make the script deterministic.
  SELECT s.name,
         s.version
    INTO lv_name,
         lv_version
    FROM (
          SELECT s2.name,
                 s2.version
            FROM STACKING.SOLUTION s2
           GROUP BY s2.name, s2.version
           ORDER BY COUNT(*) DESC, s2.name, s2.version
         ) s
   WHERE ROWNUM = 1;

  -- Get the solution row for reporting.
  SELECT s.score,
         s.nb_model,
         s.nb_feature
    INTO lv_score,
         lv_nb_model,
         lv_nb_feature
    FROM STACKING.SOLUTION s
   WHERE s.name = lv_name
     AND s.version = lv_version
     AND ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE('Solution: ' || lv_name || ' v' || lv_version || ' | SCORE=' || TO_CHAR(lv_score) || ' | NB_MODEL=' || TO_CHAR(lv_nb_model) || ' | NB_FEATURE=' || TO_CHAR(lv_nb_feature));

  -- Iterate through top feature importances and validate presence in EDA.
  FOR r_fi IN c_fi(lv_name, lv_version) LOOP
    lv_scanned := lv_scanned + 1;

    BEGIN
      SELECT e.type,
             e.drop_user,
             e.drop_correlation
        INTO lv_eda_type,
             lv_drop_user,
             lv_drop_corr
        FROM STACKING.EDA e
       WHERE e.name = lv_name
         AND e.version = lv_version
         AND e.feature = r_fi.feature
         AND ROWNUM = 1;

      DBMS_OUTPUT.PUT_LINE('Feature: ' || r_fi.feature || ' | IMPORTANCE=' || TO_CHAR(r_fi.importance) || ' | EDA_TYPE=' || lv_eda_type || ' | DROP_USER=' || TO_CHAR(lv_drop_user) || ' | DROP_CORRELATION=' || TO_CHAR(lv_drop_corr));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        lv_missing_eda := lv_missing_eda + 1;
        DBMS_OUTPUT.PUT_LINE('Feature: ' || r_fi.feature || ' | IMPORTANCE=' || TO_CHAR(r_fi.importance) || ' | EDA is missing.');
      WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    END;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Summary: scanned=' || TO_CHAR(lv_scanned) || ' missing_in_eda=' || TO_CHAR(lv_missing_eda));
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

