CREATE OR REPLACE PACKAGE pkg_ops_reports IS
  PROCEDURE print_departure_airport_punctuality(
    p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE
  );
END pkg_ops_reports;
/

CREATE OR REPLACE PACKAGE BODY pkg_ops_reports IS
  PROCEDURE print_departure_airport_punctuality(
    p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_flights IS
      WITH flt AS (
        SELECT f.flight_id,
               f.flight_no,
               f.arrival_airport,
               f.scheduled_departure,
               f.scheduled_arrival,
               f.actual_departure,
               f.actual_arrival,
               (SELECT COUNT(*)
                  FROM AIRLINES.BOARDING_PASSES bp
                 WHERE bp.flight_id = f.flight_id) AS boarded_cnt,
               CASE
                 WHEN f.actual_arrival IS NULL OR f.scheduled_arrival IS NULL THEN 'UNKNOWN'
                 WHEN f.actual_arrival > f.scheduled_arrival THEN 'LATE'
                 ELSE 'ON_TIME'
               END AS punctuality
          FROM AIRLINES.FLIGHTS f
         WHERE f.departure_airport = p_departure_airport
         ORDER BY f.scheduled_departure DESC
      )
      SELECT flt.*
        FROM flt
       WHERE ROWNUM <= co_report_limit;

    lv_processed PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Punctuality report for departure airport: ' || NVL(p_departure_airport, '(NULL)'));

    IF p_departure_airport IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Flights processed=' || lv_processed);
      RETURN;
    END IF;

    FOR r_flt IN c_flights LOOP
      lv_processed := lv_processed + 1;

      DBMS_OUTPUT.PUT_LINE('Flight ID=' || r_flt.flight_id || ', Flight No=' || r_flt.flight_no || ', To=' || r_flt.arrival_airport);
      DBMS_OUTPUT.PUT_LINE(
        '  Scheduled: dep=' || TO_CHAR(r_flt.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
        ', arr=' || TO_CHAR(r_flt.scheduled_arrival, 'YYYY-MM-DD HH24:MI')
      );
      DBMS_OUTPUT.PUT_LINE(
        '  Actual:    dep=' ||
        CASE
          WHEN r_flt.actual_departure IS NULL THEN '(NULL)'
          ELSE TO_CHAR(r_flt.actual_departure, 'YYYY-MM-DD HH24:MI')
        END ||
        ', arr=' ||
        CASE
          WHEN r_flt.actual_arrival IS NULL THEN '(NULL)'
          ELSE TO_CHAR(r_flt.actual_arrival, 'YYYY-MM-DD HH24:MI')
        END
      );
      DBMS_OUTPUT.PUT_LINE('  Boarded passengers=' || r_flt.boarded_cnt || ', Status=' || r_flt.punctuality);
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Flights processed=' || lv_processed);

    IF lv_processed = 0 THEN
      -- Escalate to the caller-friendly standard message via an explicit exception.
      -- (No RAISE / RAISE_APPLICATION_ERROR allowed; use SELECT INTO to raise NO_DATA_FOUND.)
      DECLARE
        lv_dummy PLS_INTEGER;
      BEGIN
        SELECT 1 INTO lv_dummy
          FROM AIRLINES.FLIGHTS f
         WHERE f.departure_airport = p_departure_airport
           AND ROWNUM = 1;
      END;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_departure_airport_punctuality;
END pkg_ops_reports;
/

