    DBMS_OUTPUT.PUT_LINE('Billing country must not be NULL.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top customers for billing country: ' || p_billing_country);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));
  DBMS_OUTPUT.PUT_LINE(
    RPAD('Customer', 30) ||
    RPAD('Total Spend', 15) ||
    RPAD('Invoices', 10) ||
    RPAD('Last Invoice', 15) ||
    'Tier'
  );
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));

  FOR rec IN (
    WITH spend_by_customer AS (
      SELECT
        c.customerid,
        c.firstname || ' ' || c.lastname AS customer_name,
        SUM(i.total) AS total_spend,
        COUNT(*) AS invoice_count,
        MAX(i.invoicedate) AS last_invoice_date
      FROM CHINOOK.CUSTOMERS c
      INNER JOIN CHINOOK.INVOICES i
        ON i.customerid = c.customerid
      WHERE i.billingcountry = p_billing_country
      GROUP BY c.customerid, c.firstname, c.lastname
    )
    SELECT
      sbc.customer_name,
      sbc.total_spend,
      sbc.invoice_count,
      sbc.last_invoice_date,
      CASE
        WHEN sbc.total_spend >= 50 THEN 'HIGH'
        WHEN sbc.total_spend >= 20 THEN 'MEDIUM'
        ELSE 'LOW'
      END AS spend_tier
    FROM spend_by_customer sbc
    ORDER BY sbc.total_spend DESC, sbc.customer_name ASC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.customer_name, 30) ||
      RPAD(TO_CHAR(rec.total_spend), 15) ||
      RPAD(TO_CHAR(rec.invoice_count), 10) ||
      RPAD(TO_CHAR(rec.last_invoice_date, 'YYYY-MM-DD'), 15) ||
      rec.spend_tier
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No customers found for billing country: ' || p_billing_country);
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_customers_by_billing_country;
/

CREATE OR REPLACE PROCEDURE report_country_demo_snapshot(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
  p_year_start   IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
  p_year_end     IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
  lv_year_start_n NUMBER;
  lv_year_end_n   NUMBER;
  lv_class        VARCHAR2(30);
BEGIN
  -- Basic input validation (keep procedure safe and deterministic)
  IF p_country_name IS NULL OR TRIM(p_country_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country name is required.');
    RETURN;
  END IF;

  IF p_year_start IS NULL OR p_year_end IS NULL OR TRIM(p_year_start) IS NULL OR TRIM(p_year_end) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year range is required.');
    RETURN;
  END IF;

  lv_year_start_n := TO_NUMBER(TRIM(p_year_start));
  lv_year_end_n   := TO_NUMBER(TRIM(p_year_end));

  IF lv_year_start_n > lv_year_end_n THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: start year must be <= end year.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('DEMO SNAPSHOT | Country=' || p_country_name || ' | Years=' || p_year_start || '-' || p_year_end);

  -- Report: join fertility + growth context, parse numeric strings, classify by TFR
  FOR r IN (
    SELECT *
    FROM (
      SELECT
        asfr.year AS year,
        TO_NUMBER(TRIM(asfr.total_fertility_rate)) AS tfr,
        TO_NUMBER(TRIM(bdgr.crude_birth_rate))     AS cbr,
        TO_NUMBER(TRIM(bdgr.growth_rate))          AS growth
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES asfr
      INNER JOIN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bdgr
        ON UPPER(bdgr.country_name) = UPPER(asfr.country_name)
       AND bdgr.year = asfr.year
      WHERE UPPER(asfr.country_name) = UPPER(p_country_name)
        AND TO_NUMBER(TRIM(asfr.year)) BETWEEN lv_year_start_n AND lv_year_end_n
      ORDER BY TO_NUMBER(TRIM(asfr.year))
    )
    WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    IF r.tfr >= 4 THEN
      lv_class := 'HIGH_FERTILITY';
    ELSIF r.tfr >= 2.1 THEN
      lv_class := 'REPLACEMENT_LEVEL';
    ELSE
      lv_class := 'LOW_FERTILITY';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Year=' || r.year ||
      ' | TFR=' || r.tfr ||
      ' | CBR=' || r.cbr ||
      ' | Growth=' || r.growth ||
      ' | Class=' || lv_class
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    -- Use NO_DATA_FOUND to standardize messaging, as requested
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested criteria.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered while parsing rates.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_demo_snapshot;
/

