    SELECT report_year
      INTO lv_report_year
      FROM (
            SELECT report_year
              FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION
             GROUP BY report_year
             ORDER BY COUNT(*) DESC, report_year ASC
           )
     WHERE ROWNUM = 1;
  END IF;

