CREATE OR REPLACE PROCEDURE report_group_inventory_demand(
  p_group_name IN ORACLE_SQL.PRODUCT_GROUPS.name%TYPE,
  p_month      IN ORACLE_SQL.MONTHLY_SALES.mth%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_group_id   ORACLE_SQL.PRODUCT_GROUPS.id%TYPE;

  CURSOR c_ranked_products(p_group_id ORACLE_SQL.PRODUCT_GROUPS.id%TYPE, p_mth ORACLE_SQL.MONTHLY_SALES.mth%TYPE) IS
    WITH base AS (
      SELECT
        p.id   AS product_id,
        p.name AS product_name,
        g.name AS group_name,
        NVL(ms.qty, 0) AS sales_qty,
        NVL(mb.qty, 0) AS budget_qty,
        NVL(inv.on_hand_qty, 0) AS on_hand_qty,
        CASE
          WHEN NVL(mb.qty, 0) = 0 THEN NULL
          ELSE NVL(ms.qty, 0) / NVL(mb.qty, 0)
        END AS sales_to_budget_ratio,
        ROW_NUMBER() OVER (
          ORDER BY
            CASE
              WHEN NVL(mb.qty, 0) = 0 THEN -1
              ELSE NVL(ms.qty, 0) / NVL(mb.qty, 0)
            END DESC,
            p.id ASC
        ) AS rn
      FROM ORACLE_SQL.PRODUCTS p
      INNER JOIN ORACLE_SQL.PRODUCT_GROUPS g
        ON g.id = p.group_id
      LEFT OUTER JOIN ORACLE_SQL.MONTHLY_SALES ms
        ON ms.product_id = p.id
       AND ms.mth = p_mth
      LEFT OUTER JOIN ORACLE_SQL.MONTHLY_BUDGET mb
        ON mb.product_id = p.id
       AND mb.mth = p_mth
      LEFT OUTER JOIN (
        SELECT i.product_id, SUM(i.qty) AS on_hand_qty
          FROM ORACLE_SQL.INVENTORY i
         GROUP BY i.product_id
      ) inv
        ON inv.product_id = p.id
      WHERE p.group_id = p_group_id
    )
    SELECT
      b.product_id,
      b.product_name,
      b.group_name,
      b.sales_qty,
      b.budget_qty,
      b.on_hand_qty,
      b.sales_to_budget_ratio,
      b.rn
    FROM base b
    WHERE b.rn <= co_report_limit
    ORDER BY b.rn;

  lv_rec c_ranked_products%ROWTYPE;
  lv_rows_printed PLS_INTEGER := 0;

  lv_product_id   ORACLE_SQL.PRODUCTS.id%TYPE;
  lv_product_name ORACLE_SQL.PRODUCTS.name%TYPE;
  lv_group_name   ORACLE_SQL.PRODUCT_GROUPS.name%TYPE;
  lv_sales_qty    ORACLE_SQL.MONTHLY_SALES.qty%TYPE;
  lv_budget_qty   ORACLE_SQL.MONTHLY_BUDGET.qty%TYPE;
  lv_on_hand_qty  ORACLE_SQL.INVENTORY.qty%TYPE;

  lv_ratio_txt VARCHAR2(30);
  lv_note      VARCHAR2(200);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Group=' || p_group_name || ', Month=' || p_month);
  DBMS_OUTPUT.PUT_LINE(
    RPAD('PRODUCT_ID', 12) || RPAD('PRODUCT_NAME', 35) || RPAD('GROUP_NAME', 25) ||
    LPAD('SALES_QTY', 10) || LPAD('BUDGET_QTY', 11) || LPAD('ON_HAND', 10) ||
    LPAD('RATIO', 10) || ' NOTE'
  );

  -- Resolve the product group.
  SELECT g.id
    INTO lv_group_id
    FROM ORACLE_SQL.PRODUCT_GROUPS g
   WHERE g.name = p_group_name;

  OPEN c_ranked_products(lv_group_id, p_month);
  LOOP
    FETCH c_ranked_products INTO lv_rec;
    EXIT WHEN c_ranked_products%NOTFOUND;

    lv_rows_printed := lv_rows_printed + 1;

    lv_product_id   := lv_rec.product_id;
    lv_product_name := lv_rec.product_name;
    lv_group_name   := lv_rec.group_name;
    lv_sales_qty    := lv_rec.sales_qty;
    lv_budget_qty   := lv_rec.budget_qty;
    lv_on_hand_qty  := lv_rec.on_hand_qty;

    IF lv_budget_qty = 0 THEN
      lv_ratio_txt := 'NULL';
      lv_note := 'Budget is 0; ratio not computed.';
    ELSE
      lv_ratio_txt := TO_CHAR(ROUND(lv_rec.sales_to_budget_ratio, 4));
      lv_note := '';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(lv_product_id), 12) ||
      RPAD(SUBSTR(lv_product_name, 1, 34), 35) ||
      RPAD(SUBSTR(lv_group_name, 1, 24), 25) ||
      LPAD(TO_CHAR(lv_sales_qty), 10) ||
      LPAD(TO_CHAR(lv_budget_qty), 11) ||
      LPAD(TO_CHAR(lv_on_hand_qty), 10) ||
      LPAD(lv_ratio_txt, 10) ||
      ' ' || lv_note
    );
  END LOOP;
  CLOSE c_ranked_products;

  -- If the group exists but has no products, treat it as no data for reporting.
  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_group_inventory_demand;
/

CREATE OR REPLACE PROCEDURE report_channel_sales(
  p_year IN NUMBER
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year        COMPLEX_ORACLE.TIMES.calendar_year%TYPE;
  lv_row_count   PLS_INTEGER := 0;
  lv_label       VARCHAR2(10);
BEGIN
  -- Default NULL input to the most recent calendar year in TIMES.
  IF p_year IS NULL THEN
    SELECT MAX(t.calendar_year)
      INTO lv_year
      FROM COMPLEX_ORACLE.TIMES t;
  ELSE
    lv_year := p_year;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Channel sales report for year: ' || lv_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('CHANNEL_ID', 12) || RPAD('CHANNEL_DESC', 35) || LPAD('AMOUNT_SOLD', 15) || LPAD('QTY_SOLD', 12) || RPAD('  LABEL', 10));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 84, '-'));

  -- Inline cursor FOR loop (required_cursors = False): aggregate by channel for the year.
  FOR rec IN (
    SELECT x.channel_id,
           x.channel_desc,
           x.amount_sold_total,
           x.qty_sold_total
      FROM (
        SELECT s.channel_id,
               c.channel_desc,
               SUM(s.amount_sold)   AS amount_sold_total,
               SUM(s.quantity_sold) AS qty_sold_total
          FROM COMPLEX_ORACLE.SALES s
          INNER JOIN COMPLEX_ORACLE.TIMES t
            ON t.time_id = s.time_id
          INNER JOIN COMPLEX_ORACLE.CHANNELS c
            ON c.channel_id = s.channel_id
         WHERE t.calendar_year = lv_year
         GROUP BY s.channel_id, c.channel_desc
         ORDER BY SUM(s.amount_sold) DESC
      ) x
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_row_count := lv_row_count + 1;

    -- Simple performance classification based on total amount.
    IF rec.amount_sold_total >= 1000000 THEN
      lv_label := 'HIGH';
    ELSIF rec.amount_sold_total >= 200000 THEN
      lv_label := 'MEDIUM';
    ELSE
      lv_label := 'LOW';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(rec.channel_id), 12) ||
      RPAD(SUBSTR(rec.channel_desc, 1, 34), 35) ||
      LPAD(TO_CHAR(rec.amount_sold_total), 15) ||
      LPAD(TO_CHAR(rec.qty_sold_total), 12) ||
      RPAD('  ' || lv_label, 10)
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No channels found for year: ' || lv_year);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_channel_sales;
/

