CREATE OR REPLACE PROCEDURE report_station_trip_snapshot(
  p_station_name IN SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for readability

  lv_station_id  SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE;
  lv_landmark    SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE;
  lv_trip_count  NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Station: ' || p_station_name);

  -- Lookup station details (expects exactly one match)
  SELECT s.station_id,
         s.landmark
    INTO lv_station_id,
         lv_landmark
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
   WHERE s.name = p_station_name;

  DBMS_OUTPUT.PUT_LINE('Station ID: ' || lv_station_id);
  DBMS_OUTPUT.PUT_LINE('Landmark: ' || lv_landmark);

  -- Count trips that started at this station
  SELECT COUNT(*)
    INTO lv_trip_count
    FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
   WHERE t.start_station_id = lv_station_id;

  DBMS_OUTPUT.PUT_LINE('Trips started here: ' || lv_trip_count);

  IF lv_trip_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No trips found for this station.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Recent trip start times (most recent first):');

    FOR rec IN (
      SELECT t.start_date
        FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
       WHERE t.start_station_id = lv_station_id
         AND t.start_date IS NOT NULL
       ORDER BY t.start_date DESC
       FETCH FIRST co_report_limit ROWS ONLY
    ) LOOP
      DBMS_OUTPUT.PUT_LINE('  ' || TO_CHAR(rec.start_date, 'YYYY-MM-DD HH24:MI:SS'));
    END LOOP;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_station_trip_snapshot;
/

