DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_dep_airport AIRLINES.FLIGHTS.departure_airport%TYPE := 'SVO';
  lv_airport_exists NUMBER;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF lv_dep_airport IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No delayed flights found for departure airport: ' || lv_dep_airport);
    RETURN;
  END IF;

  -- Validate the airport code exists in the airports reference data
  SELECT 1
    INTO lv_airport_exists
    FROM AIRLINES.AIRPORTS_DATA ad
   WHERE ad.airport_code = lv_dep_airport;

  DBMS_OUTPUT.PUT_LINE('Delayed flights report for departure airport: ' || lv_dep_airport);

  FOR rec IN (
    SELECT f.flight_no,
           f.scheduled_departure,
           f.actual_departure,
           ROUND((CAST(f.actual_departure AS DATE) - CAST(f.scheduled_departure AS DATE)) * 24 * 60) AS delay_minutes
      FROM AIRLINES.FLIGHTS f
     WHERE f.departure_airport = lv_dep_airport
       AND f.actual_departure IS NOT NULL
       AND f.actual_departure > f.scheduled_departure
     ORDER BY f.scheduled_departure DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      'Flight ' || rec.flight_no ||
      ' | Scheduled: ' || TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
      ' | Actual: ' || TO_CHAR(rec.actual_departure, 'YYYY-MM-DD HH24:MI') ||
      ' | Delay(min): ' || rec.delay_minutes
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No delayed flights found for departure airport: ' || lv_dep_airport);
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching airport found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

