CREATE OR REPLACE PROCEDURE report_race_summary(
  p_year  IN F1.RACES.year%TYPE,
  p_round IN F1.RACES.round%TYPE
) IS
  lv_race_id             F1.RACES.race_id%TYPE;
  lv_race_name           F1.RACES.name%TYPE;
  lv_race_date           F1.RACES.c_date%TYPE;
  lv_circuit_name        F1.CIRCUITS.name%TYPE;
  lv_circuit_country     F1.CIRCUITS.country%TYPE;
  lv_driver_results_cnt  NUMBER;
BEGIN
  -- 1) Identify the race and its circuit for the given year/round.
  SELECT r.race_id,
         r.name,
         r.c_date,
         c.name,
         c.country
    INTO lv_race_id,
         lv_race_name,
         lv_race_date,
         lv_circuit_name,
         lv_circuit_country
    FROM F1.RACES r
    INNER JOIN F1.CIRCUITS c
      ON c.circuit_id = r.circuit_id
   WHERE r.year = p_year
     AND r.round = p_round;

  DBMS_OUTPUT.PUT_LINE('Race: ' || lv_race_name || ' (' || TO_CHAR(lv_race_date, 'YYYY-MM-DD') || ')');
  DBMS_OUTPUT.PUT_LINE('Circuit: ' || lv_circuit_name || ' - ' || lv_circuit_country);

  -- 2) Count driver results (may be 0).
  SELECT COUNT(*)
    INTO lv_driver_results_cnt
    FROM F1.RESULTS res
   WHERE res.race_id = lv_race_id;

  IF lv_driver_results_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No results found for this race; driver results: 0');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Driver results: ' || TO_CHAR(lv_driver_results_cnt));
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No race found for year/round.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple races found for year/round.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_race_summary;
/

