CREATE OR REPLACE PROCEDURE report_payer_patient_costs(
  p_payer_id IN SYNTHEA.ENCOUNTERS.payer%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_payer_name SYNTHEA.PAYERS.name%TYPE;
  lv_tier       VARCHAR2(10);
BEGIN
  IF p_payer_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Payer ID is required.');
    RETURN;
  END IF;

  -- Lookup payer name (must be a single payer row)
  SELECT p.name
    INTO lv_payer_name
    FROM SYNTHEA.PAYERS p
   WHERE p.id = p_payer_id;

  DBMS_OUTPUT.PUT_LINE('Payer Name: ' || lv_payer_name);
  DBMS_OUTPUT.PUT_LINE('Top Patients by Total Claim Cost (max ' || co_report_limit || '):');

  -- Aggregate costs by patient for this payer and print up to the limit.
  FOR rec IN (
    SELECT patient_id,
           total_claim_cost
      FROM (
        SELECT e.patient AS patient_id,
               SUM(e.total_claim_cost) AS total_claim_cost
          FROM SYNTHEA.ENCOUNTERS e
         WHERE e.payer = p_payer_id
         GROUP BY e.patient
         ORDER BY SUM(e.total_claim_cost) DESC
      )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    IF rec.total_claim_cost >= 100000 THEN
      lv_tier := 'HIGH';
    ELSIF rec.total_claim_cost >= 50000 THEN
      lv_tier := 'MEDIUM';
    ELSE
      lv_tier := 'LOW';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Patient=' || rec.patient_id ||
      ' | TotalClaimCost=' || TO_CHAR(rec.total_claim_cost) ||
      ' | Tier=' || lv_tier
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_payer_patient_costs;
/

CREATE OR REPLACE PROCEDURE rpt_org_encounter_class_summary(
  p_organization_id IN SYNTHEA.ENCOUNTERS.organization%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_encounter_cnt NUMBER;
BEGIN
  -- Guard clause for required input
  IF p_organization_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Organization ID is required.');
    RETURN;
  END IF;

  -- Check whether the organization has any encounters
  SELECT COUNT(*)
    INTO lv_encounter_cnt
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.ORGANIZATION = p_organization_id;

  IF lv_encounter_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No encounters found for organization: ' || p_organization_id);
    RETURN;
  END IF;

  -- Report: most common encounter classes for the organization
  FOR rec IN (
    SELECT e.ENCOUNTERCLASS AS encounterclass,
           COUNT(*) AS encounter_cnt,
           SUM(e.TOTAL_CLAIM_COST) AS total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.ORGANIZATION = p_organization_id
     GROUP BY e.ENCOUNTERCLASS
     ORDER BY COUNT(*) DESC, e.ENCOUNTERCLASS
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'Org ' || p_organization_id ||
      ' | Class=' || rec.encounterclass ||
      ' | Encounters=' || rec.encounter_cnt ||
      ' | TotalClaimCost=' || TO_CHAR(rec.total_claim_cost)
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_org_encounter_class_summary;
/

