CREATE OR REPLACE PROCEDURE report_top_debt_indicators(
  p_region IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE,
  p_year   IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rank     PLS_INTEGER := 0;
  lv_category VARCHAR2(10);

  lv_value_num NUMBER;
  lv_total     NUMBER;
BEGIN
  -- Basic input validation (use VALUE_ERROR to route missing inputs into the exception section).
  IF p_region IS NULL OR p_year IS NULL THEN
    RAISE VALUE_ERROR;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top debt indicators for region=' || p_region || ', year=' || p_year);
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 72, '-'));
  DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('Category', 10) || RPAD('Countries', 12) || RPAD('Total', 18) || 'Indicator');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 72, '-'));

  -- Ensure at least one row exists for the requested region/year.
  SELECT SUM(TO_NUMBER(d.value))
    INTO lv_total
    FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
    INNER JOIN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
      ON cs.country_code = d.country_code
   WHERE cs.region = p_region
     AND d.year = p_year
     AND REGEXP_LIKE(d.value, '^[-]?[0-9]+(\.[0-9]+)?$');

  IF lv_total IS NULL THEN
    RAISE NO_DATA_FOUND;
  END IF;

  -- Top indicators by total numeric value; ignore non-numeric values safely.
  FOR rec IN (
    WITH indicator_totals AS (
      SELECT d.indicator_name AS indicator_name,
             COUNT(DISTINCT d.country_code) AS country_cnt,
             SUM(TO_NUMBER(d.value)) AS total_value
        FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
        INNER JOIN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
          ON cs.country_code = d.country_code
       WHERE cs.region = p_region
         AND d.year = p_year
         AND REGEXP_LIKE(d.value, '^[-]?[0-9]+(\.[0-9]+)?$')
       GROUP BY d.indicator_name
    ), ranked AS (
      SELECT it.indicator_name,
             it.country_cnt,
             it.total_value,
             ROW_NUMBER() OVER (ORDER BY it.total_value DESC, it.indicator_name ASC) AS rn
        FROM indicator_totals it
    )
    SELECT r.indicator_name,
           r.country_cnt,
           r.total_value
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn
  ) LOOP
    lv_rank := lv_rank + 1;

    IF rec.total_value >= 1000000000 THEN
      lv_category := 'HIGH';
    ELSIF rec.total_value >= 100000000 THEN
      lv_category := 'MEDIUM';
    ELSE
      lv_category := 'LOW';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(lv_rank), 6) ||
      RPAD(lv_category, 10) ||
      RPAD(TO_CHAR(rec.country_cnt), 12) ||
      RPAD(TO_CHAR(rec.total_value), 18) ||
      rec.indicator_name
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No indicators found for the requested region/year.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Missing required input(s).');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_debt_indicators;
/

