  PROCEDURE print_country_topic_latest(
    p_country_code IN WORLD_BANK_WDI.COUNTRY_SUMMARY.country_code%TYPE,
    p_topic        IN WORLD_BANK_WDI.SERIES_SUMMARY.topic%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_country_name WORLD_BANK_WDI.COUNTRY_SUMMARY.short_name%TYPE;

    -- Explicit cursor required: pull series in a topic (row-limited)
    CURSOR cur_series(
      cp_topic WORLD_BANK_WDI.SERIES_SUMMARY.topic%TYPE
    ) IS
      WITH ranked AS (
        SELECT ss.series_code,
               ss.indicator_name,
               ROW_NUMBER() OVER (ORDER BY ss.series_code) AS rn
          FROM WORLD_BANK_WDI.SERIES_SUMMARY ss
         WHERE ss.topic = cp_topic
      )
      SELECT r.series_code,
             r.indicator_name
        FROM ranked r
       WHERE r.rn <= co_report_limit
       ORDER BY r.series_code;

    lv_latest_year  WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;
    lv_latest_value WORLD_BANK_WDI.INDICATORS_DATA.value%TYPE;

    lv_series_count PLS_INTEGER := 0;
  BEGIN
    -- Basic input validation
    IF p_country_code IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input country code is required.');
      RETURN;
    END IF;

    IF p_topic IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input topic is required.');
      RETURN;
    END IF;

    -- Validate country code (single-row lookup)
    SELECT cs.short_name
      INTO lv_country_name
      FROM WORLD_BANK_WDI.COUNTRY_SUMMARY cs
     WHERE cs.country_code = p_country_code;

    DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name || ' (' || p_country_code || ')');
    DBMS_OUTPUT.PUT_LINE('Topic: ' || p_topic);

    -- Iterate series via explicit named cursor FOR loop
    FOR rec IN cur_series(p_topic) LOOP
      lv_series_count := lv_series_count + 1;

      lv_latest_year  := NULL;
      lv_latest_value := NULL;

      -- Find latest year with a numeric value for this country & series.
      -- VALUE is stored as VARCHAR2, so we validate numeric format before converting.
      BEGIN
        SELECT x.year,
               x.value
          INTO lv_latest_year,
               lv_latest_value
          FROM (
                SELECT id.year,
                       id.value,
                       ROW_NUMBER() OVER (ORDER BY TO_NUMBER(id.year) DESC) AS rn
                  FROM WORLD_BANK_WDI.INDICATORS_DATA id
                 WHERE id.country_code = p_country_code
                   AND id.indicator_code = rec.series_code
                   AND id.value IS NOT NULL
                   AND REGEXP_LIKE(id.value, '^[-+]?(\d+(\.\d*)?|\.\d+)([eE][-+]?\d+)?$')
                   AND REGEXP_LIKE(id.year, '^\d+$')
               ) x
         WHERE x.rn = 1;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_latest_year  := NULL;
          lv_latest_value := NULL;
        WHEN VALUE_ERROR THEN
          DBMS_OUTPUT.PUT_LINE('Numeric conversion error while processing values.');
          lv_latest_year  := NULL;
          lv_latest_value := NULL;
      END;

      DBMS_OUTPUT.PUT_LINE(
        'Series: ' || rec.series_code || ' | ' || SUBSTR(rec.indicator_name, 1, 80) ||
        ' | Latest year: ' || NVL(lv_latest_year, 'N/A') ||
        ' | Value: ' || NVL(lv_latest_value, 'N/A')
      );
    END LOOP;

    IF lv_series_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No series found for topic.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Numeric conversion error while processing values.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_country_topic_latest;
END wdi_reporting_pkg;
/

