question:
Build a reusable stored procedure that prints a small CPI-U (Consumer Price Index) report for a given area and item. The procedure must:
Validate inputs (area and item names can't be null/blank, year must be 4 digits).
For the requested year and the previous year, print up to 15 monthly CPI values (sorted newest to oldest) from the CPI_U table.
Include a simple year-over-year change (current year annual average minus prior year annual average) and categorize it as INCREASED / DECREASED / UNCHANGED using control flow.
Gracefully handle cases where the inputs are valid but the data doesn't exist.

Requirements:
Procedure Name: cpi_area_item_report
Parameters:
p_area_name IN BLS.CPI_U.area_name%TYPE
p_item_name IN BLS.CPI_U.item_name%TYPE
p_year IN BLS.CPI_U.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('CPI-U Report');
DBMS_OUTPUT.PUT_LINE('Area: ' || p_area_name);
DBMS_OUTPUT.PUT_LINE('Item: ' || p_item_name);
DBMS_OUTPUT.PUT_LINE('Year: ' || p_year);
DBMS_OUTPUT.PUT_LINE('YoY annual avg change: ' || TO_CHAR(lv_yoy_change));
DBMS_OUTPUT.PUT_LINE('YoY trend: INCREASED');
DBMS_OUTPUT.PUT_LINE('YoY trend: DECREASED');
DBMS_OUTPUT.PUT_LINE('YoY trend: UNCHANGED');
DBMS_OUTPUT.PUT_LINE('Monthly values (most recent first):');
DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.c_date, 'YYYY-MM-DD') || ' | ' || rec.period || ' | ' || rec.value);
DBMS_OUTPUT.PUT_LINE('No data found.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid input value.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE cpi_area_item_report(
  p_area_name IN BLS.CPI_U.area_name%TYPE,
  p_item_name IN BLS.CPI_U.item_name%TYPE,
  p_year      IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year_num    NUMBER;
  lv_prev_year   BLS.CPI_U.year%TYPE;

  lv_avg_curr    NUMBER;
  lv_avg_prev    NUMBER;
  lv_yoy_change  NUMBER;

  lv_found_rows  PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF TRIM(p_area_name) IS NULL OR TRIM(p_item_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  lv_year_num := TO_NUMBER(TRIM(p_year));
  IF LENGTH(TRIM(p_year)) <> 4 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  lv_prev_year := TO_CHAR(lv_year_num - 1);

  DBMS_OUTPUT.PUT_LINE('CPI-U Report');
  DBMS_OUTPUT.PUT_LINE('Area: ' || p_area_name);
  DBMS_OUTPUT.PUT_LINE('Item: ' || p_item_name);
  DBMS_OUTPUT.PUT_LINE('Year: ' || p_year);

  -- Annual averages for YoY change
  SELECT AVG(TO_NUMBER(c.value))
    INTO lv_avg_curr
    FROM BLS.CPI_U c
   WHERE c.area_name = p_area_name
     AND c.item_name = p_item_name
     AND c.year = p_year
     AND c.period LIKE 'M%'
     AND c.value IS NOT NULL;

  SELECT AVG(TO_NUMBER(c.value))
    INTO lv_avg_prev
    FROM BLS.CPI_U c
   WHERE c.area_name = p_area_name
     AND c.item_name = p_item_name
     AND c.year = lv_prev_year
     AND c.period LIKE 'M%'
     AND c.value IS NOT NULL;

  lv_yoy_change := lv_avg_curr - lv_avg_prev;
  DBMS_OUTPUT.PUT_LINE('YoY annual avg change: ' || TO_CHAR(lv_yoy_change));

  IF lv_yoy_change > 0 THEN
    DBMS_OUTPUT.PUT_LINE('YoY trend: INCREASED');
  ELSIF lv_yoy_change < 0 THEN
    DBMS_OUTPUT.PUT_LINE('YoY trend: DECREASED');
  ELSE
    DBMS_OUTPUT.PUT_LINE('YoY trend: UNCHANGED');
  END IF;

  DBMS_OUTPUT.PUT_LINE('Monthly values (most recent first):');

  -- Print up to 15 months across the two-year window (implicit cursor loop)
  FOR rec IN (
    SELECT c.c_date, c.period, c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND c.year IN (p_year, lv_prev_year)
       AND c.period LIKE 'M%'
     ORDER BY c.c_date DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_found_rows := lv_found_rows + 1;
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.c_date, 'YYYY-MM-DD') || ' | ' || rec.period || ' | ' || rec.value);
  END LOOP;

  IF lv_found_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_area_item_report;
/

