CREATE OR REPLACE PROCEDURE report_county_natality(
  p_year             IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.year%TYPE,
  p_county_name      IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE,
  p_births_threshold IN NUMBER
) IS
  co_row_limit CONSTANT PLS_INTEGER := 1; -- Single-county lookup for deterministic reporting

  lv_county   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.county_of_residence%TYPE;
  lv_births   NUMBER;
  lv_avg_age  NUMBER;
  lv_class    VARCHAR2(20);
BEGIN
  DBMS_OUTPUT.PUT_LINE('County Natality Report');
  DBMS_OUTPUT.PUT_LINE('Year=' || TO_CHAR(p_year, 'YYYY') || ', County=' || NVL(p_county_name, 'NULL'));

  -- Input validation
  IF p_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year is required.');
    RETURN;
  ELSIF p_county_name IS NULL OR TRIM(p_county_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: county name is required.');
    RETURN;
  ELSIF p_births_threshold IS NULL OR p_births_threshold < 0 THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: births threshold must be >= 0.');
    RETURN;
  END IF;

  -- Retrieve one matching county record for the requested year
  SELECT t.county_of_residence,
         TO_NUMBER(t.births),
         TO_NUMBER(t.ave_age_of_mother)
    INTO lv_county, lv_births, lv_avg_age
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY t
   WHERE t.year = p_year
     AND UPPER(t.county_of_residence) = UPPER(TRIM(p_county_name))
     AND ROWNUM <= co_row_limit;

  -- Classify based on threshold
  IF lv_births >= p_births_threshold THEN
    lv_class := 'HIGH_BIRTHS';
  ELSE
    lv_class := 'LOW_BIRTHS';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Result: county=' || lv_county || ', births=' || TO_CHAR(lv_births) || ', avg_age_mother=' || TO_CHAR(lv_avg_age));
  DBMS_OUTPUT.PUT_LINE('Classification=' || lv_class);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_county_natality;
/

CREATE OR REPLACE PROCEDURE report_region_station_availability(
  p_region_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region_id      SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.region_id%TYPE;
  lv_station_name   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
  lv_capacity_txt   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.capacity%TYPE;
  lv_bikes_txt      SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE;
  lv_docks_txt      SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_docks_available%TYPE;

  lv_capacity     NUMBER;
  lv_bikes_avail  NUMBER;
  lv_docks_avail  NUMBER;
  lv_pct_avail    NUMBER;

  lv_sum_pct      NUMBER := 0;
  lv_rows_printed PLS_INTEGER := 0;
  lv_avg_pct      NUMBER;

  lv_region_name_norm SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
BEGIN
  lv_region_name_norm := TRIM(p_region_name);

  IF lv_region_name_norm IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Region: ' || p_region_name);

  SELECT r.region_id
    INTO lv_region_id
    FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
   WHERE r.name = lv_region_name_norm;

  DBMS_OUTPUT.PUT_LINE('Snapshot (top ' || co_report_limit || ' stations by bikes available)');
  DBMS_OUTPUT.PUT_LINE(RPAD('Station', 35) || ' ' || LPAD('Cap', 5) || ' ' || LPAD('Bikes', 5) || ' ' || LPAD('Docks', 5) || ' ' || LPAD('%Avail', 7));

  FOR rec IN (
    WITH station_rows AS (
      SELECT si.name AS station_name,
             si.capacity AS capacity_txt,
             ss.num_bikes_available AS bikes_txt,
             ss.num_docks_available AS docks_txt
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
        INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
          ON ss.station_id = si.station_id
       WHERE si.region_id = lv_region_id
    ), ranked AS (
      SELECT sr.station_name,
             sr.capacity_txt,
             sr.bikes_txt,
             sr.docks_txt,
             ROW_NUMBER() OVER (
               ORDER BY TO_NUMBER(sr.bikes_txt) DESC, sr.station_name ASC
             ) AS rn
        FROM station_rows sr
    )
    SELECT rnk.station_name,
           rnk.capacity_txt,
           rnk.bikes_txt,
           rnk.docks_txt
      FROM ranked rnk
     WHERE rnk.rn <= co_report_limit
     ORDER BY TO_NUMBER(rnk.bikes_txt) DESC, rnk.station_name ASC
  ) LOOP
    lv_station_name := rec.station_name;
    lv_capacity_txt := rec.capacity_txt;
    lv_bikes_txt    := rec.bikes_txt;
    lv_docks_txt    := rec.docks_txt;

    lv_capacity    := TO_NUMBER(lv_capacity_txt);
    lv_bikes_avail := TO_NUMBER(lv_bikes_txt);
    lv_docks_avail := TO_NUMBER(lv_docks_txt);

    IF lv_capacity = 0 THEN
      lv_pct_avail := 0;
    ELSE
      lv_pct_avail := ROUND((lv_bikes_avail / lv_capacity) * 100, 1);
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(lv_station_name, 35) || ' ' ||
      LPAD(lv_capacity, 5) || ' ' ||
      LPAD(lv_bikes_avail, 5) || ' ' ||
      LPAD(lv_docks_avail, 5) || ' ' ||
      LPAD(TO_CHAR(lv_pct_avail, '990.0'), 7)
    );

    lv_rows_printed := lv_rows_printed + 1;
    lv_sum_pct := lv_sum_pct + lv_pct_avail;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
    RETURN;
  END IF;

  lv_avg_pct := ROUND(lv_sum_pct / lv_rows_printed, 1);
  DBMS_OUTPUT.PUT_LINE('Average % availability across ' || lv_rows_printed || ' station(s): ' || TO_CHAR(lv_avg_pct, '990.0'));

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_region_station_availability;
/

