question:
Build a reusable procedure that prints a small “patient encounter cost snapshot” for a given patient id. The snapshot should show the patient’s full name, the number of encounters for that patient, the average total claim cost across those encounters (rounded to 2 decimals) and a label describing whether the patient’s average claim cost is HIGH (>= 1000) or NORMAL (< 1000). Limit any detailed listing to 15 rows maximum.

Requirements:
Procedure Name: report_patient_encounter_costs
Parameters:
p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient_full_name);
DBMS_OUTPUT.PUT_LINE('Encounter count: ' || lv_encounter_count);
DBMS_OUTPUT.PUT_LINE('Average claim cost: ' || TO_CHAR(lv_avg_claim_cost, 'FM9999999990D00'));
DBMS_OUTPUT.PUT_LINE('Cost category: ' || lv_cost_category);
DBMS_OUTPUT.PUT_LINE('Top encounters by total claim cost (up to ' || co_report_limit || ' rows):');
DBMS_OUTPUT.PUT_LINE('  Encounter ID=' || rec.id || ', Class=' || rec.encounterclass || ', Total=' || TO_CHAR(rec.total_claim_cost, 'FM9999999990D00'));
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_patient_encounter_costs(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_patient_full_name SYNTHEA.PATIENTS.first%TYPE;
  lv_encounter_count   PLS_INTEGER;
  lv_avg_claim_cost    SYNTHEA.ENCOUNTERS.total_claim_cost%TYPE;
  lv_cost_category     VARCHAR2(10);
BEGIN
  -- Patient identity (single-row fetch)
  SELECT p.first || ' ' || p.last
    INTO lv_patient_full_name
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = p_patient_id;

  -- Summary metrics
  SELECT COUNT(*), ROUND(AVG(e.total_claim_cost), 2)
    INTO lv_encounter_count, lv_avg_claim_cost
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.patient = p_patient_id;

  -- Simple categorization
  IF lv_avg_claim_cost >= 1000 THEN
    lv_cost_category := 'HIGH';
  ELSE
    lv_cost_category := 'NORMAL';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient_full_name);
  DBMS_OUTPUT.PUT_LINE('Encounter count: ' || lv_encounter_count);
  DBMS_OUTPUT.PUT_LINE('Average claim cost: ' || TO_CHAR(lv_avg_claim_cost, 'FM9999999990D00'));
  DBMS_OUTPUT.PUT_LINE('Cost category: ' || lv_cost_category);

  DBMS_OUTPUT.PUT_LINE('Top encounters by total claim cost (up to ' || co_report_limit || ' rows):');

  -- Inline FOR loop (implicit cursor) for a small top-N listing
  FOR rec IN (
    SELECT e.id,
           e.encounterclass,
           e.total_claim_cost
      FROM SYNTHEA.ENCOUNTERS e
     WHERE e.patient = p_patient_id
     ORDER BY e.total_claim_cost DESC, e.id
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      '  Encounter ID=' || rec.id ||
      ', Class=' || rec.encounterclass ||
      ', Total=' || TO_CHAR(rec.total_claim_cost, 'FM9999999990D00')
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_patient_encounter_costs;
/

CREATE OR REPLACE PROCEDURE report_country_vital_trends(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
  p_start_year   IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE,
  p_end_year     IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_start_year_num NUMBER;
  lv_end_year_num   NUMBER;

  lv_rank  PLS_INTEGER := 0;
  lv_label VARCHAR2(30);

  CURSOR c_trends(
    cp_country_name IN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA.country_name%TYPE,
    cp_start_year   IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE,
    cp_end_year     IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE
  ) IS
    WITH base AS (
      SELECT
        mp.year AS yr,
        TO_NUMBER(mp.midyear_population)      AS pop_num,
        TO_NUMBER(bd.growth_rate)             AS growth_rate_num,
        TO_NUMBER(bd.crude_birth_rate)        AS cbr_num,
        TO_NUMBER(asfr.total_fertility_rate)  AS tfr_num
      FROM CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION mp
      INNER JOIN CENSUS_BUREAU_INTERNATIONAL.BIRTH_DEATH_GROWTH_RATES bd
        ON bd.country_name = mp.country_name
       AND bd.year = mp.year
      INNER JOIN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES asfr
        ON asfr.country_name = mp.country_name
       AND asfr.year = mp.year
      INNER JOIN CENSUS_BUREAU_INTERNATIONAL.COUNTRY_NAMES_AREA cna
        ON cna.country_name = mp.country_name
      WHERE mp.country_name = cp_country_name
        AND mp.year BETWEEN cp_start_year AND cp_end_year
    )
    SELECT
      b.yr,
      b.pop_num,
      b.growth_rate_num,
      b.cbr_num,
      b.tfr_num
    FROM (
      SELECT
        base.yr,
        base.pop_num,
        base.growth_rate_num,
        base.cbr_num,
        base.tfr_num,
        ROW_NUMBER() OVER (ORDER BY base.growth_rate_num DESC) AS rn
      FROM base
    ) b
    WHERE b.rn <= co_report_limit
    ORDER BY b.rn;

  lr_row c_trends%ROWTYPE;

  FUNCTION is_4_digit_year(p_year IN CENSUS_BUREAU_INTERNATIONAL.MIDYEAR_POPULATION.year%TYPE)
    RETURN BOOLEAN
  IS
  BEGIN
    IF p_year IS NULL OR LENGTH(p_year) <> 4 THEN
      RETURN FALSE;
    END IF;

    -- Will raise VALUE_ERROR if not numeric; caller handles.
    IF TO_NUMBER(p_year) < 0 THEN
      RETURN FALSE;
    END IF;

    RETURN TRUE;
  END is_4_digit_year;

BEGIN
  -- Validate year parameters.
  IF NOT is_4_digit_year(p_start_year) OR NOT is_4_digit_year(p_end_year) THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year range. Provide 4-digit numeric years and ensure start <= end.');
    RETURN;
  END IF;

  lv_start_year_num := TO_NUMBER(p_start_year);
  lv_end_year_num   := TO_NUMBER(p_end_year);

  IF lv_start_year_num > lv_end_year_num THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year range. Provide 4-digit numeric years and ensure start <= end.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Country Vital Trends Report for ' || p_country_name || ' (' || p_start_year || '-' || p_end_year || ')');
  DBMS_OUTPUT.PUT_LINE('Rows are ranked by Growth Rate (highest first). Max rows = ' || co_report_limit);

  OPEN c_trends(p_country_name, p_start_year, p_end_year);
  LOOP
    FETCH c_trends INTO lr_row;
    EXIT WHEN c_trends%NOTFOUND;

    lv_rank := lv_rank + 1;

    -- Growth label classification.
    IF lr_row.growth_rate_num >= 2 THEN
      lv_label := 'HIGH_GROWTH';
    ELSIF lr_row.growth_rate_num >= 1 THEN
      lv_label := 'MODERATE_GROWTH';
    ELSE
      lv_label := 'LOW_GROWTH';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Rank ' || lv_rank || ': Year=' || lr_row.yr ||
      ', GrowthRate=' || TO_CHAR(lr_row.growth_rate_num) ||
      ', Label=' || lv_label ||
      ', Pop=' || TO_CHAR(lr_row.pop_num) ||
      ', CBR=' || TO_CHAR(lr_row.cbr_num) ||
      ', TFR=' || TO_CHAR(lr_row.tfr_num)
    );
  END LOOP;

  CLOSE c_trends;

  IF lv_rank = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF c_trends%ISOPEN THEN
      CLOSE c_trends;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF c_trends%ISOPEN THEN
      CLOSE c_trends;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    IF c_trends%ISOPEN THEN
      CLOSE c_trends;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Invalid year range. Provide 4-digit numeric years and ensure start <= end.');
  WHEN OTHERS THEN
    IF c_trends%ISOPEN THEN
      CLOSE c_trends;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_vital_trends;
/

