CREATE OR REPLACE PROCEDURE pr_circuit_country_spotlight(
  p_country IN F1.CIRCUITS.country%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country F1.CIRCUITS.country%TYPE;
  lv_rows    PLS_INTEGER := 0;
BEGIN
  IF p_country IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Country is required.');
    RETURN;
  END IF;

  lv_country := TRIM(p_country);

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country);

  FOR rec IN (
    SELECT c.name,
           c.circuit_ref,
           ce.last_race_year
      FROM F1.CIRCUITS c
      LEFT OUTER JOIN F1.CIRCUITS_EXT ce
        ON ce.circuit_id = c.circuit_id
     WHERE c.country = lv_country
       AND ROWNUM <= co_report_limit
     ORDER BY c.name
  ) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(
      'Circuit: ' || rec.name || ' (ref=' || rec.circuit_ref || '), last_race_year=' || rec.last_race_year
    );
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No circuits found for the requested country.');
    -- Force the NO_DATA_FOUND handler so the same message is also covered via exception handling.
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No circuits found for the requested country.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END pr_circuit_country_spotlight;
/

question:
Build a one-off analysis script for an economist who wants a quick sanity check on CPI levels. The analyst will provide an area name, an item name, and a year.

Your script should:
- Validate the inputs and stop gracefully if any are NULL.
- Find the CPI series for that area/item combination and the requested year.
- Produce a short report (max 15 rows) listing the period, the CPI value, and the month-over-month change versus the prior period (based on date ordering).
- Include a cross-check count showing how many rows exist in the alternate CPI table for the same filters, so the analyst can see whether the two sources are aligned.
- Handle cases where no rows exist, and also handle situations where the area/item filter is ambiguous.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Input area_name=' || lv_area_name || ', item_name=' || lv_item_name || ', year=' || lv_year);
DBMS_OUTPUT.PUT_LINE('Alternate table row count (BLS.C_CPI_U)=' || lv_alt_cnt);
DBMS_OUTPUT.PUT_LINE('Report (most recent first), max rows=' || co_report_limit);
DBMS_OUTPUT.PUT_LINE('period=' || r.period || ', c_date=' || TO_CHAR(r.c_date, 'YYYY-MM-DD') || ', value=' || r.value_num || ', mom_change=' || NVL(TO_CHAR(r.mom_change), 'N/A'));
DBMS_OUTPUT.PUT_LINE('No CPI rows found for the given filters.');
DBMS_OUTPUT.PUT_LINE('Input validation failed: area, item, and year are required.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No CPI rows found for the given filters.';
WHEN TOO_MANY_ROWS THEN: 'Multiple series matched the area/item filter. Refine your inputs.';
WHEN VALUE_ERROR THEN: 'Bad numeric CPI value encountered.';
WHEN OTHERS THEN: 'Unexpected error.';

reference_answer:
DECLARE
  -- Inputs (edit these as needed for analysis runs)
  lv_area_name  BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name  BLS.CPI_U.item_name%TYPE := 'All items';
  lv_year       BLS.CPI_U.year%TYPE := '2020';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_alt_cnt NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Input area_name=' || lv_area_name || ', item_name=' || lv_item_name || ', year=' || lv_year);

  IF lv_area_name IS NULL OR lv_item_name IS NULL OR lv_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: area, item, and year are required.');
    RETURN;
  END IF;

  -- Cross-check count in alternate CPI table for the same filters
  SELECT COUNT(*)
    INTO lv_alt_cnt
    FROM BLS.C_CPI_U c
   WHERE c.area_name = lv_area_name
     AND c.item_name = lv_item_name
     AND c.year = lv_year;

  DBMS_OUTPUT.PUT_LINE('Alternate table row count (BLS.C_CPI_U)=' || lv_alt_cnt);
  DBMS_OUTPUT.PUT_LINE('Report (most recent first), max rows=' || co_report_limit);

  -- Emit up to 15 rows with month-over-month change based on date ordering
  FOR r IN (
    WITH base AS (
      SELECT u.period,
             u.c_date,
             TO_NUMBER(u.value) AS value_num,
             LAG(TO_NUMBER(u.value)) OVER (ORDER BY u.c_date) AS prev_value
        FROM BLS.CPI_U u
       WHERE u.area_name = lv_area_name
         AND u.item_name = lv_item_name
         AND u.year = lv_year
    ), calc AS (
      SELECT b.period,
             b.c_date,
             b.value_num,
             (b.value_num - b.prev_value) AS mom_change
        FROM base b
    )
    SELECT c.period,
           c.c_date,
           c.value_num,
           c.mom_change
      FROM calc c
     ORDER BY c.c_date DESC
     FETCH FIRST 15 ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'period=' || r.period ||
      ', c_date=' || TO_CHAR(r.c_date, 'YYYY-MM-DD') ||
      ', value=' || r.value_num ||
      ', mom_change=' || NVL(TO_CHAR(r.mom_change), 'N/A')
    );
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No CPI rows found for the given filters.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple series matched the area/item filter. Refine your inputs.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric CPI value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

