CREATE OR REPLACE PACKAGE bls_cpi_pkg IS
  PROCEDURE report_cpi_vs_chained(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE,
    p_year_from IN BLS.CPI_U.year%TYPE,
    p_year_to   IN BLS.CPI_U.year%TYPE
  );
END bls_cpi_pkg;
/

CREATE OR REPLACE PACKAGE BODY bls_cpi_pkg IS
  PROCEDURE report_cpi_vs_chained(
    p_area_name IN BLS.CPI_U.area_name%TYPE,
    p_item_name IN BLS.CPI_U.item_name%TYPE,
    p_year_from IN BLS.CPI_U.year%TYPE,
    p_year_to   IN BLS.CPI_U.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_series_id   BLS.CPI_U.series_id%TYPE;
    lv_rows_printed PLS_INTEGER := 0;

    CURSOR cur_cpi(
      cp_series_id BLS.CPI_U.series_id%TYPE,
      cp_year_from BLS.CPI_U.year%TYPE,
      cp_year_to   BLS.CPI_U.year%TYPE
    ) IS
      SELECT c.series_id,
             c.year,
             c.period,
             c.value,
             c.c_date
        FROM BLS.CPI_U c
       WHERE c.series_id = cp_series_id
         AND c.year BETWEEN cp_year_from AND cp_year_to
         AND c.period LIKE 'M%'
       ORDER BY c.year DESC, c.period DESC;

    lr_cpi cur_cpi%ROWTYPE;

    lv_ccpi_value  BLS.C_CPI_U.value%TYPE;
    lv_note        VARCHAR2(50);

    lv_dummy_num   NUMBER;
  BEGIN
    IF p_area_name IS NULL OR p_item_name IS NULL OR p_year_from IS NULL OR p_year_to IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No CPI-U rows found for the requested filters.');
      RETURN;
    END IF;

    IF p_year_from > p_year_to THEN
      DBMS_OUTPUT.PUT_LINE('No CPI-U rows found for the requested filters.');
      RETURN;
    END IF;

    SELECT series_id
      INTO lv_series_id
      FROM (
        SELECT c.series_id
          FROM BLS.CPI_U c
         WHERE c.area_name = p_area_name
           AND c.item_name = p_item_name
           AND c.year BETWEEN p_year_from AND p_year_to
           AND c.period LIKE 'M%'
         GROUP BY c.series_id
         ORDER BY COUNT(*) DESC, c.series_id
      )
     WHERE ROWNUM = 1;

    DBMS_OUTPUT.PUT_LINE('Detected SERIES_ID: ' || lv_series_id);
    DBMS_OUTPUT.PUT_LINE('Report (latest first). Max rows = ' || co_report_limit);

    OPEN cur_cpi(lv_series_id, p_year_from, p_year_to);
    LOOP
      FETCH cur_cpi INTO lr_cpi;
      EXIT WHEN cur_cpi%NOTFOUND;

      lv_rows_printed := lv_rows_printed + 1;

      IF lv_rows_printed > co_report_limit THEN
        EXIT;
      END IF;

      lv_ccpi_value := NULL;
      lv_note := NULL;

      BEGIN
        SELECT cc.value
          INTO lv_ccpi_value
          FROM BLS.C_CPI_U cc
         WHERE cc.area_name = p_area_name
           AND cc.item_name = p_item_name
           AND cc.year = lr_cpi.year
           AND cc.period = lr_cpi.period
           AND ROWNUM = 1;

        BEGIN
          lv_dummy_num := TO_NUMBER(lv_ccpi_value);
          lv_note := 'FOUND';
        EXCEPTION
          WHEN VALUE_ERROR THEN
            lv_note := 'NON_NUMERIC';
        END;

      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_ccpi_value := NULL;
          lv_note := 'MISSING';
        WHEN TOO_MANY_ROWS THEN
          lv_note := 'FOUND';
      END;

      DBMS_OUTPUT.PUT_LINE(
        TO_CHAR(lr_cpi.c_date, 'YYYY-MM-DD') || ' | ' || lr_cpi.year || ' ' || lr_cpi.period ||
        ' | CPI_U=' || lr_cpi.value || ' | C_CPI_U=' || lv_ccpi_value || ' | note=' || lv_note
      );
    END LOOP;
    CLOSE cur_cpi;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No CPI-U rows found for the requested filters.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Bad numeric value encountered.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END report_cpi_vs_chained;
END bls_cpi_pkg;
/

