CREATE OR REPLACE PROCEDURE cpi_trend_report(
  p_area_name  IN BLS.CPI_U.area_name%TYPE,
  p_item_name  IN BLS.CPI_U.item_name%TYPE,
  p_start_year IN BLS.CPI_U.year%TYPE,
  p_end_year   IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_start_date  BLS.CPI_U.c_date%TYPE;
  lv_end_date    BLS.CPI_U.c_date%TYPE;

  lv_start_value NUMBER;
  lv_end_value   NUMBER;

  lv_change      NUMBER;
  lv_pct_change  NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI Trend Report');
  DBMS_OUTPUT.PUT_LINE('Area: ' || p_area_name);
  DBMS_OUTPUT.PUT_LINE('Item: ' || p_item_name);
  DBMS_OUTPUT.PUT_LINE('Years: ' || p_start_year || ' to ' || p_end_year);

  -- Earliest observation in the year range
  SELECT t.c_date,
         TO_NUMBER(t.value)
    INTO lv_start_date,
         lv_start_value
    FROM (
          SELECT c.c_date,
                 c.value
            FROM BLS.CPI_U c
           WHERE c.area_name = p_area_name
             AND c.item_name = p_item_name
             AND c.year BETWEEN p_start_year AND p_end_year
           ORDER BY c.c_date ASC
         ) t
   WHERE ROWNUM = 1;

  -- Latest observation in the year range
  SELECT t.c_date,
         TO_NUMBER(t.value)
    INTO lv_end_date,
         lv_end_value
    FROM (
          SELECT c.c_date,
                 c.value
            FROM BLS.CPI_U c
           WHERE c.area_name = p_area_name
             AND c.item_name = p_item_name
             AND c.year BETWEEN p_start_year AND p_end_year
           ORDER BY c.c_date DESC
         ) t
   WHERE ROWNUM = 1;

  lv_change := lv_end_value - lv_start_value;

  IF lv_start_value = 0 THEN
    lv_pct_change := NULL;
  ELSE
    lv_pct_change := ROUND((lv_change / lv_start_value) * 100, 2);
  END IF;

  DBMS_OUTPUT.PUT_LINE('Start: ' || TO_CHAR(lv_start_date, 'YYYY-MM-DD') || ' value=' || TO_CHAR(lv_start_value));
  DBMS_OUTPUT.PUT_LINE('End:   ' || TO_CHAR(lv_end_date, 'YYYY-MM-DD') || ' value=' || TO_CHAR(lv_end_value));
  DBMS_OUTPUT.PUT_LINE('Change: ' || TO_CHAR(lv_change));
  DBMS_OUTPUT.PUT_LINE('Percent change: ' || TO_CHAR(lv_pct_change) || '%');

  DBMS_OUTPUT.PUT_LINE('Sample observations (up to ' || TO_CHAR(co_report_limit) || ' rows):');

  FOR r IN (
    SELECT c.c_date,
           c.period,
           c.value
      FROM BLS.CPI_U c
     WHERE c.area_name = p_area_name
       AND c.item_name = p_item_name
       AND c.year BETWEEN p_start_year AND p_end_year
     ORDER BY c.c_date ASC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(r.c_date, 'YYYY-MM-DD') || ' period=' || r.period || ' value=' || r.value);
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END cpi_trend_report;
/

