DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  -- Optional input: set to a season id, or keep NULL to auto-pick the most common season
  p_season_id IPL.MATCH.season_id%TYPE := NULL;

  lv_season_id IPL.MATCH.season_id%TYPE;
  lv_rows      PLS_INTEGER := 0;
BEGIN
  -- Determine which season to report
  IF p_season_id IS NOT NULL THEN
    lv_season_id := p_season_id;
  ELSE
    SELECT season_id
      INTO lv_season_id
      FROM (
            SELECT m.season_id
              FROM IPL.MATCH m
             GROUP BY m.season_id
             ORDER BY COUNT(*) DESC, m.season_id
           )
     WHERE ROWNUM = 1;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Season used: ' || lv_season_id);
  DBMS_OUTPUT.PUT_LINE('Match report (up to ' || co_report_limit || ' rows):');

  FOR rec IN (
    SELECT *
      FROM (
            SELECT m.match_id,
                   m.match_date,
                   m.venue,
                   NVL(t.name, 'UNKNOWN') AS winner_team_name,
                   NVL(p.player_name, 'UNKNOWN') AS mom_player_name
              FROM IPL.MATCH m
              LEFT JOIN IPL.TEAM t
                ON t.team_id = m.match_winner
              LEFT JOIN IPL.PLAYER p
                ON p.player_id = m.man_of_the_match
             WHERE m.season_id = lv_season_id
             ORDER BY m.match_date, m.match_id
           )
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_rows := lv_rows + 1;
    DBMS_OUTPUT.PUT_LINE(
      'MATCH_ID=' || rec.match_id ||
      ' | DATE=' || TO_CHAR(rec.match_date, 'YYYY-MM-DD') ||
      ' | VENUE=' || rec.venue ||
      ' | WINNER=' || rec.winner_team_name ||
      ' | MOM=' || rec.mom_player_name
    );
  END LOOP;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No matches found for season.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

