CREATE OR REPLACE PROCEDURE report_station_utilization(
  p_landmark IN SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Guard clause for required input
  IF p_landmark IS NULL OR TRIM(p_landmark) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Landmark is required.');
    RETURN;
  END IF;

  FOR r IN (
    WITH latest_status AS (
      SELECT
        bs.station_id,
        bs.time AS status_time,
        ROW_NUMBER() OVER (
          PARTITION BY bs.station_id
          ORDER BY bs.time DESC
        ) AS rn,
        bs.bikes_available,
        bs.docks_available
      FROM SAN_FRANCISCO.BIKESHARE_STATUS bs
    )
    SELECT
      st.name AS station_name,
      ls.status_time,
      TO_NUMBER(ls.bikes_available) AS bikes_avail,
      TO_NUMBER(ls.docks_available) AS docks_avail,
      (TO_NUMBER(ls.bikes_available) + TO_NUMBER(ls.docks_available)) AS capacity,
      CASE
        WHEN (TO_NUMBER(ls.bikes_available) + TO_NUMBER(ls.docks_available)) = 0 THEN 'UNKNOWN'
        WHEN TO_NUMBER(ls.bikes_available) / (TO_NUMBER(ls.bikes_available) + TO_NUMBER(ls.docks_available)) >= 0.80 THEN 'HIGH'
        WHEN TO_NUMBER(ls.bikes_available) / (TO_NUMBER(ls.bikes_available) + TO_NUMBER(ls.docks_available)) >= 0.40 THEN 'MEDIUM'
        ELSE 'LOW'
      END AS band
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS st
    INNER JOIN latest_status ls
      ON ls.station_id = st.station_id
     AND ls.rn = 1
    WHERE st.landmark = p_landmark
    ORDER BY st.name
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    IF lv_rows_printed > co_report_limit THEN
      EXIT;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Station: ' || r.station_name ||
      ' | Time: ' || TO_CHAR(r.status_time, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | Bikes: ' || r.bikes_avail ||
      ' | Docks: ' || r.docks_avail ||
      ' | Capacity: ' || r.capacity ||
      ' | Band: ' || r.band
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No stations found for landmark.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad numeric data encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_station_utilization;
/

CREATE OR REPLACE PROCEDURE report_latest_cpi_snapshot(
  p_area_name      IN BLS.CPI_U.area_name%TYPE,
  p_item_name_like IN BLS.CPI_U.item_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_latest_cdate BLS.CPI_U.c_date%TYPE;
  lv_max_value_num NUMBER;
BEGIN
  -- Guard clauses: do not query with missing filters
  IF p_area_name IS NULL OR p_item_name_like IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: AREA_NAME and ITEM_NAME must be provided.');
    RETURN;
  END IF;

  -- Find latest available month for the given filters
  SELECT MAX(cu.c_date)
    INTO lv_latest_cdate
    FROM BLS.CPI_U cu
   WHERE cu.area_name = p_area_name
     AND cu.item_name LIKE p_item_name_like;

  IF lv_latest_cdate IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the supplied filters.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Latest month: ' || TO_CHAR(lv_latest_cdate, 'YYYY-MM-DD'));
  DBMS_OUTPUT.PUT_LINE('CPI Snapshot (top ' || co_report_limit || ' rows)');

  -- Determine max numeric value for classification (forces numeric conversion)
  SELECT MAX(TO_NUMBER(cu.value))
    INTO lv_max_value_num
    FROM BLS.CPI_U cu
   WHERE cu.area_name = p_area_name
     AND cu.item_name LIKE p_item_name_like
     AND cu.c_date = lv_latest_cdate;

  FOR rec IN (
    SELECT cu.area_name,
           cu.item_name,
           cu.period,
           TO_NUMBER(cu.value) AS value_num
      FROM BLS.CPI_U cu
     WHERE cu.area_name = p_area_name
       AND cu.item_name LIKE p_item_name_like
       AND cu.c_date = lv_latest_cdate
     ORDER BY TO_NUMBER(cu.value) DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'AREA=' || rec.area_name ||
      ' | ITEM=' || rec.item_name ||
      ' | PERIOD=' || rec.period ||
      ' | VALUE=' || TO_CHAR(rec.value_num)
    );
  END LOOP;

  -- Simple control flow classification
  IF lv_max_value_num >= 300 THEN
    DBMS_OUTPUT.PUT_LINE('CPI level classification: High CPI level');
  ELSE
    DBMS_OUTPUT.PUT_LINE('CPI level classification: Normal CPI level');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the supplied filters.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Invalid number encountered in CPI value conversion.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_latest_cpi_snapshot;
/

CREATE OR REPLACE PROCEDURE report_solution_insights(
  p_solution_name    IN STACKING.SOLUTION.name%TYPE,
  p_solution_version IN STACKING.SOLUTION.version%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_solution_correlation STACKING.SOLUTION.correlation%TYPE;
  lv_solution_score       STACKING.SOLUTION.score%TYPE;
  lv_solution_test_size   STACKING.SOLUTION.test_size%TYPE;
  lv_solution_resampling  STACKING.SOLUTION.resampling%TYPE;

  lv_best_model       STACKING.MODEL_SCORE.model%TYPE;
  lv_best_test_score  STACKING.MODEL_SCORE.test_score%TYPE;
  lv_best_train_score STACKING.MODEL_SCORE.train_score%TYPE;

  lv_rank            PLS_INTEGER := 0;
  lv_feature_printed PLS_INTEGER := 0;

  CURSOR c_best_model IS
    WITH ranked_models AS (
      SELECT ms.model,
             ms.test_score,
             ms.train_score,
             ROW_NUMBER() OVER (
               ORDER BY ms.test_score DESC, ms.train_score DESC, ms.model ASC
             ) AS rn
        FROM STACKING.MODEL_SCORE ms
       WHERE ms.name = p_solution_name
         AND ms.version = p_solution_version
         AND ms.step = 1
    )
    SELECT rm.model, rm.test_score, rm.train_score
      FROM ranked_models rm
     WHERE rm.rn = 1;

  CURSOR c_top_features IS
    SELECT fi.feature,
           fi.importance
      FROM STACKING.FEATURE_IMPORTANCE fi
     WHERE fi.name = p_solution_name
       AND fi.version = p_solution_version
       AND fi.step = 1
     ORDER BY fi.importance DESC, fi.feature ASC;

  rec_best_model c_best_model%ROWTYPE;
  rec_f          c_top_features%ROWTYPE;
BEGIN
  IF p_solution_name IS NULL OR p_solution_version IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Solution: ' || p_solution_name || ' v' || p_solution_version);

  SELECT s.correlation,
         s.score,
         s.test_size,
         s.resampling
    INTO lv_solution_correlation,
         lv_solution_score,
         lv_solution_test_size,
         lv_solution_resampling
    FROM STACKING.SOLUTION s
   WHERE s.name = p_solution_name
     AND s.version = p_solution_version;

  DBMS_OUTPUT.PUT_LINE(
    'Correlation: ' || lv_solution_correlation ||
    ' | Score: ' || lv_solution_score ||
    ' | Test size: ' || lv_solution_test_size ||
    ' | Resampling: ' || lv_solution_resampling
  );

  OPEN c_best_model;
  FETCH c_best_model INTO rec_best_model;
  IF c_best_model%FOUND THEN
    lv_best_model := rec_best_model.model;
    lv_best_test_score := rec_best_model.test_score;
    lv_best_train_score := rec_best_model.train_score;

    DBMS_OUTPUT.PUT_LINE(
      'Best model at step 1: ' || lv_best_model ||
      ' | Test score: ' || lv_best_test_score ||
      ' | Train score: ' || lv_best_train_score
    );
  ELSE
    DBMS_OUTPUT.PUT_LINE('No model score rows found for step 1.');
  END IF;
  CLOSE c_best_model;

  DBMS_OUTPUT.PUT_LINE('Top features (step 1):');

  OPEN c_top_features;
  LOOP
    FETCH c_top_features INTO rec_f;
    EXIT WHEN c_top_features%NOTFOUND;

    lv_rank := lv_rank + 1;
    IF lv_rank > co_report_limit THEN
      EXIT;
    END IF;

    lv_feature_printed := 1;
    DBMS_OUTPUT.PUT_LINE('  ' || LPAD(lv_rank, 2, ' ') || ') ' || rec_f.feature || ' => ' || rec_f.importance);
  END LOOP;
  CLOSE c_top_features;

  IF lv_feature_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No feature importance rows found for step 1.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_solution_insights;
/

