Build a reusable PL/SQL package routine that produces a small “provider snapshot” report for a given state. The report should list up to 15 home health agencies in that state (provider id and agency name), and it should also compute how many agencies exist in total for that state. Add simple control flow so that if the state has zero agencies you print a clear message instead of the detail list. Make sure NULL or badly formatted state inputs are handled safely, and that runtime errors never reach the client.

Requirements:
Procedure Name: medicare_provider_pkg.print_hha_snapshot
Parameters:
p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Total home health agencies in state ' || lv_state || ': ' || lv_total_count);
DBMS_OUTPUT.PUT_LINE('No home health agencies found for state ' || lv_state || '.');
DBMS_OUTPUT.PUT_LINE('Provider ' || rec.provider_id || ' - ' || rec.agency_name);
DBMS_OUTPUT.PUT_LINE('State is required.');
DBMS_OUTPUT.PUT_LINE('State must be exactly 2 characters.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid value provided.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE medicare_provider_pkg IS
  PROCEDURE print_hha_snapshot(
    p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
  );
END medicare_provider_pkg;
/

CREATE OR REPLACE PACKAGE BODY medicare_provider_pkg IS
  PROCEDURE print_hha_snapshot(
    p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_state       CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE;
    lv_total_count PLS_INTEGER;
  BEGIN
    IF p_state IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('State is required.');
      RETURN;
    END IF;

    IF LENGTH(TRIM(p_state)) <> 2 THEN
      DBMS_OUTPUT.PUT_LINE('State must be exactly 2 characters.');
      RETURN;
    END IF;

    lv_state := UPPER(TRIM(p_state));

    SELECT COUNT(*)
      INTO lv_total_count
      FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
     WHERE hha.state = lv_state;

    DBMS_OUTPUT.PUT_LINE('Total home health agencies in state ' || lv_state || ': ' || lv_total_count);

    IF lv_total_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No home health agencies found for state ' || lv_state || '.');
      RETURN;
    END IF;

    FOR rec IN (
      SELECT hha.provider_id,
             hha.agency_name
        FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES hha
       WHERE hha.state = lv_state
         AND ROWNUM <= co_report_limit
       ORDER BY hha.provider_id
    ) LOOP
      DBMS_OUTPUT.PUT_LINE('Provider ' || rec.provider_id || ' - ' || rec.agency_name);
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid value provided.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_hha_snapshot;
END medicare_provider_pkg;
/

question:
Build a reusable procedure that prints a small “station snapshot” report for a given bikeshare station name: show up to 15 of the most recent status readings (timestamp, bikes available, docks available). If the station name is missing, default it to the most common start station name from the trips table. If the station name cannot be matched to a station id, print a clear message. Make sure the routine never throws an unhandled error and that it gives clean output that a helpdesk person could read.

Requirements:
Procedure Name: report_station_status
Parameters:
p_station_name IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_station_name%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_name || ' (ID=' || lv_station_id || ')');
DBMS_OUTPUT.PUT_LINE('Showing up to ' || co_report_limit || ' most recent status rows.');
DBMS_OUTPUT.PUT_LINE(TO_CHAR(rec.status_time, 'YYYY-MM-DD HH24:MI:SS') || ' | bikes=' || rec.bikes_available || ' | docks=' || rec.docks_available);
DBMS_OUTPUT.PUT_LINE('No status rows found for station ID=' || lv_station_id || '.');
DBMS_OUTPUT.PUT_LINE('No station found for name: ' || lv_station_name);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_station_status(
  p_station_name IN SAN_FRANCISCO.BIKESHARE_TRIPS.start_station_name%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_station_name SAN_FRANCISCO.BIKESHARE_TRIPS.start_station_name%TYPE;
  lv_station_id   SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Default the station name when it is not provided.
  IF p_station_name IS NULL OR TRIM(p_station_name) IS NULL THEN
    SELECT start_station_name
      INTO lv_station_name
      FROM (
            SELECT t.start_station_name
              FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
             WHERE t.start_station_name IS NOT NULL
             GROUP BY t.start_station_name
             ORDER BY COUNT(*) DESC, t.start_station_name ASC
           )
     WHERE ROWNUM = 1;
  ELSE
    lv_station_name := p_station_name;
  END IF;

  -- Resolve name to station ID (case-insensitive match).
  SELECT s.station_id
    INTO lv_station_id
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
   WHERE UPPER(s.name) = UPPER(lv_station_name);

  DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_name || ' (ID=' || lv_station_id || ')');
  DBMS_OUTPUT.PUT_LINE('Showing up to ' || co_report_limit || ' most recent status rows.');

  -- Print up to 15 most recent status readings.
  FOR rec IN (
    SELECT bs.time AS status_time,
           bs.bikes_available,
           bs.docks_available
      FROM SAN_FRANCISCO.BIKESHARE_STATUS bs
     WHERE bs.station_id = lv_station_id
     ORDER BY bs.time DESC
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      TO_CHAR(rec.status_time, 'YYYY-MM-DD HH24:MI:SS') ||
      ' | bikes=' || rec.bikes_available ||
      ' | docks=' || rec.docks_available
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No status rows found for station ID=' || lv_station_id || '.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    -- Covers: no default station name found, or station name not found in stations.
    IF lv_station_name IS NOT NULL THEN
      DBMS_OUTPUT.PUT_LINE('No station found for name: ' || lv_station_name);
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_station_status;
/

question:
Create a small analyst-style PL/SQL script that prints a compact CPI snapshot for a given area and item: show up to 15 monthly CPI observations for a chosen year, and include a simple classification of each value as LOW / NORMAL / HIGH based on thresholds.

Use the BLS CPI_U table. The script should:
Accept an area name, item name, and year.
Validate that none of these inputs are null/blank; if any are missing, print an error and stop.
Loop through matching CPI records for that area/item/year, ordered by C_DATE, and print each row as a formatted line.
Convert VALUE (stored as text) to a number for comparisons; if conversion fails for any row, handle the error via exception handling and print a friendly message.

Requirements:
Procedure Name: Anonymous Block.
Parameters:
None.
Output:
DBMS_OUTPUT.PUT_LINE('Input validation failed: area, item, and year are required.');
DBMS_OUTPUT.PUT_LINE('CPI Snapshot (Area=' || lv_area_name || ', Item=' || lv_item_name || ', Year=' || lv_year || ')');
DBMS_OUTPUT.PUT_LINE('Date=' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') || ' Period=' || rec.period || ' Value=' || rec.value || ' Category=' || lv_category);
DBMS_OUTPUT.PUT_LINE('No CPI rows matched the given inputs.');
DBMS_OUTPUT.PUT_LINE('Bad CPI VALUE encountered; unable to convert to number.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'.
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'.
WHEN VALUE_ERROR THEN: 'Bad CPI VALUE encountered; unable to convert to number.'.
WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
DECLARE
  -- Report limit for readability
  co_report_limit CONSTANT PLS_INTEGER := 15;

  -- Inputs (set these for the run)
  lv_area_name BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name BLS.CPI_U.item_name%TYPE := 'All items';
  lv_year      BLS.CPI_U.year%TYPE := '2020';

  -- Thresholds for a simple classification
  co_low_threshold  CONSTANT NUMBER := 200;
  co_high_threshold CONSTANT NUMBER := 300;

  lv_value_num NUMBER;
  lv_category  VARCHAR2(10);
  lv_printed   PLS_INTEGER := 0;
BEGIN
  -- Input validation
  IF TRIM(lv_area_name) IS NULL OR TRIM(lv_item_name) IS NULL OR TRIM(lv_year) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: area, item, and year are required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('CPI Snapshot (Area=' || lv_area_name || ', Item=' || lv_item_name || ', Year=' || lv_year || ')');

  -- Implicit cursor loop (no explicit cursor declarations)
  FOR rec IN (
    SELECT c_date,
           period,
           value
      FROM BLS.CPI_U
     WHERE area_name = lv_area_name
       AND item_name = lv_item_name
       AND year = lv_year
     ORDER BY c_date
  ) LOOP
    EXIT WHEN lv_printed >= co_report_limit;

    -- Convert VALUE (stored as VARCHAR2) and classify
    lv_value_num := TO_NUMBER(rec.value);

    IF lv_value_num < co_low_threshold THEN
      lv_category := 'LOW';
    ELSIF lv_value_num > co_high_threshold THEN
      lv_category := 'HIGH';
    ELSE
      lv_category := 'NORMAL';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Date=' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') ||
      ' Period=' || rec.period ||
      ' Value=' || rec.value ||
      ' Category=' || lv_category
    );

    lv_printed := lv_printed + 1;
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No CPI rows matched the given inputs.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Bad CPI VALUE encountered; unable to convert to number.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

