CREATE OR REPLACE PROCEDURE report_country_snapshot(
  p_country_code_2 IN CITY_LEGISLATION.CITIES_COUNTRIES.country_code_2%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country_name CITY_LEGISLATION.CITIES_COUNTRIES.country_name%TYPE;
  lv_lang_rows    PLS_INTEGER := 0;
  lv_curr_rows    PLS_INTEGER := 0;
BEGIN
  IF p_country_code_2 IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Country code is required.');
    RETURN;
  END IF;

  -- Lookup country; should be a single row for a given country code.
  SELECT cc.country_name
    INTO lv_country_name
    FROM CITY_LEGISLATION.CITIES_COUNTRIES cc
   WHERE cc.country_code_2 = p_country_code_2;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name || ' (' || p_country_code_2 || ')');

  -- Top languages (most common first)
  DBMS_OUTPUT.PUT_LINE('Top languages:');
  FOR rec IN (
    SELECT cl.language AS language,
           COUNT(*)     AS lang_count
      FROM CITY_LEGISLATION.CITIES_LANGUAGES cl
     WHERE cl.country_code_2 = p_country_code_2
     GROUP BY cl.language
     ORDER BY COUNT(*) DESC, cl.language ASC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_lang_rows := lv_lang_rows + 1;
    DBMS_OUTPUT.PUT_LINE('  ' || rec.language || ' - ' || rec.lang_count || ' record(s)');
  END LOOP;

  IF lv_lang_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('  (No languages found for this country.)');
  END IF;

  -- Currency list
  DBMS_OUTPUT.PUT_LINE('Currencies:');
  FOR rec IN (
    SELECT DISTINCT
           ccu.currency_name AS currency_name,
           ccu.currency_code AS currency_code
      FROM CITY_LEGISLATION.CITIES_CURRENCIES ccu
     WHERE ccu.country_code_2 = p_country_code_2
     ORDER BY ccu.currency_name ASC, ccu.currency_code ASC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_curr_rows := lv_curr_rows + 1;
    DBMS_OUTPUT.PUT_LINE('  ' || rec.currency_name || ' (' || rec.currency_code || ')');
  END LOOP;

  IF lv_curr_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('  (No currencies found for this country.)');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_snapshot;
/

question:
Build a reusable stored procedure that produces a concise "season batting snapshot" for a given season. The routine should print the season, then list up to 15 players with the most runs in that season, including matches played, total runs, balls faced, strike rate, and how many dismissals (wickets) they suffered.

Business rules:
 Runs and balls faced come from ball-level data; count balls faced only when a batsman scoring record exists for that ball.
 Dismissals are counted when the player appears as PLAYER_OUT in the wicket table for that season.
 If the season has no ball data, print a clear message and do not error.

Requirements:
Procedure Name: pr_season_batting_snapshot
Parameters:
