CREATE OR REPLACE PROCEDURE report_state_provider_snapshot(
  p_state IN VARCHAR2
) IS
  lv_state        VARCHAR2(2);
  lv_hospitals    NUMBER;
  lv_hha          NUMBER;
  lv_hospice      NUMBER;
  lv_nursing      NUMBER;
  lv_top_category VARCHAR2(50);
  lv_top_count    NUMBER;
BEGIN
  -- Normalize and validate state input
  lv_state := UPPER(TRIM(p_state));

  IF lv_state IS NULL OR LENGTH(lv_state) <> 2 THEN
    lv_state := '??';
  END IF;

  -- Provider counts by category
  SELECT COUNT(*)
    INTO lv_hospitals
    FROM CMS_MEDICARE.HOSPITAL_GENERAL_INFO h
   WHERE h.STATE = lv_state;

  SELECT COUNT(*)
    INTO lv_hha
    FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES a
   WHERE a.STATE = lv_state;

  SELECT COUNT(*)
    INTO lv_hospice
    FROM CMS_MEDICARE.HOSPICE_PROVIDERS p
   WHERE p.STATE = lv_state;

  SELECT COUNT(*)
    INTO lv_nursing
    FROM CMS_MEDICARE.NURSING_FACILITIES n
   WHERE n.STATE = lv_state;

  -- Determine the top category; ties break deterministically by fixed priority order.
  lv_top_category := 'Hospitals';
  lv_top_count := lv_hospitals;

  IF lv_hha > lv_top_count THEN
    lv_top_category := 'Home Health Agencies';
    lv_top_count := lv_hha;
  ELSIF lv_hha = lv_top_count THEN
    NULL;
  END IF;

  IF lv_hospice > lv_top_count THEN
    lv_top_category := 'Hospice Providers';
    lv_top_count := lv_hospice;
  ELSIF lv_hospice = lv_top_count THEN
    NULL;
  END IF;

  IF lv_nursing > lv_top_count THEN
    lv_top_category := 'Nursing Facilities';
    lv_top_count := lv_nursing;
  ELSIF lv_nursing = lv_top_count THEN
    NULL;
  END IF;

  DBMS_OUTPUT.PUT_LINE('State: ' || lv_state);
  DBMS_OUTPUT.PUT_LINE('Hospitals: ' || TO_CHAR(lv_hospitals));
  DBMS_OUTPUT.PUT_LINE('Home Health Agencies: ' || TO_CHAR(lv_hha));
  DBMS_OUTPUT.PUT_LINE('Hospice Providers: ' || TO_CHAR(lv_hospice));
  DBMS_OUTPUT.PUT_LINE('Nursing Facilities: ' || TO_CHAR(lv_nursing));
  DBMS_OUTPUT.PUT_LINE('Top Category: ' || lv_top_category || ' (' || TO_CHAR(lv_top_count) || ')');

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_state_provider_snapshot;
/

CREATE OR REPLACE PROCEDURE report_channel_year_product_sales(
  p_channel_desc  IN COMPLEX_ORACLE.CHANNELS.channel_desc%TYPE,
  p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_channel_id   COMPLEX_ORACLE.CHANNELS.channel_id%TYPE;
  lv_row_count    PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Report: Channel=' || p_channel_desc || ', Year=' || p_calendar_year);

  -- Resolve channel_id from description (intentionally expects a single match)
  SELECT c.channel_id
    INTO lv_channel_id
    FROM COMPLEX_ORACLE.CHANNELS c
   WHERE c.channel_desc = p_channel_desc;

  -- Print up to 15 product-level aggregated lines
  FOR r IN (
    SELECT p.prod_name AS prod_name,
           SUM(s.quantity_sold) AS qty_sold,
           SUM(s.amount_sold) AS amt_sold
      FROM COMPLEX_ORACLE.SALES s
      INNER JOIN COMPLEX_ORACLE.TIMES t
        ON t.time_id = s.time_id
      INNER JOIN COMPLEX_ORACLE.PRODUCTS p
        ON p.prod_id = s.prod_id
     WHERE s.channel_id = lv_channel_id
       AND t.calendar_year = p_calendar_year
     GROUP BY p.prod_name
     ORDER BY SUM(s.amount_sold) DESC
  ) LOOP
    EXIT WHEN lv_row_count >= co_report_limit;

    lv_row_count := lv_row_count + 1;
    DBMS_OUTPUT.PUT_LINE('Product=' || r.prod_name || ' | Qty=' || r.qty_sold || ' | Amt=' || r.amt_sold);
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No sales found for the requested channel/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No sales found for the requested channel/year.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple channels match the given description.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_channel_year_product_sales;
/

