For a given region and ticker, scan the most recent distinct trading dates (newest first) and print up to 15 date-level summary lines showing: transaction count, total quantity, average fee percentage, and the closing market price for that date. If a transaction date has no matching price record for the ticker, still print the row but show the price as "N/A".

The routine must use an explicit cursor (not an inline SELECT loop), iterate through the results, and include defensive handling for common data issues (bad/NULL inputs, missing data, and unexpected errors).

Requirements:
Procedure Name: report_region_ticker_activity
Parameters:
p_region IN BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE
p_ticker IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.ticker%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Region/Ticker Trading Activity Report');
DBMS_OUTPUT.PUT_LINE('Region=' || NVL(p_region, 'NULL') || ', Ticker=' || NVL(p_ticker, 'NULL'));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 72, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD('Txn Date', 12) || ' ' || RPAD('Txn Cnt', 7) || ' ' || RPAD('Tot Qty', 10) || ' ' || RPAD('Avg Fee%', 9) || ' ' || RPAD('Close Px', 10));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 72, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(TO_CHAR(lv_txn_date), 12) || ' ' || LPAD(lv_txn_cnt, 7) || ' ' || LPAD(TO_CHAR(lv_total_qty), 10) || ' ' || LPAD(TO_CHAR(lv_avg_fee_pct, 'FM999990D00'), 9) || ' ' || LPAD(lv_close_px_txt, 10));
DBMS_OUTPUT.PUT_LINE('No rows matched the inputs.');
DBMS_OUTPUT.PUT_LINE('Row limit reached: ' || co_report_limit);
DBMS_OUTPUT.PUT_LINE('Invalid input: region and ticker are required.');
DBMS_OUTPUT.PUT_LINE('Region does not exist.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN VALUE_ERROR THEN: 'Invalid input: region and ticker are required.'
WHEN NO_DATA_FOUND THEN: 'Region does not exist.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_region_ticker_activity(
  p_region IN BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE,
  p_ticker IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.ticker%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region_exists_cnt NUMBER;
  lv_rows_printed      PLS_INTEGER := 0;

  lv_txn_date      BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.txn_date%TYPE;
  lv_txn_cnt       NUMBER;
  lv_total_qty     NUMBER;
  lv_avg_fee_pct   NUMBER;
  lv_close_px_txt  VARCHAR2(30);

  CURSOR c_daily_activity IS
    WITH daily_txn AS (
      SELECT
        t.txn_date,
        COUNT(*) AS txn_cnt,
        SUM(t.quantity) AS total_qty,
        AVG(t.percentage_fee) AS avg_fee_pct
      FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
      INNER JOIN BANK_SALES_TRADING.BITCOIN_MEMBERS m
        ON m.member_id = t.member_id
      WHERE m.region = p_region
        AND t.ticker = p_ticker
      GROUP BY t.txn_date
    )
    SELECT
      d.txn_date,
      d.txn_cnt,
      d.total_qty,
      d.avg_fee_pct,
      p.price AS close_px
    FROM daily_txn d
    LEFT OUTER JOIN BANK_SALES_TRADING.BITCOIN_PRICES p
      ON p.ticker = p_ticker
     AND p.market_date = d.txn_date
    ORDER BY d.txn_date DESC;

  r_activity c_daily_activity%ROWTYPE;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Region/Ticker Trading Activity Report');
  DBMS_OUTPUT.PUT_LINE('Region=' || NVL(p_region, 'NULL') || ', Ticker=' || NVL(p_ticker, 'NULL'));

  -- Basic input validation (treat blank strings as invalid)
  IF p_region IS NULL OR TRIM(p_region) IS NULL OR p_ticker IS NULL OR TRIM(p_ticker) IS NULL THEN
    RAISE VALUE_ERROR;
  END IF;

  -- Ensure the region exists for better operator feedback
  SELECT COUNT(*)
    INTO lv_region_exists_cnt
    FROM BANK_SALES_TRADING.BITCOIN_MEMBERS m
   WHERE m.region = p_region;

  IF lv_region_exists_cnt = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE(RPAD('-', 72, '-'));
  DBMS_OUTPUT.PUT_LINE(RPAD('Txn Date', 12) || ' ' || RPAD('Txn Cnt', 7) || ' ' || RPAD('Tot Qty', 10) || ' ' || RPAD('Avg Fee%', 9) || ' ' || RPAD('Close Px', 10));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 72, '-'));

  OPEN c_daily_activity;
  LOOP
    FETCH c_daily_activity INTO r_activity;
    EXIT WHEN c_daily_activity%NOTFOUND;

    lv_txn_date    := r_activity.txn_date;
    lv_txn_cnt     := r_activity.txn_cnt;
    lv_total_qty   := r_activity.total_qty;
    lv_avg_fee_pct := r_activity.avg_fee_pct;

    IF r_activity.close_px IS NULL THEN
      lv_close_px_txt := 'N/A';
    ELSE
      lv_close_px_txt := TO_CHAR(r_activity.close_px);
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(lv_txn_date), 12) || ' ' ||
      LPAD(lv_txn_cnt, 7) || ' ' ||
      LPAD(TO_CHAR(lv_total_qty), 10) || ' ' ||
      LPAD(TO_CHAR(lv_avg_fee_pct, 'FM999990D00'), 9) || ' ' ||
      LPAD(lv_close_px_txt, 10)
    );

    lv_rows_printed := lv_rows_printed + 1;
    IF lv_rows_printed >= co_report_limit THEN
      DBMS_OUTPUT.PUT_LINE('Row limit reached: ' || co_report_limit);
      EXIT;
    END IF;
  END LOOP;
  CLOSE c_daily_activity;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the inputs.');
  END IF;

EXCEPTION
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: region and ticker are required.');
    IF c_daily_activity%ISOPEN THEN
      CLOSE c_daily_activity;
    END IF;
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Region does not exist.');
    IF c_daily_activity%ISOPEN THEN
      CLOSE c_daily_activity;
    END IF;
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    IF c_daily_activity%ISOPEN THEN
      CLOSE c_daily_activity;
    END IF;
END report_region_ticker_activity;
/

