CREATE OR REPLACE PROCEDURE wdi_country_overview(
  p_country_code IN WORLD_BANK_WDI.COUNTRY_SUMMARY.country_code%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_short_name WORLD_BANK_WDI.COUNTRY_SUMMARY.short_name%TYPE;
  lv_region     WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE;

  lv_footnote_count PLS_INTEGER;
  lv_rows_printed   PLS_INTEGER := 0;
BEGIN
  -- 1) Country header
  SELECT cs.short_name,
         cs.region
    INTO lv_short_name,
         lv_region
    FROM WORLD_BANK_WDI.COUNTRY_SUMMARY cs
   WHERE cs.country_code = p_country_code;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_short_name || ' | Region: ' || lv_region);

  -- 2) Footnote existence check
  SELECT COUNT(*)
    INTO lv_footnote_count
    FROM WORLD_BANK_WDI.FOOTNOTES f
   WHERE f.country_code = p_country_code;

  IF lv_footnote_count > 0 THEN
    DBMS_OUTPUT.PUT_LINE('Footnotes: Has footnotes');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Footnotes: No footnotes');
  END IF;

  -- 3) Indicator sample (most recent years first)
  DBMS_OUTPUT.PUT_LINE('Indicator data (up to ' || co_report_limit || ' rows):');

  FOR r IN (
    SELECT d.indicator_code,
           d.year,
           d.value
      FROM WORLD_BANK_WDI.INDICATORS_DATA d
     WHERE d.country_code = p_country_code
     ORDER BY d.year DESC, d.indicator_code
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;
    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE('- ' || r.indicator_code || ' | Year: ' || r.year || ' | Value: ' || r.value);
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No indicator data found for this country.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END wdi_country_overview;
/

question:
Operations wants a quick quality check for picking performance. Build an anonymous PL/SQL report that, for a given picker employee id, looks at the most recent pick lists (up to a readable limit), and for each pick list prints the picker name, created time, how many pick lines it contains, and the top 3 products by total quantity on that pick list.

Use an explicit cursor to iterate pick lists, and inside that loop use a second explicit cursor to iterate the top products for the current pick list. Add control-flow rules:
 If a pick list has no pick lines, print a message indicating it is empty and skip product details.
 If any product total quantity for the pick list exceeds a threshold, print a warning line for that product.

Make sure the block handles bad inputs gracefully:
 If the picker id does not exist, return a clear message.
 If multiple employees share the same id (data issue), return a clear message.
 Any other unexpected error should be caught and reported without failing.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Picker: ' || lv_picker_name || ' (EMP_ID=' || p_picker_emp_id || ')');
DBMS_OUTPUT.PUT_LINE('Picklist ' || r_pl.id || ' created ' || r_pl.created || ' - lines=' || lv_line_count);
DBMS_OUTPUT.PUT_LINE('Picklist ' || r_pl.id || ' is empty (no pick lines).');
DBMS_OUTPUT.PUT_LINE('  Product ' || r_prod.product_id || ' total_qty=' || r_prod.total_qty);
DBMS_OUTPUT.PUT_LINE('  WARNING: high quantity for product ' || r_prod.product_id || ' total_qty=' || r_prod.total_qty);
DBMS_OUTPUT.PUT_LINE('No pick lists found for picker emp id ' || p_picker_emp_id || '.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

