DECLARE
  -- Simulated input for the exercise; change as needed when running.
  p_picker_emp_id ORACLE_SQL.EMPLOYEES.id%TYPE := 1;

  co_report_limit        CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  co_top_products        CONSTANT PLS_INTEGER := 3;  -- Top N products per pick list
  co_high_qty_threshold  CONSTANT NUMBER := 50;      -- Warn when total product qty exceeds this

  lv_picker_name ORACLE_SQL.EMPLOYEES.name%TYPE;
  lv_line_count  NUMBER;

  CURSOR c_picklists(p_emp_id ORACLE_SQL.EMPLOYEES.id%TYPE) IS
    SELECT pl.id,
           pl.created
      FROM ORACLE_SQL.PICKING_LIST pl
     WHERE pl.picker_emp_id = p_emp_id
     ORDER BY pl.created DESC
     FETCH FIRST co_report_limit ROWS ONLY;

  CURSOR c_top_products(p_picklist_id ORACLE_SQL.PICKING_LIST.id%TYPE) IS
    WITH prod_totals AS (
      SELECT pln.product_id,
             SUM(pln.qty) AS total_qty,
             ROW_NUMBER() OVER (ORDER BY SUM(pln.qty) DESC, pln.product_id) AS rn
        FROM ORACLE_SQL.PICKING_LINE pln
       WHERE pln.picklist_id = p_picklist_id
       GROUP BY pln.product_id
    )
    SELECT pt.product_id,
           pt.total_qty
      FROM prod_totals pt
     WHERE pt.rn <= co_top_products
     ORDER BY pt.rn;

BEGIN
  -- Validate picker and get display name
  SELECT e.name
    INTO lv_picker_name
    FROM ORACLE_SQL.EMPLOYEES e
   WHERE e.id = p_picker_emp_id;

  DBMS_OUTPUT.PUT_LINE('Picker: ' || lv_picker_name || ' (EMP_ID=' || p_picker_emp_id || ')');

  FOR r_pl IN c_picklists(p_picker_emp_id) LOOP
    -- Count pick lines for this pick list
    SELECT COUNT(*)
      INTO lv_line_count
      FROM ORACLE_SQL.PICKING_LINE pln
     WHERE pln.picklist_id = r_pl.id;

    DBMS_OUTPUT.PUT_LINE('Picklist ' || r_pl.id || ' created ' || r_pl.created || ' - lines=' || lv_line_count);

    IF lv_line_count = 0 THEN
      DBMS_OUTPUT.PUT_LINE('Picklist ' || r_pl.id || ' is empty (no pick lines).');
      CONTINUE;
    END IF;

    FOR r_prod IN c_top_products(r_pl.id) LOOP
      DBMS_OUTPUT.PUT_LINE('  Product ' || r_prod.product_id || ' total_qty=' || r_prod.total_qty);

      IF r_prod.total_qty > co_high_qty_threshold THEN
        DBMS_OUTPUT.PUT_LINE('  WARNING: high quantity for product ' || r_prod.product_id || ' total_qty=' || r_prod.total_qty);
      END IF;
    END LOOP;
  END LOOP;

  IF c_picklists%ROWCOUNT = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No pick lists found for picker emp id ' || p_picker_emp_id || '.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

