     WHERE pl.picker_emp_id = p_emp_id
     ORDER BY pl.created DESC
     FETCH FIRST co_report_limit ROWS ONLY;
  CURSOR c_top_products(p_picklist_id ORACLE_SQL.PICKING_LIST.id%TYPE) IS
    WITH prod_totals AS (
      SELECT pln.product_id,
             SUM(pln.qty) AS total_qty,
             ROW_NUMBER() OVER (ORDER BY SUM(pln.qty) DESC, pln.product_id) AS rn
        FROM ORACLE_SQL.PICKING_LINE pln
       WHERE pln.picklist_id = p_picklist_id
       GROUP BY pln.product_id
    )
    SELECT pt.product_id, pt.total_qty
      FROM prod_totals pt
     WHERE pt.rn <= co_top_products
     ORDER BY pt.rn;
BEGIN
  SELECT e.name INTO lv_picker_name FROM ORACLE_SQL.EMPLOYEES e WHERE e.id = p_picker_emp_id;
  DBMS_OUTPUT.PUT_LINE('Picker: ' || lv_picker_name || ' (EMP_ID=' || p_picker_emp_id || ')');
EXCEPTION
  WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

