CREATE OR REPLACE PROCEDURE report_departure_punctuality(
  p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_total PLS_INTEGER := 0;
  lv_late  PLS_INTEGER := 0;
BEGIN
  IF p_departure_airport IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Airport code is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Punctuality snapshot for departure airport ' || p_departure_airport || ':');

  FOR r IN (
    SELECT f.flight_no,
           f.scheduled_departure,
           f.actual_departure
      FROM AIRLINES.FLIGHTS f
     WHERE f.departure_airport = p_departure_airport
       AND f.status = 'Departed'
       AND f.actual_departure IS NOT NULL
     ORDER BY f.scheduled_departure
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_total := lv_total + 1;

    IF r.actual_departure <= r.scheduled_departure THEN
      DBMS_OUTPUT.PUT_LINE('Flight ' || r.flight_no || ': ON TIME');
    ELSE
      lv_late := lv_late + 1;
      DBMS_OUTPUT.PUT_LINE('Flight ' || r.flight_no || ': LATE');
    END IF;
  END LOOP;

  IF lv_total = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No departed flights found for airport ' || p_departure_airport || '.');
  END IF;

  DBMS_OUTPUT.PUT_LINE('Summary - inspected: ' || lv_total || ', late: ' || lv_late);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_departure_punctuality;
/

CREATE OR REPLACE PROCEDURE report_member_ticker_activity(
  p_member_id IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.member_id%TYPE,
  p_ticker    IN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.ticker%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_first_name BANK_SALES_TRADING.BITCOIN_MEMBERS.first_name%TYPE;
  lv_region     BANK_SALES_TRADING.BITCOIN_MEMBERS.region%TYPE;

  lv_buy_qty  NUMBER := 0;
  lv_sell_qty NUMBER := 0;

  lv_match_count NUMBER := 0;
  lv_status      VARCHAR2(20);
BEGIN
  -- Guard clause for required inputs
  IF p_member_id IS NULL OR p_ticker IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input error: member_id and ticker are required.');
    RETURN;
  END IF;

  -- Member header (single-row lookup)
  SELECT m.first_name, m.region
    INTO lv_first_name, lv_region
    FROM BANK_SALES_TRADING.BITCOIN_MEMBERS m
   WHERE m.member_id = p_member_id;

  -- Determine whether the member is active for this ticker
  SELECT COUNT(*)
    INTO lv_match_count
    FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
   WHERE t.member_id = p_member_id
     AND t.ticker = p_ticker;

  IF lv_match_count > 0 THEN
    lv_status := 'ACTIVE';
  ELSE
    lv_status := 'INACTIVE';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Member: ' || lv_first_name || ' (ID=' || p_member_id || '), Region=' || lv_region);
  DBMS_OUTPUT.PUT_LINE('Ticker: ' || p_ticker);
  DBMS_OUTPUT.PUT_LINE('Status: ' || lv_status);
  DBMS_OUTPUT.PUT_LINE('Most recent transactions (up to ' || co_report_limit || '):');

  -- Print up to N most recent matching transactions
  FOR rec IN (
    SELECT t.txn_date,
           t.txn_time,
           t.txn_type,
           t.quantity,
           t.percentage_fee
      FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS t
     WHERE t.member_id = p_member_id
       AND t.ticker = p_ticker
     ORDER BY t.txn_date DESC, t.txn_time DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE('  ' || rec.txn_date || ' ' || rec.txn_time || ' | ' || rec.txn_type || ' | qty=' || rec.quantity || ' | fee%=' || rec.percentage_fee);

    -- Totals by transaction type
    IF rec.txn_type = 'BUY' THEN
      lv_buy_qty := lv_buy_qty + NVL(rec.quantity, 0);
    ELSIF rec.txn_type = 'SELL' THEN
      lv_sell_qty := lv_sell_qty + NVL(rec.quantity, 0);
    END IF;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Totals: BUY_QTY=' || lv_buy_qty || ', SELL_QTY=' || lv_sell_qty);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_member_ticker_activity;
/

