CREATE OR REPLACE PACKAGE BODY bikeshare_ops IS

  PROCEDURE station_status_report(
    p_station_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_station_id   SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
    lv_station_name SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
    lv_region_name  SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;

    CURSOR c_status(p_station_id SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.station_id%TYPE) IS
      SELECT TO_TIMESTAMP(s.last_reported, 'YYYY-MM-DD"T"HH24:MI:SS') AS last_reported_ts,
             TO_NUMBER(s.num_bikes_available) AS num_bikes,
             TO_NUMBER(s.num_docks_available) AS num_docks,
             s.is_renting AS is_renting,
             s.is_returning AS is_returning
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS s
       WHERE s.station_id = p_station_id
         AND s.last_reported IS NOT NULL
       ORDER BY TO_TIMESTAMP(s.last_reported, 'YYYY-MM-DD"T"HH24:MI:SS') DESC;

    lr_status c_status%ROWTYPE;
    lv_rows_printed PLS_INTEGER := 0;
    lv_has_rows     BOOLEAN := FALSE;
  BEGIN
    -- Find the station and region by station name.
    SELECT si.station_id,
           si.name,
           r.name
      INTO lv_station_id,
           lv_station_name,
           lv_region_name
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      INNER JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
        ON r.region_id = si.region_id
     WHERE si.name = p_station_name;

    DBMS_OUTPUT.PUT_LINE('Report station_id=' || lv_station_id || ', station_name=' || lv_station_name);
    DBMS_OUTPUT.PUT_LINE('Region=' || lv_region_name);
    DBMS_OUTPUT.PUT_LINE('Most recent status snapshots (max rows=' || co_report_limit || '):');

    OPEN c_status(lv_station_id);
    LOOP
      FETCH c_status INTO lr_status;
      EXIT WHEN c_status%NOTFOUND;

      lv_has_rows := TRUE;
      lv_rows_printed := lv_rows_printed + 1;

      DBMS_OUTPUT.PUT_LINE(
        'As of ' || TO_CHAR(lr_status.last_reported_ts, 'YYYY-MM-DD HH24:MI:SS') ||
        ': bikes=' || lr_status.num_bikes ||
        ', docks=' || lr_status.num_docks ||
        ', renting=' || lr_status.is_renting ||
        ', returning=' || lr_status.is_returning
      );

      EXIT WHEN lv_rows_printed >= co_report_limit;
    END LOOP;
    CLOSE c_status;

    IF NOT lv_has_rows THEN
      DBMS_OUTPUT.PUT_LINE('No status rows found for this station.');
      RETURN;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END station_status_report;

END bikeshare_ops;
/

