DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country         CITY_LEGISLATION.ALIEN_DATA.country%TYPE := 'USA';
  lv_min_birth_year  CITY_LEGISLATION.ALIEN_DATA.birth_year%TYPE := 1980;
  lv_aggressive_only NUMBER := 0; -- must be 0 or 1

  lv_rows_printed PLS_INTEGER := 0;
  lv_risk_label   VARCHAR2(20);
BEGIN
  DBMS_OUTPUT.PUT_LINE('Alien compliance snapshot (max ' || co_report_limit || ' rows)');
  DBMS_OUTPUT.PUT_LINE('Filters: country=' || NVL(lv_country, 'NULL') || ', min_birth_year=' || NVL(TO_CHAR(lv_min_birth_year), 'NULL') || ', aggressive_only=' || lv_aggressive_only);

  -- Input validation without raising exceptions
  IF lv_aggressive_only NOT IN (0, 1) THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: aggressive_only must be 0 or 1.');
    RETURN;
  END IF;

  -- Implicit cursor FOR loop (no explicit cursor declarations allowed)
  FOR rec IN (
    SELECT ad.id,
           ad.first_name,
           ad.last_name,
           ad.country,
           ad.state,
           ad.current_location,
           ad.aggressive,
           ad.feeding_frequency
      FROM CITY_LEGISLATION.ALIEN_DATA ad
     WHERE (lv_country IS NULL OR ad.country = lv_country)
       AND (lv_min_birth_year IS NULL OR ad.birth_year >= lv_min_birth_year)
       AND (lv_aggressive_only = 0 OR ad.aggressive = 1)
       AND ROWNUM <= co_report_limit
     ORDER BY ad.id
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    -- Risk labeling control flow
    IF rec.aggressive = 1
       OR rec.feeding_frequency LIKE '%Daily%'
       OR rec.feeding_frequency LIKE '%daily%'
    THEN
      lv_risk_label := 'HIGH_RISK';
    ELSE
      lv_risk_label := 'NORMAL';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'ID=' || rec.id ||
      ', Name=' || rec.first_name || ' ' || rec.last_name ||
      ', Country=' || rec.country ||
      ', State=' || rec.state ||
      ', Location=' || rec.current_location ||
      ', Aggressive=' || rec.aggressive ||
      ', Feeding=' || rec.feeding_frequency ||
      ', Risk=' || lv_risk_label
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No aliens matched the supplied filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

