  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_avg_qty      BANK_SALES_TRADING.BITCOIN_TRANSACTIONS.quantity%TYPE;
  lv_row_count    PLS_INTEGER := 0;

  -- Deliberate single-row lookup to demonstrate TOO_MANY_ROWS handling if member_id duplicates exist
  lv_any_member_id BANK_SALES_TRADING.BITCOIN_MEMBERS.member_id%TYPE;
BEGIN
  IF p_region IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input region is required.');
    RETURN;
  END IF;

  IF p_ticker IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input ticker is required.');
    RETURN;
  END IF;

  -- Single-row query; if BITCOIN_MEMBERS has duplicate member_id rows in the region, this raises TOO_MANY_ROWS
  SELECT m.member_id
    INTO lv_any_member_id
    FROM BANK_SALES_TRADING.BITCOIN_MEMBERS m
   WHERE m.region = p_region
     AND ROWNUM = 1;

  -- Compute regional average total quantity per member for the ticker
  SELECT AVG(t.total_qty)
    INTO lv_avg_qty
    FROM (
          SELECT tx.member_id,
                 SUM(tx.quantity) AS total_qty
            FROM BANK_SALES_TRADING.BITCOIN_TRANSACTIONS tx
            INNER JOIN BANK_SALES_TRADING.BITCOIN_MEMBERS m
              ON m.member_id = tx.member_id
           WHERE m.region = p_region
             AND tx.ticker = p_ticker
           GROUP BY tx.member_id
         ) t;

  DBMS_OUTPUT.PUT_LINE('=== Member Trading Snapshot ===');
  DBMS_OUTPUT.PUT_LINE('Region=' || p_region || ', Ticker=' || p_ticker);
  DBMS_OUTPUT.PUT_LINE('Regional average traded quantity=' || TO_CHAR(lv_avg_qty));
  DBMS_OUTPUT.PUT_LINE(
    RPAD('MEMBER_ID', 14) || RPAD('FIRST_NAME', 18) || RPAD('TOTAL_QTY', 12) || RPAD('AVG_FEE', 12) || RPAD('LAST_TXN', 22) || 'ACTIVITY'
  );

  FOR rec IN (
    WITH member_rollup AS (
      SELECT m.member_id,
             m.first_name,
             SUM(tx.quantity) AS total_qty,
             AVG(tx.percentage_fee) AS avg_fee,
             MAX(tx.txn_date || ' ' || tx.txn_time) AS last_txn_ts
        FROM BANK_SALES_TRADING.BITCOIN_MEMBERS m
        INNER JOIN BANK_SALES_TRADING.BITCOIN_TRANSACTIONS tx
          ON tx.member_id = m.member_id
       WHERE m.region = p_region
         AND tx.ticker = p_ticker
       GROUP BY m.member_id, m.first_name
    ), ranked AS (
      SELECT mr.member_id,
             mr.first_name,
             mr.total_qty,
             mr.avg_fee,
             mr.last_txn_ts,
             CASE
               WHEN mr.total_qty > lv_avg_qty THEN 'HIGH_ACTIVITY'
               ELSE 'LOW_ACTIVITY'
             END AS activity_level,
             ROW_NUMBER() OVER (ORDER BY mr.total_qty DESC, mr.member_id) AS rn
        FROM member_rollup mr
    )
    SELECT r.member_id,
           r.first_name,
           r.total_qty,
           r.avg_fee,
           r.last_txn_ts,
           r.activity_level
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn
  ) LOOP
    lv_row_count := lv_row_count + 1;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.member_id, 14) || RPAD(rec.first_name, 18) || RPAD(TO_CHAR(rec.total_qty), 12) || RPAD(TO_CHAR(rec.avg_fee), 12) || RPAD(rec.last_txn_ts, 22) || rec.activity_level
    );
  END LOOP;

  IF lv_row_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_member_trading_snapshot;
/

CREATE OR REPLACE PROCEDURE report_solution_monitoring(
  p_name    IN STACKING.SOLUTION.name%TYPE,
  p_version IN STACKING.SOLUTION.version%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 1; -- Expect at most one matching solution row

  lv_name      STACKING.SOLUTION.name%TYPE;
  lv_version   STACKING.SOLUTION.version%TYPE;
  lv_score     STACKING.SOLUTION.score%TYPE;
  lv_nb_model  STACKING.SOLUTION.nb_model%TYPE;
  lv_nb_feature STACKING.SOLUTION.nb_feature%TYPE;
  lv_test_size STACKING.SOLUTION.test_size%TYPE;

  lv_size_class VARCHAR2(10);
BEGIN
  -- Input validation
  IF p_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Name is required.');
    RETURN;
  ELSIF p_version IS NULL OR p_version <= 0 THEN
    DBMS_OUTPUT.PUT_LINE('Version must be a positive number.');
    RETURN;
  END IF;

  -- Retrieve a single matching solution record
  SELECT s.name,
         s.version,
         s.score,
         s.nb_model,
         s.nb_feature,
         s.test_size
    INTO lv_name,
         lv_version,
         lv_score,
         lv_nb_model,
         lv_nb_feature,
         lv_test_size
    FROM STACKING.SOLUTION s
   WHERE s.name = p_name
     AND s.version = p_version
     AND ROWNUM <= co_report_limit;

  -- Classify test size
  IF lv_test_size <= 20 THEN
    lv_size_class := 'SMALL';
  ELSIF lv_test_size <= 50 THEN
    lv_size_class := 'MEDIUM';
  ELSE
    lv_size_class := 'LARGE';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Solution: ' || lv_name || ' v' || TO_CHAR(lv_version));
  DBMS_OUTPUT.PUT_LINE('Score=' || TO_CHAR(lv_score) || ', Models=' || TO_CHAR(lv_nb_model) || ', Features=' || TO_CHAR(lv_nb_feature) || ', TestSize=' || TO_CHAR(lv_test_size));
  DBMS_OUTPUT.PUT_LINE('Test size class: ' || lv_size_class);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_solution_monitoring;
/

