question:
Create a small county-level natality report for a given year and county name. The report should print up to 15 matching rows, showing the county name, year, and a numeric births value. Because BIRTHS is stored as text, treat it as numeric for reporting and classify each row as either 'HIGH_BIRTHS' or 'LOW_BIRTHS' based on a births threshold provided by the user. Make sure the script gracefully handles bad inputs (like a non-numeric threshold) and situations where no data exists.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('County natality report');
DBMS_OUTPUT.PUT_LINE('Inputs -> Year=' || lv_year_str || ', County like=' || lv_county_like || ', Threshold=' || lv_threshold_str);
DBMS_OUTPUT.PUT_LINE(RPAD('COUNTY', 30) || RPAD('YEAR', 6) || RPAD('BIRTHS', 12) || 'CATEGORY');
DBMS_OUTPUT.PUT_LINE(RPAD(rec.county_of_residence, 30) || RPAD(TO_CHAR(EXTRACT(YEAR FROM rec.year)), 6) || RPAD(TO_CHAR(rec.births_num), 12) || rec.category);
DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN VALUE_ERROR THEN: 'Invalid numeric input provided.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year_str      VARCHAR2(10) := '2018';
  lv_county_like   VARCHAR2(100) := 'Los Angeles%';
  lv_threshold_str VARCHAR2(50) := '10000';

  lv_threshold_num NUMBER;
  lv_rows_printed  PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('County natality report');
  DBMS_OUTPUT.PUT_LINE('Inputs -> Year=' || lv_year_str || ', County like=' || lv_county_like || ', Threshold=' || lv_threshold_str);

  lv_threshold_num := TO_NUMBER(lv_threshold_str);

  DBMS_OUTPUT.PUT_LINE(RPAD('COUNTY', 30) || RPAD('YEAR', 6) || RPAD('BIRTHS', 12) || 'CATEGORY');

  FOR rec IN (
    SELECT
      cn.county_of_residence,
      cn.year,
      TO_NUMBER(cn.births) AS births_num,
      CASE
        WHEN TO_NUMBER(cn.births) >= lv_threshold_num THEN 'HIGH_BIRTHS'
        ELSE 'LOW_BIRTHS'
      END AS category
    FROM SDOH_CDC_WONDER_NATALITY.county_natality cn
    WHERE EXTRACT(YEAR FROM cn.year) = TO_NUMBER(lv_year_str)
      AND cn.county_of_residence LIKE lv_county_like
      AND ROWNUM <= co_report_limit
    ORDER BY cn.county_of_residence
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.county_of_residence, 30) ||
      RPAD(TO_CHAR(EXTRACT(YEAR FROM rec.year)), 6) ||
      RPAD(TO_CHAR(rec.births_num), 12) ||
      rec.category
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric input provided.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

