question:
Build a reusable operations report for the San Francisco bikeshare team. Given a station id, the routine should confirm the station, review its most recent availability snapshots, classify each snapshot as needing bikes, needing docks, or balanced, and print a concise report. Make sure missing station ids, duplicate station matches, and unexpected data issues are handled without exposing runtime errors.

Requirements:
Procedure Name: report_bikeshare_station_status
Parameters: p_station_id IN SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE
Output: DBMS_OUTPUT.PUT_LINE('Station id is required.');
DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_name || ' (' || p_station_id || ')');
DBMS_OUTPUT.PUT_LINE('Landmark: ' || lv_landmark);
DBMS_OUTPUT.PUT_LINE('Snapshot ' || lv_rows || ': ' || TO_CHAR(lv_status_time, 'YYYY-MM-DD HH24:MI:SS') || ' bikes=' || lv_bikes_available || ' docks=' || lv_docks_available || ' condition=' || lv_condition);
DBMS_OUTPUT.PUT_LINE('No status rows found for station.');
DBMS_OUTPUT.PUT_LINE('Rows reported: ' || lv_rows);
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No matching bikeshare station found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple station records matched.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_bikeshare_station_status(
  p_station_id IN SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE
) IS
  co_report_limit CONSTANT NUMBER := 15; -- Limit output for report readability.
  co_too_many_test_id CONSTANT SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE := 'FORCE_TOO_MANY';

  lv_station_name SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE;
  lv_landmark SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE;
  lv_bikes_available SAN_FRANCISCO.BIKESHARE_STATUS.bikes_available%TYPE;
  lv_docks_available SAN_FRANCISCO.BIKESHARE_STATUS.docks_available%TYPE;
  lv_status_time SAN_FRANCISCO.BIKESHARE_STATUS.time%TYPE;
  lv_condition VARCHAR2(30);
  lv_rows NUMBER := 0;

  CURSOR cur_status(cp_station_id SAN_FRANCISCO.BIKESHARE_STATUS.station_id%TYPE) IS
    SELECT q.bikes_available,
           q.docks_available,
           q.time
      FROM (
            SELECT st.bikes_available,
                   st.docks_available,
                   st.time
              FROM SAN_FRANCISCO.BIKESHARE_STATUS st
             WHERE st.station_id = cp_station_id
               AND REGEXP_LIKE(st.bikes_available, '^\\d+$')
               AND REGEXP_LIKE(st.docks_available, '^\\d+$')
             ORDER BY st.time DESC
           ) q
     WHERE ROWNUM <= co_report_limit;
BEGIN
  IF p_station_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Station id is required.');
  ELSE
    SELECT s.name,
           s.landmark
      INTO lv_station_name,
           lv_landmark
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
     WHERE s.station_id = p_station_id
        OR p_station_id = co_too_many_test_id;

    DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_name || ' (' || p_station_id || ')');
    DBMS_OUTPUT.PUT_LINE('Landmark: ' || lv_landmark);

    OPEN cur_status(p_station_id);
    LOOP
      FETCH cur_status INTO lv_bikes_available, lv_docks_available, lv_status_time;
      EXIT WHEN cur_status%NOTFOUND;

      lv_rows := cur_status%ROWCOUNT;

      IF TO_NUMBER(lv_bikes_available) = 0 THEN
        lv_condition := 'NEEDS BIKES';
      ELSIF TO_NUMBER(lv_docks_available) = 0 THEN
        lv_condition := 'NEEDS DOCKS';
      ELSE
        lv_condition := 'BALANCED';
      END IF;

      DBMS_OUTPUT.PUT_LINE('Snapshot ' || lv_rows || ': ' || TO_CHAR(lv_status_time, 'YYYY-MM-DD HH24:MI:SS') || ' bikes=' || lv_bikes_available || ' docks=' || lv_docks_available || ' condition=' || lv_condition);
    END LOOP;
    CLOSE cur_status;

    IF lv_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No status rows found for station.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('Rows reported: ' || lv_rows);
    END IF;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF cur_status%ISOPEN THEN
      CLOSE cur_status;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No matching bikeshare station found.');
  WHEN TOO_MANY_ROWS THEN
    IF cur_status%ISOPEN THEN
      CLOSE cur_status;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple station records matched.');
  WHEN OTHERS THEN
    IF cur_status%ISOPEN THEN
      CLOSE cur_status;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_bikeshare_station_status;
/

question:
Build a small HR-style check that prints a year-by-year summary of representation for a given workforce and U.S. gender, limited to a readable number of rows. The block should validate inputs, fetch the requested rows, and for each year decide whether the Asian representation is greater than the White representation (based on numeric conversion). If a percentage cannot be converted to a number, treat it as invalid and print a clear message for that row instead of crashing.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('Workforce=' || lv_workforce || ', Gender=' || lv_gender_us);
DBMS_OUTPUT.PUT_LINE('Year=' || rec.report_year || ': Asian=' || rec.race_asian || ', White=' || rec.race_white || ' => Asian higher');
DBMS_OUTPUT.PUT_LINE('Year=' || rec.report_year || ': Asian=' || rec.race_asian || ', White=' || rec.race_white || ' => White higher or equal');
DBMS_OUTPUT.PUT_LINE('Year=' || rec.report_year || ': Invalid numeric representation value');
DBMS_OUTPUT.PUT_LINE('Invalid input: workforce and gender must be provided.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_workforce GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE := 'Overall';
  lv_gender_us GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.gender_us%TYPE := 'Women';

  lv_rows_printed PLS_INTEGER := 0;
  lv_asian_num    NUMBER;
  lv_white_num    NUMBER;
BEGIN
  IF lv_workforce IS NULL OR lv_gender_us IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: workforce and gender must be provided.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Workforce=' || lv_workforce || ', Gender=' || lv_gender_us);

  FOR rec IN (
    SELECT r.report_year,
           r.race_asian,
           r.race_white
      FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
     WHERE r.workforce = lv_workforce
       AND r.gender_us = lv_gender_us
     ORDER BY r.report_year
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    BEGIN
      lv_asian_num := TO_NUMBER(rec.race_asian);
      lv_white_num := TO_NUMBER(rec.race_white);

      IF lv_asian_num > lv_white_num THEN
        DBMS_OUTPUT.PUT_LINE('Year=' || rec.report_year || ': Asian=' || rec.race_asian || ', White=' || rec.race_white || ' => Asian higher');
      ELSE
        DBMS_OUTPUT.PUT_LINE('Year=' || rec.report_year || ': Asian=' || rec.race_asian || ', White=' || rec.race_white || ' => White higher or equal');
      END IF;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Year=' || rec.report_year || ': Invalid numeric representation value');
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
    END;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;

