question:
Your support manager wants a quick customer revenue spot-check by country. Build an anonymous PL/SQL report that takes a billing country as input, prints up to 15 of the most recent invoices for that country (invoice id, invoice date, customer name, and total), and also prints a country-level summary total.

Make it resilient: if the country input is NULL, default it to the most common billing country in the invoice table. Also ensure the script never crashes—handle the common single-row SELECT exceptions and print a clear message.

Requirements:
Procedure Name: Anonymous Block.
Parameters: None.
Output: DBMS_OUTPUT.PUT_LINE('Country used: ' || lv_country);
Output: DBMS_OUTPUT.PUT_LINE('InvoiceID=' || rec.invoice_id || ', InvoiceDate=' || TO_CHAR(rec.invoice_date, 'YYYY-MM-DD') || ', Customer=' || rec.customer_name || ', Total=' || rec.total);
Output: DBMS_OUTPUT.PUT_LINE('Country invoice total: ' || lv_country_total);
Output: DBMS_OUTPUT.PUT_LINE('No invoices found for country.');
Output: DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
Output: DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No invoices found for country.'.
Exception Handling: WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'.
Exception Handling: WHEN OTHERS THEN: 'Unexpected error.'.

reference_answer:
DECLARE
  -- Input (set to NULL to use defaulting logic)
  lv_input_country CHINOOK.INVOICES.billingcountry%TYPE := NULL;

  lv_country        CHINOOK.INVOICES.billingcountry%TYPE;
  lv_country_total  CHINOOK.INVOICES.total%TYPE;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
BEGIN
  -- Default the country when input is NULL: pick the most common billing country.
  IF lv_input_country IS NULL THEN
    SELECT x.billingcountry
      INTO lv_country
      FROM (
            SELECT i.billingcountry
              FROM CHINOOK.INVOICES i
             GROUP BY i.billingcountry
             ORDER BY COUNT(*) DESC, i.billingcountry
           ) x
     WHERE ROWNUM = 1;
  ELSE
    lv_country := lv_input_country;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Country used: ' || lv_country);

  -- Print up to 15 most recent invoices for that country.
  FOR rec IN (
    SELECT i.invoiceid AS invoice_id,
           i.invoicedate AS invoice_date,
           (c.firstname || ' ' || c.lastname) AS customer_name,
           i.total AS total
      FROM CHINOOK.INVOICES i
      INNER JOIN CHINOOK.CUSTOMERS c
        ON c.customerid = i.customerid
     WHERE i.billingcountry = lv_country
     ORDER BY i.invoicedate DESC, i.invoiceid DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(
      'InvoiceID=' || rec.invoice_id ||
      ', InvoiceDate=' || TO_CHAR(rec.invoice_date, 'YYYY-MM-DD') ||
      ', Customer=' || rec.customer_name ||
      ', Total=' || rec.total
    );
  END LOOP;

  -- Country-level summary total (single-row SELECT to exercise exception handling).
  SELECT SUM(i.total)
    INTO lv_country_total
    FROM CHINOOK.INVOICES i
   WHERE i.billingcountry = lv_country;

  IF lv_country_total IS NULL THEN
    -- SUM over zero rows returns NULL: treat as no data.
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Country invoice total: ' || lv_country_total);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No invoices found for country.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

