CREATE OR REPLACE PROCEDURE report_country_debt(
  p_country_code IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.country_code%TYPE,
  p_year         IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_short_name WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.short_name%TYPE;
  lv_region     WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE;
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_country_code IS NULL OR TRIM(p_country_code) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: country code is required.');
    RETURN;
  END IF;

  IF p_year IS NULL OR TRIM(p_year) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year is required.');
    RETURN;
  END IF;

  -- Fetch descriptive country info (if missing, keep nulls and continue)
  BEGIN
    SELECT cs.short_name,
           cs.region
      INTO lv_short_name,
           lv_region
      FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
     WHERE cs.country_code = p_country_code;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      lv_short_name := NULL;
      lv_region := NULL;
  END;

  DBMS_OUTPUT.PUT_LINE('Country: ' || NVL(lv_short_name, '(unknown)') || ' | Region: ' || NVL(lv_region, '(unknown)'));

  -- List up to 15 indicators for the requested country/year
  FOR rec IN (
    SELECT id.indicator_code,
           id.indicator_name,
           id.value
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
     WHERE id.country_code = p_country_code
       AND id.year = p_year
     ORDER BY id.indicator_code
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE('Indicator: ' || rec.indicator_code || ' | ' || rec.indicator_name || ' | Value: ' || rec.value);
    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No debt indicators found for country/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_debt;
/

