DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability.
  co_region_filter CONSTANT WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE := 'Latin America & Caribbean';
  co_series_keyword CONSTANT WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_name%TYPE := 'debt service';
  co_min_year_text CONSTANT VARCHAR2(10) := '2010';
  co_force_duplicate_check CONSTANT NUMBER := 0;

  lv_region_check WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE;
  lv_min_year NUMBER;
  lv_rows_printed NUMBER := 0;
  lv_total_value NUMBER := 0;
  lv_numeric_value NUMBER;
  lv_debt_band VARCHAR2(20);

  CURSOR cur_debt_report IS
    SELECT rd.country_code,
           rd.short_name,
           rd.income_group,
           rd.year,
           rd.indicator_name,
           rd.value,
           rd.topic
      FROM (
            SELECT d.country_code,
                   cs.short_name,
                   cs.income_group,
                   d.year,
                   d.indicator_name,
                   d.value,
                   ss.topic
              FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
              INNER JOIN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
                ON cs.country_code = d.country_code
              LEFT OUTER JOIN WORLD_BANK_INTL_DEBT.SERIES_SUMMARY ss
                ON ss.series_code = d.indicator_code
             WHERE cs.region = co_region_filter
               AND REGEXP_LIKE(d.value, '^-?[0-9]+(\.[0-9]+)?$')
               AND TO_NUMBER(d.value) > 0
               AND REGEXP_LIKE(d.year, '^[0-9]{4}$')
               AND TO_NUMBER(d.year) >= lv_min_year
               AND LOWER(d.indicator_name) LIKE '%' || LOWER(co_series_keyword) || '%'
             ORDER BY TO_NUMBER(d.value) DESC
           ) rd
     WHERE ROWNUM <= co_report_limit;
BEGIN
  lv_min_year := TO_NUMBER(co_min_year_text);

  IF co_force_duplicate_check = 1 THEN
    SELECT cs.region
      INTO lv_region_check
      FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
     WHERE cs.region IS NOT NULL;
  ELSE
    SELECT cs.region
      INTO lv_region_check
      FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
     WHERE cs.region = co_region_filter
       AND ROWNUM = 1;
  END IF;

  DBMS_OUTPUT.PUT_LINE('International Debt Review for region: ' || lv_region_check);
  DBMS_OUTPUT.PUT_LINE('Minimum year: ' || lv_min_year || ', keyword: ' || co_series_keyword);

  FOR rec IN cur_debt_report LOOP
    lv_numeric_value := TO_NUMBER(rec.value);
    lv_rows_printed := lv_rows_printed + 1;
    lv_total_value := lv_total_value + lv_numeric_value;

    IF lv_numeric_value >= 1000000000 THEN
      lv_debt_band := 'BILLION_PLUS';
    ELSIF lv_numeric_value >= 1000000 THEN
      lv_debt_band := 'MILLION_PLUS';
    ELSE
      lv_debt_band := 'UNDER_MILLION';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Country=' || rec.short_name || ' (' || rec.country_code || '), Income=' || NVL(rec.income_group, 'Unclassified') || ', Year=' || rec.year || ', Band=' || lv_debt_band || ', Value=' || TO_CHAR(lv_numeric_value, 'FM999G999G999G999G990D00'));
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No debt records matched the reporting filters.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Rows printed: ' || lv_rows_printed);
    DBMS_OUTPUT.PUT_LINE('Total numeric value: ' || TO_CHAR(lv_total_value, 'FM999G999G999G999G990D00'));
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No matching region found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Region lookup returned multiple rows.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('A debt value could not be converted to a number.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

