reference_answer:
CREATE OR REPLACE PACKAGE natality_risk_pkg IS
  PROCEDURE print_maternal_morbidity_risk(
    p_year       IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.YEAR%TYPE,
    p_min_births IN NUMBER
  );
END natality_risk_pkg;
/

CREATE OR REPLACE PACKAGE BODY natality_risk_pkg IS
  PROCEDURE print_maternal_morbidity_risk(
    p_year       IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.YEAR%TYPE,
    p_min_births IN NUMBER
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_cnty IS
      SELECT cn.county_of_residence,
             cn.births
        FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
       WHERE cn.year = p_year
         AND TO_NUMBER(cn.births) >= NVL(p_min_births, 0)
       ORDER BY TO_NUMBER(cn.births) DESC;

    lv_county      SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE%TYPE;
    lv_births_vc   SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.BIRTHS%TYPE;
    lv_total_births NUMBER;

    lv_yes_births  NUMBER;
    lv_share       NUMBER;
    lv_label       VARCHAR2(10);

    lv_rows_printed PLS_INTEGER := 0;
  BEGIN
    OPEN c_cnty;

    LOOP
      FETCH c_cnty INTO lv_county, lv_births_vc;
      EXIT WHEN c_cnty%NOTFOUND;

      EXIT WHEN lv_rows_printed >= co_report_limit;

      BEGIN
        -- Births are stored as VARCHAR2 in the source; convert safely per county.
        lv_total_births := TO_NUMBER(lv_births_vc);

        -- Compute births where a maternal morbidity item is checked.
        SELECT NVL(SUM(TO_NUMBER(mm.births)), 0)
          INTO lv_yes_births
          FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_MATERNAL_MORBIDITY mm
         WHERE mm.year = p_year
           AND mm.county_of_residence = lv_county
           AND mm.maternal_morbidity_yn = 'Yes';

        IF lv_total_births = 0 THEN
          lv_share := 0;
        ELSE
          lv_share := lv_yes_births / lv_total_births;
        END IF;

        IF lv_share >= 0.10 THEN
          lv_label := 'HIGH';
        ELSIF lv_share >= 0.05 THEN
          lv_label := 'MEDIUM';
        ELSE
          lv_label := 'LOW';
        END IF;

        DBMS_OUTPUT.PUT_LINE(
          'County=' || lv_county ||
          ' | TotalBirths=' || lv_total_births ||
          ' | YesBirths=' || lv_yes_births ||
          ' | Share=' || TO_CHAR(lv_share, '0.0000') ||
          ' | Label=' || lv_label
        );

        lv_rows_printed := lv_rows_printed + 1;

      EXCEPTION
        WHEN VALUE_ERROR THEN
          DBMS_OUTPUT.PUT_LINE('County=' || lv_county || ' skipped due to invalid numeric data.');
      END;
    END LOOP;

    CLOSE c_cnty;

    IF lv_rows_printed = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No counties matched the input filters.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      IF c_cnty%ISOPEN THEN
        CLOSE c_cnty;
      END IF;
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid numeric data encountered.');
      IF c_cnty%ISOPEN THEN
        CLOSE c_cnty;
      END IF;
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
      IF c_cnty%ISOPEN THEN
        CLOSE c_cnty;
      END IF;
  END print_maternal_morbidity_risk;
END natality_risk_pkg;
/

