question:
Your demography team needs a quick operational report that compares fertility and mortality for a single country over a range of years.

Write an anonymous PL/SQL block that:
 Accepts a country name filter and a start/end year (as strings) via variables in the DECLARE section.
 Uses an explicit cursor to iterate year-by-year through matching rows.
 For each year, retrieves fertility data from AGE_SPECIFIC_FERTILITY_RATES and life expectancy + infant mortality from MORTALITY_LIFE_EXPECTANCY (join by COUNTRY_CODE and YEAR).
 Converts the numeric measures stored as VARCHAR2 to numbers; if any conversion fails for a row, skip that row and print a clear message.
 Calculates and prints a “risk_index” per year as: (infant_mortality / life_expectancy) * total_fertility_rate.
 Stops printing after 15 output rows for readability.
 Handles these error conditions without crashing: no matching rows at all, invalid year inputs, and any other unexpected error.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Fertility/Mortality trend for country filter: ' || lv_country_filter || ', years ' || lv_start_year || '-' || lv_end_year);
DBMS_OUTPUT.PUT_LINE('Year=' || rec.year || ', Country=' || rec.country_name || ', TFR=' || TO_CHAR(lv_tfr) || ', IM=' || TO_CHAR(lv_infant_mortality) || ', LE=' || TO_CHAR(lv_life_expectancy) || ', RiskIndex=' || TO_CHAR(lv_risk_index));
DBMS_OUTPUT.PUT_LINE('Skipping Year=' || rec.year || ', Country=' || rec.country_name || ' due to non-numeric measure(s).');
DBMS_OUTPUT.PUT_LINE('Output row limit reached.');
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Invalid year input.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN VALUE_ERROR THEN: 'Invalid year input.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  lv_country_filter  CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE := 'United%';
  lv_start_year      CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE := '2000';
  lv_end_year        CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE := '2010';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_start_year_n  PLS_INTEGER;
  lv_end_year_n    PLS_INTEGER;

  lv_rows_printed  PLS_INTEGER := 0;

  lv_tfr              NUMBER;
  lv_infant_mortality NUMBER;
  lv_life_expectancy  NUMBER;
  lv_risk_index       NUMBER;

  lv_dummy PLS_INTEGER;

  CURSOR cur_trend(
    p_country_filter CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
    p_start_year     CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
    p_end_year       CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
  ) IS
    SELECT f.country_name,
           f.year,
           f.total_fertility_rate,
           m.infant_mortality,
           m.life_expectancy
      FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES f
      INNER JOIN CENSUS_BUREAU_INTERNATIONAL.MORTALITY_LIFE_EXPECTANCY m
        ON m.country_code = f.country_code
       AND m.year = f.year
     WHERE f.country_name LIKE p_country_filter
       AND TO_NUMBER(f.year) BETWEEN TO_NUMBER(p_start_year) AND TO_NUMBER(p_end_year)
     ORDER BY TO_NUMBER(f.year), f.country_name;

  rec cur_trend%ROWTYPE;
BEGIN
  lv_start_year_n := TO_NUMBER(lv_start_year);
  lv_end_year_n := TO_NUMBER(lv_end_year);

  IF lv_start_year_n > lv_end_year_n THEN
    lv_dummy := lv_start_year_n;
    lv_start_year_n := lv_end_year_n;
    lv_end_year_n := lv_dummy;
    lv_start_year := TO_CHAR(lv_start_year_n);
    lv_end_year := TO_CHAR(lv_end_year_n);
  END IF;

  DBMS_OUTPUT.PUT_LINE('Fertility/Mortality trend for country filter: ' || lv_country_filter || ', years ' || lv_start_year || '-' || lv_end_year);

  OPEN cur_trend(lv_country_filter, lv_start_year, lv_end_year);
  LOOP
    FETCH cur_trend INTO rec;
    EXIT WHEN cur_trend%NOTFOUND;

    BEGIN
      lv_tfr := TO_NUMBER(rec.total_fertility_rate);
      lv_infant_mortality := TO_NUMBER(rec.infant_mortality);
      lv_life_expectancy := TO_NUMBER(rec.life_expectancy);

      IF lv_life_expectancy = 0 THEN
        DBMS_OUTPUT.PUT_LINE('Skipping Year=' || rec.year || ', Country=' || rec.country_name || ' due to non-numeric measure(s).');
        CONTINUE;
      END IF;

      lv_risk_index := (lv_infant_mortality / lv_life_expectancy) * lv_tfr;

      DBMS_OUTPUT.PUT_LINE('Year=' || rec.year || ', Country=' || rec.country_name || ', TFR=' || TO_CHAR(lv_tfr) || ', IM=' || TO_CHAR(lv_infant_mortality) || ', LE=' || TO_CHAR(lv_life_expectancy) || ', RiskIndex=' || TO_CHAR(lv_risk_index));
      lv_rows_printed := lv_rows_printed + 1;

      IF lv_rows_printed >= co_report_limit THEN
        DBMS_OUTPUT.PUT_LINE('Output row limit reached.');
        EXIT;
      END IF;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Skipping Year=' || rec.year || ', Country=' || rec.country_name || ' due to non-numeric measure(s).');
    END;
  END LOOP;
  CLOSE cur_trend;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year input.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

