CREATE OR REPLACE PACKAGE BODY station_ops_pkg IS

  PROCEDURE print_station_health(
    p_station_name IN SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE
  ) IS
    lv_station_id    SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.station_id%TYPE;
    lv_station_name  SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.name%TYPE;
    lv_region_name   SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS.name%TYPE;
    lv_capacity_txt  SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO.capacity%TYPE;
    lv_bikes_txt     SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.num_bikes_available%TYPE;
    lv_last_reported SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS.last_reported%TYPE;

    ln_capacity NUMBER;
    ln_bikes    NUMBER;
    ln_ratio    NUMBER;
  BEGIN
    -- 1) Find the station row by name; detect missing or duplicate names via exceptions.
    SELECT si.station_id,
           si.name,
           r.name,
           si.capacity
      INTO lv_station_id,
           lv_station_name,
           lv_region_name,
           lv_capacity_txt
      FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_INFO si
      LEFT JOIN SAN_FRANCISCO_BIKESHARE.BIKESHARE_REGIONS r
        ON r.region_id = si.region_id
     WHERE si.name = p_station_name;

    DBMS_OUTPUT.PUT_LINE('Station: ' || lv_station_id || ' - ' || lv_station_name);
    DBMS_OUTPUT.PUT_LINE('Region: ' || NVL(lv_region_name, 'UNKNOWN'));

    -- 2) Most recent status row (may not exist).
    BEGIN
      SELECT ss.last_reported,
             ss.num_bikes_available
        INTO lv_last_reported,
             lv_bikes_txt
        FROM SAN_FRANCISCO_BIKESHARE.BIKESHARE_STATION_STATUS ss
       WHERE ss.station_id = lv_station_id
       ORDER BY TO_NUMBER(ss.last_reported) DESC
       FETCH FIRST 1 ROWS ONLY;

      DBMS_OUTPUT.PUT_LINE('Last reported: ' || lv_last_reported);

    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No status rows found for this station.');
        RETURN;
      WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
        RETURN;
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Unexpected error.');
        RETURN;
    END;

    -- 3) Normalize and classify.
    ln_capacity := TO_NUMBER(lv_capacity_txt);
    ln_bikes    := TO_NUMBER(lv_bikes_txt);

    DBMS_OUTPUT.PUT_LINE('Bikes available: ' || lv_bikes_txt || ' / Capacity: ' || lv_capacity_txt);

    IF ln_capacity <= 0 THEN
      DBMS_OUTPUT.PUT_LINE('Classification: OK');
    ELSIF ln_bikes = 0 THEN
      DBMS_OUTPUT.PUT_LINE('Classification: CRITICAL (no bikes available)');
    ELSE
      ln_ratio := ln_bikes / ln_capacity;
      IF ln_ratio < 0.20 THEN
        DBMS_OUTPUT.PUT_LINE('Classification: LOW (below 20% bikes available)');
      ELSE
        DBMS_OUTPUT.PUT_LINE('Classification: OK');
      END IF;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_station_health;

END station_ops_pkg;
/

