CREATE OR REPLACE PROCEDURE print_model_dashboard(
  p_name    IN STACKING.MODEL_SCORE.name%TYPE,
  p_version IN STACKING.MODEL_SCORE.version%TYPE
) IS
  co_line_limit      CONSTANT PLS_INTEGER := 15; -- Limit printed lines for readability
  co_top_features    CONSTANT PLS_INTEGER := 3;  -- Business requirement: top 3 features

  lv_best_model   STACKING.MODEL_SCORE.model%TYPE;
  lv_train_score  STACKING.MODEL_SCORE.train_score%TYPE;
  lv_test_score   STACKING.MODEL_SCORE.test_score%TYPE;

  lv_lines_printed PLS_INTEGER := 0;
  lv_feature_cnt   PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_name IS NULL OR LENGTH(TRIM(p_name)) = 0 OR p_version IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Dashboard for NAME=' || p_name || ', VERSION=' || p_version);
  lv_lines_printed := lv_lines_printed + 1;

  -- Best model is highest TEST_SCORE, tie-breaker highest TRAIN_SCORE
  SELECT ms.model, ms.train_score, ms.test_score
    INTO lv_best_model, lv_train_score, lv_test_score
    FROM (
      SELECT model, train_score, test_score
        FROM STACKING.MODEL_SCORE
       WHERE name = p_name
         AND version = p_version
       ORDER BY test_score DESC, train_score DESC
    ) ms
   WHERE ROWNUM = 1;

  IF lv_lines_printed < co_line_limit THEN
    DBMS_OUTPUT.PUT_LINE('Best Model=' || lv_best_model || ', Train Score=' || lv_train_score || ', Test Score=' || lv_test_score);
    lv_lines_printed := lv_lines_printed + 1;
  END IF;

  IF lv_lines_printed < co_line_limit THEN
    DBMS_OUTPUT.PUT_LINE('Top Features:');
    lv_lines_printed := lv_lines_printed + 1;
  END IF;

  FOR rec IN (
    SELECT fi.feature, fi.importance
      FROM STACKING.FEATURE_IMPORTANCE fi
     WHERE fi.name = p_name
       AND fi.version = p_version
     ORDER BY fi.importance DESC
     FETCH FIRST co_top_features ROWS ONLY
  ) LOOP
    lv_feature_cnt := lv_feature_cnt + 1;

    IF lv_lines_printed < co_line_limit THEN
      DBMS_OUTPUT.PUT_LINE(' - ' || rec.feature || ' (importance=' || rec.importance || ')');
      lv_lines_printed := lv_lines_printed + 1;
    ELSE
      EXIT;
    END IF;
  END LOOP;

  IF lv_feature_cnt = 0 AND lv_lines_printed < co_line_limit THEN
    DBMS_OUTPUT.PUT_LINE('No features found for this NAME/VERSION.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No model scores found for this NAME/VERSION.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END print_model_dashboard;
/

