CREATE OR REPLACE PROCEDURE report_non_intersectional_rep(
  p_workforce IN GOOGLE_DEI.DAR_NON_INTERSECTIONAL_REPRESENTATION.workforce%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_workforce GOOGLE_DEI.DAR_NON_INTERSECTIONAL_REPRESENTATION.workforce%TYPE;
  ln_rows      PLS_INTEGER := 0;
BEGIN
  -- Default to the most common workforce when NULL is passed.
  IF p_workforce IS NULL THEN
    SELECT workforce
      INTO lv_workforce
      FROM (
            SELECT workforce
              FROM GOOGLE_DEI.DAR_NON_INTERSECTIONAL_REPRESENTATION
             GROUP BY workforce
             ORDER BY COUNT(*) DESC, workforce
           )
     WHERE ROWNUM = 1;
  ELSE
    lv_workforce := p_workforce;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Workforce: ' || lv_workforce);

  -- Inline query loop (implicit cursor): retrieve and safely convert text percentages to numbers.
  FOR rec IN (
    SELECT report_year,
           TO_NUMBER(gender_us_women)           AS pct_women_us,
           TO_NUMBER(gender_us_men)             AS pct_men_us,
           TO_NUMBER(race_asian)                AS pct_asian,
           TO_NUMBER(race_black)                AS pct_black,
           TO_NUMBER(race_hispanic_latinx)      AS pct_hispanic_latinx,
           TO_NUMBER(race_native_american)      AS pct_native_american,
           TO_NUMBER(race_white)                AS pct_white
      FROM GOOGLE_DEI.DAR_NON_INTERSECTIONAL_REPRESENTATION
     WHERE workforce = lv_workforce
     ORDER BY report_year DESC
  ) LOOP
    ln_rows := ln_rows + 1;
    EXIT WHEN ln_rows > co_report_limit;

    DBMS_OUTPUT.PUT_LINE('YEAR=' || rec.report_year ||
                           ' WOMEN_US=' || rec.pct_women_us ||
                           ' MEN_US=' || rec.pct_men_us ||
                           ' ASIAN=' || rec.pct_asian ||
                           ' BLACK=' || rec.pct_black ||
                           ' HISPANIC_LATINX=' || rec.pct_hispanic_latinx ||
                           ' NATIVE_AMERICAN=' || rec.pct_native_american ||
                           ' WHITE=' || rec.pct_white);
  END LOOP;

  IF ln_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_non_intersectional_rep;
/

CREATE OR REPLACE PROCEDURE wdi_country_indicator_snapshot(
  p_country_code       IN WORLD_BANK_WDI.COUNTRY_SUMMARY.country_code%TYPE,
  p_year               IN WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE,
  p_indicator_keyword  IN WORLD_BANK_WDI.INDICATORS_DATA.indicator_name%TYPE DEFAULT NULL
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_short_name   WORLD_BANK_WDI.COUNTRY_SUMMARY.short_name%TYPE;
  lv_region       WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE;
  lv_income_group WORLD_BANK_WDI.COUNTRY_SUMMARY.income_group%TYPE;

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Validate the country exists and get display attributes
  SELECT cs.short_name,
         cs.region,
         cs.income_group
    INTO lv_short_name,
         lv_region,
         lv_income_group
    FROM WORLD_BANK_WDI.COUNTRY_SUMMARY cs
   WHERE cs.country_code = p_country_code;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_short_name || ' | Region: ' || lv_region || ' | Income group: ' || lv_income_group);
  DBMS_OUTPUT.PUT_LINE('Indicators for ' || p_country_code || ' in ' || p_year || ':');

  -- Apply optional keyword filtering using control flow
  IF p_indicator_keyword IS NULL THEN
    FOR rec IN (
      SELECT id.indicator_name,
             id.value
        FROM WORLD_BANK_WDI.INDICATORS_DATA id
       WHERE id.country_code = p_country_code
         AND id.year = p_year
         AND ROWNUM <= co_report_limit
       ORDER BY id.indicator_name
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE('- ' || rec.indicator_name || ' = ' || rec.value);
    END LOOP;
  ELSE
    FOR rec IN (
      SELECT id.indicator_name,
             id.value
        FROM WORLD_BANK_WDI.INDICATORS_DATA id
       WHERE id.country_code = p_country_code
         AND id.year = p_year
         AND UPPER(id.indicator_name) LIKE '%' || UPPER(p_indicator_keyword) || '%'
         AND ROWNUM <= co_report_limit
       ORDER BY id.indicator_name
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      DBMS_OUTPUT.PUT_LINE('- ' || rec.indicator_name || ' = ' || rec.value);
    END LOOP;
  END IF;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No indicators found for the given inputs.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END wdi_country_indicator_snapshot;
/

CREATE OR REPLACE PROCEDURE report_patient_allergies(
  p_patient_id IN SYNTHEA.ALLERGIES.patient%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  IF p_patient_id IS NULL OR TRIM(p_patient_id) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Patient id is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Allergy snapshot for patient: ' || p_patient_id);

  FOR rec IN (
    SELECT a.start_date,
           a.stop_date,
           a.code,
           a.description
      FROM SYNTHEA.ALLERGIES a
     WHERE a.patient = p_patient_id
     ORDER BY a.start_date DESC
