      'Start=' || TO_CHAR(rec.start_date, 'YYYY-MM-DD') ||
      ' Stop=' || NVL(TO_CHAR(rec.stop_date, 'YYYY-MM-DD'), 'ACTIVE') ||
      ' Code=' || rec.code ||
      ' Desc=' || rec.description
    );

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No allergies found for patient.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_patient_allergies;
