question:
Build a reusable reporting routine for our F1 analytics team: given a season year, print a compact leaderboard of the top constructors by total race points for that season. For each constructor, also show the driver who contributed the most points to that constructor in that season (tie-break by driver_id). Limit output to a maximum of 15 constructors for readability.

Use an explicit cursor to iterate through the top constructors, and within the loop determine the top contributing driver for the current constructor. Include clear messaging when the year is null/invalid or when there are no race results for the requested year. Make sure all exceptions are handled gracefully without raising errors to the client.

Requirements:
Procedure Name: f1_reporting_pkg.print_constructor_contribution_report
Parameters:
p_year IN F1.RACES.year%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Constructor contribution report for year: ' || p_year);
DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD('Pos', 4) || ' ' || RPAD('Constructor', 25) || ' ' || LPAD('Team Pts', 9) || '  ' || RPAD('Top Driver', 25) || ' ' || LPAD('Drv Pts', 7));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(lv_pos, 4) || ' ' || RPAD(rec.constructor_name, 25) || ' ' || LPAD(TO_CHAR(rec.team_points), 9) || '  ' || RPAD(lv_top_driver_name, 25) || ' ' || LPAD(TO_CHAR(lv_top_driver_points), 7));
DBMS_OUTPUT.PUT_LINE('No year provided.');
DBMS_OUTPUT.PUT_LINE('No race results found for the requested year.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No race results found for the requested year.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE f1_reporting_pkg IS
  PROCEDURE print_constructor_contribution_report(
    p_year IN F1.RACES.year%TYPE
  );
END f1_reporting_pkg;
/

CREATE OR REPLACE PACKAGE BODY f1_reporting_pkg IS
  PROCEDURE print_constructor_contribution_report(
    p_year IN F1.RACES.year%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR cur_top_constructors IS
      SELECT *
      FROM (
        SELECT c.name AS constructor_name,
               rsl.constructor_id AS constructor_id,
               SUM(rsl.points) AS team_points
          FROM F1.RACES ra
          INNER JOIN F1.RESULTS rsl
            ON rsl.race_id = ra.race_id
          INNER JOIN F1.CONSTRUCTORS c
            ON c.constructor_id = rsl.constructor_id
         WHERE ra.year = p_year
         GROUP BY c.name, rsl.constructor_id
         ORDER BY SUM(rsl.points) DESC, rsl.constructor_id ASC
      )
      WHERE ROWNUM <= co_report_limit;

    lv_pos              PLS_INTEGER := 0;
    lv_has_rows         BOOLEAN := FALSE;

    lv_top_driver_id    F1.RESULTS.driver_id%TYPE;
    lv_top_driver_name  VARCHAR2(600);
    lv_top_driver_points F1.RESULTS.points%TYPE;
  BEGIN
    IF p_year IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('No year provided.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Constructor contribution report for year: ' || p_year);
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));
    DBMS_OUTPUT.PUT_LINE(RPAD('Pos', 4) || ' ' || RPAD('Constructor', 25) || ' ' || LPAD('Team Pts', 9) || '  ' || RPAD('Top Driver', 25) || ' ' || LPAD('Drv Pts', 7));
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 70, '-'));

    FOR rec IN cur_top_constructors LOOP
      lv_has_rows := TRUE;
      lv_pos := lv_pos + 1;

      BEGIN
        SELECT driver_id,
               driver_name,
               driver_points
          INTO lv_top_driver_id,
               lv_top_driver_name,
               lv_top_driver_points
          FROM (
            SELECT rsl.driver_id AS driver_id,
                   (d.forename || ' ' || d.surname) AS driver_name,
                   SUM(rsl.points) AS driver_points
              FROM F1.RACES ra
              INNER JOIN F1.RESULTS rsl
                ON rsl.race_id = ra.race_id
              INNER JOIN F1.DRIVERS d
                ON d.driver_id = rsl.driver_id
             WHERE ra.year = p_year
               AND rsl.constructor_id = rec.constructor_id
             GROUP BY rsl.driver_id, d.forename, d.surname
             ORDER BY SUM(rsl.points) DESC, rsl.driver_id ASC
          )
         WHERE ROWNUM = 1;

        DBMS_OUTPUT.PUT_LINE(
          RPAD(lv_pos, 4) || ' ' ||
          RPAD(rec.constructor_name, 25) || ' ' ||
          LPAD(TO_CHAR(rec.team_points), 9) || '  ' ||
          RPAD(lv_top_driver_name, 25) || ' ' ||
          LPAD(TO_CHAR(lv_top_driver_points), 7)
        );
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          lv_top_driver_name := 'UNKNOWN';
          lv_top_driver_points := 0;
          DBMS_OUTPUT.PUT_LINE(
            RPAD(lv_pos, 4) || ' ' ||
            RPAD(rec.constructor_name, 25) || ' ' ||
            LPAD(TO_CHAR(rec.team_points), 9) || '  ' ||
            RPAD(lv_top_driver_name, 25) || ' ' ||
            LPAD(TO_CHAR(lv_top_driver_points), 7)
          );
      END;
    END LOOP;

    IF NOT lv_has_rows THEN
      DBMS_OUTPUT.PUT_LINE('No race results found for the requested year.');
      RETURN;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No race results found for the requested year.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_constructor_contribution_report;
END f1_reporting_pkg;
/

