reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 10; -- Limit output for report readability

  lv_input_station_name SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE := NULL;

  lv_station_id   SAN_FRANCISCO.BIKESHARE_STATIONS.station_id%TYPE;
  lv_station_name SAN_FRANCISCO.BIKESHARE_STATIONS.name%TYPE;
  lv_landmark     SAN_FRANCISCO.BIKESHARE_STATIONS.landmark%TYPE;

  lv_trip_count   NUMBER;
  lv_demand_class VARCHAR2(10);

  lv_status_rows  PLS_INTEGER := 0;
BEGIN
  IF lv_input_station_name IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input station name is NULL; using busiest start station from trip history.');

    SELECT x.start_station_id,
           x.start_station_name
      INTO lv_station_id,
           lv_station_name
      FROM (
        SELECT t.start_station_id,
               t.start_station_name,
               COUNT(*) AS trip_cnt
          FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
         WHERE t.start_station_id IS NOT NULL
           AND t.start_station_name IS NOT NULL
         GROUP BY t.start_station_id, t.start_station_name
         ORDER BY COUNT(*) DESC, t.start_station_id
      ) x
     WHERE ROWNUM = 1;
  ELSE
    DBMS_OUTPUT.PUT_LINE('Input station name provided: ' || lv_input_station_name);

    SELECT s.station_id,
           s.name
      INTO lv_station_id,
           lv_station_name
      FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
     WHERE s.name = lv_input_station_name;
  END IF;

  SELECT s.landmark
    INTO lv_landmark
    FROM SAN_FRANCISCO.BIKESHARE_STATIONS s
   WHERE s.station_id = lv_station_id;

  DBMS_OUTPUT.PUT_LINE('Using station: ' || lv_station_id || ' - ' || lv_station_name || ' (' || lv_landmark || ')');

  SELECT COUNT(*)
    INTO lv_trip_count
    FROM SAN_FRANCISCO.BIKESHARE_TRIPS t
   WHERE t.start_station_id = lv_station_id;

  IF lv_trip_count >= 100 THEN
    lv_demand_class := 'HIGH';
  ELSE
    lv_demand_class := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Demand classification: ' || lv_demand_class || ' (trip count=' || lv_trip_count || ')');
  DBMS_OUTPUT.PUT_LINE('Latest status snapshots (most recent first), max rows = ' || co_report_limit);

  FOR r IN (
    SELECT st.time,
           st.bikes_available AS bikes,
           st.docks_available AS docks
      FROM SAN_FRANCISCO.BIKESHARE_STATUS st
     WHERE st.station_id = lv_station_id
     ORDER BY st.time DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_status_rows := lv_status_rows + 1;
    DBMS_OUTPUT.PUT_LINE(
      'As of ' || TO_CHAR(r.time, 'YYYY-MM-DD HH24:MI:SS') || ': bikes=' || r.bikes || ', docks=' || r.docks
    );
  END LOOP;

  IF lv_status_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No status snapshots found for this station.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

