question:
Operations wants a quick reusable report for a given Sales Order that helps validate pricing. Build a stored procedure that takes a SalesOrderID and prints up to 15 line items for that order, including product name, order quantity, unit price, discount, and the computed line total (qty * unit price * (1 - discount)). Also print a one-line summary showing the total number of lines reported and the sum of the computed line totals. If the input SalesOrderID is NULL, print a clear message and stop.

Requirements:
Procedure Name: report_sales_order_lines
Parameters:
p_salesorderid IN ADVENTUREWORKS.SALESORDERDETAIL.salesorderid%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('SalesOrderID is required.');
DBMS_OUTPUT.PUT_LINE('Order ' || p_salesorderid || ' | Showing up to ' || co_report_limit || ' lines');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD('LineID', 8) || RPAD('Product', 35) || LPAD('Qty', 6) || LPAD('UnitPrice', 12) || LPAD('Disc', 8) || LPAD('LineTotal', 15));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(TO_CHAR(rec.salesorderdetailid), 8) || RPAD(SUBSTR(rec.product_name, 1, 34), 35) || LPAD(TO_CHAR(rec.orderqty), 6) || LPAD(TO_CHAR(rec.unitprice, 'FM9999990.00'), 12) || LPAD(TO_CHAR(rec.unitpricediscount, 'FM0.0000'), 8) || LPAD(TO_CHAR(rec.line_total, 'FM9999990.00'), 15));
DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
DBMS_OUTPUT.PUT_LINE('Lines reported: ' || lv_lines_reported || ' | Sum of line totals: ' || TO_CHAR(lv_sum_line_total, 'FM9999990.00'));
DBMS_OUTPUT.PUT_LINE('No line items found for SalesOrderID ' || p_salesorderid || '.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No line items found for SalesOrderID ' || p_salesorderid || '.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_sales_order_lines(
  p_salesorderid IN ADVENTUREWORKS.SALESORDERDETAIL.salesorderid%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_lines_reported PLS_INTEGER := 0;
  lv_sum_line_total NUMBER := 0;
  lv_has_rows       BOOLEAN := FALSE;
BEGIN
  IF p_salesorderid IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('SalesOrderID is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Order ' || p_salesorderid || ' | Showing up to ' || co_report_limit || ' lines');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
  DBMS_OUTPUT.PUT_LINE(
    RPAD('LineID', 8) || RPAD('Product', 35) || LPAD('Qty', 6) ||
    LPAD('UnitPrice', 12) || LPAD('Disc', 8) || LPAD('LineTotal', 15)
  );
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));

  FOR rec IN (
    SELECT *
    FROM (
      SELECT
        sod.salesorderdetailid,
        p.name AS product_name,
        sod.orderqty,
        sod.unitprice,
        sod.unitpricediscount,
        (sod.orderqty * sod.unitprice * (1 - sod.unitpricediscount)) AS line_total
      FROM ADVENTUREWORKS.SALESORDERDETAIL sod
      INNER JOIN ADVENTUREWORKS.PRODUCT p
        ON p.productid = sod.productid
      WHERE sod.salesorderid = p_salesorderid
      ORDER BY sod.salesorderdetailid
    )
    WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_has_rows := TRUE;
    lv_lines_reported := lv_lines_reported + 1;
    lv_sum_line_total := lv_sum_line_total + rec.line_total;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(rec.salesorderdetailid), 8) ||
      RPAD(SUBSTR(rec.product_name, 1, 34), 35) ||
      LPAD(TO_CHAR(rec.orderqty), 6) ||
      LPAD(TO_CHAR(rec.unitprice, 'FM9999990.00'), 12) ||
      LPAD(TO_CHAR(rec.unitpricediscount, 'FM0.0000'), 8) ||
      LPAD(TO_CHAR(rec.line_total, 'FM9999990.00'), 15)
    );
  END LOOP;

  IF NOT lv_has_rows THEN
    RAISE NO_DATA_FOUND;
  END IF;

  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
  DBMS_OUTPUT.PUT_LINE(
    'Lines reported: ' || lv_lines_reported ||
    ' | Sum of line totals: ' || TO_CHAR(lv_sum_line_total, 'FM9999990.00')
  );

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No line items found for SalesOrderID ' || p_salesorderid || '.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_sales_order_lines;
/

CREATE OR REPLACE PROCEDURE team_season_snapshot(
  p_year    IN BASEBALL.TEAM.YEAR%TYPE,
  p_team_id IN BASEBALL.TEAM.TEAM_ID%TYPE
) IS
  co_top_n CONSTANT PLS_INTEGER := 3; -- Keep output small and readable

  lv_team_name BASEBALL.TEAM.NAME%TYPE;
  lv_w         BASEBALL.TEAM.W%TYPE;
  lv_l         BASEBALL.TEAM.L%TYPE;

  lv_rows_printed PLS_INTEGER := 0;
  lv_rank         PLS_INTEGER := 0;
BEGIN
  -- Basic input validation
  IF p_year IS NULL OR p_team_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input year and team id are required.');
    RETURN;
  END IF;

  -- Team header (single-row lookup)
  SELECT t.NAME, t.W, t.L
    INTO lv_team_name, lv_w, lv_l
    FROM BASEBALL.TEAM t
   WHERE t.YEAR = p_year
     AND t.TEAM_ID = p_team_id;

  DBMS_OUTPUT.PUT_LINE('Team: ' || lv_team_name || ' (' || p_team_id || '), Year: ' || p_year);
  DBMS_OUTPUT.PUT_LINE('Record: ' || lv_w || '-' || lv_l);

  IF lv_w > lv_l THEN
    DBMS_OUTPUT.PUT_LINE('Outcome: Winning season');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Outcome: Losing season');
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top HR hitters (up to ' || co_top_n || '):');

  -- Top hitters by total HR across stints; limited to 3
  FOR rec IN (
    SELECT b.PLAYER_ID AS player_id,
           SUM(b.HR)   AS total_hr
      FROM BASEBALL.BATTING b
     WHERE b.YEAR = p_year
       AND b.TEAM_ID = p_team_id
     GROUP BY b.PLAYER_ID
     ORDER BY SUM(b.HR) DESC, b.PLAYER_ID
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_top_n;

    lv_rank := lv_rank + 1;
    DBMS_OUTPUT.PUT_LINE('  ' || lv_rank || '. ' || rec.player_id || ' - HR: ' || rec.total_hr);

    lv_rows_printed := lv_rows_printed + 1;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No batting records found for this team/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No team found for the given year and team id.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple team rows found for the given year and team id.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END team_season_snapshot;
/

CREATE OR REPLACE PROCEDURE report_patient_allergy_followup(
  p_patient_id IN SYNTHEA.PATIENTS.id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_patient_id   SYNTHEA.PATIENTS.id%TYPE;
  lv_patient_name VARCHAR2(300);
  lv_encounter_cnt NUMBER;

  lv_rows_printed PLS_INTEGER := 0;

  CURSOR cur_allergies(p_pid SYNTHEA.ALLERGIES.patient%TYPE) IS
    SELECT a.start_date,
           a.stop_date,
           a.description
      FROM SYNTHEA.ALLERGIES a
     WHERE a.patient = p_pid
     ORDER BY a.start_date DESC;

  rec_allergy cur_allergies%ROWTYPE;
BEGIN
  IF p_patient_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Patient ID is required.');
    RETURN;
  END IF;

  lv_patient_id := p_patient_id;

  SELECT p.first || ' ' || p.last
    INTO lv_patient_name
    FROM SYNTHEA.PATIENTS p
   WHERE p.id = lv_patient_id;

  SELECT COUNT(*)
    INTO lv_encounter_cnt
    FROM SYNTHEA.ENCOUNTERS e
   WHERE e.patient = lv_patient_id;

  DBMS_OUTPUT.PUT_LINE('Patient: ' || lv_patient_id || ' - ' || lv_patient_name);
  DBMS_OUTPUT.PUT_LINE('Encounter count: ' || lv_encounter_cnt);
  DBMS_OUTPUT.PUT_LINE('Allergy follow-up (most recent first), max rows = ' || co_report_limit);

  OPEN cur_allergies(lv_patient_id);
  LOOP
    FETCH cur_allergies INTO rec_allergy;
    EXIT WHEN cur_allergies%NOTFOUND;

    lv_rows_printed := lv_rows_printed + 1;

    DBMS_OUTPUT.PUT_LINE(
      '  ' || TO_CHAR(rec_allergy.start_date, 'YYYY-MM-DD') ||
      ' to ' || NVL(TO_CHAR(rec_allergy.stop_date, 'YYYY-MM-DD'), 'OPEN') ||
      ' | ' || rec_allergy.description
    );

    EXIT WHEN lv_rows_printed >= co_report_limit;
  END LOOP;
  CLOSE cur_allergies;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No allergies found for this patient.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF cur_allergies%ISOPEN THEN
      CLOSE cur_allergies;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF cur_allergies%ISOPEN THEN
      CLOSE cur_allergies;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF cur_allergies%ISOPEN THEN
      CLOSE cur_allergies;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_patient_allergy_followup;
/

