question:
Your analytics team needs a quick country indicator snapshot for a training demo. Build an anonymous PL/SQL report that accepts a region name, an indicator code, and a year, then prints up to 15 countries in that region with their indicator value for that year. Use COUNTRY_SUMMARY to scope the countries in the region, and join to INDICATORS_DATA for the requested indicator/year. Also include the series name from SERIES_SUMMARY.

Business rules:
- If p_region is NULL, treat it as 'World'.
- If p_year is NULL, use the maximum year available in INDICATORS_DATA for the given indicator code.
- If p_indicator_code is NULL, print a message and exit without querying.
- Values are stored as VARCHAR2; try to convert to NUMBER. If conversion fails for a country, print the row with 'value_unusable'.
- Print a header line and then one line per country in the format: "<short_name> (<country_code>) | <indicator_code> | <year> | <value_status> | <value>"

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output: DBMS_OUTPUT.PUT_LINE('Report: Region=' || lv_region || ' | Indicator=' || lv_indicator_code || ' | Year=' || lv_year);
DBMS_OUTPUT.PUT_LINE('Top ' || co_report_limit || ' rows max. Format: <short_name> (<country_code>) | <indicator_code> | <year> | <value_status> | <value>');
DBMS_OUTPUT.PUT_LINE(r_country.short_name || ' (' || r_country.country_code || ') | ' || lv_indicator_code || ' | ' || lv_year || ' | value_ok | ' || TO_CHAR(lv_value_num));
DBMS_OUTPUT.PUT_LINE(r_country.short_name || ' (' || r_country.country_code || ') | ' || lv_indicator_code || ' | ' || lv_year || ' | value_unusable | ' || NVL(r_country.value_raw, 'NULL'));
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
DBMS_OUTPUT.PUT_LINE('Indicator code is required.');
Exception Handling: WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_region         WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE := 'World';
  lv_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE := 'SP.POP.TOTL';
  lv_year           WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE := NULL;

  lv_effective_year WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;
  lv_series_name    WORLD_BANK_WDI.SERIES_SUMMARY.indicator_name%TYPE;

  CURSOR c_countries(
    p_region         WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE,
    p_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE,
    p_year           WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE
  ) IS
    SELECT cs.short_name,
           cs.country_code,
           id.value AS value_raw
      FROM WORLD_BANK_WDI.COUNTRY_SUMMARY cs
      INNER JOIN WORLD_BANK_WDI.INDICATORS_DATA id
        ON id.country_code = cs.country_code
     WHERE cs.region = p_region
       AND id.indicator_code = p_indicator_code
       AND id.year = p_year
       AND ROWNUM <= co_report_limit
     ORDER BY cs.short_name;

  lv_value_num NUMBER;
BEGIN
  IF lv_region IS NULL THEN
    lv_region := 'World';
  END IF;

  IF lv_indicator_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Indicator code is required.');
    RETURN;
  END IF;

  IF lv_year IS NULL THEN
    SELECT MAX(id.year)
      INTO lv_effective_year
      FROM WORLD_BANK_WDI.INDICATORS_DATA id
     WHERE id.indicator_code = lv_indicator_code;
  ELSE
    lv_effective_year := lv_year;
  END IF;

  lv_year := lv_effective_year;

  SELECT ss.indicator_name
    INTO lv_series_name
    FROM WORLD_BANK_WDI.SERIES_SUMMARY ss
   WHERE ss.series_code = lv_indicator_code;

  DBMS_OUTPUT.PUT_LINE('Report: Region=' || lv_region || ' | Indicator=' || lv_indicator_code || ' | Year=' || lv_year);
  DBMS_OUTPUT.PUT_LINE('Top ' || co_report_limit || ' rows max. Format: <short_name> (<country_code>) | <indicator_code> | <year> | <value_status> | <value>');

  FOR r_country IN c_countries(lv_region, lv_indicator_code, lv_year) LOOP
    BEGIN
      lv_value_num := TO_NUMBER(r_country.value_raw);
      DBMS_OUTPUT.PUT_LINE(r_country.short_name || ' (' || r_country.country_code || ') | ' || lv_indicator_code || ' | ' || lv_year || ' | value_ok | ' || TO_CHAR(lv_value_num));
    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE(r_country.short_name || ' (' || r_country.country_code || ') | ' || lv_indicator_code || ' | ' || lv_year || ' | value_unusable | ' || NVL(r_country.value_raw, 'NULL'));
    END;
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

