DECLARE
  lv_country             MUSIC.CUSTOMER.country%TYPE := 'USA';
  lv_vip_threshold       MUSIC.INVOICE.total%TYPE := 40;
  lv_active_min_invoices PLS_INTEGER := 3;

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country);
  DBMS_OUTPUT.PUT_LINE('VIP threshold: ' || TO_CHAR(lv_vip_threshold) || ', Active minimum invoices: ' || TO_CHAR(lv_active_min_invoices));

  FOR rec IN (
    WITH cust_spend AS (
      SELECT
        c.customerid,
        c.firstname || ' ' || c.lastname AS customer_name,
        SUM(i.total) AS total_spend,
        COUNT(*) AS invoice_count
      FROM MUSIC.CUSTOMER c
      INNER JOIN MUSIC.INVOICE i
        ON i.customerid = c.customerid
      WHERE c.country = lv_country
      GROUP BY c.customerid, c.firstname, c.lastname
    )
    SELECT
      cs.customer_name,
      cs.total_spend,
      cs.invoice_count,
      CASE
        WHEN cs.total_spend >= lv_vip_threshold THEN 'VIP'
        WHEN cs.invoice_count >= lv_active_min_invoices THEN 'ACTIVE'
        ELSE 'INACTIVE'
      END AS status_label
    FROM cust_spend cs
    ORDER BY cs.total_spend DESC, cs.invoice_count DESC, cs.customer_name
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    lv_rows_printed := lv_rows_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      'Customer: ' || rec.customer_name ||
      ' | Total Spend: ' || TO_CHAR(rec.total_spend) ||
      ' | Invoice Count: ' || TO_CHAR(rec.invoice_count) ||
      ' | Status: ' || rec.status_label
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No customers found for that country.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

