CREATE OR REPLACE PROCEDURE report_runner_delivery_perf(
  p_runner_id IN MODERN_DATA.PIZZA_RUNNER_ORDERS.runner_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_total_completed NUMBER;
  lv_avg_distance    NUMBER;
  lv_avg_duration    NUMBER;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Runner delivery performance report');

  IF p_runner_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Runner id is required.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Runner ID: ' || p_runner_id);

  -- Summary across all completed deliveries for this runner
  SELECT COUNT(*), AVG(distance), AVG(duration)
    INTO lv_total_completed, lv_avg_distance, lv_avg_duration
    FROM MODERN_DATA.PIZZA_RUNNER_ORDERS r
   WHERE r.runner_id = p_runner_id
     AND r.cancellation IS NULL;

  DBMS_OUTPUT.PUT_LINE('Completed deliveries (total): ' || lv_total_completed);
  DBMS_OUTPUT.PUT_LINE('Average distance (km): ' || TO_CHAR(lv_avg_distance));
  DBMS_OUTPUT.PUT_LINE('Average duration (min): ' || TO_CHAR(lv_avg_duration));

  IF lv_total_completed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No completed deliveries found for runner.');
    RETURN;
  END IF;

  -- Detail report: most recent completed deliveries (up to co_report_limit)
  FOR rec IN (
    SELECT order_id,
           TO_DATE(pickup_time, 'YYYY-MM-DD HH24:MI:SS') AS pickup_ts,
           distance AS distance_km,
           duration AS duration_min,
           CASE
             WHEN distance IS NULL OR duration IS NULL OR distance = 0 OR duration = 0 THEN NULL
             ELSE distance / duration
           END AS speed_km_per_min
      FROM MODERN_DATA.PIZZA_RUNNER_ORDERS r
     WHERE r.runner_id = p_runner_id
       AND r.cancellation IS NULL
     ORDER BY TO_DATE(pickup_time, 'YYYY-MM-DD HH24:MI:SS') DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    IF rec.speed_km_per_min IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Order ' || rec.order_id || ' - Insufficient data to compute speed (missing/zero distance or duration).');
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'Order ' || rec.order_id ||
        ' - Pickup: ' || TO_CHAR(rec.pickup_ts, 'YYYY-MM-DD HH24:MI:SS') ||
        ', Distance(km): ' || TO_CHAR(rec.distance_km) ||
        ', Duration(min): ' || TO_CHAR(rec.duration_min) ||
        ', Speed(km/min): ' || TO_CHAR(rec.speed_km_per_min)
      );
    END IF;
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_runner_delivery_perf;
/

DECLARE
  -- Report readability limit
  co_report_limit CONSTANT PLS_INTEGER := 15;

  -- Inputs (set these as needed)
  lv_area_name  BLS.CPI_U.area_name%TYPE := 'U.S. city average';
  lv_item_name  BLS.CPI_U.item_name%TYPE := 'All items';
  lv_year       BLS.CPI_U.year%TYPE := '2020';

  lv_rows_printed PLS_INTEGER := 0;

  lv_value_num NUMBER;
  lv_category  VARCHAR2(20);
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI-U sample for Area=' || lv_area_name || ', Item=' || lv_item_name || ', Year=' || lv_year);

  FOR rec IN (
    SELECT c.area_name,
           c.item_name,
           c.year,
           c.period,
           c.value,
           c.c_date
      FROM BLS.CPI_U c
     WHERE c.area_name = lv_area_name
       AND c.item_name = lv_item_name
       AND c.year = lv_year
     ORDER BY c.c_date
  ) LOOP
    EXIT WHEN lv_rows_printed >= co_report_limit;

    BEGIN
      lv_value_num := TO_NUMBER(rec.value);

      IF lv_value_num > 300 THEN
        lv_category := 'Above 300';
      ELSE
        lv_category := 'Normal';
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        'AsOf=' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') ||
        ', Period=' || rec.period ||
        ', Value=' || rec.value ||
        ', ValueNum=' || TO_CHAR(lv_value_num) ||
        ', Category=' || lv_category
      );

      lv_rows_printed := lv_rows_printed + 1;
    EXCEPTION
      WHEN VALUE_ERROR THEN
        DBMS_OUTPUT.PUT_LINE('Bad numeric CPI value encountered; skipping this row.');
    END;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No rows found for the given filters.');
