DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_state        CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE := 'CA';
  lv_min_episodes VARCHAR2(20) := '100';

  lv_min_episodes_num NUMBER;
  lv_printed_count    PLS_INTEGER := 0;
BEGIN
  IF lv_state IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('State is required.');
    RETURN;
  END IF;

  IF lv_min_episodes IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Minimum episode threshold is required.');
    RETURN;
  END IF;

  lv_min_episodes_num := TO_NUMBER(TRIM(lv_min_episodes));

  FOR r IN (
    SELECT provider_id,
           agency_name,
           city,
           TO_NUMBER(TRIM(total_episodes_non_lupa)) AS total_episodes_num
      FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES
     WHERE state = lv_state
       AND TO_NUMBER(TRIM(total_episodes_non_lupa)) >= lv_min_episodes_num
     ORDER BY TO_NUMBER(TRIM(total_episodes_non_lupa)) DESC
  ) LOOP
    EXIT WHEN lv_printed_count >= co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      'Provider: ' || r.provider_id ||
      ' | Agency: ' || r.agency_name ||
      ' | City: ' || r.city ||
      ' | Total Episodes (Non-LUPA): ' || TO_CHAR(r.total_episodes_num)
    );

    lv_printed_count := lv_printed_count + 1;
  END LOOP;

  IF lv_printed_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No agencies matched the criteria.');
    RETURN;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No agencies matched the criteria.');
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Invalid number provided.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

