question:
You are building a reusable reporting routine for an operations analyst who reviews Medicare provider performance by state.

Create a package that exposes one procedure to print a “Top Providers by Medicare Payment” report for a given state. The routine must:
- Accept a 2-character state code and a maximum number of providers to print.
- Pull results from BOTH:
  1) HOME_HEALTH_AGENCIES (use TOTAL_HHA_MEDICARE_PAYMENT_AMOUNT_NON_LUPA)
  2) HOSPICE_PROVIDERS (use TOTAL_MEDICARE_PAYMENT_AMOUNT)
- Convert the payment amount columns from VARCHAR2 to NUMBER safely.
- For each provider type, print up to the requested number of rows (but never more than 15) sorted by the numeric payment amount descending.
- Use an explicit cursor (declare CURSOR IS and iterate over it) and demonstrate control flow to handle invalid inputs (null state, wrong length, etc.).
- If the state has no matching providers in one or both provider types, print a clear message for that section and continue.

Requirements:
Procedure Name: cms_provider_rpt.print_top_payments_by_state
Parameters:
p_state IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE
p_max_rows IN NUMBER
Output:
DBMS_OUTPUT.PUT_LINE('State: ' || UPPER(TRIM(p_state)) || ' | Row limit: ' || TO_CHAR(lv_limit));
DBMS_OUTPUT.PUT_LINE('--- HOME HEALTH AGENCIES (Top by Medicare Payment Non-LUPA) ---');
DBMS_OUTPUT.PUT_LINE('No matching home health agencies for state ' || UPPER(TRIM(p_state)) || '.');
DBMS_OUTPUT.PUT_LINE(RPAD('Provider ID', 12) || RPAD('Agency Name', 42) || LPAD('Payment', 18));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.provider_id, 12) || RPAD(SUBSTR(rec.name, 1, 40), 42) || LPAD(TO_CHAR(rec.payment_amt, '9999999999990D00'), 18));
DBMS_OUTPUT.PUT_LINE('--- HOSPICE PROVIDERS (Top by Medicare Payment Amount) ---');
DBMS_OUTPUT.PUT_LINE('No matching hospice providers for state ' || UPPER(TRIM(p_state)) || '.');
DBMS_OUTPUT.PUT_LINE(RPAD('Provider ID', 12) || RPAD('Name', 42) || LPAD('Payment', 18));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.provider_id, 12) || RPAD(SUBSTR(rec.name, 1, 40), 42) || LPAD(TO_CHAR(rec.payment_amt, '9999999999990D00'), 18));
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN VALUE_ERROR THEN: 'Invalid numeric conversion or parameter value.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE cms_provider_rpt IS
  PROCEDURE print_top_payments_by_state(
    p_state    IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE,
    p_max_rows IN NUMBER
  );
END cms_provider_rpt;
/

CREATE OR REPLACE PACKAGE BODY cms_provider_rpt IS

  PROCEDURE print_top_payments_by_state(
    p_state    IN CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE,
    p_max_rows IN NUMBER
  ) IS
    co_abs_max_rows CONSTANT PLS_INTEGER := 15; -- Hard cap for report readability

    lv_state CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE;
    lv_limit PLS_INTEGER;

    lv_hha_rows     PLS_INTEGER := 0;
    lv_hospice_rows PLS_INTEGER := 0;

    CURSOR cur_hha(cp_state CMS_MEDICARE.HOME_HEALTH_AGENCIES.state%TYPE, cp_limit PLS_INTEGER) IS
      SELECT provider_id,
             agency_name AS name,
             TO_NUMBER(REPLACE(total_hha_medicare_payment_amount_non_lupa, ',', '')) AS payment_amt
        FROM (
              SELECT h.provider_id,
                     h.agency_name,
                     h.total_hha_medicare_payment_amount_non_lupa
                FROM CMS_MEDICARE.HOME_HEALTH_AGENCIES h
               WHERE h.state = cp_state
                 AND h.total_hha_medicare_payment_amount_non_lupa IS NOT NULL
                 AND REGEXP_LIKE(h.total_hha_medicare_payment_amount_non_lupa, '^\s*[0-9]+(\.[0-9]+)?\s*$')
               ORDER BY TO_NUMBER(REPLACE(h.total_hha_medicare_payment_amount_non_lupa, ',', '')) DESC
             )
       WHERE ROWNUM <= cp_limit;

    CURSOR cur_hospice(cp_state CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE, cp_limit PLS_INTEGER) IS
      SELECT provider_id,
             name,
             TO_NUMBER(REPLACE(total_medicare_payment_amount, ',', '')) AS payment_amt
        FROM (
              SELECT hp.provider_id,
                     hp.name,
                     hp.total_medicare_payment_amount
                FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
               WHERE hp.state = cp_state
                 AND hp.total_medicare_payment_amount IS NOT NULL
                 AND REGEXP_LIKE(hp.total_medicare_payment_amount, '^\s*[0-9]+(\.[0-9]+)?\s*$')
               ORDER BY TO_NUMBER(REPLACE(hp.total_medicare_payment_amount, ',', '')) DESC
             )
       WHERE ROWNUM <= cp_limit;

  BEGIN
    -- Parameter normalization + validation (control flow)
    lv_state := UPPER(TRIM(p_state));

    IF lv_state IS NULL OR LENGTH(lv_state) <> 2 THEN
      DBMS_OUTPUT.PUT_LINE('State: ' || UPPER(TRIM(p_state)) || ' | Row limit: ' || TO_CHAR(0));
      DBMS_OUTPUT.PUT_LINE('--- HOME HEALTH AGENCIES (Top by Medicare Payment Non-LUPA) ---');
      DBMS_OUTPUT.PUT_LINE('No matching home health agencies for state ' || UPPER(TRIM(p_state)) || '.');
      DBMS_OUTPUT.PUT_LINE('--- HOSPICE PROVIDERS (Top by Medicare Payment Amount) ---');
      DBMS_OUTPUT.PUT_LINE('No matching hospice providers for state ' || UPPER(TRIM(p_state)) || '.');
      RETURN;
    END IF;

    IF p_max_rows IS NULL OR p_max_rows < 1 THEN
      lv_limit := 1;
    ELSIF p_max_rows > co_abs_max_rows THEN
      lv_limit := co_abs_max_rows;
    ELSE
      lv_limit := TRUNC(p_max_rows);
    END IF;

    DBMS_OUTPUT.PUT_LINE('State: ' || UPPER(TRIM(p_state)) || ' | Row limit: ' || TO_CHAR(lv_limit));

    DBMS_OUTPUT.PUT_LINE('--- HOME HEALTH AGENCIES (Top by Medicare Payment Non-LUPA) ---');
    FOR rec IN cur_hha(lv_state, lv_limit) LOOP
      IF lv_hha_rows = 0 THEN
        DBMS_OUTPUT.PUT_LINE(RPAD('Provider ID', 12) || RPAD('Agency Name', 42) || LPAD('Payment', 18));
      END IF;

      lv_hha_rows := lv_hha_rows + 1;
      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.provider_id, 12) ||
        RPAD(SUBSTR(rec.name, 1, 40), 42) ||
        LPAD(TO_CHAR(rec.payment_amt, '9999999999990D00'), 18)
      );
    END LOOP;

    IF lv_hha_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No matching home health agencies for state ' || UPPER(TRIM(p_state)) || '.');
    END IF;

    DBMS_OUTPUT.PUT_LINE('--- HOSPICE PROVIDERS (Top by Medicare Payment Amount) ---');
    FOR rec IN cur_hospice(lv_state, lv_limit) LOOP
      IF lv_hospice_rows = 0 THEN
        DBMS_OUTPUT.PUT_LINE(RPAD('Provider ID', 12) || RPAD('Name', 42) || LPAD('Payment', 18));
      END IF;

      lv_hospice_rows := lv_hospice_rows + 1;
      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.provider_id, 12) ||
        RPAD(SUBSTR(rec.name, 1, 40), 42) ||
        LPAD(TO_CHAR(rec.payment_amt, '9999999999990D00'), 18)
      );
    END LOOP;

    IF lv_hospice_rows = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No matching hospice providers for state ' || UPPER(TRIM(p_state)) || '.');
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN VALUE_ERROR THEN
      DBMS_OUTPUT.PUT_LINE('Invalid numeric conversion or parameter value.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_top_payments_by_state;

END cms_provider_rpt;
/

