CREATE OR REPLACE PROCEDURE print_country_debt_snapshot(
  p_country_code IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.country_code%TYPE,
  p_year         IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country_code WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.country_code%TYPE;
  lv_year         WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE;

  lv_short_name   WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.short_name%TYPE;
  lv_region       WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE;
  lv_income_group WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE;

  lv_total_value  NUMBER := 0;
  lv_category     VARCHAR2(10);
  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  -- Normalize inputs (treat blanks as NULL)
  lv_country_code := NULLIF(TRIM(p_country_code), '');
  lv_year         := NULLIF(TRIM(p_year), '');

  IF lv_country_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: country code is required.');
    RETURN;
  END IF;

  IF lv_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Input validation failed: year is required.');
    RETURN;
  END IF;

  -- Fetch country metadata
  SELECT cs.short_name,
         cs.region,
         cs.income_group
    INTO lv_short_name,
         lv_region,
         lv_income_group
    FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
   WHERE cs.country_code = lv_country_code;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_short_name || ' | Region: ' || lv_region || ' | Income group: ' || lv_income_group);

  -- Compute total debt for the year; VALUE is stored as text, so validate before TO_NUMBER
  SELECT SUM(
           CASE
             WHEN REGEXP_LIKE(id.value, '^\s*[-+]?(\d+\.?\d*|\d*\.?\d+)([eE][-+]?\d+)?\s*$')
               THEN TO_NUMBER(TRIM(id.value))
             ELSE 0
           END
         )
    INTO lv_total_value
    FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
   WHERE id.country_code = lv_country_code
     AND id.year = lv_year;

  IF lv_total_value >= 1000000000 THEN
    lv_category := 'HIGH';
  ELSIF lv_total_value >= 100000000 THEN
    lv_category := 'MEDIUM';
  ELSE
    lv_category := 'LOW';
  END IF;

  DBMS_OUTPUT.PUT_LINE('Debt total (' || lv_year || '): ' || TO_CHAR(lv_total_value));
  DBMS_OUTPUT.PUT_LINE('Debt category: ' || lv_category);
  DBMS_OUTPUT.PUT_LINE('Top indicators by value (max ' || co_report_limit || '):');

  -- Print top indicators by numeric value; safe conversion with same validation rule
  FOR rec IN (
    SELECT t.indicator_code,
           t.indicator_name,
           t.value_num
      FROM (
        SELECT id.indicator_code,
               id.indicator_name,
               CASE
                 WHEN REGEXP_LIKE(id.value, '^\s*[-+]?(\d+\.?\d*|\d*\.?\d+)([eE][-+]?\d+)?\s*$')
                   THEN TO_NUMBER(TRIM(id.value))
                 ELSE 0
               END AS value_num
          FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT id
         WHERE id.country_code = lv_country_code
           AND id.year = lv_year
      ) t
     ORDER BY t.value_num DESC, t.indicator_code ASC
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    EXIT WHEN lv_rows_printed > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(' - ' || rec.indicator_code || ' | ' || rec.indicator_name || ' | ' || TO_CHAR(rec.value_num));
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No indicator rows found for that country/year.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END print_country_debt_snapshot;
/

CREATE OR REPLACE PROCEDURE rpt_top_product_revenue(
  p_start_date        IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE,
  p_end_date          IN ADVENTUREWORKS.SALESORDERHEADER.orderdate%TYPE,
  p_productcategoryid IN ADVENTUREWORKS.PRODUCTCATEGORY.productcategoryid%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_category_name ADVENTUREWORKS.PRODUCTCATEGORY.name%TYPE;
  lv_rows_printed  PLS_INTEGER := 0;
  lv_rank          PLS_INTEGER := 0;

  -- Revenue tier thresholds (simple, business-friendly buckets)
  co_high_threshold   CONSTANT NUMBER := 100000;
  co_medium_threshold CONSTANT NUMBER := 25000;
BEGIN
  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the given criteria.');
    RETURN;
  END IF;

  IF p_end_date < p_start_date THEN
    DBMS_OUTPUT.PUT_LINE('Invalid date range: end date is earlier than start date.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Date Range: ' || TO_CHAR(p_start_date, 'YYYY-MM-DD') || ' to ' || TO_CHAR(p_end_date, 'YYYY-MM-DD'));

  IF p_productcategoryid IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Category Filter: ALL');
  ELSE
    SELECT pc.name
      INTO lv_category_name
      FROM ADVENTUREWORKS.PRODUCTCATEGORY pc
     WHERE pc.productcategoryid = p_productcategoryid;

    DBMS_OUTPUT.PUT_LINE('Category Filter: ' || lv_category_name);
  END IF;

  DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('Product', 40) || LPAD('Revenue', 14) || '  ' || 'Tier');

  FOR r IN (
    WITH prod_rev AS (
      SELECT p.productid,
             p.name AS product_name,
             SUM(d.orderqty * d.unitprice * (1 - d.unitpricediscount)) AS revenue
        FROM ADVENTUREWORKS.SALESORDERHEADER h
        INNER JOIN ADVENTUREWORKS.SALESORDERDETAIL d
          ON d.salesorderid = h.salesorderid
        INNER JOIN ADVENTUREWORKS.PRODUCT p
          ON p.productid = d.productid
        LEFT OUTER JOIN ADVENTUREWORKS.PRODUCTSUBCATEGORY ps
          ON ps.productsubcategoryid = p.productsubcategoryid
        LEFT OUTER JOIN ADVENTUREWORKS.PRODUCTCATEGORY pc
          ON pc.productcategoryid = ps.productcategoryid
       WHERE h.orderdate >= p_start_date
         AND h.orderdate < (p_end_date + 1)
         AND (p_productcategoryid IS NULL OR pc.productcategoryid = p_productcategoryid)
       GROUP BY p.productid, p.name
    ), ranked AS (
      SELECT pr.productid,
             pr.product_name,
             pr.revenue,
             ROW_NUMBER() OVER (ORDER BY pr.revenue DESC, pr.productid) AS rn
        FROM prod_rev pr
    )
    SELECT ranked.product_name,
           ranked.revenue,
           CASE
             WHEN ranked.revenue >= co_high_threshold THEN 'HIGH'
             WHEN ranked.revenue >= co_medium_threshold THEN 'MEDIUM'
             ELSE 'LOW'
           END AS tier
      FROM ranked
     WHERE ranked.rn <= co_report_limit
     ORDER BY ranked.rn
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;
    lv_rank := lv_rows_printed;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(lv_rank), 6) ||
      RPAD(SUBSTR(r.product_name, 1, 38), 40) ||
      LPAD(TO_CHAR(r.revenue, 'FM999G999G999G990D00'), 14) ||
      '  ' || r.tier
    );
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the given criteria.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END rpt_top_product_revenue;
/

