CREATE OR REPLACE PROCEDURE report_county_payment_natality (
  p_county_fips IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE_FIPS%TYPE,
  p_report_year IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.YEAR%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability.
  co_duplicate_probe_fips CONSTANT SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE_FIPS%TYPE := 'MULTI'; -- Training probe for duplicate-row exception validation.

  lv_county_name SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE%TYPE;
  lv_rows PLS_INTEGER := 0;
  lv_total_births NUMBER := 0;
  lv_volume_category VARCHAR2(30);

  CURSOR cur_payment (
    cp_county_fips SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT.COUNTY_OF_RESIDENCE_FIPS%TYPE,
    cp_report_year SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT.YEAR%TYPE
  ) IS
    SELECT rpt.source_of_payment,
           rpt.source_of_payment_code,
           rpt.total_births,
           rpt.avg_mother_age
      FROM (
            SELECT p.source_of_payment,
                   p.source_of_payment_code,
                   SUM(TO_NUMBER(TRIM(p.births))) AS total_births,
                   ROUND(AVG(TO_NUMBER(TRIM(p.ave_age_of_mother))), 1) AS avg_mother_age
              FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY_BY_PAYMENT p
             WHERE p.county_of_residence_fips = cp_county_fips
               AND p.year = cp_report_year
               AND REGEXP_LIKE(TRIM(p.births), '^[0-9]+(\.[0-9]+)?$')
               AND REGEXP_LIKE(TRIM(p.ave_age_of_mother), '^[0-9]+(\.[0-9]+)?$')
             GROUP BY p.source_of_payment,
                      p.source_of_payment_code
             ORDER BY SUM(TO_NUMBER(TRIM(p.births))) DESC,
                      p.source_of_payment
           ) rpt
     WHERE ROWNUM <= co_report_limit;

  lr_payment cur_payment%ROWTYPE;
BEGIN
  IF p_county_fips IS NULL OR p_report_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('County FIPS and report year are required.');
    RETURN;
  END IF;

  IF p_county_fips = co_duplicate_probe_fips THEN
    SELECT cn.county_of_residence
      INTO lv_county_name
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
     WHERE ROWNUM <= 2;
  END IF;

  SELECT cn.county_of_residence
    INTO lv_county_name
    FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
   WHERE cn.county_of_residence_fips = p_county_fips
     AND cn.year = p_report_year;

  DBMS_OUTPUT.PUT_LINE('Payment natality report for ' || lv_county_name || ' (' || p_county_fips || ') in ' || TO_CHAR(p_report_year, 'YYYY') || ':');

  OPEN cur_payment(p_county_fips, p_report_year);
  LOOP
    FETCH cur_payment INTO lr_payment;
    EXIT WHEN cur_payment%NOTFOUND;

    lv_rows := lv_rows + 1;
    lv_total_births := lv_total_births + lr_payment.total_births;

    IF lr_payment.total_births >= 1000 THEN
      lv_volume_category := 'HIGH VOLUME';
    ELSE
      lv_volume_category := 'STANDARD VOLUME';
    END IF;

    DBMS_OUTPUT.PUT_LINE('Payment=' || NVL(lr_payment.source_of_payment, 'Unknown') || ', Code=' || NVL(lr_payment.source_of_payment_code, 'Unknown') || ', Births=' || TO_CHAR(lr_payment.total_births) || ', AvgMotherAge=' || TO_CHAR(lr_payment.avg_mother_age) || ', Category=' || lv_volume_category);
  END LOOP;
  CLOSE cur_payment;

  IF lv_rows = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No payment records matched numeric quality checks.');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Displayed rows=' || TO_CHAR(lv_rows) || ', Numeric births total=' || TO_CHAR(lv_total_births));
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    IF cur_payment%ISOPEN THEN
      CLOSE cur_payment;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF cur_payment%ISOPEN THEN
      CLOSE cur_payment;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF cur_payment%ISOPEN THEN
      CLOSE cur_payment;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_county_payment_natality;
/

DECLARE
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_band            VARCHAR2(30);
  lv_scanned         PLS_INTEGER := 0;
  lv_free_or_negative PLS_INTEGER := 0;
  lv_low             PLS_INTEGER := 0;
  lv_standard        PLS_INTEGER := 0;
  lv_premium         PLS_INTEGER := 0;
BEGIN
  FOR r IN (
    SELECT p.productid,
           p.name,
           p.listprice
      FROM ADVENTUREWORKS.PRODUCT p
     WHERE p.listprice IS NOT NULL
     ORDER BY p.productid
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_scanned := lv_scanned + 1;

    IF r.listprice <= 0 THEN
      lv_band := 'FREE_OR_NEGATIVE';
      lv_free_or_negative := lv_free_or_negative + 1;
    ELSIF r.listprice < 100 THEN
      lv_band := 'LOW';
      lv_low := lv_low + 1;
    ELSIF r.listprice < 1000 THEN
      lv_band := 'STANDARD';
      lv_standard := lv_standard + 1;
    ELSE
      lv_band := 'PREMIUM';
      lv_premium := lv_premium + 1;
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'ProductId=' || r.productid || ', Name=' || r.name || ', ListPrice=' || TO_CHAR(r.listprice) || ', Band=' || lv_band
    );
  END LOOP;

  IF lv_scanned = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  ELSE
    DBMS_OUTPUT.PUT_LINE(
      'Scanned=' || lv_scanned || ', FREE_OR_NEGATIVE=' || lv_free_or_negative || ', LOW=' || lv_low || ', STANDARD=' || lv_standard || ', PREMIUM=' || lv_premium
    );
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
