CREATE OR REPLACE PACKAGE natality_reporting IS
  PROCEDURE print_county_snapshot(
    p_year          IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.YEAR%TYPE,
    p_county_filter IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE%TYPE DEFAULT NULL
  );
END natality_reporting;
/
CREATE OR REPLACE PACKAGE BODY natality_reporting IS

  PROCEDURE print_county_snapshot(
    p_year          IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.YEAR%TYPE,
    p_county_filter IN SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY.COUNTY_OF_RESIDENCE%TYPE DEFAULT NULL
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    lv_non_numeric_births_rows NUMBER := 0;
    lv_min_births              NUMBER := NULL;
    lv_max_births              NUMBER := NULL;

    lv_sum_avg_age   NUMBER := 0;
    lv_avg_age_rows  NUMBER := 0;

    lv_rows_printed  PLS_INTEGER := 0;
  BEGIN
    DBMS_OUTPUT.PUT_LINE('County natality snapshot');
    DBMS_OUTPUT.PUT_LINE('Year: ' || TO_CHAR(p_year, 'YYYY'));
    DBMS_OUTPUT.PUT_LINE('County filter: ' || NVL(p_county_filter, ''));

    -- Quality scan: count non-numeric births; compute min/max births and average age across parsable rows.
    FOR q IN (
      SELECT
        cn.births,
        cn.ave_age_of_mother
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
      WHERE cn.year = p_year
        AND (p_county_filter IS NULL OR UPPER(cn.county_of_residence) LIKE '%' || UPPER(p_county_filter) || '%')
    ) LOOP
      -- births is stored as VARCHAR2; parse defensively
      IF REGEXP_LIKE(TRIM(q.births), '^[0-9]+(\.[0-9]+)?$') THEN
        IF lv_min_births IS NULL OR TO_NUMBER(q.births) < lv_min_births THEN
          lv_min_births := TO_NUMBER(q.births);
        END IF;

        IF lv_max_births IS NULL OR TO_NUMBER(q.births) > lv_max_births THEN
          lv_max_births := TO_NUMBER(q.births);
        END IF;

        IF REGEXP_LIKE(TRIM(q.ave_age_of_mother), '^[0-9]+(\.[0-9]+)?$') THEN
          lv_sum_avg_age  := lv_sum_avg_age + TO_NUMBER(q.ave_age_of_mother);
          lv_avg_age_rows := lv_avg_age_rows + 1;
        END IF;
      ELSE
        lv_non_numeric_births_rows := lv_non_numeric_births_rows + 1;
      END IF;
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Top counties by births (up to ' || co_report_limit || ' rows)');
    DBMS_OUTPUT.PUT_LINE(RPAD('County', 35) || ' | ' || LPAD('Births', 12) || ' | ' || LPAD('Avg Mother Age', 14));
    DBMS_OUTPUT.PUT_LINE(RPAD('-', 35, '-') || '-+-' || RPAD('-', 12, '-') || '-+-' || RPAD('-', 14, '-'));

    -- Report: show up to co_report_limit counties with highest numeric births
    FOR rec IN (
      SELECT
        cn.county_of_residence,
        TO_NUMBER(cn.births) AS births_num,
        CASE
          WHEN REGEXP_LIKE(TRIM(cn.ave_age_of_mother), '^[0-9]+(\.[0-9]+)?$') THEN TO_NUMBER(cn.ave_age_of_mother)
          ELSE NULL
        END AS avg_mother_age_num
      FROM SDOH_CDC_WONDER_NATALITY.COUNTY_NATALITY cn
      WHERE cn.year = p_year
        AND (p_county_filter IS NULL OR UPPER(cn.county_of_residence) LIKE '%' || UPPER(p_county_filter) || '%')
        AND REGEXP_LIKE(TRIM(cn.births), '^[0-9]+(\.[0-9]+)?$')
      ORDER BY TO_NUMBER(cn.births) DESC, cn.county_of_residence ASC
    ) LOOP
      lv_rows_printed := lv_rows_printed + 1;
      EXIT WHEN lv_rows_printed > co_report_limit;

      DBMS_OUTPUT.PUT_LINE(
        RPAD(rec.county_of_residence, 35) || ' | ' ||
        LPAD(TO_CHAR(rec.births_num), 12) || ' | ' ||
        LPAD(
          CASE
            WHEN rec.avg_mother_age_num IS NULL THEN 'n/a'
            ELSE TO_CHAR(ROUND(rec.avg_mother_age_num, 1))
          END,
          14
        )
      );
    END LOOP;

    IF lv_rows_printed = 0 THEN
      -- Standardize empty-result behavior to NO_DATA_FOUND for the caller/test cases
      RAISE NO_DATA_FOUND;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Rows with non-numeric births skipped: ' || TO_CHAR(lv_non_numeric_births_rows));
    DBMS_OUTPUT.PUT_LINE('Min births (parsable rows): ' || TO_CHAR(lv_min_births));
    DBMS_OUTPUT.PUT_LINE('Max births (parsable rows): ' || TO_CHAR(lv_max_births));
    DBMS_OUTPUT.PUT_LINE(
      'Average mother age (parsable rows): ' ||
      CASE
        WHEN lv_avg_age_rows = 0 THEN 'n/a'
        ELSE TO_CHAR(ROUND(lv_sum_avg_age / lv_avg_age_rows, 1))
      END
    );

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_county_snapshot;

END natality_reporting;
/

