DECLARE
  -- Limit output for report readability
  co_report_limit CONSTANT PLS_INTEGER := 15;

  -- Inputs for the report
  lv_region         WORLD_BANK_WDI.COUNTRY_SUMMARY.region%TYPE := 'South Asia';
  lv_indicator_code WORLD_BANK_WDI.INDICATORS_DATA.indicator_code%TYPE := 'SP.POP.TOTL';

  -- Per-country derived values
  lv_row_count        PLS_INTEGER;
  lv_latest_year_txt  WORLD_BANK_WDI.INDICATORS_DATA.year%TYPE;

  -- Totals
  lv_countries_processed         PLS_INTEGER := 0;
  lv_countries_missing_indicator PLS_INTEGER := 0;

  CURSOR cur_countries IS
    SELECT cs.short_name,
           cs.country_code
      FROM WORLD_BANK_WDI.COUNTRY_SUMMARY cs
     WHERE cs.region = lv_region
     ORDER BY cs.short_name
     FETCH FIRST co_report_limit ROWS ONLY;

  r_countries cur_countries%ROWTYPE;
BEGIN
  IF lv_region IS NULL OR lv_indicator_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region);
  DBMS_OUTPUT.PUT_LINE('Indicator: ' || lv_indicator_code);
  DBMS_OUTPUT.PUT_LINE('Report limit: ' || co_report_limit);

  OPEN cur_countries;
  LOOP
    FETCH cur_countries INTO r_countries;
    EXIT WHEN cur_countries%NOTFOUND;

    lv_countries_processed := lv_countries_processed + 1;

    -- Count and latest year for this country + indicator
    SELECT COUNT(*),
           MAX(id.year)
      INTO lv_row_count,
           lv_latest_year_txt
      FROM WORLD_BANK_WDI.INDICATORS_DATA id
     WHERE id.country_code = r_countries.country_code
       AND id.indicator_code = lv_indicator_code;

    IF lv_row_count = 0 THEN
      lv_countries_missing_indicator := lv_countries_missing_indicator + 1;
      lv_latest_year_txt := 'N/A';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Country: ' || r_countries.short_name || ' (' || r_countries.country_code || '), rows=' || lv_row_count || ', latest_year=' || lv_latest_year_txt
    );
  END LOOP;

  IF cur_countries%ISOPEN THEN
    CLOSE cur_countries;
  END IF;

  DBMS_OUTPUT.PUT_LINE(
    'Totals: countries_processed=' || lv_countries_processed || ', countries_missing_indicator=' || lv_countries_missing_indicator
  );

EXCEPTION
  WHEN VALUE_ERROR THEN
    IF cur_countries%ISOPEN THEN
      CLOSE cur_countries;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Invalid input value.');
  WHEN NO_DATA_FOUND THEN
    IF cur_countries%ISOPEN THEN
      CLOSE cur_countries;
    END IF;
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    IF cur_countries%ISOPEN THEN
      CLOSE cur_countries;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    IF cur_countries%ISOPEN THEN
      CLOSE cur_countries;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

