  WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

question:
Build a reusable stored procedure for a debt analytics support team that produces a compact 'data quality + trend' report for a single country.

The report should:
 Accept a country code and an optional indicator code filter.
 Validate that the country code exists; if the indicator code is provided, validate it exists for that country.
 Print the country name, region, and income group.
 Print the most recent year available (for the chosen scope) and how many distinct indicators exist for that country.
 Print up to 15 of the latest observations (year + indicator code + numeric value) for that country, optionally filtered by indicator.

Use control flow so that optional parameters change the behavior, and make sure all runtime problems are caught and reported via DBMS_OUTPUT messages.

Requirements:
Procedure Name: debt_country_trend_report
Parameters:
p_country_code IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.country_code%TYPE
p_indicator_code IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_code%TYPE DEFAULT NULL
Output:
DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name);
DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region || ' | Income group: ' || lv_income_group);
DBMS_OUTPUT.PUT_LINE('Scope: ALL indicators');
DBMS_OUTPUT.PUT_LINE('Scope: Indicator ' || p_indicator_code);
DBMS_OUTPUT.PUT_LINE('Most recent year: ' || lv_latest_year);
DBMS_OUTPUT.PUT_LINE('Distinct indicators for country: ' || lv_distinct_indicators);
DBMS_OUTPUT.PUT_LINE(RPAD('-', 80, '-'));
DBMS_OUTPUT.PUT_LINE('Year | Indicator Code | Value');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 80, '-'));
DBMS_OUTPUT.PUT_LINE(rec.year || ' | ' || rec.indicator_code || ' | ' || rec.value);
DBMS_OUTPUT.PUT_LINE('No observations found for the requested scope.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE debt_country_trend_report(
  p_country_code   IN WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.country_code%TYPE,
  p_indicator_code IN WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.indicator_code%TYPE DEFAULT NULL
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_country_name WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.short_name%TYPE;
  lv_region       WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.region%TYPE;
  lv_income_group WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY.income_group%TYPE;

  lv_latest_year          WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT.year%TYPE;
  lv_distinct_indicators  NUMBER;
  lv_observation_count    PLS_INTEGER := 0;
  lv_exists               PLS_INTEGER;
BEGIN
  -- Validate input country exists and retrieve country attributes
  SELECT cs.short_name, cs.region, cs.income_group
    INTO lv_country_name, lv_region, lv_income_group
    FROM WORLD_BANK_INTL_DEBT.COUNTRY_SUMMARY cs
   WHERE cs.country_code = p_country_code;

  DBMS_OUTPUT.PUT_LINE('Country: ' || lv_country_name);
  DBMS_OUTPUT.PUT_LINE('Region: ' || lv_region || ' | Income group: ' || lv_income_group);

  -- Optional indicator filter changes scope and validation
  IF p_indicator_code IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Scope: ALL indicators');

    SELECT MAX(d.year), COUNT(DISTINCT d.indicator_code)
      INTO lv_latest_year, lv_distinct_indicators
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
     WHERE d.country_code = p_country_code;
  ELSE
    -- Validate indicator exists for the given country
    SELECT COUNT(*)
      INTO lv_exists
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
     WHERE d.country_code = p_country_code
       AND d.indicator_code = p_indicator_code;

    IF lv_exists = 0 THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
      RETURN;
    END IF;

    DBMS_OUTPUT.PUT_LINE('Scope: Indicator ' || p_indicator_code);

    SELECT MAX(d.year), COUNT(DISTINCT d.indicator_code)
      INTO lv_latest_year, lv_distinct_indicators
      FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
     WHERE d.country_code = p_country_code
       AND d.indicator_code = p_indicator_code;
  END IF;

  IF lv_latest_year IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('No observations found for the requested scope.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Most recent year: ' || lv_latest_year);
  DBMS_OUTPUT.PUT_LINE('Distinct indicators for country: ' || lv_distinct_indicators);

  DBMS_OUTPUT.PUT_LINE(RPAD('-', 80, '-'));
  DBMS_OUTPUT.PUT_LINE('Year | Indicator Code | Value');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 80, '-'));

  -- Print up to 15 latest observations within the chosen scope
  FOR rec IN (
    SELECT x.year, x.indicator_code, x.value
      FROM (
        SELECT d.year, d.indicator_code, TO_NUMBER(d.value) AS value
          FROM WORLD_BANK_INTL_DEBT.INTERNATIONAL_DEBT d
         WHERE d.country_code = p_country_code
           AND (p_indicator_code IS NULL OR d.indicator_code = p_indicator_code)
           AND d.value IS NOT NULL
         ORDER BY d.year DESC, d.indicator_code
      ) x
     WHERE ROWNUM <= co_report_limit
  ) LOOP
    lv_observation_count := lv_observation_count + 1;
    DBMS_OUTPUT.PUT_LINE(rec.year || ' | ' || rec.indicator_code || ' | ' || rec.value);
  END LOOP;

  IF lv_observation_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No observations found for the requested scope.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END debt_country_trend_report;
/

question:
Your operations team needs a quick state-level snapshot of hospice providers to spot unusually high spend patterns. Build a reusable procedure that accepts a state code and prints up to 15 hospice providers in that state with the highest Medicare payment amounts, including provider id, name, city, and the payment amount. The procedure must validate the input state, handle missing or bad data gracefully, and print a clear message when the state has no providers.

Requirements:
Procedure Name: report_top_hospice_payments_by_state
Parameters:
p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Top hospice providers by Medicare payment in state: ' || p_state);
DBMS_OUTPUT.PUT_LINE(RPAD('PROVIDER_ID', 12) || RPAD('NAME', 45) || RPAD('CITY', 25) || 'TOTAL_MEDICARE_PAYMENT_AMOUNT');
DBMS_OUTPUT.PUT_LINE(RPAD('-', 12, '-') || RPAD('-', 45, '-') || RPAD('-', 25, '-') || RPAD('-', 30, '-'));
DBMS_OUTPUT.PUT_LINE(RPAD(rec.provider_id, 12) || RPAD(SUBSTR(rec.name, 1, 44), 45) || RPAD(SUBSTR(rec.city, 1, 24), 25) || TO_CHAR(rec.payment_amt));
DBMS_OUTPUT.PUT_LINE('No providers found for state: ' || p_state);
DBMS_OUTPUT.PUT_LINE('State is required.');
DBMS_OUTPUT.PUT_LINE('State must be a 2-letter code.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No providers found for state: ' || p_state
WHEN VALUE_ERROR THEN: 'State must be a 2-letter code.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_top_hospice_payments_by_state(
  p_state IN CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_state CMS_MEDICARE.HOSPICE_PROVIDERS.state%TYPE;
  lv_rows  PLS_INTEGER := 0;
BEGIN
  IF p_state IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('State is required.');
    RETURN;
  END IF;

  lv_state := UPPER(TRIM(p_state));

  IF LENGTH(lv_state) <> 2 THEN
    RAISE VALUE_ERROR;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Top hospice providers by Medicare payment in state: ' || lv_state);
  DBMS_OUTPUT.PUT_LINE(RPAD('PROVIDER_ID', 12) || RPAD('NAME', 45) || RPAD('CITY', 25) || 'TOTAL_MEDICARE_PAYMENT_AMOUNT');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 12, '-') || RPAD('-', 45, '-') || RPAD('-', 25, '-') || RPAD('-', 30, '-'));

  FOR rec IN (
    SELECT hp.provider_id,
           hp.name,
           hp.city,
           TO_NUMBER(hp.total_medicare_payment_amount) AS payment_amt
      FROM CMS_MEDICARE.HOSPICE_PROVIDERS hp
     WHERE hp.state = lv_state
       AND hp.total_medicare_payment_amount IS NOT NULL
     ORDER BY TO_NUMBER(hp.total_medicare_payment_amount) DESC
  ) LOOP
    lv_rows := lv_rows + 1;
    EXIT WHEN lv_rows > co_report_limit;

    DBMS_OUTPUT.PUT_LINE(
      RPAD(rec.provider_id, 12) ||
      RPAD(SUBSTR(rec.name, 1, 44), 45) ||
      RPAD(SUBSTR(rec.city, 1, 24), 25) ||
      TO_CHAR(rec.payment_amt)
    );
  END LOOP;

  IF lv_rows = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No providers found for state: ' || lv_state);
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('State must be a 2-letter code.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_hospice_payments_by_state;
/

CREATE OR REPLACE PROCEDURE report_channel_performance(
  p_year IN DELIVERY_CENTER.ORDERS.order_created_year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year_min DELIVERY_CENTER.ORDERS.order_created_year%TYPE;
  lv_year_max DELIVERY_CENTER.ORDERS.order_created_year%TYPE;

  lv_fee_tier VARCHAR2(10);
BEGIN
  -- Validate the requested year against actual data range.
  SELECT MIN(o.order_created_year), MAX(o.order_created_year)
    INTO lv_year_min, lv_year_max
    FROM DELIVERY_CENTER.ORDERS o;

  IF p_year IS NULL OR p_year < lv_year_min OR p_year > lv_year_max THEN
    -- Force a handled exception path for invalid input.
    RAISE VALUE_ERROR;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Channel performance report for year=' || p_year);

  -- Ranked, row-limited report by total amount.
  FOR rec IN (
    WITH channel_totals AS (
      SELECT c.channel_name AS channel_name,
             COUNT(*) AS order_cnt,
             SUM(o.order_amount) AS total_amount,
             AVG(o.order_delivery_fee) AS avg_fee
        FROM DELIVERY_CENTER.ORDERS o
        INNER JOIN DELIVERY_CENTER.CHANNELS c
          ON c.channel_id = o.channel_id
       WHERE o.order_created_year = p_year
       GROUP BY c.channel_name
    ),
    ranked AS (
      SELECT ct.channel_name,
             ct.order_cnt,
             ct.total_amount,
             ct.avg_fee,
             ROW_NUMBER() OVER (ORDER BY ct.total_amount DESC) AS rnk
        FROM channel_totals ct
    )
    SELECT r.rnk,
           r.channel_name,
           r.order_cnt,
           r.total_amount,
           r.avg_fee
      FROM ranked r
     WHERE r.rnk <= co_report_limit
     ORDER BY r.rnk
  ) LOOP
    IF rec.avg_fee IS NULL OR rec.avg_fee < 5 THEN
      lv_fee_tier := 'LOW';
    ELSIF rec.avg_fee < 15 THEN
      lv_fee_tier := 'MEDIUM';
    ELSE
      lv_fee_tier := 'HIGH';
    END IF;

    DBMS_OUTPUT.PUT_LINE(
      'Rank=' || rec.rnk ||
      ', Channel=' || rec.channel_name ||
      ', Orders=' || rec.order_cnt ||
      ', TotalAmount=' || TO_CHAR(rec.total_amount) ||
      ', AvgFee=' || TO_CHAR(rec.avg_fee) ||
      ', FeeTier=' || lv_fee_tier
    );
  END LOOP;

  -- If the year was valid but returned no grouped rows, signal as NO_DATA_FOUND.
  IF SQL%ROWCOUNT = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_channel_performance;
/

CREATE OR REPLACE PROCEDURE report_top_products(
  p_calendar_year IN COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
  p_channel_id    IN COMPLEX_ORACLE.SALES.channel_id%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_year         COMPLEX_ORACLE.TIMES.calendar_year%TYPE;
  lv_channel      COMPLEX_ORACLE.SALES.channel_id%TYPE;
  lv_channel_desc COMPLEX_ORACLE.CHANNELS.channel_desc%TYPE;

  lv_printed      PLS_INTEGER := 0;

  CURSOR cur_ranked_products(
    c_year    COMPLEX_ORACLE.TIMES.calendar_year%TYPE,
    c_channel COMPLEX_ORACLE.SALES.channel_id%TYPE
  ) IS
    WITH prod_rollup AS (
      SELECT p.prod_name AS prod_name,
             SUM(s.amount_sold) AS revenue,
             SUM(s.quantity_sold) AS qty_sold
        FROM COMPLEX_ORACLE.SALES s
        INNER JOIN COMPLEX_ORACLE.TIMES t
          ON t.time_id = s.time_id
        INNER JOIN COMPLEX_ORACLE.PRODUCTS p
          ON p.prod_id = s.prod_id
       WHERE t.calendar_year = c_year
         AND s.channel_id = c_channel
       GROUP BY p.prod_name
    ), ranked AS (
      SELECT pr.prod_name,
             pr.revenue,
             pr.qty_sold,
             ROW_NUMBER() OVER (ORDER BY pr.revenue DESC, pr.prod_name ASC) AS rn
        FROM prod_rollup pr
    )
    SELECT r.prod_name,
           r.revenue,
           r.qty_sold,
           r.rn
      FROM ranked r
     WHERE r.rn <= co_report_limit
     ORDER BY r.rn;
BEGIN
  -- Default the year to the most recent year in TIMES if null.
  IF p_calendar_year IS NULL THEN
    SELECT MAX(t.calendar_year)
      INTO lv_year
      FROM COMPLEX_ORACLE.TIMES t;
  ELSE
    lv_year := p_calendar_year;
  END IF;

  -- Default the channel to the most frequently used channel in SALES if null.
  IF p_channel_id IS NULL THEN
    SELECT x.channel_id
      INTO lv_channel
      FROM (
            SELECT s.channel_id, COUNT(*) AS cnt
              FROM COMPLEX_ORACLE.SALES s
             GROUP BY s.channel_id
             ORDER BY COUNT(*) DESC, s.channel_id
           ) x
     WHERE ROWNUM = 1;
  ELSE
    lv_channel := p_channel_id;
  END IF;

  -- Validate channel exists and fetch description.
  SELECT c.channel_desc
    INTO lv_channel_desc
    FROM COMPLEX_ORACLE.CHANNELS c
   WHERE c.channel_id = lv_channel;

  DBMS_OUTPUT.PUT_LINE('Top products report (year=' || lv_year || ', channel_id=' || lv_channel || ', channel_desc=' || lv_channel_desc || ')');
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));
  DBMS_OUTPUT.PUT_LINE(RPAD('Rank', 6) || RPAD('Product', 45) || LPAD('Revenue', 18) || LPAD('Qty', 10));
  DBMS_OUTPUT.PUT_LINE(RPAD('-', 90, '-'));

  FOR rec IN cur_ranked_products(lv_year, lv_channel) LOOP
    lv_printed := lv_printed + 1;
    DBMS_OUTPUT.PUT_LINE(
      RPAD(TO_CHAR(lv_printed), 6) ||
      RPAD(rec.prod_name, 45) ||
      LPAD(TO_CHAR(rec.revenue, 'FM9999999990D00'), 18) ||
      LPAD(TO_CHAR(rec.qty_sold), 10)
    );
  END LOOP;

  IF lv_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the requested filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_top_products;
/

