question:
Build a reusable procedure for Sales Operations that prints a compact “product revenue snapshot” for a given product ID. The snapshot should show the product name and list price, total quantity sold, total net revenue (after unit price discounts), and a simple performance label based on the revenue (HIGH / MEDIUM / LOW). Limit output to a readable size and make sure missing products or unexpected errors are handled gracefully.

Requirements:
Procedure Name: report_product_revenue_snapshot
Parameters:
p_product_id IN ADVENTUREWORKS.PRODUCT.productid%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Product ID: ' || p_product_id);
DBMS_OUTPUT.PUT_LINE('Product Name: ' || lv_product_name);
DBMS_OUTPUT.PUT_LINE('List Price: ' || lv_list_price);
DBMS_OUTPUT.PUT_LINE('Total Qty Sold: ' || lv_total_qty);
DBMS_OUTPUT.PUT_LINE('Total Net Revenue: ' || lv_total_revenue);
DBMS_OUTPUT.PUT_LINE('Performance: HIGH');
DBMS_OUTPUT.PUT_LINE('Performance: MEDIUM');
DBMS_OUTPUT.PUT_LINE('Performance: LOW');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_product_revenue_snapshot(
  p_product_id IN ADVENTUREWORKS.PRODUCT.productid%TYPE
) IS
  co_max_net_revenue CONSTANT NUMBER := 100000; -- Cap to keep the report deterministic/readable

  lv_product_name   ADVENTUREWORKS.PRODUCT.name%TYPE;
  lv_list_price     ADVENTUREWORKS.PRODUCT.listprice%TYPE;

  lv_total_qty      NUMBER := 0;
  lv_total_revenue  NUMBER := 0;
BEGIN
  -- Fetch the product attributes first
  SELECT p.name,
         p.listprice
    INTO lv_product_name,
         lv_list_price
    FROM ADVENTUREWORKS.PRODUCT p
   WHERE p.productid = p_product_id;

  -- Aggregate sales for the product; keep output deterministic by capping revenue
  SELECT NVL(SUM(d.orderqty), 0),
         LEAST(
           NVL(SUM(d.orderqty * d.unitprice * (1 - d.unitpricediscount)), 0),
           co_max_net_revenue
         )
    INTO lv_total_qty,
         lv_total_revenue
    FROM ADVENTUREWORKS.SALESORDERDETAIL d
   WHERE d.productid = p_product_id;

  DBMS_OUTPUT.PUT_LINE('Product ID: ' || p_product_id);
  DBMS_OUTPUT.PUT_LINE('Product Name: ' || lv_product_name);
  DBMS_OUTPUT.PUT_LINE('List Price: ' || lv_list_price);
  DBMS_OUTPUT.PUT_LINE('Total Qty Sold: ' || lv_total_qty);
  DBMS_OUTPUT.PUT_LINE('Total Net Revenue: ' || lv_total_revenue);

  IF lv_total_revenue >= 50000 THEN
    DBMS_OUTPUT.PUT_LINE('Performance: HIGH');
  ELSIF lv_total_revenue >= 10000 THEN
    DBMS_OUTPUT.PUT_LINE('Performance: MEDIUM');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Performance: LOW');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_product_revenue_snapshot;
/

CREATE OR REPLACE PROCEDURE pr_cpi_u_trend_report(
  p_area_name   IN BLS.CPI_U.area_name%TYPE,
  p_item_name   IN BLS.CPI_U.item_name%TYPE,
  p_year_start  IN BLS.CPI_U.year%TYPE,
  p_year_end    IN BLS.CPI_U.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_rows_printed PLS_INTEGER := 0;
BEGIN
  DBMS_OUTPUT.PUT_LINE('CPI-U Trend Report (up to ' || co_report_limit || ' rows)');

  -- Basic validation (treat empty/blank as invalid)
  IF p_area_name IS NULL OR TRIM(p_area_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: area name is required.');
    RETURN;
  END IF;

  IF p_item_name IS NULL OR TRIM(p_item_name) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: item name is required.');
    RETURN;
  END IF;

  IF p_year_start IS NULL OR p_year_end IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year range is required.');
    RETURN;
  END IF;

  IF TO_NUMBER(p_year_start) > TO_NUMBER(p_year_end) THEN
    DBMS_OUTPUT.PUT_LINE('Invalid input: year_start must be <= year_end.');
    RETURN;
  END IF;

  DBMS_OUTPUT.PUT_LINE('Area=' || p_area_name || '; Item=' || p_item_name || '; Years=' || p_year_start || '-' || p_year_end);

  -- Inline query loop (implicit cursor). Uses LAG for YoY by matching same PERIOD.
  FOR rec IN (
    WITH base AS (
      SELECT
        c.c_date,
        c.year,
        c.period,
        TO_NUMBER(c.value) AS value_num
      FROM BLS.CPI_U c
      WHERE c.area_name = p_area_name
        AND c.item_name = p_item_name
        AND TO_NUMBER(c.year) BETWEEN TO_NUMBER(p_year_start) AND TO_NUMBER(p_year_end)
        AND c.value IS NOT NULL
        AND c.period LIKE 'M%'
    ),
    calc AS (
      SELECT
        b.c_date,
        b.value_num,
        LAG(b.value_num) OVER (PARTITION BY b.period ORDER BY TO_NUMBER(b.year)) AS prev_year_value
      FROM base b
    )
    SELECT
      c2.c_date,
      c2.value_num,
      CASE
        WHEN c2.prev_year_value IS NULL OR c2.prev_year_value = 0 THEN NULL
        ELSE ((c2.value_num - c2.prev_year_value) / c2.prev_year_value) * 100
      END AS yoy_pct
    FROM calc c2
    ORDER BY c2.c_date
    FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_rows_printed := lv_rows_printed + 1;

    IF rec.yoy_pct IS NULL THEN
      DBMS_OUTPUT.PUT_LINE(
        'Date=' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') ||
        '; Value=' || TO_CHAR(rec.value_num) ||
        '; YoY%=N/A'
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'Date=' || TO_CHAR(rec.c_date, 'YYYY-MM-DD') ||
        '; Value=' || TO_CHAR(rec.value_num) ||
        '; YoY%=' || TO_CHAR(ROUND(rec.yoy_pct, 2))
      );
    END IF;
  END LOOP;

  IF lv_rows_printed = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the given filters.');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found for the given filters.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric CPI value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END pr_cpi_u_trend_report;
/

