          ORDER BY mi.importance DESC, mi.step ASC, mi.model ASC
        ) AS rn
      FROM STACKING.MODEL_IMPORTANCE mi
      INNER JOIN STACKING.MODEL_SCORE ms
        ON ms.name = mi.name
       AND ms.version = mi.version
       AND ms.step = mi.step
       AND ms.model = mi.model
      WHERE mi.name = p_solution_name
        AND mi.version = p_version
    )
    SELECT
      r.step,
      r.model,
      r.importance,
      r.train_score,
      r.test_score
    FROM ranked r
    WHERE r.rn <= co_report_limit
    ORDER BY r.rn;

  lv_step       STACKING.MODEL_IMPORTANCE.step%TYPE;
  lv_model      STACKING.MODEL_IMPORTANCE.model%TYPE;
  lv_importance STACKING.MODEL_IMPORTANCE.importance%TYPE;
