question:
Operations wants a reusable reporting routine to quickly review whether a specific departure airport is overbooked on upcoming scheduled flights. Build a package procedure that, for a given departure airport code, finds up to 15 upcoming flights (based on scheduled departure), and for each flight prints: flight id, flight number, scheduled departure, aircraft code, capacity (number of seats for that aircraft), passenger count (number of boarding passes issued), and an overbook flag (Y if passenger count > capacity else N). Use an explicit cursor to iterate through the flights, and inside the loop use control flow to derive the overbook flag and print the row. If the airport code is NULL, handle it gracefully without raising an error. Make sure the procedure never raises an unhandled runtime error and prints friendly messages for no-data and other issues.

Requirements:
Procedure Name: pkg_overbook_report.print_airport_overbook_report
Parameters:
p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE
Output:
DBMS_OUTPUT.PUT_LINE('Overbook report for departure airport: ' || p_departure_airport);
DBMS_OUTPUT.PUT_LINE('Input departure airport is NULL.');
DBMS_OUTPUT.PUT_LINE('FLIGHT_ID=' || rec.flight_id || ' | FLIGHT_NO=' || rec.flight_no || ' | SCHED_DEP=' || TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI') || ' | AIRCRAFT=' || rec.aircraft_code || ' | CAPACITY=' || lv_capacity || ' | PAX=' || lv_pax || ' | OVERBOOKED=' || lv_overbook_flag);
DBMS_OUTPUT.PUT_LINE('No data found.');
DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
DBMS_OUTPUT.PUT_LINE('Unexpected error.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PACKAGE pkg_overbook_report IS
  PROCEDURE print_airport_overbook_report(
    p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE
  );
END pkg_overbook_report;
/

CREATE OR REPLACE PACKAGE BODY pkg_overbook_report IS
  PROCEDURE print_airport_overbook_report(
    p_departure_airport IN AIRLINES.FLIGHTS.departure_airport%TYPE
  ) IS
    co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

    CURSOR c_flights IS
      SELECT f.flight_id,
             f.flight_no,
             f.scheduled_departure,
             f.aircraft_code
        FROM AIRLINES.FLIGHTS f
       WHERE f.departure_airport = p_departure_airport
         AND f.status = 'Scheduled'
       ORDER BY f.scheduled_departure
       FETCH FIRST co_report_limit ROWS ONLY;

    lv_capacity      NUMBER;
    lv_pax           NUMBER;
    lv_overbook_flag VARCHAR2(1);
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Overbook report for departure airport: ' || p_departure_airport);

    IF p_departure_airport IS NULL THEN
      DBMS_OUTPUT.PUT_LINE('Input departure airport is NULL.');
      RETURN;
    END IF;

    FOR rec IN c_flights LOOP
      -- Capacity: number of seats on the assigned aircraft.
      SELECT COUNT(*)
        INTO lv_capacity
        FROM AIRLINES.SEATS s
       WHERE s.aircraft_code = rec.aircraft_code;

      -- Pax: number of boarding passes already issued for this flight.
      SELECT COUNT(DISTINCT bp.ticket_no)
        INTO lv_pax
        FROM AIRLINES.BOARDING_PASSES bp
       WHERE bp.flight_id = rec.flight_id;

      IF lv_pax > lv_capacity THEN
        lv_overbook_flag := 'Y';
      ELSE
        lv_overbook_flag := 'N';
      END IF;

      DBMS_OUTPUT.PUT_LINE(
        'FLIGHT_ID=' || rec.flight_id ||
        ' | FLIGHT_NO=' || rec.flight_no ||
        ' | SCHED_DEP=' || TO_CHAR(rec.scheduled_departure, 'YYYY-MM-DD HH24:MI') ||
        ' | AIRCRAFT=' || rec.aircraft_code ||
        ' | CAPACITY=' || lv_capacity ||
        ' | PAX=' || lv_pax ||
        ' | OVERBOOKED=' || lv_overbook_flag
      );
    END LOOP;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No data found.');
    WHEN TOO_MANY_ROWS THEN
      DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Unexpected error.');
  END print_airport_overbook_report;
END pkg_overbook_report;
/

