reference_answer:
CREATE OR REPLACE PROCEDURE report_customer_recent_invoices(
  p_email IN CHINOOK.CUSTOMERS.email%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_customer_id CHINOOK.CUSTOMERS.customerid%TYPE;
  lv_first_name  CHINOOK.CUSTOMERS.firstname%TYPE;
  lv_last_name   CHINOOK.CUSTOMERS.lastname%TYPE;

  lv_invoice_count PLS_INTEGER := 0;
  lv_total_sum     CHINOOK.INVOICES.total%TYPE := 0;
BEGIN
  -- Basic input validation
  IF p_email IS NULL OR TRIM(p_email) IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('Email is required.');
    RETURN;
  END IF;

  -- Find the customer by email (expects single match)
  SELECT c.customerid, c.firstname, c.lastname
    INTO lv_customer_id, lv_first_name, lv_last_name
    FROM CHINOOK.CUSTOMERS c
   WHERE c.email = p_email;

  DBMS_OUTPUT.PUT_LINE('Customer: ' || lv_first_name || ' ' || lv_last_name || ' (CustomerId=' || lv_customer_id || ')');

  -- Print up to N most recent invoices
  FOR rec IN (
    SELECT i.invoiceid   AS invoice_id,
           i.invoicedate AS invoice_date,
           i.total       AS total
      FROM CHINOOK.INVOICES i
     WHERE i.customerid = lv_customer_id
     ORDER BY i.invoicedate DESC, i.invoiceid DESC
     FETCH FIRST co_report_limit ROWS ONLY
  ) LOOP
    lv_invoice_count := lv_invoice_count + 1;
    lv_total_sum := lv_total_sum + rec.total;

    DBMS_OUTPUT.PUT_LINE(
      'InvoiceId=' || rec.invoice_id ||
      ', InvoiceDate=' || TO_CHAR(rec.invoice_date, 'YYYY-MM-DD') ||
      ', Total=' || rec.total
    );
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Summary: invoices_listed=' || lv_invoice_count || ', total_sum=' || lv_total_sum);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No customer found for the provided email.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple customers found for the provided email.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_customer_recent_invoices;
/

