DBMS_OUTPUT.PUT_LINE('Year 2: ' || p_year_2 || ' TFR=' || TO_CHAR(lv_tfr_2));
DBMS_OUTPUT.PUT_LINE('Change (Year2-Year1): ' || TO_CHAR(lv_change));
