WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN VALUE_ERROR THEN: 'Invalid numeric value encountered.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
CREATE OR REPLACE PROCEDURE report_country_tfr_change(
  p_country_name IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.country_name%TYPE,
  p_year_1       IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE,
  p_year_2       IN CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.year%TYPE
) IS
  co_report_limit CONSTANT PLS_INTEGER := 15; -- Keep any supporting lookups/reporting bounded

  lv_tfr_1_txt CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;
  lv_tfr_2_txt CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES.total_fertility_rate%TYPE;

  lv_tfr_1   NUMBER;
  lv_tfr_2   NUMBER;
  lv_change  NUMBER;
BEGIN
  -- Retrieve the two year values (single-row expectations per country/year).
  SELECT a.total_fertility_rate
    INTO lv_tfr_1_txt
    FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
   WHERE a.country_name = p_country_name
     AND a.year = p_year_1
     AND ROWNUM <= co_report_limit;

  SELECT a.total_fertility_rate
    INTO lv_tfr_2_txt
    FROM CENSUS_BUREAU_INTERNATIONAL.AGE_SPECIFIC_FERTILITY_RATES a
   WHERE a.country_name = p_country_name
     AND a.year = p_year_2
     AND ROWNUM <= co_report_limit;

  -- Normalize and convert (source columns are VARCHAR2).
  lv_tfr_1 := TO_NUMBER(TRIM(lv_tfr_1_txt));
  lv_tfr_2 := TO_NUMBER(TRIM(lv_tfr_2_txt));

  lv_change := lv_tfr_2 - lv_tfr_1;

  DBMS_OUTPUT.PUT_LINE('Country: ' || p_country_name);
  DBMS_OUTPUT.PUT_LINE('Year 1: ' || p_year_1 || ' TFR=' || TO_CHAR(lv_tfr_1));
  DBMS_OUTPUT.PUT_LINE('Year 2: ' || p_year_2 || ' TFR=' || TO_CHAR(lv_tfr_2));
  DBMS_OUTPUT.PUT_LINE('Change (Year2-Year1): ' || TO_CHAR(lv_change));

  -- Trend classification
  IF lv_change > 0 THEN
    DBMS_OUTPUT.PUT_LINE('Trend: Increase');
  ELSIF lv_change < 0 THEN
    DBMS_OUTPUT.PUT_LINE('Trend: Decrease');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Trend: No change');
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE('Invalid numeric value encountered.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END report_country_tfr_change;
/

