question:
Create a small HR analytics script that prints a concise DEI representation report for a given workforce and report year.

The script should:
 Validate that the input year is a 4-digit number.
 Look up the representation row in GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION for the provided workforce + year.
 Print up to 15 lines that show the gender and race percentages from that row in a readable format.
 Include control flow so that if the workforce is not provided, it defaults to the most common workforce value in the table.
 Catch and report common issues (no data, multiple rows, and unexpected errors) using DBMS_OUTPUT.

Requirements:
Procedure Name: Anonymous Block
Parameters: None
Output:
DBMS_OUTPUT.PUT_LINE('Resolved Workforce: ' || lv_workforce);
DBMS_OUTPUT.PUT_LINE('Report Year: ' || lv_report_year);
DBMS_OUTPUT.PUT_LINE('Gender (US): ' || rec.gender_us);
DBMS_OUTPUT.PUT_LINE('Race Asian: ' || rec.race_asian);
DBMS_OUTPUT.PUT_LINE('Race Black: ' || rec.race_black);
DBMS_OUTPUT.PUT_LINE('Race Hispanic/Latinx: ' || rec.race_hispanic_latinx);
DBMS_OUTPUT.PUT_LINE('Race Native American: ' || rec.race_native_american);
DBMS_OUTPUT.PUT_LINE('Race White: ' || rec.race_white);
DBMS_OUTPUT.PUT_LINE('No rows matched the given workforce/year.');
DBMS_OUTPUT.PUT_LINE('Invalid year format. Expected a 4-digit year.');
Exception Handling:
WHEN NO_DATA_FOUND THEN: 'No data found.'
WHEN TOO_MANY_ROWS THEN: 'Multiple rows returned.'
WHEN OTHERS THEN: 'Unexpected error.'

reference_answer:
DECLARE
  -- Inputs (simulate parameters)
  lv_workforce   GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.workforce%TYPE := NULL;
  lv_report_year GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION.report_year%TYPE := '2023';

  co_report_limit CONSTANT PLS_INTEGER := 15; -- Limit output for report readability

  lv_cnt PLS_INTEGER;
  rec GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION%ROWTYPE;
BEGIN
  -- Default workforce to the most common value when not provided
  IF lv_workforce IS NULL THEN
    SELECT workforce
      INTO lv_workforce
      FROM (
        SELECT r.workforce
          FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
         GROUP BY r.workforce
         ORDER BY COUNT(*) DESC, r.workforce
      )
     WHERE ROWNUM = 1;
  END IF;

  -- Validate year is exactly 4 digits
  IF LENGTH(lv_report_year) != 4
     OR REGEXP_LIKE(lv_report_year, '[^0-9]') THEN
    DBMS_OUTPUT.PUT_LINE('Invalid year format. Expected a 4-digit year.');
    RETURN;
  END IF;

  -- Ensure there is at least one matching row before printing
  SELECT COUNT(*)
    INTO lv_cnt
    FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
   WHERE r.workforce = lv_workforce
     AND r.report_year = lv_report_year;

  IF lv_cnt = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No rows matched the given workforce/year.');
    RETURN;
  ELSIF lv_cnt > 1 THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
    RETURN;
  END IF;

  -- Print the representation details (single row)
  SELECT r.*
    INTO rec
    FROM GOOGLE_DEI.DAR_INTERSECTIONAL_REPRESENTATION r
   WHERE r.workforce = lv_workforce
     AND r.report_year = lv_report_year;

  DBMS_OUTPUT.PUT_LINE('Resolved Workforce: ' || lv_workforce);
  DBMS_OUTPUT.PUT_LINE('Report Year: ' || lv_report_year);
  DBMS_OUTPUT.PUT_LINE('Gender (US): ' || rec.gender_us);
  DBMS_OUTPUT.PUT_LINE('Race Asian: ' || rec.race_asian);
  DBMS_OUTPUT.PUT_LINE('Race Black: ' || rec.race_black);
  DBMS_OUTPUT.PUT_LINE('Race Hispanic/Latinx: ' || rec.race_hispanic_latinx);
  DBMS_OUTPUT.PUT_LINE('Race Native American: ' || rec.race_native_american);
  DBMS_OUTPUT.PUT_LINE('Race White: ' || rec.race_white);

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No data found.');
  WHEN TOO_MANY_ROWS THEN
    DBMS_OUTPUT.PUT_LINE('Multiple rows returned.');
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error.');
END;
/

